class CrucibleConsole:
    """Dual-mode console output.

    When CRUCIBLE_MANAGED=1: emits protocol tokens that Crucible intercepts for
    structured logs, errors, prompts, and phase-status updates.
    When running in a real terminal: falls back to ANSI-coloured text.
    """

    _ERROR_LEVELS = frozenset({"ERROR", "WARNING"})

    def __init__(self) -> None:
        self._managed = _CRUCIBLE_MANAGED
        self._lock    = threading.Lock()
        self._error_log_path: "pathlib.Path | None" = None
        self._current_target: str = ""
        self._target_index: int = 0
        self._target_total: int = 0

    def set_error_log(self, path: "pathlib.Path") -> None:
        """Set the on-disk errors.log path for persistent error logging."""
        self._error_log_path = path

    @property
    def managed(self) -> bool:
        return self._managed

    def _persist_error(self, ts: str, level: str, message: str,
                        source: str = "fracture", detail: str = "") -> None:
        """Append an error-level entry to the on-disk errors.log (best-effort)."""
        if self._error_log_path is None:
            return
        try:
            line = f"[{ts}] {level}  SOURCE={source}\n  Message : {message}\n"
            if detail:
                line += f"  Detail  : {detail}\n"
            line += "\n"
            with open(self._error_log_path, "a", encoding="utf-8") as fh:
                fh.write(line)
        except Exception:
            pass

    def log(self, message: str, level: str = "INFO") -> None:
        ts = datetime.now().isoformat()
        with self._lock:
            if self._managed:
                entry = {
                    "ts":      ts,
                    "level":   level,
                    "message": message,
                }
                sys.stdout.write(_CP_LOG + json.dumps(entry) + "\n")
                sys.stdout.flush()
            else:
                _colours = {
                    "INFO":    Fore.CYAN,
                    "SUCCESS": Fore.GREEN,
                    "WARNING": Fore.YELLOW,
                    "ERROR":   Fore.RED,
                    "DEBUG":   Fore.WHITE,
                }
                _tags = {
                    "INFO": "[*]", "SUCCESS": "[+]", "WARNING": "[~]",
                    "ERROR": "[!]", "DEBUG": "[.]",
                }
                c   = _colours.get(level, "")
                tag = _tags.get(level, "[*]")
                _tprint(f"{c}{tag}{Style.RESET_ALL} {message}")
        if level.upper() in self._ERROR_LEVELS:
            self._persist_error(ts, level, message)

    def error(self, message: str, source: str = "fracture",
              detail: str = "", category: str = "") -> None:
        ts = datetime.now().isoformat()
        with self._lock:
            if self._managed:
                entry = {
                    "ts":       ts,
                    "source":   source,
                    "message":  message,
                    "detail":   detail,
                    "category": category or self._categorise(message),
                }
                sys.stderr.write(_CP_ERR + json.dumps(entry) + "\n")
                sys.stderr.flush()
            else:
                _tprint(f"{Fore.RED}[!] {message}{Style.RESET_ALL}")
        self._persist_error(ts, "ERROR", message, source=source, detail=detail)

    def status(self, phase: str, label: str = "", status: str = "running",
               step: str = "", progress: int = 0, total: int = 0,
               tools: "dict | None" = None) -> None:
        _FRACTURE_PHASE[0] = phase   # §14h: current phase for per-request HTTP evidence
        with self._lock:
            if self._managed:
                entry = {
                    "phase":    phase,
                    "label":    label or phase,
                    "status":   status,
                    "step":     step,
                    "progress": progress,
                    "total":    total,
                    "ts":       datetime.now().isoformat(),
                }
                if tools is not None:
                    entry["tools"] = tools
                if self._current_target:
                    entry["target"] = self._current_target
                    entry["target_index"] = self._target_index
                    entry["target_total"] = self._target_total
                sys.stdout.write(_CP_STATUS + json.dumps(entry) + "\n")
                sys.stdout.flush()
        # §14j: persist the phase transition to scan.log + scan.log.json with a
        # timestamp, unconditionally (the status token above is ephemeral / live-UI).
        try:
            with self._log_lock:
                with self.log_file.open("a", encoding="utf-8") as _f:
                    _f.write(f"[{self._ts()}] EVENT phase={phase} status={status}"
                             + (f" step={step}" if step else "") + "\n")
                try:
                    _arr = json.loads(self.json_log_file.read_text(encoding="utf-8") or "[]")
                    if not isinstance(_arr, list):
                        _arr = []
                except Exception:
                    _arr = []
                _arr.append({"timestamp": self._ts(), "level": "EVENT",
                             "phase": phase, "status": status, "step": step})
                self.json_log_file.write_text(json.dumps(_arr, indent=2), encoding="utf-8")
        except Exception:
            pass

    def prompt(self, question: str, prompt_type: str = "text",
               options: list = None, skippable: bool = False,
               role: str = "", username: str = "",
               timeout: "int | None" = None) -> str:
        """Request user input. Blocks until an answer is received.

        role/username are surfaced in Crucible's prompt modal so operators
        responding to an MFA / OTP / consent prompt can immediately see
        which login the prompt belongs to (matters when a project uses
        multiple roles or multi-role engagements).

        timeout (seconds): if set and no input is received within this
        window, return "" automatically.  Prevents blocking when Fracture
        runs unattended (e.g. scheduled Crucible scans).
        """
        if self._managed:
            payload = {
                "id":        str(_uuid.uuid4()),
                "question":  question,
                "type":      prompt_type,
                "options":   options or [],
                "skippable": skippable,
            }
            if role:
                payload["role"] = role
            if username:
                payload["username"] = username
            if timeout:
                payload["timeout"] = timeout
            with self._lock:
                sys.stdout.write(_CP_PROMPT + json.dumps(payload) + "\n")
                sys.stdout.flush()
            try:
                if timeout:
                    import select as _sel
                    ready, _, _ = _sel.select([sys.stdin], [], [], timeout)
                    if not ready:
                        self.log(
                            f"[prompt] No response within {timeout}s — "
                            "auto-skipping (unattended mode)",
                            "WARNING",
                        )
                        return ""
                return sys.stdin.readline().rstrip("\n")
            except Exception:
                return ""
        else:
            if timeout:
                import select as _sel
                _tprint(f"\n  [?] {question}")
                _tprint(f"      (auto-skip in {timeout}s if no input)")
                try:
                    ready, _, _ = _sel.select([sys.stdin], [], [], timeout)
                    if not ready:
                        _tprint(f"  [!] No input after {timeout}s — skipping")
                        return ""
                    return sys.stdin.readline().rstrip("\n").strip()
                except Exception:
                    return ""
            if prompt_type == "password":
                return getpass.getpass(f"  {question}: ")
            elif options:
                _tprint(f"\n[?] {question}")
                for i, opt in enumerate(options, 1):
                    _tprint(f"    [{i}] {opt}")
                raw = input("    Select: ").strip()
                if raw.isdigit():
                    idx = int(raw) - 1
                    if 0 <= idx < len(options):
                        return options[idx]
                return raw
            else:
                return input(f"  [?] {question}: ").strip()

    def action_item(self, entry: dict) -> None:
        with self._lock:
            if self._managed:
                sys.stdout.write(_CR_ACTION + json.dumps(entry) + "\n")
                sys.stdout.flush()

    @staticmethod
    def _categorise(msg: str) -> str:
        m = msg.lower()
        if any(k in m for k in ("connection", "socket", "timeout", "refused", "network", "unreachable")):
            return "Network"
        if any(k in m for k in ("tool", "binary", "not found", "command", "executable")):
            return "Tool"
        return "Scan"


class ProgressManager:
    """Thread-safe checkpoint manager for scan recovery."""

    def __init__(self, checkpoint_file: "str | Path") -> None:
        self._file  = Path(checkpoint_file)
        self._lock  = threading.Lock()
        self._state = self._load()

    def _load(self) -> dict:
        if self._file.exists():
            try:
                data = json.loads(self._file.read_text(encoding="utf-8"))
                data.setdefault("version", 1)
                data.setdefault("started", datetime.now().isoformat())
                data.setdefault("completed_phases", [])
                data.setdefault("phase_status", {})
                return data
            except Exception:
                pass
        return {
            "version":          1,
            "started":          datetime.now().isoformat(),
            "completed_phases": [],
            "phase_status":     {},
        }

    def _save(self) -> None:
        self._file.parent.mkdir(parents=True, exist_ok=True)
        fd, tmp = tempfile.mkstemp(dir=str(self._file.parent), suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(self._state, f, indent=2)
            os.replace(tmp, str(self._file))
        except Exception:
            try:
                os.unlink(tmp)
            except Exception:
                pass

    def is_phase_complete(self, phase: str) -> bool:
        with self._lock:
            return phase in self._state.get("completed_phases", [])

    def set_phase_status(self, phase: str, status: str,
                         label: str = "", detail: str = "") -> None:
        with self._lock:
            self._state.setdefault("phase_status", {})[phase] = {
                "status":     status,
                "label":      label or phase,
                "detail":     detail,
                "updated_at": datetime.now().isoformat(),
            }
            if status == "complete":
                lst = self._state.setdefault("completed_phases", [])
                if phase not in lst:
                    lst.append(phase)
            self._save()

    def get_state(self) -> dict:
        with self._lock:
            return dict(self._state)

    # ── v2 checkpoint: full runtime state ──────────────────────────────────

    def save_scan_state(self, state: dict) -> None:
        """Store full serialisable runtime state alongside phase tracking."""
        with self._lock:
            self._state["scan_state"]    = state
            self._state["version"]       = 2
            self._state["checkpoint_ts"] = datetime.now().isoformat()
            self._save()

    def load_scan_state(self) -> dict:
        """Return stored runtime state, or empty dict if none."""
        with self._lock:
            return self._state.get("scan_state", {})

    def has_resumable_state(self) -> bool:
        """True when this checkpoint carries v2 runtime state."""
        with self._lock:
            return (self._state.get("version", 1) >= 2
                    and bool(self._state.get("scan_state")))

    def prepare_resume(self) -> dict:
        """Reset running/error phases to pending and return full state.

        Called once at the start of a --resume run.  Phases that were
        mid-flight when the previous run was interrupted are demoted to
        'pending' so they re-execute; completed phases remain complete
        and are skipped by _skip().
        """
        with self._lock:
            ps = self._state.get("phase_status", {})
            for k, v in ps.items():
                if v.get("status") in ("running", "error"):
                    v["status"]     = "pending"
                    v["updated_at"] = datetime.now().isoformat()
            self._save()
            return dict(self._state)


# ─────────────────────────────────────────────
# Session serialisation helpers (checkpoint)
# ─────────────────────────────────────────────

def _serialize_session_auth(sess: "requests.Session | None") -> dict:
    """Extract JSON-safe auth artefacts from a requests Session."""
    if sess is None:
        return {}
    cookies = []
    try:
        for c in sess.cookies:
            cookies.append({
                "name":    c.name,
                "value":   c.value,
                "domain":  c.domain,
                "path":    c.path,
                "secure":  c.secure,
                "expires": c.expires,
            })
    except Exception:
        pass
    auth_headers = {}
    for h in ("Authorization", "X-Auth-Token", "X-API-Key",
              "Cookie", "X-XSRF-TOKEN", "X-CSRF-Token"):
        v = sess.headers.get(h)
        if v:
            auth_headers[h] = v
    return {"cookies": cookies, "auth_headers": auth_headers}


def _restore_session_auth(sess: "requests.Session", state: dict) -> None:
    """Inject previously-serialised cookies and auth headers into *sess*."""
    for c in state.get("cookies", []):
        try:
            sess.cookies.set(
                c["name"], c["value"],
                domain=c.get("domain", ""),
                path=c.get("path", "/"),
            )
        except Exception:
            pass
    for h, v in state.get("auth_headers", {}).items():
        sess.headers[h] = v


# ─────────────────────────────────────────────
# Subprocess helpers
# ─────────────────────────────────────────────
_POPEN_FLAGS: dict = {}
if platform.system() == "Windows":
    _POPEN_FLAGS["creationflags"] = subprocess.CREATE_NO_WINDOW  # type: ignore


def _run(cmd: list, **kwargs) -> subprocess.CompletedProcess:
    """Run a subprocess with memory limits, suppressing console windows on Windows."""
    if "preexec_fn" not in kwargs and sys.platform != "win32":
        _bin = Path(cmd[0]).name if cmd else ""
        if _bin in _GO_BINARIES:
            kwargs["preexec_fn"] = _go_mem_limit_preexec
            _env = kwargs.get("env")
            if _env is None:
                _env = os.environ.copy()
            _env.setdefault("GOMEMLIMIT", "2GiB")
            kwargs["env"] = _env
        else:
            kwargs["preexec_fn"] = _mem_limit_preexec
    return subprocess.run(cmd, **{**_POPEN_FLAGS, **kwargs})


def _popen(cmd: list, **kwargs) -> subprocess.Popen:
    """Open a subprocess with memory limits, suppressing console windows on Windows."""
    if "preexec_fn" not in kwargs and sys.platform != "win32":
        _bin = Path(cmd[0]).name if cmd else ""
        if _bin in _GO_BINARIES:
            kwargs["preexec_fn"] = _go_mem_limit_preexec
            _env = kwargs.get("env")
            if _env is None:
                _env = os.environ.copy()
            _env.setdefault("GOMEMLIMIT", "2GiB")
            kwargs["env"] = _env
        else:
            kwargs["preexec_fn"] = _mem_limit_preexec
    proc = subprocess.Popen(cmd, **{**_POPEN_FLAGS, **kwargs})
    _track_proc(proc)
    return proc


# ─────────────────────────────────────────────
# OutputManager
# ─────────────────────────────────────────────
_RE_UNSAFE_FNAME = re.compile(r'[^\w.\-]')


class OutputManager:
    """Manages the output directory tree for a Fracture scan."""

    TOOL_DIRS = [
        "recon", "tls", "headers", "crawl", "injection",
        "traversal", "ssrf", "auth_bypass", "files", "vulnscan", "zap",
        "graphql", "auth_recon", "authorization", "session", "csrf", "cross_user",
        "logout",
    ]

    FINDINGS_CSV_FIELDS = [
        "title", "datetime", "ip", "port", "hostname", "risk", "command",
        "description", "output", "cves", "sources", "service", "output_file",
        "affected", "exploitdb", "metasploit", "exploit_details",
        "owasp", "owasp_url", "nist", "remediation",
    ]

    _findings_lock: threading.Lock = threading.Lock()
    _log_lock:      threading.Lock = threading.Lock()

    def __init__(self, project_name: str) -> None:
        self.project_name     = project_name
        self.root             = Path(project_name).resolve()
        self.log_file         = self.root / "scan.log"
        self.json_log_file    = self.root / "scan.log.json"
        self.error_log        = self.root / "errors.log"
        self.findings_json    = self.root / "findings.json"
        self.findings_csv     = self.root / "findings.csv"
        self.summary_json     = self.root / "summary.json"
        self._current_accounts: list = []
        # Set by the scan loop after instantiation; used to relativize affected URLs
        self.base_url: str = ""
        # When set to a role label (e.g. "Admin", "unauthenticated"), output_path() and
        # _save_http_evidence() route tool outputs into a per-role subdirectory so that
        # files from different roles do not overwrite each other.
        self._output_role: str = ""
        # "Information Disclosure:" header findings are server-level — only the first
        # occurrence per title+hostname is recorded.  Subsequent calls for the
        # same header on different paths are silently dropped.
        self._hdr_disclosure_seen: set = set()
        # SPA dedup: baseline response body sizes from Phase 0b
        # (login, root, error pages).  endpoint_tools compares
        # against these to skip duplicate SPA-shell screenshots.
        self._spa_baseline_sizes: set = set()
        # ── Action items (Siphon recommendations) ─────────────────────────
        self._action_items_lock = threading.Lock()
        self.action_items_json  = self.root / "action_items.json"
        self._ai_seen: set      = set()
        self._setup_dirs()
        vc.set_error_log(self.error_log)

    def _setup_dirs(self) -> None:
        self.root.mkdir(parents=True, exist_ok=True)
        for d in self.TOOL_DIRS:
            (self.root / d).mkdir(exist_ok=True)
        if not self.log_file.exists():
            self._write_log_header()
        if not self.json_log_file.exists():
            self.json_log_file.write_text("[]\n", encoding="utf-8")
        if not self.error_log.exists():
            self._write_error_header()
        if not self.findings_json.exists():
            self.findings_json.write_text("[]\n", encoding="utf-8")
        if not self.findings_csv.exists():
            self._write_findings_csv_header()
        if not self.action_items_json.exists():
            self.action_items_json.write_text("[]\n", encoding="utf-8")

    _SPA_SIZE_TOLERANCE = 200  # bytes — accounts for CSRF tokens / nonces

    def record_spa_baseline(self, body_len: int) -> None:
        if body_len and body_len > 0:
            self._spa_baseline_sizes.add(body_len)

    def is_spa_duplicate(self, body_len: int) -> bool:
        if not self._spa_baseline_sizes or not body_len or body_len <= 0:
            return False
        for bl in self._spa_baseline_sizes:
            if abs(body_len - bl) <= self._SPA_SIZE_TOLERANCE:
                return True
        return False

    def _write_log_header(self) -> None:
        header = (
            f"{'='*70}\n"
            f"  fracture.py — Scan Log\n"
            f"  Project : {self.project_name}\n"
            f"  Created : {self._ts()}\n"
            f"  Host    : {platform.node()}  OS: {platform.system()} {platform.release()}\n"
            f"{'='*70}\n\n"
        )
        self.log_file.write_text(header, encoding="utf-8")
        # §14k: record the tool's own version as a startup EVENT in the audit log
        # (external tool versions are recorded per-invocation in their .log headers).
        try:
            with self._log_lock:
                with self.log_file.open("a", encoding="utf-8") as _f:
                    _f.write(f"[{self._ts()}] EVENT fracture v{VERSION} started\n")
                try:
                    _arr = json.loads(self.json_log_file.read_text(encoding="utf-8") or "[]")
                    if not isinstance(_arr, list):
                        _arr = []
                except Exception:
                    _arr = []
                _arr.append({"timestamp": self._ts(), "level": "EVENT",
                             "message": f"fracture v{VERSION} started"})
                self.json_log_file.write_text(json.dumps(_arr, indent=2), encoding="utf-8")
        except Exception:
            pass

    def _write_error_header(self) -> None:
        header = (
            f"{'='*70}\n"
            f"  fracture.py — Error Log\n"
            f"  Project : {self.project_name}\n"
            f"  Created : {self._ts()}\n"
            f"{'='*70}\n\n"
        )
        self.error_log.write_text(header, encoding="utf-8")

    def _write_findings_csv_header(self) -> None:
        with self.findings_csv.open("w", newline="", encoding="utf-8") as f:
            writer = csv.DictWriter(f, fieldnames=self.FINDINGS_CSV_FIELDS, extrasaction="ignore")
            writer.writeheader()

    def log_action_item(self, *, type: str, recommended_tool: str,
                        target: str, ip: str, port: int, hostname: str,
                        title: str, description: str, source_finding: str,
                        priority: str, scope: str,
                        metadata: "dict | None" = None) -> None:
        key = (recommended_tool.lower(), target.lower(), title.strip().lower())
        with self._action_items_lock:
            if key in self._ai_seen:
                return
            self._ai_seen.add(key)
            entry = {
                "id":              str(_uuid.uuid4()),
                "type":            type,
                "recommended_tool": recommended_tool,
                "target":          target,
                "ip":              _sanitize_ip(ip),
                "port":            port,
                "hostname":        hostname,
                "title":           title,
                "description":     description,
                "source_finding":  source_finding,
                "priority":        priority,
                "scope":           scope,
                "status":          "pending",
                "datetime":        datetime.now().isoformat(),
                "metadata":        metadata or {},
            }
            try:
                items = json.loads(
                    self.action_items_json.read_text(encoding="utf-8") or "[]")
            except Exception:
                items = []
            items.append(entry)
            tmp = self.action_items_json.with_suffix(".tmp")
            tmp.write_text(json.dumps(items, indent=2), encoding="utf-8")
            os.replace(str(tmp), str(self.action_items_json))
        vc.action_item(entry)

    def _ts(self) -> str:
        return datetime.now().strftime("%Y-%m-%d %H:%M:%S")

    def _safe_filename(self, parts: list, ext: str) -> str:
        name = "_".join(str(p) for p in parts)
        name = _RE_UNSAFE_FNAME.sub("_", name)
        return f"{name}.{ext}"

    def output_path(self, phase: str, *parts) -> Path:
        fname = self._safe_filename(list(parts), "txt")
        if self._output_role:
            role_safe = _RE_UNSAFE_FNAME.sub("_", self._output_role)
            p = self.root / phase / role_safe / fname
            p.parent.mkdir(parents=True, exist_ok=True)
            return p
        p = self.root / phase / fname
        # Ensure the phase dir exists for the role-less path too. Without
        # this, the first caller in a phase would silently fail to write
        # when the dir didn't pre-exist (caught by their try/except blocks,
        # leaving findings with no Evidence file).
        p.parent.mkdir(parents=True, exist_ok=True)
        return p

    def log_command(self, tool: str, command: "list | str", output_file: "Path | None",
                    extra: "dict | None" = None,
                    *,
                    tool_path: "str | None" = None,
                    stdout: "str | None" = None,
                    stderr: "str | None" = None,
                    started: "datetime | None" = None,
                    ended:   "datetime | None" = None,
                    exit_code: "int | None" = None) -> None:
        """Append a structured invocation line to scan.log.

        When the caller passes *stdout*/*stderr*/*started*/*ended*/*exit_code*
        (and optionally *tool_path*), additionally emit a sibling .log file
        next to *output_file* containing a bash-prompted transcript with
        timing and version metadata — per CLAUDE.md Section 15.
        Legacy callers that don't pass capture data continue to work; their
        .log file is simply not written.
        """
        ts      = self._ts()
        cmd_str = " ".join(command) if isinstance(command, list) else command
        out_str = str(output_file.relative_to(self.root)) if output_file else "n/a"
        lines   = [f"[{ts}] TOOL={tool}", f"  Command     : {cmd_str}", f"  Output file : {out_str}", ""]
        if extra:
            for k, v in extra.items():
                if v is not None:
                    lines.insert(2, f"  {k:<13} : {v}")
        with self._log_lock:
            with self.log_file.open("a", encoding="utf-8") as f:
                f.write("\n".join(lines) + "\n")

        # ── Per-invocation .log (bash-prompted transcript) ─────────────────
        # §14: ALWAYS emit a .log sibling for every tool invocation (even when
        # the caller didn't capture stdout/stderr — the transcript then records
        # the command, timing and output-file reference). Callers that DO pass
        # capture data get the full stdout/stderr transcript.
        if True:
            try:
                import sys as _s
                if "/opt/pr0t31n/shared" not in _s.path:
                    _s.path.insert(0, "/opt/pr0t31n/shared")
                import pr0t31n_tool_runner as _ur
                from datetime import datetime as _dt
                _st = started or _dt.now().astimezone()
                _ed = ended   or _dt.now().astimezone()
                _ur.write_tool_log(
                    cmd=command, started=_st, ended=_ed,
                    exit_code=exit_code,
                    stdout=stdout or "", stderr=stderr or "",
                    tool_name=tool, tool_path=tool_path or tool,
                    output_file=output_file,
                    log_dir=self.root if not output_file else None,
                    extra_header=extra,
                    errors_log=self.error_log,
                )
            except Exception:
                pass

    def log_error(self, tool: str, command: "list | str", error: str) -> None:
        ts      = self._ts()
        cmd_str = " ".join(command) if isinstance(command, list) else command
        with self._log_lock:
            with self.error_log.open("a", encoding="utf-8") as f:
                f.write(f"[{ts}] ERROR  TOOL={tool}\n  Command : {cmd_str}\n  Error   : {error}\n\n")

    def set_auth_context(self, accounts: list) -> None:
        """Set the active auth context for subsequent add_finding calls."""
        self._current_accounts = list(accounts)

    def _rel_affected(self, raw: str) -> str:
        """Convert each line of `raw` that is a same-origin full URL to a
        host-prefixed relative path, using self.base_url as the origin anchor.
        Lines that are not HTTP URLs (paths, names, cipher strings, etc.)
        are returned unchanged.  Falls back to `raw` if base_url is unset.
        Paths containing unencoded quote characters or other junk are filtered out.
        Deduplicates entries that refer to the same host (e.g. host, host:443,
        https://host all collapse to hostname/path)."""
        _PATH_JUNK = frozenset('"\'<> \t\r\n\x00')
        if not self.base_url or not raw:
            return raw
        try:
            _base_p = urllib.parse.urlparse(self.base_url)
            _base_host = _base_p.hostname or ""
            _base_port = _base_p.port
            _base_scheme = _base_p.scheme or "https"
        except Exception:
            _base_host = ""
            _base_port = None
            _base_scheme = "https"
        _default_port = 443 if _base_scheme == "https" else 80
        lines = raw.split("\n")
        result = []
        seen = set()
        for line in lines:
            stripped = line.strip()
            if not stripped:
                continue
            if stripped.startswith("http"):
                rel = _url_rel_path(stripped, self.base_url)
            else:
                rel = stripped
            if rel.startswith("/") and any(c in rel for c in _PATH_JUNK):
                continue
            if rel.startswith("/") and _base_host:
                rel = _base_host + rel
            _norm = rel.lower().rstrip("/") or rel.lower()
            if _base_host:
                _bhl = _base_host.lower()
                if _norm == _bhl or _norm == f"{_bhl}:{_default_port}":
                    rel = f"{_base_host}/"
                    _norm = rel.lower().rstrip("/")
            if _norm in seen:
                continue
            seen.add(_norm)
            result.append(rel)
        return "\n".join(result)

    @staticmethod
    def _collapse_header_affected(entries: set) -> set:
        """For host-level header findings, collapse subpath entries to
        parent origin.  'columbushosp.org/bin/' → 'columbushosp.org/'.
        Entries that are already parent-level or not URL-shaped pass through.
        IPs without a path component are normalised to IP:PORT."""
        result: set = set()
        for entry in entries:
            e = entry.strip()
            if not e:
                continue
            if "/" in e:
                host_part = e.split("/", 1)[0]
                result.add(host_part + "/")
            else:
                result.add(e)
        return result

    def _dedup_affected(self, entries: set) -> set:
        """Deduplicate affected location entries that refer to the same host.
        Collapses bare host, host:default_port, and host/ into one entry.
        Entries that are not host/URL-shaped (tech names, cipher strings) pass through."""
        try:
            _base_p = urllib.parse.urlparse(self.base_url)
            _base_scheme = _base_p.scheme or "https"
        except Exception:
            _base_scheme = "https"
        _default_port = 443 if _base_scheme == "https" else 80
        seen_norm = {}
        result = set()
        for entry in entries:
            e = entry.strip()
            if not e:
                continue
            _el = e.lower().rstrip("/") or e.lower()
            if ":" in _el and not _el.startswith("http"):
                _parts = _el.rsplit(":", 1)
                try:
                    _p = int(_parts[1])
                    if _p == _default_port:
                        _el = _parts[0]
                except (ValueError, IndexError):
                    pass
            if _el not in seen_norm:
                seen_norm[_el] = e
                result.add(e)
            else:
                _existing = seen_norm[_el]
                if len(e) > len(_existing):
                    result.discard(_existing)
                    result.add(e)
                    seen_norm[_el] = e
        return result

    @staticmethod
    def _auto_highlights(
        title: str, output: str, cves: str, affected: str,
    ) -> list:
        """Derive highlight terms from finding data when none are explicit.

        Returns a list of 1-10 strings suitable for searching in evidence
        files.  The terms should be precise enough to avoid false matches
        (e.g. ``Server: Microsoft-IIS/10.0`` rather than ``Server``).
        """
        hl: list = []
        t = title or ""

        # ── Header findings — use full "Name: Value" lines from output ──
        if re.match(
            r"^(Information Disclosure|Software Version Detected|Software Version Disclosed"
            r"|Unknown Header Identified"
            r"|Inconsistent Security Header Usage"
            r"|Endpoint-Specific Header"
            r"|Technology Identified|Software Identified|Software Version Detected|Vulnerable Component):",
            t,
        ):
            for ln in (output or "").split("\n"):
                ln = ln.strip()
                if not ln or re.match(
                    r"^(HTTP Status:|Matched at:|Plugin:|Missing:)", ln, re.I
                ):
                    continue
                if 5 <= len(ln) <= 120:
                    hl.append(ln)
            if hl:
                return hl[:8]

        # ── Missing / permissive security headers ──
        if t.startswith("Missing Security Header:"):
            _hdr = t.split(":", 1)[1].strip()
            if _hdr:
                hl.append(_hdr)
                return hl
        if t.startswith("Permissive Security Header:"):
            for ln in (output or "").split("\n"):
                ln = ln.strip()
                if ln and ":" in ln and len(ln) >= 8:
                    hl.append(ln[:120])
                    break
            if hl:
                return hl

        # ── Cookie findings — cookie name from output ──
        if re.search(r"Cookie|Session", t, re.I):
            _ck_m = re.findall(
                r"(?:Cookies?\s+without\s+\w+:\s*|Cookie:\s*|"
                r"Set-Cookie:\s*)(\S+)",
                output or "", re.I,
            )
            if _ck_m:
                hl.extend(_ck_m[:3])
                return hl

        # ── Injection / XSS — use the payload from output ──
        if re.search(
            r"injection|xss|sqli|ssrf|rce|xxe|ssti|crlf|traversal|"
            r"deserialization|smuggling|open.redirect",
            t, re.I,
        ):
            for ln in (output or "").split("\n"):
                ln = ln.strip()
                _pm = re.match(
                    r"^(?:Payload|Parameter|Field|Vector|Matched):\s*(.+)",
                    ln, re.I,
                )
                if _pm and len(_pm.group(1)) >= 3:
                    hl.append(_pm.group(1).strip()[:100])
            if hl:
                return hl[:5]

        # ── SSL/TLS — cipher names + CVEs ──
        if re.match(r"^(SSL/TLS|CBC Mode|Non-Standard Cipher|Deprecated)", t):
            for ln in (output or "").split("\n"):
                ln = ln.strip()
                if ln and len(ln) >= 4 and not ln.startswith("Matched"):
                    hl.append(ln)
            if cves:
                hl.extend(
                    c.strip() for c in cves.split(",") if c.strip()
                )
            if hl:
                return hl[:10]

        # ── WAF / LB / CDN — platform name ──
        if re.match(r"^(WAF|Load Balancer|CDN)", t):
            for ln in (output or "").split("\n"):
                ln = ln.strip()
                if ln and ":" in ln and len(ln) >= 5:
                    hl.append(ln[:120])
            if hl:
                return hl[:5]

        # ── Telerik / ViewState / specific tech ──
        if "Telerik" in t:
            hl.extend([
                "Telerik.Web.UI", "DialogHandler",
                "WebResource.axd", "ScriptResource.axd",
            ])
            return hl
        if "ViewState" in t:
            hl.extend([
                "__VIEWSTATE", "ViewState",
                "EnableViewStateMac",
            ])
            return hl

        # ── CVEs as last resort ──
        if cves:
            hl.extend(c.strip() for c in cves.split(",") if c.strip())
            return hl[:5]

        # ── Title suffix after ":" as minimal fallback ──
        if ":" in t:
            _suffix = t.split(":")[-1].strip()
            if 4 <= len(_suffix) <= 80:
                hl.append(_suffix)
                return hl

        return hl

    def add_finding(
        self,
        title: str,
        url: str,
        port: int,
        risk: str,
        description: str,
        output: str = "",
        cves: str = "",
        sources: str = "",
        service: str = "",
        output_file: str = "",
        affected: str = "",
        owasp: str = "",
        nist: str = "",
        remediation: str = "",
        command: str = "",
        http_code: int = 0,
        highlights: "list | None" = None,
        **extra_v11,
    ) -> None:
        """Record a security finding to findings.json and findings.csv. Thread-safe.

        Any extra keyword arguments are merged into the finding dict as v1.1
        enrichment fields (cvss_score, cvss_vector, cwe, mitre_attack, etc.).
        """
        ts    = self._ts()
        title = _normalize_finding_title(title)

        # Server-level findings are emitted once per title+hostname across the
        # entire scan regardless of which path or phase triggers them.
        # Software version headers (Server, X-Powered-By, X-AspNet-Version) are
        # identical on every response from the same host — recording one per
        # endpoint floods the report with duplicates.
        if (title.startswith("Information Disclosure:")
                or title.startswith("Software Version Detected:")
                or title.startswith("Software Version Disclosed:")):
            try:
                _hdr_host = urllib.parse.urlparse(url).hostname or url
            except Exception:
                _hdr_host = url
            _hdr_key = f"{title}\x00{_hdr_host}"
            with self._findings_lock:
                if _hdr_key in self._hdr_disclosure_seen:
                    return
                self._hdr_disclosure_seen.add(_hdr_key)
            # Normalise URL/affected to server root — the header applies to
            # the entire host, not one endpoint.
            try:
                _p = urllib.parse.urlparse(url)
                url = f"{_p.scheme}://{_p.netloc}/"
            except Exception:
                pass
            if not affected:
                affected = "/"

        ascii_title = title.encode("ascii", errors="replace").decode("ascii")

        # parse hostname from url
        try:
            _parsed  = urllib.parse.urlparse(url)
            hostname = _parsed.hostname or url
            _svc     = service or _parsed.scheme or "http"
        except Exception:
            hostname = url
            _svc     = service or "http"

        _owasp_name, _owasp_url = _owasp_resolve(owasp, title)
        entry = {
            "title":          title,
            "datetime":       ts,
            "ip":             _sanitize_ip(hostname),
            "port":           int(port) if port else 0,
            "hostname":       hostname,
            "risk":           risk or "",
            "command":        command or "",
            "description":    description or "",
            "output":         output or "",
            "cves":           cves or "",
            "sources":        sources or "",
            "service":        _svc,
            "output_file":    output_file or "",
            "affected":       self._rel_affected(affected or url),
            "exploitdb":      False,
            "metasploit":     False,
            "exploit_details": [],
            "owasp":          _owasp_name or owasp or "",
            "owasp_url":      _owasp_url or "",
            "nist":           nist or "",
            "remediation":    remediation or "",
            "accounts":       list(self._current_accounts),
            "roles":          ", ".join(sorted(set(
                                  a.get("role", "") for a in self._current_accounts
                                  if a.get("role", "")))),
            "http_code":      int(http_code) if http_code else 0,
            "highlights":     highlights or self._auto_highlights(
                                  title, output, cves, affected),
        }
        # Merge v1.1 enrichment fields (cvss_score, cvss_vector, cwe, etc.)
        if extra_v11:
            entry.update(extra_v11)
        _tl = title.strip().lower()
        if (_tl.startswith("missing security header:")
                or _tl.startswith("deprecated protocol enabled:")
                or _tl.startswith("ssl/tls ")):
            _init_aff = set(a.strip() for a in entry["affected"].split("\n") if a.strip())
            _init_aff = self._collapse_header_affected(_init_aff)
            entry["affected"] = "\n".join(sorted(_init_aff)) if _init_aff else entry["affected"]
        csv_entry = dict(entry)
        csv_entry["title"] = ascii_title

        with self._findings_lock:
            try:
                existing_all: list = json.loads(self.findings_json.read_text(encoding="utf-8"))
                if not isinstance(existing_all, list):
                    existing_all = []
            except Exception:
                existing_all = []

            _title_lower = title.strip().lower()
            # Findings that should merge globally by (title, port) only — the
            # incoming URL is always folded into the affected list on merge.
            _GLOBAL_MERGE_PREFIXES = (
                "missing security header:",
                "interesting endpoint discovered",
                # auth_recon emits one "Authenticated Interesting Endpoint"
                # finding per discovered link; without global merge each
                # one became a separate finding (same title, different
                # URL/port) and the operator saw N entries in the Findings
                # tab instead of one entry whose affected list enumerates
                # every endpoint.
                "authenticated interesting endpoint",
                "api endpoint identified",
                "non-login form detected",
                "login page identified",
                "missing secure cookie attribute:",
                "misconfigured secure cookie attribute:",
                "broken function level authorization (bfla)",
                # BOLA/IDOR validator emits one finding per vulnerable
                # endpoint+role pair; same global-merge rationale as BFLA
                # so the Findings tab shows a single entry whose affected
                # list enumerates every confirmed endpoint.
                "broken object level authorization (idor / bola)",
                "web files downloaded",
                "web screenshot captured",
                # Nikto/nuclei normalised titles that overlap with Fracture
                # native findings — merge globally so the same header/cookie/
                # method finding from shcheck + nikto + nuclei produces one
                # entry with combined affected paths + merged sources.
                "session cookie missing",
                "directory listing enabled",
                "http trace method enabled",
                "http methods",
                "information disclosure: sensitive path in robots.txt",
                "verbose error messages",
                "cors misconfiguration",
                "cross-site request forgery (csrf)",
                "admin panel exposed",
                "sensitive file exposed",
                "sensitive path accessible:",
                "deprecated protocol enabled:",
                "telerik ui",
                "cryptographic padding oracle",
                "ssl/tls certificate:",
                "ssl/tls ciphers:",
                "ssl/tls forward secrecy:",
                "ssl/tls vulnerability:",
                "ssl/tls vulnerability (potential):",
                "ssl/tls: tlsv1.3",
                "information disclosure:",
                "waf / edge security platform active:",
                "technology identified:",
                "permissive security header:",
                "server misconfiguration:",
                "load balancer detected:",
                "password reset endpoint exposed",
                "http method tampering:",
                "non-standard cipher suites accepted",
                "missing rate limiting",
                "web misconfiguration: iis tilde shortname vulnerability",
                "enumeration: iis tilde directory enumeration",
                "dns information: missing caa record",
                "outdated copyright notice detected",
                "exposed cryptocurrency wallet address",
                "unauthenticated access to protected path",
                "asp.net viewstate",
                "viewstate contains",
                "sensitive file exposed:",
                "asp.net trace handler",
                "asp.net error log",
                "asp.net handler endpoints",
                "asp.net app_data",
                "asp.net client scripts",
                "frontpage",
                "f5 big-ip:",
                "f5 big-ip cookie",
                "backend server configuration",
                "spa routes extracted",
                "http method accepted but not functional:",
                # Additional SSL/TLS merge: testssl/sslscan emit per-check
                # titles (OCSP, BREACH, LUCKY13, etc.) that are always
                # host-level and must not duplicate across probed paths.
                "ssl/tls obsolete",
                "ssl/tls signature",
                "ssl/tls ocsp",
                "ssl/tls breach",
                "ssl/tls lucky13",
                "ssl/tls sweet32",
                "ssl/tls dns:",
                "ssl/tls cert_",
                "ssl/tls cookie_",
                "ssl/tls certificate information",
                "ssl/tls non-standard",
                "ssl/tls session",
                # Host-level findings from various phases
                "single page application",
                "unknown header:",
                "missing secure cookie:",
                "timing attack on login",
            )
            _is_global = any(_title_lower.startswith(_p) for _p in _GLOBAL_MERGE_PREFIXES)
            _norm_key  = (_title_lower, "" if _is_global else url.strip(),
                          int(port) if port else 0)
            merged     = False

            for ex in existing_all:
                _ex_tl = (ex.get("title") or "").strip().lower()
                _ex_is_global = any(_ex_tl.startswith(_p) for _p in _GLOBAL_MERGE_PREFIXES)
                ex_key = (
                    _ex_tl,
                    "" if _ex_is_global else (ex.get("ip") or "").strip(),
                    int(ex.get("port") or 0),
                )
                if ex_key == _norm_key:
                    # merge sources
                    if sources:
                        ex_srcs = set(s.strip() for s in (ex.get("sources") or "").split(",") if s.strip())
                        new_srcs = set(s.strip() for s in sources.split(",") if s.strip())
                        ex["sources"] = ",".join(sorted(ex_srcs | new_srcs))
                    # merge CVEs
                    if cves:
                        ex_cves = set(c.strip() for c in (ex.get("cves") or "").split(",") if c.strip())
                        new_cves = set(c.strip() for c in cves.split(",") if c.strip())
                        ex["cves"] = ",".join(sorted(ex_cves | new_cves))
                    # merge affected — for global-merge titles always include the
                    # incoming url so every affected URL is captured even when the
                    # caller passes affected="" (e.g. header findings from other phases)
                    _ex_aff = set(a.strip() for a in (ex.get("affected") or "").split("\n") if a.strip())
                    if _is_global:
                        _ex_aff.add(self._rel_affected(url.strip()))
                    if affected:
                        _ex_aff |= set(
                            self._rel_affected(a.strip())
                            for a in affected.split("\n") if a.strip()
                        )
                    _ex_aff.discard("")
                    if _ex_aff:
                        _ex_aff = self._dedup_affected(_ex_aff)
                        if (_title_lower.startswith("missing security header:")
                                or _title_lower.startswith("deprecated protocol enabled:")
                                or _title_lower.startswith("ssl/tls ")):
                            _ex_aff = self._collapse_header_affected(_ex_aff)
                        ex["affected"] = "\n".join(sorted(_ex_aff))
                    # ── merge output_file — preserve BOTH formats ──────────
                    # output_file can be in two formats:
                    #   - JSON array of HTTP-exchange dicts:
                    #         [{"url": "...", "req": "...", "resp": "..."}, …]
                    #   - Plain path(s), newline- or comma-separated.
                    # The previous merge logic silently dropped plain paths
                    # when crossed with a JSON-array side (and vice-versa).
                    # The visible symptom: WhatWeb's output file disappeared
                    # from the Evidence column and Crucible showed an empty
                    # array "[]". Fix: convert plain paths to synthetic
                    # entries {"file": "<path>"} so they round-trip through
                    # the JSON-array form when needed; consumers (Crucible)
                    # render entries with a "file" key as plain file links
                    # and entries with "req"/"resp" keys as HTTP exchanges.
                    if output_file:
                        _ex_of  = (ex.get("output_file") or "").strip()
                        _in_of  = output_file.strip()
                        _ex_json = _ex_of.startswith("[")
                        _in_json = _in_of.startswith("[")

                        def _to_entries(_s: str, _is_json: bool) -> "list":
                            if not _s:
                                return []
                            if _is_json:
                                try:
                                    _e = json.loads(_s)
                                    return _e if isinstance(_e, list) else []
                                except Exception:
                                    return []
                            return [
                                {"file": _p.strip()}
                                for _p in re.split(r"[,\n]", _s) if _p.strip()
                            ]

                        if _ex_json or _in_json:
                            _ex_ents = _to_entries(_ex_of, _ex_json)
                            _in_ents = _to_entries(_in_of, _in_json)
                            def _entry_key(_e: dict) -> tuple:
                                return (_e.get("url", ""), _e.get("file", ""),
                                        _e.get("req", ""), _e.get("resp", ""))
                            _seen_ev = {_entry_key(_e) for _e in _ex_ents}
                            for _e in _in_ents:
                                _k = _entry_key(_e)
                                if _k not in _seen_ev and any(_k):
                                    _ex_ents.append(_e)
                                    _seen_ev.add(_k)
                            ex["output_file"] = (
                                json.dumps(_ex_ents) if _ex_ents else _ex_of
                            )
                        else:
                            ex_files = set(
                                f.strip()
                                for f in re.split(r"[,\n]", _ex_of)
                                if f.strip()
                            )
                            for _p in re.split(r"[,\n]", _in_of):
                                _p = _p.strip()
                                if _p:
                                    ex_files.add(_p)
                            ex["output_file"] = ",".join(sorted(ex_files))
                    # merge description — findings with HTTP-status context
                    # replace stale entries rather than appending, so the most
                    # recent scan's response code appears prominently in Crucible.
                    if description:
                        ex_desc  = (ex.get("description") or "").strip()
                        new_desc = description.strip()
                        if new_desc:
                            if "[HTTP " in new_desc and "[HTTP " not in ex_desc:
                                ex["description"] = new_desc
                                if output:
                                    ex["output"] = output
                            elif new_desc not in ex_desc:
                                ex["description"] = f"{ex_desc}\n\n{new_desc}".strip() if ex_desc else new_desc
                    # merge accounts — dedup by role so the same role is never added twice
                    if self._current_accounts:
                        _ex_accts = ex.get("accounts") or []
                        _ex_roles = {a.get("role", "") for a in _ex_accts}
                        for _a in self._current_accounts:
                            if _a.get("role", "") not in _ex_roles:
                                _ex_accts.append(_a)
                                _ex_roles.add(_a.get("role", ""))
                        ex["accounts"] = _ex_accts
                    # merge roles — union existing and incoming
                    _in_roles = entry.get("roles", "")
                    if _in_roles:
                        _ex_r_set = set(r.strip() for r in (ex.get("roles") or "").split(",") if r.strip())
                        _ex_r_set |= set(r.strip() for r in _in_roles.split(",") if r.strip())
                        ex["roles"] = ", ".join(sorted(_ex_r_set))
                    # merge highlights — combine without duplication
                    if highlights:
                        _ex_hl = ex.get("highlights") or []
                        _ex_hl_set = {h.lower() for h in _ex_hl}
                        for _h in highlights:
                            if _h.lower() not in _ex_hl_set:
                                _ex_hl.append(_h)
                                _ex_hl_set.add(_h.lower())
                        ex["highlights"] = _ex_hl
                    # escalate risk
                    _risk_rank = {"CRITICAL": 4, "HIGH": 3, "MEDIUM": 2, "LOW": 1, "INFO": 0}
                    if _risk_rank.get((risk or "").upper(), 0) > _risk_rank.get((ex.get("risk") or "").upper(), 0):
                        ex["risk"] = risk
                    # update http_code — always prefer the latest non-zero value
                    if http_code:
                        ex["http_code"] = int(http_code)
                    merged = True
                    break

            if not merged:
                existing_all.append(entry)

            # atomic write JSON
            tmp = self.findings_json.with_suffix(".tmp")
            tmp.write_text(json.dumps(existing_all, indent=2), encoding="utf-8")
            tmp.replace(self.findings_json)

            # append CSV only for new entries
            if not merged:
                with self.findings_csv.open("a", newline="", encoding="utf-8") as f:
                    writer = csv.DictWriter(f, fieldnames=self.FINDINGS_CSV_FIELDS, extrasaction="ignore")
                    writer.writerow(csv_entry)

    def write_summary(self, meta: dict) -> None:
        """Write scan summary JSON."""
        try:
            findings = json.loads(self.findings_json.read_text(encoding="utf-8"))
        except Exception:
            findings = []
        counts = {"CRITICAL": 0, "HIGH": 0, "MEDIUM": 0, "LOW": 0, "INFO": 0}
        for f in findings:
            r = (f.get("risk") or "INFO").upper()
            counts[r] = counts.get(r, 0) + 1
        summary = {
            "tool":        "fracture",
            "version":     VERSION,
            "generated":   datetime.now().isoformat(),
            "hostname":    socket.gethostname(),
            "total_findings": len(findings),
            "risk_counts": counts,
            **meta,
        }
        tmp = self.summary_json.with_suffix(".tmp")
        tmp.write_text(json.dumps(summary, indent=2), encoding="utf-8")
        tmp.replace(self.summary_json)


