# ── Soft-404 / custom error page fingerprint library ──────────────────────────
_SOFT_404_FINGERPRINTS = [
    # ── ASP.NET / IIS ──
    re.compile(r'<title>\s*Error\s*Page\s*</title>', re.I),
    re.compile(r'<title>\s*Page\s*Not\s*Found\s*</title>', re.I),
    re.compile(r'<title>\s*404\s*[-—]?\s*(?:File|Page)?\s*Not\s*Found\s*</title>', re.I),
    re.compile(r'Runtime\s+Error.*Server\s+Error\s+in', re.I),
    re.compile(r'class=["\']error-?page["\']', re.I),
    re.compile(r'The\s+resource\s+(?:cannot|could\s+not)\s+be\s+found', re.I),
    re.compile(r'<h2>\s*\d+\s*[-—]\s*(?:File|Page)\s+Not\s+Found\s*</h2>', re.I),
    re.compile(r'ErrorPage\.aspx', re.I),
    re.compile(r'CustomErrors\s+mode=', re.I),

    # ── Spring Boot / Java ──
    re.compile(r'Whitelabel\s+Error\s+Page', re.I),
    re.compile(r'"status"\s*:\s*404\s*,\s*"error"\s*:\s*"Not Found"'),
    re.compile(r'<h1>HTTP\s+Status\s+404', re.I),

    # ── Apache / Nginx ──
    re.compile(r'<title>404\s+Not\s+Found</title>', re.I),
    re.compile(r'The\s+requested\s+URL\s+was\s+not\s+found\s+on\s+this\s+server'),
    re.compile(r'<center>\s*<h1>\s*404\s+Not\s+Found\s*</h1>\s*</center>', re.I),

    # ── Django ──
    re.compile(r'Page\s+not\s+found.*Django', re.I),
    re.compile(r'Using\s+the\s+URLconf\s+defined\s+in', re.I),

    # ── Ruby on Rails ──
    re.compile(r"The\s+page\s+you\s+were\s+looking\s+for\s+doesn't\s+exist", re.I),
    re.compile(r'<h1>\s*The\s+change\s+you\s+wanted\s+was\s+rejected', re.I),

    # ── Node.js / Express ──
    re.compile(r'Cannot\s+(?:GET|POST|PUT|DELETE)\s+/', re.I),
    re.compile(r'<pre>\s*Cannot\s+GET\s+/', re.I),

    # ── PHP / Laravel ──
    re.compile(r'<div\s+class=["\']symfony-exception', re.I),
    re.compile(r'NotFoundHttpException', re.I),

    # ── Generic patterns ──
    re.compile(r'<h1>\s*(?:404|Not\s*Found|Page\s*Not\s*Found|Error)\s*</h1>', re.I),
    re.compile(
        r'(?:does\s+not\s+exist|could\s+not\s+be\s+found|no\s+longer\s+available'
        r'|page\s+(?:you\s+requested\s+)?(?:was|is)\s+not\s+found)', re.I),
    re.compile(r'id=["\'](?:error-?page|not-?found|page-?404)["\']', re.I),

    # ── IIS Detailed Error ──
    re.compile(r'<title>\s*IIS\s+\d+(?:\.\d+)?\s+Detailed\s+Error', re.I),
    re.compile(r'Module\s+IIS\s+Web\s+Core.*Notification\s+MapRequestHandler', re.I),

    # ── Broad error-in-title catch (v2.43.0) ──
    # Many custom error pages have "Error" or "Not Found" as part of a longer
    # title (e.g. "OMT Critical Error", "MyApp - Error", "Acme 404 Page").
    # The narrow patterns above miss these.  This broader match catches any
    # <title> containing "error" or "not found" as a word.
    re.compile(r'<title>[^<]{0,60}(?:critical\s+error|server\s+error|\berror\b)[^<]{0,60}</title>', re.I),
    re.compile(r'<title>[^<]{0,60}(?:not\s+found|unavailable|access\s+denied)[^<]{0,60}</title>', re.I),

    # ── ASP.NET catch-all marker class (v2.43.0) ──
    # target app (and similar ASP.NET apps) use a ghg-html class on the
    # error page's <html> tag.  The literal string "ErrorPage.aspx" is in the
    # URL (not the body), so the earlier regex can't match it.
    re.compile(r'class=["\']ghg-html\b', re.I),
]


def _matches_error_fingerprint(body: str) -> bool:
    """Return True if the response body matches any known error page pattern."""
    if not body:
        return False
    _sample = body[:8192]
    return any(_fp.search(_sample) for _fp in _SOFT_404_FINGERPRINTS)


# ── Internal IP disclosure in HTTP response bodies ────────────────────────────
_RFC1918_NETWORKS = [
    ipaddress.ip_network("10.0.0.0/8"),
    ipaddress.ip_network("172.16.0.0/12"),
    ipaddress.ip_network("192.168.0.0/16"),
]

_RE_RFC1918_IN_TEXT = re.compile(
    r'\b('
    r'10\.\d{1,3}\.\d{1,3}\.\d{1,3}'
    r'|172\.(?:1[6-9]|2\d|3[01])\.\d{1,3}\.\d{1,3}'
    r'|192\.168\.\d{1,3}\.\d{1,3}'
    r')\b'
)

# SVG path coordinate data (d="m4.636 10.2.5.3 ...") produces false IP matches
_RE_SVG_BLOCK = re.compile(r'<svg[\s>].*?</svg>', re.S | re.I)


def _find_rfc1918_in_text(text: str, exclude_ips: "set[str] | None" = None) -> "set[str]":
    """Return RFC 1918 IPs found in *text*, minus any in *exclude_ips*."""
    text = _RE_SVG_BLOCK.sub(' ', text)
    exclude = exclude_ips or set()
    found: set[str] = set()
    for m in _RE_RFC1918_IN_TEXT.finditer(text):
        candidate = m.group(1)
        if candidate in exclude:
            continue
        try:
            addr = ipaddress.ip_address(candidate)
        except ValueError:
            continue
        if any(addr in net for net in _RFC1918_NETWORKS):
            found.add(candidate)
    return found


# ── Exception / stack-trace disclosure patterns (#5 + #12) ─────────────────
_EXCEPTION_PATTERNS = re.compile(
    r'(?:'
    # Python
    r'Traceback \(most recent call last\)'
    r'|(?:TypeError|ValueError|AttributeError|KeyError|ImportError|'
      r'NameError|IndexError|RuntimeError|ZeroDivisionError|'
      r'UnboundLocalError|FileNotFoundError|PermissionError|'
      r'ModuleNotFoundError|StopIteration|RecursionError|'
      r'AssertionError|SyntaxError|IndentationError):'
    r'|File ".*", line \d+'
    r'|django\.(?:core|db|template|utils)\.'
    # Java / Kotlin
    r'|(?:NullPointerException|ClassCastException|ArrayIndexOutOfBoundsException|'
      r'NumberFormatException|IllegalArgumentException|IllegalStateException|'
      r'ConcurrentModificationException|StackOverflowError|OutOfMemoryError)'
    r'|at (?:com|org|net|io|java|javax|sun|jdk)\.\w+\.\w+\('
    r'|java\.lang\.(?:Exception|Error|Throwable|Runtime)'
    # .NET / ASP.NET
    r'|System\.(?:Exception|NullReferenceException|ArgumentException|'
      r'InvalidOperationException|IO\.IOException|FormatException)'
    r'|Stack Trace:\s'
    r'|Server Error in .* Application'
    r'|at \w+\.\w+\.\w+\(.*\) in .*:\d+'
    r'|\[(?:SqlException|OleDbException|OdbcException)\]'
    # PHP
    r'|Fatal error:\s'
    r'|(?:Parse|Compile) error:\s'
    r'|(?:Warning|Notice|Deprecated):\s.*(?:on line \d+|in /)'
    r'|Uncaught (?:Exception|Error|TypeError|ValueError)'
    # Node.js / JavaScript
    r'|(?:ReferenceError|SyntaxError|TypeError|RangeError|URIError|EvalError):'
    r'|at Object\.<anonymous>'
    r'|at Module\._compile'
    # Ruby / Rails
    r'|ActionController::RoutingError'
    r'|NoMethodError:?\s'
    r'|ActiveRecord::(?:RecordNotFound|StatementInvalid)'
    # SQL / Database
    r'|SQLSTATE\[[\dA-Z]+\]'
    r'|(?:MySQL|MariaDB) (?:server|syntax)'
    r'|ORA-\d{5}'
    r'|PG::(?:Error|UndefinedTable|SyntaxError)'
    r'|sqlite3\.(?:OperationalError|IntegrityError)'
    r'|Microsoft OLE DB Provider'
    r'|ODBC (?:SQL Server|Driver)'
    r')', re.IGNORECASE
)


def _detect_exception_disclosure(body: str) -> "list[str]":
    """Return distinct exception/stack-trace snippets found in *body*."""
    if not body:
        return []
    sample = body[:16384]
    matches: list[str] = []
    seen: set[str] = set()
    for m in _EXCEPTION_PATTERNS.finditer(sample):
        snip = m.group(0)[:120]
        key = snip[:40].lower()
        if key not in seen:
            seen.add(key)
            matches.append(snip)
    return matches


# ── GAP-15: Log file exposure paths (FR-466) ────────────────────────────────
_LOG_FILE_PATHS = [
    "/debug.log", "/error.log", "/access.log", "/application.log",
    "/app.log", "/server.log", "/system.log",
    "/wp-content/debug.log",
    "/storage/logs/laravel.log",
    "/logs/", "/log/",
    "/var/log/", "/tmp/logs/",
    "/rails/log/production.log", "/rails/log/development.log",
    "/WEB-INF/logs/", "/catalina.out",
]

_RE_LOG_LINE = re.compile(
    r'(?:'
    r'\d{4}[-/]\d{2}[-/]\d{2}[\sT]\d{2}:\d{2}:\d{2}'   # ISO / common timestamps
    r'|\[\d{2}/\w{3}/\d{4}:\d{2}:\d{2}:\d{2}'           # Apache CLF timestamp
    r'|(?:ERROR|WARN|INFO|DEBUG|FATAL|CRITICAL)\s'        # log-level keywords
    r'|Traceback \(most recent call last\)'                # Python stack traces
    r'|at (?:com|org|net|java)\.\w+\.\w+\('               # Java stack traces
    r'|Stack Trace:\s'                                     # .NET stack traces
    r')', re.IGNORECASE
)


def _check_log_exposure(base_url: str, sess: "requests.Session",
                        timeout: int) -> "list[tuple[str, str, str]]":
    """Probe common log file paths; return [(path, status_hint, snippet)]."""
    hits: list[tuple[str, str, str]] = []
    for path in _LOG_FILE_PATHS:
        probe_url = base_url.rstrip("/") + path
        try:
            r = sess.get(probe_url, timeout=min(timeout, 6),
                         allow_redirects=True, stream=True)
            if r.status_code != 200:
                continue
            ct = r.headers.get("Content-Type", "").lower()
            # Accept text/plain, application/octet-stream, or text/html
            # only when the body genuinely looks like a log
            chunk = r.text[:8192] if hasattr(r, 'text') else ""
            if not chunk:
                continue
            log_matches = _RE_LOG_LINE.findall(chunk)
            if len(log_matches) >= 2:
                # Looks like a real log file
                snippet = chunk[:300].replace("\n", " | ")
                hits.append((path, ct, snippet))
        except Exception:
            continue
    return hits


# ── GAP-17: Cloud credentials file paths (FR-468) ───────────────────────────
_CLOUD_CRED_PATHS = [
    ("/.aws/credentials",     r'\[(?:default|profile)',  "AWS credentials"),
    ("/.aws/config",          r'\[(?:default|profile)',  "AWS config"),
    ("/aws/credentials",      r'\[(?:default|profile)',  "AWS credentials"),
    ("/.docker/config.json",  r'"auths"',                "Docker config"),
    ("/.kube/config",         r'apiVersion:',            "Kubernetes config"),
    ("/.npmrc",               r'//registry\.',           "NPM config"),
    ("/.git-credentials",     r'https?://[^\s<>]+@',     "Git credentials"),
    ("/.pgpass",              r'^\S+:\d{1,5}:\S+:\S+:', "PostgreSQL password file"),
]


def _check_cloud_cred_exposure(base_url: str, sess: "requests.Session",
                               timeout: int) -> "list[tuple[str, str, str]]":
    """Probe for exposed cloud/CI credential files.
    Returns [(path, cred_type, snippet)]."""
    hits: list[tuple[str, str, str]] = []
    for path, pattern, cred_type in _CLOUD_CRED_PATHS:
        probe_url = base_url.rstrip("/") + path
        try:
            r = sess.get(probe_url, timeout=min(timeout, 6),
                         allow_redirects=True)
            if r.status_code != 200:
                continue
            if _is_waf_block(r):
                continue
            body = r.text[:4096] if hasattr(r, 'text') else ""
            if not body:
                continue
            body_strip = body.lstrip()[:256].lower()
            if body_strip.startswith(("<!doctype", "<html", "<head", "<?xml")):
                continue
            if re.search(pattern, body, re.I | re.M):
                snippet = body[:300].replace("\n", " | ")
                hits.append((path, cred_type, snippet))
        except Exception:
            continue
    return hits


