def _phase_files(target: dict, cfg: dict, pm: ProgressManager,
                 out: OutputManager, sess: requests.Session) -> None:
    phase      = "files"
    url        = target["url"]
    timeout    = cfg.get("timeout", 10)
    total      = len(_SENSITIVE_FILES)
    _base_path = urllib.parse.urlparse(url).path or "/"
    vc.status(phase, "Sensitive Files", "running", "Probing", 0, total)

    # Detect wildcard/catch-all before probing; skip files that match the baseline.
    _file_wc = _detect_wildcard(url, sess, timeout)
    if _file_wc is not None:
        vc.log("[files] Wildcard detected — all file findings will be validated against baseline",
               "INFO")
    # SPA baseline: fetch the root page body once; any file probe that returns
    # an identical body is the SPA shell, not a real file.
    _spa_baseline_body = None
    try:
        _tp_files = json.loads((out.root / "target_profile.json").read_text())
        _ws = (_tp_files.get("web_structure") or "").lower()
        if "spa" in _ws or "single page" in _ws:
            _spa_r = sess.get(url, timeout=timeout, allow_redirects=True)
            if _spa_r.status_code == 200:
                _spa_baseline_body = _spa_r.text[:50000]
                vc.log("[files] SPA detected — file probes returning identical body will be skipped",
                       "INFO")
    except Exception:
        pass

    for idx, (fpath, risk, fdesc) in enumerate(_SENSITIVE_FILES):
        vc.status(phase, "Sensitive Files", "running", fpath, idx, total)
        try:
            _fpath_full_url = url.rstrip("/") + fpath
            r = sess.get(_fpath_full_url, timeout=timeout, allow_redirects=False)
            if r.status_code == 200 and len(r.text) > 5:
                if _is_wildcard_match(r, _file_wc):
                    continue   # matches catch-all baseline — not a real file
                if (_spa_baseline_body is not None
                        and r.text[:50000] == _spa_baseline_body):
                    continue   # SPA shell — identical to root page
                if _matches_error_fingerprint(r.text):
                    continue   # custom error page (e.g. ErrorPage.aspx catch-all)
                if _response_is_error_page(r.text, fpath):
                    continue   # secondary error-page / content-type mismatch guard
                # Content-Type sanity check — a genuine .json/.xml/.env file
                # should NOT come back as text/html.
                _ct = (r.headers.get("Content-Type") or "").lower()
                _fext = ""
                _fp_base = fpath.rstrip("/").split("/")[-1]
                if "." in _fp_base:
                    _fext = "." + _fp_base.rsplit(".", 1)[-1].lower()
                if _fext and _fext in _NON_HTML_EXTENSIONS and "text/html" in _ct:
                    continue   # HTML response for non-HTML file = catch-all
                out_f = out.output_path(phase, "file_" + fpath.replace("/", "_").lstrip("_"))
                out_f.write_text(r.text[:10000], encoding="utf-8")
                out.add_finding(
                    title="Discovery: Sensitive File Exposed",
                    url=_fpath_full_url, port=target["port"], risk=risk,
                    description=fdesc + f" ({_fpath_full_url} returned HTTP 200).",
                    output=r.text[:500], sources="fracture-files",
                    service=target["scheme"], output_file=str(out_f),
                    affected=_fpath_full_url,
                    owasp="A05:2025 Security Misconfiguration", nist="CM-7",
                    remediation=f"Remove or restrict access to {fpath}.",
                )
                try:
                    _write_structure_map(out, target,
                                         path_statuses={_base_path.rstrip("/") + fpath: r.status_code},
                                         source="files")
                except Exception:
                    pass
                vc.log(f"[files] Found: {fpath} (risk={risk})", "SUCCESS")
                if risk == "CRITICAL" and any(kw in fpath.lower() for kw in
                        ("credentials", "tfstate", ".env", "secret")):
                    out.log_action_item(
                        type="cross_tool_credential",
                        recommended_tool="isotope",
                        target=f"{target['ip']}:{target['port']}",
                        ip=target["ip"], port=target["port"],
                        hostname=target.get("hostname", ""),
                        title=f"Credential File Exposed — Validate Access ({fpath})",
                        description=(
                            f"Fracture found {fpath} exposed at "
                            f"{_fpath_full_url}. Run Isotope to extract and "
                            f"validate exposed credentials against target "
                            f"services (AWS, databases, SSH, etc.)."),
                        source_finding="credential_file_exposure",
                        priority="CRITICAL", scope="webapp",
                    )
        except Exception:
            pass

    vc.status(phase, "Sensitive Files", "complete", "Done", total, total)
    vc.log("[files] Phase complete", "SUCCESS")


