_NIKTO_NORM_COMPILED = [(re.compile(p, re.IGNORECASE), t, r, o, n, rm)
                         for p, t, r, o, n, rm in _NIKTO_NORM]


_NIKTO_DYN_HEADER = re.compile(
    r"[Ss]uggested security header (?:is )?missing:\s*([A-Za-z0-9_-]+)", re.IGNORECASE)
_NIKTO_DYN_UNCOMMON = re.compile(
    r"[Uu]ncommon header\(?s?\)?\s+['\"]?([A-Za-z0-9_-]+)['\"]?\s+found", re.IGNORECASE)
_NIKTO_DYN_CERT_MISMATCH = re.compile(
    r"[Hh]ostname\s+['\"]?([^'\"]+?)['\"]?\s+does\s+not\s+match\s+certificate'?s?\s+names?\s*[:(]\s*(.+)",
    re.IGNORECASE)
_NIKTO_DYN_OUTDATED = re.compile(
    r"([A-Za-z][A-Za-z0-9_.+-]*/[\d][\w.+-]*)\s+appears?\s+to\s+be\s+outdated",
    re.IGNORECASE)
_NIKTO_DYN_IP_DISCLOSURE = re.compile(
    r"(?:IP\s+address\s+found\s+in\s+the\s+['\"]?([^'\"]+?)['\"]?\s+header|"
    r"(?:internal|private)\s+IP\s+(?:address\s+)?(?:found|leaked|disclosed)|"
    r"reveal\s+its\s+(?:internal|real)[\w\s]*IP\s+in\s+the\s+([A-Za-z0-9_-]+)\s+header)",
    re.IGNORECASE)


_ADMIN_PATH_KEYWORDS = frozenset({
    "admin", "administrator", "adm", "cpanel", "webadmin", "sysadmin",
    "manager", "console", "dashboard", "backend", "controlpanel",
    "phpmyadmin", "adminer", "wp-admin", "wp-login",
})


def _normalize_nikto(vuln: dict) -> dict:
    """Map a nikto vulnerability dict to a Fracture-convention finding dict.

    Returns a dict with at minimum title/risk/owasp/nist/remediation.
    May also return 'affected' when the normaliser extracts structured
    location data (e.g. hostname vs certificate names).
    """
    msg = vuln.get("msg", "").strip()
    _nik_id = vuln.get("id", "")
    _nik_url = vuln.get("url", "")

    # Dynamic extractions checked first — these build the title from
    # captured groups so the table can't handle them statically.
    _m = _NIKTO_DYN_CERT_MISMATCH.search(msg)
    if _m:
        _host = _m.group(1).strip()
        _certs = _m.group(2).strip().rstrip(".)")
        return {
            "title": "SSL/TLS Certificate: Hostname Mismatch",
            "risk": "HIGH",
            "owasp": "A02:2025 Cryptographic Failures", "nist": "SC-17",
            "remediation": (
                "Obtain an SSL/TLS certificate that covers the hostname "
                "used to access the service, or add a Subject Alternative "
                "Name (SAN) entry for it."
            ),
            "affected": f"Hostname: {_host} / Certificate: {_certs}",
        }
    _m = _NIKTO_DYN_OUTDATED.search(msg)
    if _m:
        _sw = _m.group(1).strip()
        return {"title": f"Outdated Software: {_sw}", "risk": "MEDIUM",
                "owasp": "A06:2025 Vulnerable and Outdated Components", "nist": "SI-2",
                "remediation": f"Update {_sw.split('/')[0]} to the latest stable version.",
                "affected": _sw}
    _m = _NIKTO_DYN_IP_DISCLOSURE.search(msg)
    if _m:
        _hdr = _m.group(1) or _m.group(2)
        _affected = f"header: {_hdr.strip()}" if _hdr else ""
        _r = {"title": "Information Disclosure: Internal IP in HTTP Response", "risk": "MEDIUM",
              "owasp": "A05:2025 Security Misconfiguration", "nist": "SI-11",
              "remediation": "Configure the web server or reverse proxy to suppress internal IP addresses from response headers and error pages."}
        if _affected:
            _r["affected"] = _affected
        return _r
    _m = _NIKTO_DYN_HEADER.search(msg)
    if _m:
        _hdr = "-".join(w.capitalize() for w in _m.group(1).strip().split("-"))
        if _hdr not in _SHCHECK_ALLOWED_HEADERS:
            return None
        return {"title": f"Missing Security Header: {_hdr}", "risk": "LOW",
                "owasp": "A05:2025 Security Misconfiguration", "nist": "SC-8",
                "remediation": f"Configure the {_hdr} response header."}
    _m = _NIKTO_DYN_UNCOMMON.search(msg)
    if _m:
        _hdr = _m.group(1).strip()
        _nik_hn_l = _hdr.lower()
        if _nik_hn_l in _KNOWN_NON_SEC_HEADERS:
            return {"title": "Discovery: Known Non-Security Header Detected",
                    "risk": "INFO",
                    "owasp": "A05:2025 Security Misconfiguration", "nist": "SI-11",
                    "affected": _hdr,
                    "remediation": f"The {_hdr} header is a known non-security header. No action required."}
        _fp_hit = _FINGERPRINT_HEADERS.get(_nik_hn_l)
        if _fp_hit:
            return {"title": f"Discovery: {_fp_hit[0]}",
                    "risk": "INFO",
                    "owasp": "A05:2025 Security Misconfiguration", "nist": "CM-7",
                    "affected": _hdr,
                    "remediation": _fp_hit[1]}
        return {"title": f"Unknown Header Identified: {_hdr}", "risk": "INFO",
                "owasp": "A05:2025 Security Misconfiguration", "nist": "SI-11",
                "remediation": f"Review the {_hdr} header for information disclosure."}

    # Table-driven normalisation — first match wins.
    for _rx, _title, _risk, _owasp, _nist, _remed in _NIKTO_NORM_COMPILED:
        if _rx.search(msg):
            if _risk == "DROP":
                return None
            if _title == "Admin Panel Exposed" and _nik_url:
                _url_parts = _nik_url.lower().replace("/", " ").replace("-", " ").replace("_", " ").split()
                if not (_ADMIN_PATH_KEYWORDS & set(_url_parts)):
                    return {"title": "Login Page Identified",
                            "risk": "INFO", "owasp": _owasp, "nist": _nist,
                            "remediation": "Informational — login pages are expected on web applications."}
            # Cookie FP gate — validate nikto output against actual attrs
            if _title.startswith("Missing Secure Cookie Attribute:"):
                _nik_msg_low = msg.lower()
                if _title.endswith(": SameSite"):
                    if re.search(r'samesite\s*=\s*\w+', _nik_msg_low):
                        return None
                elif _title.endswith(": HttpOnly"):
                    if "httponly" in _nik_msg_low.split("not")[0] if "not" in _nik_msg_low else False:
                        pass  # "httponly not set" — legit finding
                elif _title.endswith(": Secure"):
                    pass
                if _is_deletion_cookie_from_output(_nik_msg_low):
                    return None
            return {"title": _title, "risk": _risk, "owasp": _owasp,
                    "nist": _nist, "remediation": _remed}

    # Fallback: use first sentence of msg as title (no "Nikto:" prefix so
    # identical findings from different tools still merge by title).
    _fb_title = msg.split(". ")[0].strip().rstrip(".") if msg else f"Nikto ID {_nik_id}"
    if len(_fb_title) > 120:
        _fb_title = _fb_title[:117] + "..."
    return {"title": _fb_title, "risk": "MEDIUM",
            "owasp": "A05:2025 Security Misconfiguration", "nist": "SI-2",
            "remediation": "Review and remediate the identified web server issue."}


