# ── Nuclei output quality enrichment ──────────────────────────────────────────
# This is a MODIFICATION to the existing _normalize_nuclei() function, not a
# new function.  The change replaces the `_output` variable computation at
# the top of the function and adds a helper.

# ── OLD CODE (lines 22665-22667 in fracture.py) ──
def _enrich_nuclei_output(raw_output: str, item: dict) -> str:
    """Build informative output text for a nuclei finding.

    When the raw output is empty or just "Template: <id>", enriches it with
    matched-at URL, template metadata, curl command, and response excerpts
    so the finding is human-reviewable without consulting raw nuclei logs.
    """
    _tid = item.get("template-id", "")
    _matched = item.get("matched-at", "")
    _matcher = item.get("matcher-name", "")
    _sev = (item.get("info", {}).get("severity") or "info").upper()

    # If we have real extracted content, use it with light context
    if raw_output and not raw_output.startswith("Template:"):
        parts = []
        if _matched:
            parts.append(f"Matched at: {_matched}")
        parts.append(str(raw_output)[:2000])
        return "\n".join(parts)

    # Build enriched output from all available nuclei fields
    parts = []
    if _matched:
        parts.append(f"Matched at: {_matched}")
    parts.append(f"Template: {_tid}")
    if _matcher:
        parts.append(f"Matcher: {_matcher}")
    parts.append(f"Severity: {_sev}")

    # Try to get actual evidence from nuclei's output fields
    _curl = item.get("curl-command", "")
    _response = item.get("response", "")
    _matched_line = item.get("matched-line", "")
    _host = item.get("host", "")

    if _matched_line and _matched_line != raw_output:
        parts.append("")
        parts.append("Matched line:")
        parts.append(str(_matched_line)[:500])
    elif _response:
        parts.append("")
        parts.append("Response excerpt:")
        # Extract just the body portion if it looks like a full HTTP response
        _resp_str = str(_response)
        _body_start = _resp_str.find("\r\n\r\n")
        if _body_start > 0:
            _resp_body = _resp_str[_body_start + 4:]
            parts.append(_resp_body[:500])
        else:
            parts.append(_resp_str[:500])

    if _curl:
        parts.append("")
        parts.append(f"Reproduce: {str(_curl)[:300]}")

    if _host and _host != _matched:
        parts.append(f"Host: {_host}")

    return "\n".join(parts)


def _normalize_nuclei(item: dict) -> dict:
    """Map a nuclei JSONL item to a Fracture-convention finding dict."""
    _info = item.get("info", {})
    _tid = item.get("template-id", "")
    _matcher = item.get("matcher-name", "")
    _name = _info.get("name", "Nuclei Finding")
    _sev = _NUCLEI_SEVERITY_MAP.get(_info.get("severity", "info"), "INFO")
    _desc = _info.get("description", "")
    _cves = ",".join(_info.get("classification", {}).get("cve-id", []) or [])
    # ── v1.1 enrichment fields from nuclei classification ──
    _cls = _info.get("classification", {})
    _v11: dict = {}
    _n_cvss = _cls.get("cvss-score")
    if _n_cvss is not None:
        try:
            _v11["cvss_score"] = round(float(_n_cvss), 1)
        except (ValueError, TypeError):
            pass
    _n_cvss_vec = _cls.get("cvss-metrics", "")
    if _n_cvss_vec:
        _v11["cvss_vector"] = str(_n_cvss_vec)
    _n_cwe = _cls.get("cwe-id") or []
    if _n_cwe:
        _v11["cwe"] = [str(c) for c in _n_cwe if c]
    _matched = item.get("matched-at", "")
    _output_raw = item.get("extracted-results", item.get("matched-line", ""))
    if isinstance(_output_raw, list):
        _output_raw = "\n".join(_output_raw)
    _output = _enrich_nuclei_output(_output_raw, item)

    # ── Priority 1: http-missing-security-headers with named matchers ──
    # Each JSONL line for this template carries a matcher-name like
    # "strict-transport-security".  Without this check the template-id
    # regex table cannot distinguish which header is missing.
    if _tid == "http-missing-security-headers" and _matcher:
        _hdr = _NUCLEI_HDR_MATCHER.get(_matcher)
        if _hdr:
            _hdr_display, _hdr_risk = _hdr
            return {
                "title": f"Missing Security Header: {_hdr_display}",
                "risk": _hdr_risk,
                "description": _desc or f"The {_hdr_display} HTTP security header is not present.",
                "output": str(_output)[:2000] if _output else f"Template: {_tid}:{_matcher}",
                "owasp": "A05:2025 Security Misconfiguration", "nist": "SI-11",
                "remediation": f"Add the {_hdr_display} header to all HTTP responses.",
                "cves": _cves, **_v11,
            }
        return None

    # ── Priority 1b: Deprecated TLS/SSL protocol — split by protocol ──
    # Nuclei's tls-version / deprecated-tls / sslvN templates emit a
    # generic title.  Parse the specific protocol from the template-id,
    # matcher, output, or description to emit per-protocol findings
    # matching testssl/sslscan titles and risk levels.
    _tid_lower = _tid.lower()
    if re.search(r"tls-version|deprecated-tls|ssl-deprecated|sslv[23]|tlsv1", _tid_lower):
        _proto_map = [
            (re.compile(r"sslv?2",         re.I), "SSLv2",   "CRITICAL", "CVE-2016-0800"),
            (re.compile(r"sslv?3",         re.I), "SSLv3",   "HIGH",     "CVE-2014-3566"),
            (re.compile(r"tlsv?1[._-]0|tls[._\s-]1\.0", re.I), "TLSv1.0", "MEDIUM", "CVE-2011-3389"),
            (re.compile(r"tlsv?1[._-]1|tls[._\s-]1\.1", re.I), "TLSv1.1", "MEDIUM", ""),
        ]
        _nuc_text = f"{_tid} {_matcher} {_output} {_desc} {_name}"
        _detected_proto = None
        for _prx, _pname, _prisk, _pcve in _proto_map:
            if _prx.search(_nuc_text):
                _detected_proto = (_pname, _prisk, _pcve)
                break
        if _detected_proto:
            _dp_name, _dp_risk, _dp_cve = _detected_proto
            _dp_all_cves = ",".join(filter(None, [_dp_cve, _cves]))
            return {
                "title": f"Deprecated Protocol Enabled: {_dp_name}",
                "risk": _dp_risk,
                "description": _desc or (
                    f"{_dp_name} is a deprecated protocol version that is no longer "
                    "considered secure. Disable it and enforce TLS 1.2 or higher."
                ),
                "output": str(_output)[:2000] if _output else f"Template: {_tid}",
                "owasp": "A02:2025 Cryptographic Failures", "nist": "SC-8",
                "remediation": (
                    f"Disable {_dp_name} on the server/load balancer and enforce "
                    "TLS 1.2 minimum. Update the TLS configuration to remove "
                    "support for deprecated protocol versions."
                ),
                "cves": _dp_all_cves, **_v11,
            }

    # ── Priority 2: Dynamic titles from template category ──
    # Use matcher-name (the actual detected technology) instead of
    # info.name (which is just "Wappalyzer Technology Detection").
    if _NUCLEI_DYN_TECH.search(_tid):
        if _matcher:
            _tech_display = _NUCLEI_TECH_DISPLAY.get(
                _matcher, _matcher.replace("-", " ").replace("_", " ").title())
        elif _name and _name.lower() not in (
                "wappalyzer technology detection", "tech detect"):
            _tech_display = _name
        else:
            _tech_display = "Unknown Technology"
        _sw_cat = "Software Version Detected" if re.search(r'\d+\.\d+', _tech_display) else "Software Identified"
        return {
            "title": f"{_sw_cat}: {_tech_display}", "risk": "INFO",
            "description": _desc or f"{_tech_display} detected by nuclei ({_tid}).",
            "output": str(_output)[:2000] if _output else f"Template: {_tid}",
            "owasp": "A05:2025 Security Misconfiguration", "nist": "CM-7",
            "remediation": "Review exposed technology stack for known vulnerabilities.",
            "cves": _cves, **_v11,
        }
    if _NUCLEI_DYN_WAF.search(_tid):
        # Classify: if _name resolves to a known LB-only platform, emit a
        # load-balancer finding rather than a misleading "WAF Active" title.
        _waf_name_upper = _name.upper()
        _is_lb = any(lb.upper() in _waf_name_upper for lb in (
            "F5", "BIG-IP", "HAProxy", "Nginx LB", "AWS ELB", "Azure LB",
            "Citrix NetScaler", "Envoy",
        ))
        if _is_lb:
            return {
                "title": f"Discovery: Load Balancer Detected - {_name}", "risk": "INFO",
                "description": (
                    _desc or f"A load balancer ({_name}) was identified in front of the target. "
                    "The load balancer distributes traffic but does NOT perform application-layer "
                    "inspection or WAF-style blocking."
                ),
                "output": str(_output)[:2000] if _output else f"Template: {_tid}",
                "owasp": "A05:2025 Security Misconfiguration", "nist": "SC-7",
                "remediation": (
                    "Ensure load balancer cookies do not leak internal infrastructure details. "
                    "Review session affinity configuration. Do not confuse load balancing with "
                    "WAF protection."
                ),
                "cves": _cves, **_v11,
            }
        _waf_id = _NUCLEI_WAF_MATCHER_MAP.get(
            _matcher.lower(), _name if _name != "WAF Detection" else _matcher or "Unknown")
        return {
            "title": f"Discovery: WAF Detected - {_waf_id}", "risk": "INFO",
            "description": (
                _desc or
                f"A WAF or edge security platform ({_waf_id}) was identified by nuclei "
                f"({_tid}, matcher: {_matcher}). WAF rules may mask application-layer "
                f"vulnerabilities — absence of a finding does not confirm absence of "
                f"the vulnerability."
            ),
            "output": str(_output)[:2000] if _output else f"Template: {_tid}",
            "owasp": "A05:2025 Security Misconfiguration", "nist": "CM-7",
            "remediation": (
                "Keep WAF rule sets up to date and covering OWASP Top 10 2025. "
                "Do not rely solely on WAF protection — fix underlying vulnerabilities."
            ),
            "cves": _cves, **_v11,
        }
    if _NUCLEI_DYN_PANEL.search(_tid):
        _panel_path = ""
        try:
            _panel_path = urllib.parse.urlparse(_matched).path or ""
        except Exception:
            pass
        _panel_title = f"Admin Panel Exposed: {_panel_path}" if _panel_path else f"Admin Panel Exposed: {_name}"
        return {
            "title": _panel_title, "risk": "HIGH",
            "description": _desc or f"{_name} detected by nuclei ({_tid}).",
            "output": str(_output)[:2000] if _output else f"Template: {_tid}",
            "owasp": "A05:2025 Security Misconfiguration", "nist": "AC-3",
            "remediation": "Restrict admin interfaces by IP allowlist or VPN.",
            "cves": _cves, **_v11,
        }

    # ── Priority 3: Table-driven regex on template-id / matcher-name / name ──
    # Search template-id, then matcher-name, then info.name — first match wins.
    _nuc_search_fields = [_tid]
    if _matcher:
        _nuc_search_fields.append(_matcher)
    _nuc_search_fields.append(_name)
    for _rx, _title, _risk, _owasp, _nist, _remed in _NUCLEI_NORM_COMPILED:
        if any(_rx.search(f) for f in _nuc_search_fields):
            if _title is None:
                # CVE catch-all: use nuclei's own name
                break
            if _title == "__SUPPRESS__":
                return {}  # Intentionally suppressed — known FP template
            # ── Cookie FP gate: validate nuclei output against actual attrs ──
            if _title.startswith("Missing Secure Cookie Attribute:"):
                _nuc_out_low = (str(_output) or "").lower()
                if _title.endswith(": SameSite"):
                    if re.search(r'samesite\s*=\s*\w+', _nuc_out_low):
                        return {}
                elif _title.endswith(": HttpOnly"):
                    if "httponly" in _nuc_out_low:
                        return {}
                elif _title.endswith(": Secure"):
                    if re.search(r'[;\s]secure[;\s]|[;\s]secure$', _nuc_out_low):
                        return {}
                if _is_deletion_cookie_from_output(_nuc_out_low):
                    return {}
            return {
                "title": _title, "risk": _risk or _sev,
                "description": _desc or f"{_name} ({_tid})",
                "output": str(_output)[:2000] if _output else f"Template: {_tid}",
                "owasp": _owasp, "nist": _nist,
                "remediation": _remed, "cves": _cves, **_v11,
            }

    # ── Priority 4: Template-path directory category ──
    # Use the template path directory to assign category-based titles for
    # templates not matched by the table (e.g. new exposed-panels, new
    # technology detections added after our table was written).
    _tpath = item.get("template-path", "")
    if _tpath:
        _tp_parts = _tpath.replace("\\", "/").split("/")
        if "exposed-panels" in _tp_parts:
            _ep_path = ""
            try:
                _ep_path = urllib.parse.urlparse(_matched).path or ""
            except Exception:
                pass
            _clean = _name
            for _sfx in (" - Detect", " - Detection", " - Exposure",
                         " Panel - Detect", " Login Panel - Detect",
                         " Login - Detect", " Panel Detect"):
                if _clean.endswith(_sfx):
                    _clean = _clean[:-len(_sfx)].strip()
                    break
            _ep_title = f"Admin Panel Exposed: {_ep_path}" if _ep_path else f"Admin Panel Exposed: {_clean}"
            return {
                "title": _ep_title, "risk": _sev or "MEDIUM",
                "description": _desc or f"{_name} ({_tid})",
                "output": str(_output)[:2000] if _output else f"Template: {_tid}",
                "owasp": "A01:2025 Broken Access Control", "nist": "CM-7",
                "remediation": "Restrict access to administrative panels.",
                "cves": _cves, **_v11,
            }
        if "technologies" in _tp_parts:
            _clean = _name
            for _sfx in (" - Detect", " - Detection", " - Tech Detect",
                         " - Discovery"):
                if _clean.endswith(_sfx):
                    _clean = _clean[:-len(_sfx)].strip()
                    break
            _sw_cat2 = "Software Version Detected" if re.search(r'\d+\.\d+', _clean) else "Software Identified"
            return {
                "title": f"{_sw_cat2}: {_clean}", "risk": _sev or "INFO",
                "description": _desc or f"{_name} ({_tid})",
                "output": str(_output)[:2000] if _output else f"Template: {_tid}",
                "owasp": "A06:2025 Vulnerable and Outdated Components", "nist": "SI-2",
                "remediation": "Keep identified components up to date.",
                "cves": _cves, **_v11,
            }
        if "default-logins" in _tp_parts:
            return {
                "title": f"Default Credentials: {_name}", "risk": _sev or "HIGH",
                "description": _desc or f"{_name} ({_tid})",
                "output": str(_output)[:2000] if _output else f"Template: {_tid}",
                "owasp": "A07:2025 Identification and Authentication Failures", "nist": "IA-5",
                "remediation": "Change default credentials immediately.",
                "cves": _cves, **_v11,
            }
        if "exposures" in _tp_parts:
            _ep_path = ""
            try:
                _ep_path = urllib.parse.urlparse(_matched).path or ""
            except Exception:
                pass
            return {
                "title": f"Sensitive Path Accessible: {_ep_path}" if _ep_path else f"Sensitive Path Accessible: {_name}",
                "risk": _sev or "MEDIUM",
                "description": _desc or f"{_name} ({_tid})",
                "output": str(_output)[:2000] if _output else f"Template: {_tid}",
                "owasp": "A01:2025 Broken Access Control", "nist": "AC-3",
                "remediation": "Restrict access to the exposed resource.",
                "cves": _cves, **_v11,
            }
        if "cves" in _tp_parts or "vulnerabilities" in _tp_parts:
            return {
                "title": f"Vulnerable Component: {_name}", "risk": _sev,
                "description": _desc or f"{_name} ({_tid})",
                "output": str(_output)[:2000] if _output else f"Template: {_tid}",
                "owasp": "A06:2025 Vulnerable and Outdated Components", "nist": "SI-2",
                "remediation": "Apply vendor patches and update affected components.",
                "cves": _cves, **_v11,
            }
        if "misconfiguration" in _tp_parts:
            return {
                "title": f"Server Misconfiguration: {_name}", "risk": _sev,
                "description": _desc or f"{_name} ({_tid})",
                "output": str(_output)[:2000] if _output else f"Template: {_tid}",
                "owasp": "A05:2025 Security Misconfiguration", "nist": "CM-6",
                "remediation": "Review and correct the identified misconfiguration.",
                "cves": _cves, **_v11,
            }

    # Fallback: no prefix, so identical findings from different tools merge.
    return {
        "title": _name, "risk": _sev,
        "description": _desc or f"Nuclei template {_tid} matched.",
        "output": str(_output)[:2000] if _output else f"Template: {_tid}",
        "owasp": "A06:2025 Vulnerable and Outdated Components", "nist": "SI-2",
        "remediation": "Apply vendor patches and update affected components.",
        "cves": _cves, **_v11,
    }


def _launch_vulnscan_bg(target: dict, cfg: dict, pm: ProgressManager,
                        out: OutputManager, sess: requests.Session,
                        fast: bool = False,
                        skip_nikto: bool = False) -> dict:
    """Launch nuclei and nikto as background processes.

    Returns a handle dict consumed by _collect_vulnscan_bg() to join and
    parse results.  Both tools run in the background while subsequent
    phases (endpoint_tools, jwt, injection, traversal, etc.) execute
    concurrently — nuclei and nikto produce only findings, nothing
    downstream depends on their output.
    """
    phase   = "vulnscan"
    url     = target["url"]
    timeout = max(cfg.get("nuclei_timeout", 1800), 1800)
    handle: dict = {
        "target": target, "cfg": cfg, "out": out, "url": url, "phase": phase,
        "timeout": timeout,
        "nuclei_proc": None, "nuclei_cmd": None, "nuclei_out": None,
        "nuclei_started": None,
        "nikto_procs": [],   # list of (proc, cmd, nik_out, nik_base, started)
    }
    # Derive origin root + app parents for broad scanning (same logic as recon)
    _vs_parsed = urllib.parse.urlparse(url)
    _vs_origin = f"{_vs_parsed.scheme}://{_vs_parsed.netloc}"
    _vs_parents: list[str] = [_vs_origin]
    _vs_path = _vs_parsed.path.rstrip("/")
    if _vs_path:
        _vs_parts = _vs_path.split("/")
        for _vi in range(2, len(_vs_parts) + 1):
            _vp = "/".join(_vs_parts[:_vi])
            _vp_url = _vs_origin + _vp
            if _vp_url not in _vs_parents:
                _vs_parents.append(_vp_url)
    # Extract session cookies + auth headers for subprocess tools (nuclei, nikto)
    _vs_cookie_str, _vs_auth_headers = _extract_subprocess_auth(sess)
    vc.status(phase, "Vuln Scan", "running", "launching background", 0, 2)

    # ── 1. Launch nuclei ────────────────────────────────────────────────────
    nuclei = _find_tool("nuclei")
    if nuclei and not fast:
        nuc_out = out.output_path(phase, "nuclei_" + target["hostname"])
        _nuc_templates_dir = "/opt/nuclei-templates"

        # Build a target list from the structure_map so nuclei scans every
        # discovered endpoint, not just the base URL.  A React SPA that
        # serves a JS shell at "/" gives nuclei almost nothing to work with
        # when only the base URL is supplied.
        _NUC_USEFUL_CODES = {200, 201, 202, 204, 401, 403}
        _nuc_targets: list = [url]
        _nuc_skipped = 0
        try:
            _nuc_sm_path = out.root / "structure_map.json"
            if _nuc_sm_path.exists():
                _nuc_sm = json.loads(_nuc_sm_path.read_text())
                _nuc_base = _vs_origin
                _nuc_paths = _nuc_sm.get("paths", {})
                for _np in sorted(_nuc_paths.keys()):
                    _np_info = _nuc_paths[_np]
                    _np_code = None
                    if isinstance(_np_info, dict):
                        _np_code = _np_info.get("status")
                        if _np_code is None:
                            for _nv in _np_info.values():
                                if isinstance(_nv, int) and _nv in _NUC_USEFUL_CODES:
                                    _np_code = _nv
                                    break
                    if isinstance(_np_code, int) and _np_code not in _NUC_USEFUL_CODES:
                        _nuc_skipped += 1
                        continue
                    _nuc_full = _nuc_base + _np
                    if _nuc_full not in _nuc_targets:
                        _nuc_targets.append(_nuc_full)
        except Exception:
            pass
        if _nuc_skipped:
            vc.log(
                f"[vulnscan] nuclei: filtered {_nuc_skipped} redirect/error "
                f"paths from target list (only 200/401/403 included)",
                "INFO",
            )

        _nuc_list_file = out.root / phase / "nuclei_targets.txt"
        _nuc_list_file.parent.mkdir(parents=True, exist_ok=True)
        _nuc_list_file.write_text("\n".join(_nuc_targets), encoding="utf-8")
        vc.log(
            f"[vulnscan] nuclei target list: {len(_nuc_targets)} URLs "
            f"(base + {len(_nuc_targets) - 1} structure_map paths)",
            "INFO",
        )

        nuc_out.parent.mkdir(parents=True, exist_ok=True)
        cmd = [nuclei, "-l", str(_nuc_list_file),
               "-s", "critical,high,medium,low,info",
               "-silent", "-jsonl", "-no-interactsh",
               "-stats", "-c", "25",
               "-o", str(nuc_out)]
        if _vs_cookie_str:
            cmd += ["-H", f"Cookie: {_vs_cookie_str}"]
        for _ah_name, _ah_val in _vs_auth_headers:
            cmd += ["-H", f"{_ah_name}: {_ah_val}"]
        _nuc_ua = _subprocess_ua(sess)
        if _nuc_ua:
            cmd += ["-H", f"User-Agent: {_nuc_ua}"]
        if _vs_cookie_str or _vs_auth_headers:
            vc.log("[vulnscan] nuclei: passing session auth for authenticated scanning", "INFO")
        if Path(_nuc_templates_dir).is_dir():
            cmd += ["-t", _nuc_templates_dir]
        # ── Technology-based template pre-filtering ──
        _nuc_exclude = _build_nuclei_exclude_tags(out.root / "target_profile.json")
        if _nuc_exclude:
            cmd += ["-etags", ",".join(_nuc_exclude)]
            vc.log(
                f"[vulnscan] nuclei: excluding {len(_nuc_exclude)} irrelevant "
                f"technology tags based on target profile", "INFO")
        _nuc_max_time = f"{max(timeout // 60, 1)}m"
        cmd += ["-max-time", _nuc_max_time]
        vc.log(f"[vulnscan] Launching nuclei in background (max-time {_nuc_max_time}) ...", "INFO")
        try:
            _nuc_started = datetime.now().astimezone()
            proc = _popen(cmd, stdout=subprocess.DEVNULL, stderr=subprocess.PIPE, text=True,
                          preexec_fn=_go_mem_limit_preexec)
            _register_proc(proc)
            handle["nuclei_proc"]    = proc
            handle["nuclei_cmd"]     = cmd
            handle["nuclei_out"]     = nuc_out
            handle["nuclei_started"] = _nuc_started
            handle["nuclei_tool"]    = nuclei
        except Exception as e:
            vc.error(f"[vulnscan] nuclei launch failed: {e}")
            out.log_error("nuclei", cmd, str(e))
    else:
        vc.log("[vulnscan] nuclei not found or fast mode — skipping", "WARNING")

    # ── 2. Launch nikto (one per app-base parent path) ──────────────────────
    nikto = _find_tool("nikto")
    if skip_nikto:
        vc.log(
            "[vulnscan] nikto skipped — target has wildcard/catch-all or SPA "
            "behaviour (every path returns identical content)",
            "INFO",
        )
        nikto = None
    if nikto:
        for _nik_idx, _nik_base in enumerate(_vs_parents):
            _nik_label = urllib.parse.urlparse(_nik_base).path or "/"
            nik_out = out.output_path(
                phase,
                f"nikto_{target['hostname']}_{_nik_label.strip('/').replace('/', '_') or 'root'}",
            )
            cmd = [nikto, "-h", _nik_base, "-Format", "json",
                   "-output", str(nik_out), "-nointeractive"]
            if _vs_cookie_str:
                cmd += ["-Add-header", f"Cookie: {_vs_cookie_str}"]
            for _ah_name, _ah_val in _vs_auth_headers:
                cmd += ["-Add-header", f"{_ah_name}: {_ah_val}"]
            _nik_ua = _subprocess_ua(sess)
            if _nik_ua:
                cmd += ["-useragent", _nik_ua]
            _nik_authed = bool(_vs_cookie_str or _vs_auth_headers)
            vc.log(
                f"[vulnscan] Launching nikto ({_nik_idx + 1}/{len(_vs_parents)}) "
                f"in background against {_nik_base}"
                + (" (authenticated)" if _nik_authed else "") + " ...",
                "INFO",
            )
            try:
                _nik_started = datetime.now().astimezone()
                proc = _popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True)
                _register_proc(proc)
                handle["nikto_procs"].append({
                    "proc": proc, "cmd": cmd, "out": nik_out,
                    "base": _nik_base, "started": _nik_started,
                    "tool": nikto,
                })
            except Exception as e:
                vc.error(f"[vulnscan] nikto launch failed for {_nik_base}: {e}")
                out.log_error("nikto", cmd, str(e))
    else:
        vc.log("[vulnscan] nikto not found", "WARNING")

    _bg_count = (1 if handle["nuclei_proc"] else 0) + len(handle["nikto_procs"])
    vc.log(
        f"[vulnscan] {_bg_count} background tool(s) launched — "
        f"continuing with subsequent phases while they run",
        "INFO",
    )
    return handle


def _collect_vulnscan_bg(handle: dict) -> None:
    """Join background nuclei/nikto processes and parse their findings.

    Called after all other phases complete so findings are added to
    findings.json before the final summary.
    """
    if not handle:
        return
    target = handle["target"]
    cfg    = handle.get("cfg", {})
    out    = handle["out"]
    url    = handle["url"]
    phase  = handle["phase"]

    vc.status(phase, "Vuln Scan", "running", "collecting results", 0, 2)
    vc.log("[vulnscan] Collecting background tool results ...", "INFO")

    # ── 1. Collect nuclei ───────────────────────────────────────────────────
    _nuc_proc = handle.get("nuclei_proc")
    if _nuc_proc is not None:
        nuc_out     = handle["nuclei_out"]
        nuc_cmd     = handle["nuclei_cmd"]
        _nuc_started = handle["nuclei_started"]
        nuclei_tool = handle.get("nuclei_tool", "nuclei")
        timeout     = handle["timeout"]

        nuc_stderr      = ""
        _nuc_timed_out  = False
        # Check if nuclei already finished while other phases ran
        _already_done = _nuc_proc.poll() is not None
        if _already_done:
            vc.log("[vulnscan] nuclei already finished — collecting output", "INFO")
        else:
            vc.log("[vulnscan] Waiting for nuclei to finish ...", "INFO")

        try:
            _, nuc_stderr = _nuc_proc.communicate(timeout=timeout + 120)
            nuc_stderr = nuc_stderr or ""
        except subprocess.TimeoutExpired:
            _nuc_timed_out = True
            vc.log(
                f"[vulnscan] nuclei exceeded Python timeout ({timeout + 120}s) "
                f"— killing process (streamed output already on disk)",
                "WARNING",
            )
            _kill_proc_tree(_nuc_proc)
            try:
                _, nuc_stderr = _nuc_proc.communicate(timeout=10)
                nuc_stderr = nuc_stderr or ""
            except Exception:
                pass
            _timeout_action_item(out, "nuclei", target, timeout + 120)
        _deregister_proc(_nuc_proc)
        _nuc_ended = datetime.now().astimezone()

        if nuc_stderr:
            _nuc_clean = re.sub(r'\x1b\[[0-9;]*[a-zA-Z]', '', nuc_stderr).strip()
            _NUC_NONFATAL = re.compile(
                r'failed to load provider keys'
                r'|update check'
                r'|nuclei cloud'
                r'|cannot unmarshal.*sources\.Provider',
                re.I,
            )
            _nuc_warn = "\n".join(
                ln for ln in _nuc_clean.splitlines()
                if ln.strip() and not _NUC_NONFATAL.search(ln)
            )
            if _nuc_warn:
                vc.log(f"[vulnscan] nuclei stderr: {_nuc_warn[:500]}", "WARNING")

        try:
            nuc_stdout = nuc_out.read_text(encoding="utf-8")
        except FileNotFoundError:
            nuc_stdout = ""

        _nuc_lines = nuc_stdout.strip().splitlines()
        _nuc_dur = int((_nuc_ended - _nuc_started).total_seconds())
        vc.log(
            f"[vulnscan] nuclei completed: {len(_nuc_lines)} finding(s), "
            f"{_nuc_dur}s elapsed, exit code {_nuc_proc.returncode}"
            + (" (TIMED OUT)" if _nuc_timed_out else ""),
            "INFO" if _nuc_lines else "WARNING",
        )
        out.log_command(
            "nuclei", nuc_cmd, nuc_out,
            tool_path=nuclei_tool,
            stdout=nuc_stdout, stderr=nuc_stderr,
            started=_nuc_started, ended=_nuc_ended,
            exit_code=_nuc_proc.returncode,
        )
        if _nuc_timed_out:
            vc.log(
                f"[vulnscan] nuclei timed out — "
                f"partial output ({len(_nuc_lines)} lines) "
                f"already on disk at {nuc_out}",
                "WARNING",
            )
            out.log_error("nuclei", nuc_cmd,
                          f"timed out after {timeout + 120}s "
                          f"(partial: {len(_nuc_lines)} lines)")
        elif _nuc_proc.returncode != 0 and not _nuc_lines:
            out.log_error("nuclei", nuc_cmd,
                          f"exit code {_nuc_proc.returncode}, "
                          f"0 findings produced")
        # CMS-mismatch filter: suppress CMS-specific nuclei templates when the
        # target's detected tech stack does not include that CMS.
        _NUC_CMS_DIR = {
            "drupal": {"drupal"},
            "wordpress": {"wordpress", "wp-"},
            "joomla": {"joomla"},
            "magento": {"magento"},
            "moodle": {"moodle"},
            "shopify": {"shopify"},
        }
        _nuc_detected_techs = set()
        try:
            _tp_path = out.root / "target_profile.json"
            if _tp_path.exists():
                _tp_data = json.loads(_tp_path.read_text())
                _tp_cms = (_tp_data.get("cms") or "").lower()
                if _tp_cms:
                    _nuc_detected_techs.add(_tp_cms)
                for _tp_t in _tp_data.get("technologies", []):
                    _nuc_detected_techs.add((_tp_t.get("name") or "").lower())
        except Exception:
            pass
        _nuc_cms_suppressed = 0

        # Load soft-404 info for nuclei finding filtering
        _nuc_soft_404 = None
        try:
            _tp_path_s4 = out.root / "target_profile.json"
            if _tp_path_s4.exists():
                _tp_data_s4 = json.loads(_tp_path_s4.read_text())
                _nuc_soft_404 = _tp_data_s4.get("soft_404")
        except Exception:
            pass
        _nuc_soft404_suppressed = 0

        _nuc_count = 0
        for line in (nuc_stdout or "").splitlines():
            try:
                item    = json.loads(line)
                # CMS-mismatch suppression
                _nuc_tpath = (item.get("template-path", "")
                              + "/" + item.get("template-id", "")).lower()
                _nuc_cms_hit = False
                for _cms_key, _cms_names in _NUC_CMS_DIR.items():
                    if _cms_key in _nuc_tpath:
                        if not any(cn in _nuc_detected_techs for cn in _cms_names):
                            _nuc_cms_hit = True
                            break
                if _nuc_cms_hit:
                    _nuc_cms_suppressed += 1
                    continue
                # Soft-404 suppression
                if _nuc_soft_404 and _nuc_soft_404.get("detected"):
                    _nuc_resp = item.get("response", "")
                    if _nuc_resp and _is_soft_404(_nuc_resp, _nuc_soft_404):
                        _nuc_soft404_suppressed += 1
                        continue
                # Error-page fingerprint suppression (catches catch-all
                # error pages that vary too much for the hash-based check)
                _nuc_resp_body = item.get("response", "")
                if _nuc_resp_body and _matches_error_fingerprint(_nuc_resp_body):
                    _nuc_soft404_suppressed += 1
                    continue
                matched = item.get("matched-at", url)
                # Strip query params for dedup — session-specific tokens
                # (sessionDataKey, wct, etc.) create false duplicates.
                try:
                    _mp = urllib.parse.urlparse(matched)
                    matched = urllib.parse.urlunparse((_mp.scheme, _mp.netloc, _mp.path, "", "", ""))
                except Exception:
                    pass
                # Scope filter: discard findings on out-of-scope hosts
                # (nuclei follows redirects to SSO / IdP domains etc.)
                try:
                    _nuc_match_host = urllib.parse.urlparse(matched).hostname or ""
                    _nuc_tgt_host = target["hostname"]
                    if (_nuc_match_host and _nuc_tgt_host
                            and _nuc_match_host.lower() != _nuc_tgt_host.lower()):
                        continue
                except Exception:
                    pass
                _norm   = _normalize_nuclei(item)
                # Downgrade hostname-mismatch findings when target is IP
                if (_norm.get("title") == "SSL/TLS Certificate: Hostname Mismatch"
                        and _norm.get("risk") in ("HIGH", "MEDIUM", "CRITICAL")):
                    try:
                        ipaddress.ip_address(target["hostname"])
                        _norm["risk"] = "INFO"
                        _norm["description"] = (
                            _norm.get("description", "") +
                            " Note: target was accessed by IP address; certificate hostname "
                            "mismatch is expected. Verify with the actual FQDN."
                        )
                    except ValueError:
                        pass
                # Redirect gate — suppress content-rendering header findings
                # on pure redirect targets.
                _nuc_title = _norm["title"]
                if (target.get("_is_redirect")
                        and _nuc_title.startswith("Missing Security Header: ")):
                    _nuc_hdr = _nuc_title.split(": ", 1)[1]
                    if _nuc_hdr in _REDIRECT_EXEMPT_HEADERS:
                        continue
                # Unsafe methods gate — nuclei reports OPTIONS Allow
                # header contents without verifying; recon sends actual
                # requests (GAP-50).  Suppress here to avoid FPs.
                if _nuc_title == "HTTP Methods: Unsafe Methods Enabled":
                    continue
                # Extract v1.1 enrichment fields from normalizer output
                _nuc_v11 = {k: _norm[k] for k in ("cvss_score", "cvss_vector", "cwe")
                            if k in _norm and _norm[k]}
                out.add_finding(
                    title=_norm["title"],
                    url=matched, port=target["port"],
                    risk=_norm["risk"],
                    description=_norm["description"],
                    output=_norm["output"],
                    sources="nuclei", service=target["scheme"],
                    output_file=str(nuc_out),
                    cves=_norm.get("cves", ""),
                    affected=matched,
                    owasp=_norm["owasp"],
                    nist=_norm["nist"],
                    remediation=_norm["remediation"],
                    command=" ".join(handle["nuclei_cmd"]),
                    **_nuc_v11,
                )
                _nuc_count += 1
                # ── Action item: CVE exploit verification ─────────────
                _ai_cves = _norm.get("cves", "")
                _ai_risk = _norm["risk"]
                if _ai_cves and _ai_risk in ("CRITICAL", "HIGH"):
                    _ai_cve_list = [c.strip() for c in _ai_cves.split(",") if c.strip()]
                    out.log_action_item(
                        type="vulnerability",
                        recommended_tool="Manual Verification",
                        target=matched,
                        ip=target.get("ip", ""),
                        port=target["port"],
                        hostname=target.get("hostname", ""),
                        title=f"CVE Verification Required — {_norm['title'][:80]}",
                        description=(
                            f"{_ai_risk} nuclei finding with {len(_ai_cve_list)} "
                            f"CVE(s): {', '.join(_ai_cve_list[:5])}. "
                            "Manual exploitation verification recommended."
                        ),
                        source_finding=_norm["title"],
                        priority=_ai_risk,
                        scope="webapp",
                        metadata={"cves": _ai_cve_list[:5],
                                  "nuclei_template": item.get("template-id", ""),
                                  "cvss_score": _nuc_v11.get("cvss_score")},
                    )
            except (ValueError, KeyError):
                pass
            except Exception as _nuc_line_err:
                vc.error(f"[vulnscan] nuclei line parse error: {_nuc_line_err}")
        if _nuc_cms_suppressed:
            vc.log(
                f"[vulnscan] nuclei: suppressed {_nuc_cms_suppressed} "
                f"CMS-specific finding(s) (CMS not detected on target)", "INFO")
        if _nuc_soft404_suppressed:
            vc.log(
                f"[vulnscan] nuclei: suppressed {_nuc_soft404_suppressed} "
                f"finding(s) matching soft-404 error page pattern", "INFO")
        if _nuc_count:
            vc.log(f"[vulnscan] nuclei: {_nuc_count} finding(s) parsed", "SUCCESS")

        # ── Telerik validation ──
        try:
            _has_telerik = any(
                "telerik" in (f.get("title", "") + f.get("sources", "")).lower()
                for f in json.loads(out.findings_json.read_text())
            ) if out.findings_json.exists() else False
            if _has_telerik:
                try:
                    _validate_telerik(target, handle.get("cfg", {}), out,
                                      handle.get("sess") or requests.Session())
                except Exception as _tv_err:
                    vc.error(f"[telerik] Validation failed: {_tv_err}")
        except Exception:
            pass

        # ── IIS tilde shortname enumeration ──
        try:
            _has_iis_shortname = any(
                "iis tilde shortname" in f.get("title", "").lower()
                for f in json.loads(out.findings_json.read_text())
            ) if out.findings_json.exists() else False
            if _has_iis_shortname:
                try:
                    _enumerate_iis_shortname(
                        target, handle.get("cfg", {}), out,
                        handle.get("sess") or requests.Session())
                except Exception as _ise_err:
                    vc.error(f"[iis-shortname] Enumeration failed: {_ise_err}")
        except Exception:
            pass

    vc.status(phase, "Vuln Scan", "running", "nikto", 1, 2)

    # ── Cloud catch-all detection ───────────────────────────────────────────
    # Azure AD / Entra ID / Microsoft cloud apps return non-404 error pages
    # for any arbitrary path (treating the first segment as a tenant lookup).
    # Nikto flags these as findings based on the path pattern match alone.
    # Probe a random non-existent path; if the response contains known cloud
    # error signatures, suppress all Nikto path-based findings for this host.
    _CLOUD_CATCHALL_SIGS = (
        "AADSTS",
        "Tenant '",
        "login.microsoftonline.com",
        "login.live.com",
        "logincdn.msauth.net",
        "The resource you are looking for has been removed",
    )
    _nik_cloud_catchall: dict = {}  # base_url -> bool

    def _is_cloud_catchall(base_url: str, sess_obj) -> bool:
        if base_url in _nik_cloud_catchall:
            return _nik_cloud_catchall[base_url]
        try:
            _probe_url = base_url.rstrip("/") + "/fr4ctur3_catchall_probe_" + str(int(time.time()))
            _pr = sess_obj.get(_probe_url, timeout=10, allow_redirects=True)
            _pr_body = (_pr.text or "")[:8000]
            _pr_loc = (_pr.headers.get("Location") or "")
            _is_ca = any(sig in _pr_body or sig in _pr_loc for sig in _CLOUD_CATCHALL_SIGS)
            if _is_ca:
                vc.log(f"[vulnscan] nikto: cloud catch-all detected on {base_url} — "
                       f"path-based findings will be suppressed", "INFO")
        except Exception:
            _is_ca = False
        _nik_cloud_catchall[base_url] = _is_ca
        return _is_ca

    # ── 2. Collect nikto ────────────────────────────────────────────────────
    _nik_total = 0
    for _nik_h in handle.get("nikto_procs", []):
        _nik_proc  = _nik_h["proc"]
        _nik_cmd   = _nik_h["cmd"]
        _nik_out   = _nik_h["out"]
        _nik_base  = _nik_h["base"]
        _nik_start = _nik_h["started"]
        _nik_tool  = _nik_h.get("tool", "nikto")
        _nik_label = urllib.parse.urlparse(_nik_base).path or "/"

        _nik_stdout = ""
        _nik_stderr = ""
        try:
            _nik_stdout, _nik_stderr = _nik_proc.communicate(timeout=600)
        except subprocess.TimeoutExpired:
            vc.log(f"[vulnscan] nikto ({_nik_label}): timeout — killing", "WARNING")
            _kill_proc_tree(_nik_proc)
            try:
                _nik_stdout, _nik_stderr = _nik_proc.communicate(timeout=10)
            except Exception:
                pass
            _timeout_action_item(out, "nikto", target, 600)
        _deregister_proc(_nik_proc)
        _nik_ended = datetime.now().astimezone()
        out.log_command(
            "nikto", _nik_cmd, _nik_out,
            tool_path=_nik_tool,
            stdout=_nik_stdout, stderr=_nik_stderr,
            started=_nik_start, ended=_nik_ended,
            exit_code=_nik_proc.returncode,
        )
        if _nik_proc.returncode != 0:
            _nik_rc_msg = (
                f"[vulnscan] nikto ({_nik_label}): exit code "
                f"{_nik_proc.returncode}")
            if _nik_stderr:
                _nik_rc_msg += f" — {_nik_stderr.strip()[:200]}"
            vc.log(_nik_rc_msg, "WARNING")
            out.log_error("nikto", _nik_cmd,
                          f"exit code {_nik_proc.returncode}: "
                          f"{(_nik_stderr or '').strip()[:500]}")
        # Resolve actual output path — nikto sometimes appends its own
        # extension (.json, .txt.json) rather than writing to the exact path.
        _nik_json_path = _nik_out
        if not _nik_json_path.exists():
            for _nik_ext in (".json", ".txt.json"):
                _nik_alt = Path(str(_nik_out) + _nik_ext)
                if _nik_alt.exists():
                    _nik_json_path = _nik_alt
                    break
        if _nik_json_path.exists():
            try:
                _nik_raw = _nik_json_path.read_text(encoding="utf-8").strip()
                if not _nik_raw:
                    raise ValueError("nikto produced empty output file")
                ndata = json.loads(_nik_raw)
                _nik_hosts = ndata if isinstance(ndata, list) else [ndata]
                _nik_count = 0
                for _nik_host in _nik_hosts:
                    if not isinstance(_nik_host, dict):
                        continue
                    for vuln in _nik_host.get("vulnerabilities", []):
                        _nik_msg = vuln.get("msg", "").strip()
                        _nik_method = vuln.get("method", "GET")
                        _nik_url_path = vuln.get("url", "")
                        _nik_id = vuln.get("id", "")
                        _nik_osvdb = vuln.get("OSVDB", vuln.get("osvdb", ""))
                        _nik_full_url = _nik_base.rstrip("/") + _nik_url_path if _nik_url_path else _nik_base
                        _nik_output = f"{_nik_method} {_nik_url_path}" if _nik_url_path else ""
                        if _nik_osvdb:
                            _nik_output += f"\nOSVDB-{_nik_osvdb}"
                        _norm = _normalize_nikto(vuln)
                        if _norm is None:
                            continue
                        # STS on HTTP gate — RFC 6797 §7.2: ignore over plain HTTP
                        if (_norm["title"] == "Missing Security Header: Strict-Transport-Security"
                                and not target["is_https"]):
                            continue
                        # Redirect gate — content-rendering headers are
                        # meaningless on pure 3xx redirect responses.
                        _nik_norm_title = _norm["title"]
                        if (target.get("_is_redirect")
                                and _nik_norm_title.startswith("Missing Security Header: ")):
                            _nik_hdr_name = _nik_norm_title.split(": ", 1)[1]
                            if _nik_hdr_name in _REDIRECT_EXEMPT_HEADERS:
                                continue
                        # Unsafe methods gate — nikto reports OPTIONS Allow
                        # header contents without verifying; recon already
                        # sends actual requests (GAP-50).  Suppress here to
                        # avoid re-introducing FPs that recon filtered out.
                        if _nik_norm_title == "HTTP Methods: Unsafe Methods Enabled":
                            continue
                        # Cloud catch-all guard: suppress path-based findings
                        # when the server returns a branded error page for any
                        # arbitrary path (Azure AD/Entra ID, Microsoft cloud).
                        if (_nik_url_path and _nik_url_path != "/"
                                and _is_cloud_catchall(
                                    _nik_base,
                                    handle.get("sess") or requests.Session())):
                            continue
                        _nik_of = str(_nik_json_path)
                        _nik_title = _norm["title"]
                        if ("Verbose Server Error" in _nik_title
                                or "Stack Trace" in _nik_title
                                or "Exception" in _nik_title
                                or "Debug" in _nik_title):
                            _nik_safe = re.sub(r'[^\w]', '_', _nik_url_path or "root")[:40]
                            _nik_ss = _capture_error_screenshot(
                                _nik_full_url, out, phase,
                                f"nikto_error_{_nik_safe}",
                                target, cfg)
                            if _nik_ss:
                                _nik_of = f"{_nik_of},{_nik_ss}"
                        out.add_finding(
                            title=_nik_title,
                            url=_nik_full_url, port=target["port"],
                            risk=_norm["risk"],
                            description=_nik_msg or f"Nikto finding {_nik_id}",
                            output=_nik_output,
                            sources="nikto", service=target["scheme"],
                            output_file=_nik_of,
                            affected=_norm.get("affected", _nik_full_url),
                            owasp=_norm["owasp"],
                            nist=_norm["nist"],
                            remediation=_norm["remediation"],
                            command=" ".join(_nik_cmd),
                        )
                        _nik_count += 1
                if _nik_count:
                    vc.log(
                        f"[vulnscan] nikto ({_nik_label}): "
                        f"{_nik_count} finding(s) parsed",
                        "SUCCESS",
                    )
                _nik_total += _nik_count
            except Exception as _nik_parse_err:
                vc.error(f"[vulnscan] nikto JSON parse error: {_nik_parse_err}")
                out.log_error("nikto", _nik_cmd, f"JSON parse error: {_nik_parse_err}")
        else:
            _nik_dur = int((_nik_ended - _nik_start).total_seconds())
            _nik_diag = ""
            if _nik_stdout and _nik_stdout.strip():
                _nik_diag += f"\n  stdout: {_nik_stdout.strip()[:500]}"
            if _nik_stderr and _nik_stderr.strip():
                _nik_diag += f"\n  stderr: {_nik_stderr.strip()[:500]}"
            _nik_err_detail = (
                f"no output file produced ({_nik_dur}s elapsed, "
                f"exit code {_nik_proc.returncode})"
            )
            if _nik_stderr and _nik_stderr.strip():
                _nik_err_detail += f" stderr: {_nik_stderr.strip()[:500]}"
            vc.log(
                f"[vulnscan] nikto ({_nik_label}): {_nik_err_detail}"
                + (_nik_diag if _nik_diag else ""),
                "WARNING",
            )
            out.log_error("nikto", _nik_cmd, _nik_err_detail)
    if _nik_total:
        vc.log(f"[vulnscan] nikto total: {_nik_total} finding(s) across {len(handle.get('nikto_procs', []))} base(s)", "SUCCESS")

    vc.status(phase, "Vuln Scan", "complete", "Done", 2, 2)
    vc.log("[vulnscan] Phase complete", "SUCCESS")


# ─────────────────────────────────────────────
# Phase 9b: OWASP ZAP (background)
# ─────────────────────────────────────────────

def _launch_zap_bg(target: dict, cfg: dict, pm: ProgressManager,
                   out: OutputManager, sess: requests.Session) -> dict:
    phase = "zap"
    url   = target["url"]
    zap_bin = _find_tool("zap")
    if not zap_bin:
        vc.log("[zap] ZAP not found — skipping", "WARNING")
        return None

    # ZAP requires Java 17+. Pre-check to avoid a 120s timeout waiting
    # for a daemon that exits immediately.
    _java = shutil.which("java")
    if not _java:
        vc.log("[zap] Java not installed — skipping ZAP", "WARNING")
        return None
    try:
        _jv = subprocess.run(
            [_java, "-version"], capture_output=True, text=True, timeout=10)
        _jv_out = (_jv.stderr + _jv.stdout).strip()
        import re as _jre
        _jv_m = _jre.search(r'"(\d+)[\._]', _jv_out)
        _jv_major = int(_jv_m.group(1)) if _jv_m else 0
        if _jv_major < 17:
            vc.log(
                f"[zap] Java {_jv_major} found but ZAP requires Java 17+ — skipping",
                "WARNING")
            return None
    except Exception:
        vc.log("[zap] Could not determine Java version — skipping ZAP", "WARNING")
        return None

    import random as _zap_rnd
    api_port = 8090 + _zap_rnd.randint(0, 900)

    cmd = [
        zap_bin, "-daemon",
        "-port", str(api_port),
        "-config", "api.disablekey=true",
        "-config", "api.addrs.addr.name=127.0.0.1",
        "-config", "api.addrs.addr.regex=true",
        "-config", "connection.timeoutInSecs=120",
    ]
    _zap_env = os.environ.copy()
    _zap_env["JAVA_TOOL_OPTIONS"] = "-Xmx1024m"
    vc.log(f"[zap] Launching ZAP daemon on port {api_port} (heap capped at 1024 MB)", "INFO")
    vc.status(phase, "ZAP Scan", "running", "starting daemon", 0, 4)

    _zap_log = Path(out.root) / "zap_daemon.log"
    _zap_log_fh = open(_zap_log, "w")
    started = datetime.now().astimezone()
    try:
        proc = _popen(cmd, stdout=_zap_log_fh, stderr=subprocess.STDOUT,
                       env=_zap_env)
        _register_proc(proc)
    except Exception as e:
        _zap_log_fh.close()
        vc.error(f"[zap] Failed to launch ZAP daemon: {e}")
        out.log_error("zap", " ".join(cmd), str(e))
        return None

    # Wait for ZAP API to become ready
    import requests as _zap_req
    _zap_base = f"http://127.0.0.1:{api_port}"
    _zap_ready = False
    for _attempt in range(40):
        try:
            _r = _zap_req.get(f"{_zap_base}/JSON/core/view/version/", timeout=5)
            if _r.status_code == 200:
                _zap_ready = True
                _ver = _r.json().get("version", "unknown")
                vc.log(f"[zap] ZAP daemon ready (v{_ver})", "INFO")
                break
        except Exception:
            pass
        import time as _zap_time
        _zap_time.sleep(3)

    if not _zap_ready:
        vc.log("[zap] ZAP daemon did not become ready within 120s — aborting", "WARNING")
        out.log_error("zap", " ".join(cmd), "daemon startup timeout (120s)")
        try:
            _kill_proc_tree(proc)
            proc.wait(timeout=10)
        except Exception:
            pass
        _zap_log_fh.close()
        _deregister_proc(proc)
        return None

    # Pass auth cookies to ZAP
    cookie_str, auth_headers = _extract_subprocess_auth(sess)
    if cookie_str:
        for _ck_pair in cookie_str.split("; "):
            if "=" in _ck_pair:
                _ck_name, _ck_val = _ck_pair.split("=", 1)
                try:
                    _zap_req.get(
                        f"{_zap_base}/JSON/httpsession/action/setSessionTokenValue/",
                        params={"site": urllib.parse.urlparse(url).netloc,
                                "sessionToken": _ck_name, "tokenValue": _ck_val},
                        timeout=10,
                    )
                except Exception:
                    pass

    # Pass auth headers (e.g. Authorization: Bearer) to ZAP via replacer rules
    for _zah_idx, (_zah_name, _zah_val) in enumerate(auth_headers):
        try:
            _zap_req.get(
                f"{_zap_base}/JSON/replacer/action/addRule/",
                params={
                    "description": f"FractureAuth_{_zah_name}",
                    "enabled": "true",
                    "matchType": "REQ_HEADER",
                    "matchRegex": "false",
                    "matchString": _zah_name,
                    "replacement": _zah_val,
                },
                timeout=10,
            )
        except Exception:
            pass
    # Forward session UA via replacer rule
    _zap_ua = _subprocess_ua(sess)
    if _zap_ua:
        try:
            _zap_req.get(
                f"{_zap_base}/JSON/replacer/action/addRule/",
                params={
                    "description": "FractureUA",
                    "enabled": "true",
                    "matchType": "REQ_HEADER",
                    "matchRegex": "false",
                    "matchString": "User-Agent",
                    "replacement": _zap_ua,
                },
                timeout=10,
            )
        except Exception:
            pass
    if auth_headers or _zap_ua:
        vc.log(f"[zap] Forwarded {len(auth_headers)} auth header(s)"
               + (" + session UA" if _zap_ua else "") + " via replacer rules", "INFO")

    # Start ZAP spider
    spider_id = None
    try:
        _sr = _zap_req.get(
            f"{_zap_base}/JSON/spider/action/scan/",
            params={"url": url, "maxChildren": "10", "recurse": "true",
                    "subtreeOnly": "true"},
            timeout=30,
        )
        spider_id = _sr.json().get("scan")
        vc.log(f"[zap] Spider started (id={spider_id})", "INFO")
    except Exception as e:
        vc.log(f"[zap] Spider start failed: {e}", "WARNING")

    # Start AJAX spider (best-effort)
    try:
        _zap_req.get(
            f"{_zap_base}/JSON/ajaxSpider/action/scan/",
            params={"url": url, "subtreeOnly": "true"},
            timeout=30,
        )
        vc.log("[zap] AJAX spider started", "INFO")
    except Exception:
        pass

    handle = {
        "zap_proc": proc, "zap_port": api_port, "zap_cmd": cmd,
        "spider_id": spider_id, "target": target, "out": out,
        "started": started, "phase": phase, "log_fh": _zap_log_fh,
    }
    return handle


def _collect_zap_bg(handle: dict) -> None:
    if not handle:
        return
    target   = handle["target"]
    out      = handle["out"]
    phase    = handle["phase"]
    proc     = handle["zap_proc"]
    api_port = handle["zap_port"]
    url      = target["url"]
    hostname = target.get("hostname", "target")
    started  = handle["started"]

    import requests as _zap_req
    import time as _zap_time
    _zap_base = f"http://127.0.0.1:{api_port}"

    _ZAP_RISK_MAP = {
        "High": "HIGH", "Medium": "MEDIUM", "Low": "LOW",
        "Informational": "INFO", "False Positive": None,
    }

    # ── Wait for spider ──────────────────────────────────────────────────────
    spider_id = handle.get("spider_id")
    if spider_id is not None:
        vc.status(phase, "ZAP Scan", "running", "spidering", 1, 4)
        _spider_deadline = _zap_time.time() + 600
        while _zap_time.time() < _spider_deadline:
            try:
                _ss = _zap_req.get(
                    f"{_zap_base}/JSON/spider/view/status/",
                    params={"scanId": str(spider_id)}, timeout=30,
                )
                if _ss.json().get("status") == "100":
                    vc.log("[zap] Spider complete", "INFO")
                    break
            except Exception:
                pass
            _zap_time.sleep(5)
        else:
            vc.log("[zap] Spider timed out after 600s — continuing", "WARNING")

    # ── Start active scan ────────────────────────────────────────────────────
    ascan_id = None
    try:
        vc.status(phase, "ZAP Scan", "running", "active scan", 2, 4)
        _ar = _zap_req.get(
            f"{_zap_base}/JSON/ascan/action/scan/",
            params={"url": url, "recurse": "true"},
            timeout=30,
        )
        ascan_id = _ar.json().get("scan")
        vc.log(f"[zap] Active scan started (id={ascan_id})", "INFO")
    except Exception as e:
        vc.log(f"[zap] Active scan start failed: {e}", "WARNING")

    # ── Wait for active scan ─────────────────────────────────────────────────
    if ascan_id is not None:
        _ascan_deadline = _zap_time.time() + 1800
        while _zap_time.time() < _ascan_deadline:
            try:
                _as = _zap_req.get(
                    f"{_zap_base}/JSON/ascan/view/status/",
                    params={"scanId": str(ascan_id)}, timeout=30,
                )
                _pct = _as.json().get("status", "0")
                if _pct == "100":
                    vc.log("[zap] Active scan complete", "INFO")
                    break
                if int(_pct) % 20 == 0 and int(_pct) > 0:
                    vc.log(f"[zap] Active scan {_pct}% complete", "INFO")
            except Exception:
                pass
            _zap_time.sleep(10)
        else:
            vc.log("[zap] Active scan timed out after 1800s — collecting partial results", "WARNING")

    # ── Retrieve alerts ──────────────────────────────────────────────────────
    vc.status(phase, "ZAP Scan", "running", "collecting alerts", 3, 4)
    alerts = []
    try:
        _al = _zap_req.get(
            f"{_zap_base}/JSON/core/view/alerts/",
            params={"baseurl": url, "start": "0", "count": "500"},
            timeout=30,
        )
        alerts = _al.json().get("alerts", [])
        vc.log(f"[zap] Retrieved {len(alerts)} alert(s)", "INFO")
    except Exception as e:
        vc.log(f"[zap] Failed to retrieve alerts: {e}", "WARNING")

    # Save raw alerts JSON
    _alerts_out = out.output_path("zap", f"zap_alerts_{hostname}.json")
    try:
        _alerts_out.parent.mkdir(parents=True, exist_ok=True)
        _alerts_out.write_text(json.dumps(alerts, indent=2, default=str),
                               encoding="utf-8")
    except Exception as e:
        vc.log(f"[zap] Failed to write alerts JSON: {e}", "WARNING")

    # ── Parse alerts into findings ───────────────────────────────────────────
    _cve_re = re.compile(r"CVE-\d{4}-\d{4,}")
    _finding_count = 0
    for _alert in alerts:
        _risk_raw = _alert.get("risk", "Informational")
        _risk = _ZAP_RISK_MAP.get(_risk_raw)
        if _risk is None:
            continue

        _ref = _alert.get("reference", "")
        _cves_found = ", ".join(sorted(set(_cve_re.findall(_ref))))
        _owasp = ""
        if "owasp.org" in _ref.lower():
            for _line in _ref.splitlines():
                if "owasp.org" in _line.lower():
                    _owasp = _line.strip()
                    break

        _output = _alert.get("evidence", "") or _alert.get("other", "")

        out.add_finding(
            title=_alert.get("alert", "ZAP Alert"),
            url=_alert.get("url", url),
            port=target.get("port", 443),
            risk=_risk,
            description=_alert.get("description", ""),
            sources="zap",
            output=_output[:4096] if _output else "",
            affected=_alert.get("url", ""),
            owasp=_owasp,
            remediation=_alert.get("solution", ""),
            output_file=str(_alerts_out.relative_to(out.root))
                        if _alerts_out.exists() else "",
            cves=_cves_found,
            command="ZAP automated scan (spider + active scan)",
        )
        _finding_count += 1

    # ── Save HTML report ─────────────────────────────────────────────────────
    _html_out = out.output_path("zap", f"zap_report_{hostname}.html")
    try:
        _html_out.parent.mkdir(parents=True, exist_ok=True)
        _hr = _zap_req.get(f"{_zap_base}/OTHER/core/other/htmlreport/", timeout=30)
        _html_out.write_bytes(_hr.content)
        vc.log(f"[zap] HTML report saved: {_html_out.name}", "INFO")
    except Exception as e:
        vc.log(f"[zap] Failed to retrieve HTML report: {e}", "WARNING")

    # ── Log command ──────────────────────────────────────────────────────────
    ended = datetime.now().astimezone()
    out.log_command(
        "zap", handle["zap_cmd"], _alerts_out,
        tool_path=handle["zap_cmd"][0] if handle["zap_cmd"] else "",
        stdout="", stderr="",
        started=started, ended=ended,
        exit_code=0,
    )

    # ── Shut down ZAP ────────────────────────────────────────────────────────
    try:
        _zap_req.get(f"{_zap_base}/JSON/core/action/shutdown/", timeout=10)
    except Exception:
        pass
    try:
        proc.wait(timeout=15)
    except subprocess.TimeoutExpired:
        _kill_proc_tree(proc)
        proc.wait(timeout=5)
    except Exception:
        pass
    _deregister_proc(proc)
    _lfh = handle.get("log_fh")
    if _lfh and not _lfh.closed:
        _lfh.close()

    vc.status(phase, "ZAP Scan", "complete", "Done", 4, 4)
    vc.log(f"[zap] Phase complete — {_finding_count} finding(s)", "SUCCESS")


# ─────────────────────────────────────────────
# Phase 10: GraphQL
# ─────────────────────────────────────────────
_GRAPHQL_PATHS = ["/graphql", "/api/graphql", "/graphql/v1",
                  "/query", "/gql", "/v1/graphql"]
_INTROSPECTION_QUERY = '{"query":"{__schema{types{name}}}"}'


def _phase_graphql(target: dict, cfg: dict, pm: ProgressManager,
                   out: OutputManager, sess: requests.Session) -> None:
    phase   = "graphql"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    vc.status(phase, "GraphQL", "running", "Endpoint detection", 0, 3)

    found_gql = None
    for gpath in _GRAPHQL_PATHS:
        try:
            r = sess.post(url + gpath,
                          data=_INTROSPECTION_QUERY,
                          headers={"Content-Type": "application/json"},
                          timeout=timeout)
            if r.status_code == 200 and "__schema" in r.text:
                found_gql = url + gpath
                vc.log(f"[graphql] GraphQL endpoint: {found_gql}", "SUCCESS")
                _gql_intr_ev = ""
                try:
                    _gql_rq, _gql_rp = _save_http_evidence(
                        out, phase, "graphql_introspection", r)
                    _gql_intr_ev = json.dumps(
                        [{"url": found_gql, "req": str(_gql_rq), "resp": str(_gql_rp)}])
                except Exception:
                    pass
                out.add_finding(
                    title="Enumeration: GraphQL Introspection Enabled",
                    url=found_gql, port=target["port"], risk="MEDIUM",
                    description=f"GraphQL introspection is enabled at {found_gql}. This allows attackers to enumerate the full API schema.",
                    output=r.text[:500], sources="fracture-graphql",
                    output_file=_gql_intr_ev,
                    service=target["scheme"], affected=found_gql,
                    owasp="A05:2025 Security Misconfiguration", nist="CM-7",
                    remediation="Disable GraphQL introspection in production environments.",
                )
                break
            elif r.status_code == 200 and "data" in r.text:
                found_gql = url + gpath
                vc.log(f"[graphql] GraphQL endpoint (no introspection): {found_gql}", "INFO")
                break
        except Exception:
            pass

    if found_gql:
        # ── Action item: recommend Siphon for GraphQL testing ─────
        out.log_action_item(
            type="api",
            recommended_tool="Siphon",
            target=found_gql,
            ip=target.get("ip", ""),
            port=target["port"],
            hostname=target.get("hostname", ""),
            title="GraphQL Endpoint Detected — Siphon Scan Recommended",
            description=(
                f"GraphQL endpoint discovered at {found_gql}. Recommend Siphon "
                f"for comprehensive API security testing including introspection "
                f"analysis, query depth/complexity attacks, and batching abuse."
            ),
            source_finding="GraphQL Introspection Enabled",
            priority="high",
            scope=target.get("scope", ""),
            metadata={"source_phase": "graphql", "endpoint": found_gql},
        )

    if not found_gql:
        vc.log("[graphql] No GraphQL endpoint found", "INFO")
        vc.status(phase, "GraphQL", "complete", "No endpoint", 3, 3)
        return

    vc.status(phase, "GraphQL", "running", "Batch query test", 1, 3)
    # Test batch query attack
    batch_query = '[{"query":"{__typename}"},{"query":"{__typename}"},{"query":"{__typename}"}]'
    try:
        r = sess.post(found_gql, data=batch_query,
                      headers={"Content-Type": "application/json"}, timeout=timeout)
        if r.status_code == 200 and isinstance(json.loads(r.text), list):
            _gql_batch_ev = ""
            try:
                _gb_rq, _gb_rp = _save_http_evidence(
                    out, phase, "graphql_batch", r)
                _gql_batch_ev = json.dumps(
                    [{"url": found_gql, "req": str(_gb_rq), "resp": str(_gb_rp)}])
            except Exception:
                pass
            out.add_finding(
                title="GraphQL Batch Query Attack Possible",
                url=found_gql, port=target["port"], risk="MEDIUM",
                description="GraphQL accepts batched queries, which can be used to bypass rate limiting.",
                output=r.text[:300], sources="fracture-graphql",
                output_file=_gql_batch_ev,
                service=target["scheme"], affected=found_gql,
                owasp="A05:2025 Security Misconfiguration", nist="SC-5",
                remediation="Implement query complexity limits and disable batching if not required.",
            )
    except Exception:
        pass

    vc.status(phase, "GraphQL", "running", "Field suggestions", 2, 3)
    # Field suggestion detection
    try:
        r = sess.post(found_gql,
                      data='{"query":"{doesNotExist}"}',
                      headers={"Content-Type": "application/json"}, timeout=timeout)
        if "Did you mean" in r.text or "suggestion" in r.text.lower():
            _gql_sug_ev = ""
            try:
                _gs_rq, _gs_rp = _save_http_evidence(
                    out, phase, "graphql_suggestions", r)
                _gql_sug_ev = json.dumps(
                    [{"url": found_gql, "req": str(_gs_rq), "resp": str(_gs_rp)}])
            except Exception:
                pass
            out.add_finding(
                title="GraphQL Field Suggestions Enabled",
                url=found_gql, port=target["port"], risk="LOW",
                description="GraphQL returns field name suggestions on typos, which can aid schema enumeration.",
                output=r.text[:300], sources="fracture-graphql",
                output_file=_gql_sug_ev,
                service=target["scheme"], affected=found_gql,
                owasp="A05:2025 Security Misconfiguration", nist="CM-7",
                remediation="Disable field suggestions in production.",
            )
    except Exception:
        pass

    vc.status(phase, "GraphQL", "complete", "Done", 3, 3)
    vc.log("[graphql] Phase complete", "SUCCESS")


# ─────────────────────────────────────────────
# Phase 11: Auth Recon
# ─────────────────────────────────────────────
# ── ASP.NET ViewState Analyzer ─────────────────────────────────────────────────
_VS_FIELD_RE = re.compile(
    r'<input[^>]+name=["\'](__VIEWSTATE)["\'][^>]+value=["\']([^"\']*)["\']',
    re.I | re.S)
_VS_GENERATOR_RE = re.compile(
    r'<input[^>]+name=["\']__VIEWSTATEGENERATOR["\'][^>]+value=["\']([^"\']*)["\']',
    re.I | re.S)
_VS_EVENTVALIDATION_RE = re.compile(
    r'<input[^>]+name=["\']__EVENTVALIDATION["\'][^>]+value=["\']([^"\']*)["\']',
    re.I | re.S)
# Also match value-first attribute order: <input value="..." name="__VIEWSTATE">
_VS_FIELD_ALT_RE = re.compile(
    r'<input[^>]+value=["\']([^"\']*)["\'][^>]+name=["\'](__VIEWSTATE)["\']',
    re.I | re.S)
_VS_GENERATOR_ALT_RE = re.compile(
    r'<input[^>]+value=["\']([^"\']*)["\'][^>]+name=["\']__VIEWSTATEGENERATOR["\']',
    re.I | re.S)
_VS_EVENTVALIDATION_ALT_RE = re.compile(
    r'<input[^>]+value=["\']([^"\']*)["\'][^>]+name=["\']__EVENTVALIDATION["\']',
    re.I | re.S)

# Patterns indicating sensitive data in decoded ViewState
_VS_SENSITIVE_PATTERNS = [
    (re.compile(r'(?:Data\s*Source|Initial\s*Catalog|Server)\s*=', re.I),
     "Database connection string fragment"),
    (re.compile(r'(?:password|passwd|pwd)\s*=', re.I),
     "Credential fragment"),
    (re.compile(r'[A-Za-z]:\\(?:inetpub|Windows|Users|Program Files)', re.I),
     "Internal file path"),
    (re.compile(r'(?:SELECT|INSERT|UPDATE|DELETE)\s+(?:FROM|INTO|SET)\s', re.I),
     "SQL query fragment"),
    (re.compile(r'[a-zA-Z0-9_.+-]+@[a-zA-Z0-9-]+\.[a-zA-Z]{2,}'),
     "Email address"),
    (re.compile(r'(?:api[_-]?key|secret[_-]?key|access[_-]?token)\s*[:=]', re.I),
     "API key / secret reference"),
    (re.compile(r'machine[Kk]ey|validation[Kk]ey|decryption[Kk]ey', re.I),
     "ASP.NET MachineKey reference"),
]

# ASP.NET ViewState MAC signature marker
# The last 20 bytes of a MAC-protected ViewState (HMACSHA1) are the signature.
# For HMACSHA256 it's 32 bytes.  A ViewState with fewer than 24 bytes of raw
# decoded data almost certainly has no MAC.
_VS_MIN_MAC_LEN = 24


# ── Main function ───────────────────────────────────────────────────────────

def _check_viewstate(target: dict, cfg: dict, out: "OutputManager",
                     sess: "requests.Session", crawl_data: dict) -> None:
    """Analyze ASP.NET ViewState fields discovered during crawl.

    Checks for:
      1. Missing MAC protection (HIGH — parameter tampering / deserialization)
      2. Sensitive data embedded in decoded ViewState (MEDIUM — information disclosure)
      3. Generator fingerprinting (INFO — logged, not a finding)
    """
    phase   = "auth_recon"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    _pu     = urllib.parse.urlparse(url)
    origin  = f"{_pu.scheme}://{_pu.netloc}"
    port    = target["port"]
    scheme  = target["scheme"]

    # Collect unique .aspx / form-bearing pages from crawl
    _vs_pages: list = []
    _seen_pages: set = set()
    for link in crawl_data.get("links", []):
        _lp = urllib.parse.urlparse(link).path or ""
        _norm = link.rstrip("/").lower()
        if _norm in _seen_pages:
            continue
        # Check .aspx pages and root pages that might have ViewState
        if (_lp.lower().endswith(".aspx")
                or _lp.lower().endswith("/")
                or not "." in _lp.rsplit("/", 1)[-1]):
            _seen_pages.add(_norm)
            _vs_pages.append(link)
    # Also check forms pages
    for form in crawl_data.get("forms", []):
        _form_url = form.get("action") or form.get("url") or ""
        if _form_url and _form_url.rstrip("/").lower() not in _seen_pages:
            _seen_pages.add(_form_url.rstrip("/").lower())
            _vs_pages.append(_form_url)

    if not _vs_pages:
        vc.log("[viewstate] No .aspx or form pages to analyze", "INFO")
        return

    vc.log(f"[viewstate] Analyzing {len(_vs_pages)} page(s) for ViewState fields", "INFO")

    _vs_no_mac_pages:    list = []
    _vs_sensitive_pages: list = []
    _vs_generators:      dict = {}  # page → generator value
    _vs_evidence_lines:  list = []
    _vs_max_pages = min(len(_vs_pages), 50)

    for _idx, page_url in enumerate(_vs_pages[:_vs_max_pages]):
        try:
            r = sess.get(page_url, timeout=timeout, allow_redirects=True)
            if r.status_code != 200:
                continue
            body = r.text or ""
            if not body:
                continue

            # Extract __VIEWSTATE value
            _vs_match = _VS_FIELD_RE.search(body)
            if not _vs_match:
                _vs_match = _VS_FIELD_ALT_RE.search(body)
                if _vs_match:
                    _vs_val = _vs_match.group(1)  # value is group 1 in alt
                else:
                    continue
            else:
                _vs_val = _vs_match.group(2)  # value is group 2 in primary

            if not _vs_val or len(_vs_val) < 10:
                continue

            _page_path = urllib.parse.urlparse(page_url).path or page_url

            # Extract __VIEWSTATEGENERATOR
            _vsg_match = _VS_GENERATOR_RE.search(body)
            if not _vsg_match:
                _vsg_match = _VS_GENERATOR_ALT_RE.search(body)
            if _vsg_match:
                _vsg_val = _vsg_match.group(1) if _VS_GENERATOR_ALT_RE.search(body) else _vsg_match.group(1)
                _vs_generators[_page_path] = _vsg_val

            # Check for __EVENTVALIDATION (indicates MAC is likely configured)
            _has_ev = bool(_VS_EVENTVALIDATION_RE.search(body)
                          or _VS_EVENTVALIDATION_ALT_RE.search(body))

            # Decode ViewState
            try:
                # ViewState values may have URL encoding
                _vs_decoded_b = base64.b64decode(_vs_val)
            except Exception:
                try:
                    _vs_decoded_b = base64.b64decode(urllib.parse.unquote(_vs_val))
                except Exception:
                    _vs_evidence_lines.append(
                        f"Page: {_page_path}\n  ViewState: (decode failed, {len(_vs_val)} chars)\n")
                    continue

            _vs_len = len(_vs_decoded_b)
            _vs_evidence_lines.append(
                f"Page: {_page_path}\n"
                f"  ViewState length: {_vs_len} bytes (encoded: {len(_vs_val)} chars)\n"
                f"  EventValidation: {'present' if _has_ev else 'MISSING'}\n"
                f"  Generator: {_vs_generators.get(_page_path, 'not found')}\n"
            )

            # ── MAC check ──────────────────────────────────────────────────
            # Heuristic: ASP.NET appends a 20-byte (SHA1) or 32-byte (SHA256)
            # HMAC to the serialized ViewState.  A ViewState without MAC
            # protection will typically have its first bytes as the ASP.NET
            # serialization marker (0xFF 0x01) without trailing MAC bytes.
            #
            # Additional signals of missing MAC:
            #   - No __EVENTVALIDATION field (usually co-enabled with MAC)
            #   - ViewState shorter than typical MAC-protected payload
            #   - enableViewStateMac="false" in decoded content
            _mac_missing = False
            _mac_evidence = []

            if not _has_ev:
                _mac_evidence.append("__EVENTVALIDATION field absent")

            if _vs_len < _VS_MIN_MAC_LEN:
                _mac_evidence.append(f"ViewState too short ({_vs_len}B) for MAC")
                _mac_missing = True

            # Check for explicit MAC disable in the decoded bytes
            try:
                _vs_text = _vs_decoded_b.decode("utf-8", errors="replace")
                if "enableviewstatemac" in _vs_text.lower():
                    if re.search(r'enableViewStateMac\s*=\s*["\']?false', _vs_text, re.I):
                        _mac_evidence.append("enableViewStateMac=false found in ViewState")
                        _mac_missing = True
            except Exception:
                _vs_text = ""

            # If no EVENTVALIDATION AND short → likely no MAC
            if not _has_ev and _vs_len < 200:
                _mac_missing = True

            if _mac_missing or (len(_mac_evidence) >= 2):
                _vs_no_mac_pages.append({
                    "page": _page_path,
                    "evidence": _mac_evidence,
                    "vs_len": _vs_len,
                })

            # ── Sensitive data check ───────────────────────────────────────
            # Scan the decoded bytes (as lossy UTF-8) for sensitive patterns
            if not _vs_text:
                try:
                    _vs_text = _vs_decoded_b.decode("utf-8", errors="replace")
                except Exception:
                    _vs_text = repr(_vs_decoded_b[:2000])

            _found_sensitive: list = []
            for _pat, _label in _VS_SENSITIVE_PATTERNS:
                _matches = _pat.findall(_vs_text)
                if _matches:
                    _found_sensitive.append((_label, _matches[:3]))

            if _found_sensitive:
                _vs_sensitive_pages.append({
                    "page": _page_path,
                    "findings": _found_sensitive,
                    "preview": _vs_text[:500],
                })

        except requests.exceptions.Timeout:
            vc.log(f"[viewstate] Timeout fetching {page_url}", "WARNING")
            _timeout_action_item(out, "ViewState analysis", target, 0, priority="LOW")
        except Exception as _vs_err:
            vc.error(f"[viewstate] Error analyzing {page_url}: {_vs_err}")

    # ── Emit findings ──────────────────────────────────────────────────────

    # Save evidence file with all analysis details
    _ev_path = ""
    if _vs_evidence_lines or _vs_generators:
        try:
            _ev_file = out.output_path(phase, "viewstate_analysis")
            _ev_content = [
                "ASP.NET ViewState Analysis",
                "=" * 50,
                f"Target: {url}",
                f"Pages analyzed: {min(len(_vs_pages), _vs_max_pages)}",
                "",
            ]
            _ev_content.extend(_vs_evidence_lines)
            if _vs_generators:
                _ev_content.append("\nViewState Generators:")
                for _pg, _gen in _vs_generators.items():
                    _ev_content.append(f"  {_pg} → {_gen}")
            _ev_file.write_text("\n".join(_ev_content), encoding="utf-8")
            _ev_path = str(_ev_file)
        except Exception:
            pass

    # Finding 1: ViewState not MAC-protected
    if _vs_no_mac_pages:
        _affected = "\n".join(p["page"] for p in _vs_no_mac_pages)
        _out_lines = []
        for p in _vs_no_mac_pages:
            _out_lines.append(f"{p['page']}:")
            for e in p["evidence"]:
                _out_lines.append(f"  - {e}")
            _out_lines.append(f"  ViewState size: {p['vs_len']} bytes")
        out.add_finding(
            title="ASP.NET ViewState Not MAC-Protected",
            url=url, port=port, risk="HIGH",
            description=(
                "One or more ASP.NET pages serve ViewState without Message Authentication "
                "Code (MAC) protection. An attacker can tamper with serialized ViewState "
                "data to bypass security controls, manipulate server-side state, or — if "
                "the application deserializes ViewState objects — achieve remote code "
                "execution via .NET deserialization attacks (e.g. ysoserial.net payloads).\n\n"
                "ViewState MAC protection (enableViewStateMac) was made mandatory in "
                ".NET 4.5.2+ (MS14-059 / KB2990942). Applications that explicitly "
                "disable it are critically vulnerable."
            ),
            output="\n".join(_out_lines),
            sources="fracture-viewstate", service=scheme,
            output_file=_ev_path,
            affected=_affected,
            cves="CVE-2020-0688,CVE-2014-4075",
            cvss_score=8.8, cvss_vector="CVSS:3.1/AV:N/AC:L/PR:L/UI:N/S:U/C:H/I:H/A:H",
            cwe=["CWE-642", "CWE-502"],
            owasp="A08:2025 Software and Data Integrity Failures",
            nist="SI-10",
            remediation=(
                "1. Ensure enableViewStateMac is NOT set to 'false' in web.config or any page directive.\n"
                "2. Apply MS14-059 (KB2990942) — .NET 4.5.2+ enforces MAC regardless of config.\n"
                "3. Set a strong, unique MachineKey in web.config (do not use auto-generated keys "
                "in web farm scenarios).\n"
                "4. Consider migrating stateful pages to ASP.NET MVC or Razor Pages which do not "
                "use ViewState."
            ),
        )
        vc.log(
            f"[viewstate] ViewState MAC not detected on {len(_vs_no_mac_pages)} page(s)",
            "SUCCESS")

    # Finding 2: Sensitive data in ViewState
    if _vs_sensitive_pages:
        _affected = "\n".join(p["page"] for p in _vs_sensitive_pages)
        _out_lines = []
        for p in _vs_sensitive_pages:
            _out_lines.append(f"{p['page']}:")
            for _label, _matches in p["findings"]:
                _out_lines.append(f"  {_label}: {', '.join(str(m) for m in _matches[:2])}")
            if p["preview"]:
                _out_lines.append(f"  Preview: {p['preview'][:200]}...")
        out.add_finding(
            title="ViewState Contains Sensitive Data",
            url=url, port=port, risk="MEDIUM",
            description=(
                "The decoded ASP.NET ViewState contains data that may be sensitive: "
                "connection strings, file paths, email addresses, SQL fragments, or "
                "credential references. Even with MAC protection, ViewState is only "
                "signed (not encrypted by default) — the data is base64-encoded and "
                "readable by any client."
            ),
            output="\n".join(_out_lines),
            sources="fracture-viewstate", service=scheme,
            output_file=_ev_path,
            affected=_affected,
            owasp="A01:2025 Broken Access Control",
            nist="SC-28",
            remediation=(
                "1. Enable ViewState encryption: set viewStateEncryptionMode='Always' in web.config.\n"
                "2. Do not store sensitive data in ViewState — use server-side Session or cache.\n"
                "3. Review each flagged page and remove sensitive data from control properties."
            ),
        )
        vc.log(
            f"[viewstate] Sensitive data found in ViewState on {len(_vs_sensitive_pages)} page(s)",
            "SUCCESS")

    _total = len(_vs_no_mac_pages) + len(_vs_sensitive_pages)
    if _total:
        vc.log(f"[viewstate] Analysis complete: {_total} finding(s)", "SUCCESS")
    else:
        vc.log("[viewstate] ViewState analysis complete — no issues found", "INFO")


