    r'(?:Telerik\.Web\.UI[,\s]+Version=|'           # Assembly version
    r'telerik\.web\.ui[/\\]|'                        # JS path component
    r'Telerik_Web_UI_WebResource_|'                  # Resource URL
    r'["\']version["\']\s*:\s*["\']|'                # JSON metadata
    r'Version\s*=\s*)'
    r'(\d{4}\.\d+\.\d+(?:\.\d+)?)',                 # Capture: 2023.3.1010[.45]
